-- function: activate_purchase_xml_inventory_lots_v1(p_document_id uuid, p_user_id uuid)
CREATE OR REPLACE FUNCTION public.activate_purchase_xml_inventory_lots_v1(p_document_id uuid, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_items integer:=0;
  v_active integer:=0;
begin
  update public.purchase_xml_items
     set processing_status=processing_status,
         updated_at=now()
   where document_id=p_document_id
     and product_id is not null
     and coalesce(converted_quantity,0)>0
     and stock_update_requested is true;
  get diagnostics v_items=row_count;

  select count(*) into v_active
    from public.purchase_xml_items i
    join public.product_inventory_lots l on l.id=i.inventory_lot_id
   where i.document_id=p_document_id and i.stock_update_requested is true and l.status in ('active','depleted');

  return jsonb_build_object(
    'ok',true,'document_id',p_document_id,'items_touched',v_items,
    'active_lots',v_active,'verified_by',p_user_id,'local_product_stock_mutated',false
  );
end;
$function$
;

-- function: admin_basket_configuration_product_type_save_v1(p_product_type jsonb)
CREATE OR REPLACE FUNCTION public.admin_basket_configuration_product_type_save_v1(p_product_type jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid(); v_id uuid; v_name text; v_category text; v_order integer; v_active boolean;
  v_row jsonb; v_product uuid; v_seen uuid[]:='{}'::uuid[]; v_pos uuid; v_mold uuid;
  v_template uuid; v_qty numeric; v_labels text[];
begin
  if v_uid is null or not exists(select 1 from public.admin_users a where a.user_id=v_uid and a.is_active and a.role<>'viewer') then
    raise exception 'admin_not_authorized';
  end if;
  if p_product_type is null or jsonb_typeof(p_product_type)<>'object' then raise exception 'basket_admin_product_type_invalid'; end if;
  v_id:=nullif(p_product_type->>'id','')::uuid; v_name:=btrim(coalesce(p_product_type->>'name',''));
  v_category:=btrim(coalesce(p_product_type->>'category','')); v_order:=coalesce(nullif(p_product_type->>'sort_order','')::integer,0);
  v_active:=coalesce((p_product_type->>'is_active')::boolean,true);
  if v_name='' or char_length(v_name)>100 or v_category not in ('Alimentos','Limpeza','Higiene') or v_order<0 then
    raise exception 'basket_admin_product_type_invalid';
  end if;
  if jsonb_typeof(p_product_type->'options')<>'array' then raise exception 'basket_admin_product_options_invalid'; end if;
  for v_row in select value from jsonb_array_elements(p_product_type->'options') loop
    v_product:=nullif(v_row->>'product_id','')::uuid;
    -- Do not reject a product solely because it was deactivated after being added to a basket.
    if v_product is null or v_product=any(v_seen) or not exists(select 1 from public.products p where p.id=v_product) then
      raise exception 'basket_admin_product_option_invalid';
    end if;
    v_seen:=array_append(v_seen,v_product);
  end loop;
  if v_id is null then
    insert into public.basket_admin_product_types(name,category,sort_order,is_active,metadata)
    values(v_name,v_category,v_order,v_active,jsonb_build_object('updated_by',v_uid)) returning id into v_id;
  else
    update public.basket_admin_product_types set name=v_name,category=v_category,sort_order=v_order,is_active=v_active,
      metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('updated_by',v_uid),updated_at=now()
    where id=v_id;
    if not found then raise exception 'basket_admin_product_type_not_found'; end if;
  end if;
  delete from public.basket_admin_product_options where product_type_id=v_id;
  for v_row in select value from jsonb_array_elements(p_product_type->'options') with ordinality as x(value,ord) order by ord loop
    insert into public.basket_admin_product_options(product_type_id,product_id,sort_order)
    values(v_id,(v_row->>'product_id')::uuid,(v_row->>'sort_order')::integer);
  end loop;
  select legacy_labels into v_labels from public.basket_admin_product_types where id=v_id;
  for v_template in select linked_basket_id from public.basket_admin_basket_types where linked_basket_id is not null loop
    select id into v_mold from public.basket_molds where basket_id=v_template;
    if v_mold is null then continue; end if;
    select id into v_pos from public.basket_mold_positions where mold_id=v_mold
      and (lower(label)=any(select lower(x) from unnest(v_labels) x) or lower(label)=lower(v_name))
      order by sort_order,id limit 1;
    if v_pos is null then
      select coalesce(quantity,0) into v_qty from public.basket_admin_quantities
       where basket_type_id=(select id from public.basket_admin_basket_types where linked_basket_id=v_template)
       and product_type_id=v_id;
      if coalesce(v_qty,0)<=0 then continue; end if;
      insert into public.basket_mold_positions(mold_id,label,quantity,sort_order)
      select v_mold,v_name,v_qty,coalesce(max(sort_order)+1,0) from public.basket_mold_positions where mold_id=v_mold
      returning id into v_pos;
    end if;
    delete from public.basket_mold_position_options where position_id=v_pos;
    insert into public.basket_mold_position_options(position_id,product_id,sort_order)
      select v_pos,o.product_id,o.sort_order from public.basket_admin_product_options o
      where o.product_type_id=v_id order by o.sort_order,o.product_id;
  end loop;
  return public.admin_basket_configuration_v1();
end;
$function$
;

-- function: admin_basket_configuration_quantities_save_v1(p_quantities jsonb)
CREATE OR REPLACE FUNCTION public.admin_basket_configuration_quantities_save_v1(p_quantities jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_row jsonb;
  v_basket_type_id uuid;
  v_product_id uuid;
  v_quantity numeric;
  v_template_id uuid;
  v_mold_id uuid;
  v_position_id uuid;
  v_labels text[];
  v_name text;
  v_order integer;
begin
  if v_uid is null or not exists(
    select 1 from public.admin_users a
    where a.user_id=v_uid and a.is_active and a.role<>'viewer'
  ) then
    raise exception 'admin_not_authorized';
  end if;
  if jsonb_typeof(p_quantities)<>'array' then
    raise exception 'basket_admin_quantities_invalid';
  end if;

  for v_row in select value from jsonb_array_elements(p_quantities) loop
    v_basket_type_id:=nullif(v_row->>'basket_type_id','')::uuid;
    v_product_id:=nullif(v_row->>'product_type_id','')::uuid;
    v_quantity:=nullif(v_row->>'quantity','')::numeric;
    if v_basket_type_id is null or v_product_id is null or v_quantity is null or v_quantity<0
      or not exists(select 1 from public.basket_admin_basket_types where id=v_basket_type_id)
      or not exists(select 1 from public.basket_admin_product_types where id=v_product_id) then
      raise exception 'basket_admin_quantity_invalid';
    end if;
  end loop;

  for v_row in select value from jsonb_array_elements(p_quantities) loop
    v_basket_type_id:=(v_row->>'basket_type_id')::uuid;
    v_product_id:=(v_row->>'product_type_id')::uuid;
    v_quantity:=(v_row->>'quantity')::numeric;

    insert into public.basket_admin_quantities(basket_type_id,product_type_id,quantity,metadata,updated_at)
    values(v_basket_type_id,v_product_id,v_quantity,jsonb_build_object('updated_by',v_uid),now())
    on conflict(basket_type_id,product_type_id) do update
      set quantity=excluded.quantity,metadata=excluded.metadata,updated_at=now();

    select linked_basket_id into v_template_id
    from public.basket_admin_basket_types where id=v_basket_type_id;
    if v_template_id is null then continue; end if;

    select id into v_mold_id from public.basket_molds where basket_id=v_template_id;
    if v_mold_id is null then continue; end if;

    select name,legacy_labels into v_name,v_labels
    from public.basket_admin_product_types where id=v_product_id;

    if v_quantity=0 then
      delete from public.basket_mold_positions
      where mold_id=v_mold_id
        and (lower(label)=any(select lower(x) from unnest(v_labels) x) or lower(label)=lower(v_name));
      continue;
    end if;

    select id into v_position_id from public.basket_mold_positions
    where mold_id=v_mold_id
      and (lower(label)=any(select lower(x) from unnest(v_labels) x) or lower(label)=lower(v_name))
    order by sort_order,id limit 1;

    if v_position_id is null then
      select coalesce(max(sort_order)+1,0) into v_order
      from public.basket_mold_positions where mold_id=v_mold_id;
      insert into public.basket_mold_positions(mold_id,label,quantity,sort_order)
      values(v_mold_id,v_name,v_quantity,v_order);
      continue;
    end if;

    -- Merge alternatives from duplicate legacy rows before removing those rows.
    select coalesce(max(sort_order)+1,0) into v_order
    from public.basket_mold_position_options where position_id=v_position_id;
    insert into public.basket_mold_position_options(position_id,product_id,sort_order)
    select v_position_id,o.product_id,
      v_order+(row_number() over(order by extra.sort_order,extra.id,o.sort_order,o.product_id))::integer-1
    from public.basket_mold_positions extra
    join public.basket_mold_position_options o on o.position_id=extra.id
    where extra.mold_id=v_mold_id and extra.id<>v_position_id
      and (lower(extra.label)=any(select lower(x) from unnest(v_labels) x) or lower(extra.label)=lower(v_name))
    on conflict(position_id,product_id) do nothing;

    update public.basket_mold_positions
    set label=v_name,quantity=v_quantity,updated_at=now()
    where id=v_position_id;

    delete from public.basket_mold_positions
    where mold_id=v_mold_id and id<>v_position_id
      and (lower(label)=any(select lower(x) from unnest(v_labels) x) or lower(label)=lower(v_name));
  end loop;

  return public.admin_basket_configuration_v1();
end;
$function$
;

-- function: admin_basket_configuration_types_save_v1(p_types jsonb)
CREATE OR REPLACE FUNCTION public.admin_basket_configuration_types_save_v1(p_types jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid(); v_row jsonb; v_id uuid; v_name text; v_order integer; v_active boolean;
begin
  if v_uid is null or not exists(select 1 from public.admin_users a where a.user_id=v_uid and a.is_active and a.role<>'viewer') then
    raise exception 'admin_not_authorized';
  end if;
  if jsonb_typeof(p_types)<>'array' then raise exception 'basket_admin_types_invalid'; end if;
  if exists(select 1 from (select lower(btrim(value->>'name')) n,count(*) c from jsonb_array_elements(p_types) group by 1 having count(*)>1) d) then
    raise exception 'basket_admin_type_duplicate';
  end if;
  for v_row in select value from jsonb_array_elements(p_types) loop
    v_id:=nullif(v_row->>'id','')::uuid; v_name:=btrim(coalesce(v_row->>'name',''));
    v_order:=coalesce(nullif(v_row->>'sort_order','')::integer,0); v_active:=coalesce((v_row->>'is_active')::boolean,true);
    if v_name='' or char_length(v_name)>100 or v_order<0 then raise exception 'basket_admin_type_invalid'; end if;
    if v_id is null then
      insert into public.basket_admin_basket_types(name,sort_order,is_active,metadata)
      values(v_name,v_order,v_active,jsonb_build_object('updated_by',v_uid))
      returning id into v_id;
    else
      update public.basket_admin_basket_types set name=v_name,sort_order=v_order,is_active=v_active,updated_at=now(),
        metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('updated_by',v_uid)
      where id=v_id;
      if not found then raise exception 'basket_admin_type_not_found'; end if;
    end if;
    update public.basket_templates b set name=v_name,sort_order=v_order,updated_at=now()
    where b.id=(select linked_basket_id from public.basket_admin_basket_types where id=v_id);
  end loop;
  return public.admin_basket_configuration_v1();
end;
$function$
;

-- function: admin_basket_configuration_v1()
CREATE OR REPLACE FUNCTION public.admin_basket_configuration_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
begin
  if v_uid is null or not exists(
    select 1 from public.admin_users a
    where a.user_id=v_uid and a.is_active and a.role<>'viewer'
  ) then
    raise exception 'admin_not_authorized';
  end if;

  return jsonb_build_object(
    'basket_types',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',t.id,'name',t.name,'sort_order',t.sort_order,'is_active',t.is_active,
        'linked_template_id',t.linked_basket_id,'template_active',b.is_active,'site_visible',coalesce(b.is_active,false)
      ) order by t.sort_order,t.name)
      from public.basket_admin_basket_types t
      left join public.basket_templates b on b.id=t.linked_basket_id
    ),'[]'::jsonb),
    'product_types',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',pt.id,'name',pt.name,'category',pt.category,'sort_order',pt.sort_order,'is_active',pt.is_active,
        'options',coalesce((
          select jsonb_agg(jsonb_build_object(
            'product_id',p.id,'name',p.name,'sku',p.sku,'gtin',p.gtin,'image_url',p.image_url,
            'is_active',p.is_active,
            'stock',coalesce(p.stock,0),
            'physical_stock',coalesce(p.stock,0),
            'loose_sellable_stock',coalesce(s.loose_sellable_stock,0),
            'basket_locked_quantity',coalesce(s.basket_locked_quantity,0),
            'stock_authority','supabase','stock_source','supabase.products.stock',
            'bling_stock_ready',coalesce(s.bling_stock_ready,false),
            'price',p.price,'offer_price',p.offer_price,'is_offer',p.is_offer,'sort_order',o.sort_order
          ) order by o.sort_order,p.id)
          from public.basket_admin_product_options o
          join public.products p on p.id=o.product_id
          left join public.ops2_loose_sellable_stock_v1 s on s.product_id=p.id
          where o.product_type_id=pt.id
        ),'[]'::jsonb)
      ) order by case pt.category when 'Alimentos' then 0 when 'Limpeza' then 1 else 2 end,pt.sort_order,pt.name)
      from public.basket_admin_product_types pt
    ),'[]'::jsonb),
    'quantities',coalesce((
      select jsonb_agg(jsonb_build_object('basket_type_id',q.basket_type_id,'product_type_id',q.product_type_id,'quantity',q.quantity))
      from public.basket_admin_quantities q
    ),'[]'::jsonb)
  );
end;
$function$
;

-- function: admin_basket_extra_themes_editor_v1()
CREATE OR REPLACE FUNCTION public.admin_basket_extra_themes_editor_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_themes jsonb;
begin
  if v_uid is null or not exists (
    select 1 from public.admin_users a
    where a.user_id = v_uid and a.is_active and a.role <> 'viewer'
  ) then raise exception 'admin_not_authorized'; end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', t.id, 'name', t.name, 'sort_order', t.sort_order,
    'products', coalesce((
      select jsonb_agg(jsonb_build_object(
        'product_id', p.id, 'name', p.name, 'sku', p.sku, 'gtin', p.gtin,
        'image_url', p.image_url, 'packaging', p.packaging, 'is_active', p.is_active
      ) order by tp.sort_order, p.name)
      from public.basket_extra_theme_products tp
      join public.products p on p.id = tp.product_id
      where tp.theme_id = t.id
    ), '[]'::jsonb)
  ) order by t.sort_order, t.created_at, t.id), '[]'::jsonb)
  into v_themes from public.basket_extra_themes t;

  return jsonb_build_object('themes', v_themes);
end;
$function$
;

-- function: admin_basket_flow_configuration_save_v1(p_config jsonb)
CREATE OR REPLACE FUNCTION public.admin_basket_flow_configuration_save_v1(p_config jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_row jsonb;
  v_id uuid;
  v_enabled boolean;
  v_order integer;
  v_mode text;
  v_max integer;
  v_position_labels jsonb;
begin
  if v_uid is null or not exists(
    select 1 from public.admin_users a
    where a.user_id=v_uid and a.is_active and a.role<>'viewer'
  ) then
    raise exception 'admin_not_authorized';
  end if;

  if p_config is null or jsonb_typeof(p_config)<>'object'
     or coalesce(jsonb_typeof(p_config->'basket_types'),'')<>'array'
     or coalesce(jsonb_typeof(p_config->'product_types'),'')<>'array' then
    raise exception 'basket_admin_flow_configuration_invalid';
  end if;

  if exists(
    select 1 from jsonb_array_elements(p_config->'basket_types') as x(value)
    group by x.value->>'id' having count(*)>1
  ) or exists(
    select 1 from jsonb_array_elements(p_config->'product_types') as x(value)
    group by x.value->>'id' having count(*)>1
  ) then
    raise exception 'basket_admin_flow_duplicate_id';
  end if;

  for v_row in select value from jsonb_array_elements(p_config->'basket_types') loop
    v_id:=nullif(v_row->>'id','')::uuid;
    v_enabled:=coalesce((v_row->>'flow_enabled')::boolean,false);
    v_order:=coalesce(nullif(v_row->>'flow_sort_order','')::integer,-1);
    if v_id is null or v_order<0 or v_order>1000 then
      raise exception 'basket_admin_flow_basket_invalid';
    end if;
    update public.basket_admin_basket_types bt
    set metadata=jsonb_set(
      coalesce(bt.metadata,'{}'::jsonb),
      '{flow_v1}',
      coalesce(bt.metadata->'flow_v1','{}'::jsonb)
        || jsonb_build_object('enabled',v_enabled,'sort_order',v_order),
      true
    ),
    updated_at=now()
    where bt.id=v_id;
    if not found then raise exception 'basket_admin_flow_basket_not_found'; end if;
  end loop;

  for v_row in select value from jsonb_array_elements(p_config->'product_types') loop
    v_id:=nullif(v_row->>'id','')::uuid;
    v_enabled:=coalesce((v_row->>'flow_enabled')::boolean,false);
    v_order:=coalesce(nullif(v_row->>'flow_sort_order','')::integer,-1);
    v_mode:=coalesce(v_row->>'selection_mode','');
    v_max:=coalesce(nullif(v_row->>'max_quantity','')::integer,0);
    v_position_labels:=coalesce(
      v_row->'position_labels',
      (select case
        when jsonb_typeof(pt.metadata #> '{flow_v1,position_labels}')='array'
          then pt.metadata #> '{flow_v1,position_labels}'
        else '[]'::jsonb
      end from public.basket_admin_product_types pt where pt.id=v_id),
      '[]'::jsonb
    );
    if v_id is null or v_order<0 or v_order>1000
       or v_mode not in ('single','multiple') or v_max<1 or v_max>10
       or jsonb_typeof(v_position_labels)<>'array' then
      raise exception 'basket_admin_flow_product_type_invalid';
    end if;
    if jsonb_array_length(v_position_labels)>20 or exists(
      select 1 from jsonb_array_elements(v_position_labels) as x(value)
      where jsonb_typeof(x.value)<>'string'
         or nullif(btrim(x.value #>> '{}'),'') is null
         or char_length(btrim(x.value #>> '{}'))>120
    ) then
      raise exception 'basket_admin_flow_product_type_invalid';
    end if;
    update public.basket_admin_product_types pt
    set metadata=jsonb_set(
      coalesce(pt.metadata,'{}'::jsonb),
      '{flow_v1}',
      coalesce(pt.metadata->'flow_v1','{}'::jsonb)
        || jsonb_build_object(
          'enabled',v_enabled,
          'sort_order',v_order,
          'selection_mode',v_mode,
          'max_quantity',v_max,
          'position_labels',v_position_labels
        ),
      true
    ),
    updated_at=now()
    where pt.id=v_id;
    if not found then raise exception 'basket_admin_flow_product_type_not_found'; end if;
  end loop;

  return public.admin_basket_flow_configuration_v1();
end;
$function$
;

-- function: admin_basket_flow_configuration_v1()
CREATE OR REPLACE FUNCTION public.admin_basket_flow_configuration_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
begin
  if v_uid is null or not exists(
    select 1 from public.admin_users a
    where a.user_id=v_uid and a.is_active and a.role<>'viewer'
  ) then
    raise exception 'admin_not_authorized';
  end if;

  return jsonb_build_object(
    'basket_types',coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id',bt.id,
          'name',bt.name,
          'sort_order',bt.sort_order,
          'is_active',bt.is_active,
          'linked_template_id',bt.linked_basket_id,
          'template_active',b.is_active,
          'site_visible',coalesce(b.is_active,false),
          'public_composition_count',coalesce(m.public_composition_count,0),
          'flow_enabled',coalesce((bt.metadata #>> '{flow_v1,enabled}')::boolean,false),
          'flow_sort_order',case
            when coalesce(bt.metadata #>> '{flow_v1,sort_order}','') ~ '^[0-9]+$'
              then (bt.metadata #>> '{flow_v1,sort_order}')::integer
            else bt.sort_order
          end
        )
        order by
          case when coalesce(bt.metadata #>> '{flow_v1,sort_order}','') ~ '^[0-9]+$'
            then (bt.metadata #>> '{flow_v1,sort_order}')::integer else bt.sort_order end,
          bt.name
      )
      from public.basket_admin_basket_types bt
      left join public.basket_templates b on b.id=bt.linked_basket_id
      left join public.basket_molds m on m.basket_id=bt.linked_basket_id
    ),'[]'::jsonb),
    'product_types',coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id',pt.id,
          'name',pt.name,
          'category',pt.category,
          'sort_order',pt.sort_order,
          'is_active',pt.is_active,
          'legacy_labels',pt.legacy_labels,
          'position_labels',case
            when jsonb_typeof(pt.metadata #> '{flow_v1,position_labels}')='array'
              then pt.metadata #> '{flow_v1,position_labels}'
            else '[]'::jsonb
          end,
          'flow_enabled',coalesce((pt.metadata #>> '{flow_v1,enabled}')::boolean,pt.is_active),
          'flow_sort_order',case
            when coalesce(pt.metadata #>> '{flow_v1,sort_order}','') ~ '^[0-9]+$'
              then (pt.metadata #>> '{flow_v1,sort_order}')::integer
            else pt.sort_order
          end,
          'selection_mode',case
            when pt.metadata #>> '{flow_v1,selection_mode}' in ('single','multiple')
              then pt.metadata #>> '{flow_v1,selection_mode}'
            else 'multiple'
          end,
          'max_quantity',case
            when coalesce(pt.metadata #>> '{flow_v1,max_quantity}','') ~ '^[0-9]+$'
              then greatest(1,least(10,(pt.metadata #>> '{flow_v1,max_quantity}')::integer))
            else 10
          end,
          'options',coalesce((
            select jsonb_agg(
              jsonb_build_object(
                'product_id',p.id,
                'name',p.name,
                'brand',p.brand,
                'sku',p.sku,
                'gtin',p.gtin,
                'image_url',p.image_url,
                'packaging',p.packaging,
                'price_cents',round((case when p.is_offer and p.offer_price is not null then p.offer_price else p.price end)*100)::integer,
                'regular_price_cents',case when p.is_offer and p.offer_price is not null then round(coalesce(p.price,0)*100)::integer else null end,
                'is_offer',p.is_offer and p.offer_price is not null,
                'is_active',p.is_active,
                'sort_order',o.sort_order
              )
              order by o.sort_order,p.id
            )
            from public.basket_admin_product_options o
            join public.products p on p.id=o.product_id
            where o.product_type_id=pt.id
          ),'[]'::jsonb)
        )
        order by
          case when coalesce(pt.metadata #>> '{flow_v1,sort_order}','') ~ '^[0-9]+$'
            then (pt.metadata #>> '{flow_v1,sort_order}')::integer else pt.sort_order end,
          pt.name
      )
      from public.basket_admin_product_types pt
    ),'[]'::jsonb),
    'quantities',coalesce((
      select jsonb_agg(jsonb_build_object(
        'basket_type_id',q.basket_type_id,
        'product_type_id',q.product_type_id,
        'quantity',q.quantity
      ))
      from public.basket_admin_quantities q
    ),'[]'::jsonb)
  );
end;
$function$
;

-- function: admin_basket_mold_editor_v1(p_basket_id uuid)
CREATE OR REPLACE FUNCTION public.admin_basket_mold_editor_v1(p_basket_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid(); v_result jsonb; v_category_id uuid; v_subcategory_id uuid;
begin
 if v_uid is null or not exists(select 1 from public.admin_users a where a.user_id=v_uid and a.is_active) then raise exception 'admin_not_authorized'; end if;
 v_result:=public.basket_mold_editor_v1(p_basket_id); if v_result is null then raise exception 'basket_mold_basket_not_found'; end if;
 select category_id,subcategory_id into v_category_id,v_subcategory_id from public.basket_templates where id=p_basket_id;
 return v_result||jsonb_build_object('category_id',v_category_id,'subcategory_id',v_subcategory_id);
end; $function$
;

-- function: admin_basket_mold_list_v1()
CREATE OR REPLACE FUNCTION public.admin_basket_mold_list_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();
begin
 if v_uid is null or not exists(select 1 from public.admin_users a where a.user_id=v_uid and a.is_active) then raise exception 'admin_not_authorized'; end if;
 return jsonb_build_object(
 'baskets',coalesce((select jsonb_agg(jsonb_build_object('id',b.id,'name',b.name,'image_url',b.image_url,'is_active',b.is_active,'category_id',b.category_id,'subcategory_id',b.subcategory_id,'category_name',c.name,'subcategory_name',s.name,'mold_configured',m.id is not null,'hidden_adjustment',coalesce(m.hidden_adjustment,0),'public_composition_count',coalesce(m.public_composition_count,2)) order by b.sort_order,b.name,b.id)
 from public.basket_templates b left join public.basket_molds m on m.basket_id=b.id left join public.basket_categories c on c.id=b.category_id left join public.basket_subcategories s on s.id=b.subcategory_id
 where b.is_active and coalesce((b.rules->>'mold_legacy_source')::boolean,false)=false and coalesce((b.rules->>'mold_internal_legacy')::boolean,false)=false),'[]'::jsonb),
 'categories',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'name',c.name,'slug',c.slug,'sort_order',c.sort_order) order by c.sort_order,c.name) from public.basket_categories c where c.is_active),'[]'::jsonb),
 'subcategories',coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'category_id',s.category_id,'name',s.name,'sort_order',s.sort_order) order by s.sort_order,s.name) from public.basket_subcategories s where s.is_active),'[]'::jsonb));
end; $function$
;

-- function: admin_basket_mold_optional_items_editor_v1(p_basket_id uuid)
CREATE OR REPLACE FUNCTION public.admin_basket_mold_optional_items_editor_v1(p_basket_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_mold public.basket_molds%rowtype;
  v_basket public.basket_templates%rowtype;
  v_items jsonb;
begin
  if v_uid is null or not exists (
    select 1 from public.admin_users a
    where a.user_id = v_uid and a.is_active and a.role <> 'viewer'
  ) then raise exception 'admin_not_authorized'; end if;

  select * into v_basket from public.basket_templates where id = p_basket_id;
  select * into v_mold from public.basket_molds where basket_id = p_basket_id;
  if v_basket.id is null or v_mold.id is null then raise exception 'basket_mold_basket_not_found'; end if;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', e.item->>'id',
      'label', e.item->>'label',
      'options', coalesce((
        select jsonb_agg(jsonb_build_object(
          'product_id', p.id, 'name', p.name, 'sku', p.sku, 'gtin', p.gtin,
          'image_url', p.image_url, 'packaging', p.packaging
        ) order by o.ordinality)
        from jsonb_array_elements_text(coalesce(e.item->'product_ids','[]'::jsonb)) with ordinality o(product_id, ordinality)
        join public.products p on p.id = o.product_id::uuid and p.is_active = true
      ), '[]'::jsonb)
    ) order by e.ordinality
  ), '[]'::jsonb)
  into v_items
  from jsonb_array_elements(coalesce(v_mold.metadata->'optional_items','[]'::jsonb)) with ordinality e(item, ordinality);

  return jsonb_build_object('basket_id', v_basket.id, 'basket_name', v_basket.name, 'items', v_items);
end;
$function$
;

-- function: admin_basket_mold_products_v1(p_query text, p_limit integer)
CREATE OR REPLACE FUNCTION public.admin_basket_mold_products_v1(p_query text DEFAULT NULL::text, p_limit integer DEFAULT 24)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_query text:=btrim(coalesce(p_query,''));
  v_limit integer:=least(40,greatest(1,coalesce(p_limit,24)));
begin
  if v_uid is null or not exists(
    select 1 from public.admin_users a
    where a.user_id=v_uid and a.is_active=true
  ) then
    raise exception 'admin_not_authorized';
  end if;

  return jsonb_build_object(
    'products',coalesce((
      select jsonb_agg(row_data order by row_data->>'name',row_data->>'id')
      from (
        select jsonb_build_object(
          'id',p.id,'name',p.name,'sku',p.sku,'gtin',p.gtin,'packaging',p.packaging,
          'image_url',p.image_url,'price',p.price,'cost',p.cost,'stock',coalesce(p.stock,0),
          'is_active',p.is_active,'loose_sellable_stock',coalesce(s.loose_sellable_stock,0),
          'effective_sellable_stock',coalesce(s.effective_sellable_stock,0),
          'basket_locked_quantity',coalesce(s.basket_locked_quantity,0)
        ) as row_data
        from public.products p
        left join public.ops2_loose_sellable_stock_v1 s on s.product_id=p.id
        where v_query='' or p.name ilike '%'||v_query||'%'
          or coalesce(p.sku,'') ilike '%'||v_query||'%'
          or coalesce(p.gtin,'') ilike '%'||v_query||'%'
        order by p.name,p.id
        limit v_limit
      ) q
    ),'[]'::jsonb)
  );
end;
$function$
;

-- function: admin_basket_mold_shared_items_v1()
CREATE OR REPLACE FUNCTION public.admin_basket_mold_shared_items_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();
begin
  if v_uid is null or not exists(
    select 1 from public.admin_users a where a.user_id=v_uid and a.is_active and a.role<>'viewer'
  ) then raise exception 'admin_not_authorized'; end if;
  return jsonb_build_object('items',coalesce((
    select jsonb_agg(jsonb_build_object(
      'id',i.id,'label',i.label,'sort_order',i.sort_order,
      'options',coalesce((
        select jsonb_agg(jsonb_build_object(
          'product_id',p.id,'name',p.name,'brand',p.brand,'sku',p.sku,'gtin',p.gtin,
          'image_url',p.image_url,'price',p.price,'offer_price',p.offer_price,'is_offer',p.is_offer,
          'sort_order',o.sort_order
        ) order by o.sort_order,o.id)
        from public.basket_mold_shared_item_options o
        join public.products p on p.id=o.product_id
        where o.shared_item_id=i.id
      ),'[]'::jsonb)
    ) order by i.sort_order,i.label)
    from public.basket_mold_shared_items i where i.scope='cestas-completas'
  ),'[]'::jsonb));
end;
$function$
;

-- function: admin_save_basket_extra_themes_v1(p_themes jsonb)
CREATE OR REPLACE FUNCTION public.admin_save_basket_extra_themes_v1(p_themes jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_theme jsonb;
  v_product jsonb;
  v_theme_id uuid;
  v_product_id uuid;
  v_name text;
  v_theme_order integer := 0;
  v_product_order integer;
  v_seen_themes uuid[] := array[]::uuid[];
  v_seen_products uuid[];
begin
  if v_uid is null or not exists (
    select 1 from public.admin_users a
    where a.user_id = v_uid and a.is_active and a.role <> 'viewer'
  ) then raise exception 'admin_not_authorized'; end if;
  if coalesce(jsonb_typeof(p_themes), 'null') <> 'array' then
    raise exception 'basket_extra_themes_invalid';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('basket_extra_themes_v1', 0));
  delete from public.basket_extra_themes where true;

  for v_theme in select value from jsonb_array_elements(p_themes) loop
    v_name := btrim(coalesce(v_theme->>'name', ''));
    if v_name = '' or char_length(v_name) > 80 then raise exception 'basket_extra_theme_name_invalid'; end if;
    if coalesce(v_theme->>'id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
      raise exception 'basket_extra_theme_id_invalid';
    end if;
    v_theme_id := (v_theme->>'id')::uuid;
    if v_theme_id = any(v_seen_themes) then raise exception 'basket_extra_theme_id_invalid'; end if;
    v_seen_themes := array_append(v_seen_themes, v_theme_id);
    if coalesce(jsonb_typeof(v_theme->'products'), 'array') <> 'array' then raise exception 'basket_extra_theme_products_invalid'; end if;

    insert into public.basket_extra_themes(id, name, sort_order, updated_at)
    values (v_theme_id, v_name, v_theme_order, now());
    v_seen_products := array[]::uuid[];
    v_product_order := 0;
    for v_product in select value from jsonb_array_elements(coalesce(v_theme->'products','[]'::jsonb)) loop
      if coalesce(v_product->>'product_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
        raise exception 'basket_extra_theme_product_invalid';
      end if;
      v_product_id := (v_product->>'product_id')::uuid;
      if v_product_id = any(v_seen_products) then raise exception 'basket_extra_theme_product_duplicate'; end if;
      if not exists (select 1 from public.products p where p.id = v_product_id) then
        raise exception 'basket_extra_theme_product_not_found';
      end if;
      v_seen_products := array_append(v_seen_products, v_product_id);
      insert into public.basket_extra_theme_products(theme_id, product_id, sort_order)
      values (v_theme_id, v_product_id, v_product_order);
      v_product_order := v_product_order + 1;
    end loop;
    v_theme_order := v_theme_order + 1;
  end loop;

  return public.admin_basket_extra_themes_editor_v1();
end;
$function$
;

-- function: admin_save_basket_mold_optional_items_v1(p_basket_id uuid, p_items jsonb)
CREATE OR REPLACE FUNCTION public.admin_save_basket_mold_optional_items_v1(p_basket_id uuid, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_item jsonb;
  v_product text;
  v_seen text[];
  v_clean jsonb := '[]'::jsonb;
  v_count integer := 0;
  v_label text;
  v_options jsonb;
begin
  if v_uid is null or not exists (
    select 1 from public.admin_users a
    where a.user_id = v_uid and a.is_active and a.role <> 'viewer'
  ) then raise exception 'admin_not_authorized'; end if;
  if not exists (select 1 from public.basket_molds where basket_id = p_basket_id) then
    raise exception 'basket_mold_basket_not_found';
  end if;
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) > 40 then
    raise exception 'basket_mold_optional_items_invalid';
  end if;

  for v_item in select value from jsonb_array_elements(p_items) loop
    v_count := v_count + 1;
    v_label := btrim(coalesce(v_item->>'label',''));
    v_options := coalesce(v_item->'options','[]'::jsonb);
    if v_label = '' or char_length(v_label) > 120 then raise exception 'basket_mold_optional_label_invalid'; end if;
    if jsonb_typeof(v_options) <> 'array' or jsonb_array_length(v_options) < 1 or jsonb_array_length(v_options) > 3 then
      raise exception 'basket_mold_optional_options_limit';
    end if;
    v_seen := array[]::text[];
    for v_product in select value from jsonb_array_elements_text(v_options) loop
      if v_product !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
        raise exception 'basket_mold_optional_product_invalid';
      end if;
      if v_product = any(v_seen)
        or not exists (select 1 from public.products p where p.id = v_product::uuid and p.is_active = true) then
        raise exception 'basket_mold_optional_product_invalid';
      end if;
      v_seen := array_append(v_seen, v_product);
    end loop;
    v_clean := v_clean || jsonb_build_array(jsonb_build_object(
      'id', case when coalesce(v_item->>'id','') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then v_item->>'id' else gen_random_uuid()::text end,
      'label', v_label,
      'product_ids', to_jsonb(v_seen)
    ));
  end loop;

  update public.basket_molds
  set metadata = jsonb_set(coalesce(metadata,'{}'::jsonb), '{optional_items}', v_clean, true), updated_at = now()
  where basket_id = p_basket_id;

  return jsonb_build_object('basket_id', p_basket_id, 'items', v_clean);
end;
$function$
;

-- function: admin_save_basket_mold_shared_items_v1(p_items jsonb)
CREATE OR REPLACE FUNCTION public.admin_save_basket_mold_shared_items_v1(p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_item jsonb;
  v_option jsonb;
  v_item_id uuid;
  v_product_id uuid;
  v_label text;
  v_order integer;
  v_seen uuid[];
begin
  if v_uid is null or not exists(
    select 1 from public.admin_users a where a.user_id=v_uid and a.is_active and a.role<>'viewer'
  ) then raise exception 'admin_not_authorized'; end if;
  if p_items is null or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)>150 then
    raise exception 'basket_mold_shared_items_invalid';
  end if;
  for v_item in select value from jsonb_array_elements(p_items) loop
    v_item_id:=nullif(v_item->>'id','')::uuid;
    v_label:=btrim(coalesce(v_item->>'label',''));
    if v_item_id is null or v_label='' or jsonb_typeof(v_item->'options')<>'array'
      or jsonb_array_length(v_item->'options')<1 or jsonb_array_length(v_item->'options')>3 then
      raise exception 'basket_mold_shared_item_invalid';
    end if;
    if not exists(select 1 from public.basket_mold_shared_items i
      where i.id=v_item_id and i.scope='cestas-completas') then
      raise exception 'basket_mold_shared_item_not_found';
    end if;
    v_seen:='{}'::uuid[];
    for v_option in select value from jsonb_array_elements(v_item->'options') loop
      v_product_id:=nullif(v_option->>'product_id','')::uuid;
      if v_product_id is null or v_product_id=any(v_seen)
        or not exists(select 1 from public.products p where p.id=v_product_id) then
        raise exception 'basket_mold_shared_product_invalid';
      end if;
      v_seen:=array_append(v_seen,v_product_id);
    end loop;
  end loop;

  for v_item in select value from jsonb_array_elements(p_items) loop
    v_item_id:=(v_item->>'id')::uuid;
    v_label:=btrim(v_item->>'label');
    update public.basket_mold_shared_items set label=v_label,updated_at=now(),
      metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('updated_by',v_uid)
      where id=v_item_id;
    delete from public.basket_mold_shared_item_options where shared_item_id=v_item_id;
    v_order:=0;
    for v_option in select value from jsonb_array_elements(v_item->'options') loop
      v_product_id:=(v_option->>'product_id')::uuid;
      insert into public.basket_mold_shared_item_options(shared_item_id,product_id,sort_order)
      values(v_item_id,v_product_id,v_order);
      v_order:=v_order+1;
    end loop;
    delete from public.basket_mold_position_options opt
    using public.basket_mold_positions pos,public.basket_molds m,
      public.basket_templates b,public.basket_categories c,public.basket_subcategories s
    where opt.position_id=pos.id and pos.mold_id=m.id and m.basket_id=b.id
      and b.category_id=c.id and b.subcategory_id=s.id and c.slug='cestas-completas'
      and s.name in ('Econômica','Mini Completa','Pequena Completa','Média Completa','Grande Completa')
      and pos.label=v_label;
    insert into public.basket_mold_position_options(position_id,product_id,sort_order)
    select pos.id,o.product_id,o.sort_order
    from public.basket_mold_positions pos
    join public.basket_molds m on m.id=pos.mold_id
    join public.basket_templates b on b.id=m.basket_id
    join public.basket_categories c on c.id=b.category_id and c.slug='cestas-completas'
    join public.basket_subcategories s on s.id=b.subcategory_id
    join public.basket_mold_shared_item_options o on o.shared_item_id=v_item_id
    where s.name in ('Econômica','Mini Completa','Pequena Completa','Média Completa','Grande Completa')
      and pos.label=v_label;
  end loop;
  return public.admin_basket_mold_shared_items_v1();
end;
$function$
;

-- function: admin_save_basket_mold_v1(p_basket_id uuid, p_name text, p_hidden_adjustment numeric, p_public_composition_count integer, p_positions jsonb, p_category_id uuid, p_operator text)
CREATE OR REPLACE FUNCTION public.admin_save_basket_mold_v1(p_basket_id uuid, p_name text, p_hidden_adjustment numeric, p_public_composition_count integer, p_positions jsonb, p_category_id uuid, p_operator text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_result jsonb;
begin
  if v_uid is null or not exists (
    select 1 from public.admin_users a
    where a.user_id=v_uid and a.is_active=true and a.role<>'viewer'
  ) then
    raise exception 'admin_not_authorized';
  end if;

  if p_category_id is null or not exists (
    select 1 from public.basket_categories c
    where c.id=p_category_id and c.is_active=true
      and c.slug in ('cestas-completas','cestas-so-alimentos','kits-promocionais')
  ) then
    raise exception 'basket_category_invalid';
  end if;

  v_result := public.admin_save_basket_mold_v1(
    p_basket_id,p_name,p_hidden_adjustment,p_public_composition_count,p_positions,p_operator
  );

  update public.basket_templates
     set category_id=p_category_id,updated_at=now()
   where id=p_basket_id;

  return coalesce(v_result,'{}'::jsonb) || jsonb_build_object('category_id',p_category_id);
end;
$function$
;

-- function: admin_save_basket_mold_v1(p_basket_id uuid, p_name text, p_hidden_adjustment numeric, p_public_composition_count integer, p_positions jsonb, p_category_id uuid, p_operator text, p_subcategory_id uuid)
CREATE OR REPLACE FUNCTION public.admin_save_basket_mold_v1(p_basket_id uuid, p_name text, p_hidden_adjustment numeric, p_public_composition_count integer, p_positions jsonb, p_category_id uuid, p_operator text, p_subcategory_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid(); v_name text:=btrim(coalesce(p_name,'')); v_result jsonb;
begin
 if v_uid is null or not exists(select 1 from public.admin_users a where a.user_id=v_uid and a.is_active and a.role<>'viewer') then raise exception 'admin_not_authorized'; end if;
 if not exists(select 1 from public.basket_templates b where b.id=p_basket_id) then raise exception 'basket_mold_basket_not_found'; end if;
 if not exists(select 1 from public.basket_categories c where c.id=p_category_id and c.is_active) then raise exception 'basket_category_invalid'; end if;
 if not exists(select 1 from public.basket_subcategories s where s.id=p_subcategory_id and s.category_id=p_category_id and s.is_active) then raise exception 'basket_subcategory_invalid'; end if;
 if v_name='' or char_length(v_name)>180 then raise exception 'basket_mold_name_invalid'; end if;
 update public.basket_templates set name=v_name,category_id=p_category_id,subcategory_id=p_subcategory_id,updated_at=now() where id=p_basket_id;
 v_result:=public.save_basket_mold_v1(p_basket_id,p_hidden_adjustment,p_public_composition_count,p_positions,coalesce(nullif(btrim(p_operator),''),'Operação'));
 return coalesce(v_result,'{}'::jsonb)||jsonb_build_object('basket_name',v_name,'category_id',p_category_id,'subcategory_id',p_subcategory_id);
end; $function$
;

-- function: admin_save_basket_mold_v1(p_basket_id uuid, p_name text, p_hidden_adjustment numeric, p_public_composition_count integer, p_positions jsonb, p_operator text)
CREATE OR REPLACE FUNCTION public.admin_save_basket_mold_v1(p_basket_id uuid, p_name text, p_hidden_adjustment numeric, p_public_composition_count integer, p_positions jsonb, p_operator text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_name text := btrim(coalesce(p_name, ''));
  v_result jsonb;
begin
  if v_uid is null or not exists (
    select 1 from public.admin_users a
    where a.user_id = v_uid and a.is_active = true and a.role <> 'viewer'
  ) then
    raise exception 'admin_not_authorized';
  end if;

  if v_name = '' or char_length(v_name) > 180 then
    raise exception 'basket_mold_name_invalid';
  end if;

  if p_basket_id is null or not exists (
    select 1 from public.basket_templates b where b.id = p_basket_id
  ) then
    raise exception 'basket_mold_basket_not_found';
  end if;

  update public.basket_templates
     set name = v_name,
         updated_at = now()
   where id = p_basket_id;

  v_result := public.save_basket_mold_v1(
    p_basket_id,
    p_hidden_adjustment,
    p_public_composition_count,
    p_positions,
    coalesce(nullif(btrim(p_operator), ''), 'Operação')
  );

  return coalesce(v_result, '{}'::jsonb) || jsonb_build_object('basket_name', v_name);
end;
$function$
;

