CREATE OR REPLACE FUNCTION public.admin_save_basket_mold_v2(p_basket_id uuid, p_name text, p_hidden_adjustment numeric, p_public_composition_count integer, p_positions jsonb, p_category_id uuid, p_operator text, p_subcategory_id uuid)
 RETURNS jsonb
