-- function: admin_save_basket_mold_v3(p_basket_id uuid, p_name text, p_hidden_adjustment numeric, p_public_composition_count integer, p_positions jsonb, p_category_id uuid, p_subcategory_id uuid, p_conditional_hidden_enabled boolean, p_conditional_hidden_product_id uuid, p_conditional_hidden_adjustment numeric, p_operator text)
CREATE OR REPLACE FUNCTION public.admin_save_basket_mold_v3(p_basket_id uuid, p_name text, p_hidden_adjustment numeric, p_public_composition_count integer, p_positions jsonb, p_category_id uuid, p_subcategory_id uuid, p_conditional_hidden_enabled boolean, p_conditional_hidden_product_id uuid, p_conditional_hidden_adjustment numeric, p_operator text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_name text:=btrim(coalesce(p_name,''));
  v_result jsonb;
  v_conditional numeric:=round(coalesce(p_conditional_hidden_adjustment,0),2);
begin
  if v_uid is null or not exists(
    select 1 from public.admin_users a
    where a.user_id=v_uid and a.is_active and a.role<>'viewer'
  ) then
    raise exception 'admin_not_authorized';
  end if;

  if p_basket_id is null or not exists(
    select 1 from public.basket_templates b where b.id=p_basket_id
  ) then raise exception 'basket_mold_basket_not_found'; end if;

  if not exists(
    select 1 from public.basket_categories c
    where c.id=p_category_id and c.is_active
  ) then raise exception 'basket_category_invalid'; end if;

  if not exists(
    select 1 from public.basket_subcategories s
    where s.id=p_subcategory_id and s.category_id=p_category_id and s.is_active
  ) then raise exception 'basket_subcategory_invalid'; end if;

  if v_name='' or char_length(v_name)>180 then
    raise exception 'basket_mold_name_invalid';
  end if;

  if v_conditional<0 or v_conditional>9999999 then
    raise exception 'basket_mold_conditional_hidden_adjustment_invalid';
  end if;

  if p_conditional_hidden_product_id is not null and not exists(
    select 1 from public.products p where p.id=p_conditional_hidden_product_id
  ) then
    raise exception 'basket_mold_conditional_hidden_product_invalid';
  end if;

  if coalesce(p_conditional_hidden_enabled,false) then
    if p_conditional_hidden_product_id is null then
      raise exception 'basket_mold_conditional_hidden_product_required';
    end if;
    if v_conditional<=0 then
      raise exception 'basket_mold_conditional_hidden_adjustment_required';
    end if;
  end if;

  update public.basket_templates
     set name=v_name,
         category_id=p_category_id,
         subcategory_id=p_subcategory_id,
         updated_at=now()
   where id=p_basket_id;

  v_result:=public.save_basket_mold_v1(
    p_basket_id,
    p_hidden_adjustment,
    p_public_composition_count,
    p_positions,
    coalesce(nullif(btrim(p_operator),''),'Operação')
  );

  update public.basket_molds
     set conditional_hidden_enabled=coalesce(p_conditional_hidden_enabled,false),
         conditional_hidden_product_id=p_conditional_hidden_product_id,
         conditional_hidden_adjustment=v_conditional,
         metadata=coalesce(metadata,'{}'::jsonb) || jsonb_build_object(
           'conditional_hidden_rule_version',1,
           'updated_by',coalesce(nullif(btrim(p_operator),''),'Operação')
         ),
         updated_at=now()
   where basket_id=p_basket_id;

  return public.basket_mold_editor_v1(p_basket_id)
    || jsonb_build_object(
      'basket_name',v_name,
      'category_id',p_category_id,
      'subcategory_id',p_subcategory_id
    );
end;
$function$
;

-- function: admin_upsert_basket_mold_shared_item_v2(p_item jsonb)
CREATE OR REPLACE FUNCTION public.admin_upsert_basket_mold_shared_item_v2(p_item jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_id uuid;
  v_label text;
  v_old_label text;
  v_options jsonb;
  v_option jsonb;
  v_product uuid;
  v_seen uuid[]:='{}'::uuid[];
  v_order integer:=0;
  v_limit integer:=40;
begin
  if v_uid is null or not exists(
    select 1 from public.admin_users a
    where a.user_id=v_uid and a.is_active and a.role<>'viewer'
  ) then raise exception 'admin_not_authorized'; end if;
  if p_item is null or jsonb_typeof(p_item)<>'object' then
    raise exception 'basket_mold_shared_item_invalid';
  end if;
  v_label:=btrim(coalesce(p_item->>'label',''));
  v_options:=p_item->'options';
  if v_label='' or char_length(v_label)>180
     or coalesce(jsonb_typeof(v_options),'')<>'array'
     or jsonb_array_length(v_options) < 1 or jsonb_array_length(v_options)>v_limit then
    raise exception 'basket_mold_shared_item_invalid';
  end if;
  -- Prevent overlapping mutations on the shared registry.
  perform pg_advisory_xact_lock(hashtextextended('basket_mold_shared_items:cestas-completas',0));
  v_id:=nullif(p_item->>'id','')::uuid;
  if v_id is null then
    insert into public.basket_mold_shared_items(scope,label,sort_order,metadata)
    values ('cestas-completas',v_label,
      (select coalesce(max(sort_order)+1,0) from public.basket_mold_shared_items where scope='cestas-completas'),
      jsonb_build_object('updated_by',v_uid))
    returning id into v_id;
  else
    select label into v_old_label from public.basket_mold_shared_items
    where id=v_id and scope='cestas-completas' for update;
    if not found then raise exception 'basket_mold_shared_item_not_found'; end if;
    if v_label<>v_old_label then
      -- Allow a rename while preserving existing quantities in each basket.
      update public.basket_mold_positions pos set label=v_label
      from public.basket_molds m,public.basket_templates b,public.basket_categories cat
      where pos.mold_id=m.id and m.basket_id=b.id and b.category_id=cat.id
        and cat.slug='cestas-completas' and pos.label=v_old_label;
    end if;
    update public.basket_mold_shared_items set label=v_label,
       updated_at=now(),metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('updated_by',v_uid)
    where id=v_id;
  end if;
  for v_option in select value from jsonb_array_elements(v_options) loop
    v_product:=nullif(v_option->>'product_id','')::uuid;
    if v_product is null or v_product=any(v_seen)
      or not exists(select 1 from public.products p where p.id=v_product and p.is_active=true) then
      raise exception 'basket_mold_shared_product_invalid';
    end if;
    v_seen:=array_append(v_seen,v_product);
  end loop;

  delete from public.basket_mold_shared_item_options where shared_item_id=v_id;
  for v_option in select value from jsonb_array_elements(v_options) loop
    insert into public.basket_mold_shared_item_options(shared_item_id,product_id,sort_order)
    values (v_id,(v_option->>'product_id')::uuid,v_order);
    v_order:=v_order+1;
  end loop;

  -- Materialize the shared choices into each active position, without touching quantities.
  delete from public.basket_mold_position_options op
    using public.basket_mold_positions pos,public.basket_molds m,
          public.basket_templates b,public.basket_categories cat
    where op.position_id=pos.id and pos.mold_id=m.id and m.basket_id=b.id
      and b.category_id=cat.id and cat.slug='cestas-completas' and pos.label=v_label;
  insert into public.basket_mold_position_options(position_id,product_id,sort_order)
    select pos.id,op.product_id,op.sort_order
    from public.basket_mold_positions pos
    join public.basket_molds m on m.id=pos.mold_id
    join public.basket_templates b on b.id=m.basket_id
    join public.basket_categories cat on cat.id=b.category_id and cat.slug='cestas-completas'
    join public.basket_mold_shared_item_options op on op.shared_item_id=v_id
    where pos.label=v_label;
  return public.admin_basket_mold_shared_items_v1() || jsonb_build_object('item_id',v_id);
end;
$function$
;

-- function: admin_whatsapp_flow_binding_disable_v1(p_account_id uuid, p_binding_id uuid)
CREATE OR REPLACE FUNCTION public.admin_whatsapp_flow_binding_disable_v1(p_account_id uuid, p_binding_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_updated uuid;
begin
  update whatsapp_ordering_private.whatsapp_order_flow_bindings_v1 b
  set is_send_enabled = false, updated_at = now()
  from public.whatsapp_accounts a
  where b.id = p_binding_id
    and b.whatsapp_account_id = p_account_id
    and a.id = b.whatsapp_account_id
    and a.slug in ('dona-antonia-0975', 'dona-antonia-1018')
  returning b.id into v_updated;
  if v_updated is null then
    return jsonb_build_object('ok', false, 'error', 'flow_binding_not_found');
  end if;
  return jsonb_build_object('ok', true, 'binding_id', v_updated, 'is_send_enabled', false);
end;
$function$
;

-- function: admin_whatsapp_flow_binding_enable_v1(p_account_id uuid, p_binding_id uuid)
CREATE OR REPLACE FUNCTION public.admin_whatsapp_flow_binding_enable_v1(p_account_id uuid, p_binding_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_key_status text;
  v_updated uuid;
begin
  select k.key_status into v_key_status
  from whatsapp_ordering_private.whatsapp_flow_keyring_v1 k
  join public.whatsapp_accounts a on a.id = k.whatsapp_account_id
  where k.whatsapp_account_id = p_account_id
    and a.slug in ('dona-antonia-0975', 'dona-antonia-1018')
    and a.is_active;
  if v_key_status is distinct from 'ready' then
    return jsonb_build_object('ok', false, 'error', 'flow_key_not_ready');
  end if;

  perform 1
  from whatsapp_ordering_private.whatsapp_order_flow_bindings_v1 b
  where b.id = p_binding_id
    and b.whatsapp_account_id = p_account_id
    and b.is_verified
    and upper(b.flow_status) = 'PUBLISHED'
    and b.verified_at is not null
  for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'flow_binding_not_verified');
  end if;

  update whatsapp_ordering_private.whatsapp_order_flow_bindings_v1
  set is_send_enabled = false, updated_at = now()
  where whatsapp_account_id = p_account_id and is_send_enabled;

  update whatsapp_ordering_private.whatsapp_order_flow_bindings_v1
  set is_send_enabled = true, updated_at = now()
  where id = p_binding_id
    and whatsapp_account_id = p_account_id
    and is_verified
    and upper(flow_status) = 'PUBLISHED'
    and verified_at is not null
  returning id into v_updated;
  return jsonb_build_object('ok', true, 'binding_id', v_updated, 'is_send_enabled', true);
end;
$function$
;

-- function: admin_whatsapp_flow_binding_upsert_v1(p_account_id uuid, p_actor_id uuid, p_meta_flow_id text, p_flow_json_version text, p_data_api_version text, p_flow_message_version text, p_flow_status text, p_flow_cta text, p_body_text text)
CREATE OR REPLACE FUNCTION public.admin_whatsapp_flow_binding_upsert_v1(p_account_id uuid, p_actor_id uuid, p_meta_flow_id text, p_flow_json_version text, p_data_api_version text, p_flow_message_version text, p_flow_status text, p_flow_cta text, p_body_text text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_key_status text;
  v_binding_id uuid;
begin
  select k.key_status into v_key_status
  from whatsapp_ordering_private.whatsapp_flow_keyring_v1 k
  join public.whatsapp_accounts a on a.id = k.whatsapp_account_id
  where k.whatsapp_account_id = p_account_id
    and a.slug in ('dona-antonia-0975', 'dona-antonia-1018')
    and a.is_active;
  if v_key_status is distinct from 'ready' then
    return jsonb_build_object('ok', false, 'error', 'flow_key_not_ready');
  end if;
  if p_meta_flow_id is null
     or p_flow_json_version is null
     or p_data_api_version is null
     or p_flow_message_version is null
     or p_flow_status is null
     or p_flow_cta is null
     or p_body_text is null
     or p_meta_flow_id !~ '^[0-9]{6,32}$'
     or p_flow_json_version <> '7.3'
     or p_data_api_version <> '3.0'
     or p_flow_message_version <> '3'
     or upper(p_flow_status) <> 'PUBLISHED'
     or length(btrim(p_flow_cta)) not between 1 and 20
     or length(btrim(p_body_text)) not between 1 and 1024 then
    return jsonb_build_object('ok', false, 'error', 'flow_binding_invalid');
  end if;

  insert into whatsapp_ordering_private.whatsapp_order_flow_bindings_v1 (
    whatsapp_account_id, meta_flow_id, flow_json_version,
    data_api_version, flow_message_version, flow_action, flow_status,
    flow_cta, body_text, is_verified, is_send_enabled, verified_at, verified_by
  ) values (
    p_account_id, p_meta_flow_id, p_flow_json_version,
    p_data_api_version, p_flow_message_version, 'data_exchange', 'PUBLISHED',
    btrim(p_flow_cta), btrim(p_body_text), true, false, now(), p_actor_id
  )
  on conflict (whatsapp_account_id, meta_flow_id, flow_json_version)
  do update set
    data_api_version = excluded.data_api_version,
    flow_message_version = excluded.flow_message_version,
    flow_status = excluded.flow_status,
    flow_cta = excluded.flow_cta,
    body_text = excluded.body_text,
    is_verified = true,
    verified_at = now(),
    verified_by = excluded.verified_by,
    updated_at = now()
  returning id into v_binding_id;

  return jsonb_build_object('ok', true, 'binding_id', v_binding_id, 'is_send_enabled', false);
end;
$function$
;

-- function: admin_whatsapp_flow_key_candidate_resolve_v1(p_account_id uuid)
CREATE OR REPLACE FUNCTION public.admin_whatsapp_flow_key_candidate_resolve_v1(p_account_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_secret_name text;
  v_private_key text;
begin
  select k.vault_secret_name into v_secret_name
  from whatsapp_ordering_private.whatsapp_flow_keyring_v1 k
  join public.whatsapp_accounts a on a.id = k.whatsapp_account_id
  where k.whatsapp_account_id = p_account_id
    and a.slug in ('dona-antonia-0975', 'dona-antonia-1018')
    and a.phone_number_id = k.meta_phone_number_id
    and a.is_active
    and k.key_status <> 'disabled';
  if not found then
    return jsonb_build_object('ok', false, 'error', 'keyring_not_found');
  end if;

  select s.decrypted_secret into v_private_key
  from vault.decrypted_secrets s
  where s.name = v_secret_name
  order by s.updated_at desc
  limit 1;
  if v_private_key is null then
    return jsonb_build_object('ok', false, 'error', 'key_not_present');
  end if;

  return jsonb_build_object('ok', true, 'private_key_pkcs8', v_private_key);
end;
$function$
;

-- function: admin_whatsapp_flow_key_mark_ready_v1(p_account_id uuid, p_private_key_sha256 text, p_meta_public_key_fingerprint text)
CREATE OR REPLACE FUNCTION public.admin_whatsapp_flow_key_mark_ready_v1(p_account_id uuid, p_private_key_sha256 text, p_meta_public_key_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_keyring whatsapp_ordering_private.whatsapp_flow_keyring_v1%rowtype;
  v_vault_digest text;
begin
  if p_private_key_sha256 is null
     or p_meta_public_key_fingerprint is null
     or p_private_key_sha256 !~ '^[0-9a-f]{64}$'
     or p_meta_public_key_fingerprint !~ '^[0-9a-f]{64}$' then
    return jsonb_build_object('ok', false, 'error', 'key_fingerprint_invalid');
  end if;

  select k.* into v_keyring
  from whatsapp_ordering_private.whatsapp_flow_keyring_v1 k
  join public.whatsapp_accounts a on a.id = k.whatsapp_account_id
  where k.whatsapp_account_id = p_account_id
    and a.slug in ('dona-antonia-0975', 'dona-antonia-1018')
    and a.phone_number_id = k.meta_phone_number_id
    and a.is_active
  for update of k;
  if not found or v_keyring.key_status = 'disabled' then
    return jsonb_build_object('ok', false, 'error', 'keyring_not_found');
  end if;

  select encode(extensions.digest(s.decrypted_secret, 'sha256'), 'hex')
  into v_vault_digest
  from vault.decrypted_secrets s
  where s.name = v_keyring.vault_secret_name
  order by s.updated_at desc
  limit 1;
  if v_vault_digest is null or v_vault_digest <> p_private_key_sha256
     or v_keyring.private_key_sha256 <> p_private_key_sha256 then
    return jsonb_build_object('ok', false, 'error', 'key_fingerprint_mismatch');
  end if;

  update whatsapp_ordering_private.whatsapp_flow_keyring_v1
  set key_status = 'ready',
      meta_public_key_fingerprint = p_meta_public_key_fingerprint,
      verified_at = now(),
      updated_at = now()
  where whatsapp_account_id = p_account_id;
  return jsonb_build_object('ok', true, 'key_status', 'ready');
end;
$function$
;

-- function: admin_whatsapp_flow_key_store_v1(p_account_id uuid, p_private_key_pkcs8 text, p_private_key_sha256 text)
CREATE OR REPLACE FUNCTION public.admin_whatsapp_flow_key_store_v1(p_account_id uuid, p_private_key_pkcs8 text, p_private_key_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_keyring whatsapp_ordering_private.whatsapp_flow_keyring_v1%rowtype;
  v_existing text;
  v_digest text;
begin
  if p_private_key_pkcs8 is null
     or length(p_private_key_pkcs8) > 16000
     or p_private_key_pkcs8 not like '%-----BEGIN PRIVATE KEY-----%'
     or p_private_key_pkcs8 not like '%-----END PRIVATE KEY-----%'
     or p_private_key_sha256 is null
     or p_private_key_sha256 !~ '^[0-9a-f]{64}$' then
    return jsonb_build_object('ok', false, 'error', 'key_material_invalid');
  end if;
  v_digest := encode(extensions.digest(p_private_key_pkcs8, 'sha256'), 'hex');
  if v_digest <> p_private_key_sha256 then
    return jsonb_build_object('ok', false, 'error', 'key_fingerprint_mismatch');
  end if;

  select k.* into v_keyring
  from whatsapp_ordering_private.whatsapp_flow_keyring_v1 k
  join public.whatsapp_accounts a on a.id = k.whatsapp_account_id
  where k.whatsapp_account_id = p_account_id
    and a.slug in ('dona-antonia-0975', 'dona-antonia-1018')
    and a.phone_number_id = k.meta_phone_number_id
    and a.is_active
  for update of k;
  if not found or v_keyring.key_status = 'disabled' then
    return jsonb_build_object('ok', false, 'error', 'keyring_not_found');
  end if;

  select s.decrypted_secret into v_existing
  from vault.decrypted_secrets s
  where s.name = v_keyring.vault_secret_name
  order by s.updated_at desc
  limit 1;

  if v_existing is not null then
    if encode(extensions.digest(v_existing, 'sha256'), 'hex') <> v_digest then
      return jsonb_build_object('ok', false, 'error', 'key_already_exists');
    end if;
    update whatsapp_ordering_private.whatsapp_flow_keyring_v1
    set private_key_sha256 = v_digest,
        key_status = case when key_status = 'pending_key_provisioning'
          then 'pending_meta_verification' else key_status end,
        updated_at = now()
    where whatsapp_account_id = p_account_id;
    return jsonb_build_object('ok', true, 'stored', false, 'key_status', 'pending_meta_verification');
  end if;

  if v_keyring.key_status <> 'pending_key_provisioning' then
    return jsonb_build_object('ok', false, 'error', 'key_provisioning_not_allowed');
  end if;

  perform vault.create_secret(
    p_private_key_pkcs8,
    v_keyring.vault_secret_name,
    'WhatsApp Flow private key for ' || p_account_id::text
  );
  update whatsapp_ordering_private.whatsapp_flow_keyring_v1
  set private_key_sha256 = v_digest,
      meta_public_key_fingerprint = null,
      verified_at = null,
      key_status = 'pending_meta_verification',
      updated_at = now()
  where whatsapp_account_id = p_account_id;

  return jsonb_build_object('ok', true, 'stored', true, 'key_status', 'pending_meta_verification');
end;
$function$
;

-- function: admin_whatsapp_flow_setup_snapshot_v1(p_account_id uuid)
CREATE OR REPLACE FUNCTION public.admin_whatsapp_flow_setup_snapshot_v1(p_account_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_account public.whatsapp_accounts%rowtype;
  v_keyring whatsapp_ordering_private.whatsapp_flow_keyring_v1%rowtype;
  v_vault_present boolean := false;
  v_bindings jsonb;
begin
  select * into v_account
  from public.whatsapp_accounts a
  where a.id = p_account_id
    and a.slug in ('dona-antonia-0975', 'dona-antonia-1018')
    and a.is_active;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'account_not_found');
  end if;

  select k.* into v_keyring
  from whatsapp_ordering_private.whatsapp_flow_keyring_v1 k
  where k.whatsapp_account_id = v_account.id
    and k.meta_phone_number_id = v_account.phone_number_id;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'keyring_not_found');
  end if;

  select exists (
    select 1 from vault.decrypted_secrets s
    where s.name = v_keyring.vault_secret_name
      and s.decrypted_secret is not null
  ) into v_vault_present;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', b.id,
    'meta_flow_id', b.meta_flow_id,
    'flow_json_version', b.flow_json_version,
    'data_api_version', b.data_api_version,
    'flow_message_version', b.flow_message_version,
    'flow_status', b.flow_status,
    'flow_cta', b.flow_cta,
    'body_text', b.body_text,
    'is_verified', b.is_verified,
    'is_send_enabled', b.is_send_enabled,
    'verified_at', b.verified_at
  ) order by b.updated_at desc), '[]'::jsonb)
  into v_bindings
  from whatsapp_ordering_private.whatsapp_order_flow_bindings_v1 b
  where b.whatsapp_account_id = v_account.id;

  return jsonb_build_object(
    'ok', true,
    'account_id', v_account.id,
    'account_slug', v_account.slug,
    'key_status', v_keyring.key_status,
    'vault_secret_present', v_vault_present,
    'private_key_sha256', v_keyring.private_key_sha256,
    'meta_public_key_fingerprint', v_keyring.meta_public_key_fingerprint,
    'verified_at', v_keyring.verified_at,
    'bindings', v_bindings
  );
end;
$function$
;

-- function: apply_basket_cart_selection_v2(p_cart_id uuid, p_basket_id uuid, p_selection jsonb)
CREATE OR REPLACE FUNCTION public.apply_basket_cart_selection_v2(p_cart_id uuid, p_basket_id uuid, p_selection jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_cart public.carts%rowtype;
  v_validated jsonb;
  v_expected integer;
  v_updated integer;
  v_recalc jsonb;
begin
  select * into v_cart
  from public.carts
  where id=p_cart_id
  for update;
  if not found then raise exception 'cart_not_found'; end if;
  if v_cart.status<>'draft' then raise exception 'cart_not_editable'; end if;
  if v_cart.basket_id is distinct from p_basket_id then raise exception 'basket_cart_mismatch'; end if;

  v_validated:=public.validate_basket_flow_selection_v1(p_basket_id,coalesce(p_selection,'[]'::jsonb));
  if not coalesce((v_validated->>'valid')::boolean,false) then raise exception 'basket_selection_invalid'; end if;
  v_expected:=jsonb_array_length(v_validated->'normalized');

  with sel as (
    select (x->>'product_id')::uuid as product_id,
           (x->>'quantity')::numeric as quantity
    from jsonb_array_elements(v_validated->'normalized') x
  ), priced as (
    select ci.id,
           s.quantity as new_quantity,
           case
             when s.quantity < bi.quantity then
               abs(s.quantity-bi.quantity) * coalesce(bi.remove_unit_delta, case when coalesce(p.price,0)>0 then -p.price end)
             when s.quantity > bi.quantity then
               (s.quantity-bi.quantity) * coalesce(bi.add_unit_delta, case when coalesce(p.price,0)>0 then p.price end)
             else 0::numeric
           end as new_delta
    from public.cart_items ci
    join sel s on s.product_id=ci.product_id
    join public.basket_template_items bi on bi.basket_id=p_basket_id and bi.product_id=ci.product_id
    join public.products p on p.id=ci.product_id
    where ci.cart_id=p_cart_id and ci.source in ('basket','substitution')
  )
  update public.cart_items ci
     set quantity=priced.new_quantity,
         commercial_delta=priced.new_delta,
         updated_at=now()
    from priced
   where ci.id=priced.id;
  get diagnostics v_updated=row_count;
  if v_updated<>v_expected then raise exception 'basket_selection_cart_mismatch'; end if;

  v_recalc:=public.recalculate_cart(p_cart_id);
  return v_recalc || jsonb_build_object(
    'selection',v_validated->'normalized',
    'updated_components',v_updated,
    'recalculation_count',1,
    'apply_mode','bulk_single_recalc'
  );
end;
$function$
;

-- function: apply_bling_stock_mirror_event_v2(p_product_id uuid, p_bling_product_id bigint, p_physical_total numeric, p_virtual_total numeric, p_deposit_balances jsonb, p_observed_at timestamp with time zone, p_source_event_id text, p_source_resource text, p_replace_deposits boolean)
CREATE OR REPLACE FUNCTION public.apply_bling_stock_mirror_event_v2(p_product_id uuid, p_bling_product_id bigint, p_physical_total numeric, p_virtual_total numeric, p_deposit_balances jsonb, p_observed_at timestamp with time zone, p_source_event_id text, p_source_resource text, p_replace_deposits boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_resource text := lower(trim(coalesce(p_source_resource,'')));
  v_observed_at timestamptz := coalesce(p_observed_at,now());
  v_event_id text := nullif(left(trim(coalesce(p_source_event_id,'')),200),'');
  v_deposits jsonb := coalesce(p_deposit_balances,'{}'::jsonb);
  v_row public.bling_stock_mirror_v2%rowtype;
  v_applied boolean := false;
begin
  if p_product_id is null then
    raise exception 'product_id_required';
  end if;
  if coalesce(p_bling_product_id,0) <= 0 then
    raise exception 'bling_product_id_required';
  end if;
  if p_physical_total is null or p_virtual_total is null then
    raise exception 'stock_totals_required';
  end if;
  if v_resource not in ('stock','virtual_stock','backfill') then
    raise exception 'invalid_source_resource';
  end if;
  if jsonb_typeof(v_deposits) <> 'object' then
    raise exception 'deposit_balances_must_be_object';
  end if;

  insert into public.bling_stock_mirror_v2(
    product_id,
    bling_product_id,
    physical_total,
    virtual_total,
    deposit_balances,
    observed_at,
    source_event_id,
    source_resource,
    created_at,
    updated_at
  )
  values(
    p_product_id,
    p_bling_product_id,
    p_physical_total,
    p_virtual_total,
    v_deposits,
    v_observed_at,
    v_event_id,
    v_resource,
    now(),
    now()
  )
  on conflict(product_id) do update
  set bling_product_id = excluded.bling_product_id,
      physical_total = excluded.physical_total,
      virtual_total = excluded.virtual_total,
      deposit_balances = case
        when p_replace_deposits then excluded.deposit_balances
        else coalesce(public.bling_stock_mirror_v2.deposit_balances,'{}'::jsonb) || excluded.deposit_balances
      end,
      observed_at = excluded.observed_at,
      source_event_id = excluded.source_event_id,
      source_resource = excluded.source_resource,
      updated_at = now()
  where excluded.observed_at >= public.bling_stock_mirror_v2.observed_at
  returning * into v_row;

  if found then
    v_applied := true;
  else
    select *
      into v_row
      from public.bling_stock_mirror_v2
     where product_id = p_product_id;
  end if;

  return jsonb_build_object(
    'applied',v_applied,
    'stale_ignored',not v_applied,
    'product_id',v_row.product_id,
    'bling_product_id',v_row.bling_product_id,
    'physical_total',v_row.physical_total,
    'virtual_total',v_row.virtual_total,
    'deposit_balances',v_row.deposit_balances,
    'observed_at',v_row.observed_at,
    'source_event_id',v_row.source_event_id,
    'source_resource',v_row.source_resource
  );
end
$function$
;

-- function: apply_product_fiscal_strict_validation_v1()
CREATE OR REPLACE FUNCTION public.apply_product_fiscal_strict_validation_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_evidence integer:=0;
  v_profiles integer:=0;
begin
  insert into public.product_fiscal_evidence(
    evidence_key,
    product_id,
    evidence_type,
    source_name,
    source_url,
    gtin,
    ncm,
    cest,
    origin_code,
    fiscal_description,
    evidence_confidence,
    observed_at,
    evidence_payload
  )
  select
    'official_mt_rule:'||v.rule_id::text||':'||v.product_id::text,
    v.product_id,
    'official_mt_legal_rule',
    'SEFAZ-MT - RICMS/MT Anexo X',
    v.source_url,
    regexp_replace(coalesce(v.gtin,''),'\D','','g'),
    v.ncm,
    v.rule_cest,
    v.origin_code,
    v.name,
    0.9900,
    now(),
    jsonb_build_object(
      'rule_id',v.rule_id,
      'rule_version',v.rule_version,
      'segment_code',v.segment_code,
      'segment_name',v.segment_name,
      'legal_description',v.legal_description,
      'validation_policy','strict_auto_r0_10',
      'category',v.category,
      'bling_evidence_count',v.bling_evidence_count,
      'supplier_xml_cest_count',v.supplier_xml_cest_count,
      'external_write',false
    )
  from public.product_fiscal_strict_validation_preview_v1 v
  where v.validation_eligible
  on conflict (evidence_key) do update set
    source_url=excluded.source_url,
    ncm=excluded.ncm,
    cest=excluded.cest,
    origin_code=excluded.origin_code,
    fiscal_description=excluded.fiscal_description,
    evidence_confidence=excluded.evidence_confidence,
    observed_at=excluded.observed_at,
    evidence_payload=excluded.evidence_payload;
  get diagnostics v_evidence=row_count;

  with eligible as (
    select *
    from public.product_fiscal_strict_validation_preview_v1
    where validation_eligible
  ),
  upd as (
    update public.product_fiscal_profiles pf
       set cest=e.rule_cest,
           st_status='applicable',
           matched_st_rule_id=e.rule_id,
           tax_segment_code=e.segment_code,
           tax_segment_name=e.segment_name,
           fiscal_description=coalesce(nullif(pf.fiscal_description,''),e.name),
           classification_source='official_mt_rule+bling_ncm+origin_consensus',
           classification_confidence=0.9900,
           review_status='auto_validated',
           validated_at=now(),
           rule_version=e.rule_version,
           metadata=coalesce(pf.metadata,'{}'::jsonb) || jsonb_build_object(
             'strict_validation_policy','r0_10',
             'strict_validation_at',now(),
             'strict_validation_rule_id',e.rule_id,
             'strict_validation_source_url',e.source_url
           ),
           updated_at=now()
      from eligible e
     where pf.product_id=e.product_id
       and pf.review_status not in ('blocked','human_validated')
    returning pf.product_id
  )
  select count(*) into v_profiles from upd;

  return jsonb_build_object(
    'ok',true,
    'evidence_rows_upserted',v_evidence,
    'profiles_auto_validated',v_profiles,
    'external_write',false,
    'bling_mutations',0
  );
end;
$function$
;

-- function: apply_purchase_stock_receipt_v1(p_document_id uuid, p_user_id uuid)
CREATE OR REPLACE FUNCTION public.apply_purchase_stock_receipt_v1(p_document_id uuid, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_doc public.purchase_xml_documents%rowtype; v_receipt public.purchase_stock_receipts%rowtype; v_item record; v_count integer:=0; v_total_qty numeric:=0; v_now timestamptz:=now(); v_authority text;
begin
 if p_document_id is null then raise exception 'document_id_required'; end if;
 select * into v_doc from public.purchase_xml_documents where id=p_document_id for update; if not found then raise exception 'purchase_document_not_found'; end if;
 select coalesce(metadata->>'ops2_stock_authority','legacy_shadow') into v_authority from public.bling_hub_runtime_v2 where id=1;
 if v_authority='bling' then
  insert into public.bling_hub_audit_v2(event_type,severity,domain,source_system,source_id,details) values('purchase_stock_receipt_blocked_bling_authority','warning','stock','canonical',p_document_id,jsonb_build_object('document_key',v_doc.document_key,'stock_authority',v_authority,'local_stock_applied',false,'make_used',false));
  return jsonb_build_object('ok',false,'error','bling_stock_authority_requires_erp_receipt','document_id',p_document_id,'stock_authority',v_authority,'local_stock_applied',false);
 end if;
 select * into v_receipt from public.purchase_stock_receipts where document_id=p_document_id for update;
 if found and v_receipt.status='applied' then return jsonb_build_object('ok',true,'idempotent_replay',true,'receipt_id',v_receipt.id,'document_id',p_document_id,'applied_at',v_receipt.applied_at); end if;
 if v_doc.processing_status<>'processed' then raise exception 'purchase_document_not_ready:%',v_doc.processing_status; end if;
 if not exists(select 1 from public.purchase_xml_items i where i.document_id=p_document_id and i.stock_update_requested is true) then raise exception 'no_stock_items_selected'; end if;
 if exists(select 1 from public.purchase_xml_items i where i.document_id=p_document_id and i.stock_update_requested is true and (i.product_id is null or i.conversion_status='review_required' or i.processing_status in ('review_required','failed','pending') or i.converted_quantity is null or i.converted_quantity<=0)) then raise exception 'purchase_items_require_review'; end if;
 insert into public.purchase_stock_receipts(document_id,status,confirmed_by,confirmed_at,idempotency_key,updated_at) values(p_document_id,'confirmed',p_user_id,v_now,'purchase-stock:'||p_document_id::text,v_now)
 on conflict(document_id) do update set status=case when public.purchase_stock_receipts.status='applied' then 'applied' else 'confirmed' end,confirmed_by=coalesce(public.purchase_stock_receipts.confirmed_by,excluded.confirmed_by),confirmed_at=coalesce(public.purchase_stock_receipts.confirmed_at,excluded.confirmed_at),updated_at=v_now returning * into v_receipt;
 if v_receipt.status='applied' then return jsonb_build_object('ok',true,'idempotent_replay',true,'receipt_id',v_receipt.id,'document_id',p_document_id,'applied_at',v_receipt.applied_at); end if;
 for v_item in select i.id,i.product_id,i.converted_quantity,i.base_unit,i.description from public.purchase_xml_items i where i.document_id=p_document_id and i.stock_update_requested is true order by i.item_number for update loop
  update public.products set stock=coalesce(stock,0)+v_item.converted_quantity,updated_at=v_now where id=v_item.product_id; if not found then raise exception 'product_not_found:%',v_item.product_id; end if; v_count:=v_count+1; v_total_qty:=v_total_qty+v_item.converted_quantity;
 end loop;
 update public.purchase_stock_receipts set status='applied',applied_at=v_now,result=jsonb_build_object('items_applied',v_count,'base_quantity_total',v_total_qty,'document_key',v_doc.document_key),updated_at=v_now where id=v_receipt.id;
 update public.purchase_xml_documents set receipt_status='received',updated_at=v_now where id=p_document_id;
 insert into public.bling_hub_audit_v2(event_type,severity,domain,source_system,source_id,details) values('purchase_stock_receipt_applied','info','stock','canonical',p_document_id,jsonb_build_object('document_key',v_doc.document_key,'items_applied',v_count,'base_quantity_total',v_total_qty,'confirmed_by',p_user_id,'make_used',false));
 return jsonb_build_object('ok',true,'idempotent_replay',false,'receipt_id',v_receipt.id,'document_id',p_document_id,'items_applied',v_count,'base_quantity_total',v_total_qty,'applied_at',v_now);
end $function$
;

-- function: basket_auto_norm_text_v1(p_value text)
CREATE OR REPLACE FUNCTION public.basket_auto_norm_text_v1(p_value text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select lower(translate(coalesce(p_value,''),'áàãâäéèêëíìîïóòõôöúùûüçÁÀÃÂÄÉÈÊËÍÌÎÏÓÒÕÔÖÚÙÛÜÇ','aaaaaeeeeiiiiooooouuuucAAAAAEEEEIIIIOOOOOUUUUC'));
$function$
;

-- function: basket_component_fresh_sellable_stock_v1(p_product_id uuid)
CREATE OR REPLACE FUNCTION public.basket_component_fresh_sellable_stock_v1(p_product_id uuid)
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select greatest(0,coalesce(s.loose_sellable_stock,0))::numeric
  from public.ops2_loose_sellable_stock_v1 s
  where s.product_id=p_product_id;
$function$
;

-- function: basket_mold_cutover_ready_v1(p_basket_id uuid)
CREATE OR REPLACE FUNCTION public.basket_mold_cutover_ready_v1(p_basket_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  -- Checkout hotfix: mold cards already published by the storefront must remain
  -- purchasable. Stock validation/reservation is still enforced transactionally
  -- by create_vitrine_cart_order_v3_base/reserve_vitrine_order_stock_v1.
  select exists (
    select 1
    from public.basket_molds bm
    join public.basket_templates bt on bt.id = bm.basket_id
    where bm.basket_id = p_basket_id
      and bt.is_active = true
  );
$function$
;

-- function: basket_mold_editor_v1(p_basket_id uuid)
CREATE OR REPLACE FUNCTION public.basket_mold_editor_v1(p_basket_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select jsonb_build_object(
    'basket_id', b.id,
    'basket_name', b.name,
    'basket_image_url', b.image_url,
    'mold_id', m.id,
    'hidden_adjustment', coalesce(m.hidden_adjustment, 0),
    'conditional_hidden_enabled', coalesce(m.conditional_hidden_enabled, false),
    'conditional_hidden_product_id', m.conditional_hidden_product_id,
    'conditional_hidden_adjustment', coalesce(m.conditional_hidden_adjustment, 0),
    'conditional_hidden_product',
      case when cp.id is null then null else jsonb_build_object(
        'product_id', cp.id,
        'name', cp.name,
        'sku', cp.sku,
        'gtin', cp.gtin,
        'image_url', cp.image_url,
        'packaging', cp.packaging,
        'is_active', cp.is_active
      ) end,
    'public_composition_count', coalesce(m.public_composition_count, 2),
    'metadata', coalesce(m.metadata, '{}'::jsonb),
    'positions', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'position_id', pos.id,
          'label', pos.label,
          'quantity', pos.quantity,
          'sort_order', pos.sort_order,
          'metadata', pos.metadata,
          'options', coalesce((
            select jsonb_agg(
              jsonb_build_object(
                'option_id', opt.id,
                'product_id', p.id,
                'name', p.name,
                'sku', p.sku,
                'gtin', p.gtin,
                'image_url', p.image_url,
                'is_active', p.is_active,
                'sort_order', opt.sort_order,
                'metadata', opt.metadata
              ) order by opt.sort_order, opt.id
            )
            from public.basket_mold_position_options opt
            join public.products p on p.id = opt.product_id
            where opt.position_id = pos.id
          ), '[]'::jsonb)
        ) order by pos.sort_order, pos.id
      )
      from public.basket_mold_positions pos
      where pos.mold_id = m.id
    ), '[]'::jsonb)
  )
  from public.basket_templates b
  left join public.basket_molds m on m.basket_id = b.id
  left join public.products cp on cp.id = m.conditional_hidden_product_id
  where b.id = p_basket_id;
$function$
;

-- function: basket_mold_manual_replacement_review_v1(p_basket_ids uuid[])
CREATE OR REPLACE FUNCTION public.basket_mold_manual_replacement_review_v1(p_basket_ids uuid[])
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
WITH positions AS (
  SELECT
    basket.id AS basket_id,
    basket.name AS basket_name,
    position.id AS position_id,
    position.label,
    position.sort_order AS position_order,
    position.quantity,
    option_row.product_id,
    option_row.sort_order AS option_order,
    coalesce(option_row.metadata, '{}'::jsonb) AS option_metadata,
    product.is_active,
    product.is_whatsapp_active,
    greatest(0, coalesce(product.stock, 0)
      - public.supabase_stock_pending_reservations_v1(product.id, NULL::uuid)) AS available_stock,
    count(*) OVER (PARTITION BY position.id)::integer AS option_count
  FROM public.basket_templates basket
  JOIN public.basket_categories category
    ON category.id = basket.category_id
   AND category.slug = 'cestas-completas'
  JOIN public.basket_molds mold ON mold.basket_id = basket.id
  JOIN public.basket_mold_positions position ON position.mold_id = mold.id
  JOIN public.basket_mold_position_options option_row ON option_row.position_id = position.id
  JOIN public.products product ON product.id = option_row.product_id
  WHERE basket.is_active IS TRUE
    AND (p_basket_ids IS NULL OR basket.id = ANY(p_basket_ids))
), position_state AS (
  SELECT
    position_id,
    bool_or(is_active IS TRUE AND available_stock >= quantity) AS has_available_option
  FROM positions
  GROUP BY position_id
), candidates AS (
  SELECT
    position.*,
    CASE
      WHEN position.option_count = 1
       AND position.is_active IS TRUE
       AND position.is_whatsapp_active IS NOT TRUE
       AND position.available_stock >= position.quantity
       AND position.option_metadata @> '{"manual_replacement_required":true}'::jsonb
        THEN 'only_configured_option_inactive'
      WHEN position.option_count = 1
        THEN 'only_configured_option_unavailable'
      ELSE 'no_sellable_option'
    END AS reason,
    row_number() OVER (
      PARTITION BY position.position_id
      ORDER BY
        CASE WHEN position.option_metadata @> '{"preferred":true}'::jsonb THEN 0 ELSE 1 END,
        position.option_order,
        position.product_id
    ) AS candidate_order
  FROM positions position
  JOIN position_state state ON state.position_id = position.position_id
  WHERE state.has_available_option IS NOT TRUE
     OR (
       position.option_count = 1
       AND position.is_active IS TRUE
       AND position.is_whatsapp_active IS NOT TRUE
       AND position.available_stock >= position.quantity
       AND position.option_metadata @> '{"manual_replacement_required":true}'::jsonb
     )
)
SELECT coalesce(jsonb_agg(jsonb_build_object(
  'basket_id', basket_id,
  'basket_name', basket_name,
  'position_id', position_id,
  'position_label', label,
  'product_id', product_id,
  'reason', reason
) ORDER BY basket_name, position_order, product_id), '[]'::jsonb)
FROM candidates
WHERE candidate_order = 1;
$function$
;

-- function: basket_mold_public_compositions_batch_v1(p_basket_ids uuid[])
CREATE OR REPLACE FUNCTION public.basket_mold_public_compositions_batch_v1(p_basket_ids uuid[])
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
WITH requested AS (
  SELECT DISTINCT unnest(coalesce(p_basket_ids, '{}'::uuid[])) AS basket_id
), mold AS (
  SELECT m.id,m.basket_id,m.hidden_adjustment,m.public_composition_count,b.name,b.image_url
  FROM public.basket_molds m
  JOIN public.basket_templates b ON b.id=m.basket_id
  JOIN public.basket_categories cat ON cat.id=b.category_id AND cat.slug='cestas-completas'
  JOIN requested r ON r.basket_id=m.basket_id
), active_order_reservations AS (
  SELECT r.product_id,
         public.supabase_stock_pending_reservations_v1(r.product_id,NULL::uuid)::numeric AS reserved
  FROM public.vitrine_stock_reservations r
  WHERE r.status IN ('reserved','allocated') OR r.status='consumed'
  GROUP BY r.product_id
), stock_candidates AS (
  SELECT DISTINCT option_row.product_id
  FROM mold m
  JOIN public.basket_mold_positions position ON position.mold_id=m.id
  JOIN public.basket_mold_position_options option_row ON option_row.position_id=position.id
), fresh_stock AS MATERIALIZED (
  SELECT candidate.product_id,
         public.basket_component_fresh_sellable_stock_v1(candidate.product_id) AS sellable_stock
  FROM stock_candidates candidate
), configured AS (
  SELECT position.id AS position_id,position.mold_id,m.basket_id,position.label,
         position.sort_order AS position_order,option_row.product_id,option_row.sort_order AS option_order,
         product.name AS product_name,product.sku,product.gtin,product.image_url,
         CASE WHEN product.is_offer IS TRUE AND product.offer_price>0 THEN product.offer_price
              WHEN product.price>0 THEN product.price ELSE 9999999 END AS unit_price,
         CASE WHEN option_row.metadata ? 'base_quantity'
              THEN greatest(0,coalesce(nullif(option_row.metadata->>'base_quantity','')::numeric,0))
              WHEN option_row.sort_order=0 THEN greatest(0,position.quantity)
              ELSE 0 END AS base_quantity,
         greatest(0,stock.sellable_stock-coalesce(reservation.reserved,0))::numeric AS available_stock,
         product.is_active
  FROM mold m
  JOIN public.basket_mold_positions position ON position.mold_id=m.id
  JOIN public.basket_mold_position_options option_row ON option_row.position_id=position.id
  JOIN public.products product ON product.id=option_row.product_id
  JOIN fresh_stock stock ON stock.product_id=product.id
  LEFT JOIN active_order_reservations reservation ON reservation.product_id=product.id
), selected AS (
  SELECT configured.*,
         CASE WHEN is_active IS TRUE
              THEN least(base_quantity,available_stock)
              ELSE 0 END AS quantity
  FROM configured
), slots AS (
  SELECT m.basket_id,series.composition_number
  FROM mold m
  CROSS JOIN LATERAL generate_series(1,greatest(1,coalesce(m.public_composition_count,1))) AS series(composition_number)
), compositions AS (
  SELECT slot.basket_id,slot.composition_number,
         coalesce(jsonb_agg(jsonb_build_object(
           'position_id',selected.position_id,'label',selected.label,
           'quantity',selected.quantity,'product_id',selected.product_id,
           'name',selected.product_name,'sku',selected.sku,'gtin',selected.gtin,
           'image_url',selected.image_url,'available_stock',selected.available_stock,
           'coverage_baskets',floor(selected.available_stock/nullif(selected.quantity,0))::bigint,
           'option_rank',selected.option_order+1,'selection_score',selected.available_stock,
           'selection_reason','configured_quantity'
         ) ORDER BY selected.position_order,selected.option_order,selected.product_id)
           FILTER (WHERE selected.product_id IS NOT NULL AND selected.quantity>0),'[]'::jsonb) AS items
  FROM slots slot
  LEFT JOIN selected ON selected.basket_id=slot.basket_id
  GROUP BY slot.basket_id,slot.composition_number
)
SELECT coalesce(jsonb_agg(jsonb_build_object(
  'basket_id',m.basket_id,'name',m.name,'image_url',m.image_url,
  'hidden_adjustment',m.hidden_adjustment,
  'public_composition_count',greatest(1,coalesce(m.public_composition_count,1)),
  'balancing','configured_quantities_v1',
  'compositions',coalesce((
    SELECT jsonb_agg(jsonb_build_object('number',c.composition_number,'items',c.items)
      ORDER BY c.composition_number)
    FROM compositions c WHERE c.basket_id=m.basket_id
  ),'[]'::jsonb)
) ORDER BY m.basket_id),'[]'::jsonb)
FROM mold m;
$function$
;

-- function: basket_mold_public_compositions_v1(p_basket_id uuid)
CREATE OR REPLACE FUNCTION public.basket_mold_public_compositions_v1(p_basket_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select public.basket_mold_public_compositions_v2(p_basket_id);
$function$
;

-- function: basket_mold_public_compositions_v2(p_basket_id uuid)
CREATE OR REPLACE FUNCTION public.basket_mold_public_compositions_v2(p_basket_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(
    (select result.item from jsonb_array_elements(
      public.basket_mold_public_compositions_batch_v1(array[p_basket_id])
    ) as result(item) where result.item->>'basket_id' = p_basket_id::text),
    jsonb_build_object('basket_id', p_basket_id, 'error', 'basket_mold_not_found')
  );
$function$
;

-- function: basket_package_compatible_v1(p_original_packaging text, p_original_name text, p_candidate_packaging text, p_candidate_name text)
CREATE OR REPLACE FUNCTION public.basket_package_compatible_v1(p_original_packaging text, p_original_name text, p_candidate_packaging text, p_candidate_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  a text:=lower(coalesce(p_original_packaging,'')||' '||coalesce(p_original_name,''));
  b text:=lower(coalesce(p_candidate_packaging,'')||' '||coalesce(p_candidate_name,''));
  ma text[];mb text[];va numeric;vb numeric;ua text;ub text;da text;db text;
begin
  ma:=regexp_match(a,'([0-9]+([.,][0-9]+)?)\s*(kg|g|ml|l)([^a-z]|$)');
  mb:=regexp_match(b,'([0-9]+([.,][0-9]+)?)\s*(kg|g|ml|l)([^a-z]|$)');
  if ma is null or mb is null then return public.basket_auto_norm_text_v1(p_original_packaging)=public.basket_auto_norm_text_v1(p_candidate_packaging); end if;
  va:=replace(ma[1],',','.')::numeric;vb:=replace(mb[1],',','.')::numeric;ua:=ma[3];ub:=mb[3];
  da:=case when ua in ('kg','g') then 'mass' else 'volume' end;db:=case when ub in ('kg','g') then 'mass' else 'volume' end;
  if da<>db then return false; end if;
  if ua='kg' then va:=va*1000; elsif ua='l' then va:=va*1000; end if;
  if ub='kg' then vb:=vb*1000; elsif ub='l' then vb:=vb*1000; end if;
  return vb>=va*0.80 and vb<=va*1.25;
end;$function$
;

-- function: basket_substitution_family_v1(p_name text, p_subcategory text)
CREATE OR REPLACE FUNCTION public.basket_substitution_family_v1(p_name text, p_subcategory text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare n text:=public.basket_auto_norm_text_v1(p_name);s text:=public.basket_auto_norm_text_v1(p_subcategory);
begin
  if s='detergente' or n like '%detergente%' then return 'detergente'; end if;
  if n like '%creme dental%' or n like '%pasta de dente%' then return 'creme_dental'; end if;
  if n like '%molho de tomate%' and n not like '%sardinha%' then return 'molho_tomate'; end if;
  if (n like '%macarrao%' and (n like '%lamen%' or n like '%miojo%' or n like '%instantaneo%')) or n like '%miojo%' or n like '%lamen%' then return 'miojo'; end if;
  if n like '%macarrao%' and n not like '%molho%' and n not like '%sopao%' then return 'macarrao'; end if;
  if s like '%suco em po%' or n like '%suco em po%' then return 'suco'; end if;
  if n like '%milho verde%' and n not like '%amido%' and n not like '%pipoca%' then return 'milho'; end if;
  if n like '%sabonete%' and n not like '%saboneteira%' then return 'sabonete'; end if;
  if n like '%farinha de trigo%' then return 'trigo'; end if;
  if n like '%biscoito%' or n like '%bolacha%' or n like '%rosquinha%' then return 'bolacha'; end if;
  return null;
end;$function$
;

-- function: bind_bling_contact_id(p_customer_id uuid, p_bling_contact_id bigint)
CREATE OR REPLACE FUNCTION public.bind_bling_contact_id(p_customer_id uuid, p_bling_contact_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_customer_id is null or p_bling_contact_id is null or p_bling_contact_id<=0 then raise exception 'invalid_bling_contact_binding'; end if;
  if exists(select 1 from public.customers where bling_contact_id=p_bling_contact_id and id<>p_customer_id) then raise exception 'bling_contact_already_bound'; end if;
  update public.customers set bling_contact_id=p_bling_contact_id,last_bling_sync_at=now(),updated_at=now() where id=p_customer_id;
  if not found then raise exception 'customer_not_found'; end if;
  return jsonb_build_object('customer_id',p_customer_id,'bling_contact_id',p_bling_contact_id);
end;
$function$
;

-- function: bind_bling_product_id(p_product_id uuid, p_bling_product_id bigint)
CREATE OR REPLACE FUNCTION public.bind_bling_product_id(p_product_id uuid, p_bling_product_id bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_product_id is null or p_bling_product_id is null then raise exception 'ids_required'; end if;
  update public.products
     set bling_product_id = p_bling_product_id,
         updated_at = now()
   where id = p_product_id;
  return found;
end;
$function$
;

-- function: bind_bling_product_id_v1(p_product_id uuid, p_bling_product_id bigint, p_source text, p_external_key text)
CREATE OR REPLACE FUNCTION public.bind_bling_product_id_v1(p_product_id uuid, p_bling_product_id bigint, p_source text DEFAULT 'whatsapp_sales_mvp'::text, p_external_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare p public.products%rowtype; begin
  if p_product_id is null or coalesce(p_bling_product_id,0)<=0 then raise exception 'invalid_product_binding'; end if;
  select * into p from public.products where id=p_product_id for update; if not found then raise exception 'product_not_found'; end if;
  if p.bling_product_id is not null and p.bling_product_id<>p_bling_product_id then raise exception 'bling_product_binding_conflict'; end if;
  update public.products set bling_product_id=p_bling_product_id,metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('bling_binding_source',left(coalesce(p_source,'whatsapp_sales_mvp'),80),'bling_binding_at',now()),updated_at=now() where id=p.id;
  insert into public.bling_product_binding_events(product_id,bling_product_id,binding_source,external_key) values(p.id,p_bling_product_id,left(coalesce(p_source,'whatsapp_sales_mvp'),80),left(p_external_key,180));
  return jsonb_build_object('product_id',p.id,'bling_product_id',p_bling_product_id,'source',p_source);
end $function$
;

-- function: bling_hub_customer_creation_guard_v1()
CREATE OR REPLACE FUNCTION public.bling_hub_customer_creation_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_customer record;
  v_reasons text[] := array[]::text[];
begin
  if new.domain <> 'customer'
     or new.operation <> 'sync_customer'
     or new.payload->'allow_create' is distinct from 'true'::jsonb then
    return new;
  end if;

  select c.id,c.name,c.cpf_cnpj,c.primary_whatsapp_e164,c.bling_contact_id
    into v_customer
  from public.customers c
  where c.id::text = new.source_id;

  -- A contact that is already linked in Bling never needs authorization
  -- to create a new contact. Leave the job untouched so normal sync/update
  -- behavior can continue.
  if found and coalesce(v_customer.bling_contact_id,0) > 0 then
    return new;
  end if;

  if not found then
    v_reasons := array_append(v_reasons,'customer_not_found');
  else
    if nullif(btrim(coalesce(v_customer.name,'')),'') is null then
      v_reasons := array_append(v_reasons,'name_required');
    end if;
    if not public.ops2_valid_cpf_cnpj_v1(v_customer.cpf_cnpj) then
      v_reasons := array_append(v_reasons,'valid_document_required');
    end if;
    if public.canonical_whatsapp_e164_br_v2(v_customer.primary_whatsapp_e164) is null then
      v_reasons := array_append(v_reasons,'valid_phone_required');
    end if;
  end if;

  if cardinality(v_reasons) > 0 then
    new.payload := jsonb_set(coalesce(new.payload,'{}'::jsonb),'{allow_create}','false'::jsonb,true);
    new.payload := jsonb_set(
      new.payload,
      '{creation_guard}',
      jsonb_build_object(
        'blocked',true,
        'reasons',to_jsonb(v_reasons),
        'guard','bling_hub_customer_creation_guard_v1',
        'checked_at',to_jsonb(clock_timestamp())
      ),
      true
    );
  else
    new.payload := jsonb_set(
      coalesce(new.payload,'{}'::jsonb),
      '{creation_guard}',
      jsonb_build_object(
        'blocked',false,
        'reasons','[]'::jsonb,
        'guard','bling_hub_customer_creation_guard_v1',
        'checked_at',to_jsonb(clock_timestamp())
      ),
      true
    );
  end if;

  return new;
end;
$function$
;

-- function: bling_hub_readiness_v2()
CREATE OR REPLACE FUNCTION public.bling_hub_readiness_v2()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_runtime public.bling_hub_runtime_v2%rowtype;
  v_creds jsonb;
begin
  select * into v_runtime from public.bling_hub_runtime_v2 where id=1;
  select public.get_bling_api_credentials_v1() into v_creds;
  return jsonb_build_object(
    'mode',v_runtime.mode,
    'hub_enabled',v_runtime.hub_enabled,
    'legacy_queues_frozen',true,
    'domains',jsonb_build_object(
      'products',v_runtime.products_enabled,
      'stock',v_runtime.stock_enabled,
      'customers',v_runtime.customers_enabled,
      'orders',v_runtime.orders_enabled,
      'webhooks',v_runtime.webhooks_enabled,
      'fiscal',v_runtime.fiscal_enabled
    ),
    'credentials',jsonb_build_object(
      'client_id',nullif(v_creds->>'client_id','') is not null,
      'client_secret',nullif(v_creds->>'client_secret','') is not null,
      'refresh_token',nullif(v_creds->>'refresh_token','') is not null,
      'ready',nullif(v_creds->>'client_id','') is not null
        and nullif(v_creds->>'client_secret','') is not null
        and nullif(v_creds->>'refresh_token','') is not null
    ),
    'legacy',jsonb_build_object(
      'bling_commands_pending',0,
      'bling_commands_processing',0,
      'bling_commands_removed',true,
      'order_sync_pending_or_error',0,
      'order_sync_processing',0,
      'order_sync_removed',true,
      'history_staging_removed',true
    ),
    'hub_queue',jsonb_build_object(
      'pending',(select count(*) from public.bling_hub_jobs_v2 where status='pending'),
      'processing',(select count(*) from public.bling_hub_jobs_v2 where status='processing'),
      'review_required',(select count(*) from public.bling_hub_jobs_v2 where status='review_required'),
      'failed',(select count(*) from public.bling_hub_jobs_v2 where status='failed')
    ),
    'last_oauth_check_at',v_runtime.last_oauth_check_at,
    'last_oauth_ok_at',v_runtime.last_oauth_ok_at,
    'last_readonly_check_at',v_runtime.last_readonly_check_at,
    'last_readonly_ok_at',v_runtime.last_readonly_ok_at
  );
end $function$
;

-- function: build_bling_order_draft(p_order_id uuid)
CREATE OR REPLACE FUNCTION public.build_bling_order_draft(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select jsonb_build_object('order_id',o.id,'bling_order_id',o.bling_order_id,'status',o.status,'customer',o.customer_snapshot,'delivery_address',o.delivery_address,
    'items',coalesce((select jsonb_agg(jsonb_build_object('product_id',oi.product_id,'bling_product_id',p.bling_product_id,'sku',oi.sku_snapshot,'name',oi.name_snapshot,'gtin',p.gtin,'ncm',p.ncm,'unit',p.unit,'packaging',p.packaging,'quantity',oi.quantity,'unit_price',oi.unit_price,'line_total',oi.line_total,'catalog_source','counter_verified') order by oi.created_at) from public.order_items oi left join public.products p on p.id=oi.product_id where oi.order_id=o.id),'[]'::jsonb),
    'fiscal_subtotal',o.fiscal_subtotal,'other_expenses',o.other_expenses,'discount',o.discount,'total',o.total,'currency',o.currency,'catalog_source','counter_verified') from public.orders o where o.id=p_order_id
$function$
;

-- function: calculate_basket_hidden_adjustment_v1(p_basket_id uuid)
CREATE OR REPLACE FUNCTION public.calculate_basket_hidden_adjustment_v1(p_basket_id uuid)
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select round(
    coalesce(b.base_price,0)
    - coalesce((
      select sum(bi.quantity*coalesce(p.price,0))
      from public.basket_template_items bi
      join public.products p on p.id=bi.product_id
      where bi.basket_id=b.id
    ),0),
    2
  )
  from public.basket_templates b
  where b.id=p_basket_id;
$function$
;

-- function: canonical_whatsapp_e164_br_v2(p_phone text)
CREATE OR REPLACE FUNCTION public.canonical_whatsapp_e164_br_v2(p_phone text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  d text:=regexp_replace(coalesce(p_phone,''),'[^0-9]','','g');
  base text;
begin
  if left(d,2)='00' then d:=substr(d,3); end if;
  if left(d,2)='55' and length(d) in (12,13) then
    base:=substr(d,3);
  elsif length(d) in (10,11) then
    base:=d;
  else
    return null;
  end if;

  -- Brazilian mobile numbers received by some WhatsApp providers can arrive
  -- without the ninth digit. Restore it only for mobile-looking 8-digit
  -- subscribers (first subscriber digit 6-9); landlines remain unchanged.
  if length(base)=10 and substr(base,3,1) ~ '^[6-9]$' then
    base:=substr(base,1,2)||'9'||substr(base,3);
  end if;

  if length(base) not in (10,11) then return null; end if;
  return '+55'||base;
end;
$function$
;

-- function: capineca_b2b_consume_rate_limit(p_ip_hash text, p_limit integer)
CREATE OR REPLACE FUNCTION public.capineca_b2b_consume_rate_limit(p_ip_hash text, p_limit integer DEFAULT 3)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare current_attempts integer;
begin
  if p_ip_hash is null or length(p_ip_hash) <> 64 or p_limit < 1 or p_limit > 10 then return false; end if;
  insert into public.capineca_b2b_rate_limits (ip_hash, window_started_at, attempts)
  values (p_ip_hash, now(), 1)
  on conflict (ip_hash) do update
  set window_started_at = case when public.capineca_b2b_rate_limits.window_started_at < now() - interval '24 hours' then now() else public.capineca_b2b_rate_limits.window_started_at end,
      attempts = case when public.capineca_b2b_rate_limits.window_started_at < now() - interval '24 hours' then 1 else public.capineca_b2b_rate_limits.attempts + 1 end
  returning attempts into current_attempts;
  return current_attempts <= p_limit;
end;
$function$
;

-- function: capture_inventory_unknown_ean_v1(p_ean text, p_operator_label text, p_source text, p_observed_quantity numeric, p_observed_gondola_number integer)
CREATE OR REPLACE FUNCTION public.capture_inventory_unknown_ean_v1(p_ean text, p_operator_label text DEFAULT NULL::text, p_source text DEFAULT 'quick_balance'::text, p_observed_quantity numeric DEFAULT NULL::numeric, p_observed_gondola_number integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_ean text:=regexp_replace(coalesce(p_ean,''),'[^0-9]','','g');
  v_row public.inventory_unknown_eans%rowtype;
begin
  if length(v_ean)<4 or length(v_ean)>30 then raise exception 'invalid_ean'; end if;
  if exists(select 1 from public.products where gtin=v_ean) then
    raise exception 'ean_already_registered';
  end if;
  if p_observed_quantity is not null and p_observed_quantity<0 then raise exception 'invalid_quantity'; end if;
  if p_observed_gondola_number is not null and (p_observed_gondola_number<1 or p_observed_gondola_number>9999) then
    raise exception 'invalid_gondola';
  end if;

  insert into public.inventory_unknown_eans(
    ean,status,seen_count,first_operator_label,last_operator_label,source,
    observed_quantity,observed_gondola_number
  ) values(
    v_ean,'pending',1,left(nullif(trim(coalesce(p_operator_label,'')),''),80),
    left(nullif(trim(coalesce(p_operator_label,'')),''),80),
    left(coalesce(nullif(trim(p_source),''),'quick_balance'),80),
    p_observed_quantity,p_observed_gondola_number
  )
  on conflict(ean) do update set
    seen_count=public.inventory_unknown_eans.seen_count+1,
    last_seen_at=now(),
    last_operator_label=coalesce(left(nullif(trim(coalesce(p_operator_label,'')),''),80),public.inventory_unknown_eans.last_operator_label),
    source=coalesce(nullif(left(trim(coalesce(p_source,'')),80),''),public.inventory_unknown_eans.source),
    observed_quantity=coalesce(p_observed_quantity,public.inventory_unknown_eans.observed_quantity),
    observed_gondola_number=coalesce(p_observed_gondola_number,public.inventory_unknown_eans.observed_gondola_number),
    status=case when public.inventory_unknown_eans.status in ('registered','ignored') then public.inventory_unknown_eans.status else public.inventory_unknown_eans.status end,
    updated_at=now()
  returning * into v_row;

  return jsonb_build_object(
    'id',v_row.id,'ean',v_row.ean,'status',v_row.status,
    'seen_count',v_row.seen_count,'last_seen_at',v_row.last_seen_at
  );
end;
$function$
;

-- function: capture_whatsapp_location_evidence_v1()
CREATE OR REPLACE FUNCTION public.capture_whatsapp_location_evidence_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  loc jsonb;
  lat numeric;
  lng numeric;
  src text;
begin
  if new.message_type <> 'location' then
    return new;
  end if;

  loc := coalesce(new.metadata -> 'location', '{}'::jsonb);
  if loc = '{}'::jsonb then
    return new;
  end if;

  begin
    lat := nullif(loc ->> 'latitude', '')::numeric;
    lng := nullif(loc ->> 'longitude', '')::numeric;
  exception when others then
    return new;
  end;

  if lat is null or lng is null or lat not between -90 and 90 or lng not between -180 and 180 then
    return new;
  end if;

  src := case
    when new.direction = 'inbound' then 'customer_whatsapp'
    else 'business_whatsapp'
  end;

  insert into public.customer_location_evidence_v1(
    customer_id, conversation_id, whatsapp_message_id,
    source, direction, latitude, longitude,
    label, address_text, confidence, captured_at, metadata
  )
  values (
    new.customer_id, new.conversation_id, new.id,
    src, new.direction, lat, lng,
    nullif(loc ->> 'name', ''),
    nullif(loc ->> 'address', ''),
    'unconfirmed',
    coalesce(new.received_at, new.sent_at, new.created_at, now()),
    jsonb_strip_nulls(jsonb_build_object(
      'provider', new.provider,
      'provider_message_id', new.provider_message_id,
      'location_url', nullif(loc ->> 'url', '')
    ))
  )
  on conflict (whatsapp_message_id) where whatsapp_message_id is not null
  do update set
    customer_id = coalesce(excluded.customer_id, customer_location_evidence_v1.customer_id),
    conversation_id = coalesce(excluded.conversation_id, customer_location_evidence_v1.conversation_id),
    latitude = case when customer_location_evidence_v1.confidence = 'confirmed'
                    then customer_location_evidence_v1.latitude else excluded.latitude end,
    longitude = case when customer_location_evidence_v1.confidence = 'confirmed'
                     then customer_location_evidence_v1.longitude else excluded.longitude end,
    label = coalesce(excluded.label, customer_location_evidence_v1.label),
    address_text = coalesce(excluded.address_text, customer_location_evidence_v1.address_text),
    metadata = customer_location_evidence_v1.metadata || excluded.metadata,
    updated_at = now();

  return new;
end;
$function$
;

-- function: check_order_dispatch_fiscal_gate_v1(p_order_id uuid)
CREATE OR REPLACE FUNCTION public.check_order_dispatch_fiscal_gate_v1(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  cfg public.fiscal_runtime_config%rowtype;
  o public.orders%rowtype;
  c public.order_fiscal_controls%rowtype;
  gate_mode text:='observe';
  authorization_required boolean:=true;
  authorized boolean:=false;
  fiscal_allowed boolean:=true;
  authority text:='legacy_shadow';
  physical_state text:=null;
  physical_allowed boolean:=true;
  allowed boolean:=true;
  reason text:=null;
begin
  select * into o from public.orders where id=p_order_id;
  if not found then return jsonb_build_object('ok',false,'error','order_not_found','allowed',false,'external_side_effect',false); end if;

  select * into cfg from public.fiscal_runtime_config where id=1;
  if found then
    gate_mode:=coalesce(cfg.dispatch_gate_mode,'observe');
    authorization_required:=coalesce(cfg.require_fiscal_authorization_before_dispatch,true);
  end if;

  insert into public.order_fiscal_controls(order_id) values(o.id) on conflict(order_id) do nothing;
  select * into c from public.order_fiscal_controls where order_id=o.id;
  authorized:=c.dispatch_fiscal_status in ('authorized','not_required');
  fiscal_allowed:=not (gate_mode='enforce' and authorization_required) or authorized;

  select coalesce(r.metadata->>'ops2_stock_authority','legacy_shadow') into authority
    from public.bling_hub_runtime_v2 r where r.id=1;
  if coalesce(authority,'legacy_shadow')='bling' then
    select s.state into physical_state from public.bling_order_stock_controls_v2 s where s.source_order_id=o.id;
    physical_allowed:=coalesce(physical_state,'')='launched';
  end if;

  allowed:=fiscal_allowed and physical_allowed;
  if not fiscal_allowed then reason:='fiscal_authorization_required_before_dispatch';
  elsif not physical_allowed then reason:='bling_physical_stock_launch_required_before_dispatch';
  elsif authorized then reason:=null;
  elsif gate_mode='off' or not authorization_required then reason:='dispatch_fiscal_gate_off';
  else reason:='fiscal_authorization_pending_observe'; end if;

  return jsonb_build_object(
    'ok',true,'order_id',o.id,'order_status',o.status,'mode',gate_mode,
    'authorization_required',authorization_required,'allowed',allowed,'authorized',authorized,
    'dispatch_fiscal_status',c.dispatch_fiscal_status,'authorized_at',c.dispatch_fiscal_authorized_at,
    'source',c.dispatch_fiscal_source,'reason',coalesce(c.dispatch_fiscal_reason,reason),
    'bling_invoice_id',c.bling_invoice_id,'bling_invoice_number',c.bling_invoice_number,'sefaz_status',c.sefaz_status,
    'stock_authority',authority,'physical_stock_state',physical_state,'physical_stock_ready',physical_allowed,
    'external_side_effect',false
  );
end;
$function$
;

-- function: claim_bling_hub_jobs_v2(p_worker text, p_domains text[], p_limit integer, p_lease_seconds integer)
CREATE OR REPLACE FUNCTION public.claim_bling_hub_jobs_v2(p_worker text, p_domains text[] DEFAULT NULL::text[], p_limit integer DEFAULT 10, p_lease_seconds integer DEFAULT 300)
 RETURNS SETOF bling_hub_jobs_v2
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_runtime public.bling_hub_runtime_v2%rowtype;
  v_limit integer;
begin
  select * into v_runtime from public.bling_hub_runtime_v2 where id=1;
  if not found or v_runtime.hub_enabled is not true or v_runtime.mode not in ('homologation','live') then
    return;
  end if;
  if nullif(trim(coalesce(p_worker,'')),'') is null then raise exception 'worker_required'; end if;

  v_limit:=greatest(1,least(coalesce(p_limit,10),100));
  if v_runtime.mode='homologation' then
    v_limit:=least(v_limit,greatest(1,v_runtime.write_canary_limit));
  end if;

  update public.bling_hub_jobs_v2
  set status='retry',locked_at=null,locked_by=null,next_attempt_at=now(),updated_at=now(),
      error_code=coalesce(error_code,'lease_expired')
  where status='processing'
    and locked_at is not null
    and locked_at < now()-make_interval(secs=>greatest(60,least(coalesce(p_lease_seconds,300),1800)));

  return query
  with picked as (
    select j.id
    from public.bling_hub_jobs_v2 j
    where j.status in ('pending','retry')
      and j.next_attempt_at<=now()
      and j.attempts<j.max_attempts
      and (p_domains is null or cardinality(p_domains)=0 or j.domain=any(p_domains))
      and (
        (j.domain='product' and v_runtime.products_enabled)
        or (j.domain='stock' and v_runtime.stock_enabled)
        or (j.domain='customer' and v_runtime.customers_enabled)
        or (j.domain='order' and v_runtime.orders_enabled)
        or (j.domain='webhook' and v_runtime.webhooks_enabled)
        or (j.domain='fiscal' and v_runtime.fiscal_enabled)
      )
      and (
        v_runtime.mode='live'
        or (
          v_runtime.mode='homologation'
          and exists(
            select 1
            from public.bling_hub_canary_allowlist_v2 a
            where a.domain=j.domain
              and a.source_system=j.source_system
              and a.source_id=j.source_id
              and a.enabled=true
              and (a.expires_at is null or a.expires_at>now())
          )
        )
      )
    order by j.created_at,j.id
    for update skip locked
    limit v_limit
  )
  update public.bling_hub_jobs_v2 j
  set status='processing',attempts=j.attempts+1,locked_at=now(),locked_by=left(trim(p_worker),120),
      started_at=coalesce(j.started_at,now()),updated_at=now()
  from picked
  where j.id=picked.id
  returning j.*;
end
$function$
;

-- function: claim_bling_hub_oauth_lock_v2(p_owner uuid, p_ttl_seconds integer)
CREATE OR REPLACE FUNCTION public.claim_bling_hub_oauth_lock_v2(p_owner uuid, p_ttl_seconds integer DEFAULT 60)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_claimed boolean:=false;
begin
  if p_owner is null then raise exception 'owner_required'; end if;
  update public.bling_hub_runtime_v2
  set oauth_lock_owner=p_owner,
      oauth_locked_until=now()+make_interval(secs=>greatest(15,least(coalesce(p_ttl_seconds,60),300))),
      updated_at=now()
  where id=1 and (oauth_locked_until is null or oauth_locked_until<now() or oauth_lock_owner=p_owner)
  returning true into v_claimed;
  return coalesce(v_claimed,false);
end
$function$
;

-- function: claim_bling_official_ncm_catalog_refresh_v1(p_lease_seconds integer)
CREATE OR REPLACE FUNCTION public.claim_bling_official_ncm_catalog_refresh_v1(p_lease_seconds integer DEFAULT 180)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_claimed boolean := false;
begin
  update public.bling_official_ncm_catalog_cache_v1
     set refresh_lease_until = clock_timestamp()
         + make_interval(secs => greatest(30, least(coalesce(p_lease_seconds, 180), 300))),
         updated_at = clock_timestamp()
   where id = true
     and (refresh_lease_until is null or refresh_lease_until < clock_timestamp())
     and (next_refresh_after is null or next_refresh_after <= clock_timestamp())
  returning true into v_claimed;

  return coalesce(v_claimed, false);
end;
$function$
;

-- function: claim_bling_order_stock_action_v2(p_source_order_id uuid, p_bling_order_id bigint, p_deposit_id bigint, p_action text, p_snapshot jsonb)
CREATE OR REPLACE FUNCTION public.claim_bling_order_stock_action_v2(p_source_order_id uuid, p_bling_order_id bigint, p_deposit_id bigint, p_action text, p_snapshot jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_action text:=lower(trim(coalesce(p_action,'')));
  v_row public.bling_order_stock_controls_v2%rowtype;
begin
  if p_source_order_id is null or coalesce(p_bling_order_id,0)<=0 or coalesce(p_deposit_id,0)<=0 then
    return jsonb_build_object('ok',false,'error','invalid_identity');
  end if;
  if v_action not in ('launch','reverse') then
    return jsonb_build_object('ok',false,'error','invalid_action');
  end if;

  insert into public.bling_order_stock_controls_v2(
    source_order_id,bling_order_id,deposit_id,state,created_at,updated_at
  )
  values(
    p_source_order_id,p_bling_order_id,p_deposit_id,'not_launched',now(),now()
  )
  on conflict(source_order_id) do nothing;

  select *
    into v_row
    from public.bling_order_stock_controls_v2
   where source_order_id=p_source_order_id
   for update;

  if not found then
    return jsonb_build_object('ok',false,'error','control_row_missing');
  end if;
  if v_row.bling_order_id<>p_bling_order_id or v_row.deposit_id<>p_deposit_id then
    return jsonb_build_object('ok',false,'error','control_identity_mismatch','state',v_row.state);
  end if;

  if v_action='launch' then
    if v_row.state='launched' then
      return jsonb_build_object('ok',true,'claimed',false,'already_done',true,'state',v_row.state);
    end if;
    if v_row.state='launching' then
      return jsonb_build_object('ok',true,'claimed',false,'in_progress',true,'state',v_row.state);
    end if;
    if v_row.state in ('reversing','review_required') then
      return jsonb_build_object('ok',false,'error','stock_action_blocked','state',v_row.state);
    end if;

    update public.bling_order_stock_controls_v2
       set state='launching',
           launch_attempts=launch_attempts+1,
           before_launch=coalesce(p_snapshot,'{}'::jsonb),
           after_launch=null,
           launched_at=null,
           last_error=null,
           updated_at=now()
     where source_order_id=p_source_order_id;

    return jsonb_build_object('ok',true,'claimed',true,'state','launching');
  end if;

  if v_row.state='reversed' or v_row.state='not_launched' then
    return jsonb_build_object('ok',true,'claimed',false,'already_done',true,'state',v_row.state);
  end if;
  if v_row.state='reversing' then
    return jsonb_build_object('ok',true,'claimed',false,'in_progress',true,'state',v_row.state);
  end if;
  if v_row.state<>'launched' then
    return jsonb_build_object('ok',false,'error','stock_reverse_not_allowed','state',v_row.state);
  end if;

  update public.bling_order_stock_controls_v2
     set state='reversing',
         reverse_attempts=reverse_attempts+1,
         before_reverse=coalesce(p_snapshot,'{}'::jsonb),
         after_reverse=null,
         reversed_at=null,
         last_error=null,
         updated_at=now()
   where source_order_id=p_source_order_id;

  return jsonb_build_object('ok',true,'claimed',true,'state','reversing');
end
$function$
;

-- function: claim_bling_webhook_inbox_v2(p_worker text, p_limit integer, p_lease_seconds integer)
CREATE OR REPLACE FUNCTION public.claim_bling_webhook_inbox_v2(p_worker text, p_limit integer DEFAULT 10, p_lease_seconds integer DEFAULT 300)
 RETURNS SETOF bling_webhook_inbox_v2
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_runtime public.bling_hub_runtime_v2%rowtype;
  v_limit integer;
begin
  select * into v_runtime from public.bling_hub_runtime_v2 where id=1;
  if not found
     or v_runtime.hub_enabled is not true
     or v_runtime.webhooks_enabled is not true
     or v_runtime.mode not in ('homologation','live') then
    return;
  end if;
  if nullif(trim(coalesce(p_worker,'')),'') is null then raise exception 'worker_required'; end if;

  v_limit:=greatest(1,least(coalesce(p_limit,10),50));

  update public.bling_webhook_inbox_v2
     set status='retry',locked_at=null,locked_by=null,next_attempt_at=now(),updated_at=now(),
         last_error=coalesce(last_error,'lease_expired')
   where status='processing'
     and resource in ('order','stock','virtual_stock')
     and locked_at is not null
     and locked_at < now()-make_interval(secs=>greatest(60,least(coalesce(p_lease_seconds,300),1800)));

  return query
  with picked as (
    select i.event_id
      from public.bling_webhook_inbox_v2 i
     where i.status in ('held','received','retry')
       and i.resource in ('order','stock','virtual_stock')
       and i.next_attempt_at<=now()
       and i.attempt_count<i.max_attempts
     order by i.event_at nulls last,i.received_at,i.event_id
     for update skip locked
     limit v_limit
  )
  update public.bling_webhook_inbox_v2 i
     set status='processing',attempt_count=i.attempt_count+1,
         locked_by=left(trim(p_worker),120),locked_at=now(),updated_at=now()
    from picked
   where i.event_id=picked.event_id
  returning i.*;
end
$function$
;

-- function: claim_product_catalog_enrichment_jobs_v1(p_limit integer)
CREATE OR REPLACE FUNCTION public.claim_product_catalog_enrichment_jobs_v1(p_limit integer DEFAULT 5)
 RETURNS TABLE(product_id uuid, attempts integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  return query
  with candidates as (
    select j.product_id
    from public.product_catalog_enrichment_jobs_v1 j
    where (j.status='pending' and j.available_at <= now())
       or (j.status='processing' and j.locked_at < now() - interval '15 minutes')
    order by j.available_at, j.created_at
    for update skip locked
    limit greatest(1, least(coalesce(p_limit,5),5))
  ), claimed as (
    update public.product_catalog_enrichment_jobs_v1 j
    set status='processing', attempts=j.attempts+1, locked_at=now(), updated_at=now(), last_error=null
    from candidates c
    where j.product_id=c.product_id
    returning j.product_id, j.attempts
  )
  select c.product_id, c.attempts from claimed c;
end
$function$
;

-- function: confirm_cart_order(p_cart_id uuid, p_delivery_address jsonb)
CREATE OR REPLACE FUNCTION public.confirm_cart_order(p_cart_id uuid, p_delivery_address jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_cart public.carts%rowtype;
  v_conv public.conversations%rowtype;
  v_customer public.customers%rowtype;
  v_order_id uuid;
begin
  perform public.recalculate_cart(p_cart_id);
  select * into v_cart from public.carts where id=p_cart_id for update;
  if not found or v_cart.status<>'draft' then raise exception 'cart_not_confirmable'; end if;
  if v_cart.pricing_status<>'ready' then raise exception 'pricing_not_ready'; end if;
  select * into v_conv from public.conversations where id=v_cart.conversation_id;
  if not found then raise exception 'conversation_not_found'; end if;
  if v_cart.customer_id is not null then select * into v_customer from public.customers where id=v_cart.customer_id; end if;

  insert into public.orders(customer_id,conversation_id,whatsapp_account_id,cart_id,basket_id,status,total,fiscal_subtotal,other_expenses,discount,delivery_address,customer_snapshot,confirmed_at)
  values(v_cart.customer_id,v_cart.conversation_id,v_conv.whatsapp_account_id,v_cart.id,v_cart.basket_id,'confirmed',v_cart.total,v_cart.fiscal_subtotal,v_cart.other_expenses,v_cart.discount,coalesce(p_delivery_address,'{}'::jsonb),
         case when v_cart.customer_id is null then '{}'::jsonb else jsonb_build_object('id',v_customer.id,'name',v_customer.name,'phone',v_customer.primary_whatsapp_e164,'cpf_cnpj',v_customer.cpf_cnpj,'bling_contact_id',v_customer.bling_contact_id) end,now())
  returning id into v_order_id;

  insert into public.order_items(order_id,product_id,sku_snapshot,name_snapshot,quantity,unit_price,line_total,metadata)
  select v_order_id,p.id,p.sku,p.name,ci.quantity,coalesce(p.price,ci.unit_price,0),ci.quantity*coalesce(p.price,ci.unit_price,0),ci.metadata || jsonb_build_object('source',ci.source,'commercial_delta',ci.commercial_delta)
  from public.cart_items ci join public.products p on p.id=ci.product_id where ci.cart_id=p_cart_id and ci.quantity>0;

  update public.carts set status='converted',updated_at=now() where id=p_cart_id;
  update public.conversations set stage='confirmation',status='waiting_customer',updated_at=now() where id=v_cart.conversation_id;
  return jsonb_build_object('order_id',v_order_id,'cart_id',p_cart_id,'total',v_cart.total,'fiscal_subtotal',v_cart.fiscal_subtotal,'other_expenses',v_cart.other_expenses,'discount',v_cart.discount,'status','confirmed');
end;
$function$
;

-- function: confirm_cart_order_v2(p_cart_id uuid, p_delivery_address jsonb, p_idempotency_key text)
CREATE OR REPLACE FUNCTION public.confirm_cart_order_v2(p_cart_id uuid, p_delivery_address jsonb DEFAULT '{}'::jsonb, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_cart public.carts%rowtype;
  v_conv public.conversations%rowtype;
  v_customer public.customers%rowtype;
  v_order public.orders%rowtype;
  v_key text;
begin
  if p_cart_id is null then raise exception 'cart_id_required'; end if;
  v_key := nullif(left(btrim(coalesce(p_idempotency_key,'')),160),'');

  select * into v_order from public.orders where cart_id=p_cart_id limit 1;
  if found then
    if v_key is not null and v_order.idempotency_key is not null and v_order.idempotency_key<>v_key then raise exception 'idempotency_key_conflict'; end if;
    return jsonb_build_object('order_id',v_order.id,'cart_id',v_order.cart_id,'total',v_order.total,'fiscal_subtotal',v_order.fiscal_subtotal,'other_expenses',v_order.other_expenses,'discount',v_order.discount,'status',v_order.status,'idempotent_replay',true);
  end if;

  if v_key is not null then
    select * into v_order from public.orders where idempotency_key=v_key limit 1;
    if found then
      if v_order.cart_id is distinct from p_cart_id then raise exception 'idempotency_key_conflict'; end if;
      return jsonb_build_object('order_id',v_order.id,'cart_id',v_order.cart_id,'total',v_order.total,'fiscal_subtotal',v_order.fiscal_subtotal,'other_expenses',v_order.other_expenses,'discount',v_order.discount,'status',v_order.status,'idempotent_replay',true);
    end if;
  end if;

  perform public.recalculate_cart(p_cart_id);
  select * into v_cart from public.carts where id=p_cart_id for update;
  if not found or v_cart.status<>'draft' then raise exception 'cart_not_confirmable'; end if;
  if v_cart.pricing_status<>'ready' then raise exception 'pricing_not_ready'; end if;
  select * into v_conv from public.conversations where id=v_cart.conversation_id;
  if not found then raise exception 'conversation_not_found'; end if;
  if v_cart.customer_id is not null then select * into v_customer from public.customers where id=v_cart.customer_id; end if;

  insert into public.orders(customer_id,conversation_id,whatsapp_account_id,cart_id,basket_id,status,total,fiscal_subtotal,other_expenses,discount,delivery_address,customer_snapshot,confirmed_at,idempotency_key)
  values(v_cart.customer_id,v_cart.conversation_id,v_conv.whatsapp_account_id,v_cart.id,v_cart.basket_id,'confirmed',v_cart.total,v_cart.fiscal_subtotal,v_cart.other_expenses,v_cart.discount,coalesce(p_delivery_address,'{}'::jsonb),case when v_cart.customer_id is null then '{}'::jsonb else jsonb_build_object('id',v_customer.id,'name',v_customer.name,'phone',v_customer.primary_whatsapp_e164,'cpf_cnpj',v_customer.cpf_cnpj,'bling_contact_id',v_customer.bling_contact_id) end,now(),v_key)
  returning * into v_order;

  insert into public.order_items(order_id,product_id,sku_snapshot,name_snapshot,quantity,unit_price,line_total,metadata)
  select v_order.id,p.id,p.sku,p.name,ci.quantity,coalesce(p.price,ci.unit_price,0),ci.quantity*coalesce(p.price,ci.unit_price,0),ci.metadata || jsonb_build_object('source',ci.source,'commercial_delta',ci.commercial_delta)
  from public.cart_items ci join public.products p on p.id=ci.product_id where ci.cart_id=p_cart_id and ci.quantity>0;

  update public.carts set status='converted',updated_at=now() where id=p_cart_id;
  update public.conversations set stage='confirmation',status='waiting_customer',updated_at=now() where id=v_cart.conversation_id;
  insert into public.order_status_events(order_id,from_status,to_status,source,event_key,metadata) values(v_order.id,null,'confirmed','checkout','order-confirmed:'||v_order.id,jsonb_build_object('cart_id',p_cart_id));

  return jsonb_build_object('order_id',v_order.id,'cart_id',p_cart_id,'total',v_order.total,'fiscal_subtotal',v_order.fiscal_subtotal,'other_expenses',v_order.other_expenses,'discount',v_order.discount,'status','confirmed','idempotent_replay',false);
exception when unique_violation then
  select * into v_order from public.orders where cart_id=p_cart_id or (v_key is not null and idempotency_key=v_key) order by created_at limit 1;
  if found then return jsonb_build_object('order_id',v_order.id,'cart_id',v_order.cart_id,'total',v_order.total,'fiscal_subtotal',v_order.fiscal_subtotal,'other_expenses',v_order.other_expenses,'discount',v_order.discount,'status',v_order.status,'idempotent_replay',true); end if;
  raise;
end;
$function$
;

-- function: confirm_order_payment_v1(p_order_id uuid, p_payment_method text, p_payment_source text, p_settled_amount numeric, p_confirmed_at timestamp with time zone)
CREATE OR REPLACE FUNCTION public.confirm_order_payment_v1(p_order_id uuid, p_payment_method text, p_payment_source text, p_settled_amount numeric, p_confirmed_at timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  o public.orders%rowtype;
  method text := lower(trim(coalesce(p_payment_method,'')));
  source text := lower(trim(coalesce(p_payment_source,'')));
begin
  select * into o from public.orders where id=p_order_id for update;
  if not found then return jsonb_build_object('ok',false,'error','order_not_found','side_effect_performed',false); end if;
  if method not in ('cash','pix','card','payment_link','prepaid_pix','prepaid_link','other') then
    return jsonb_build_object('ok',false,'error','invalid_payment_method','side_effect_performed',false);
  end if;
  if p_settled_amount is null or p_settled_amount < 0 then
    return jsonb_build_object('ok',false,'error','invalid_settled_amount','side_effect_performed',false);
  end if;

  insert into public.order_fiscal_controls(order_id,payment_status,payment_method,payment_source,settled_amount,payment_confirmed_at)
  values(o.id,'confirmed',method,nullif(source,''),p_settled_amount,coalesce(p_confirmed_at,now()))
  on conflict(order_id) do update
    set payment_status='confirmed',payment_method=excluded.payment_method,payment_source=excluded.payment_source,
        settled_amount=excluded.settled_amount,payment_confirmed_at=excluded.payment_confirmed_at,updated_at=now();

  return public.refresh_order_fiscal_readiness_v1(o.id);
end;
$function$
;

-- function: consume_caneca_studio_public_limit_v1(p_client_ip_hash text, p_limit integer)
CREATE OR REPLACE FUNCTION public.consume_caneca_studio_public_limit_v1(p_client_ip_hash text, p_limit integer DEFAULT 5)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
declare
  affected_rows integer;
begin
  if p_client_ip_hash is null
    or p_client_ip_hash !~ '^[0-9a-f]{64}$'
    or p_limit < 1
    or p_limit > 10
  then
    return false;
  end if;

  insert into public.caneca_studio_generation_limits as stored (
    client_ip_hash,
    window_started_at,
    request_count,
    last_seen_at
  )
  values (p_client_ip_hash, now(), 1, now())
  on conflict (client_ip_hash) do update
  set
    window_started_at = case
      when stored.window_started_at <= now() - interval '24 hours' then now()
      else stored.window_started_at
    end,
    request_count = case
      when stored.window_started_at <= now() - interval '24 hours' then 1
      else stored.request_count + 1
    end,
    last_seen_at = now()
  where
    stored.window_started_at <= now() - interval '24 hours'
    or stored.request_count < p_limit;

  get diagnostics affected_rows = row_count;
  return affected_rows = 1;
end;
$function$
;

-- function: consume_public_rate_limit(p_rate_key text, p_bucket text, p_limit integer, p_window_seconds integer)
CREATE OR REPLACE FUNCTION public.consume_public_rate_limit(p_rate_key text, p_bucket text, p_limit integer, p_window_seconds integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_count integer;v_start timestamptz;
begin
  if p_limit<1 or p_window_seconds<1 then return false; end if;
  insert into public.public_rate_limits(rate_key,bucket,window_started_at,hit_count,updated_at)
  values(left(coalesce(p_rate_key,''),180),left(coalesce(p_bucket,''),80),now(),1,now())
  on conflict(rate_key,bucket) do update set
    hit_count=case when public.public_rate_limits.window_started_at <= now()-make_interval(secs=>p_window_seconds) then 1 else public.public_rate_limits.hit_count+1 end,
    window_started_at=case when public.public_rate_limits.window_started_at <= now()-make_interval(secs=>p_window_seconds) then now() else public.public_rate_limits.window_started_at end,
    updated_at=now()
  returning hit_count,window_started_at into v_count,v_start;
  return v_count<=p_limit;
end;
$function$
;

-- function: consume_vitrine_order_stock_v1(p_order_id uuid)
CREATE OR REPLACE FUNCTION public.consume_vitrine_order_stock_v1(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  r record;
  v_count integer;
  v_consumed integer;
  v_released integer;
  v_stock numeric;
begin
  if p_order_id is null then
    return jsonb_build_object('ok',false,'error','invalid_order_id');
  end if;

  select count(*),count(*) filter(where status='consumed'),count(*) filter(where status='released')
    into v_count,v_consumed,v_released
  from public.vitrine_stock_reservations
  where order_id=p_order_id;

  if v_count=0 then
    return jsonb_build_object('ok',true,'status','no_reservations',
      'local_consume_skipped',true,'reservations_consumed',true,'physical_stock_changed',false);
  end if;
  if v_consumed=v_count then
    return jsonb_build_object('ok',true,'status','consumed','already_consumed',true,
      'local_consume_skipped',false,'reservations_consumed',true);
  end if;
  if v_released>0 then
    return jsonb_build_object('ok',false,'error','stock_reservation_released');
  end if;

  for r in
    select product_id,quantity
    from public.vitrine_stock_reservations
    where order_id=p_order_id and status='reserved'
    order by product_id
    for update
  loop
    select stock into v_stock
    from public.products
    where id=r.product_id and is_active=true
    for update;
    if not found then
      return jsonb_build_object('ok',false,'error','product_unavailable','product_id',r.product_id);
    end if;
    if coalesce(v_stock,0)<r.quantity then
      return jsonb_build_object('ok',false,'error','insufficient_physical_stock',
        'product_id',r.product_id,'available',coalesce(v_stock,0),'requested',r.quantity);
    end if;
  end loop;

  for r in
    select product_id,quantity
    from public.vitrine_stock_reservations
    where order_id=p_order_id and status='reserved'
    order by product_id
  loop
    update public.products
    set stock=coalesce(stock,0)-r.quantity,updated_at=now()
    where id=r.product_id;
  end loop;

  update public.vitrine_stock_reservations
  set status='consumed',consumed_at=now(),released_at=null,updated_at=now()
  where order_id=p_order_id and status='reserved';

  return jsonb_build_object('ok',true,'status','consumed','already_consumed',false,
    'stock_source','supabase_products_stock','physical_stock_changed',true);
end;
$function$
;

-- function: cosmos_gtin_valid(p_gtin text)
CREATE OR REPLACE FUNCTION public.cosmos_gtin_valid(p_gtin text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog'
AS $function$
declare n integer; pos integer; sum_digits integer:=0;
begin
 n:=length(p_gtin);
 if n not in (8,12,13,14) or p_gtin !~ '^[0-9]+$' then return false; end if;
 for pos in 1..(n-1) loop
   sum_digits:=sum_digits+substring(p_gtin from pos for 1)::int
     * case when mod(n-pos,2)=1 then 3 else 1 end;
 end loop;
 return mod(10-mod(sum_digits,10),10)=right(p_gtin,1)::int;
end $function$
;

-- function: cosmos_research_reserve_next()
CREATE OR REPLACE FUNCTION public.cosmos_research_reserve_next()
 RETURNS TABLE(request_id bigint, selected_product_id uuid, selected_gtin text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
 cfg record;
 used_slots int;
 next_record record;
 local_day date := (now() at time zone 'America/Cuiaba')::date;
begin
 select enabled,daily_limit,research_mode into cfg
 from public.cosmos_research_config where id=true for update;
 if not found or not cfg.enabled then return; end if;

 -- Refazer fila somente para produtos ativos com GTIN numérico de formato válido.
 -- Nenhum match é assumido usando apenas a semelhança dos nomes.
 insert into public.cosmos_product_research(product_id,gtin,candidate_cohort_key)
 select p.id,trim(p.gtin),
        lower(concat_ws('|',nullif(trim(p.brand),''),
          nullif(trim(coalesce(p.customer_subsubcategory,p.subcategory,'')),''),
          regexp_replace(coalesce(p.packaging,''),'\s+','','g')))
 from public.products p
 where p.is_active and trim(coalesce(p.gtin,'')) ~ '^[0-9]{8}([0-9]{4}([0-9]{1,2})?)?$'
   and not exists (select 1 from public.cosmos_product_research r where r.product_id=p.id)
 order by p.id limit 150
 on conflict (product_id) do nothing;

 -- Se a função caiu no meio da chamada, liberar o item para nova tentativa futura.
 update public.cosmos_product_research r set status='retry',
   retry_after=now()+interval '24 hours', updated_at=now(),last_error='abandoned_reservation'
 where r.status='reserved' and r.last_attempt_at<now()-interval '45 minutes';

 select count(*) into used_slots from public.cosmos_research_requests
 where quota_date=local_day;
 if used_slots >= cfg.daily_limit then return; end if;

 select r.product_id,r.gtin into next_record
 from public.cosmos_product_research r
 join public.products p on p.id=r.product_id
 left join public.cosmos_family_representatives_v2 rep
   on rep.representative_product_id=r.product_id
 where p.is_active and trim(p.gtin)=r.gtin
   and public.cosmos_gtin_valid(r.gtin)
   and (cfg.research_mode='full' or rep.representative_product_id is not null)
   and r.status in ('pending','retry')
   and (r.retry_after is null or r.retry_after <= now())
 order by case when rep.representative_product_id is not null then 0 else 1 end,
   r.created_at, r.product_id
 for update of r skip locked limit 1;
 if not found then return; end if;

 insert into public.cosmos_research_requests(quota_date,quota_slot,product_id,gtin)
 values (local_day,used_slots+1,next_record.product_id,next_record.gtin)
 returning id into request_id;
 update public.cosmos_product_research
 set status='reserved',last_attempt_at=now(),updated_at=now()
 where product_id=next_record.product_id;
 selected_product_id:=next_record.product_id;
 selected_gtin:=next_record.gtin;
 return next;
end $function$
;

-- function: create_admin_saved_card_v1(p_name text, p_brand text, p_initial_value numeric, p_credit_added_on date, p_card_password text, p_idempotency_key uuid)
CREATE OR REPLACE FUNCTION public.create_admin_saved_card_v1(p_name text, p_brand text, p_initial_value numeric, p_credit_added_on date, p_card_password text, p_idempotency_key uuid)
 RETURNS admin_saved_cards_v1
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_card public.admin_saved_cards_v1%rowtype;
  v_name text := btrim(coalesce(p_name, ''));
  v_brand text := btrim(coalesce(p_brand, ''));
  v_password text := btrim(coalesce(p_card_password, ''));
begin
  if char_length(v_name) not between 1 and 120
    or char_length(v_brand) not between 1 and 60
    or char_length(v_password) not between 1 and 120
    or p_initial_value is null
    or p_initial_value <= 0
    or p_initial_value > 9999999999.99
    or p_initial_value <> round(p_initial_value, 2)
    or p_credit_added_on is null
    or p_idempotency_key is null
  then
    raise exception 'invalid_card';
  end if;

  select c.* into v_card
  from public.admin_saved_cards_v1 as c
  join public.admin_saved_card_uses_v1 as u on u.card_id = c.id
  where u.idempotency_key = p_idempotency_key
    and u.transaction_origin = 'initial'
    and c.deleted_at is null
  limit 1;

  if found then
    if v_card.name <> v_name
      or v_card.brand <> v_brand
      or v_card.initial_value <> p_initial_value
      or v_card.credit_added_on <> p_credit_added_on
      or v_card.card_password <> v_password
    then
      raise exception 'idempotency_key_conflict';
    end if;
    return v_card;
  end if;

  insert into public.admin_saved_cards_v1 (
    name, brand, initial_value, current_balance, credit_added_on, card_password
  )
  values (
    v_name, v_brand, p_initial_value, p_initial_value, p_credit_added_on, v_password
  )
  returning * into v_card;

  insert into public.admin_saved_card_uses_v1 (
    card_id, amount, idempotency_key, transaction_type, location, transaction_origin
  )
  values (
    v_card.id, p_initial_value, p_idempotency_key, 'entry', null, 'initial'
  );

  return v_card;
end;
$function$
;

-- function: create_canonical_cart_order_v2(p_source text, p_phone text, p_payment_method text, p_items jsonb, p_customer_snapshot jsonb, p_delivery jsonb)
CREATE OR REPLACE FUNCTION public.create_canonical_cart_order_v2(p_source text, p_phone text, p_payment_method text, p_items jsonb, p_customer_snapshot jsonb DEFAULT '{}'::jsonb, p_delivery jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_source text:=lower(trim(coalesce(p_source,'')));
  v_result jsonb;
  v_order_id uuid;
  v_reservation jsonb;
  v_error text;
begin
  v_result:=public.create_canonical_cart_order_v2_base(
    p_source,p_phone,p_payment_method,p_items,p_customer_snapshot,p_delivery
  );

  if v_source='vitrine' then
    begin
      v_order_id:=nullif(v_result->>'order_id','')::uuid;
    exception when others then
      v_order_id:=null;
    end;
    if v_order_id is null then
      raise exception 'order_id_missing' using errcode='P0001';
    end if;

    v_reservation:=public.reserve_vitrine_order_stock_v1(v_order_id);
    if coalesce((v_reservation->>'ok')::boolean,false) is not true then
      v_error:=coalesce(nullif(v_reservation->>'error',''),'stock_reservation_failed');
      raise exception '%',v_error using errcode='P0001';
    end if;

    v_result:=v_result||jsonb_build_object(
      'stock_reserved',true,
      'reservation_timing','on_create',
      'reservation_status',coalesce(v_reservation->>'status','reserved')
    );
  end if;

  return public.ops2_enrich_storefront_order_result_v1(v_result);
end;
$function$
;

-- function: create_storefront_order_v2(p_phone text, p_items jsonb, p_basket jsonb)
CREATE OR REPLACE FUNCTION public.create_storefront_order_v2(p_phone text, p_items jsonb DEFAULT '[]'::jsonb, p_basket jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_phone text; v_customer_id uuid; v_order_id uuid:=gen_random_uuid(); v_order_number text; v_basket_id uuid; v_basket public.basket_templates%rowtype; v_basket_items jsonb:='[]'::jsonb; v_extra_items jsonb:=coalesce(p_items,'[]'::jsonb); v_bi public.basket_template_items%rowtype; v_product public.products%rowtype; v_item jsonb; v_sel jsonb; v_qty numeric; v_min numeric; v_max numeric; v_delta numeric; v_total numeric(12,2):=0; v_fiscal numeric(12,2):=0; v_line numeric(12,2); v_unit numeric(12,2); v_matches integer; v_seen uuid[]:='{}'::uuid[]; v_lines text; v_message text; v_basket_name text;
begin
  v_phone:=public.normalize_storefront_phone_v2(p_phone);
  if jsonb_typeof(v_extra_items)<>'array' then raise exception 'items_must_be_array'; end if;
  if p_basket is not null and jsonb_typeof(p_basket)<>'object' then raise exception 'basket_must_be_object'; end if;
  select id into v_customer_id from public.customers where primary_whatsapp_e164=v_phone limit 1;
  if v_customer_id is null then select customer_id into v_customer_id from public.customer_phones where phone_e164=v_phone order by is_primary desc,created_at asc limit 1; end if;
  if p_basket is not null then
    begin v_basket_id:=nullif(p_basket->>'basket_id','')::uuid; exception when others then raise exception 'invalid_basket_id'; end;
    if v_basket_id is null then raise exception 'basket_id_required'; end if;
    select * into v_basket from public.basket_templates where id=v_basket_id and is_active=true;
    if not found then raise exception 'basket_not_available'; end if;
    if coalesce(v_basket.base_price,0)<0 then raise exception 'basket_price_invalid'; end if;
    v_basket_name:=v_basket.name; v_total:=v_basket.base_price; v_basket_items:=coalesce(p_basket->'items','[]'::jsonb);
    if jsonb_typeof(v_basket_items)<>'array' then raise exception 'basket_items_must_be_array'; end if;
    if jsonb_array_length(v_basket_items)<>(select count(*) from public.basket_template_items where basket_id=v_basket_id) then raise exception 'basket_selection_incomplete'; end if;
  elsif jsonb_array_length(v_extra_items)=0 then raise exception 'cart_empty'; end if;
  v_order_number:='DA-'||to_char(clock_timestamp() at time zone 'America/Cuiaba','YYMMDD')||'-'||upper(substr(replace(v_order_id::text,'-',''),1,8));
  insert into public.orders(id,customer_id,conversation_id,whatsapp_account_id,status,total,subtotal,currency,delivery_address,customer_snapshot,confirmed_at,created_at,updated_at,basket_id,fiscal_subtotal,other_expenses,discount,sync_status,idempotency_key,phone_e164,source,order_number)
  values(v_order_id,v_customer_id,null,null,'storefront_received',0,0,'BRL','{}'::jsonb,jsonb_build_object('phone_e164',v_phone),null,now(),now(),v_basket_id,0,0,0,'local','storefront-v2:'||v_order_number,v_phone,'storefront_v2',v_order_number);
  if v_basket_id is not null then
    for v_bi in select * from public.basket_template_items where basket_id=v_basket_id order by sort_order,created_at loop
      select count(*) into v_matches from jsonb_array_elements(v_basket_items) where value->>'product_id'=v_bi.product_id::text;
      select value into v_sel from jsonb_array_elements(v_basket_items) where value->>'product_id'=v_bi.product_id::text limit 1;
      if v_matches<>1 then raise exception 'basket_component_missing_or_duplicate'; end if;
      if coalesce(v_sel->>'quantity','')!~'^[0-9]+([.]0+)?$' then raise exception 'invalid_basket_quantity'; end if;
      v_qty:=(v_sel->>'quantity')::numeric; if trunc(v_qty)<>v_qty then raise exception 'invalid_basket_quantity'; end if;
      select * into v_product from public.products where id=v_bi.product_id and is_active=true;
      if not found then raise exception 'basket_product_unavailable'; end if;
      if v_qty>greatest(0,floor(coalesce(v_product.stock,0))) then raise exception 'insufficient_stock'; end if;
      if v_qty=0 and not v_bi.removable then raise exception 'item_not_removable'; end if;
      if v_qty<v_bi.quantity and not (v_bi.removable or v_bi.quantity_editable) then raise exception 'quantity_not_editable'; end if;
      if v_qty>v_bi.quantity and not v_bi.quantity_editable then raise exception 'quantity_not_editable'; end if;
      v_min:=greatest(0,coalesce(v_bi.min_quantity,case when v_bi.removable then 0 else v_bi.quantity end));
      v_max:=least(greatest(0,floor(coalesce(v_product.stock,0))),coalesce(v_bi.max_quantity,greatest(v_bi.quantity,floor(coalesce(v_product.stock,0)))));
      if v_qty<v_min or v_qty>v_max then raise exception 'basket_quantity_out_of_range'; end if;
      v_delta:=0;
      if v_qty<v_bi.quantity then
        if v_bi.remove_unit_delta is null and coalesce(v_product.price,0)<=0 then raise exception 'remove_pricing_not_configured'; end if;
        v_delta:=abs(v_qty-v_bi.quantity)*coalesce(v_bi.remove_unit_delta,-v_product.price);
      elsif v_qty>v_bi.quantity then
        if v_bi.add_unit_delta is null and coalesce(v_product.price,0)<=0 then raise exception 'add_pricing_not_configured'; end if;
        v_delta:=(v_qty-v_bi.quantity)*coalesce(v_bi.add_unit_delta,v_product.price);
      end if;
      v_total:=v_total+v_delta;
      if v_qty>0 then
        v_line:=round(v_qty*coalesce(v_product.price,0),2); v_fiscal:=v_fiscal+v_line;
        insert into public.order_items(order_id,product_id,sku_snapshot,name_snapshot,quantity,unit_price,line_total,metadata)
        values(v_order_id,v_product.id,v_product.sku,v_product.name,v_qty,coalesce(v_product.price,0),v_line,jsonb_build_object('source','basket','basket_id',v_basket_id,'base_quantity',v_bi.quantity,'commercial_delta',v_delta,'removable',v_bi.removable,'quantity_editable',v_bi.quantity_editable));
      end if;
    end loop;
  end if;
  for v_item in select value from jsonb_array_elements(v_extra_items) loop
    if jsonb_typeof(v_item)<>'object' then raise exception 'item_must_be_object'; end if;
    begin v_product.id:=(v_item->>'product_id')::uuid; exception when others then raise exception 'invalid_product_id'; end;
    if v_product.id=any(v_seen) then raise exception 'duplicate_product'; end if; v_seen:=array_append(v_seen,v_product.id);
    if coalesce(v_item->>'quantity','')!~'^[1-9][0-9]*([.]0+)?$' then raise exception 'invalid_quantity'; end if;
    v_qty:=(v_item->>'quantity')::numeric; if trunc(v_qty)<>v_qty then raise exception 'invalid_quantity'; end if;
    select * into v_product from public.products where id=v_product.id and is_active=true;
    if not found or v_product.price is null or v_product.price<0 then raise exception 'product_unavailable'; end if;
    if v_qty>greatest(0,floor(coalesce(v_product.stock,0))) then raise exception 'insufficient_stock'; end if;
    v_unit:=case when v_product.is_offer=true and v_product.offer_price is not null and v_product.offer_price>=0 then v_product.offer_price else v_product.price end;
    v_line:=round(v_qty*v_unit,2); v_total:=v_total+v_line; v_fiscal:=v_fiscal+v_line;
    insert into public.order_items(order_id,product_id,sku_snapshot,name_snapshot,quantity,unit_price,line_total,metadata)
    values(v_order_id,v_product.id,v_product.sku,v_product.name,v_qty,v_unit,v_line,jsonb_build_object('source','extra','regular_price',v_product.price,'offer_price',case when v_product.is_offer then v_product.offer_price else null end));
  end loop;
  if v_total<0 then raise exception 'invalid_order_total'; end if;
  update public.orders set subtotal=round(v_total,2),total=round(v_total,2),fiscal_subtotal=round(v_fiscal,2),other_expenses=greatest(round(v_total-v_fiscal,2),0),discount=greatest(round(v_fiscal-v_total,2),0),updated_at=now() where id=v_order_id;
  select string_agg('- '||trim(to_char(quantity,'FM999999990.###'))||'x '||name_snapshot,E'\n' order by created_at,id) into v_lines from public.order_items where order_id=v_order_id;
  v_message:='Olá! Meu pedido é '||v_order_number||E'.\n\n'||case when v_basket_name is not null then 'Cesta: '||v_basket_name||E'\n' else '' end||coalesce(v_lines,'')||E'\n\nTotal: R$ '||replace(to_char(round(v_total,2),'FM999999990.00'),'.',',');
  return jsonb_build_object('order_id',v_order_id,'order_number',v_order_number,'customer_id',v_customer_id,'phone_e164',v_phone,'subtotal',round(v_total,2),'total',round(v_total,2),'message',v_message);
end;
$function$
;

-- function: create_vitrine_cart_order_v3(p_phone text, p_payment_method text, p_items jsonb, p_customer_snapshot jsonb, p_delivery jsonb)
CREATE OR REPLACE FUNCTION public.create_vitrine_cart_order_v3(p_phone text, p_payment_method text, p_items jsonb, p_customer_snapshot jsonb DEFAULT '{}'::jsonb, p_delivery jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_result jsonb;
  v_order_id uuid;
  v_reservation jsonb;
  v_error text;
begin
  v_result:=public.create_vitrine_cart_order_v3_base(
    p_phone,p_payment_method,p_items,p_customer_snapshot,p_delivery
  );

  begin
    v_order_id:=nullif(v_result->>'order_id','')::uuid;
  exception when others then
    v_order_id:=null;
  end;
  if v_order_id is null then
    raise exception 'order_id_missing' using errcode='P0001';
  end if;

  v_reservation:=public.reserve_vitrine_order_stock_v1(v_order_id);
  if coalesce((v_reservation->>'ok')::boolean,false) is not true then
    v_error:=coalesce(nullif(v_reservation->>'error',''),'stock_reservation_failed');
    raise exception '%',v_error using errcode='P0001',detail=v_reservation::text;
  end if;

  -- Discard the whole transaction if a concurrent order consumed a reviewed item.
  if p_customer_snapshot ? 'expected_total_cents'
     and coalesce((v_reservation->>'manual_replacement_count')::integer,0)>0 then
    raise exception 'checkout_stock_changed';
  end if;

  v_result:=v_result||jsonb_build_object(
    'stock_reserved',coalesce(v_reservation->>'status','reserved')<>'manual_replacement_pending',
    'reservation_timing','on_create',
    'reservation_status',coalesce(v_reservation->>'status','reserved'),
    'manual_replacement_count',coalesce(nullif(v_reservation->>'manual_replacement_count','')::integer,0)
  );

  return public.ops2_enrich_storefront_order_result_v1(v_result);
end;
$function$
;

-- function: create_vitrine_cart_order_v3_base(p_phone text, p_payment_method text, p_items jsonb, p_customer_snapshot jsonb, p_delivery jsonb)
CREATE OR REPLACE FUNCTION public.create_vitrine_cart_order_v3_base(p_phone text, p_payment_method text, p_items jsonb, p_customer_snapshot jsonb DEFAULT '{}'::jsonb, p_delivery jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_phone text;
  v_customer_id uuid;
  v_order_id uuid:=gen_random_uuid();
  v_order_number text;
  v_payment_code text;
  v_payment_label text;
  v_cart jsonb:=coalesce(p_items,'[]'::jsonb);
  v_customer jsonb:=coalesce(p_customer_snapshot,'{}'::jsonb);
  v_delivery jsonb:=coalesce(p_delivery,'{}'::jsonb);
  v_line jsonb;
  v_components jsonb;
  v_basket public.basket_templates%rowtype;
  v_product public.products%rowtype;
  v_line_qty numeric;
  v_product_id uuid;
  v_unit numeric;
  v_line_total numeric;
  v_total numeric(14,2):=0;
  v_expected_total_cents bigint;
  v_actual_total_cents bigint;
  v_fiscal numeric(14,2):=0;
  v_item_rows jsonb:='[]'::jsonb;
  v_sep_rows jsonb:='[]'::jsonb;
  v_loose_demand jsonb:='{}'::jsonb;
  v_current_demand numeric;
  v_mold_component_demand numeric;
  v_existing_stock numeric;
  v_pair record;
  v_basket_unit numeric;
  v_basket_fiscal_unit numeric;
  v_component_snapshot jsonb;
  v_addr jsonb;
  v_first_basket uuid:=null;
  v_basket_names text[]:='{}'::text[];
  v_mold public.basket_molds%rowtype;
  v_mold_position record;
  v_mold_component_count integer;
  v_mold_position_count integer;
  v_composition_number integer;
  v_conditional_hidden_applied numeric:=0;
  v_mold_pricing_model text;
  v_mold_configured_product_total numeric:=0;
  v_mold_configured_base numeric:=0;
  v_mold_configured_conditional numeric:=0;
  v_mold_selection_delta numeric:=0;
  v_manual_replacement_required boolean:=false;
  v_replacement_product_id uuid;
  v_requested_sort_order integer;
  v_selected_option jsonb;
  v_selected jsonb;
  v_selected_qty numeric;
  v_options jsonb;
  v_selected_total numeric;

begin
  -- Older clients do not send a reviewed total yet.
  if v_customer ? 'expected_total_cents' then
    if jsonb_typeof(v_customer->'expected_total_cents') is distinct from 'number'
       or coalesce(v_customer->>'expected_total_cents','') !~ '^[0-9]{1,14}$' then
      raise exception 'checkout_confirmation_invalid';
    end if;
    v_expected_total_cents:=(v_customer->>'expected_total_cents')::bigint;
  end if;
  if nullif(btrim(coalesce(p_phone,'')),'') is null then
    v_phone:=null;
  else
    v_phone:=public.normalize_storefront_phone_v2(p_phone);
  end if;
  if jsonb_typeof(v_cart)<>'array' or jsonb_array_length(v_cart)=0 then raise exception 'cart_empty'; end if;
  if jsonb_array_length(v_cart)>80 then raise exception 'too_many_items'; end if;

  v_payment_label:=trim(coalesce(p_payment_method,''));
  v_payment_code:=case v_payment_label
    when 'PIX' then 'pix'
    when 'Dinheiro' then 'cash'
    when 'Cartão de crédito' then 'credit_card'
    when 'Cartão alimentação/refeição' then 'food_card'
    else null
  end;
  if v_payment_label<>'' and v_payment_code is null then raise exception 'invalid_payment'; end if;

  begin
    if coalesce(v_customer->>'id','')<>'' then
      v_customer_id:=(v_customer->>'id')::uuid;
      if not exists(select 1 from public.customers where id=v_customer_id) then v_customer_id:=null; end if;
    end if;
  exception when others then v_customer_id:=null;
  end;
  if v_customer_id is null then
    select id into v_customer_id from public.customers where primary_whatsapp_e164=v_phone limit 1;
  end if;
  if v_customer_id is null then
    select customer_id into v_customer_id
    from public.customer_phones where phone_e164=v_phone
    order by is_primary desc,created_at asc limit 1;
  end if;

  for v_line in select value from jsonb_array_elements(v_cart) loop
    if jsonb_typeof(v_line)<>'object' then raise exception 'item_must_be_object'; end if;
    if coalesce(v_line->>'type','product') not in ('product','basket_mold') then raise exception 'invalid_item_type'; end if;
    begin v_line_qty:=coalesce(nullif(v_line->>'qty','')::numeric,1);
    exception when others then raise exception 'invalid_quantity'; end;
    if v_line_qty<=0 or v_line_qty>30 or trunc(v_line_qty)<>v_line_qty then raise exception 'invalid_quantity'; end if;

    if coalesce(v_line->>'type','product')='product' then
      begin v_product_id:=(v_line->>'id')::uuid;
      exception when others then raise exception 'invalid_product_id'; end;
      select * into v_product from public.products where id=v_product_id and is_active=true;
      if not found or v_product.price is null then
        raise exception 'product_unavailable'
          using detail=jsonb_build_object(
            'kind','product','product_id',v_product_id,
            'requested',v_line_qty,'available',0,
            'reason','product_not_orderable'
          )::text;
      end if;
      select case when stock_authority='bling' then loose_sellable_stock else coalesce(ean_sellable_stock,loose_sellable_stock) end into v_existing_stock
      from public.storefront_ean_sellable_stock_v1
      where product_id=v_product.id and is_active=true;
      if coalesce(v_existing_stock,0)<=0 then
        raise exception 'product_unavailable'
          using detail=jsonb_build_object(
            'kind','product','product_id',v_product.id,
            'requested',v_line_qty,'available',greatest(0,coalesce(v_existing_stock,0)),
            'reason','sem_estoque'
          )::text;
      end if;

      v_unit:=public.storefront_order_unit_price_v1(v_product.price,v_product.offer_price,v_product.is_offer,v_product.metadata,statement_timestamp());
      v_line_total:=round(v_unit*v_line_qty,2);
      v_total:=v_total+v_line_total;
      v_fiscal:=v_fiscal+v_line_total;
      v_current_demand:=coalesce((v_loose_demand->>v_product.id::text)::numeric,0)+v_line_qty;
      v_loose_demand:=jsonb_set(v_loose_demand,array[v_product.id::text],to_jsonb(v_current_demand),true);
      v_item_rows:=v_item_rows||jsonb_build_array(jsonb_build_object(
        'product_id',v_product.id,'sku',v_product.sku,'name',v_product.name,
        'quantity',v_line_qty,'unit_price',v_unit,'line_total',v_line_total,
        'metadata',jsonb_build_object(
          'source','vitrine_direct','history_kind','product',
          'image_url',coalesce(v_product.image_url,'')
        )
      ));
      continue;
    end if;

    if coalesce(v_line->>'type','product')='basket_mold' then
      v_mold_pricing_model:=coalesce(nullif(v_line->>'pricing_model',''),'legacy_component_sum_v1');
      v_mold_configured_product_total:=0;
      v_mold_configured_base:=0;
      v_mold_configured_conditional:=0;
      v_mold_selection_delta:=0;

      begin
        select * into v_basket
        from public.basket_templates
        where id=(v_line->>'id')::uuid and is_active=true;
      exception when others then raise exception 'invalid_basket_id'; end;
      if not found then
        if v_expected_total_cents is not null then raise exception 'basket_mold_unavailable'; end if;
        -- Recover saved carts only from an exact, unambiguous position set.
        -- Products, quantities, prices and stock are still validated below.
        v_components:=coalesce(v_line->'components','[]'::jsonb);
        if jsonb_typeof(v_components)<>'array' or jsonb_array_length(v_components)=0 then
          raise exception 'basket_mold_unavailable';
        end if;
        select * into v_basket from public.basket_templates
        where is_active=true and id=(
          select min(candidate.basket_id::text)::uuid
          from (
            select m.basket_id
            from public.basket_molds m
            join public.basket_templates b on b.id=m.basket_id and b.is_active=true
            join public.basket_mold_positions pos on pos.mold_id=m.id
            group by m.basket_id,m.id
            having count(*)=jsonb_array_length(v_components)
               and count(*)=(select count(distinct c->>'position_id') from jsonb_array_elements(v_components) c)
               and bool_and(exists(select 1 from jsonb_array_elements(v_components) c where c->>'position_id'=pos.id::text))
          ) candidate
          having count(*)=1
        );
        if not found then raise exception 'basket_mold_unavailable'; end if;
      end if;

      select * into v_mold from public.basket_molds where basket_id=v_basket.id;
      if not found then raise exception 'basket_mold_not_configured'; end if;
      if not public.basket_mold_cutover_ready_v1(v_basket.id) then
        raise exception 'basket_mold_legacy_pending';
      end if;

      begin v_composition_number:=coalesce(nullif(v_line->>'composition_number','')::integer,1);
      exception when others then raise exception 'basket_mold_composition_invalid'; end;
      if v_composition_number<1 or v_composition_number>v_mold.public_composition_count then
        raise exception 'basket_mold_composition_invalid';
      end if;

      v_components:=coalesce(v_line->'components','[]'::jsonb);
      if jsonb_typeof(v_components)<>'array' then raise exception 'basket_mold_components_required'; end if;
      select count(*) into v_mold_position_count from public.basket_mold_positions where mold_id=v_mold.id;
      if v_mold_position_count=0 or jsonb_array_length(v_components)<>v_mold_position_count then
        raise exception 'basket_mold_component_invalid';
      end if;

      if exists(
        select 1 from jsonb_array_elements(v_components) c
        where not exists(
          select 1 from public.basket_mold_positions pos
          where pos.mold_id=v_mold.id and pos.id::text=c->>'position_id'
        )
      ) then raise exception 'basket_mold_component_invalid'; end if;

      if v_mold_pricing_model='configured_base_delta_v1' then
        if exists(
          select 1 from public.basket_mold_positions pos
          where pos.mold_id=v_mold.id and not exists(
            select 1 from public.basket_mold_position_options opt where opt.position_id=pos.id
          )
        ) then
          raise exception 'basket_mold_composition_invalid';
        end if;

        -- Price the configured composition before applying stock or customer changes.
        -- Each variant contributes its own quantity; legacy positions use their first option.
        with configured as (
          select opt.product_id,
            case
              when coalesce(opt.metadata->>'base_quantity','') ~ '^[0-9]{1,3}$'
                then (opt.metadata->>'base_quantity')::numeric
              when row_number() over(partition by pos.id order by opt.sort_order,opt.product_id)=1
                then greatest(0,pos.quantity)
              else 0
            end as quantity
          from public.basket_mold_positions pos
          join public.basket_mold_position_options opt on opt.position_id=pos.id
          where pos.mold_id=v_mold.id
        )
        select
          coalesce(sum(round((public.storefront_order_unit_price_v1(product.price,product.offer_price,product.is_offer,product.metadata,statement_timestamp()))*configured.quantity,2)),0),
          case when coalesce(v_mold.conditional_hidden_enabled,false)
                     and coalesce(v_mold.conditional_hidden_adjustment,0)>0
                     and coalesce(bool_or(configured.product_id=v_mold.conditional_hidden_product_id),false)
               then round(v_mold.conditional_hidden_adjustment,2)
               else 0 end
        into v_mold_configured_product_total,v_mold_configured_conditional
        from configured
        left join public.products product on product.id=configured.product_id
        where configured.quantity>0;

        v_mold_configured_base:=case
          when coalesce(v_mold.metadata->>'site_admin_default_price_cents','') ~ '^[0-9]{1,9}$'
            then (v_mold.metadata->>'site_admin_default_price_cents')::numeric / 100
          else greatest(0,round(v_mold_configured_product_total
            +coalesce(v_mold.hidden_adjustment,0)+v_mold_configured_conditional,2))
        end;
      end if;

      v_basket_unit:=coalesce(v_mold.hidden_adjustment,0);
      v_basket_fiscal_unit:=0;
      v_component_snapshot:='[]'::jsonb;

      for v_mold_position in
        select id,label,quantity,sort_order
        from public.basket_mold_positions
        where mold_id=v_mold.id
        order by sort_order,id
      loop
        select count(*) into v_mold_component_count
        from jsonb_array_elements(v_components) c
        where c->>'position_id'=v_mold_position.id::text;
        if v_mold_component_count<>1 then raise exception 'basket_mold_component_invalid'; end if;

        select value into v_selected
        from jsonb_array_elements(v_components)
        where value->>'position_id'=v_mold_position.id::text
        limit 1;

        v_options:=coalesce(v_selected->'options','[]'::jsonb);
        if jsonb_typeof(v_options)<>'array' then raise exception 'basket_mold_component_invalid'; end if;
        if jsonb_array_length(v_options)=0 then
          v_options:=jsonb_build_array(jsonb_build_object(
            'product_id',v_selected->>'product_id',
            'quantity',case when v_selected ? 'quantity' then v_selected->'quantity' else to_jsonb(v_mold_position.quantity) end
          ));
        end if;
        v_selected_total:=0;

        for v_selected_option in select value from jsonb_array_elements(v_options)
        loop
          begin v_product_id:=nullif(v_selected_option->>'product_id','')::uuid;
          exception when others then raise exception 'basket_mold_component_invalid'; end;
          if v_product_id is null then raise exception 'basket_mold_option_invalid'; end if;
          select opt_row.sort_order into v_requested_sort_order
          from public.basket_mold_position_options opt_row
          where opt_row.position_id=v_mold_position.id and opt_row.product_id=v_product_id;
          if not found then
            if v_expected_total_cents is not null then raise exception 'basket_mold_option_invalid'; end if;
            select opt_row.product_id,opt_row.sort_order
            into v_product_id,v_requested_sort_order
            from public.basket_mold_position_options opt_row
            where opt_row.position_id=v_mold_position.id
            order by case when coalesce(opt_row.metadata,'{}'::jsonb) @> '{"preferred":true}'::jsonb then 0 else 1 end,
                     opt_row.sort_order,opt_row.product_id
            limit 1;
          end if;
          if v_product_id is null then raise exception 'basket_mold_option_invalid'; end if;

          select * into v_product from public.products where id=v_product_id;
          if not found or v_product.price is null then raise exception 'basket_mold_option_invalid'; end if;

          begin
            v_selected_qty:=coalesce(nullif(v_selected_option->>'quantity','')::numeric,0);
          exception when others then raise exception 'invalid_basket_quantity'; end;
          if v_selected_qty<0 or v_selected_qty>1000 or trunc(v_selected_qty)<>v_selected_qty then raise exception 'invalid_basket_quantity'; end if;
          v_selected_total:=v_selected_total+v_selected_qty;
          if v_selected_total>1000 then raise exception 'invalid_basket_quantity'; end if;

          select public.basket_component_fresh_sellable_stock_v1(v_product.id) into v_existing_stock;
          if v_expected_total_cents is not null and v_selected_qty>0
             and (v_product.is_active is not true or coalesce(v_existing_stock,0)<v_selected_qty*v_line_qty) then
            raise exception 'insufficient_stock'
              using detail=jsonb_build_object(
                'kind','basket_mold_component','product_id',v_product.id,
                'requested',v_selected_qty*v_line_qty,
                'available',case when v_product.is_active is true then greatest(0,coalesce(v_existing_stock,0)) else 0 end,
                'reason','estoque_insuficiente'
              )::text;
          end if;
          if v_product.is_active is not true or coalesce(v_existing_stock,0)<v_selected_qty*v_line_qty then
            select opt_row.product_id into v_replacement_product_id
            from public.basket_mold_position_options opt_row
            join public.products replacement_product on replacement_product.id=opt_row.product_id
            where opt_row.position_id=v_mold_position.id
              and replacement_product.is_active=true
              and public.basket_component_fresh_sellable_stock_v1(replacement_product.id)>=v_selected_qty*v_line_qty
            order by case
                       when (opt_row.sort_order,opt_row.product_id)>(coalesce(v_requested_sort_order,-1),v_product_id) then 0
                       else 1
                     end,
                     opt_row.sort_order,opt_row.product_id
            limit 1;
            if found then
              v_product_id:=v_replacement_product_id;
              select * into v_product from public.products where id=v_product_id;
              select public.basket_component_fresh_sellable_stock_v1(v_product.id) into v_existing_stock;
            end if;
          end if;
          v_manual_replacement_required:=v_product.is_active is not true
            or coalesce(v_existing_stock,0)<v_selected_qty*v_line_qty;
          if v_selected_qty=0 then
            v_component_snapshot:=v_component_snapshot||jsonb_build_array(jsonb_build_object(
              'position_id',v_mold_position.id,'label',v_mold_position.label,
              'product_id',v_product.id,'quantity',0
            ));
            continue;
          end if;

          v_unit:=public.storefront_order_unit_price_v1(v_product.price,v_product.offer_price,v_product.is_offer,v_product.metadata,statement_timestamp());
          v_line_total:=round(v_unit*v_selected_qty*v_line_qty,2);
          v_basket_fiscal_unit:=v_basket_fiscal_unit+round(v_unit*v_selected_qty,2);
          v_basket_unit:=v_basket_unit+round(v_unit*v_selected_qty,2);
          if not v_manual_replacement_required then
            v_current_demand:=coalesce((v_loose_demand->>v_product.id::text)::numeric,0)+(v_selected_qty*v_line_qty);
            v_loose_demand:=jsonb_set(v_loose_demand,array[v_product.id::text],to_jsonb(v_current_demand),true);
          end if;

          v_item_rows:=v_item_rows||jsonb_build_array(jsonb_build_object(
            'product_id',v_product.id,'sku',v_product.sku,'name',v_product.name,
            'quantity',v_selected_qty*v_line_qty,'unit_price',v_unit,'line_total',v_line_total,
            'metadata',jsonb_build_object(
              'source','vitrine_direct','history_kind','basket_mold_component',
              'basket_id',v_basket.id,'basket_name',v_basket.name,'basket_quantity',v_line_qty,
              'mold_id',v_mold.id,'position_id',v_mold_position.id,'position_label',v_mold_position.label,
              'composition_number',v_composition_number,'selected_quantity',v_selected_qty,
              'selected_product_id',v_selected_option->>'product_id',
              'image_url',coalesce(v_product.image_url,''),
              'manual_replacement_required',v_manual_replacement_required,
              'manual_replacement_reason',case when v_manual_replacement_required then 'no_available_basket_option' else null end
            )
          ));
          v_component_snapshot:=v_component_snapshot||jsonb_build_array(jsonb_build_object(
            'position_id',v_mold_position.id,'label',v_mold_position.label,
            'product_id',v_product.id,'quantity',v_selected_qty,
            'selected_product_id',v_selected_option->>'product_id'
          ));
        end loop;
      end loop;

      v_conditional_hidden_applied:=0;
      if coalesce(v_mold.conditional_hidden_enabled,false)
         and v_mold.conditional_hidden_product_id is not null
         and coalesce(v_mold.conditional_hidden_adjustment,0)>0
         and exists(
           select 1
           from jsonb_array_elements(v_component_snapshot) c
           where c->>'product_id'=v_mold.conditional_hidden_product_id::text
             and coalesce(nullif(c->>'quantity','')::numeric,0)>0
         )
      then
        v_conditional_hidden_applied:=round(v_mold.conditional_hidden_adjustment,2);
        v_basket_unit:=v_basket_unit+v_conditional_hidden_applied;
      end if;

      if v_mold_pricing_model='configured_base_delta_v1' then
        v_mold_selection_delta:=round(v_basket_fiscal_unit-v_mold_configured_product_total,2);
        v_basket_unit:=greatest(0,round(
          v_mold_configured_base
          +v_mold_selection_delta
          +v_conditional_hidden_applied
          -v_mold_configured_conditional,2
        ));
      end if;

      if v_basket_unit<0 then raise exception 'invalid_order_total'; end if;
      if v_first_basket is null then v_first_basket:=v_basket.id; end if;
      if not (v_basket.name=any(v_basket_names)) then v_basket_names:=array_append(v_basket_names,v_basket.name); end if;
      v_total:=v_total+round(v_basket_unit*v_line_qty,2);
      v_fiscal:=v_fiscal+round(v_basket_fiscal_unit*v_line_qty,2);

      v_item_rows:=v_item_rows||jsonb_build_array(jsonb_build_object(
        'product_id',null,'sku',null,'name',v_basket.name,
        'quantity',v_line_qty,'unit_price',round(v_basket_unit,2),'line_total',round(v_basket_unit*v_line_qty,2),
        'metadata',jsonb_build_object(
          'source','vitrine_direct','history_kind','basket_mold','basket_id',v_basket.id,
          'mold_id',v_mold.id,'composition_number',v_composition_number,
          'hidden_value_fixed',v_mold.hidden_adjustment,
          'conditional_hidden_enabled',v_mold.conditional_hidden_enabled,
          'conditional_hidden_product_id',v_mold.conditional_hidden_product_id,
          'conditional_hidden_value',v_conditional_hidden_applied,
          'hidden_value_total',round(v_basket_unit-v_basket_fiscal_unit,2),
          'hidden_value_preserved',true,
          'component_snapshot',v_component_snapshot,'image_url',coalesce(v_basket.image_url,'')
        )
      ));
      v_sep_rows:=v_sep_rows||jsonb_build_array(jsonb_build_object(
        'basket_id',v_basket.id,'basket_name',v_basket.name,'quantity',v_line_qty,
        'mold',jsonb_build_object('mode','loose','mold_id',v_mold.id,'composition_number',v_composition_number,
          'hidden_value_fixed',v_mold.hidden_adjustment,
          'conditional_hidden_value',v_conditional_hidden_applied,
          'hidden_value_total',round(v_basket_unit-v_basket_fiscal_unit,2),
          'components',v_component_snapshot)
      ));
      continue;
    end if;

  end loop;

  if v_expected_total_cents is not null then
    v_actual_total_cents:=round(v_total*100)::bigint;
    if v_actual_total_cents<>v_expected_total_cents then
      raise exception 'checkout_price_changed'
        using detail=jsonb_build_object('actual_total_cents',v_actual_total_cents)::text;
    end if;
  end if;

  if v_total<75 and coalesce((v_customer->>'stock_adjusted_retry')::boolean,false)=false then raise exception 'minimum_order'; end if;

  for v_pair in select key,value from jsonb_each_text(v_loose_demand) loop
    perform 1 from public.products where id=v_pair.key::uuid for update;
    if not found then
      raise exception 'product_unavailable'
        using detail=jsonb_build_object(
          'kind','product','product_id',v_pair.key::uuid,
          'requested',v_pair.value::numeric,'available',0,
          'reason','produto_nao_encontrado'
        )::text;
    end if;

    select coalesce(sum(nullif(item->>'quantity','')::numeric),0)
    into v_mold_component_demand
    from jsonb_array_elements(v_item_rows) as item
    where item->>'product_id'=v_pair.key
      and item#>>'{metadata,history_kind}'='basket_mold_component';

    if coalesce((select p.is_active from public.products p where p.id=v_pair.key::uuid),false) then
      select case when stock_authority='bling' then loose_sellable_stock else coalesce(ean_sellable_stock,loose_sellable_stock) end into v_existing_stock
      from public.storefront_ean_sellable_stock_v1
      where product_id=v_pair.key::uuid and is_active=true;
      if not found then
        raise exception 'product_unavailable'
          using detail=jsonb_build_object(
            'kind',case when v_mold_component_demand=v_pair.value::numeric then 'basket_mold_component' else 'product' end,
            'product_id',v_pair.key::uuid,
            'requested',v_pair.value::numeric,'available',0,
            'reason','saldo_nao_encontrado'
          )::text;
      end if;
    else
      if v_mold_component_demand<>v_pair.value::numeric then
        raise exception 'product_unavailable'
          using detail=jsonb_build_object(
            'kind','basket_mold_component','product_id',v_pair.key::uuid,
            'requested',v_pair.value::numeric,'available',0,
            'reason','demanda_de_componente_invalida'
          )::text;
      end if;
      select public.basket_component_fresh_sellable_stock_v1(v_pair.key::uuid)
      into v_existing_stock;
    end if;

    if coalesce(v_existing_stock,0)<v_pair.value::numeric then
      if v_expected_total_cents is null and v_mold_component_demand=v_pair.value::numeric then
        select coalesce(jsonb_agg(
          case when item->>'product_id'=v_pair.key
            then jsonb_set(item,'{metadata}',
              coalesce(item->'metadata','{}'::jsonb)||jsonb_build_object(
                'manual_replacement_required',true,
                'manual_replacement_reason','aggregate_stock_shortage'
              ),true)
            else item end
          order by ordinal
        ),'[]'::jsonb)
        into v_item_rows
        from jsonb_array_elements(v_item_rows) with ordinality rows(item,ordinal);
      else
        raise exception 'insufficient_stock'
          using detail=jsonb_build_object(
            'kind',case when v_mold_component_demand=v_pair.value::numeric then 'basket_mold_component' else 'product' end,
            'product_id',v_pair.key::uuid,
            'requested',v_pair.value::numeric,
            'available',greatest(0,coalesce(v_existing_stock,0)),
            'reason','estoque_insuficiente'
          )::text;
      end if;
    end if;
  end loop;

  v_order_number:='DA-'||to_char(clock_timestamp() at time zone 'America/Cuiaba','YYMMDD')||'-'||upper(substr(replace(v_order_id::text,'-',''),1,8));
  v_addr:=jsonb_strip_nulls(jsonb_build_object(
    'customer_name',nullif(v_customer->>'display_name',''),'source_customer_id',v_customer_id,
    'phone',v_phone,'street',nullif(v_customer#>>'{address,street}',''),
    'number',nullif(v_customer#>>'{address,number}',''),'complement',nullif(v_customer#>>'{address,complement}',''),
    'district',coalesce(nullif(v_customer#>>'{address,district}',''),nullif(v_customer#>>'{address,neighborhood}','')),
    'city',nullif(v_customer#>>'{address,city}',''),'state',nullif(v_customer#>>'{address,state}',''),
    'postal_code',nullif(v_customer#>>'{address,postal_code}',''),'raw_text',nullif(v_customer#>>'{address,raw_text}',''),
    'google_maps_url',nullif(v_customer#>>'{address,google_maps_url}',''),
    'delivery_date',nullif(v_delivery->>'date',''),'delivery_label',nullif(v_delivery->>'label',''),
    'delivery_reason',nullif(v_delivery->>'reason',''),'delivery_time_zone',nullif(v_delivery->>'time_zone',''),
    'delivery_cutoff_hour',v_delivery->'cutoff_hour'
  ));

  insert into public.orders(
    id,customer_id,status,total,currency,delivery_address,customer_snapshot,confirmed_at,
    created_at,updated_at,basket_id,fiscal_subtotal,other_expenses,discount,sync_status,
    idempotency_key,payment_method,phone_e164,source,subtotal,order_number,basket_name_snapshot,
    checkout_snapshot
  ) values(
    v_order_id,v_customer_id,'storefront_received',round(v_total,2),'BRL',coalesce(v_addr,'{}'::jsonb),
    jsonb_strip_nulls(jsonb_build_object(
      'customer_id',v_customer_id,'name',nullif(v_customer->>'display_name',''),
      'phone_e164',v_phone,'status',case when v_customer_id is null then 'new' else 'registered' end
    )),
    null,now(),now(),
    case when array_length(v_basket_names,1)=1 then v_first_basket else null end,
    round(v_fiscal,2),greatest(round(v_total-v_fiscal,2),0),greatest(round(v_fiscal-v_total,2),0),
    'local','vitrine-direct-v3:'||v_order_id::text,v_payment_code,v_phone,'vitrine',
    round(v_total,2),v_order_number,
    case when array_length(v_basket_names,1)=1 then v_basket_names[1] else null end,
    jsonb_build_object(
      'source','vitrine_direct','cart',v_cart,'payment_label',v_payment_label,
      'delivery',v_delivery,'customer',v_customer,'basket_names',to_jsonb(v_basket_names),
      'separation_plan',v_sep_rows,'hidden_value_preserved',true
    )
  );

  for v_line in select value from jsonb_array_elements(v_item_rows) loop
    insert into public.order_items(order_id,product_id,sku_snapshot,name_snapshot,quantity,unit_price,line_total,metadata)
    values(
      v_order_id,
      case when nullif(v_line->>'product_id','') is null then null else (v_line->>'product_id')::uuid end,
      nullif(v_line->>'sku',''),v_line->>'name',
      (v_line->>'quantity')::numeric,(v_line->>'unit_price')::numeric,(v_line->>'line_total')::numeric,
      coalesce(v_line->'metadata','{}'::jsonb)
    );
  end loop;

  return jsonb_build_object(
    'order_id',v_order_id,'order_number',v_order_number,
    'total_cents',round(v_total*100)::bigint,'total',round(v_total,2),
    'customer_id',v_customer_id,'phone_e164',v_phone,'payment_method',v_payment_label,
    'separation_plan',v_sep_rows,'hidden_value_preserved',true
  );
end;
$function$
;

-- function: customer_ids_by_phone_variants_v1(p_phone text)
CREATE OR REPLACE FUNCTION public.customer_ids_by_phone_variants_v1(p_phone text)
 RETURNS TABLE(customer_id uuid)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with vars as (
    select public.phone_variants_br(p_phone) as variants
  ), ids as (
    select c.id as customer_id
      from public.customers c, vars v
     where public.normalize_phone_digits(c.primary_whatsapp_e164)=any(v.variants)
    union
    select cp.customer_id
      from public.customer_phones cp, vars v
     where public.normalize_phone_digits(cp.phone_e164)=any(v.variants)
  )
  select customer_id from ids order by customer_id
$function$
;

-- function: customer_person_first_name_v1(p_name text, p_cpf_cnpj text)
CREATE OR REPLACE FUNCTION public.customer_person_first_name_v1(p_name text, p_cpf_cnpj text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  n text:=trim(regexp_replace(coalesce(p_name,''),'\s+',' ','g'));
  d text:=regexp_replace(coalesce(p_cpf_cnpj,''),'\D','','g');
  low text;
  first_name text;
begin
  if n='' or length(n)>120 then return null; end if;
  if length(d)=14 then return null; end if;
  low:=translate(lower(n),'áàãâäéèêëíìîïóòõôöúùûüç','aaaaaeeeeiiiiooooouuuuc');
  if low ~ '(^| )(ltda|eireli|empresa|comercio|comercial|mercado|supermercado|atacado|varejo|distribuidora|distribuidor|cesta|cestas|super cestas|dona antonia|loja|store|shop)( |$)' then return null; end if;
  if n !~ '^[[:alpha:]][[:alpha:] ''-]{1,119}$' then return null; end if;
  first_name:=split_part(n,' ',1);
  if length(first_name)<2 then return null; end if;
  return initcap(lower(first_name));
end $function$
;

-- function: customer_phone_primary_guard()
CREATE OR REPLACE FUNCTION public.customer_phone_primary_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_primary text;
begin
  select c.primary_whatsapp_e164
    into v_primary
    from public.customers c
   where c.id = new.customer_id;

  new.is_primary := (
    nullif(public.normalize_phone_digits(new.phone_e164),'') is not null
    and public.normalize_phone_digits(new.phone_e164) = public.normalize_phone_digits(v_primary)
  );
  return new;
end;
$function$
;

-- function: customers_link_unclaimed_orders_v2()
CREATE OR REPLACE FUNCTION public.customers_link_unclaimed_orders_v2()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform public.link_unclaimed_orders_to_customer_v2(new.id);
  return new;
end;
$function$
;

-- function: da6_worker_dispatch_tick_v1()
CREATE OR REPLACE FUNCTION public.da6_worker_dispatch_tick_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_pending boolean;v_secret text;v_request_id bigint;
BEGIN
 IF NOT pg_try_advisory_xact_lock(hashtextextended('inventory-label-worker-da6-v1',0)) THEN
  RETURN jsonb_build_object('ok',true,'no_op',true,'reason','tick_locked');
 END IF;
 SELECT EXISTS(
  SELECT 1 FROM public.inventory_label_photos
  WHERE (status IN ('queued','retry') AND attempts<3 AND COALESCE(next_attempt_at,now())<=now())
    OR (status='processing' AND claimed_at<now()-interval '5 minutes')
 ) INTO v_pending;
 IF NOT v_pending THEN RETURN jsonb_build_object('ok',true,'no_op',true,'reason','queue_empty');END IF;
 SELECT decrypted_secret INTO v_secret FROM vault.decrypted_secrets
  WHERE name='da6_label_worker_key_v1';
 IF v_secret IS NULL THEN RETURN jsonb_build_object('ok',false,'error','worker_key_missing');END IF;
 SELECT net.http_post(
  url:='https://ssbesxgaijknwsjbsbcz.supabase.co/functions/v1/admin-products-live-v1?action=inventory_label_worker_tick',
  headers:=jsonb_build_object('Content-Type','application/json','x-da6-worker-key',v_secret),
  body:='{"limit":3}'::jsonb,
  timeout_milliseconds:=55000
 ) INTO v_request_id;
 RETURN jsonb_build_object('ok',true,'queued',true,'request_id',v_request_id);
END $function$
;

-- function: da6_worker_key_v1()
CREATE OR REPLACE FUNCTION public.da6_worker_key_v1()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_key text;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN
  RAISE EXCEPTION 'worker_only' USING ERRCODE='42501';
 END IF;
 SELECT decrypted_secret INTO v_key FROM vault.decrypted_secrets WHERE name='da6_label_worker_key_v1';
 IF nullif(v_key,'') IS NULL THEN RAISE EXCEPTION 'worker_key_missing'; END IF;
 RETURN v_key;
END $function$
;

-- function: da_instagram_automation_cron_authorized_v1(p_token text)
CREATE OR REPLACE FUNCTION public.da_instagram_automation_cron_authorized_v1(p_token text)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'extensions', 'pg_temp'
AS $function$
  SELECT p_token IS NOT NULL
    AND length(p_token) BETWEEN 32 AND 256
    AND EXISTS (
      SELECT 1
      FROM private.da_instagram_automation_cron_token_v1 t
      WHERE t.id=1
        AND t.token_hash=encode(extensions.digest(convert_to(p_token,'UTF8'),'sha256'),'hex')
    );
$function$
;

-- function: da_instagram_materialize_due_v1(p_now timestamp with time zone)
CREATE OR REPLACE FUNCTION public.da_instagram_materialize_due_v1(p_now timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_created jsonb;
BEGIN
  WITH due AS (
    SELECT a.id AS automation_id,
           a.name AS automation_name,
           a.content_format,
           a.source_type,
           a.products_per_post,
           a.caption_template,
           (clock_data.local_now::date + slot.schedule_time::time) AT TIME ZONE a.time_zone AS scheduled_for
    FROM public.da_instagram_automations_v1 a
    CROSS JOIN LATERAL unnest(a.schedule_times) AS slot(schedule_time)
    CROSS JOIN LATERAL (SELECT p_now AT TIME ZONE a.time_zone AS local_now) AS clock_data
    WHERE a.status='active'
      AND slot.schedule_time ~ '^(?:[01][0-9]|2[0-3]):(?:00|05|10|15|20|25|30|35|40|45|50|55)$'
      AND extract(isodow FROM clock_data.local_now)::smallint = ANY(a.schedule_days)
      AND clock_data.local_now >= (clock_data.local_now::date + slot.schedule_time::time)
      AND clock_data.local_now < (clock_data.local_now::date + slot.schedule_time::time) + interval '10 minutes'
  ),
  inserted AS (
    INSERT INTO public.da_instagram_jobs_v1 (
      automation_id, automation_name, content_format, source_type,
      scheduled_for, run_kind, products_per_post, caption
    )
    SELECT automation_id, automation_name, content_format, source_type,
           scheduled_for, 'scheduled', products_per_post, caption_template
    FROM due
    ON CONFLICT (automation_id, scheduled_for) DO NOTHING
    RETURNING id, automation_id, scheduled_for
  )
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'id',id,'automation_id',automation_id,'scheduled_for',scheduled_for
  )), '[]'::jsonb)
  INTO v_created
  FROM inserted;

  RETURN v_created;
END
$function$
;

-- function: da_offer_rotation_admin_v1(p_action text, p_payload jsonb)
CREATE OR REPLACE FUNCTION public.da_offer_rotation_admin_v1(p_action text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
DECLARE
  v_action text := lower(trim(coalesce(p_action,'')));
  v_payload jsonb := coalesce(p_payload,'{}'::jsonb);
  v_state private.da_offer_rotation_state_v1%ROWTYPE;
  v_was_enabled boolean;
  v_enabled boolean;
  v_daily_count integer;
  v_min_discount integer;
  v_max_discount integer;
  v_min_margin numeric(5,2);
  v_product_id uuid;
  v_removed integer := 0;
  v_today date := (now() AT TIME ZONE 'America/Cuiaba')::date;
  v_result jsonb;
BEGIN
  IF v_action='get' THEN
    RETURN private.da_offer_rotation_snapshot_v1();
  ELSIF v_action='save' THEN
    SELECT * INTO v_state FROM private.da_offer_rotation_state_v1 WHERE id=1 FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'daily offer rotation state missing'; END IF;

    v_enabled := coalesce((v_payload->>'enabled')::boolean,false);
    v_daily_count := nullif(v_payload->>'daily_product_count','')::integer;
    v_min_discount := nullif(v_payload->>'min_discount_percent','')::integer;
    v_max_discount := nullif(v_payload->>'max_discount_percent','')::integer;
    v_min_margin := nullif(v_payload->>'min_gross_margin_percent','')::numeric;

    IF v_daily_count IS NULL OR v_daily_count NOT BETWEEN 1 AND 100
      OR v_min_discount IS NULL OR v_min_discount NOT BETWEEN 5 AND 15
      OR v_max_discount IS NULL OR v_max_discount NOT BETWEEN v_min_discount AND 15
      OR v_min_margin IS NULL OR v_min_margin NOT BETWEEN 0 AND 50 THEN
      RETURN jsonb_build_object('status',400,'error','daily_offer_settings_invalid','message','Configuração de oferta diária inválida.');
    END IF;

    v_was_enabled := v_state.enabled IS TRUE;
    UPDATE private.da_offer_rotation_state_v1
    SET enabled=v_enabled,
        daily_product_count=v_daily_count,
        min_discount_percent=v_min_discount,
        max_discount_percent=v_max_discount,
        min_gross_margin_percent=v_min_margin,
        last_rotation_date=CASE WHEN v_enabled AND NOT v_was_enabled THEN NULL ELSE last_rotation_date END
    WHERE id=1;

    IF NOT v_enabled OR (v_enabled AND NOT v_was_enabled) THEN
      v_result := private.da_offer_rotation_run_v1(false);
    ELSIF v_state.daily_product_count IS DISTINCT FROM v_daily_count
      OR v_state.min_discount_percent IS DISTINCT FROM v_min_discount
      OR v_state.max_discount_percent IS DISTINCT FROM v_max_discount
      OR v_state.min_gross_margin_percent IS DISTINCT FROM v_min_margin THEN
      v_result := private.da_offer_rotation_run_v1(true);
    END IF;
    RETURN private.da_offer_rotation_snapshot_v1();
  ELSIF v_action='generate' THEN
    v_result := private.da_offer_rotation_run_v1(true);
    RETURN private.da_offer_rotation_snapshot_v1() || jsonb_build_object('run',v_result);
  ELSIF v_action='remove' THEN
    v_product_id := nullif(v_payload->>'product_id','')::uuid;
    IF v_product_id IS NULL THEN
      RETURN jsonb_build_object('status',400,'error','invalid_product_id','message','Produto inválido.');
    END IF;
    UPDATE public.products
    SET is_offer=false,
        offer_price=NULL,
        metadata=(coalesce(metadata,'{}'::jsonb)-'offer_source'-'offer_discount_percent'-'offer_starts_at'-'offer_ends_at'-'offer_rotation_date')
          || jsonb_build_object('daily_offer_excluded_date',v_today::text)
    WHERE id=v_product_id
      AND is_offer=true
      AND metadata->>'offer_source'='auto_rotation'
      AND metadata->>'offer_rotation_date'=v_today::text;
    GET DIAGNOSTICS v_removed=ROW_COUNT;
    IF v_removed=0 THEN
      RETURN jsonb_build_object('status',404,'error','daily_offer_not_found','message','Essa oferta diária já não está ativa.');
    END IF;
    RETURN private.da_offer_rotation_snapshot_v1() || jsonb_build_object('removed',true);
  END IF;

  RETURN jsonb_build_object('status',400,'error','daily_offer_action_invalid','message','Ação de oferta diária inválida.');
END
$function$
;

-- function: da_offer_status_images_cron_authorized_v1(p_token text)
CREATE OR REPLACE FUNCTION public.da_offer_status_images_cron_authorized_v1(p_token text)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'extensions', 'pg_temp'
AS $function$
  SELECT p_token IS NOT NULL
    AND length(p_token)>=32
    AND EXISTS (
      SELECT 1
      FROM private.da_offer_status_image_cron_token_v1 t
      WHERE t.id=1
        AND t.token_hash=encode(extensions.digest(convert_to(p_token,'UTF8'),'sha256'),'hex')
    );
$function$
;

-- function: da_offer_story_begin_publish_v1(p_offer_date date, p_image_number integer)
CREATE OR REPLACE FUNCTION public.da_offer_story_begin_publish_v1(p_offer_date date, p_image_number integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  UPDATE public.da_offer_story_publications_v1
  SET status='publishing',updated_at=now()
  WHERE offer_date=p_offer_date AND image_number=p_image_number
    AND status='container_created' AND creation_id IS NOT NULL;
  RETURN FOUND;
END
$function$
;

-- function: da_offer_story_claim_v1(p_offer_date date, p_image_number integer, p_source_path text)
CREATE OR REPLACE FUNCTION public.da_offer_story_claim_v1(p_offer_date date, p_image_number integer, p_source_path text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_row public.da_offer_story_publications_v1%ROWTYPE;
BEGIN
  IF p_offer_date IS NULL OR p_image_number IS NULL OR p_image_number < 1 OR p_image_number > 8
     OR p_source_path IS NULL OR length(p_source_path) > 300 THEN
    RAISE EXCEPTION 'invalid story publication key';
  END IF;

  INSERT INTO public.da_offer_story_publications_v1 (offer_date,image_number,source_path)
  VALUES (p_offer_date,p_image_number,p_source_path)
  ON CONFLICT (offer_date,image_number) DO NOTHING;

  SELECT * INTO v_row
  FROM public.da_offer_story_publications_v1
  WHERE offer_date=p_offer_date AND image_number=p_image_number
  FOR UPDATE;

  IF v_row.status IN ('creating','publishing') AND v_row.updated_at < now() - interval '5 minutes' THEN
    UPDATE public.da_offer_story_publications_v1
    SET status='needs_review',
        last_error='A execução anterior foi interrompida; confira o Instagram antes de tentar novamente.',
        updated_at=now()
    WHERE offer_date=p_offer_date AND image_number=p_image_number;
    RETURN jsonb_build_object(
      'action','needs_review',
      'status','needs_review',
      'last_error','A execução anterior foi interrompida; confira o Instagram antes de tentar novamente.'
    );
  END IF;

  IF v_row.status='published' THEN
    RETURN jsonb_build_object('action','skip','status','published');
  END IF;

  IF v_row.status IN ('creating','publishing') THEN
    RETURN jsonb_build_object('action','busy','status',v_row.status);
  END IF;

  IF v_row.status='container_created' THEN
    RETURN jsonb_build_object(
      'action','check_container',
      'status',v_row.status,
      'creation_id',v_row.creation_id
    );
  END IF;

  IF v_row.status IN ('pending','failed') AND v_row.attempt_count < 3 THEN
    UPDATE public.da_offer_story_publications_v1
    SET status='creating',
        source_path=p_source_path,
        attempt_count=attempt_count+1,
        creation_id=NULL,
        story_id=NULL,
        last_error=NULL,
        updated_at=now()
    WHERE offer_date=p_offer_date AND image_number=p_image_number
    RETURNING * INTO v_row;
    RETURN jsonb_build_object(
      'action','create',
      'status',v_row.status,
      'attempt_count',v_row.attempt_count
    );
  END IF;

  RETURN jsonb_build_object(
    'action',v_row.status,
    'status',v_row.status,
    'last_error',v_row.last_error,
    'attempt_count',v_row.attempt_count
  );
END
$function$
;

-- function: da_offer_story_container_created_v1(p_offer_date date, p_image_number integer, p_creation_id text)
CREATE OR REPLACE FUNCTION public.da_offer_story_container_created_v1(p_offer_date date, p_image_number integer, p_creation_id text)
