-- function: delete_admin_saved_card_v1(p_card_id uuid)
CREATE OR REPLACE FUNCTION public.delete_admin_saved_card_v1(p_card_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_id uuid;
begin
  if p_card_id is null then
    raise exception 'card_not_found';
  end if;

  update public.admin_saved_cards_v1 as c
  set deleted_at = now(), card_password = '', updated_at = now()
  where c.id = p_card_id and c.deleted_at is null
  returning c.id into v_id;

  if v_id is null then
    raise exception 'card_not_found';
  end if;

  return v_id;
end;
$function$
;

-- function: dispatch_bling_hub_cycle_v2()
CREATE OR REPLACE FUNCTION public.dispatch_bling_hub_cycle_v2()
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_request_id bigint;
  v_ean_recovery_id bigint;
  v_fiscal_request_id bigint;
begin
  if not exists(
    select 1
    from public.bling_hub_runtime_v2
    where id=1
      and hub_enabled=true
      and mode in ('homologation','live')
  ) then
    return null;
  end if;

  select net.http_post(
    url := 'https://ssbesxgaijknwsjbsbcz.supabase.co/functions/v1/admin-service-intelligence-v1',
    headers := jsonb_build_object(
      'Content-Type','application/json',
      'x-dona-antonia-bling-hub-key',public.get_bling_hub_key_v2()
    ),
    body := jsonb_build_object(
      'action','vitrine_bling_hub_internal',
      'subaction','process_cycle',
      'limit',3
    ),
    timeout_milliseconds := 55000
  ) into v_request_id;

  select net.http_post(
    url := 'https://ssbesxgaijknwsjbsbcz.supabase.co/functions/v1/admin-products-live-v1?action=ops2_recover_ean_verified',
    headers := jsonb_build_object(
      'Content-Type','application/json',
      'x-dona-antonia-bling-hub-key',public.get_bling_hub_key_v2()
    ),
    body := jsonb_build_object('limit',3),
    timeout_milliseconds := 55000
  ) into v_ean_recovery_id;

  if exists(
    select 1
    from public.fiscal_runtime_config f
    where f.id=1
      and f.enabled=true
      and f.execution_mode='live'
      and f.bling_invoice_send_enabled=true
      and f.dispatch_gate_mode='enforce'
      and f.dispatch_fiscal_auto_issue_enabled=true
  ) and exists(
    select 1
    from public.bling_hub_runtime_v2 h
    where h.id=1
      and h.hub_enabled=true
      and h.orders_enabled=true
      and h.mode='live'
  ) then
    select net.http_post(
      url := 'https://ssbesxgaijknwsjbsbcz.supabase.co/functions/v1/admin-service-intelligence-v1',
      headers := jsonb_build_object(
        'Content-Type','application/json',
        'x-dona-antonia-bling-hub-key',public.get_bling_hub_key_v2()
      ),
      body := jsonb_build_object(
        'action','vitrine_bling_hub_internal',
        'subaction','fiscal_dispatch_auto_process',
        'limit',1
      ),
      timeout_milliseconds := 55000
    ) into v_fiscal_request_id;
  end if;

  return v_request_id;
end;
$function$
;

-- function: dispatch_fiscal_bling_nfe_backfill_v1(p_steps integer)
CREATE OR REPLACE FUNCTION public.dispatch_fiscal_bling_nfe_backfill_v1(p_steps integer DEFAULT 4)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_steps integer := greatest(1,least(coalesce(p_steps,4),8));
  v_status text;
  v_request_id bigint;
begin
  select s.status into v_status
  from public.fiscal_source_scan_state s
  where s.source='bling_nfe_entry_xml';

  if coalesce(v_status,'done') <> 'running' then
    return null;
  end if;

  select net.http_post(
    url := 'https://ssbesxgaijknwsjbsbcz.supabase.co/functions/v1/admin-service-intelligence-v1',
    headers := jsonb_build_object(
      'Content-Type','application/json',
      'x-dona-antonia-bling-hub-key',public.get_bling_hub_key_v2()
    ),
    body := jsonb_build_object(
      'action','vitrine_bling_hub_internal',
      'subaction','fiscal_nfe_entry_backfill',
      'steps',v_steps
    ),
    timeout_milliseconds := 120000
  ) into v_request_id;

  return v_request_id;
end;
$function$
;

-- function: dispatch_fiscal_nfe_autorecovery_v1()
CREATE OR REPLACE FUNCTION public.dispatch_fiscal_nfe_autorecovery_v1()
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_req bigint;
begin
  if not exists(
    select 1 from public.fiscal_nfe_recovery_control_v1 where id=true and enabled=true
  ) then return null; end if;
  if not exists(
    select 1 from public.bling_hub_runtime_v2
    where id=1 and mode='live' and hub_enabled=true and orders_enabled=true
  ) then return null; end if;
  select net.http_post(
    url := 'https://ssbesxgaijknwsjbsbcz.supabase.co/functions/v1/admin-service-intelligence-v1',
    headers := jsonb_build_object('Content-Type','application/json','x-dona-antonia-bling-hub-key',public.get_bling_hub_key_v2()),
    body := jsonb_build_object('action','vitrine_bling_hub_internal','subaction','fiscal_nfe_autorecovery_v1','limit',2),
    timeout_milliseconds := 55000
  ) into v_req;
  return v_req;
end $function$
;

