-- function: ean_capture_resolve_v1(p_capture_id uuid, p_mode text, p_product_id uuid, p_name text, p_ncm text)
CREATE OR REPLACE FUNCTION public.ean_capture_resolve_v1(p_capture_id uuid, p_mode text, p_product_id uuid DEFAULT NULL::uuid, p_name text DEFAULT NULL::text, p_ncm text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_capture public.ean_capture_records_v1%rowtype;
  v_product public.products%rowtype;
  v_owner uuid;
  v_ean text;
  v_ncm text;
  v_name text;
begin
  if p_mode not in ('link','create') then
    return jsonb_build_object('ok',false,'error','modo_invalido');
  end if;
  select * into v_capture
    from public.ean_capture_records_v1
   where id=p_capture_id
   for update;
  if not found then return jsonb_build_object('ok',false,'error','leitura_nao_encontrada'); end if;
  if v_capture.sync_status <> 'not_found' then
    return jsonb_build_object('ok',false,'error','leitura_nao_esta_na_fila');
  end if;
  v_ean:=v_capture.ean;
  v_ncm:=nullif(regexp_replace(coalesce(p_ncm,''),'\D','','g'),'');
  if v_ncm is not null and v_ncm !~ '^\d{8}$' then
    return jsonb_build_object('ok',false,'error','ncm_invalido');
  end if;

  if p_mode='link' then
    if p_product_id is null then return jsonb_build_object('ok',false,'error','produto_invalido'); end if;
    select * into v_product from public.products where id=p_product_id for update;
    if not found then return jsonb_build_object('ok',false,'error','produto_nao_encontrado'); end if;
    if v_product.is_active is not true then return jsonb_build_object('ok',false,'error','produto_inativo'); end if;

    select p.id into v_owner
      from public.products p
     where regexp_replace(coalesce(p.gtin,''),'\D','','g')=v_ean and p.id<>p_product_id
     limit 1;
    if v_owner is not null then return jsonb_build_object('ok',false,'error','ean_principal_de_outro_produto'); end if;
    select pi.product_id into v_owner
      from public.product_identifiers pi
     where pi.identifier_value=v_ean and pi.status='confirmed'
       and pi.identifier_kind in ('base_gtin','package_gtin','sku_alias')
       and pi.product_id<>p_product_id
     limit 1;
    if v_owner is not null then return jsonb_build_object('ok',false,'error','ean_vinculado_a_outro_produto'); end if;

    if regexp_replace(coalesce(v_product.gtin,''),'\D','','g')<>v_ean then
      insert into public.product_identifiers(
        product_id,identifier_value,identifier_kind,source,confidence,status,metadata
      ) values (
        p_product_id,v_ean,'base_gtin','ean_capture_admin',1,'confirmed',
        jsonb_build_object('capture_id',p_capture_id,'captured_at',v_capture.created_at)
      ) on conflict do nothing;
    end if;
    update public.products
       set stock=coalesce(stock,0)+v_capture.quantity,
           ncm=coalesce(v_ncm,ncm),
           last_admin_edit_at=now(),
           last_admin_edit_by=v_capture.created_by
     where id=p_product_id
     returning * into v_product;
  else
    v_name:=nullif(btrim(coalesce(p_name,'')),'');
    if v_name is null then return jsonb_build_object('ok',false,'error','nome_obrigatorio'); end if;
    select p.id into v_owner
      from public.products p
     where regexp_replace(coalesce(p.gtin,''),'\D','','g')=v_ean
     limit 1;
    if v_owner is not null then return jsonb_build_object('ok',false,'error','ean_ja_cadastrado'); end if;
    select pi.product_id into v_owner
      from public.product_identifiers pi
     where pi.identifier_value=v_ean and pi.status='confirmed'
       and pi.identifier_kind in ('base_gtin','package_gtin','sku_alias')
     limit 1;
    if v_owner is not null then return jsonb_build_object('ok',false,'error','ean_ja_vinculado'); end if;

    insert into public.products(name,gtin,ncm,stock,is_active,source_system,sync_status,metadata)
    values(v_name,v_ean,v_ncm,0,false,'ean_capture_admin','local',
      jsonb_build_object('created_from_ean_capture',p_capture_id,'requires_admin_review',true))
    returning * into v_product;
    insert into public.product_identifiers(
      product_id,identifier_value,identifier_kind,source,confidence,status,metadata
    ) values (
      v_product.id,v_ean,'base_gtin','ean_capture_admin',1,'confirmed',
      jsonb_build_object('capture_id',p_capture_id,'captured_at',v_capture.created_at)
    ) on conflict do nothing;
  end if;

  update public.ean_capture_records_v1
     set matched_product_id=v_product.id,sync_status='found',synced_at=now(),updated_at=now()
   where id=p_capture_id
   returning * into v_capture;

  return jsonb_build_object(
    'ok',true,
    'row',jsonb_build_object(
      'id',v_capture.id,'ean',v_capture.ean,'quantity',v_capture.quantity,
      'expires_on',v_capture.expires_on,'sync_status',v_capture.sync_status,
      'matched_product_id',v_capture.matched_product_id,'photo_path',v_capture.photo_path,
      'photo_captured_at',v_capture.photo_captured_at,'created_at',v_capture.created_at,
      'updated_at',v_capture.updated_at,'synced_at',v_capture.synced_at
    ),
    'summary',public.ean_capture_stats_v1(),
    'product',jsonb_build_object('id',v_product.id,'name',v_product.name,'stock',v_product.stock,'is_active',v_product.is_active)
  );
end;
$function$
;

-- function: ean_capture_resolve_v2(p_capture_id uuid, p_mode text, p_product_id uuid, p_name text, p_ncm text, p_attributes jsonb)
CREATE OR REPLACE FUNCTION public.ean_capture_resolve_v2(p_capture_id uuid, p_mode text, p_product_id uuid DEFAULT NULL::uuid, p_name text DEFAULT NULL::text, p_ncm text DEFAULT NULL::text, p_attributes jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_capture public.ean_capture_records_v1%rowtype;
  v_product public.products%rowtype;
  v_owner uuid;
  v_ean text;
  v_ncm text;
  v_name text;
  v_attrs jsonb := coalesce(p_attributes,'{}'::jsonb);
  v_cest text;
  v_brand text;
  v_category text;
  v_description text;
  v_image text;
begin
  if p_mode not in ('link','create') then
    return jsonb_build_object('ok',false,'error','modo_invalido');
  end if;
  select * into v_capture from public.ean_capture_records_v1 where id=p_capture_id for update;
  if not found then return jsonb_build_object('ok',false,'error','leitura_nao_encontrada'); end if;
  if v_capture.sync_status <> 'not_found' then
    return jsonb_build_object('ok',false,'error','leitura_nao_esta_na_fila');
  end if;
  v_ean:=v_capture.ean;
  v_ncm:=nullif(regexp_replace(coalesce(p_ncm,''),'[^0-9]','','g'),'');
  if v_ncm is not null and v_ncm !~ '^[0-9]{8}$' then
    return jsonb_build_object('ok',false,'error','ncm_invalido');
  end if;
  if p_mode='link' then
    if p_product_id is null then return jsonb_build_object('ok',false,'error','produto_invalido'); end if;
    select * into v_product from public.products where id=p_product_id for update;
    if not found then return jsonb_build_object('ok',false,'error','produto_nao_encontrado'); end if;
    if v_product.is_active is not true then return jsonb_build_object('ok',false,'error','produto_inativo'); end if;
    select p.id into v_owner from public.products p
      where regexp_replace(coalesce(p.gtin,''),'[^0-9]','','g')=v_ean and p.id<>p_product_id limit 1;
    if v_owner is not null then return jsonb_build_object('ok',false,'error','ean_principal_de_outro_produto'); end if;
    select pi.product_id into v_owner from public.product_identifiers pi
      where pi.identifier_value=v_ean and pi.status='confirmed'
        and pi.identifier_kind in ('base_gtin','package_gtin','sku_alias') and pi.product_id<>p_product_id limit 1;
    if v_owner is not null then return jsonb_build_object('ok',false,'error','ean_vinculado_a_outro_produto'); end if;
    if regexp_replace(coalesce(v_product.gtin,''),'[^0-9]','','g')<>v_ean then
      insert into public.product_identifiers(product_id,identifier_value,identifier_kind,source,confidence,status,metadata)
      values(p_product_id,v_ean,'base_gtin','ean_capture_admin',1,'confirmed',
        jsonb_build_object('capture_id',p_capture_id,'captured_at',v_capture.created_at)) on conflict do nothing;
    end if;
    update public.products set stock=v_capture.quantity,
      ncm=coalesce(v_ncm,ncm),last_admin_edit_at=now(),last_admin_edit_by=v_capture.created_by
      where id=p_product_id returning * into v_product;
  else
    v_name:=nullif(btrim(coalesce(p_name,v_attrs->>'name','')),'');
    if v_name is null then return jsonb_build_object('ok',false,'error','nome_obrigatorio'); end if;
    if length(v_name)>180 then return jsonb_build_object('ok',false,'error','nome_invalido'); end if;
    select p.id into v_owner from public.products p
      where regexp_replace(coalesce(p.gtin,''),'[^0-9]','','g')=v_ean limit 1;
    if v_owner is not null then return jsonb_build_object('ok',false,'error','ean_ja_cadastrado'); end if;
    select pi.product_id into v_owner from public.product_identifiers pi
      where pi.identifier_value=v_ean and pi.status='confirmed'
        and pi.identifier_kind in ('base_gtin','package_gtin','sku_alias') limit 1;
    if v_owner is not null then return jsonb_build_object('ok',false,'error','ean_ja_vinculado'); end if;
    v_cest:=nullif(regexp_replace(coalesce(v_attrs->>'cest',''),'[^0-9]','','g'),'');
    if v_cest is not null and v_cest !~ '^[0-9]{7}$' then
      return jsonb_build_object('ok',false,'error','cest_invalido');
    end if;
    v_brand:=left(nullif(btrim(v_attrs->>'brand'),''),100);
    v_category:=left(nullif(btrim(v_attrs->>'category'),''),160);
    v_description:=left(nullif(btrim(v_attrs->>'description'),''),1000);
    v_image:=nullif(v_attrs->>'image_url','');
    if v_image !~ '^https://cdn-cosmos[.]bluesoft[.]com[.]br/' then v_image:=null; end if;
    insert into public.products(
      name,gtin,ncm,stock,validity_date,is_active,source_system,sync_status,metadata,
      brand,category,subcategory,description_short,description_long,image_url,image_original_url,
      image_source_url,image_source_origin,unit,packaging,supplier
    ) values(
      v_name,v_ean,v_ncm,v_capture.quantity,v_capture.expires_on,false,'ean_capture_admin','local',
      jsonb_build_object(
        'created_from_ean_capture',p_capture_id,'requires_admin_review',true,
        'cest',v_cest,'cosmos_gpc',left(coalesce(v_attrs->>'gpc',''),40),
        'cosmos_net_weight_raw',v_attrs->'net_weight_raw',
        'cosmos_gross_weight_raw',v_attrs->'gross_weight_raw',
        'cosmos_researched_at',v_attrs->>'researched_at',
        'cosmos_unit_description',left(coalesce(v_attrs->>'unit_description',''),80)
      ),
      v_brand,v_category,left(nullif(btrim(v_attrs->>'subcategory'),''),160),
      v_description,v_description,v_image,v_image,v_image,
      case when v_image is not null then 'cosmos' else null end,
      left(nullif(btrim(v_attrs->>'unit'),''),24),
      left(nullif(btrim(v_attrs->>'packaging'),''),100),
      left(nullif(btrim(v_attrs->>'manufacturer'),''),120)
    ) returning * into v_product;
    insert into public.product_identifiers(product_id,identifier_value,identifier_kind,source,confidence,status,metadata)
      values(v_product.id,v_ean,'base_gtin','ean_capture_admin',1,'confirmed',
        jsonb_build_object('capture_id',p_capture_id,'captured_at',v_capture.created_at)) on conflict do nothing;
  end if;
  update public.ean_capture_records_v1 set matched_product_id=v_product.id,sync_status='found',synced_at=now(),updated_at=now()
    where id=p_capture_id returning * into v_capture;
  return jsonb_build_object('ok',true,
    'row',jsonb_build_object('id',v_capture.id,'ean',v_capture.ean,'quantity',v_capture.quantity,
      'expires_on',v_capture.expires_on,'sync_status',v_capture.sync_status,'matched_product_id',v_capture.matched_product_id,
      'photo_path',v_capture.photo_path,'photo_captured_at',v_capture.photo_captured_at,'created_at',v_capture.created_at,
      'updated_at',v_capture.updated_at,'synced_at',v_capture.synced_at),
    'summary',public.ean_capture_stats_v1(),
    'product',jsonb_build_object('id',v_product.id,'name',v_product.name,'stock',v_product.stock,'is_active',v_product.is_active));
end;
$function$
;

-- function: ean_capture_stats_v1()
CREATE OR REPLACE FUNCTION public.ean_capture_stats_v1()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'total',count(*),
    'pending',count(*) filter(where sync_status='pending'),
    'found',count(*) filter(where sync_status='found'),
    'not_found',count(*) filter(where sync_status='not_found'),
    'quantity',coalesce(sum(quantity),0)
  ) from public.ean_capture_records_v1;
$function$
;

-- function: ean_capture_sync_one_v1(p_capture_id uuid)
CREATE OR REPLACE FUNCTION public.ean_capture_sync_one_v1(p_capture_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_row public.ean_capture_records_v1%rowtype;
  v_old_status text;
  v_old_product_id uuid;
  v_latest_quantity numeric;
BEGIN
  SELECT e.sync_status,e.matched_product_id
    INTO v_old_status,v_old_product_id
  FROM public.ean_capture_records_v1 e
  WHERE e.id=p_capture_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'error','leitura_nao_encontrada');
  END IF;

  UPDATE public.ean_capture_records_v1 e
  SET matched_product_id=(
        SELECT found.product_id
        FROM (
          SELECT p.id AS product_id,0 AS priority
          FROM public.products p WHERE p.gtin=e.ean
          UNION ALL
          SELECT pi.product_id,1 AS priority
          FROM public.product_identifiers pi
          WHERE pi.identifier_value=e.ean AND pi.status='confirmed'
        ) found
        ORDER BY found.priority,found.product_id
        LIMIT 1
      ),
      synced_at=now(),
      updated_at=now()
  WHERE e.id=p_capture_id
  RETURNING * INTO v_row;

  UPDATE public.ean_capture_records_v1
  SET sync_status=CASE WHEN v_row.matched_product_id IS NULL THEN 'not_found' ELSE 'found' END,
      updated_at=now()
  WHERE id=v_row.id
  RETURNING * INTO v_row;

  IF v_row.matched_product_id IS NOT NULL
     AND (v_old_status IS DISTINCT FROM 'found'
          OR v_old_product_id IS DISTINCT FROM v_row.matched_product_id) THEN
    SELECT e.quantity
      INTO v_latest_quantity
    FROM public.ean_capture_records_v1 e
    WHERE e.sync_status='found'
      AND e.matched_product_id=v_row.matched_product_id
    ORDER BY e.created_at DESC,e.id DESC
    LIMIT 1;

    UPDATE public.products
    SET stock=v_latest_quantity
    WHERE id=v_row.matched_product_id;
  END IF;

  RETURN jsonb_build_object(
    'ok',true,
    'row',jsonb_build_object(
       'id',v_row.id,'ean',v_row.ean,'quantity',v_row.quantity,
       'expires_on',v_row.expires_on,'sync_status',v_row.sync_status,
       'matched_product_id',v_row.matched_product_id,'photo_path',v_row.photo_path,
       'photo_captured_at',v_row.photo_captured_at,'created_at',v_row.created_at,
       'updated_at',v_row.updated_at,'synced_at',v_row.synced_at
    ),
    'summary',public.ean_capture_stats_v1()
  );
END;
$function$
;

-- function: ean_capture_sync_v1()
CREATE OR REPLACE FUNCTION public.ean_capture_sync_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_capture record;
  v_product_id uuid;
  v_old_status text;
  v_old_product_id uuid;
  v_latest_quantity numeric;
BEGIN
  FOR v_capture IN
    SELECT e.id,e.ean,e.sync_status,e.matched_product_id
    FROM public.ean_capture_records_v1 e
    ORDER BY e.created_at ASC,e.id ASC
    FOR UPDATE
  LOOP
    v_old_status:=v_capture.sync_status;
    v_old_product_id:=v_capture.matched_product_id;

    SELECT matches.product_id INTO v_product_id
    FROM (
      SELECT p.id AS product_id,0 AS priority
      FROM public.products p WHERE p.gtin=v_capture.ean
      UNION ALL
      SELECT pi.product_id,1 AS priority
      FROM public.product_identifiers pi
      WHERE pi.identifier_value=v_capture.ean AND pi.status='confirmed'
    ) matches
    ORDER BY matches.priority,matches.product_id
    LIMIT 1;

    UPDATE public.ean_capture_records_v1
    SET sync_status=CASE WHEN v_product_id IS NULL THEN 'not_found' ELSE 'found' END,
        matched_product_id=v_product_id,
        synced_at=now(),
        updated_at=now()
    WHERE id=v_capture.id;

    IF v_product_id IS NOT NULL
       AND (v_old_status IS DISTINCT FROM 'found'
            OR v_old_product_id IS DISTINCT FROM v_product_id) THEN
      SELECT e.quantity INTO v_latest_quantity
      FROM public.ean_capture_records_v1 e
      WHERE e.sync_status='found'
        AND e.matched_product_id=v_product_id
      ORDER BY e.created_at DESC,e.id DESC
      LIMIT 1;

      UPDATE public.products
      SET stock=v_latest_quantity
      WHERE id=v_product_id;
    END IF;
  END LOOP;

  RETURN public.ean_capture_stats_v1();
END;
$function$
;

-- function: enforce_basket_mold_position_option_limit_v1()
CREATE OR REPLACE FUNCTION public.enforce_basket_mold_position_option_limit_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_category text; v_count integer;
begin
  select cat.slug into v_category
  from public.basket_mold_positions pos
  join public.basket_molds m on m.id=pos.mold_id
  join public.basket_templates b on b.id=m.basket_id
  join public.basket_categories cat on cat.id=b.category_id
  where pos.id=new.position_id;
  if v_category='cestas-completas' then return new; end if;
  select count(*) into v_count from public.basket_mold_position_options where position_id=new.position_id;
  if v_count>=3 then raise exception 'basket_mold_position_options_limit'; end if;
  return new;
end;
$function$
;

-- function: enforce_order_dispatch_fiscal_gate_trigger_v1()
CREATE OR REPLACE FUNCTION public.enforce_order_dispatch_fiscal_gate_trigger_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  gate jsonb;
begin
  if new.status in ('out_for_delivery','delivered')
     and old.status not in ('out_for_delivery','delivered') then
    gate:=public.check_order_dispatch_fiscal_gate_v1(new.id);
    if coalesce((gate->>'allowed')::boolean,false) is not true then
      raise exception 'fiscal_dispatch_not_authorized:%',new.id
        using errcode='P0001',detail=coalesce(gate::text,'{}'),hint='Authorize o documento fiscal e conclua a baixa física antes da saída.';
    end if;
  end if;
  return new;
end;
$function$
;

-- function: enforce_storefront_checkout_basics_v1()
CREATE OR REPLACE FUNCTION public.enforce_storefront_checkout_basics_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(new.source, '') <> 'vitrine' then
    return new;
  end if;

  if nullif(btrim(coalesce(new.phone_e164, '')), '') is null
     or nullif(btrim(coalesce(new.payment_method, '')), '') is null
     or nullif(btrim(coalesce(new.delivery_address->>'delivery_date', '')), '') is null then
    raise exception 'required_checkout_data' using errcode = 'P0001';
  end if;

  return new;
end;
$function$
;

-- function: enforce_zero_stock_inactive()
CREATE OR REPLACE FUNCTION public.enforce_zero_stock_inactive()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_authority text:='legacy_shadow';
  v_keep_active boolean:=false;
begin
  select coalesce(metadata->>'ops2_stock_authority','legacy_shadow')
    into v_authority
  from public.bling_hub_runtime_v2 where id=1;
  v_authority:=coalesce(v_authority,'legacy_shadow');

  if new.stock is not null and new.stock<=0 then
    v_keep_active:=public.handle_basket_product_unavailable_v1(new.id);
    if v_keep_active then
      new.is_active:=true;
    elsif v_authority<>'bling' then
      new.is_active:=false;
    end if;
  elsif new.is_active is false then
    v_keep_active:=public.handle_basket_product_unavailable_v1(new.id);
    if v_keep_active then
      new.is_active:=true;
    end if;
  elsif exists(
    select 1
    from public.basket_mold_position_options opt
    join public.basket_mold_positions pos on pos.id=opt.position_id
    join public.basket_molds mold on mold.id=pos.mold_id
    join public.basket_templates basket on basket.id=mold.basket_id and basket.is_active=true
    where opt.product_id=new.id
      and coalesce(public.basket_component_fresh_sellable_stock_v1(new.id),0)<pos.quantity
  ) then
    -- Bling-backed sellable stock can reach zero while products.stock stays positive.
    v_keep_active:=public.handle_basket_product_unavailable_v1(new.id);
    if v_keep_active then
      new.is_active:=true;
    end if;
  end if;

  return new;
end
$function$
;

-- function: enqueue_bling_hub_job_v2(p_domain text, p_operation text, p_source_system text, p_source_id text, p_idempotency_key text, p_payload jsonb, p_payload_version integer)
CREATE OR REPLACE FUNCTION public.enqueue_bling_hub_job_v2(p_domain text, p_operation text, p_source_system text, p_source_id text, p_idempotency_key text, p_payload jsonb DEFAULT '{}'::jsonb, p_payload_version integer DEFAULT 1)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid;
  v_max integer;
begin
  if p_domain not in ('product','stock','customer','order','webhook','fiscal') then
    raise exception 'invalid_domain';
  end if;
  if nullif(trim(coalesce(p_operation,'')),'') is null then raise exception 'operation_required'; end if;
  if nullif(trim(coalesce(p_source_system,'')),'') is null then raise exception 'source_system_required'; end if;
  if nullif(trim(coalesce(p_source_id,'')),'') is null then raise exception 'source_id_required'; end if;
  if nullif(trim(coalesce(p_idempotency_key,'')),'') is null then raise exception 'idempotency_key_required'; end if;

  select max_attempts into v_max from public.bling_hub_runtime_v2 where id=1;

  if p_domain='stock' and trim(p_operation)='set_stock' then
    select j.id
      into v_id
      from public.bling_hub_jobs_v2 j
     where j.domain='stock'
       and j.operation='set_stock'
       and j.source_system=trim(p_source_system)
       and j.source_id=trim(p_source_id)
       and j.status in ('pending','retry','review_required','failed')
     order by j.created_at desc,j.id desc
     for update
     limit 1;

    if v_id is not null then
      update public.bling_hub_jobs_v2
         set payload=coalesce(p_payload,'{}'::jsonb),
             payload_version=greatest(1,coalesce(p_payload_version,1)),
             status='pending',
             attempts=0,
             max_attempts=coalesce(v_max,5),
             next_attempt_at=now(),
             locked_at=null,
             locked_by=null,
             result='{}'::jsonb,
             error_code=null,
             error_message=null,
             last_http_status=null,
             finished_at=null,
             updated_at=now()
       where id=v_id;
      return v_id;
    end if;
  end if;

  insert into public.bling_hub_jobs_v2(
    domain,operation,source_system,source_id,idempotency_key,payload_version,payload,max_attempts
  ) values(
    p_domain,trim(p_operation),trim(p_source_system),trim(p_source_id),trim(p_idempotency_key),
    greatest(1,coalesce(p_payload_version,1)),coalesce(p_payload,'{}'::jsonb),coalesce(v_max,5)
  )
  on conflict(idempotency_key) do update set
    payload=excluded.payload,
    payload_version=excluded.payload_version,
    updated_at=now()
  where public.bling_hub_jobs_v2.status in ('pending','retry','review_required','failed')
  returning id into v_id;

  if v_id is null then
    select id into v_id
      from public.bling_hub_jobs_v2
     where idempotency_key=trim(p_idempotency_key);
  end if;
  return v_id;
end
$function$
;

-- function: enqueue_bling_hub_product_outbox_v1()
CREATE OR REPLACE FUNCTION public.enqueue_bling_hub_product_outbox_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_link public.bling_hub_entity_links_v2%rowtype;
  v_operation text;
  v_gtin text;
  v_key text;
  v_payload jsonb;
begin
  if tg_op = 'UPDATE' and
     row(new.name, new.sku, new.gtin, new.ncm, new.price, new.brand, new.unit,
         new.description_short, new.description_long, new.is_active,
         coalesce(new.metadata->>'brand',''), coalesce(new.metadata->>'unit',''))
       is not distinct from
     row(old.name, old.sku, old.gtin, old.ncm, old.price, old.brand, old.unit,
         old.description_short, old.description_long, old.is_active,
         coalesce(old.metadata->>'brand',''), coalesce(old.metadata->>'unit','')) then
    return new;
  end if;

  v_gtin := regexp_replace(coalesce(new.gtin, ''), '[^0-9]', '', 'g');
  if nullif(btrim(coalesce(new.gtin, '')), '') is null
     and private.bling_hub_valid_gtin_from_sku_v1(new.sku) then
    v_gtin := btrim(new.sku);
  end if;

  select *
    into v_link
    from public.bling_hub_entity_links_v2
   where source_system = 'vitrine_qx'
     and entity_type = 'product'
     and source_id = new.id::text
   limit 1;

  if found then
    if v_link.status = 'matched' and coalesce(v_link.bling_id, 0) > 0 then
      v_operation := 'sync_product';
    elsif v_link.status = 'not_found'
      and new.is_active = true
      and length(v_gtin) in (8, 12, 13, 14) then
      v_operation := 'create_product';
    else
      return new;
    end if;
  elsif new.is_active = true and length(v_gtin) in (8, 12, 13, 14) then
    v_operation := 'create_product';
  else
    return new;
  end if;

  v_key := 'supabase:vitrine:product:' || v_operation || ':' || new.id::text || ':' ||
    to_char(coalesce(new.updated_at, now()) at time zone 'UTC', 'YYYYMMDDHH24MISSUS');

  v_payload := jsonb_build_object(
    'product', jsonb_build_object(
      'id', new.id,
      'sku', coalesce(new.sku, ''),
      'gtin', coalesce(nullif(btrim(new.gtin), ''), v_gtin),
      'ncm', coalesce(new.ncm, ''),
      'name', coalesce(new.name, ''),
      'description', coalesce(new.description_short, new.description_long, ''),
      'active', coalesce(new.is_active, false),
      'sale_price_cents', round(coalesce(new.price, 0) * 100)::bigint,
      'stock_quantity', coalesce(new.stock, 0),
      'image_url', coalesce(new.image_url, ''),
      'brand', coalesce(new.brand, new.metadata->>'brand', ''),
      'unit', coalesce(new.unit, new.metadata->>'unit', ''),
      'metadata', coalesce(new.metadata, '{}'::jsonb),
      'expiration_date', case when new.validity_date is null then null else to_char(new.validity_date, 'YYYY-MM-DD') end
    ),
    'requested_from', 'supabase_product_outbox_v1'
  );

  perform public.enqueue_bling_hub_job_v2(
    'product', v_operation, 'vitrine_qx', new.id::text, v_key, v_payload, 2
  );

  update public.products
     set sync_status = 'pending_bling',
         sync_error = null
   where id = new.id
     and (sync_status is distinct from 'pending_bling' or sync_error is not null);

  return new;
end
$function$
;

-- function: enqueue_bling_hub_stock_outbox_v1()
CREATE OR REPLACE FUNCTION public.enqueue_bling_hub_stock_outbox_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_link public.bling_hub_entity_links_v2%rowtype;
  v_key text;
begin
  if tg_op = 'UPDATE' and new.stock is not distinct from old.stock then
    return new;
  end if;

  select *
    into v_link
    from public.bling_hub_entity_links_v2
   where source_system = 'vitrine_qx'
     and entity_type = 'product'
     and source_id = new.id::text
   limit 1;

  if not found or v_link.status <> 'matched' or coalesce(v_link.bling_id, 0) <= 0 then
    return new;
  end if;

  v_key := 'supabase:vitrine:stock:' || new.id::text || ':' ||
    to_char(coalesce(new.updated_at, now()) at time zone 'UTC', 'YYYYMMDDHH24MISSUS');

  perform public.enqueue_bling_hub_job_v2(
    'stock',
    'set_stock',
    'vitrine_qx',
    new.id::text,
    v_key,
    jsonb_build_object('stock_quantity', coalesce(new.stock, 0), 'authority', 'supabase'),
    1
  );

  return new;
end
$function$
;

-- function: enqueue_bling_stock_after_product_link_v1()
CREATE OR REPLACE FUNCTION public.enqueue_bling_stock_after_product_link_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_product_id uuid;
  v_stock numeric;
begin
  if tg_op = 'UPDATE'
     and new.bling_id is not distinct from old.bling_id
     and new.status is not distinct from old.status then
    return new;
  end if;

  if new.source_system <> 'vitrine_qx'
     or new.entity_type <> 'product'
     or new.status <> 'matched'
     or coalesce(new.bling_id, 0) <= 0 then
    return new;
  end if;

  begin
    v_product_id := new.source_id::uuid;
  exception when invalid_text_representation then
    return new;
  end;

  select stock into v_stock
    from public.products
   where id = v_product_id;

  if not found then
    return new;
  end if;

  perform public.enqueue_bling_hub_job_v2(
    'stock',
    'set_stock',
    'vitrine_qx',
    v_product_id::text,
    'supabase:vitrine:stock:linked:' || v_product_id::text || ':' || new.bling_id::text,
    jsonb_build_object('stock_quantity', coalesce(v_stock, 0), 'authority', 'supabase'),
    1
  );

  return new;
end
$function$
;

-- function: enqueue_new_xml_product_catalog_enrichment_v1()
CREATE OR REPLACE FUNCTION public.enqueue_new_xml_product_catalog_enrichment_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if coalesce(new.metadata->>'purchase_xml_created','false')='true'
     and coalesce(new.metadata->>'new_product_review_required','false')='true' then
    insert into public.product_catalog_enrichment_jobs_v1(product_id)
    values (new.id) on conflict (product_id) do nothing;
  end if;
  return new;
end
$function$
;

-- function: ensure_storefront_customer_v2(p_phone text, p_name text, p_source_key text)
CREATE OR REPLACE FUNCTION public.ensure_storefront_customer_v2(p_phone text, p_name text DEFAULT NULL::text, p_source_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_phone text:=public.canonical_whatsapp_e164_br_v2(p_phone);
  v_name text:=nullif(left(btrim(regexp_replace(coalesce(p_name,''),'\s+',' ','g')),180),'');
  v_resolved jsonb;
  v_customer_id uuid;
  v_created boolean:=false;
  v_status text:='verified_existing';
begin
  if v_phone is null then
    return jsonb_build_object('ok',false,'error','invalid_phone');
  end if;

  perform pg_advisory_xact_lock(hashtextextended('ops2:customer-phone:'||v_phone,0));
  v_resolved:=public.resolve_customer_by_phone_v1(v_phone);

  if v_resolved->>'match_status'='matched' then
    v_customer_id:=(v_resolved->>'customer_id')::uuid;
  elsif v_resolved->>'match_status'='ambiguous' then
    return jsonb_build_object(
      'ok',false,'error','ambiguous_phone','canonical_phone_e164',v_phone,
      'candidate_count',coalesce((v_resolved->>'candidate_count')::integer,0)
    );
  end if;

  if v_customer_id is null and v_name is null then
    return jsonb_build_object('ok',false,'error','customer_name_required','canonical_phone_e164',v_phone);
  end if;

  if v_customer_id is null then
    begin
      insert into public.customers(name,primary_whatsapp_e164,is_active,created_at,updated_at)
      values(v_name,v_phone,true,now(),now())
      returning id into v_customer_id;
      v_created:=true;
      v_status:='provisional';
    exception when unique_violation then
      v_resolved:=public.resolve_customer_by_phone_v1(v_phone);
      if v_resolved->>'match_status'='matched' then
        v_customer_id:=(v_resolved->>'customer_id')::uuid;
      else
        return jsonb_build_object('ok',false,'error','ambiguous_phone','canonical_phone_e164',v_phone);
      end if;
    end;
  else
    update public.customers
       set name=case when nullif(btrim(coalesce(name,'')),'') is null then v_name else name end,
           is_active=true,updated_at=now()
     where id=v_customer_id;
  end if;

  if not exists(
    select 1 from public.customer_phones cp
     where cp.customer_id=v_customer_id
       and public.normalize_phone_digits(cp.phone_e164)=public.normalize_phone_digits(v_phone)
  ) then
    insert into public.customer_phones(customer_id,phone_e164,source,is_primary,verified_at)
    values(v_customer_id,v_phone,'whatsapp',true,case when v_created then null else now() end)
    on conflict(phone_e164) do nothing;
  end if;

  insert into public.customer_identity_profiles_v1(
    customer_id,identity_status,created_from,canonical_phone_e164,last_source_key,metadata,updated_at
  ) values(
    v_customer_id,
    case when v_created then 'provisional' else 'verified_existing' end,
    case when v_created then 'site_checkout' else 'existing' end,
    v_phone,nullif(left(coalesce(p_source_key,''),220),''),'{}'::jsonb,now()
  )
  on conflict(customer_id) do update set
    canonical_phone_e164=excluded.canonical_phone_e164,
    last_source_key=coalesce(excluded.last_source_key,public.customer_identity_profiles_v1.last_source_key),
    updated_at=now();

  select identity_status into v_status
    from public.customer_identity_profiles_v1 where customer_id=v_customer_id;

  return jsonb_build_object(
    'ok',true,'customer_id',v_customer_id,'created',v_created,'status',v_status,
    'canonical_phone_e164',v_phone,'ambiguous_variants_observed',false
  );
end;
$function$
;

-- function: finish_bling_hub_job_v2(p_job_id uuid, p_status text, p_result jsonb, p_error_code text, p_error_message text, p_http_status integer, p_retry_seconds integer, p_provider_id text)
CREATE OR REPLACE FUNCTION public.finish_bling_hub_job_v2(p_job_id uuid, p_status text, p_result jsonb DEFAULT '{}'::jsonb, p_error_code text DEFAULT NULL::text, p_error_message text DEFAULT NULL::text, p_http_status integer DEFAULT NULL::integer, p_retry_seconds integer DEFAULT 120, p_provider_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_job public.bling_hub_jobs_v2%rowtype;
  v_status text:=lower(trim(coalesce(p_status,'')));
begin
  if v_status not in ('synced','retry','review_required','failed','cancelled') then raise exception 'invalid_finish_status'; end if;

  update public.bling_hub_jobs_v2
  set status=v_status,
      result=coalesce(p_result,'{}'::jsonb),
      error_code=nullif(trim(coalesce(p_error_code,'')),''),
      error_message=nullif(left(trim(coalesce(p_error_message,'')),1500),''),
      last_http_status=p_http_status,
      provider_id=coalesce(nullif(trim(coalesce(p_provider_id,'')),''),provider_id),
      next_attempt_at=case when v_status='retry' then now()+make_interval(secs=>greatest(5,least(coalesce(p_retry_seconds,120),86400))) else next_attempt_at end,
      finished_at=case when v_status in ('synced','review_required','failed','cancelled') then now() else null end,
      locked_at=null,locked_by=null,updated_at=now()
  where id=p_job_id
  returning * into v_job;

  if not found then raise exception 'job_not_found'; end if;

  insert into public.bling_hub_audit_v2(event_type,severity,domain,job_id,source_system,source_id,correlation_id,details)
  values(
    'job_'||v_status,
    case when v_status in ('failed','review_required') then 'warning' else 'info' end,
    v_job.domain,v_job.id,v_job.source_system,v_job.source_id,v_job.correlation_id,
    jsonb_build_object('operation',v_job.operation,'attempts',v_job.attempts,'http_status',p_http_status,'error_code',p_error_code)
  );

  return jsonb_build_object('id',v_job.id,'status',v_job.status,'attempts',v_job.attempts,'provider_id',v_job.provider_id);
end
$function$
;

-- function: finish_bling_order_stock_action_v2(p_source_order_id uuid, p_action text, p_success boolean, p_snapshot jsonb, p_error text, p_metadata jsonb)
CREATE OR REPLACE FUNCTION public.finish_bling_order_stock_action_v2(p_source_order_id uuid, p_action text, p_success boolean, p_snapshot jsonb DEFAULT '{}'::jsonb, p_error text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_action text:=lower(trim(coalesce(p_action,'')));
  v_state text;
begin
  if v_action not in ('launch','reverse') then
    return jsonb_build_object('ok',false,'error','invalid_action');
  end if;

  if v_action='launch' then
    v_state:=case when p_success then 'launched' else 'review_required' end;
    update public.bling_order_stock_controls_v2
       set state=v_state,
           after_launch=coalesce(p_snapshot,'{}'::jsonb),
           launched_at=case when p_success then now() else launched_at end,
           last_error=case when p_success then null else left(coalesce(p_error,'launch_failed'),1000) end,
           metadata=coalesce(metadata,'{}'::jsonb)||coalesce(p_metadata,'{}'::jsonb),
           updated_at=now()
     where source_order_id=p_source_order_id;
  else
    v_state:=case when p_success then 'reversed' else 'review_required' end;
    update public.bling_order_stock_controls_v2
       set state=v_state,
           after_reverse=coalesce(p_snapshot,'{}'::jsonb),
           reversed_at=case when p_success then now() else reversed_at end,
           last_error=case when p_success then null else left(coalesce(p_error,'reverse_failed'),1000) end,
           metadata=coalesce(metadata,'{}'::jsonb)||coalesce(p_metadata,'{}'::jsonb),
           updated_at=now()
     where source_order_id=p_source_order_id;
  end if;

  if not found then
    return jsonb_build_object('ok',false,'error','control_row_missing');
  end if;
  return jsonb_build_object('ok',true,'state',v_state);
end
$function$
;

-- function: finish_bling_webhook_inbox_v2(p_event_id text, p_status text, p_result jsonb, p_error text, p_retry_seconds integer, p_self_generated boolean)
CREATE OR REPLACE FUNCTION public.finish_bling_webhook_inbox_v2(p_event_id text, p_status text, p_result jsonb DEFAULT '{}'::jsonb, p_error text DEFAULT NULL::text, p_retry_seconds integer DEFAULT 120, p_self_generated boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_status text:=lower(trim(coalesce(p_status,'')));
  v_row public.bling_webhook_inbox_v2%rowtype;
begin
  if v_status not in ('processed','ignored','review_required','retry','failed') then
    raise exception 'invalid_finish_status';
  end if;

  update public.bling_webhook_inbox_v2
     set status=v_status,
         result=coalesce(p_result,'{}'::jsonb),
         last_error=nullif(left(trim(coalesce(p_error,'')),1200),''),
         self_generated_candidate=coalesce(p_self_generated,false),
         next_attempt_at=case
           when v_status='retry' then now()+make_interval(secs=>greatest(5,least(coalesce(p_retry_seconds,120),86400)))
           else next_attempt_at
         end,
         processed_at=case when v_status in ('processed','ignored','review_required','failed') then now() else null end,
         locked_by=null,
         locked_at=null,
         updated_at=now()
   where event_id=p_event_id
   returning * into v_row;

  if not found then raise exception 'webhook_event_not_found'; end if;

  insert into public.bling_hub_audit_v2(event_type,severity,domain,source_system,source_id,details)
  values(
    'webhook_'||v_status,
    case when v_status in ('review_required','failed') then 'warning' else 'info' end,
    case
      when v_row.resource='product' then 'product'
      when v_row.resource in ('stock','virtual_stock') then 'stock'
      when v_row.resource='order' then 'order'
      when v_row.resource in ('invoice','consumer_invoice') then 'fiscal'
      else 'webhook'
    end,
    'bling_webhook',
    v_row.event_id,
    jsonb_build_object(
      'event_name',v_row.event_name,
      'provider_entity_id',v_row.provider_entity_id,
      'self_generated_candidate',coalesce(p_self_generated,false),
      'status',v_status
    )
  );

  return jsonb_build_object(
    'event_id',v_row.event_id,
    'status',v_row.status,
    'attempt_count',v_row.attempt_count,
    'self_generated_candidate',v_row.self_generated_candidate
  );
end
$function$
;

-- function: fiscal_normalize_text_v1(p_text text)
CREATE OR REPLACE FUNCTION public.fiscal_normalize_text_v1(p_text text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO ''
AS $function$
  select trim(regexp_replace(
    translate(
      lower(coalesce(p_text,'')),
      'áàâãäéèêëíìîïóòôõöúùûüç',
      'aaaaaeeeeiiiiooooouuuuc'
    ),
    '[^a-z0-9]+',
    ' ',
    'g'
  ));
$function$
;

-- function: fiscal_rule_description_matches_v1(p_description text, p_qualifiers jsonb)
CREATE OR REPLACE FUNCTION public.fiscal_rule_description_matches_v1(p_description text, p_qualifiers jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  with q as (
    select
      public.fiscal_normalize_text_v1(p_description) as d,
      case when jsonb_typeof(coalesce(p_qualifiers,'{}'::jsonb)->'include_all')='array'
        then coalesce(p_qualifiers,'{}'::jsonb)->'include_all' else '[]'::jsonb end as include_all,
      case when jsonb_typeof(coalesce(p_qualifiers,'{}'::jsonb)->'include_any')='array'
        then coalesce(p_qualifiers,'{}'::jsonb)->'include_any' else '[]'::jsonb end as include_any,
      case when jsonb_typeof(coalesce(p_qualifiers,'{}'::jsonb)->'exclude_any')='array'
        then coalesce(p_qualifiers,'{}'::jsonb)->'exclude_any' else '[]'::jsonb end as exclude_any
  )
  select
    not exists (
      select 1 from q, jsonb_array_elements_text(q.include_all) t(term)
      where position(public.fiscal_normalize_text_v1(t.term) in q.d)=0
    )
    and (
      jsonb_array_length((select include_any from q))=0
      or exists (
        select 1 from q, jsonb_array_elements_text(q.include_any) t(term)
        where position(public.fiscal_normalize_text_v1(t.term) in q.d)>0
      )
    )
    and not exists (
      select 1 from q, jsonb_array_elements_text(q.exclude_any) t(term)
      where position(public.fiscal_normalize_text_v1(t.term) in q.d)>0
    );
$function$
;

-- function: fiscal_valid_gtin_v1(p_gtin text)
CREATE OR REPLACE FUNCTION public.fiscal_valid_gtin_v1(p_gtin text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO ''
AS $function$
declare
  g text:=regexp_replace(coalesce(p_gtin,''),'\D','','g');
  i integer;
  offset_idx integer:=0;
  total integer:=0;
  expected integer;
begin
  if length(g) not in (8,12,13,14) then return false; end if;
  expected:=substring(g from length(g) for 1)::integer;
  i:=length(g)-1;
  while i>=1 loop
    total:=total + substring(g from i for 1)::integer * case when mod(offset_idx,2)=0 then 3 else 1 end;
    offset_idx:=offset_idx+1;
    i:=i-1;
  end loop;
  return mod(10-mod(total,10),10)=expected;
end;
$function$
;

-- function: force_supabase_stock_authority_v1()
CREATE OR REPLACE FUNCTION public.force_supabase_stock_authority_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  new.metadata := jsonb_set(
    coalesce(new.metadata, '{}'::jsonb),
    '{ops2_stock_authority}',
    '"supabase"'::jsonb,
    true
  );
  if nullif(new.metadata->>'ops2_supabase_stock_authority_at','') is null then
    new.metadata := jsonb_set(new.metadata, '{ops2_supabase_stock_authority_at}', to_jsonb(now()::text), true);
  end if;
  if nullif(new.metadata->>'ops2_stock_cutover_at','') is null then
    new.metadata := jsonb_set(new.metadata, '{ops2_stock_cutover_at}', new.metadata->'ops2_supabase_stock_authority_at', true);
  end if;
  new.metadata := jsonb_set(new.metadata, '{ops2_stock_authority_fixed}', 'true'::jsonb, true);
  return new;
end;
$function$
;

-- function: format_phone_br_v1(p_phone text)
CREATE OR REPLACE FUNCTION public.format_phone_br_v1(p_phone text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare d text:=regexp_replace(coalesce(p_phone,''),'\D','','g'); localp text;begin
  if left(d,2)='55' then d:=substring(d from 3); end if;
  if length(d)<10 then return coalesce(p_phone,''); end if;
  localp:=substring(d from 3);
  if length(localp)=9 then return '('||left(d,2)||') '||left(localp,5)||'-'||right(localp,4); end if;
  return '('||left(d,2)||') '||left(localp,4)||'-'||right(localp,4);
end $function$
;

-- function: get_bling_api_credentials_v1()
CREATE OR REPLACE FUNCTION public.get_bling_api_credentials_v1()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'client_id',max(decrypted_secret) filter(where name='bling_api_client_id_v1'),
    'client_secret',max(decrypted_secret) filter(where name='bling_api_client_secret_v1'),
    'refresh_token',max(decrypted_secret) filter(where name='bling_api_refresh_token_v1')
  )
  from vault.decrypted_secrets
  where name in ('bling_api_client_id_v1','bling_api_client_secret_v1','bling_api_refresh_token_v1')
$function$
;

-- function: get_bling_hub_key_v2()
CREATE OR REPLACE FUNCTION public.get_bling_hub_key_v2()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select decrypted_secret
