-- function: get_cart_aware_recommendations(p_conversation_id uuid, p_limit integer, p_kind text)
CREATE OR REPLACE FUNCTION public.get_cart_aware_recommendations(p_conversation_id uuid, p_limit integer DEFAULT 6, p_kind text DEFAULT 'upsell'::text)
 RETURNS TABLE(product_id uuid, name text, price numeric, image_url text, sales_category text, stock numeric, score numeric, reason text, bought_before boolean, purchase_count integer, last_purchase_at timestamp with time zone, is_offer boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with conv as (
    select c.customer_id from public.conversations c where c.id=p_conversation_id
  ), cart as (
    select ca.id from public.carts ca where ca.conversation_id=p_conversation_id and ca.status='draft' order by ca.updated_at desc limit 1
  ), in_cart as (
    select ci.product_id from public.cart_items ci join cart ca on ca.id=ci.cart_id where ci.quantity>0
  ), stats as (
    select s.* from public.customer_product_stats s join conv c on c.customer_id=s.customer_id
  ), affinity as (
    select p.sales_category,sum(s.purchase_count)::numeric category_weight
    from stats s join public.products p on p.id=s.product_id
    where p.sales_category is not null group by p.sales_category
  ), recent_events as (
    select e.product_id,
      max(e.occurred_at) filter(where e.event_type='offered') last_offered,
      max(e.occurred_at) filter(where e.event_type='rejected') last_rejected,
      count(*) filter(where e.event_type='offered' and e.occurred_at>=now()-interval '7 days') offered_7d
    from public.sales_offer_events e join conv c on c.customer_id=e.customer_id
    where e.product_id is not null and e.occurred_at>=now()-interval '30 days'
    group by e.product_id
  ), ranked as (
    select p.id,p.name,p.price,p.image_url,p.sales_category,p.stock,p.is_offer,
      (
        case when s.product_id is not null then 42 else 0 end
        + least(coalesce(s.purchase_count,0)*7,28)
        + least(coalesce(a.category_weight,0)*2,18)
        + case when p.is_offer then 24 else 0 end
        + case when p.is_upsell then 10 else 0 end
        + case when s.last_purchase_at between now()-interval '90 days' and now()-interval '14 days' then 8 else 0 end
        - least(coalesce(re.offered_7d,0)*12,36)
      )::numeric score,
      case
        when s.product_id is not null and p.is_offer then 'Você já costuma comprar e está em oferta'
        when s.product_id is not null then 'Você já costuma comprar este produto'
        when p.is_offer and coalesce(a.category_weight,0)>0 then 'Oferta em uma categoria que você costuma comprar'
        when p.is_offer then 'Está em oferta hoje'
        when coalesce(a.category_weight,0)>0 then 'Combina com suas compras anteriores'
        when p.is_upsell then 'Complementa esta compra'
        else 'Sugestão para completar o pedido'
      end reason,
      (s.product_id is not null) bought_before,coalesce(s.purchase_count,0)::int purchase_count,s.last_purchase_at,p.sort_order
    from public.products p
    left join stats s on s.product_id=p.id
    left join affinity a on a.sales_category=p.sales_category
    left join recent_events re on re.product_id=p.id
    where p.is_active=true and coalesce(p.stock,0)>0
      and not exists(select 1 from in_cart x where x.product_id=p.id)
      and (re.last_rejected is null or re.last_rejected<now()-interval '30 days')
      and (p_kind<>'offers' or p.is_offer=true)
  )
  select id,name,price,image_url,sales_category,stock,score,reason,bought_before,purchase_count,last_purchase_at,is_offer
  from ranked
  order by score desc,sort_order asc,name asc
  limit greatest(1,least(coalesce(p_limit,6),30))
$function$
;

-- function: get_conversation_worker_provider_secret_v1()
CREATE OR REPLACE FUNCTION public.get_conversation_worker_provider_secret_v1()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_key text;
  v_expected_hash text;
  v_active boolean;
begin
  select key_hash,is_active into v_expected_hash,v_active
    from public.system_secrets
   where key_name='openai_conversation_worker_v1';

  if not coalesce(v_active,false) or v_expected_hash is null then
    return null;
  end if;

  select decrypted_secret into v_key
    from vault.decrypted_secrets
   where name='openai_conversation_worker_key_v1'
   order by created_at desc
   limit 1;

  if v_key is null or encode(extensions.digest(v_key,'sha256'),'hex') is distinct from v_expected_hash then
    return null;
  end if;

  return v_key;
end;
$function$
;

-- function: get_ops2_fiscal_dispatch_health_v1()
CREATE OR REPLACE FUNCTION public.get_ops2_fiscal_dispatch_health_v1()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
select jsonb_build_object(
  'generated_at',now(),
  'authorized',count(*) filter(where status='authorized'),
  'review_required',count(*) filter(where status='review_required'),
  'error',count(*) filter(where status='error'),
  'generating_stale',count(*) filter(where status='generating' and updated_at<now()-interval '5 minutes'),
  'authorizing_stale',count(*) filter(where status='authorizing' and updated_at<now()-interval '5 minutes'),
  'authorized_invalid_document',count(*) filter(
    where status='authorized' and (
      coalesce(bling_invoice_id,0)<=0
      or length(regexp_replace(coalesce(access_key,''),'[^0-9]','','g'))<>44
      or nullif(trim(coalesce(sefaz_status,'')),'') is null
    )
  ),
  'retry_policy','reconcile_only_after_irreversible_post',
  'max_write_attempts',1
)
from public.dispatch_fiscal_jobs;
$function$
;

-- function: get_ops2_order_shadow_readiness_v1()
CREATE OR REPLACE FUNCTION public.get_ops2_order_shadow_readiness_v1()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
with cfg as (
  select coalesce(live_orders_since,'2026-09-24T03:19:06.631396Z'::timestamptz) as live_since
  from public.vitrine_operational_cutover_config
  where id=1
),
open_orders as (
  select o.*
  from public.orders o, cfg
  where o.created_at >= cfg.live_since
    and o.status in ('storefront_received','confirmed')
),
product_stats as (
  select
    oi.order_id,
    count(distinct oi.product_id) filter (where oi.product_id is not null) as product_count,
    count(distinct oi.product_id) filter (
      where oi.product_id is not null
        and not exists (
          select 1
          from public.bling_hub_entity_links_v2 l
          where l.source_system='vitrine_qx'
            and l.entity_type='product'
            and l.source_id=oi.product_id::text
            and l.status='matched'
            and l.bling_id is not null
        )
    ) as unresolved_products
  from public.order_items oi
  join open_orders o on o.id=oi.order_id
  group by oi.order_id
),
detail as (
  select
    o.id,
    o.order_number,
    o.status,
    o.created_at,
    o.source,
    coalesce(ps.product_count,0) as product_count,
    coalesce(ps.unresolved_products,0) as unresolved_products,
    case
      when o.customer_id is null then true
      when exists (
        select 1
        from public.bling_hub_entity_links_v2 l
        where l.source_system='canonical_ssbes'
          and l.entity_type='customer'
          and l.source_id=o.customer_id::text
          and l.status='matched'
          and l.bling_id is not null
      ) then false
      else true
    end as unresolved_customer,
    (
      coalesce(trim(o.delivery_address->>'street'),'')='' or
      coalesce(trim(o.delivery_address->>'number'),'')='' or
      coalesce(trim(o.delivery_address->>'city'),'')='' or
      coalesce(trim(o.delivery_address->>'state'),'')=''
    ) as incomplete_address,
    coalesce(trim(o.payment_method),'')='' as missing_payment
  from open_orders o
  left join product_stats ps on ps.order_id=o.id
),
classified as (
  select *,
    (
      product_count > 0
      and unresolved_products=0
      and unresolved_customer=false
      and incomplete_address=false
      and missing_payment=false
    ) as erp_ready
  from detail
)
select jsonb_build_object(
  'generated_at',now(),
  'total',count(*),
  'erp_ready',count(*) filter (where erp_ready),
  'blocked',count(*) filter (where not erp_ready),
  'unresolved_customer',count(*) filter (where unresolved_customer),
  'unresolved_products',count(*) filter (where unresolved_products>0),
  'incomplete_address',count(*) filter (where incomplete_address),
  'missing_payment',count(*) filter (where missing_payment),
  'orders',coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id',id,
        'order_number',order_number,
        'status',status,
        'source',source,
        'created_at',created_at,
        'product_count',product_count,
        'unresolved_products',unresolved_products,
        'unresolved_customer',unresolved_customer,
        'incomplete_address',incomplete_address,
        'missing_payment',missing_payment,
        'erp_ready',erp_ready
      )
      order by erp_ready desc, created_at desc
    ),
    '[]'::jsonb
  )
)
from classified;
$function$
;

-- function: get_ops2_papoai_bridge_health_v1()
CREATE OR REPLACE FUNCTION public.get_ops2_papoai_bridge_health_v1()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
select jsonb_build_object(
  'generated_at',now(),
  'capture_enabled',(select capture_enabled from public.papoai_webhook_runtime_v2 where id=1),
  'last_seen_at',(select last_seen_at from public.papoai_webhook_runtime_v2 where id=1),
  'last_error',(select last_error from public.papoai_webhook_runtime_v2 where id=1),
  'events_total',(select count(*) from public.papoai_webhook_inbox_v2),
  'events_24h',(select count(*) from public.papoai_webhook_inbox_v2 where received_at>=now()-interval '24 hours'),
  'events_review',(select count(*) from public.papoai_webhook_inbox_v2 where status='review_required'),
  'events_customer_linked',(select count(*) from public.papoai_webhook_inbox_v2 where nullif(metadata->>'customer_id','') is not null),
  'events_conversation_linked',(select count(*) from public.papoai_webhook_inbox_v2 where nullif(metadata->>'conversation_id','') is not null),
  'flow_events_total',(select count(*) from public.papoai_customer_flow_events_v1),
  'flow_events_review',(select count(*) from public.papoai_customer_flow_events_v1 where status='review_required'),
  'flow_orders_linked',(select coalesce(sum(orders_linked),0) from public.papoai_customer_flow_events_v1 where status='processed'),
  'drafts_total',(select count(*) from public.papoai_order_drafts_v2),
  'drafts_active',(select count(*) from public.papoai_order_drafts_v2 where status in ('draft','awaiting_confirmation','review_required')),
  'orders_linked',(select count(*) from public.papoai_order_drafts_v2 where canonical_order_id is not null),
  'identity_tokens_total',(select count(*) from public.storefront_identity_tokens where source='papoai'),
  'identity_tokens_active',(select count(*) from public.storefront_identity_tokens where source='papoai' and redeemed_at is null and expires_at>now()),
  'identity_tokens_redeemed',(select count(*) from public.storefront_identity_tokens where source='papoai' and redeemed_at is not null),
  'identity_order_links',(select count(*) from public.orders where coalesce((checkout_snapshot->>'papoai_conversation_linked')::boolean,false)=true),
  'structured_draft_enabled',(select structured_draft_enabled from public.ops2_papoai_bridge_runtime_v1 where id=1),
  'structured_order_commit_enabled',(select structured_order_commit_enabled from public.ops2_papoai_bridge_runtime_v1 where id=1),
  'identity_link_enabled',(select identity_link_enabled from public.ops2_papoai_bridge_runtime_v1 where id=1),
  'last_identity_link',(
    select jsonb_build_object(
      'created_at',t.created_at,'expires_at',t.expires_at,'redeemed_at',t.redeemed_at,
      'short_code',t.short_code,'catalog_path','/catalogo_'||t.short_code,
      'conversation_linked',t.conversation_id is not null,'customer_linked',t.customer_id is not null
    )
    from public.storefront_identity_tokens t
    where t.source='papoai'
    order by t.created_at desc limit 1
  ),
  'last_flow',(
    select jsonb_build_object(
      'created_at',f.created_at,'status',f.status,'customer_created',f.customer_created,
      'customer_linked',f.customer_id is not null,'conversation_linked',f.conversation_id is not null,
      'orders_linked',f.orders_linked
    )
    from public.papoai_customer_flow_events_v1 f
    order by f.created_at desc limit 1
  )
);
$function$
;

-- function: get_ops2_purchase_xml_health_v1()
CREATE OR REPLACE FUNCTION public.get_ops2_purchase_xml_health_v1()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
select jsonb_build_object(
  'generated_at',now(),
  'documents_total',(select count(*) from purchase_xml_documents),
  'documents_processed',(select count(*) from purchase_xml_documents where processing_status='processed'),
  'documents_review',(select count(*) from purchase_xml_documents where processing_status='review_required'),
  'items_total',(select count(*) from purchase_xml_items),
  'items_inferred_xml',(select count(*) from purchase_xml_items where conversion_status='inferred_xml'),
  'items_known',(select count(*) from purchase_xml_items where conversion_status='known'),
  'items_not_needed',(select count(*) from purchase_xml_items where conversion_status='not_needed'),
  'items_review',(select count(*) from purchase_xml_items where conversion_status='review_required' or processing_status='review_required'),
  'unsafe_conversion_quarantined',(select count(*) from purchase_xml_items where metadata ? 'unsafe_conversion_quarantined_at'),
  'lot_evidence_rows',(select count(*) from purchase_xml_item_lot_evidence),
  'receipt_plans',(select count(*) from purchase_stock_receipt_plans_v1),
  'receipt_plans_waiting',(select count(*) from purchase_stock_receipt_plans_v1 where status='awaiting_bling_receipt'),
  'receipt_plans_review',(select count(*) from purchase_stock_receipt_plans_v1 where status='review_required'),
  'receipt_plans_verified',(select count(*) from purchase_stock_receipt_plans_v1 where status='verified'),
  'stock_receipts_applied',(select count(*) from purchase_stock_receipts where status='applied'),
  'cpf_finance_violations',(select count(*) from purchase_xml_documents
    where recipient_kind='CPF'
      and (financial_eligible<>false
        or finance_status<>'blocked_personal'
        or jsonb_array_length(coalesce(finance_reference->'accounts','[]'::jsonb))>0)),
  'daily_enabled',(select daily_enabled from purchase_xml_settings where id=1),
  'daily_hour_cuiaba',(select daily_hour_cuiaba from purchase_xml_settings where id=1),
  'daily_lookback_days',(select daily_lookback_days from purchase_xml_settings where id=1),
  'stock_authority',(select coalesce(metadata->>'ops2_stock_authority','legacy_shadow') from bling_hub_runtime_v2 where id=1)
);
$function$
;

