-- function: get_ops2_sellable_stock_v1(p_product_id uuid)
CREATE OR REPLACE FUNCTION public.get_ops2_sellable_stock_v1(p_product_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce((
    select jsonb_build_object(
      'product_id',p.id,'is_active',p.is_active,'stock_authority','supabase',
      'stock_cutover_at',nullif(rt.metadata->>'ops2_supabase_stock_authority_at','')::timestamptz,
      'stock',coalesce(p.stock,0),'catalog_stock',coalesce(p.stock,0),
      'legacy_stock',coalesce(p.stock,0),'effective_sellable_stock',coalesce(p.stock,0),
      'basket_locked_quantity',coalesce(s.basket_locked_quantity,0),
      'sellable_stock',coalesce(s.loose_sellable_stock,0),
      'stock_source','supabase.products.stock','stock_source_reason','supabase_products_stock'
    )
    from public.products p
    left join public.ops2_loose_sellable_stock_v1 s on s.product_id=p.id
    cross join public.bling_hub_runtime_v2 rt
    where p.id=p_product_id and rt.id=1
  ),jsonb_build_object('product_id',p_product_id,'error','product_not_found'));
$function$
;

-- function: get_ops2_stock_cutover_preflight_v1()
CREATE OR REPLACE FUNCTION public.get_ops2_stock_cutover_preflight_v1()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
with inventory as (
  select count(*) filter(where is_active) as active_products,
         count(*) filter(where is_active and coalesce(stock,0)>0) as active_stock_positive,
         count(*) filter(where is_active and coalesce(stock,0)<=0) as active_stock_zero,
         coalesce(sum(greatest(0,coalesce(stock,0))),0) as catalog_stock_total
  from public.products
), reservations as (
  select count(distinct r.order_id) as orders,count(*) as rows
  from public.vitrine_stock_reservations r join public.orders o on o.id=r.order_id
  where o.status not in ('cancelled','delivered','returned')
    and public.supabase_stock_pending_reservations_v1(r.product_id,null::uuid)>0
), manual as (
  select count(distinct p.id) as products
  from public.products p
  where p.is_active=true and coalesce(p.stock,0)<=0
    and (exists(select 1 from public.basket_admin_product_options o where o.product_id=p.id)
      or exists(select 1 from public.basket_mold_position_options o where o.product_id=p.id))
)
select jsonb_build_object(
  'phase','supabase_stock_authority_fixed','authority','supabase',
  'stock_source','supabase.products.stock','stock_authority_fixed',true,
  'active_products',inventory.active_products,'active_stock_positive',inventory.active_stock_positive,
  'active_stock_zero',inventory.active_stock_zero,'catalog_stock_total',inventory.catalog_stock_total,
  'pending_local_reservation_orders',reservations.orders,'pending_local_reservation_rows',reservations.rows,
  'products_for_manual_basket_review',manual.products,'ready',true,'blocking_reasons','[]'::jsonb
)
from inventory,reservations,manual
$function$
;

-- function: get_ops_control_tower_summary_v1()
CREATE OR REPLACE FUNCTION public.get_ops_control_tower_summary_v1()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'generated_at', now(),
    'orders', jsonb_build_object(
      'awaiting', (select count(*) from public.orders where status='storefront_received'),
      'confirmed', (select count(*) from public.orders where status='confirmed'),
      'ready', (select count(*) from public.orders where status='ready'),
      'delivered', (select count(*) from public.orders where status='delivered'),
      'cancelled', (select count(*) from public.orders where status='cancelled')
    ),
    'delivery', jsonb_build_object(
      'returning', (select count(*) from public.order_delivery_return_cases where status='returning'),
      'return_review', (select count(*) from public.order_delivery_return_cases where status='returned_review'),
      'planned_runs', (select count(*) from public.ops_delivery_runs where service_date=(now() at time zone 'America/Cuiaba')::date and status='planned'),
      'active_runs', (select count(*) from public.ops_delivery_runs where service_date=(now() at time zone 'America/Cuiaba')::date and status='dispatched'),
      'active_stops', (select count(*) from public.ops_delivery_stops s join public.ops_delivery_runs r on r.id=s.run_id where r.service_date=(now() at time zone 'America/Cuiaba')::date and r.status='dispatched' and s.status='out_for_delivery')
    ),
    'whatsapp', jsonb_build_object(
      'human_required', (select count(*) from public.conversations where channel='whatsapp' and human_required=true),
      'human_mode', (select count(*) from public.conversations where channel='whatsapp' and mode='human')
    ),
    'inventory', jsonb_build_object(
      'active_products', (select count(*) from public.products where is_active=true),
      'zero_or_negative', (select count(*) from public.products where is_active=true and coalesce(stock,0)<=0),
      'expires_90d', (select count(*) from public.products where is_active=true and validity_date is not null and validity_date between current_date and current_date+90),
      'expired', (select count(*) from public.products where is_active=true and validity_date is not null and validity_date<current_date),
      'count_differences_pending', (select count(*) from public.ops_inventory_counts where reconciliation_state='pending_erp_reconciliation'),
      'incidents_open', (select count(*) from public.ops_inventory_incidents where status in ('open','review'))
    ),
    'payments', jsonb_build_object(
      'captured_unsynced', (select count(*) from public.order_payment_settlements where status in ('captured','needs_review') and bling_sync_state in ('blocked_homologation','pending','failed')),
      'sync_failed', (select count(*) from public.order_payment_settlements where status in ('captured','needs_review') and bling_sync_state='failed')
    ),
    'attention', jsonb_build_object(
      'open', (select count(*) from public.ops_attention where status in ('open','acknowledged')),
      'critical', (select count(*) from public.ops_attention where status in ('open','acknowledged') and priority='critical'),
      'high', (select count(*) from public.ops_attention where status in ('open','acknowledged') and priority='high')
    ),
    'approvals', jsonb_build_object(
      'pending', (select count(*) from public.ops_approvals where status='pending')
    ),
    'printing', jsonb_build_object(
      'pending', (select count(*) from public.ops_print_jobs where status='pending'),
      'failed', (select count(*) from public.ops_print_jobs where status='failed'),
      'claimed', (select count(*) from public.ops_print_jobs where status='claimed'),
      'presented', (select count(*) from public.ops_print_jobs where status='presented'),
      'printed', (select count(*) from public.ops_print_jobs where status='printed')
    )
  );
$function$
;

-- function: get_ops_delivery_returns_summary_v1(p_limit integer)
CREATE OR REPLACE FUNCTION public.get_ops_delivery_returns_summary_v1(p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'returning',count(*) filter (where status='returning'),
    'review',count(*) filter (where status='returned_review'),
    'cases',coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id',id,'order_id',order_id,'attempt_number',attempt_number,
          'reason_code',reason_code,'reason_label',reason_label,'note',note,
          'status',status,'recommended_disposition',recommended_disposition,
          'final_disposition',final_disposition,'failed_at',failed_at,
          'returned_at',returned_at,'failed_by',failed_by,'returned_by',returned_by,
          'dispatch_blocked',(status='returned_review')
        ) order by failed_at desc
      ) filter (where rn<=greatest(1,least(100,coalesce(p_limit,50)))),
      '[]'::jsonb
    )
  )
  from (
    select c.*,row_number() over(order by failed_at desc) rn
    from public.order_delivery_return_cases c
    where status in ('returning','returned_review')
  ) x;
$function$
;

-- function: get_ops_delivery_runs_today_v1()
CREATE OR REPLACE FUNCTION public.get_ops_delivery_runs_today_v1()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
with runs as (
  select *
  from public.ops_delivery_runs
  where service_date=(now() at time zone 'America/Cuiaba')::date
    and status<>'cancelled'
  order by created_at desc
),
packed as (
  select r.id,r.vehicle_key,r.status,r.operator_label,r.created_at,r.dispatched_at,r.completed_at,
    coalesce(jsonb_agg(
      jsonb_build_object(
        'stop_id',s.id,
        'order_id',s.order_id,
        'sequence',s.sequence,
        'status',s.status,
        'address',s.address_snapshot,
        'phone',s.phone_snapshot,
        'customer_name',s.customer_name_snapshot,
        'order_number',s.order_number_snapshot,
        'total_cents',s.total_cents,
        'payment_method',s.payment_method_snapshot,
        'maps_url',s.maps_url_snapshot
      ) order by s.sequence
    ) filter(where s.id is not null),'[]'::jsonb) stops
  from runs r
  left join public.ops_delivery_stops s on s.run_id=r.id
  group by r.id,r.vehicle_key,r.status,r.operator_label,r.created_at,r.dispatched_at,r.completed_at
)
select jsonb_build_object(
  'generated_at',now(),
  'runs',coalesce(jsonb_agg(to_jsonb(packed) order by created_at desc),'[]'::jsonb)
)
from packed;
$function$
;

-- function: get_ops_delivery_runs_today_v2()
CREATE OR REPLACE FUNCTION public.get_ops_delivery_runs_today_v2()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
select jsonb_build_object(
  'generated_at',now(),
  'catalog',public.smart_delivery_catalog_v1(),
  'runs',coalesce((
    select jsonb_agg(run_json order by (run_json->>'created_at')::timestamptz desc)
    from (
      select jsonb_build_object(
        'id',r.id,'service_date',r.service_date,'vehicle_key',r.vehicle_key,'status',r.status,
        'operator_label',r.operator_label,'created_at',r.created_at,'dispatched_at',r.dispatched_at,'completed_at',r.completed_at,
        'region_id',r.region_id,'driver_id',r.driver_id,'vehicle_id',r.vehicle_id,
        'optimizer_provider',r.optimizer_provider,'optimizer_job_ref',r.optimizer_job_ref,'optimizer_payload',r.optimizer_payload,
        'loading_started_at',r.loading_started_at,'loaded_at',r.loaded_at,
        'region',case when rg.id is null then null else jsonb_build_object('id',rg.id,'code',rg.code,'name',rg.name,'city',rg.city) end,
        'driver',case when dr.id is null then null else jsonb_build_object('id',dr.id,'name',dr.name,'phone_e164',dr.phone_e164) end,
        'vehicle',case when vh.id is null then null else jsonb_build_object('id',vh.id,'label',vh.label,'plate',vh.plate,'vehicle_type',vh.vehicle_type,'capacity_units',vh.capacity_units) end,
        'stops',coalesce((
          select jsonb_agg(jsonb_build_object(
            'stop_id',s.id,'order_id',s.order_id,'sequence',s.sequence,'status',s.status,
            'address',s.address_snapshot,'phone',s.phone_snapshot,'customer_name',s.customer_name_snapshot,
            'order_number',s.order_number_snapshot,'total_cents',s.total_cents,'payment_method',s.payment_method_snapshot,
            'maps_url',s.maps_url_snapshot,'customer_address_id',s.customer_address_id,
            'location_evidence_id',s.location_evidence_id,'region_id',s.region_id,
            'destination_latitude',s.destination_latitude,'destination_longitude',s.destination_longitude,
            'destination_confidence',s.destination_confidence,'loaded_at',s.loaded_at,
            'custody_confirmed_at',s.custody_confirmed_at,'failed_at',s.failed_at,
            'failure_reason',s.failure_reason,'returned_at',s.returned_at,'proof_metadata',s.proof_metadata
          ) order by s.sequence)
          from public.ops_delivery_stops s where s.run_id=r.id
        ),'[]'::jsonb)
      ) as run_json
      from public.ops_delivery_runs r
      left join public.delivery_regions_v1 rg on rg.id=r.region_id
      left join public.delivery_drivers_v1 dr on dr.id=r.driver_id
      left join public.delivery_vehicles_v1 vh on vh.id=r.vehicle_id
      where r.service_date=(now() at time zone 'America/Cuiaba')::date
        and r.status<>'cancelled'
    ) q
  ),'[]'::jsonb)
);
$function$
;

-- function: get_ops_inventory_incidents_v1(p_limit integer)
CREATE OR REPLACE FUNCTION public.get_ops_inventory_incidents_v1(p_limit integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'open',count(*) filter (where status in ('open','review')),
    'damage',count(*) filter (where status in ('open','review') and incident_type='damage'),
    'expired',count(*) filter (where status in ('open','review') and incident_type='expired'),
    'loss',count(*) filter (where status in ('open','review') and incident_type='loss'),
    'return',count(*) filter (where status in ('open','review') and incident_type='return'),
    'incidents',coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id',id,'created_at',created_at,'incident_type',incident_type,'status',status,
          'product_id',product_id,'product_name',product_name_snapshot,'gtin',gtin_snapshot,
          'sku',sku_snapshot,'quantity',quantity,'local_stock_before',local_stock_before,
          'local_stock_delta',local_stock_delta,'local_stock_after',local_stock_after,
          'local_stock_applied',local_stock_applied,'needs_bling_reconciliation',needs_bling_reconciliation,
          'operator_label',operator_label,'note',note,'source_order_id',source_order_id
        ) order by created_at desc
      ) filter (where rn<=greatest(1,least(100,coalesce(p_limit,30)))),
      '[]'::jsonb
    )
  )
  from (
    select i.*,row_number() over(order by created_at desc) rn
    from public.ops_inventory_incidents i
    where status in ('open','review')
  ) x;
$function$
;

-- function: get_ops_print_queue_v1(p_limit integer)
CREATE OR REPLACE FUNCTION public.get_ops_print_queue_v1(p_limit integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'generated_at',now(),
    'pending',count(*) filter (where status='pending'),
    'failed',count(*) filter (where status='failed'),
    'claimed',count(*) filter (where status='claimed'),
    'jobs',coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id',id,'job_type',job_type,'entity_type',entity_type,'entity_id',entity_id,
          'version_key',version_key,'printer_profile',printer_profile,'status',status,
          'copies',copies,'attempts',attempts,'created_at',created_at,'updated_at',updated_at,
          'last_error',last_error,'payload',payload
        ) order by created_at
      ) filter (where status in ('pending','failed','claimed')),
      '[]'::jsonb
    )
  )
  from (
    select *
    from public.ops_print_jobs
    where status in ('pending','failed','claimed')
    order by created_at
    limit greatest(1,least(100,coalesce(p_limit,30)))
  ) x;
$function$
;

-- function: get_ops_stock_recount_queue_v1()
CREATE OR REPLACE FUNCTION public.get_ops_stock_recount_queue_v1()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'count',count(*),
    'high',count(*) filter (where a.priority='high'),
    'normal',count(*) filter (where a.priority='normal'),
    'items',coalesce(jsonb_agg(
      jsonb_build_object(
        'attention_id',a.id,
        'product_id',p.id,
        'name',p.name,
        'gtin',p.gtin,
        'sku',p.sku,
        'gondola_number',case when p.gondola ~ '^\\d+$' then p.gondola::integer else null end,
        'shelf_label',p.shelf,
        'priority',a.priority,
        'legacy_stock',coalesce((a.evidence->>'legacy_stock')::numeric,p.stock,0),
        'bling_physical',coalesce((a.evidence->>'bling_physical')::numeric,0),
        'bling_virtual',coalesce((a.evidence->>'bling_virtual')::numeric,0),
        'bling_product_id',nullif(a.evidence->>'bling_product_id',''),
        'reconciliation_class',a.evidence->>'reconciliation_class',
        'previous_physical_verification_at',a.evidence->>'previous_physical_verification_at',
        'automatic_stock_write',false
      )
      order by case a.priority when 'critical' then 0 when 'high' then 1 else 2 end,p.name
    ),'[]'::jsonb)
  )
  from public.ops_attention a
  join public.products p on p.id::text=a.entity_id
  where a.status in ('open','acknowledged')
    and a.idempotency_key like 'ops2:stock-recount:%';
$function$
;

-- function: get_papoai_webhook_capture_status_v2()
CREATE OR REPLACE FUNCTION public.get_papoai_webhook_capture_status_v2()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'capture_enabled',r.capture_enabled,
    'last_seen_at',r.last_seen_at,
    'last_event_key',r.last_event_key,
    'last_error',r.last_error,
    'captured_24h',(select count(*) from public.papoai_webhook_inbox_v2 where received_at>=now()-interval '24 hours'),
    'pending',(select count(*) from public.papoai_webhook_inbox_v2 where status in ('captured','normalized') and expires_at>now()),
    'raw_pending',(select count(*) from public.papoai_webhook_inbox_v2 where status='captured' and expires_at>now()),
    'normalized_pending',(select count(*) from public.papoai_webhook_inbox_v2 where status='normalized' and expires_at>now()),
    'review_required',(select count(*) from public.papoai_webhook_inbox_v2 where status='review_required' and expires_at>now()),
    'conversation_linked_24h',(
      select count(*)
      from public.papoai_webhook_inbox_v2
      where received_at>=now()-interval '24 hours'
        and status='normalized'
        and coalesce(metadata->>'conversation_id','')<>''
    ),
    'conversation_unlinked_24h',(
      select count(*)
      from public.papoai_webhook_inbox_v2
      where received_at>=now()-interval '24 hours'
        and status='normalized'
        and coalesce(metadata->>'conversation_id','')=''
    ),
    'expired',(select count(*) from public.papoai_webhook_inbox_v2 where expires_at<=now()),
    'adapter_version',2,
    'conversation_bridge_version',2
  )
  from public.papoai_webhook_runtime_v2 r
  where r.id=1;
$function$
;

-- function: get_papoai_webhook_health_v3()
CREATE OR REPLACE FUNCTION public.get_papoai_webhook_health_v3()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
with runtime as (
  select r.*
  from public.papoai_webhook_runtime_v2 r
  where r.id=1
), status_31d as (
  select i.status,count(*)::int as cnt
  from public.papoai_webhook_inbox_v2 i
  where i.received_at>=now()-interval '31 days'
  group by i.status
), channel_31d as (
  select
    coalesce(
      nullif(right(regexp_replace(coalesce(i.metadata->>'business_phone_e164',i.metadata->>'phone_to',''),'\D','','g'),4),''),
      'unknown'
    ) as channel_suffix,
    count(*)::int as cnt
  from public.papoai_webhook_inbox_v2 i
  where i.received_at>=now()-interval '31 days'
  group by 1
)
select jsonb_build_object(
  'generated_at',now(),
  'capture_enabled',(select capture_enabled from runtime),
  'last_seen_at',(select last_seen_at from runtime),
  'freshness_seconds',(
    select case when last_seen_at is null then null else extract(epoch from (now()-last_seen_at))::bigint end
    from runtime
  ),
  'last_runtime_error',(select last_error from runtime),
  'events_total',(select count(*) from public.papoai_webhook_inbox_v2),
  'events_24h',(select count(*) from public.papoai_webhook_inbox_v2 where received_at>=now()-interval '24 hours'),
  'raw_pending',(
    select count(*) from public.papoai_webhook_inbox_v2
    where status='captured' and expires_at>now()
  ),
  'normalized_terminal',(
    select count(*) from public.papoai_webhook_inbox_v2 where status='normalized'
  ),
  'processed_special',(
    select count(*) from public.papoai_webhook_inbox_v2 where status='processed'
  ),
  'review_required',(
    select count(*) from public.papoai_webhook_inbox_v2 where status='review_required'
  ),
  'events_with_error',(
    select count(*) from public.papoai_webhook_inbox_v2
    where nullif(btrim(coalesce(last_error,'')),'') is not null
  ),
  'conversation_linked_24h',(
    select count(*) from public.papoai_webhook_inbox_v2
    where received_at>=now()-interval '24 hours'
      and status in ('normalized','processed')
      and nullif(metadata->>'conversation_id','') is not null
  ),
  'conversation_unlinked_24h',(
    select count(*) from public.papoai_webhook_inbox_v2
    where received_at>=now()-interval '24 hours'
      and status in ('normalized','processed')
      and nullif(metadata->>'conversation_id','') is null
  ),
  'customer_linked_24h',(
    select count(*) from public.papoai_webhook_inbox_v2
    where received_at>=now()-interval '24 hours'
      and nullif(metadata->>'customer_id','') is not null
  ),
  'status_counts_31d',coalesce((select jsonb_object_agg(status,cnt) from status_31d),'{}'::jsonb),
  'channel_counts_31d',coalesce((select jsonb_object_agg(channel_suffix,cnt) from channel_31d),'{}'::jsonb),
  'flow_events_total',(select count(*) from public.papoai_customer_flow_events_v1),
  'flow_events_review',(select count(*) from public.papoai_customer_flow_events_v1 where status<>'processed'),
  'registration_summary',public.ops2_customer_registration_summary_v1(31),
  'structured_draft_enabled',(select structured_draft_enabled from public.ops2_papoai_bridge_runtime_v1 where id=1),
  'structured_order_commit_enabled',(select structured_order_commit_enabled from public.ops2_papoai_bridge_runtime_v1 where id=1)
);
$function$
;

