-- function: get_purchase_xml_receipt_preflight_v1(p_document_id uuid)
CREATE OR REPLACE FUNCTION public.get_purchase_xml_receipt_preflight_v1(p_document_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  d public.purchase_xml_documents%rowtype;
  v_total integer:=0;
  v_ready integer:=0;
  v_review integer:=0;
  v_unlinked integer:=0;
  v_lot_rows integer:=0;
  v_lot_review integer:=0;
  v_cpf boolean:=false;
begin
  select * into d from public.purchase_xml_documents where id=p_document_id;
  if not found then return jsonb_build_object('ok',false,'ready',false,'error','document_not_found'); end if;
  select count(*),
    count(*) filter(where product_id is not null and conversion_status<>'review_required'
      and processing_status not in ('review_required','failed','pending') and coalesce(converted_quantity,0)>0
      and coalesce(base_unit_cost,0)>=0),
    count(*) filter(where product_id is null or conversion_status='review_required'
      or processing_status in ('review_required','failed','pending') or coalesce(converted_quantity,0)<=0),
    count(*) filter(where product_id is not null and not exists(
      select 1 from public.bling_hub_entity_links_v2 l where l.entity_type='product' and l.status='matched'
        and l.source_id=purchase_xml_items.product_id::text))
  into v_total,v_ready,v_review,v_unlinked
  from public.purchase_xml_items where document_id=p_document_id and stock_update_requested is true;
  select count(*),count(*) filter(where e.status='review_required') into v_lot_rows,v_lot_review
  from public.purchase_xml_item_lot_evidence e join public.purchase_xml_items i on i.id=e.purchase_item_id
  where i.document_id=p_document_id and i.stock_update_requested is true;
  v_cpf:=d.recipient_kind='CPF';
  return jsonb_build_object(
    'ok',true,'document_id',d.id,'document_key',d.document_key,'processing_status',d.processing_status,
    'receipt_status',d.receipt_status,'recipient_kind',d.recipient_kind,'financial_eligible',d.financial_eligible,
    'finance_status',d.finance_status,'cpf_finance_blocked',v_cpf and d.financial_eligible=false and d.finance_status='blocked_personal',
    'stock_authority','supabase','stock_source','supabase.products.stock','deposit_id',null,
    'item_count',v_total,'ready_item_count',v_ready,'review_item_count',v_review,
    'products_without_bling_link',v_unlinked,'lot_evidence_rows',v_lot_rows,
    'lot_evidence_review_rows',v_lot_review,'expiration_required',false,
    'local_stock_write_allowed',true,'external_bling_receipt_required',false,
    'ready',d.processing_status='processed' and v_total>0 and v_review=0 and v_lot_review=0,
    'blocking_reasons',to_jsonb(array_remove(array[
      case when d.processing_status<>'processed' then 'document_not_processed' end,
      case when v_total=0 then 'no_stock_items_selected' end,
      case when v_review>0 then 'items_require_conversion_or_product_match_review' end,
      case when v_lot_review>0 then 'lot_evidence_requires_review' end
    ],null))
  );
end;
$function$
;

-- function: get_simples_period_gate_v1(p_period_id uuid)
CREATE OR REPLACE FUNCTION public.get_simples_period_gate_v1(p_period_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
with p as (
  select * from public.simples_periods where id=p_period_id
), counts as (
  select
    count(*) filter (where status='open' and severity='blocking')::int as blocking,
    count(*) filter (where status='open' and severity='warning')::int as warnings
  from public.simples_reconciliation_issues
  where period_id=p_period_id
), lines as (
  select count(*) filter (where classification_status <> 'classified')::int as unresolved
  from public.simples_revenue_lines where period_id=p_period_id
), reason_rows as (
  select 'collection_not_complete'::text as reason from p where collection_status <> 'complete'
  union all select 'blocking_issues' from counts where blocking > 0
  union all select 'unresolved_revenue_lines' from lines where unresolved > 0
  union all select 'rbt12_missing' from p where rbt12 is null
  union all select 'rule_set_missing' from p where rule_set_id is null
  union all select 'period_locked' from p where status in ('locked','superseded')
)
select jsonb_build_object(
  'ready', coalesce((select collection_status='complete' and status not in ('locked','superseded') and rule_set_id is not null and rbt12 is not null from p),false)
           and coalesce((select blocking=0 from counts),true)
           and coalesce((select unresolved=0 from lines),true),
  'blocking_issue_count', coalesce((select blocking from counts),0),
  'warning_count', coalesce((select warnings from counts),0),
  'reasons', coalesce((select jsonb_agg(reason order by reason) from reason_rows),'[]'::jsonb)
);
$function$
;

-- function: get_whatsapp_checkout_contact_v1(p_conversation_id uuid)
CREATE OR REPLACE FUNCTION public.get_whatsapp_checkout_contact_v1(p_conversation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  c public.conversations%rowtype;u public.customers%rowtype;a public.customer_addresses%rowtype;s public.whatsapp_sales_state%rowtype;
  ident jsonb; addr jsonb:='{}'::jsonb; display_name text; person_name text; base_complete boolean;
begin
  ident:=public.link_whatsapp_customer_from_phone_v1(p_conversation_id);
  select * into c from public.conversations where id=p_conversation_id;
  if not found then raise exception 'conversation_not_found'; end if;
  if c.customer_id is not null then
    select * into u from public.customers where id=c.customer_id;
    select * into a from public.customer_addresses where customer_id=c.customer_id and is_active=true order by is_default desc,updated_at desc limit 1;
  end if;
  select * into s from public.whatsapp_sales_state where conversation_id=c.id;
  addr:=jsonb_build_object(
    'street',coalesce(nullif(s.pending_delivery_address->>'street',''),a.street,''),
    'number',coalesce(nullif(s.pending_delivery_address->>'number',''),a.number,''),
    'complement',coalesce(nullif(s.pending_delivery_address->>'complement',''),a.complement,''),
    'neighborhood',coalesce(nullif(s.pending_delivery_address->>'neighborhood',''),a.neighborhood,''),
    'city',coalesce(nullif(s.pending_delivery_address->>'city',''),a.city,''),
    'state',coalesce(nullif(s.pending_delivery_address->>'state',''),a.state,'MT'),
    'postal_code',coalesce(nullif(s.pending_delivery_address->>'postal_code',''),a.postal_code,''),
    'reference',coalesce(nullif(s.pending_delivery_address->>'reference',''),a.reference,'')
  );
  display_name:=nullif(trim(coalesce(u.name,'')),'');
  person_name:=case when u.id is null then null else public.customer_person_first_name_v1(u.name,u.cpf_cnpj) end;
  base_complete:=display_name is not null and nullif(addr->>'street','') is not null and nullif(addr->>'number','') is not null
    and nullif(addr->>'neighborhood','') is not null and public.normalize_local_delivery_city_v1(addr->>'city') is not null;
  return jsonb_build_object('known_customer',u.id is not null,'customer_id',u.id,'name',display_name,'person_name',person_name,
    'phone',coalesce(u.primary_whatsapp_e164,c.wa_contact_e164),'phone_display',public.format_phone_br_v1(coalesce(u.primary_whatsapp_e164,c.wa_contact_e164)),
    'address',addr,'base_complete',base_complete,'locator',addr->>'reference');
end $function$
;

-- function: get_whatsapp_sellable_product_v1(p_product_id uuid)
CREATE OR REPLACE FUNCTION public.get_whatsapp_sellable_product_v1(p_product_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select case when p.id is null then null else jsonb_build_object(
    'id',p.id,'sku',p.sku,'gtin',p.gtin,'name',p.name,'brand',p.brand,
    'category',p.category,'packaging',p.packaging,'price',p.price,'stock',p.stock,
    'image_url',p.image_url,'description_short',p.description_short,
    'gondola',p.gondola,'shelf',p.shelf,'source','counter_verified'
  ) end
  from public.products p
  where p.id=p_product_id
    and p.is_active=true
    and p.price is not null
    and p.price>=0
    and coalesce(p.stock,0)>0
$function$
;

-- function: get_whatsapp_simple_baskets_v1()
CREATE OR REPLACE FUNCTION public.get_whatsapp_simple_baskets_v1()
 RETURNS TABLE(id uuid, name text, display_name text, base_price numeric, image_url text, sort_order integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select b.id,b.name,case when lower(b.name)='economica bonini' then 'Econômica' else b.name end,b.base_price,b.image_url,b.sort_order
  from public.basket_templates b where b.is_active=true and b.is_whatsapp_active=true order by b.sort_order,b.name
