-- function: guard_simples_locked_snapshot_v1()
CREATE OR REPLACE FUNCTION public.guard_simples_locked_snapshot_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if tg_op='DELETE' and old.status in ('locked','superseded') then
    raise exception 'simples_locked_snapshot_immutable';
  end if;
  if tg_op='UPDATE' and old.status in ('locked','superseded') then
    if old.status='locked' and new.status='superseded'
       and (to_jsonb(new) - 'status' - 'updated_at') = (to_jsonb(old) - 'status' - 'updated_at') then
      return new;
    end if;
    raise exception 'simples_locked_snapshot_immutable';
  end if;
  return coalesce(new,old);
end;
$function$
;

-- function: guard_web_existing_customer_binding_v1()
CREATE OR REPLACE FUNCTION public.guard_web_existing_customer_binding_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_customer_created_at timestamptz;
begin
  if old.customer_id is null
     and new.customer_id is not null
     and coalesce(old.metadata->>'entry_channel',new.metadata->>'entry_channel','')='website'
     and nullif(coalesce(new.metadata->>'web_identity_verified_at',''),'') is null
     and nullif(coalesce(new.metadata->>'web_customer_committed_at',''),'') is null then
    select c.created_at into v_customer_created_at
      from public.customers c
     where c.id=new.customer_id;
    if v_customer_created_at is not null and v_customer_created_at < old.created_at then
      raise exception 'customer_verification_required';
    end if;
  end if;
  return new;
end;
$function$
;

-- function: handle_basket_product_unavailable_v1(p_product_id uuid)
CREATE OR REPLACE FUNCTION public.handle_basket_product_unavailable_v1(p_product_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  r record;
  candidate record;
  v_keep_active boolean:=false;
  v_stock numeric;
begin
  for r in
    select opt.id as option_id,opt.position_id,opt.sort_order,
           pos.quantity,coalesce(opt.metadata,'{}'::jsonb) as metadata
    from public.basket_mold_position_options opt
    join public.basket_mold_positions pos on pos.id=opt.position_id
    join public.basket_molds mold on mold.id=pos.mold_id
    join public.basket_templates basket on basket.id=mold.basket_id
    where opt.product_id=p_product_id and basket.is_active=true
    order by opt.position_id,opt.sort_order,opt.id
  loop
    -- Prefer the next configured option that is active and covers the position.
    select opt.id,opt.product_id,opt.sort_order,p.is_active,
           public.basket_component_fresh_sellable_stock_v1(p.id) as stock
      into candidate
    from public.basket_mold_position_options opt
    join public.products p on p.id=opt.product_id
    where opt.position_id=r.position_id and opt.id<>r.option_id
      and p.is_active=true
      and coalesce(public.basket_component_fresh_sellable_stock_v1(p.id),0)>=r.quantity
    order by case when (opt.sort_order,opt.product_id)>(r.sort_order,p_product_id) then 0 else 1 end,
             opt.sort_order,opt.product_id
    limit 1;

    -- If none can cover the basket, use the next active configured option and flag it for review.
    if not found then
      select opt.id,opt.product_id,opt.sort_order,p.is_active,
             public.basket_component_fresh_sellable_stock_v1(p.id) as stock
        into candidate
      from public.basket_mold_position_options opt
      join public.products p on p.id=opt.product_id
      where opt.position_id=r.position_id and opt.id<>r.option_id
        and p.is_active=true
      order by case when (opt.sort_order,opt.product_id)>(r.sort_order,p_product_id) then 0 else 1 end,
               opt.sort_order,opt.product_id
      limit 1;
    end if;

    -- If every remaining variation is inactive, keep one configured option for manual correction.
    if not found then
      select opt.id,opt.product_id,opt.sort_order,p.is_active,
             public.basket_component_fresh_sellable_stock_v1(p.id) as stock
        into candidate
      from public.basket_mold_position_options opt
      join public.products p on p.id=opt.product_id
      where opt.position_id=r.position_id and opt.id<>r.option_id
      order by case when (opt.sort_order,opt.product_id)>(r.sort_order,p_product_id) then 0 else 1 end,
               opt.sort_order,opt.product_id
      limit 1;
    end if;

    if not found then
      update public.basket_mold_position_options
      set metadata=(coalesce(metadata,'{}'::jsonb)-'manual_replacement_reason')
        ||jsonb_build_object('manual_replacement_required',true,
                             'manual_replacement_reason','only_configured_option_unavailable')
      where id=r.option_id;
      v_keep_active:=true;
      continue;
    end if;

    delete from public.basket_mold_position_options where id=r.option_id;

    update public.basket_mold_position_options
    set metadata=(coalesce(metadata,'{}'::jsonb)-'manual_replacement_required'-'manual_replacement_reason')
          ||jsonb_build_object('preferred',(id=candidate.id)),
        updated_at=now()
    where position_id=r.position_id;

    with ordered as (
      select id,(row_number() over(order by case when id=candidate.id then 0 else 1 end,
                                            sort_order,product_id)-1)::integer as next_order
      from public.basket_mold_position_options
      where position_id=r.position_id
    )
    update public.basket_mold_position_options opt
    set sort_order=ordered.next_order,updated_at=now()
    from ordered where opt.id=ordered.id;

    v_stock:=coalesce(candidate.stock,0);
    if candidate.is_active is not true or v_stock<r.quantity then
      update public.basket_mold_position_options
      set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object(
        'manual_replacement_required',true,
        'manual_replacement_reason',case
          when candidate.is_active is not true then 'replacement_product_inactive'
          else 'replacement_has_no_sellable_stock'
        end
      )
      where id=candidate.id;
    end if;
  end loop;

  return v_keep_active;
end;
$function$
;

-- function: install_bling_api_credentials_v1(p_client_id text, p_client_secret text, p_refresh_token text)
CREATE OR REPLACE FUNCTION public.install_bling_api_credentials_v1(p_client_id text, p_client_secret text, p_refresh_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid;
begin
  if nullif(trim(coalesce(p_client_id,'')),'') is null then raise exception 'client_id_required'; end if;
  if nullif(trim(coalesce(p_client_secret,'')),'') is null then raise exception 'client_secret_required'; end if;
  if nullif(trim(coalesce(p_refresh_token,'')),'') is null then raise exception 'refresh_token_required'; end if;

  select id into v_id from vault.secrets where name='bling_api_client_id_v1' order by updated_at desc limit 1;
  if v_id is null then
    perform vault.create_secret(trim(p_client_id),'bling_api_client_id_v1','Bling API V3 Client ID - server-side only',null);
  else
    perform vault.update_secret(v_id,trim(p_client_id),'bling_api_client_id_v1','Bling API V3 Client ID - server-side only',null);
  end if;

  v_id:=null;
  select id into v_id from vault.secrets where name='bling_api_client_secret_v1' order by updated_at desc limit 1;
  if v_id is null then
    perform vault.create_secret(trim(p_client_secret),'bling_api_client_secret_v1','Bling API V3 Client Secret - server-side only',null);
  else
    perform vault.update_secret(v_id,trim(p_client_secret),'bling_api_client_secret_v1','Bling API V3 Client Secret - server-side only',null);
  end if;

  v_id:=null;
  select id into v_id from vault.secrets where name='bling_api_refresh_token_v1' order by updated_at desc limit 1;
  if v_id is null then
    perform vault.create_secret(trim(p_refresh_token),'bling_api_refresh_token_v1','Bling API V3 Refresh Token - server-side only',null);
  else
    perform vault.update_secret(v_id,trim(p_refresh_token),'bling_api_refresh_token_v1','Bling API V3 Refresh Token - server-side only',null);
  end if;

  return jsonb_build_object('ok',true,'stored',3);
end
$function$
;

-- function: inventory_label_claim_next()
CREATE OR REPLACE FUNCTION public.inventory_label_claim_next()
 RETURNS TABLE(photo_id uuid, storage_path text, attempt_no integer, claim_token uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_id uuid;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'worker_only' USING ERRCODE='42501';
  END IF;
  UPDATE public.inventory_label_photos
  SET status='failed',error_code='worker_timeout',error_detail='Limite de tentativas',
      finished_at=now(),updated_at=now(),claim_token=NULL
  WHERE status='processing' AND attempts>=3 AND claimed_at<now()-interval '5 minutes';
  SELECT p.id INTO v_id
    FROM public.inventory_label_photos AS p
    WHERE p.attempts<3 AND
    ((p.status IN ('queued','retry') AND COALESCE(p.next_attempt_at,now())<=now())
    OR (p.status='processing' AND p.claimed_at<now()-interval '5 minutes'))
    ORDER BY p.created_at,p.id FOR UPDATE SKIP LOCKED LIMIT 1;
  IF v_id IS NULL THEN RETURN; END IF;
  UPDATE public.inventory_label_photos
  SET status='processing',attempts=attempts+1,claim_token=gen_random_uuid(),
      claimed_at=now(),next_attempt_at=NULL,updated_at=now(),
      error_code=NULL,error_detail=NULL
  WHERE id=v_id;
  RETURN QUERY SELECT p.id,p.storage_path,p.attempts::integer,p.claim_token
    FROM public.inventory_label_photos AS p WHERE p.id=v_id;
END $function$
;

-- function: inventory_label_fail_photo(p_photo_id uuid, p_claim_token uuid, p_error_code text, p_error_detail text)
CREATE OR REPLACE FUNCTION public.inventory_label_fail_photo(p_photo_id uuid, p_claim_token uuid, p_error_code text, p_error_detail text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_attempts integer;v_status text;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN
  RAISE EXCEPTION 'worker_only' USING ERRCODE='42501';
 END IF;
 SELECT attempts INTO v_attempts FROM public.inventory_label_photos
  WHERE id=p_photo_id AND claim_token=p_claim_token AND status='processing' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'stale_claim' USING ERRCODE='40001'; END IF;
 v_status:=CASE WHEN v_attempts>=3 THEN 'failed' ELSE 'retry' END;
 UPDATE public.inventory_label_photos
 SET status=v_status,error_code=left(coalesce(p_error_code,'read_failed'),80),
  error_detail=left(coalesce(p_error_detail,''),500),
  next_attempt_at=CASE WHEN v_status='retry' THEN now()+make_interval(secs=>CASE WHEN v_attempts=1 THEN 15 ELSE 60 END) ELSE NULL END,
  finished_at=CASE WHEN v_status='failed' THEN now() ELSE NULL END,
  claim_token=NULL,claimed_at=NULL,updated_at=now()
 WHERE id=p_photo_id;
 RETURN v_status;
END $function$
;

-- function: inventory_label_finish_photo(p_photo_id uuid, p_claim_token uuid, p_product_id uuid, p_label_serial text, p_readings jsonb, p_errors jsonb)
CREATE OR REPLACE FUNCTION public.inventory_label_finish_photo(p_photo_id uuid, p_claim_token uuid, p_product_id uuid, p_label_serial text, p_readings jsonb, p_errors jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 v_photo public.inventory_label_photos%ROWTYPE;
 v_reading jsonb;v_slot integer;v_qty integer;v_conf numeric;
 v_duplicates integer:=0;v_inserted integer:=0;v_status text;
 v_seen integer[]:='{}';
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN
  RAISE EXCEPTION 'worker_only' USING ERRCODE='42501';
 END IF;
 SELECT * INTO v_photo FROM public.inventory_label_photos
 WHERE id=p_photo_id AND claim_token=p_claim_token AND status='processing' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'stale_claim' USING ERRCODE='40001'; END IF;
 IF p_label_serial !~ '^[0-9A-F]{10,20}$' OR p_product_id IS NULL THEN
  RAISE EXCEPTION 'invalid_identity' USING ERRCODE='22023';
 END IF;
 IF p_readings IS NULL OR p_errors IS NULL
  OR jsonb_typeof(p_readings) IS DISTINCT FROM 'array'
  OR jsonb_typeof(p_errors) IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'invalid_readings' USING ERRCODE='22023';
 END IF;
 IF jsonb_array_length(p_readings)>6 THEN
  RAISE EXCEPTION 'too_many_readings' USING ERRCODE='22023';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.products WHERE id=p_product_id) THEN
  RAISE EXCEPTION 'product_not_found' USING ERRCODE='22023';
 END IF;
 FOR v_reading IN SELECT value FROM jsonb_array_elements(p_readings) LOOP
  IF jsonb_typeof(v_reading) <> 'object' THEN
   RAISE EXCEPTION 'invalid_reading' USING ERRCODE='22023';
  END IF;
  BEGIN
   v_slot:=(v_reading->>'slot')::integer;
   v_qty:=(v_reading->>'quantity')::integer;
   v_conf:=(v_reading->>'confidence')::numeric;
  EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
   RAISE EXCEPTION 'invalid_reading' USING ERRCODE='22023';
  END;
  IF v_slot IS NULL OR v_slot NOT BETWEEN 1 AND 6
   OR v_qty IS NULL OR v_qty NOT BETWEEN 0 AND 99
   OR v_conf IS NULL OR v_conf NOT BETWEEN 0 AND 1
   OR v_slot=ANY(v_seen) THEN
   RAISE EXCEPTION 'invalid_reading' USING ERRCODE='22023';
  END IF;
  v_seen:=array_append(v_seen,v_slot);
  INSERT INTO public.inventory_label_counts
   (photo_id,batch_id,product_id,label_serial,balance_slot,quantity,confidence,status)
  VALUES(p_photo_id,v_photo.batch_id,p_product_id,p_label_serial,v_slot,v_qty,v_conf,'pending_review')
  ON CONFLICT (label_serial,balance_slot) DO NOTHING;
  IF FOUND THEN v_inserted:=v_inserted+1; ELSE v_duplicates:=v_duplicates+1; END IF;
 END LOOP;
 v_status:=CASE WHEN v_duplicates>0 OR jsonb_array_length(p_errors)>0 OR v_inserted=0
  THEN 'needs_review' ELSE 'complete' END;
 UPDATE public.inventory_label_photos
 SET status=v_status,parsed=jsonb_build_object('product_id',p_product_id,'label_serial',p_label_serial,
  'readings',p_readings,'errors',p_errors,'duplicates',v_duplicates),
  error_code=CASE WHEN v_duplicates>0 THEN 'duplicate_balance_slot'
   WHEN jsonb_array_length(p_errors)>0 THEN 'ambiguous_marks'
   WHEN v_inserted=0 THEN 'no_active_balance' ELSE NULL END,
  claim_token=NULL,claimed_at=NULL,finished_at=now(),updated_at=now()
 WHERE id=p_photo_id;
 RETURN jsonb_build_object('status',v_status,'inserted',v_inserted,'duplicates',v_duplicates);
END $function$
;

-- function: is_customer_purchase_valid_v1(p_status text, p_cancelled_at timestamp with time zone, p_returned_at timestamp with time zone)
CREATE OR REPLACE FUNCTION public.is_customer_purchase_valid_v1(p_status text, p_cancelled_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_returned_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select
    p_cancelled_at is null
    and p_returned_at is null
    and coalesce(p_status,'') = any(array[
      'storefront_received',
      'confirmed',
      'sent_to_bling',
      'processing',
      'ready',
      'out_for_delivery',
      'delivered'
    ]::text[])
$function$
;

-- function: link_unclaimed_orders_to_customer_v2(p_customer_id uuid)
CREATE OR REPLACE FUNCTION public.link_unclaimed_orders_to_customer_v2(p_customer_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_phone text; v_normalized text; v_count integer:=0;
begin
  select primary_whatsapp_e164 into v_phone from public.customers where id=p_customer_id;
  if not found or nullif(v_phone,'') is null then return 0; end if;
  begin
    v_normalized:=public.normalize_storefront_phone_v2(v_phone);
  exception when others then
    return 0;
  end;
  update public.orders
     set customer_id=p_customer_id,updated_at=now()
   where customer_id is null and phone_e164=v_normalized;
  get diagnostics v_count=row_count;
  return v_count;
end;
$function$
;

-- function: lookup_customer_by_phone(p_phone text)
CREATE OR REPLACE FUNCTION public.lookup_customer_by_phone(p_phone text)
 RETURNS TABLE(customer_id uuid, bling_contact_id bigint, customer_name text, preferred_reply text)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with r as (
    select public.resolve_customer_by_phone_v1(p_phone) as j
  )
  select c.id,c.bling_contact_id,c.name,c.preferred_reply
    from r
    join public.customers c
      on (r.j->>'match_status')='matched'
     and c.id=(r.j->>'customer_id')::uuid
$function$
;

-- function: manual_pick_queue_action_v1(p_action text, p_order_id uuid)
CREATE OR REPLACE FUNCTION public.manual_pick_queue_action_v1(p_action text, p_order_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user uuid := auth.uid();
  v_role text;
  v_status text;
  v_ids jsonb;
begin
  select a.role into v_role
    from public.admin_users a
   where a.user_id = v_user and a.is_active = true;
  if v_role is null then
    raise exception 'admin_not_authorized' using errcode = '42501';
  end if;
  if p_action not in ('list','add','remove') or p_action is null then
    raise exception 'invalid_queue_action' using errcode = '22023';
  end if;
  if p_action <> 'list' then
    if v_role = 'viewer' then
      raise exception 'queue_update_forbidden' using errcode = '42501';
    end if;
    if p_order_id is null then
      raise exception 'order_id_required' using errcode = '22023';
    end if;
    if p_action = 'add' then
      select o.status into v_status
        from public.orders o where o.id = p_order_id for update;
      if v_status is distinct from 'confirmed' then
        raise exception 'order_not_confirmed_for_queue' using errcode = '22023';
      end if;
      insert into public.order_manual_separation_queue_v1(order_id,selected_by)
      values (p_order_id,v_user) on conflict (order_id) do nothing;
    else
      delete from public.order_manual_separation_queue_v1
        where order_id = p_order_id;
    end if;
  end if;
  select coalesce(jsonb_agg(q.order_id order by q.selected_at, q.order_id),'[]'::jsonb)
    into v_ids
    from public.order_manual_separation_queue_v1 q
    join public.orders o on o.id = q.order_id
   where o.status in ('confirmed','processing');
  return jsonb_build_object('order_ids',v_ids);
end;
$function$
;

-- function: manual_pick_queue_feed_v1()
CREATE OR REPLACE FUNCTION public.manual_pick_queue_feed_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_rows jsonb;
begin
  if not exists (
    select 1 from public.admin_users a
     where a.user_id = v_uid and a.is_active = true
  ) then
    raise exception 'admin_not_authorized' using errcode = '42501';
  end if;
  select coalesce(jsonb_agg(x.obj order by x.selected_at asc, x.order_id asc), '[]'::jsonb)
  into v_rows
  from (
    select q.selected_at,q.order_id,
      jsonb_build_object(
        'id',o.id,
        'order_number',o.order_number,
        'public_code',p.public_code,
        'status',o.status,
        'created_at',o.created_at,
        'selected_at',q.selected_at,
        'customer_name',coalesce(nullif(o.customer_snapshot->>'name',''),
                                  nullif(o.delivery_address->>'customer_name',''),
                                  nullif(o.delivery_address->>'recipient_name',''),'Cliente'),
        'total',o.total,
        'separator_key',a.separator_key,
        'separator_label',a.separator_label,
        'completed',c.completed_at is not null,
        'completed_at',c.completed_at,
        'completed_separator_key',c.separator_key,
        'completed_separator_label',coalesce(a.separator_label,case c.separator_key when 'jose' then 'José' when 'claudio' then 'Cláudio' when 'claudenil' then 'Claudenil' when 'jovenil' then 'Jovenil' when 'kelly' then 'Kelly' else null end),
        'counts',jsonb_build_object(
          'total',coalesce(s.total,0),
          'pending',coalesce(s.pending,0),
          'separated',coalesce(s.separated,0),
          'missing',coalesce(s.missing,0)
        )
      ) as obj
    from public.order_manual_separation_queue_v1 q
    join public.orders o on o.id=q.order_id
    left join public.order_public_snapshots_v1 p on p.order_id=o.id
    left join public.order_separation_assignments_v1 a on a.order_id=o.id
    left join public.order_separation_completions_v1 c on c.order_id=o.id
    left join lateral (
      select count(*)::int as total,
        count(*) filter(where i.state='pending')::int as pending,
        count(*) filter(where i.state='separated')::int as separated,
        count(*) filter(where i.state='missing')::int as missing
      from public.order_separation_items_v1 i
      where i.order_id=o.id
    ) s on true
    where (o.status in ('confirmed','processing') and c.completed_at is null)
       or (o.status='ready' and c.completed_at is not null)
  ) x;
  return jsonb_build_object('ok',true,'orders',v_rows);
end;
$function$
;

-- function: mark_new_xml_product_for_catalog_enrichment_v1()
CREATE OR REPLACE FUNCTION public.mark_new_xml_product_for_catalog_enrichment_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if coalesce(new.metadata->>'purchase_xml_created','false')='true' then
    new.metadata := coalesce(new.metadata,'{}'::jsonb) || jsonb_build_object('ean_reader_segment_visible',true);
  end if;
  return new;
end
$function$
;

-- function: mark_order_dispatch_fiscal_authorized_v1(p_order_id uuid, p_source text, p_bling_invoice_id bigint, p_bling_invoice_number text, p_sefaz_status text, p_authorized_at timestamp with time zone)
CREATE OR REPLACE FUNCTION public.mark_order_dispatch_fiscal_authorized_v1(p_order_id uuid, p_source text, p_bling_invoice_id bigint DEFAULT NULL::bigint, p_bling_invoice_number text DEFAULT NULL::text, p_sefaz_status text DEFAULT NULL::text, p_authorized_at timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if not exists(select 1 from public.orders where id=p_order_id) then
    return jsonb_build_object('ok',false,'error','order_not_found','external_side_effect',false);
  end if;

  insert into public.order_fiscal_controls(
    order_id,dispatch_fiscal_status,dispatch_fiscal_authorized_at,
    dispatch_fiscal_source,dispatch_fiscal_reason,
    bling_invoice_id,bling_invoice_number,sefaz_status,issued_at,updated_at
  )
  values(
    p_order_id,'authorized',coalesce(p_authorized_at,now()),
    nullif(trim(coalesce(p_source,'')),''),null,
    p_bling_invoice_id,nullif(trim(coalesce(p_bling_invoice_number,'')),''),
    nullif(trim(coalesce(p_sefaz_status,'')),''),coalesce(p_authorized_at,now()),now()
  )
  on conflict(order_id) do update
    set dispatch_fiscal_status='authorized',
        dispatch_fiscal_authorized_at=coalesce(p_authorized_at,now()),
        dispatch_fiscal_source=nullif(trim(coalesce(p_source,'')),''),
        dispatch_fiscal_reason=null,
        bling_invoice_id=coalesce(p_bling_invoice_id,public.order_fiscal_controls.bling_invoice_id),
        bling_invoice_number=coalesce(nullif(trim(coalesce(p_bling_invoice_number,'')),''),public.order_fiscal_controls.bling_invoice_number),
        sefaz_status=coalesce(nullif(trim(coalesce(p_sefaz_status,'')),''),public.order_fiscal_controls.sefaz_status),
        issued_at=coalesce(public.order_fiscal_controls.issued_at,p_authorized_at,now()),
        updated_at=now();

  return public.check_order_dispatch_fiscal_gate_v1(p_order_id);
end;
$function$
;

-- function: marketing_accept_meta_dispatch_v1(p_dispatch_id uuid, p_provider_message_id text, p_accepted_at timestamp with time zone)
CREATE OR REPLACE FUNCTION public.marketing_accept_meta_dispatch_v1(p_dispatch_id uuid, p_provider_message_id text, p_accepted_at timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_dispatch public.marketing_campaign_dispatches_v1%rowtype;
  v_outbox public.whatsapp_outbox_v1%rowtype;
  v_message public.whatsapp_messages_v1%rowtype;
  v_finish jsonb;
  v_status_result jsonb;
  v_accepted_at timestamptz:=coalesce(p_accepted_at,now());
  v_wamid text:=nullif(btrim(coalesce(p_provider_message_id,'')),'');
  v_duplicate boolean:=false;
  v_replayed integer:=0;
  v_event_status text;
  v_occurred_at timestamptz;
  r public.whatsapp_webhook_events_v1%rowtype;
begin
  if v_wamid is null or v_wamid !~ '^wamid\.' then
    return jsonb_build_object('ok',false,'error','provider_message_id_required');
  end if;

  select * into v_dispatch
  from public.marketing_campaign_dispatches_v1
  where id=p_dispatch_id
  for update;
  if not found then return jsonb_build_object('ok',false,'error','dispatch_not_found'); end if;

  if v_dispatch.status='accepted' then
    if v_dispatch.provider_message_id is distinct from v_wamid then
      return jsonb_build_object('ok',false,'error','provider_message_conflict');
    end if;
    v_duplicate:=true;
  elsif v_dispatch.status<>'claimed' then
    return jsonb_build_object('ok',false,'error','dispatch_not_claimed','status',v_dispatch.status);
  end if;

  if v_dispatch.outbox_id is null then return jsonb_build_object('ok',false,'error','campaign_outbox_missing'); end if;

  select * into v_outbox
  from public.whatsapp_outbox_v1
  where id=v_dispatch.outbox_id
  for update;
  if not found or v_outbox.purpose<>'marketing_campaign' or v_outbox.message_type<>'template'
     or v_outbox.whatsapp_account_id<>v_dispatch.whatsapp_account_id
     or v_outbox.customer_id is distinct from v_dispatch.customer_id then
    return jsonb_build_object('ok',false,'error','campaign_outbox_invalid');
  end if;
  if v_outbox.message_id is null then return jsonb_build_object('ok',false,'error','canonical_message_missing'); end if;

  select * into v_message
  from public.whatsapp_messages_v1
  where id=v_outbox.message_id
  for update;
  if not found then return jsonb_build_object('ok',false,'error','canonical_message_missing'); end if;

  if v_duplicate is false then
    v_finish:=public.marketing_finish_dispatch_v1(v_dispatch.id,'accepted',v_wamid,null,null);
    if coalesce((v_finish->>'ok')::boolean,false) is not true then
      raise exception 'marketing_accept_finish_failed:%',coalesce(v_finish->>'error','unknown');
    end if;

    update public.whatsapp_messages_v1
    set provider='meta',provider_message_id=v_wamid,status_current='accepted',sender_kind='campaign',sent_at=v_accepted_at,
        metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('source','marketing_campaign_worker','campaign_dispatch_id',v_dispatch.id)
    where id=v_message.id
    returning * into v_message;

    v_status_result:=public.whatsapp_record_status_v1(
      v_dispatch.whatsapp_account_id,'meta',v_wamid,'accepted',v_accepted_at,v_accepted_at,
      null,null,null,jsonb_build_object('source','marketing_campaign_worker','dispatch_id',v_dispatch.id)
    );
    if coalesce((v_status_result->>'ok')::boolean,false) is not true then
      raise exception 'marketing_accept_status_failed:%',coalesce(v_status_result->>'error','unknown');
    end if;
  end if;

  for r in
    select e.*
    from public.whatsapp_webhook_events_v1 e
    where e.whatsapp_account_id=v_dispatch.whatsapp_account_id
      and e.provider='meta'
      and e.provider_message_id=v_wamid
      and e.event_type like 'message.status.%'
      and e.status='received'
    order by e.received_at,e.id
    for update
  loop
    v_event_status:=split_part(r.event_type,'.',3);
    if v_event_status not in ('sent','delivered','read','failed','cancelled') then
      update public.whatsapp_webhook_events_v1
      set status='ignored',processed_at=now(),last_error='status_not_supported_for_replay'
      where id=r.id;
      continue;
    end if;

    v_occurred_at:=case
      when coalesce(r.payload->>'timestamp','') ~ '^\d+(\.\d+)?$'
        then to_timestamp((r.payload->>'timestamp')::double precision)
      else r.received_at
    end;

    v_status_result:=public.whatsapp_record_status_v1(
      v_dispatch.whatsapp_account_id,'meta',v_wamid,v_event_status,v_occurred_at,r.received_at,
      nullif(r.payload->'errors'->0->>'code',''),
      nullif(r.payload->'errors'->0->>'title',''),
      nullif(coalesce(r.payload->'errors'->0->>'message',r.payload->'errors'->0->'error_data'->>'details'),''),
      r.payload
    );

    if coalesce((v_status_result->>'ok')::boolean,false) is true then
      update public.whatsapp_webhook_events_v1
      set status='normalized',processed_at=now(),last_error=null
      where id=r.id;
      v_replayed:=v_replayed+1;
    else
      update public.whatsapp_webhook_events_v1
      set status='review_required',processed_at=now(),last_error=left(coalesce(v_status_result->>'error','status_replay_failed'),500)
      where id=r.id;
    end if;
  end loop;

  select * into v_message from public.whatsapp_messages_v1 where id=v_outbox.message_id;

  return jsonb_build_object(
    'ok',true,
    'duplicate',v_duplicate,
    'dispatch_id',v_dispatch.id,
    'outbox_id',v_outbox.id,
    'message_id',v_message.id,
    'status','accepted',
    'status_current',v_message.status_current,
    'provider_message_id',v_wamid,
    'pending_statuses_replayed',v_replayed
  );
end;
$function$
;

-- function: marketing_acquire_manual_campaign_batch_v1(p_batch_id uuid)
CREATE OR REPLACE FUNCTION public.marketing_acquire_manual_campaign_batch_v1(p_batch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_batch public.marketing_campaign_manual_batches_v1%rowtype;
  v_campaign public.marketing_campaigns_v1%rowtype;
  v_gate jsonb;
  v_items jsonb:='[]'::jsonb;
begin
  select * into v_batch from public.marketing_campaign_manual_batches_v1 where id=p_batch_id for update;
  if not found then return jsonb_build_object('ok',false,'error','manual_batch_not_found'); end if;
  if v_batch.status<>'processing' then return jsonb_build_object('ok',false,'error','manual_batch_not_processing','status',v_batch.status); end if;
  if v_batch.worker_started_at is not null then return jsonb_build_object('ok',false,'error','manual_batch_already_acquired'); end if;
  select * into v_campaign from public.marketing_campaigns_v1 where id=v_batch.campaign_id;
  if not found or v_campaign.status<>'running' or v_campaign.manual_batch_mode is not true then
    return jsonb_build_object('ok',false,'error','manual_campaign_not_running');
  end if;
  v_gate:=public.marketing_campaign_execution_gate_v1(v_campaign.whatsapp_account_id);
  if coalesce((v_gate->>'ok')::boolean,false) is not true then return v_gate; end if;
  if not exists(select 1 from public.whatsapp_accounts a where a.id=v_campaign.whatsapp_account_id
      and a.is_active is true and a.phone_number_id ~ '^[0-9]{5,30}$') then
    return jsonb_build_object('ok',false,'error','account_not_available');
  end if;
  update public.marketing_campaign_manual_batches_v1 set worker_started_at=now() where id=v_batch.id;
  select coalesce(jsonb_agg(to_jsonb(d) order by d.created_at,d.id),'[]'::jsonb) into v_items
    from public.marketing_campaign_dispatches_v1 d
    where d.manual_batch_id=v_batch.id and d.status='claimed';
  return jsonb_build_object('ok',true,'batch_id',v_batch.id,'campaign_id',v_campaign.id,
    'whatsapp_account_id',v_campaign.whatsapp_account_id,'items',v_items,'count',jsonb_array_length(v_items));
end;
$function$
;

-- function: marketing_attribute_order_trigger_v1()
CREATE OR REPLACE FUNCTION public.marketing_attribute_order_trigger_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.customer_id is not null
     and new.confirmed_at is not null
     and new.cancelled_at is null
     and new.returned_at is null
     and (
       tg_op='INSERT'
       or old.customer_id is distinct from new.customer_id
       or old.confirmed_at is distinct from new.confirmed_at
     ) then
    perform public.marketing_attribute_order_v1(new.id,null);
  end if;
  return new;
exception when others then
  -- Marketing é observacional: nunca bloqueia o fluxo operacional do pedido.
  return new;
end;
$function$
;

-- function: marketing_attribute_order_v1(p_order_id uuid, p_token text)
CREATE OR REPLACE FUNCTION public.marketing_attribute_order_v1(p_order_id uuid, p_token text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_order public.orders%rowtype;
  v_token text:=lower(btrim(coalesce(p_token,'')));
  v_hash text;
  v_clicked public.marketing_tracking_links_v1%rowtype;
  v_latest public.marketing_tracking_links_v1%rowtype;
  v_link public.marketing_tracking_links_v1%rowtype;
  v_kind text;
  v_order_commercial_id uuid;
  v_order_lot_id uuid;
  v_item_commercial_id uuid;
  v_item_lot_id uuid;
  v_offer_match boolean:=false;
  v_event_key text;
begin
  select * into v_order from public.orders where id=p_order_id;
  if not found then return jsonb_build_object('ok',false,'error','order_not_found'); end if;
  if v_order.confirmed_at is null then
    return jsonb_build_object('ok',false,'error','order_not_confirmed');
  end if;
  if v_order.cancelled_at is not null or v_order.returned_at is not null then
    return jsonb_build_object('ok',false,'error','order_not_attributable');
  end if;

  v_order_commercial_id:=v_order.basket_id;

  select
    case when coalesce(i.metadata->>'basket_id','') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      then (i.metadata->>'basket_id')::uuid else null end,
    case when coalesce(i.metadata->>'basket_lot_id','') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      then (i.metadata->>'basket_lot_id')::uuid else null end
  into v_item_commercial_id,v_item_lot_id
  from public.order_items i
  where i.order_id=v_order.id
    and ((i.metadata ? 'basket_id') or (i.metadata ? 'basket_lot_id'))
  order by i.created_at,i.id
  limit 1;

  v_order_commercial_id:=coalesce(v_order_commercial_id,v_item_commercial_id);
  v_order_lot_id:=v_item_lot_id;

  -- Quando o token chegou explicitamente, ele tem precedência.
  if v_token ~ '^[0-9a-f]{36}$' then
    v_hash:=encode(extensions.digest(convert_to(v_token,'UTF8'),'sha256'),'hex');
    select * into v_clicked
    from public.marketing_tracking_links_v1
    where token_hash=v_hash
      and first_opened_at is not null
      and first_opened_at<=v_order.created_at
      and first_opened_at>=v_order.created_at-interval '7 days'
      and customer_id is not distinct from v_order.customer_id
    limit 1;
    if found then v_link:=v_clicked; end if;
  end if;

  -- Caminho normal: reconstrói pelo cliente e pelo último clique rastreado.
  if v_link.id is null and v_order.customer_id is not null then
    select l.* into v_latest
    from public.marketing_tracking_links_v1 l
    where l.customer_id=v_order.customer_id
      and l.first_opened_at is not null
      and l.first_opened_at<=v_order.created_at
      and l.first_opened_at>=v_order.created_at-interval '7 days'
      and l.expires_at>=l.first_opened_at
    order by l.first_opened_at desc,l.created_at desc
    limit 1;
    if found then
      v_link:=v_latest;
      v_hash:=v_latest.token_hash;
    end if;
  end if;

  if v_link.id is null then
    return jsonb_build_object('ok',true,'attributed',false,'reason','no_marketing_touch_in_window');
  end if;

  v_offer_match:=(
    (v_link.commercial_id is not null and v_link.commercial_id=v_order_commercial_id)
    or (v_link.public_lot_id is not null and v_link.public_lot_id=v_order_lot_id)
  );
  v_kind:=case when v_offer_match then 'direct' else 'assisted' end;

  v_event_key:=format('strategy-order:%s:%s',v_link.strategy_id,v_order.id);
  insert into public.marketing_attribution_events_v1(
    strategy_id,campaign_id,customer_id,order_id,commercial_id,public_lot_id,event_type,
    attribution_kind,amount,token_hash,idempotency_key,occurred_at,metadata
  ) values (
    v_link.strategy_id,v_link.campaign_id,v_order.customer_id,v_order.id,
    coalesce(v_order_commercial_id,v_link.commercial_id),coalesce(v_order_lot_id,v_link.public_lot_id),
    'order_attributed',v_kind,greatest(coalesce(v_order.total,0),0),v_hash,v_event_key,
    v_order.confirmed_at,
    jsonb_build_object(
      'dispatch_id',v_link.dispatch_id,'offer_position',v_link.offer_position,
      'clicked_commercial_id',v_link.commercial_id,'clicked_public_lot_id',v_link.public_lot_id,
      'purchased_commercial_id',v_order_commercial_id,'purchased_public_lot_id',v_order_lot_id,
      'direct_offer_match',v_offer_match,'window_days',7
    )
  ) on conflict(idempotency_key) do nothing;

  update public.marketing_tracking_links_v1
  set attributed_order_id=coalesce(attributed_order_id,v_order.id),
      attribution_kind=coalesce(attribution_kind,v_kind),updated_at=now()
  where id=v_link.id;

  return jsonb_build_object(
    'ok',true,'attributed',true,'attribution_kind',v_kind,'strategy_id',v_link.strategy_id,
    'campaign_id',v_link.campaign_id,'order_id',v_order.id,'amount',v_order.total,
    'commercial_id',coalesce(v_order_commercial_id,v_link.commercial_id),
    'public_lot_id',coalesce(v_order_lot_id,v_link.public_lot_id)
  );
end;
$function$
;

-- function: marketing_audience_candidates_v2(p_filters jsonb)
CREATE OR REPLACE FUNCTION public.marketing_audience_candidates_v2(p_filters jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(customer_id uuid, name text, canonical_phone text, masked_phone text, consent_state text, is_active boolean, city text, neighborhood text, order_count integer, lifetime_value numeric, last_purchase_at timestamp with time zone, phone_rank bigint, eligible boolean, exclusion_reason_list text[])
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_filters jsonb := coalesce(p_filters,'{}'::jsonb);
  v_unsupported text;
  v_search text;
  v_city text;
  v_neighborhood text;
  v_brand text;
  v_category text;
  v_purchase_recency text;
  v_last_purchase_before timestamptz;
  v_last_purchase_after timestamptz;
  v_inactive_days integer;
  v_min_order_count integer;
  v_max_order_count integer;
  v_min_lifetime_value numeric;
  v_max_lifetime_value numeric;
begin
  if jsonb_typeof(v_filters) is distinct from 'object' then
    raise exception using errcode='22023', message='invalid_filters';
  end if;

  select k into v_unsupported
  from jsonb_object_keys(v_filters) as k
  where k <> all(array[
    'customer_ids','search','city','neighborhood','label_ids','product_ids','brand','category',
    'last_purchase_before','last_purchase_after','inactive_days','min_order_count','max_order_count',
    'min_lifetime_value','max_lifetime_value','purchase_recency'
  ]::text[])
  limit 1;
  if v_unsupported is not null then
    raise exception using errcode='22023', message='unsupported_filter:'||v_unsupported;
  end if;

  if v_filters ? 'customer_ids' and jsonb_typeof(v_filters->'customer_ids') <> 'array' then
    raise exception using errcode='22023', message='invalid_filter_value:customer_ids';
  end if;
  if v_filters ? 'label_ids' and jsonb_typeof(v_filters->'label_ids') <> 'array' then
    raise exception using errcode='22023', message='invalid_filter_value:label_ids';
  end if;
  if v_filters ? 'product_ids' and jsonb_typeof(v_filters->'product_ids') <> 'array' then
    raise exception using errcode='22023', message='invalid_filter_value:product_ids';
  end if;

  v_search := nullif(btrim(coalesce(v_filters->>'search','')),'');
  v_city := nullif(btrim(coalesce(v_filters->>'city','')),'');
  v_neighborhood := nullif(btrim(coalesce(v_filters->>'neighborhood','')),'');
  v_brand := nullif(btrim(coalesce(v_filters->>'brand','')),'');
  v_category := nullif(btrim(coalesce(v_filters->>'category','')),'');
  if v_filters ? 'purchase_recency' then
    if jsonb_typeof(v_filters->'purchase_recency') is distinct from 'string'
       or v_filters->>'purchase_recency' not in ('all','last_30','days_31_60','over_60') then
      raise exception using errcode='22023', message='invalid_filter_value:purchase_recency';
    end if;
    v_purchase_recency := v_filters->>'purchase_recency';
  end if;

  begin
    if nullif(v_filters->>'last_purchase_before','') is not null then
      v_last_purchase_before := (v_filters->>'last_purchase_before')::timestamptz;
    end if;
    if nullif(v_filters->>'last_purchase_after','') is not null then
      v_last_purchase_after := (v_filters->>'last_purchase_after')::timestamptz;
    end if;
    if nullif(v_filters->>'inactive_days','') is not null then
      v_inactive_days := (v_filters->>'inactive_days')::integer;
    end if;
    if nullif(v_filters->>'min_order_count','') is not null then
      v_min_order_count := (v_filters->>'min_order_count')::integer;
    end if;
    if nullif(v_filters->>'max_order_count','') is not null then
      v_max_order_count := (v_filters->>'max_order_count')::integer;
    end if;
    if nullif(v_filters->>'min_lifetime_value','') is not null then
      v_min_lifetime_value := (v_filters->>'min_lifetime_value')::numeric;
    end if;
    if nullif(v_filters->>'max_lifetime_value','') is not null then
      v_max_lifetime_value := (v_filters->>'max_lifetime_value')::numeric;
    end if;
  exception when others then
    raise exception using errcode='22023', message='invalid_filter_value';
  end;

  if coalesce(v_inactive_days,0) < 0
     or coalesce(v_min_order_count,0) < 0
     or coalesce(v_max_order_count,0) < 0
     or coalesce(v_min_lifetime_value,0) < 0
     or coalesce(v_max_lifetime_value,0) < 0 then
    raise exception using errcode='22023', message='invalid_filter_value';
  end if;

  return query
  with purchase_orders as (
    select o.id,o.customer_id,o.total,o.confirmed_at,o.delivered_at,o.created_at
    from public.orders o
    where o.customer_id is not null
      and o.cancelled_at is null
      and o.returned_at is null
      and (
        o.confirmed_at is not null
        or lower(coalesce(o.status,'')) in ('confirmed','processing','ready','delivered')
      )
  ),
  purchase_stats as (
    select po.customer_id,
           count(*)::integer as order_count,
           coalesce(sum(coalesce(po.total,0)),0)::numeric as lifetime_value,
           max(coalesce(po.delivered_at,po.confirmed_at,po.created_at)) as last_purchase_at
    from purchase_orders po
    group by po.customer_id
  ),
  base as (
    select c.id as customer_id,
           c.name,
           c.is_active,
           c.updated_at,
           c.marketing_consent_updated_at,
           public.canonical_whatsapp_e164_br_v2(c.primary_whatsapp_e164) as canonical_phone,
           coalesce(consent.consent_state,'never_consented') as consent_state,
           public.marketing_has_verified_campaign_consent_v1(c.id) as individual_evidence_verified,
           coalesce(ps.order_count,0) as order_count,
           coalesce(ps.lifetime_value,0)::numeric as lifetime_value,
           ps.last_purchase_at,
           addr.city,
           addr.neighborhood
    from public.customers c
    left join public.marketing_customer_consent_current_v1 consent on consent.customer_id=c.id
    left join purchase_stats ps on ps.customer_id=c.id
    left join lateral (
      select a.city,a.neighborhood
      from public.customer_addresses a
      where a.customer_id=c.id
        and coalesce(a.is_active,true) is true
      order by coalesce(a.is_default,false) desc,
               a.last_confirmed_at desc nulls last,
               a.updated_at desc nulls last,
               a.id
      limit 1
    ) addr on true
    where
      (
        not (v_filters ? 'customer_ids')
        or exists (
          select 1 from jsonb_array_elements_text(v_filters->'customer_ids') x(value)
          where x.value=c.id::text
        )
      )
      and (
        v_search is null
        or c.name ilike '%'||v_search||'%'
        or coalesce(c.primary_whatsapp_e164,'') ilike '%'||v_search||'%'
      )
      and (v_city is null or lower(coalesce(addr.city,''))=lower(v_city))
      and (v_neighborhood is null or lower(coalesce(addr.neighborhood,''))=lower(v_neighborhood))
      and (
        not (v_filters ? 'label_ids')
        or exists (
          select 1
          from public.conversations cv
          join public.attendance_conversation_labels_v1 cl on cl.conversation_id=cv.id
          join public.attendance_labels_v1 l on l.id=cl.label_id and coalesce(l.is_active,true) is true
          where cv.customer_id=c.id
            and exists (
              select 1 from jsonb_array_elements_text(v_filters->'label_ids') lx(value)
              where lx.value=l.id::text
            )
        )
      )
      and (
        not (v_filters ? 'product_ids') and v_brand is null and v_category is null
        or exists (
          select 1
          from purchase_orders po2
          join public.order_items oi on oi.order_id=po2.id
          join public.products p on p.id=oi.product_id
          where po2.customer_id=c.id
            and (
              not (v_filters ? 'product_ids')
              or exists (
                select 1 from jsonb_array_elements_text(v_filters->'product_ids') px(value)
                where px.value=p.id::text
              )
            )
            and (v_brand is null or lower(coalesce(p.brand,''))=lower(v_brand))
            and (
              v_category is null
              or lower(coalesce(nullif(p.customer_category,''),nullif(p.category,''),nullif(p.whatsapp_category,''),''))=lower(v_category)
            )
        )
      )
      and (v_last_purchase_before is null or ps.last_purchase_at < v_last_purchase_before)
      and (v_last_purchase_after is null or ps.last_purchase_at >= v_last_purchase_after)
      and (
        v_purchase_recency is null
        or v_purchase_recency='all'
        or (v_purchase_recency='last_30' and ps.last_purchase_at >= now()-interval '30 days')
        or (v_purchase_recency='days_31_60'
          and ps.last_purchase_at >= now()-interval '60 days'
          and ps.last_purchase_at < now()-interval '30 days')
        or (v_purchase_recency='over_60' and ps.last_purchase_at < now()-interval '60 days')
      )
      and (
        v_inactive_days is null
        or (ps.last_purchase_at is not null and ps.last_purchase_at <= now()-make_interval(days=>v_inactive_days))
      )
      and (v_min_order_count is null or coalesce(ps.order_count,0) >= v_min_order_count)
      and (v_max_order_count is null or coalesce(ps.order_count,0) <= v_max_order_count)
      and (v_min_lifetime_value is null or coalesce(ps.lifetime_value,0) >= v_min_lifetime_value)
      and (v_max_lifetime_value is null or coalesce(ps.lifetime_value,0) <= v_max_lifetime_value)
  ),
  ranked as (
    select b.*,
           row_number() over (
             partition by b.canonical_phone
             order by
               case when b.consent_state='opt_in' then 0 else 1 end,
               case when coalesce(b.is_active,false) then 0 else 1 end,
               b.marketing_consent_updated_at desc nulls last,
               b.updated_at desc nulls last,
               b.customer_id
           ) as phone_rank
    from base b
  ),
  evaluated as (
    select r.*,
           case
             when r.canonical_phone is null then null
             else left(r.canonical_phone,5)||'*****'||right(r.canonical_phone,4)
           end as masked_phone,
           array_remove(array[
             case
               when r.consent_state='opt_out' then 'opted_out'
               when r.consent_state<>'opt_in' then 'no_consent'
               else null
             end,
             case when r.consent_state='opt_in' and r.individual_evidence_verified is not true then 'consent_evidence_unverified' else null end,
             case when coalesce(r.is_active,false) is not true then 'inactive_customer' else null end,
             case when r.canonical_phone is null then 'invalid_phone' else null end,
             case when r.canonical_phone is not null and r.phone_rank>1 then 'duplicate_phone' else null end
           ]::text[],null) as exclusion_reason_list
    from ranked r
  )
  select e.customer_id,
         e.name,
         e.canonical_phone,
         e.masked_phone,
         e.consent_state,
         e.is_active,
         e.city,
         e.neighborhood,
         e.order_count,
         e.lifetime_value,
         e.last_purchase_at,
         e.phone_rank,
         coalesce(cardinality(e.exclusion_reason_list),0)=0 as eligible,
         e.exclusion_reason_list
  from evaluated e;
end;
$function$
;

-- function: marketing_begin_manual_campaign_batch_v1(p_campaign_id uuid, p_expected_revision integer, p_idempotency_key text, p_limit integer)
CREATE OR REPLACE FUNCTION public.marketing_begin_manual_campaign_batch_v1(p_campaign_id uuid, p_expected_revision integer, p_idempotency_key text, p_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_campaign public.marketing_campaigns_v1%rowtype;
  v_snapshot public.marketing_campaign_snapshots_v1%rowtype;
  v_template public.whatsapp_templates_v1%rowtype;
  v_gate jsonb;
  v_batch public.marketing_campaign_manual_batches_v1%rowtype;
  v_limit integer:=least(greatest(coalesce(p_limit,10),1),10);
  v_count integer:=0;
begin
  if nullif(btrim(coalesce(p_idempotency_key,'')),'') is null or length(p_idempotency_key)>180 then
    return jsonb_build_object('ok',false,'error','invalid_idempotency_key');
  end if;
  select * into v_campaign from public.marketing_campaigns_v1 where id=p_campaign_id for update;
  if not found then return jsonb_build_object('ok',false,'error','campaign_not_found'); end if;
  select * into v_batch from public.marketing_campaign_manual_batches_v1
    where campaign_id=v_campaign.id and idempotency_key=p_idempotency_key;
  if found then
    return jsonb_build_object('ok',true,'batch_id',v_batch.id,'campaign_id',v_campaign.id,
      'status',v_batch.status,'claimed_count',v_batch.claimed_count,'worker_started_at',v_batch.worker_started_at,'replayed',true);
  end if;
  if v_campaign.revision<>p_expected_revision then return jsonb_build_object('ok',false,'error','revision_conflict','revision',v_campaign.revision); end if;
  if v_campaign.status not in ('approved','paused') then return jsonb_build_object('ok',false,'error','campaign_invalid_transition','status',v_campaign.status); end if;
  select * into v_snapshot from public.marketing_campaign_snapshots_v1
    where campaign_id=v_campaign.id and campaign_revision=v_campaign.revision
    order by snapshot_version desc limit 1;
  if not found then return jsonb_build_object('ok',false,'error','snapshot_stale'); end if;
  if not exists (
    select 1
    from public.marketing_campaign_snapshot_recipients_v1 r
    where r.snapshot_id=v_snapshot.id
      and r.campaign_id=v_campaign.id
      and r.eligible_at_snapshot is true
      and public.marketing_has_verified_campaign_consent_v1(r.customer_id)
  ) then
    return jsonb_build_object('ok',false,'error','no_eligible_recipients');
  end if;
  select * into v_template from public.whatsapp_templates_v1
    where id=v_campaign.template_id and whatsapp_account_id=v_campaign.whatsapp_account_id
      and upper(category)='MARKETING' and upper(status)='APPROVED';
  if not found then return jsonb_build_object('ok',false,'error','template_not_sendable'); end if;
  v_gate:=public.marketing_campaign_execution_gate_v1(v_campaign.whatsapp_account_id);
  if coalesce((v_gate->>'ok')::boolean,false) is not true then return v_gate; end if;

  update public.marketing_campaigns_v1
    set manual_batch_mode=true,status='scheduled',scheduled_for=now(),updated_at=now()
    where id=v_campaign.id;
  perform public.marketing_materialize_dispatches_v1(v_campaign.id);
  insert into public.marketing_campaign_manual_batches_v1(campaign_id,idempotency_key,requested_limit)
    values(v_campaign.id,p_idempotency_key,v_limit) returning * into v_batch;
  update public.marketing_campaigns_v1
    set manual_batch_mode=true,status='running',started_at=coalesce(started_at,now()),paused_at=null,
        completed_at=null,failed_at=null,execution_last_error=null,updated_at=now()
    where id=v_campaign.id;

  with picked as (
    select d.id
    from public.marketing_campaign_dispatches_v1 d
    where d.campaign_id=v_campaign.id and d.status in ('pending','retry') and d.available_at<=now()
    order by d.available_at,d.created_at,d.id
    for update skip locked
    limit v_limit
  ), claimed as (
    update public.marketing_campaign_dispatches_v1 d
    set status='claimed',claimed_at=now(),last_error=null,manual_batch_id=v_batch.id,updated_at=now()
    from picked p where d.id=p.id returning d.id
  ) select count(*)::integer into v_count from claimed;
  update public.marketing_campaign_manual_batches_v1
    set claimed_count=v_count,status=case when v_count=0 then 'no_work' else 'processing' end,
        completed_at=case when v_count=0 then now() else null end
    where id=v_batch.id returning * into v_batch;
  if v_count=0 then
    if exists(select 1 from public.marketing_campaign_dispatches_v1 d where d.campaign_id=v_campaign.id and d.status in ('pending','retry','claimed')) then
      update public.marketing_campaigns_v1 set status='paused',paused_at=now(),updated_at=now() where id=v_campaign.id;
    else
      update public.marketing_campaigns_v1 set status='completed',completed_at=now(),updated_at=now() where id=v_campaign.id;
    end if;
  end if;
  return jsonb_build_object('ok',true,'batch_id',v_batch.id,'campaign_id',v_campaign.id,
    'status',v_batch.status,'claimed_count',v_count,'worker_started_at',v_batch.worker_started_at,'replayed',false,'mode',v_gate->>'mode');
exception when unique_violation then
  return jsonb_build_object('ok',false,'error','manual_batch_already_active');
end;
$function$
;

-- function: marketing_campaign_append_only_guard_v1()
CREATE OR REPLACE FUNCTION public.marketing_campaign_append_only_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  raise exception using errcode='55000', message='immutable_append_only';
end;
$function$
;

-- function: marketing_campaign_detail_v1(p_campaign_id uuid)
CREATE OR REPLACE FUNCTION public.marketing_campaign_detail_v1(p_campaign_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_campaign public.marketing_campaigns_v1%rowtype;
  v_snapshot jsonb;
begin
  select * into v_campaign from public.marketing_campaigns_v1 c where c.id=p_campaign_id;
  if not found then return jsonb_build_object('ok',false,'error','campaign_not_found'); end if;
  select jsonb_build_object(
    'id',s.id,'campaign_revision',s.campaign_revision,'snapshot_version',s.snapshot_version,
    'found_count',s.found_count,'eligible_count',s.eligible_count,'excluded_count',s.excluded_count,'created_at',s.created_at
  ) into v_snapshot
  from public.marketing_campaign_snapshots_v1 s
  where s.campaign_id=v_campaign.id and s.campaign_revision=v_campaign.revision
  order by s.snapshot_version desc limit 1;

  return jsonb_build_object(
    'ok',true,
    'campaign',jsonb_build_object(
      'id',v_campaign.id,'name',v_campaign.name,'whatsapp_account_id',v_campaign.whatsapp_account_id,
      'template_id',v_campaign.template_id,'status',v_campaign.status,'revision',v_campaign.revision,
      'filters',v_campaign.filters,'variable_values',v_campaign.variable_values,'deep_link',v_campaign.deep_link,
      'notes',v_campaign.notes,'template_name',v_campaign.template_name_snapshot,'template_language',v_campaign.template_language_snapshot,
      'template_category',v_campaign.template_category_snapshot,'template_components',v_campaign.template_components_snapshot,
      'created_at',v_campaign.created_at,'updated_at',v_campaign.updated_at
    ),
    'snapshot',v_snapshot
  );
end;
$function$
;

-- function: marketing_campaign_dispatch_identity_guard_v1()
CREATE OR REPLACE FUNCTION public.marketing_campaign_dispatch_identity_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.snapshot_id is distinct from old.snapshot_id
     or new.campaign_id is distinct from old.campaign_id
     or new.customer_id is distinct from old.customer_id
     or new.whatsapp_account_id is distinct from old.whatsapp_account_id
     or new.phone_e164 is distinct from old.phone_e164 then
    raise exception 'marketing_campaign_dispatch_identity_immutable' using errcode='55000';
  end if;
  new.updated_at:=now();
  return new;
end;
$function$
;

-- function: marketing_campaign_execution_gate_v1(p_whatsapp_account_id uuid)
CREATE OR REPLACE FUNCTION public.marketing_campaign_execution_gate_v1(p_whatsapp_account_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_channel public.whatsapp_channel_runtime_v1%rowtype;
  v_execution public.marketing_campaign_execution_runtime_v1%rowtype;
begin
  select * into v_channel from public.whatsapp_channel_runtime_v1 where whatsapp_account_id=p_whatsapp_account_id;
  select * into v_execution from public.marketing_campaign_execution_runtime_v1 where whatsapp_account_id=p_whatsapp_account_id;
  if not found then
    return jsonb_build_object('ok',false,'error','campaigns_disabled','mode','off');
  end if;
  if v_channel.whatsapp_account_id is null
     or v_channel.campaigns_enabled is not true
     or v_channel.send_enabled is not true
     or v_channel.outbound_provider <> 'meta'
     or v_execution.mode='off' then
    return jsonb_build_object('ok',false,'error','campaigns_disabled','mode',coalesce(v_execution.mode,'off'));
  end if;
  return jsonb_build_object('ok',true,'mode',v_execution.mode);
end;
$function$
;

-- function: marketing_campaign_execution_status_v1(p_campaign_id uuid)
CREATE OR REPLACE FUNCTION public.marketing_campaign_execution_status_v1(p_campaign_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_campaign public.marketing_campaigns_v1%rowtype;
  v_execution public.marketing_campaign_execution_runtime_v1%rowtype;
  v_channel public.whatsapp_channel_runtime_v1%rowtype;
  v_total integer:=0; v_pending integer:=0; v_claimed integer:=0; v_skipped integer:=0;
  v_accepted integer:=0; v_retry integer:=0; v_uncertain integer:=0; v_failed integer:=0;
begin
  select * into v_campaign from public.marketing_campaigns_v1 where id=p_campaign_id;
  if not found then return jsonb_build_object('ok',false,'error','campaign_not_found'); end if;
  select * into v_execution from public.marketing_campaign_execution_runtime_v1 where whatsapp_account_id=v_campaign.whatsapp_account_id;
  select * into v_channel from public.whatsapp_channel_runtime_v1 where whatsapp_account_id=v_campaign.whatsapp_account_id;
  select count(*)::integer,count(*) filter(where status='pending')::integer,count(*) filter(where status='claimed')::integer,
         count(*) filter(where status='skipped')::integer,count(*) filter(where status='accepted')::integer,
         count(*) filter(where status='retry')::integer,count(*) filter(where status='uncertain')::integer,
         count(*) filter(where status='failed')::integer
    into v_total,v_pending,v_claimed,v_skipped,v_accepted,v_retry,v_uncertain,v_failed
    from public.marketing_campaign_dispatches_v1 where campaign_id=v_campaign.id;
  return jsonb_build_object(
    'ok',true,'campaign_id',v_campaign.id,'status',v_campaign.status,'revision',v_campaign.revision,
    'manual_batch_mode',v_campaign.manual_batch_mode,'scheduled_for',v_campaign.scheduled_for,
    'started_at',v_campaign.started_at,'paused_at',v_campaign.paused_at,'completed_at',v_campaign.completed_at,
    'failed_at',v_campaign.failed_at,'cancelled_at',v_campaign.cancelled_at,'execution_last_error',v_campaign.execution_last_error,
    'runtime',jsonb_build_object('mode',coalesce(v_execution.mode,'off'),
      'campaigns_enabled',coalesce(v_channel.campaigns_enabled,false),'send_enabled',coalesce(v_channel.send_enabled,false),
      'outbound_provider',v_channel.outbound_provider),
    'counts',jsonb_build_object('total',v_total,'pending',v_pending,'claimed',v_claimed,'skipped',v_skipped,
      'accepted',v_accepted,'retry',v_retry,'uncertain',v_uncertain,'failed',v_failed));
end;
$function$
;

-- function: marketing_campaign_template_snapshot_v1(p_whatsapp_account_id uuid, p_template_id uuid)
CREATE OR REPLACE FUNCTION public.marketing_campaign_template_snapshot_v1(p_whatsapp_account_id uuid, p_template_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_template jsonb;
begin
  if not exists (
    select 1 from public.whatsapp_accounts a
    where a.id=p_whatsapp_account_id and coalesce(a.is_active,false) is true
  ) or not exists (
    select 1 from public.whatsapp_channel_runtime_v1 r
    where r.whatsapp_account_id=p_whatsapp_account_id
  ) then
    return jsonb_build_object('ok',false,'error','account_not_available');
  end if;

  select jsonb_build_object(
    'ok',true,
    'id',s.id,
    'name',s.name,
    'language',s.language,
    'category',s.category,
    'status',s.status,
    'components',coalesce(s.components,'[]'::jsonb)
  ) into v_template
  from (
    select t.id,t.name,t.language,t.category,t.status,t.components
    from public.whatsapp_templates_v1 t
    where t.id=p_template_id
      and t.whatsapp_account_id=p_whatsapp_account_id
  ) s
  where upper(category)='MARKETING'
    and upper(status)='APPROVED';

  if v_template is null then
    return jsonb_build_object('ok',false,'error','template_not_sendable');
  end if;
  return v_template;
end;
$function$
;

-- function: marketing_campaign_worker_internal_key_v1()
CREATE OR REPLACE FUNCTION public.marketing_campaign_worker_internal_key_v1()
 RETURNS text
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select s.secret from public.marketing_campaign_worker_secret_v1 s where s.singleton=true;
$function$
;

-- function: marketing_cancel_campaign_execution_v1(p_campaign_id uuid, p_reason text)
CREATE OR REPLACE FUNCTION public.marketing_cancel_campaign_execution_v1(p_campaign_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_campaign public.marketing_campaigns_v1%rowtype;
  v_skipped integer:=0;
  v_cancelled_outbox integer:=0;
  v_reason text:=coalesce(nullif(btrim(coalesce(p_reason,'')),''),'campaign_cancelled');
begin
  select * into v_campaign from public.marketing_campaigns_v1 where id=p_campaign_id for update;
  if not found then return jsonb_build_object('ok',false,'error','campaign_not_found'); end if;
  if v_campaign.status='cancelled' then
    return jsonb_build_object('ok',true,'duplicate',true,'campaign_id',v_campaign.id,'status','cancelled');
  end if;
  if v_campaign.status not in ('scheduled','running','paused') then
    return jsonb_build_object('ok',false,'error','campaign_invalid_transition','status',v_campaign.status);
  end if;

  update public.whatsapp_outbox_v1 o
  set status='cancelled',last_error='campaign_cancelled',updated_at=now()
  where o.id in (
    select d.outbox_id from public.marketing_campaign_dispatches_v1 d
    where d.campaign_id=v_campaign.id and d.status in ('pending','claimed','retry') and d.outbox_id is not null
  ) and o.status in ('queued','claimed');
  get diagnostics v_cancelled_outbox=row_count;

  update public.whatsapp_messages_v1 m
  set status_current='cancelled'
  where m.id in (
    select o.message_id from public.whatsapp_outbox_v1 o
    join public.marketing_campaign_dispatches_v1 d on d.outbox_id=o.id
    where d.campaign_id=v_campaign.id and o.status='cancelled' and o.message_id is not null
  ) and m.status_current in ('queued','sending');

  update public.marketing_campaign_dispatches_v1
  set status='skipped',skip_reason='campaign_cancelled',claimed_at=null,last_error=v_reason,updated_at=now()
  where campaign_id=v_campaign.id and status in ('pending','claimed','retry');
  get diagnostics v_skipped=row_count;

  update public.marketing_campaigns_v1
  set status='cancelled',cancelled_at=now(),execution_last_error=v_reason,updated_at=now()
  where id=v_campaign.id;

  return jsonb_build_object('ok',true,'duplicate',false,'campaign_id',v_campaign.id,'status','cancelled',
    'skipped_dispatches',v_skipped,'cancelled_outboxes',v_cancelled_outbox);
end;
$function$
;

-- function: marketing_capture_direct_customer_consent_change_v1()
CREATE OR REPLACE FUNCTION public.marketing_capture_direct_customer_consent_change_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_guard text; begin
  v_guard := current_setting('app.marketing_consent_rpc',true);
  if coalesce(v_guard,'')='1' then return new; end if;
  if old.marketing_opt_in is not distinct from new.marketing_opt_in then return new; end if;
  insert into public.marketing_consent_events_v1(customer_id,phone_e164,decision,source,source_ref,source_event_key,consent_text_version,consent_text_snapshot,occurred_at,recorded_by,metadata)
  values(new.id,public.canonical_whatsapp_e164_br_v2(new.primary_whatsapp_e164),case when coalesce(new.marketing_opt_in,false) then 'opt_in' else 'opt_out' end,'customer_state_change',null,null,null,null,coalesce(new.marketing_consent_updated_at,now()),'legacy_trigger:'||current_user,jsonb_build_object('old_marketing_opt_in',old.marketing_opt_in,'new_marketing_opt_in',new.marketing_opt_in));
  return new;
end; $function$
;

-- function: marketing_capture_optout_v1()
CREATE OR REPLACE FUNCTION public.marketing_capture_optout_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_text text;
  v_norm text;
  v_customer_id uuid;
  v_is_optout boolean := false;
begin
  if new.event_name is distinct from 'message.received' or new.status is distinct from 'normalized' then
    return new;
  end if;

  if exists(select 1 from public.marketing_optout_events_v1 where capture_id=new.id) then
    return new;
  end if;

  v_text := coalesce(new.payload#>>'{data,message,content}',new.payload#>>'{data,message,text}',new.payload#>>'{data,message,body}','');
  v_norm := lower(translate(v_text,'áàâãäéèêëíìîïóòôõöúùûüçñ','aaaaaeeeeiiiiooooouuuucn'));
  v_norm := regexp_replace(v_norm,'[^a-z0-9 ]+',' ','g');
  v_norm := regexp_replace(v_norm,'\s+',' ','g');
  v_norm := btrim(v_norm);

  v_is_optout :=
    v_norm = 'sair'
    or (v_norm ~ '(nao quero|nao me envie|nao envie|nao mandar|pare de|parar|cancelar|remover)' and v_norm ~ '(promoc|oferta|marketing)')
    or v_norm ~ 'nao quero mais mensagens promocionais'
    or v_norm ~ 'pare de mandar ofertas';

  if not v_is_optout then return new; end if;

  select l.customer_id into v_customer_id
  from public.lookup_customer_by_phone(new.phone_candidate) l
  limit 1;

  insert into public.marketing_optout_events_v1(capture_id,customer_id,phone_e164,source,reason_code,occurred_at)
  values(new.id,v_customer_id,new.phone_candidate,'papoai_inbound','customer_optout',coalesce(new.received_at,now()))
  on conflict (capture_id) do nothing;

  if v_customer_id is not null then
    update public.customers
      set marketing_opt_in=false,
          marketing_consent_updated_at=now()
    where id=v_customer_id
      and coalesce(marketing_opt_in,false) is true;

    perform public.marketing_repurchase_recalc_v1(v_customer_id);
  end if;

  return new;
end
$function$
;

-- function: marketing_capture_weekly_consent_message_v1()
CREATE OR REPLACE FUNCTION public.marketing_capture_weekly_consent_message_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_customer_id uuid;
  v_request public.marketing_weekly_consent_requests_v1%rowtype;
  v_text text;
  v_decision text;
  v_record jsonb;
  v_event_id uuid;
begin
  if new.direction<>'inbound' or nullif(btrim(coalesce(new.text_body,'')),'') is null then return new; end if;
  v_text:=regexp_replace(translate(lower(btrim(new.text_body)),'áàãâäéèêëíìîïóòõôöúùûüç','aaaaaeeeeiiiiooooouuuuc'),'\s+',' ','g');
  select c.customer_id into v_customer_id from public.conversations c where c.id=new.conversation_id limit 1;
  if v_customer_id is null then return new; end if;

  if v_text in ('sair','parar','cancelar ofertas','nao enviar ofertas','nao quero ofertas') then
    v_record:=public.marketing_record_consent_v1(v_customer_id,'opt_out','attendance_weekly_offers_optout',new.conversation_id::text,
      'weekly_marketing_optout:'||new.id::text,'weekly_offers_coupons_v1',null,coalesce(new.received_at,new.created_at,now()),'customer_whatsapp',
      jsonb_build_object('scope','weekly_offers_coupons','frequency','max_once_per_week','response_message_id',new.id,'response_text',new.text_body));
    return new;
  end if;

  if v_text='sim, quero receber' then v_text:='sim quero receber'; end if;
  if v_text='agora não' then v_text:='agora nao'; end if;
  if v_text='sim quero receber' then v_decision:='opt_in';
  elsif v_text='agora nao' then v_decision:='opt_out';
  else return new;
  end if;

  select * into v_request from public.marketing_weekly_consent_requests_v1 r
  where r.customer_id=v_customer_id and r.consent_scope='weekly_offers_coupons' and r.status='sent' and r.decision is null
  order by r.asked_at desc nulls last,r.created_at desc limit 1 for update;
  if not found then return new; end if;

  v_record:=public.marketing_record_consent_v1(v_customer_id,v_decision,'attendance_weekly_offers_consent',v_request.id::text,
    'weekly_consent_response:'||new.id::text,v_request.consent_text_version,v_request.consent_text_snapshot,
    coalesce(new.received_at,new.created_at,now()),'customer_whatsapp',
    jsonb_build_object('scope','weekly_offers_coupons','frequency',v_request.frequency_label,'conversation_id',new.conversation_id,
      'request_id',v_request.id,'response_message_id',new.id,'response_text',new.text_body));

  if coalesce((v_record->>'ok')::boolean,false) is true then
    begin v_event_id:=nullif(v_record->>'event_id','')::uuid; exception when others then v_event_id:=null; end;
    update public.marketing_weekly_consent_requests_v1
       set decision=v_decision,responded_at=coalesce(new.received_at,new.created_at,now()),response_message_id=new.id,
           consent_event_id=v_event_id,updated_at=now()
     where id=v_request.id;
  end if;
  return new;
end;
$function$
;

-- function: marketing_claim_dispatch_batch_v1(p_whatsapp_account_id uuid, p_limit integer)
CREATE OR REPLACE FUNCTION public.marketing_claim_dispatch_batch_v1(p_whatsapp_account_id uuid, p_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_gate jsonb;
  v_limit integer:=least(greatest(coalesce(p_limit,10),1),10);
  v_campaign record;
  v_items jsonb:='[]'::jsonb;
begin
  v_gate:=public.marketing_campaign_execution_gate_v1(p_whatsapp_account_id);
  if coalesce((v_gate->>'ok')::boolean,false) is not true then return v_gate||jsonb_build_object('items','[]'::jsonb); end if;

  for v_campaign in
    select c.id
    from public.marketing_campaigns_v1 c
    where c.whatsapp_account_id=p_whatsapp_account_id and c.status='scheduled'
      and coalesce(c.manual_batch_mode,false) is false
      and coalesce(c.scheduled_for,now())<=now()
    order by c.scheduled_for,c.created_at
    for update skip locked
  loop
    perform public.marketing_materialize_dispatches_v1(v_campaign.id);
    update public.marketing_campaigns_v1
      set status='running',started_at=coalesce(started_at,now()),updated_at=now()
      where id=v_campaign.id and status='scheduled' and coalesce(manual_batch_mode,false) is false;
  end loop;

  with picked as (
    select d.id
    from public.marketing_campaign_dispatches_v1 d
    join public.marketing_campaigns_v1 c on c.id=d.campaign_id
    where d.whatsapp_account_id=p_whatsapp_account_id
      and d.status in ('pending','retry')
      and d.available_at<=now()
      and c.status='running'
      and coalesce(c.manual_batch_mode,false) is false
    order by d.available_at,d.created_at,d.id
    for update of d skip locked
    limit v_limit
  ), claimed as (
    update public.marketing_campaign_dispatches_v1 d
      set status='claimed',claimed_at=now(),last_error=null,updated_at=now()
    from picked p
    where d.id=p.id
    returning d.id,d.campaign_id,d.snapshot_id,d.customer_id,d.whatsapp_account_id,d.phone_e164,d.attempt_count,d.outbox_id
  )
  select coalesce(jsonb_agg(to_jsonb(claimed)),'[]'::jsonb) into v_items from claimed;

  return jsonb_build_object('ok',true,'mode',v_gate->>'mode','items',v_items,'count',jsonb_array_length(v_items));
end;
$function$
;

-- function: marketing_consent_events_append_only_guard_v1()
CREATE OR REPLACE FUNCTION public.marketing_consent_events_append_only_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ begin raise exception 'marketing_consent_events_v1_append_only'; end; $function$
;

-- function: marketing_create_campaign_snapshot_v1(p_campaign_id uuid, p_expected_revision integer, p_idempotency_key text)
CREATE OR REPLACE FUNCTION public.marketing_create_campaign_snapshot_v1(p_campaign_id uuid, p_expected_revision integer, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_campaign public.marketing_campaigns_v1%rowtype;
  v_existing public.marketing_campaign_snapshots_v1%rowtype;
  v_snapshot public.marketing_campaign_snapshots_v1%rowtype;
  v_template jsonb;
  v_version integer;
  v_found integer;
  v_eligible integer;
begin
  select * into v_campaign from public.marketing_campaigns_v1 c where c.id=p_campaign_id for update;
  if not found then return jsonb_build_object('ok',false,'error','campaign_not_found'); end if;
  if v_campaign.revision <> p_expected_revision then return jsonb_build_object('ok',false,'error','revision_conflict','revision',v_campaign.revision); end if;
  if v_campaign.status not in ('draft','ready_for_review') then return jsonb_build_object('ok',false,'error','campaign_invalid_transition'); end if;

  select * into v_existing from public.marketing_campaign_snapshots_v1 s
  where s.campaign_id=p_campaign_id and s.campaign_revision=v_campaign.revision limit 1;
  if found then
    return jsonb_build_object('ok',true,'snapshot_id',v_existing.id,'campaign_id',p_campaign_id,'revision',v_existing.campaign_revision,'snapshot_version',v_existing.snapshot_version,'found_count',v_existing.found_count,'eligible_count',v_existing.eligible_count,'excluded_count',v_existing.excluded_count,'idempotent',true);
  end if;

  v_template := public.marketing_campaign_template_snapshot_v1(v_campaign.whatsapp_account_id,v_campaign.template_id);
  if coalesce((v_template->>'ok')::boolean,false) is not true then return v_template; end if;

  select coalesce(max(s.snapshot_version),0)+1 into v_version from public.marketing_campaign_snapshots_v1 s where s.campaign_id=p_campaign_id;
  select count(*)::integer,count(*) filter(where a.eligible)::integer into v_found,v_eligible
  from public.marketing_audience_candidates_v2(v_campaign.filters) a;

  insert into public.marketing_campaign_snapshots_v1(
    campaign_id,campaign_revision,snapshot_version,whatsapp_account_id,template_id,
    template_name,template_language,template_category,template_components,
    filters_snapshot,variable_values_snapshot,deep_link_snapshot,
    found_count,eligible_count,excluded_count,idempotency_key
  ) values (
    v_campaign.id,v_campaign.revision,v_version,v_campaign.whatsapp_account_id,v_campaign.template_id,
    v_template->>'name',v_template->>'language',v_template->>'category',coalesce(v_template->'components','[]'::jsonb),
    v_campaign.filters,v_campaign.variable_values,v_campaign.deep_link,
    coalesce(v_found,0),coalesce(v_eligible,0),coalesce(v_found,0)-coalesce(v_eligible,0),nullif(btrim(coalesce(p_idempotency_key,'')),'')
  ) returning * into v_snapshot;

  insert into public.marketing_campaign_snapshot_recipients_v1(
    snapshot_id,campaign_id,customer_id,phone_e164,whatsapp_account_id,eligible_at_snapshot,
    exclusion_reasons,phone_rank,city,neighborhood,order_count,lifetime_value,last_purchase_at,
    segment_evidence,parameter_source_metadata
  )
  select v_snapshot.id,v_campaign.id,a.customer_id,a.canonical_phone,v_campaign.whatsapp_account_id,a.eligible,
         coalesce(a.exclusion_reason_list,'{}'::text[]),a.phone_rank,a.city,a.neighborhood,a.order_count,a.lifetime_value,a.last_purchase_at,
         jsonb_build_object('city',a.city,'neighborhood',a.neighborhood,'order_count',a.order_count,'lifetime_value',a.lifetime_value,'last_purchase_at',a.last_purchase_at),
         jsonb_build_object('variable_values',v_campaign.variable_values,'deep_link',v_campaign.deep_link)
  from public.marketing_audience_candidates_v2(v_campaign.filters) a;

  insert into public.marketing_campaign_events_v1(campaign_id,event_type,campaign_revision,snapshot_id,from_status,to_status,metadata)
  values(v_campaign.id,'snapshot_created',v_campaign.revision,v_snapshot.id,v_campaign.status,v_campaign.status,jsonb_build_object('snapshot_version',v_snapshot.snapshot_version,'found_count',v_snapshot.found_count,'eligible_count',v_snapshot.eligible_count));

  return jsonb_build_object('ok',true,'snapshot_id',v_snapshot.id,'campaign_id',p_campaign_id,'revision',v_snapshot.campaign_revision,'snapshot_version',v_snapshot.snapshot_version,'found_count',v_snapshot.found_count,'eligible_count',v_snapshot.eligible_count,'excluded_count',v_snapshot.excluded_count,'idempotent',false);
exception when unique_violation then
  select * into v_existing from public.marketing_campaign_snapshots_v1 s where s.campaign_id=p_campaign_id and s.campaign_revision=p_expected_revision limit 1;
  if found then return jsonb_build_object('ok',true,'snapshot_id',v_existing.id,'campaign_id',p_campaign_id,'revision',v_existing.campaign_revision,'snapshot_version',v_existing.snapshot_version,'found_count',v_existing.found_count,'eligible_count',v_existing.eligible_count,'excluded_count',v_existing.excluded_count,'idempotent',true); end if;
  raise;
end;
$function$
;

-- function: marketing_create_campaign_v1(p_name text, p_whatsapp_account_id uuid, p_template_id uuid, p_filters jsonb, p_variable_values jsonb, p_deep_link jsonb, p_idempotency_key text)
CREATE OR REPLACE FUNCTION public.marketing_create_campaign_v1(p_name text, p_whatsapp_account_id uuid, p_template_id uuid, p_filters jsonb, p_variable_values jsonb DEFAULT '{}'::jsonb, p_deep_link jsonb DEFAULT '{}'::jsonb, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_template jsonb;
  v_campaign public.marketing_campaigns_v1%rowtype;
begin
  if nullif(btrim(coalesce(p_name,'')),'') is null then
    return jsonb_build_object('ok',false,'error','invalid_name');
  end if;
  if jsonb_typeof(coalesce(p_filters,'{}'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(p_variable_values,'{}'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(p_deep_link,'{}'::jsonb)) <> 'object' then
    return jsonb_build_object('ok',false,'error','invalid_payload');
  end if;

  if nullif(btrim(coalesce(p_idempotency_key,'')),'') is not null then
    select * into v_campaign from public.marketing_campaigns_v1 c
    where c.idempotency_key=btrim(p_idempotency_key) limit 1;
    if found then
      return jsonb_build_object('ok',true,'campaign_id',v_campaign.id,'revision',v_campaign.revision,'status',v_campaign.status,'idempotent',true);
    end if;
  end if;

  v_template := public.marketing_campaign_template_snapshot_v1(p_whatsapp_account_id,p_template_id);
  if coalesce((v_template->>'ok')::boolean,false) is not true then return v_template; end if;

  begin
    perform * from public.marketing_audience_candidates_v2(coalesce(p_filters,'{}'::jsonb)) limit 1;
  exception when others then
    return jsonb_build_object('ok',false,'error','invalid_filters','detail',sqlerrm);
  end;

  insert into public.marketing_campaigns_v1(
    name,whatsapp_account_id,template_id,filters,variable_values,deep_link,idempotency_key,
    template_name_snapshot,template_language_snapshot,template_category_snapshot,template_components_snapshot
  ) values (
    btrim(p_name),p_whatsapp_account_id,p_template_id,coalesce(p_filters,'{}'::jsonb),
    coalesce(p_variable_values,'{}'::jsonb),coalesce(p_deep_link,'{}'::jsonb),nullif(btrim(coalesce(p_idempotency_key,'')),''),
    v_template->>'name',v_template->>'language',v_template->>'category',coalesce(v_template->'components','[]'::jsonb)
  ) returning * into v_campaign;

  insert into public.marketing_campaign_events_v1(campaign_id,event_type,campaign_revision,to_status,metadata)
  values(v_campaign.id,'created',v_campaign.revision,v_campaign.status,jsonb_build_object('template_id',p_template_id));

  return jsonb_build_object('ok',true,'campaign_id',v_campaign.id,'revision',v_campaign.revision,'status',v_campaign.status,'idempotent',false);
exception when unique_violation then
  if nullif(btrim(coalesce(p_idempotency_key,'')),'') is not null then
    select * into v_campaign from public.marketing_campaigns_v1 c where c.idempotency_key=btrim(p_idempotency_key) limit 1;
    if found then return jsonb_build_object('ok',true,'campaign_id',v_campaign.id,'revision',v_campaign.revision,'status',v_campaign.status,'idempotent',true); end if;
  end if;
  raise;
end;
$function$
;

-- function: marketing_finish_dispatch_v1(p_dispatch_id uuid, p_status text, p_provider_message_id text, p_last_error text, p_retry_after_seconds integer)
CREATE OR REPLACE FUNCTION public.marketing_finish_dispatch_v1(p_dispatch_id uuid, p_status text, p_provider_message_id text DEFAULT NULL::text, p_last_error text DEFAULT NULL::text, p_retry_after_seconds integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_dispatch public.marketing_campaign_dispatches_v1%rowtype;
  v_status text:=lower(btrim(coalesce(p_status,'')));
  v_attempt integer;
  v_retry_seconds integer;
  v_final text;
  v_has_fail boolean;
begin
  select * into v_dispatch from public.marketing_campaign_dispatches_v1 where id=p_dispatch_id for update;
  if not found then return jsonb_build_object('ok',false,'error','dispatch_not_found'); end if;
  if v_dispatch.status='accepted' and v_status='accepted' and v_dispatch.provider_message_id=p_provider_message_id then
    return jsonb_build_object('ok',true,'duplicate',true,'dispatch_id',v_dispatch.id,'status','accepted','provider_message_id',v_dispatch.provider_message_id);
  end if;
  if v_dispatch.status<>'claimed' then return jsonb_build_object('ok',false,'error','dispatch_not_claimed','status',v_dispatch.status); end if;
  if v_status not in ('accepted','retry','uncertain','failed','skipped') then return jsonb_build_object('ok',false,'error','invalid_dispatch_status'); end if;

  if v_status='skipped' then
    update public.marketing_campaign_dispatches_v1
      set status='skipped',skip_reason=coalesce(nullif(btrim(coalesce(p_last_error,'')),''),'worker_skipped'),claimed_at=null,updated_at=now()
      where id=v_dispatch.id returning * into v_dispatch;
  else
    v_attempt:=v_dispatch.attempt_count+1;
    if v_status='accepted' then
      if nullif(btrim(coalesce(p_provider_message_id,'')),'') is null or p_provider_message_id !~ '^wamid\.' then
        return jsonb_build_object('ok',false,'error','provider_message_id_required');
      end if;
      update public.marketing_campaign_dispatches_v1
        set status='accepted',attempt_count=v_attempt,provider_message_id=p_provider_message_id,last_error=null,claimed_at=null,updated_at=now()
        where id=v_dispatch.id returning * into v_dispatch;
      if v_dispatch.outbox_id is not null then
        update public.whatsapp_outbox_v1 set status='sent',attempt_count=v_attempt,provider_message_id=p_provider_message_id,last_error=null,sent_at=now(),updated_at=now()
        where id=v_dispatch.outbox_id;
      end if;
    elsif v_status='retry' and v_attempt<3 then
      v_retry_seconds:=least(greatest(coalesce(p_retry_after_seconds,30),1),3600);
      update public.marketing_campaign_dispatches_v1
        set status='retry',attempt_count=v_attempt,available_at=now()+make_interval(secs=>v_retry_seconds),claimed_at=null,last_error=nullif(btrim(coalesce(p_last_error,'')),''),updated_at=now()
        where id=v_dispatch.id returning * into v_dispatch;
      if v_dispatch.outbox_id is not null then
        update public.whatsapp_outbox_v1 set status='queued',attempt_count=v_attempt,available_at=v_dispatch.available_at,claimed_at=null,last_error=v_dispatch.last_error,updated_at=now()
        where id=v_dispatch.outbox_id;
      end if;
    else
      v_final:=case when v_status='uncertain' then 'uncertain' else 'failed' end;
      update public.marketing_campaign_dispatches_v1
        set status=v_final,attempt_count=v_attempt,claimed_at=null,last_error=nullif(btrim(coalesce(p_last_error,'')),''),updated_at=now()
        where id=v_dispatch.id returning * into v_dispatch;
      if v_dispatch.outbox_id is not null then
        update public.whatsapp_outbox_v1 set status='failed',attempt_count=v_attempt,last_error=coalesce(v_dispatch.last_error,v_final),updated_at=now()
        where id=v_dispatch.outbox_id;
      end if;
    end if;
  end if;

  if v_dispatch.status in ('accepted','skipped','uncertain','failed')
     and not exists(select 1 from public.marketing_campaign_dispatches_v1 d where d.campaign_id=v_dispatch.campaign_id and d.status in ('pending','claimed','retry')) then
    select exists(select 1 from public.marketing_campaign_dispatches_v1 d where d.campaign_id=v_dispatch.campaign_id and d.status in ('uncertain','failed')) into v_has_fail;
    update public.marketing_campaigns_v1
      set status=case when v_has_fail then 'failed' else 'completed' end,
          completed_at=case when v_has_fail then completed_at else now() end,
          failed_at=case when v_has_fail then now() else failed_at end,
          execution_last_error=case when v_has_fail then 'dispatch_failure' else null end,
          updated_at=now()
      where id=v_dispatch.campaign_id and status in ('running','scheduled','paused');
  end if;

  return jsonb_build_object('ok',true,'dispatch_id',v_dispatch.id,'status',v_dispatch.status,'attempt_count',v_dispatch.attempt_count,
    'provider_message_id',v_dispatch.provider_message_id,'available_at',v_dispatch.available_at);
end;
$function$
;

-- function: marketing_finish_manual_campaign_batch_v1(p_batch_id uuid)
CREATE OR REPLACE FUNCTION public.marketing_finish_manual_campaign_batch_v1(p_batch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_batch public.marketing_campaign_manual_batches_v1%rowtype;
  v_claimed integer:=0;
  v_remaining integer:=0;
  v_status text;
begin
  select * into v_batch from public.marketing_campaign_manual_batches_v1 where id=p_batch_id for update;
  if not found then return jsonb_build_object('ok',false,'error','manual_batch_not_found'); end if;
  if v_batch.status='completed' or v_batch.status='no_work' then
    return jsonb_build_object('ok',true,'batch_id',v_batch.id,'status',v_batch.status);
  end if;
  select count(*)::integer into v_claimed from public.marketing_campaign_dispatches_v1
    where manual_batch_id=v_batch.id and status='claimed';
  if v_claimed>0 then return jsonb_build_object('ok',false,'error','manual_batch_has_unfinished_dispatches','claimed_count',v_claimed); end if;
  update public.marketing_campaign_manual_batches_v1 set status='completed',completed_at=now() where id=v_batch.id;
  select count(*)::integer into v_remaining from public.marketing_campaign_dispatches_v1
    where campaign_id=v_batch.campaign_id and status in ('pending','retry','claimed');
  if v_remaining>0 then
    v_status:='paused';
    update public.marketing_campaigns_v1 set status='paused',paused_at=now(),completed_at=null,updated_at=now()
      where id=v_batch.campaign_id and manual_batch_mode is true;
  else
    v_status:='completed';
    update public.marketing_campaigns_v1 set status='completed',completed_at=now(),paused_at=null,updated_at=now()
      where id=v_batch.campaign_id and manual_batch_mode is true;
  end if;
  return jsonb_build_object('ok',true,'batch_id',v_batch.id,'batch_status','completed','campaign_status',v_status,
    'remaining_count',v_remaining);
end;
$function$
;

-- function: marketing_has_verified_campaign_consent_v1(p_customer_id uuid)
CREATE OR REPLACE FUNCTION public.marketing_has_verified_campaign_consent_v1(p_customer_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (
    select 1
    from public.marketing_customer_consent_current_v1 current_consent
    join public.marketing_consent_events_v1 evidence
      on evidence.customer_id=current_consent.customer_id
     and evidence.decision='opt_in'
     and evidence.source='attendance_weekly_offers_consent'
     and evidence.recorded_by='customer_whatsapp'
    join public.marketing_weekly_consent_requests_v1 consent_request
      on consent_request.id::text=evidence.source_ref
     and consent_request.customer_id=current_consent.customer_id
     and consent_request.consent_event_id=evidence.id
     and consent_request.decision='opt_in'
     and consent_request.response_message_id::text=evidence.metadata->>'response_message_id'
     and consent_request.consent_text_version=evidence.consent_text_version
     and consent_request.consent_text_snapshot=evidence.consent_text_snapshot
     and consent_request.asked_at is not null
     and evidence.occurred_at>=consent_request.asked_at
    where current_consent.customer_id=p_customer_id
      and current_consent.consent_state='opt_in'
      and current_consent.marketing_opt_in=true
      and evidence.source_event_key='weekly_consent_response:'||consent_request.response_message_id::text
      and evidence.metadata->>'scope'='weekly_offers_coupons'
      and nullif(btrim(evidence.source_ref),'') is not null
      and nullif(btrim(evidence.consent_text_snapshot),'') is not null
      and public.canonical_whatsapp_e164_br_v2(current_consent.phone_e164)
          = public.canonical_whatsapp_e164_br_v2(evidence.phone_e164)
      and not exists (
        select 1 from public.marketing_consent_events_v1 opted_out
        where opted_out.customer_id=evidence.customer_id
          and opted_out.decision='opt_out'
          and opted_out.occurred_at>=evidence.occurred_at
      )
  ) or exists (
    select 1
    from public.marketing_customer_consent_current_v1 current_consent
    join public.marketing_consent_events_v1 evidence on evidence.customer_id=current_consent.customer_id
      and evidence.decision='opt_in'
      and evidence.source='site_checkout_checkbox'
      and evidence.recorded_by='storefront_site_checkout'
      and evidence.consent_text_version='site_whatsapp_marketing_optin_v1'
      and evidence.source_event_key like 'checkout_optin:%'
      and evidence.metadata->>'channel'='site_checkout'
      and evidence.metadata->>'customer_checked'='true'
    where current_consent.customer_id=p_customer_id
      and current_consent.consent_state='opt_in'
      and current_consent.marketing_opt_in=true
      and nullif(btrim(evidence.consent_text_snapshot),'') is not null
      and public.canonical_whatsapp_e164_br_v2(evidence.phone_e164)
        = public.canonical_whatsapp_e164_br_v2(current_consent.phone_e164)
      and not exists (
        select 1 from public.marketing_consent_events_v1 o
        where o.customer_id=p_customer_id and o.decision='opt_out'
          and o.occurred_at>=evidence.occurred_at
      )
  );
$function$
;

-- function: marketing_issue_tracking_links_v1(p_dispatch_id uuid)
CREATE OR REPLACE FUNCTION public.marketing_issue_tracking_links_v1(p_dispatch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_dispatch public.marketing_campaign_dispatches_v1%rowtype;
  v_campaign public.marketing_campaigns_v1%rowtype;
  v_offer record;
  v_raw text;
  v_hash text;
  v_link public.marketing_tracking_links_v1%rowtype;
  v_links jsonb:='[]'::jsonb;
begin
  select * into v_dispatch
  from public.marketing_campaign_dispatches_v1
  where id=p_dispatch_id;
  if not found then return jsonb_build_object('ok',false,'error','dispatch_not_found'); end if;

  select * into v_campaign
  from public.marketing_campaigns_v1
  where id=v_dispatch.campaign_id;
  if not found then return jsonb_build_object('ok',false,'error','campaign_not_found'); end if;

  if v_campaign.strategy_id is null then
    return jsonb_build_object('ok',true,'strategy_tracked',false,'tracking_links','[]'::jsonb);
  end if;

  for v_offer in
    select o.position,o.commercial_id,o.public_lot_id,o.public_name,o.image_url
    from public.marketing_strategy_offers_v1 o
    where o.strategy_id=v_campaign.strategy_id
    order by o.position
  loop
    v_raw:=encode(extensions.gen_random_bytes(18),'hex');
    v_hash:=encode(extensions.digest(convert_to(v_raw,'UTF8'),'sha256'),'hex');

    insert into public.marketing_tracking_links_v1(
      token_hash,dispatch_id,strategy_id,campaign_id,customer_id,offer_position,
      commercial_id,public_lot_id,expires_at,metadata,updated_at
    ) values (
      v_hash,v_dispatch.id,v_campaign.strategy_id,v_campaign.id,v_dispatch.customer_id,v_offer.position,
      v_offer.commercial_id,v_offer.public_lot_id,now()+interval '7 days',
      jsonb_build_object('source','marketing_strategy_v1','public_name',v_offer.public_name,'image_url',v_offer.image_url),now()
    )
    on conflict (dispatch_id,offer_position) do update
      set token_hash=excluded.token_hash,
          commercial_id=excluded.commercial_id,
          public_lot_id=excluded.public_lot_id,
          expires_at=excluded.expires_at,
          first_opened_at=null,
          last_opened_at=null,
          open_count=0,
          checkout_started_at=null,
          attributed_order_id=null,
          attribution_kind=null,
          metadata=excluded.metadata,
          updated_at=now()
    returning * into v_link;

    v_links:=v_links||jsonb_build_array(jsonb_build_object(
      'card_index',v_offer.position-1,
      'offer_position',v_offer.position,
      'commercial_id',v_offer.commercial_id,
      'public_lot_id',v_offer.public_lot_id,
      'image_url',v_offer.image_url,
      'tracking_token',v_raw,
      'url','https://www.donaantonia.com.br/?mt='||v_raw
    ));
  end loop;

  if jsonb_array_length(v_links)=0 then
    return jsonb_build_object('ok',false,'error','strategy_offers_missing');
  end if;

  return jsonb_build_object(
    'ok',true,'strategy_tracked',true,'strategy_id',v_campaign.strategy_id,
    'campaign_id',v_campaign.id,'dispatch_id',v_dispatch.id,'tracking_links',v_links
  );
end;
$function$
;

-- function: marketing_materialize_dispatches_v1(p_campaign_id uuid)
CREATE OR REPLACE FUNCTION public.marketing_materialize_dispatches_v1(p_campaign_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_campaign public.marketing_campaigns_v1%rowtype;
  v_snapshot public.marketing_campaign_snapshots_v1%rowtype;
  v_inserted integer:=0;
  v_total integer:=0;
begin
  select * into v_campaign from public.marketing_campaigns_v1 where id=p_campaign_id for update;
  if not found then return jsonb_build_object('ok',false,'error','campaign_not_found'); end if;
  if v_campaign.status not in ('scheduled','running','paused') then return jsonb_build_object('ok',false,'error','campaign_invalid_transition','status',v_campaign.status); end if;
  select * into v_snapshot from public.marketing_campaign_snapshots_v1
  where campaign_id=v_campaign.id and campaign_revision=v_campaign.revision
  order by snapshot_version desc limit 1;
  if not found then return jsonb_build_object('ok',false,'error','snapshot_stale'); end if;

  insert into public.marketing_campaign_dispatches_v1(
    snapshot_id,campaign_id,customer_id,whatsapp_account_id,phone_e164,status,available_at,metadata
  )
  select r.snapshot_id,r.campaign_id,r.customer_id,r.whatsapp_account_id,r.phone_e164,'pending',
         greatest(coalesce(v_campaign.scheduled_for,now()),now()),
         jsonb_build_object('eligible_at_snapshot',r.eligible_at_snapshot,'exclusion_reasons',r.exclusion_reasons,'snapshot_recipient_id',r.id)
  from public.marketing_campaign_snapshot_recipients_v1 r
  where r.snapshot_id=v_snapshot.id
  on conflict(snapshot_id,customer_id) do nothing;
  get diagnostics v_inserted=row_count;
  select count(*)::integer into v_total from public.marketing_campaign_dispatches_v1 where snapshot_id=v_snapshot.id;
  return jsonb_build_object('ok',true,'campaign_id',v_campaign.id,'snapshot_id',v_snapshot.id,'inserted',v_inserted,'total',v_total);
end;
$function$
;

-- function: marketing_pause_campaign_v1(p_campaign_id uuid, p_reason text)
CREATE OR REPLACE FUNCTION public.marketing_pause_campaign_v1(p_campaign_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_campaign public.marketing_campaigns_v1%rowtype;
begin
  select * into v_campaign from public.marketing_campaigns_v1 where id=p_campaign_id for update;
  if not found then return jsonb_build_object('ok',false,'error','campaign_not_found'); end if;
  if v_campaign.status not in ('scheduled','running') then return jsonb_build_object('ok',false,'error','campaign_invalid_transition','status',v_campaign.status); end if;
  update public.marketing_campaigns_v1
  set status='paused',paused_at=now(),execution_last_error=nullif(btrim(coalesce(p_reason,'')),''),updated_at=now()
  where id=v_campaign.id;
  return jsonb_build_object('ok',true,'campaign_id',v_campaign.id,'status','paused');
end;
$function$
;

-- function: marketing_preview_audience_v1(p_filters jsonb, p_limit integer, p_offset integer)
CREATE OR REPLACE FUNCTION public.marketing_preview_audience_v1(p_filters jsonb DEFAULT '{}'::jsonb, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_filters jsonb := coalesce(p_filters,'{}'::jsonb);
  v_unsupported text;
  v_limit integer := coalesce(p_limit,50);
  v_offset integer := coalesce(p_offset,0);
  v_result jsonb;
  v_dummy timestamptz;
  v_dummy_int integer;
  v_dummy_num numeric;
begin
  if jsonb_typeof(v_filters) is distinct from 'object' then
    return jsonb_build_object('ok',false,'error','invalid_filters');
  end if;

  select k into v_unsupported
  from jsonb_object_keys(v_filters) as k
  where k <> all(array[
    'customer_ids','search','city','neighborhood','label_ids','product_ids','brand','category',
    'last_purchase_before','last_purchase_after','inactive_days','min_order_count','max_order_count',
    'min_lifetime_value','max_lifetime_value','purchase_recency'
  ]::text[])
  limit 1;
  if v_unsupported is not null then
    return jsonb_build_object('ok',false,'error','unsupported_filter','filter',v_unsupported);
  end if;

  if v_limit < 1 or v_limit > 100 or v_offset < 0 then
    return jsonb_build_object('ok',false,'error','invalid_pagination');
  end if;

  if v_filters ? 'customer_ids' and jsonb_typeof(v_filters->'customer_ids') <> 'array' then
    return jsonb_build_object('ok',false,'error','invalid_filter_value','filter','customer_ids');
  end if;
  if v_filters ? 'label_ids' and jsonb_typeof(v_filters->'label_ids') <> 'array' then
    return jsonb_build_object('ok',false,'error','invalid_filter_value','filter','label_ids');
  end if;
  if v_filters ? 'product_ids' and jsonb_typeof(v_filters->'product_ids') <> 'array' then
    return jsonb_build_object('ok',false,'error','invalid_filter_value','filter','product_ids');
  end if;
  if v_filters ? 'purchase_recency'
     and (
       jsonb_typeof(v_filters->'purchase_recency') is distinct from 'string'
       or v_filters->>'purchase_recency' not in ('all','last_30','days_31_60','over_60')
     ) then
    return jsonb_build_object('ok',false,'error','invalid_filter_value','filter','purchase_recency');
  end if;

  begin
    if nullif(v_filters->>'last_purchase_before','') is not null then v_dummy := (v_filters->>'last_purchase_before')::timestamptz; end if;
    if nullif(v_filters->>'last_purchase_after','') is not null then v_dummy := (v_filters->>'last_purchase_after')::timestamptz; end if;
    if nullif(v_filters->>'inactive_days','') is not null then v_dummy_int := (v_filters->>'inactive_days')::integer; if v_dummy_int < 0 then raise exception 'invalid'; end if; end if;
    if nullif(v_filters->>'min_order_count','') is not null then v_dummy_int := (v_filters->>'min_order_count')::integer; if v_dummy_int < 0 then raise exception 'invalid'; end if; end if;
    if nullif(v_filters->>'max_order_count','') is not null then v_dummy_int := (v_filters->>'max_order_count')::integer; if v_dummy_int < 0 then raise exception 'invalid'; end if; end if;
    if nullif(v_filters->>'min_lifetime_value','') is not null then v_dummy_num := (v_filters->>'min_lifetime_value')::numeric; if v_dummy_num < 0 then raise exception 'invalid'; end if; end if;
    if nullif(v_filters->>'max_lifetime_value','') is not null then v_dummy_num := (v_filters->>'max_lifetime_value')::numeric; if v_dummy_num < 0 then raise exception 'invalid'; end if; end if;
  exception when others then
    return jsonb_build_object('ok',false,'error','invalid_filter_value');
  end;

  with candidates as (
    select * from public.marketing_audience_candidates_v2(v_filters)
  ),
  counts as (
    select count(*)::integer as found_count,
           count(*) filter (where c.eligible)::integer as eligible_count,
           count(*) filter (where not c.eligible)::integer as excluded_count
    from candidates c
  ),
  reason_counts as (
    select coalesce(jsonb_object_agg(reason,cnt),'{}'::jsonb) as exclusion_reasons
    from (
      select reason,count(*)::integer as cnt
      from candidates c
      cross join lateral unnest(c.exclusion_reason_list) reason
      group by reason
      order by reason
    ) x
  ),
  paged as (
    select c.*
    from candidates c
    order by c.eligible desc,lower(coalesce(c.name,'')),c.customer_id
    limit v_limit offset v_offset
  ),
  items_json as (
    select coalesce(jsonb_agg(jsonb_build_object(
      'customer_id',p.customer_id,
      'name',p.name,
      'masked_phone',p.masked_phone,
      'consent_state',p.consent_state,
      'eligible',p.eligible,
      'exclusion_reasons',to_jsonb(p.exclusion_reason_list),
      'city',p.city,
      'neighborhood',p.neighborhood,
      'last_purchase_at',p.last_purchase_at,
      'order_count',p.order_count,
      'lifetime_value',p.lifetime_value
    ) order by p.eligible desc,lower(coalesce(p.name,'')),p.customer_id),'[]'::jsonb) as items
    from paged p
  )
  select jsonb_build_object(
    'ok',true,
    'found_count',c.found_count,
    'eligible_count',c.eligible_count,
    'excluded_count',c.excluded_count,
    'exclusion_reasons',r.exclusion_reasons,
    'limit',v_limit,
    'offset',v_offset,
    'items',i.items
  ) into v_result
  from counts c cross join reason_counts r cross join items_json i;

  return coalesce(v_result,jsonb_build_object(
    'ok',true,'found_count',0,'eligible_count',0,'excluded_count',0,
    'exclusion_reasons','{}'::jsonb,'limit',v_limit,'offset',v_offset,'items','[]'::jsonb
  ));
end;
$function$
;

-- function: marketing_record_consent_v1(p_customer_id uuid, p_decision text, p_source text, p_source_ref text, p_source_event_key text, p_consent_text_version text, p_consent_text_snapshot text, p_occurred_at timestamp with time zone, p_recorded_by text, p_metadata jsonb)
CREATE OR REPLACE FUNCTION public.marketing_record_consent_v1(p_customer_id uuid, p_decision text, p_source text, p_source_ref text DEFAULT NULL::text, p_source_event_key text DEFAULT NULL::text, p_consent_text_version text DEFAULT NULL::text, p_consent_text_snapshot text DEFAULT NULL::text, p_occurred_at timestamp with time zone DEFAULT now(), p_recorded_by text DEFAULT 'system'::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_customer public.customers%rowtype;
  v_existing public.marketing_consent_events_v1%rowtype;
  v_event_id uuid;
  v_decision text := lower(btrim(coalesce(p_decision,'')));
  v_source text := btrim(coalesce(p_source,''));
  v_phone text;
  v_target boolean;
  v_changed boolean;
  v_occurred_at timestamptz := coalesce(p_occurred_at,now());
  v_previous_guard text;
begin
  if p_customer_id is null then return jsonb_build_object('ok',false,'error','invalid_customer'); end if;
  if v_decision not in ('opt_in','opt_out') then return jsonb_build_object('ok',false,'error','invalid_decision'); end if;
  if v_source = '' then return jsonb_build_object('ok',false,'error','invalid_source'); end if;
  select * into v_customer from public.customers where id=p_customer_id for update;
  if not found then return jsonb_build_object('ok',false,'error','customer_not_found'); end if;
  v_phone := public.canonical_whatsapp_e164_br_v2(v_customer.primary_whatsapp_e164);
  v_target := (v_decision='opt_in');
  v_changed := coalesce(v_customer.marketing_opt_in,false) is distinct from v_target;
  if nullif(btrim(coalesce(p_source_event_key,'')),'') is not null then
    select * into v_existing from public.marketing_consent_events_v1 where source_event_key=btrim(p_source_event_key) limit 1;
    if found then
      if v_existing.customer_id is distinct from p_customer_id or v_existing.decision is distinct from v_decision then return jsonb_build_object('ok',false,'error','source_event_key_conflict'); end if;
      return jsonb_build_object('ok',true,'idempotent',true,'event_id',v_existing.id,'customer_id',p_customer_id,'decision',v_existing.decision,'marketing_opt_in',coalesce(v_customer.marketing_opt_in,false),'changed',false);
    end if;
  end if;
  insert into public.marketing_consent_events_v1(customer_id,phone_e164,decision,source,source_ref,source_event_key,consent_text_version,consent_text_snapshot,occurred_at,recorded_by,metadata)
  values (p_customer_id,v_phone,v_decision,v_source,nullif(btrim(coalesce(p_source_ref,'')),''),nullif(btrim(coalesce(p_source_event_key,'')),''),nullif(btrim(coalesce(p_consent_text_version,'')),''),nullif(p_consent_text_snapshot,''),v_occurred_at,coalesce(nullif(btrim(coalesce(p_recorded_by,'')),''),'system'),coalesce(p_metadata,'{}'::jsonb))
  on conflict (source_event_key) do nothing returning id into v_event_id;
  if v_event_id is null then
    select * into v_existing from public.marketing_consent_events_v1 where source_event_key=btrim(p_source_event_key) limit 1;
    if not found then return jsonb_build_object('ok',false,'error','consent_event_insert_failed'); end if;
    if v_existing.customer_id is distinct from p_customer_id or v_existing.decision is distinct from v_decision then return jsonb_build_object('ok',false,'error','source_event_key_conflict'); end if;
    return jsonb_build_object('ok',true,'idempotent',true,'event_id',v_existing.id,'customer_id',p_customer_id,'decision',v_existing.decision,'marketing_opt_in',coalesce(v_customer.marketing_opt_in,false),'changed',false);
  end if;
  v_previous_guard := current_setting('app.marketing_consent_rpc',true);
  perform set_config('app.marketing_consent_rpc','1',true);
  update public.customers set marketing_opt_in=v_target,marketing_consent_updated_at=v_occurred_at,updated_at=now() where id=p_customer_id;
  perform set_config('app.marketing_consent_rpc',coalesce(v_previous_guard,''),true);
  return jsonb_build_object('ok',true,'idempotent',false,'event_id',v_event_id,'customer_id',p_customer_id,'decision',v_decision,'marketing_opt_in',v_target,'changed',v_changed);
end; $function$
;

-- function: marketing_repurchase_customer_trigger_v1()
CREATE OR REPLACE FUNCTION public.marketing_repurchase_customer_trigger_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if old.marketing_opt_in is distinct from new.marketing_opt_in
     or old.primary_whatsapp_e164 is distinct from new.primary_whatsapp_e164 then
    perform public.marketing_repurchase_recalc_v1(new.id);
  end if;
  return new;
end
$function$
;

-- function: marketing_repurchase_mark_sent_v1(p_customer_id uuid, p_order_id uuid, p_sent_at timestamp with time zone)
CREATE OR REPLACE FUNCTION public.marketing_repurchase_mark_sent_v1(p_customer_id uuid, p_order_id uuid, p_sent_at timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_state public.marketing_repurchase_state_v1%rowtype;
begin
  select * into v_state from public.marketing_repurchase_state_v1 where customer_id=p_customer_id for update;
  if not found then return jsonb_build_object('ok',false,'error','state_not_found'); end if;
  if v_state.last_purchase_order_id is distinct from p_order_id then return jsonb_build_object('ok',false,'error','stale_order'); end if;
  if v_state.marketing_opt_in is not true then return jsonb_build_object('ok',false,'error','opted_out'); end if;
  update public.marketing_repurchase_state_v1
    set status='sent',last_sent_at=coalesce(p_sent_at,now()),last_sent_order_id=p_order_id,blocked_reason=null,updated_at=now()
  where customer_id=p_customer_id;
  return jsonb_build_object('ok',true,'customer_id',p_customer_id,'order_id',p_order_id,'sent_at',coalesce(p_sent_at,now()));
end
$function$
;

-- function: marketing_repurchase_order_trigger_v1()
CREATE OR REPLACE FUNCTION public.marketing_repurchase_order_trigger_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'INSERT' then
    if new.customer_id is not null and new.confirmed_at is not null then
      perform public.marketing_repurchase_recalc_v1(new.customer_id);
    end if;
    return new;
  end if;

  if old.customer_id is distinct from new.customer_id then
    if old.customer_id is not null then perform public.marketing_repurchase_recalc_v1(old.customer_id); end if;
    if new.customer_id is not null then perform public.marketing_repurchase_recalc_v1(new.customer_id); end if;
  elsif new.customer_id is not null and (
    old.confirmed_at is distinct from new.confirmed_at or
    old.cancelled_at is distinct from new.cancelled_at or
    old.status is distinct from new.status
  ) then
    perform public.marketing_repurchase_recalc_v1(new.customer_id);
  end if;
  return new;
end
$function$
;

-- function: marketing_repurchase_recalc_v1(p_customer_id uuid)
CREATE OR REPLACE FUNCTION public.marketing_repurchase_recalc_v1(p_customer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_customer record;
  v_order record;
  v_existing public.marketing_repurchase_state_v1%rowtype;
  v_due timestamptz;
  v_status text;
  v_reason text;
begin
  if p_customer_id is null then
    return jsonb_build_object('ok',false,'error','customer_required');
  end if;

  select id, primary_whatsapp_e164, coalesce(marketing_opt_in,false) as marketing_opt_in
    into v_customer
  from public.customers
  where id = p_customer_id;

  if not found then
    return jsonb_build_object('ok',false,'error','customer_not_found');
  end if;

  select * into v_existing
  from public.marketing_repurchase_state_v1
  where customer_id = p_customer_id;

  select o.id,o.order_number,o.confirmed_at
    into v_order
  from public.orders o
  where o.customer_id = p_customer_id
    and o.confirmed_at is not null
    and coalesce(o.status,'') <> 'cancelled'
    and o.cancelled_at is null
  order by o.confirmed_at desc, o.updated_at desc, o.id desc
  limit 1;

  if not found then
    v_status := 'no_purchase';
    v_reason := 'no_confirmed_purchase';
    v_due := null;
  elsif coalesce(v_customer.marketing_opt_in,false) is not true then
    v_status := 'blocked_opt_out';
    v_reason := 'marketing_opt_out';
    v_due := v_order.confirmed_at + interval '10 days';
  elsif nullif(btrim(coalesce(v_customer.primary_whatsapp_e164,'')),'') is null then
    v_status := 'not_eligible';
    v_reason := 'phone_missing';
    v_due := v_order.confirmed_at + interval '10 days';
  elsif v_existing.last_sent_order_id is not null and v_existing.last_sent_order_id = v_order.id then
    v_status := 'sent';
    v_reason := null;
    v_due := v_order.confirmed_at + interval '10 days';
  else
    v_due := v_order.confirmed_at + interval '10 days';
    v_status := case when v_due <= now() then 'ready' else 'scheduled' end;
    v_reason := null;
  end if;

  insert into public.marketing_repurchase_state_v1(
    customer_id,last_purchase_order_id,last_purchase_order_number,last_purchase_at,due_at,status,
    marketing_opt_in,phone_e164,send_channel_e164,template_name,last_sent_at,last_sent_order_id,
    blocked_reason,metadata,updated_at
  ) values (
    p_customer_id,
    case when v_order.id is null then null else v_order.id end,
    case when v_order.order_number is null then null else v_order.order_number end,
    case when v_order.confirmed_at is null then null else v_order.confirmed_at end,
    v_due,v_status,coalesce(v_customer.marketing_opt_in,false),v_customer.primary_whatsapp_e164,
    '+5565998150975','recompradonaantonia10dias',v_existing.last_sent_at,v_existing.last_sent_order_id,
    v_reason,
    jsonb_build_object('purchase_source','canonical_orders','purchase_channels',jsonb_build_array('0975','1018'),'delay_days',10),
    now()
  )
  on conflict (customer_id) do update set
    last_purchase_order_id=excluded.last_purchase_order_id,
    last_purchase_order_number=excluded.last_purchase_order_number,
    last_purchase_at=excluded.last_purchase_at,
    due_at=excluded.due_at,
    status=excluded.status,
    marketing_opt_in=excluded.marketing_opt_in,
    phone_e164=excluded.phone_e164,
    send_channel_e164=excluded.send_channel_e164,
    template_name=excluded.template_name,
    blocked_reason=excluded.blocked_reason,
    metadata=excluded.metadata,
    updated_at=now();

  return jsonb_build_object(
    'ok',true,
    'customer_id',p_customer_id,
    'status',v_status,
    'last_purchase_order_id',case when v_order.id is null then null else v_order.id end,
    'last_purchase_at',case when v_order.confirmed_at is null then null else v_order.confirmed_at end,
    'due_at',v_due,
    'send_channel_e164','+5565998150975',
    'template_name','recompradonaantonia10dias'
  );
end
$function$
;

-- function: marketing_resolve_tracking_token_v1(p_token text)
CREATE OR REPLACE FUNCTION public.marketing_resolve_tracking_token_v1(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_token text:=lower(btrim(coalesce(p_token,'')));
  v_hash text;
  v_link public.marketing_tracking_links_v1%rowtype;
  v_open integer;
begin
  if v_token !~ '^[0-9a-f]{36}$' then return jsonb_build_object('ok',false,'error','tracking_token_invalid'); end if;
  v_hash:=encode(extensions.digest(convert_to(v_token,'UTF8'),'sha256'),'hex');

  update public.marketing_tracking_links_v1
  set first_opened_at=coalesce(first_opened_at,now()),
      last_opened_at=now(),
      open_count=open_count+1,
      updated_at=now()
  where token_hash=v_hash and expires_at>=now()
  returning * into v_link;

  if not found then return jsonb_build_object('ok',false,'error','tracking_token_not_found'); end if;
  v_open:=v_link.open_count;

  insert into public.marketing_attribution_events_v1(
    strategy_id,campaign_id,customer_id,commercial_id,public_lot_id,event_type,
    token_hash,idempotency_key,occurred_at,metadata
  ) values (
    v_link.strategy_id,v_link.campaign_id,v_link.customer_id,v_link.commercial_id,v_link.public_lot_id,'click',
    v_hash,format('tracking-open:%s:%s',v_link.id,v_open),now(),
    jsonb_build_object('dispatch_id',v_link.dispatch_id,'offer_position',v_link.offer_position,'open_count',v_open)
  ) on conflict(idempotency_key) do nothing;

  -- Resposta pública deliberadamente sem customer_id/telefone/token_hash.
  return jsonb_build_object(
    'ok',true,'strategy_id',v_link.strategy_id,'campaign_id',v_link.campaign_id,
    'commercial_id',v_link.commercial_id,'public_lot_id',v_link.public_lot_id,
    'offer_position',v_link.offer_position,'expires_at',v_link.expires_at
  );
end;
$function$
;

-- function: marketing_resume_campaign_v1(p_campaign_id uuid, p_scheduled_for timestamp with time zone)
CREATE OR REPLACE FUNCTION public.marketing_resume_campaign_v1(p_campaign_id uuid, p_scheduled_for timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_campaign public.marketing_campaigns_v1%rowtype;
  v_template public.whatsapp_templates_v1%rowtype;
  v_snapshot public.marketing_campaign_snapshots_v1%rowtype;
  v_gate jsonb;
  v_when timestamptz:=coalesce(p_scheduled_for,now());
begin
  select * into v_campaign from public.marketing_campaigns_v1 where id=p_campaign_id for update;
  if not found then return jsonb_build_object('ok',false,'error','campaign_not_found'); end if;
  if v_campaign.status<>'paused' then return jsonb_build_object('ok',false,'error','campaign_invalid_transition','status',v_campaign.status); end if;
  if v_campaign.manual_batch_mode is true then return jsonb_build_object('ok',false,'error','manual_campaign_requires_explicit_batch'); end if;
  select * into v_snapshot from public.marketing_campaign_snapshots_v1
    where campaign_id=v_campaign.id and campaign_revision=v_campaign.revision order by snapshot_version desc limit 1;
  if not found then return jsonb_build_object('ok',false,'error','snapshot_stale'); end if;
  select * into v_template from public.whatsapp_templates_v1
    where id=v_campaign.template_id and whatsapp_account_id=v_campaign.whatsapp_account_id
      and upper(category)='MARKETING' and upper(status)='APPROVED';
  if not found then return jsonb_build_object('ok',false,'error','template_not_sendable'); end if;
  v_gate:=public.marketing_campaign_execution_gate_v1(v_campaign.whatsapp_account_id);
  if coalesce((v_gate->>'ok')::boolean,false) is not true then return v_gate; end if;
  update public.marketing_campaigns_v1 set status='scheduled',scheduled_for=v_when,paused_at=null,
    execution_last_error=null,updated_at=now() where id=v_campaign.id;
  return jsonb_build_object('ok',true,'campaign_id',v_campaign.id,'status','scheduled','scheduled_for',v_when,'mode',v_gate->>'mode');
end;
$function$
;

-- function: marketing_revalidate_dispatch_v1(p_dispatch_id uuid)
CREATE OR REPLACE FUNCTION public.marketing_revalidate_dispatch_v1(p_dispatch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_dispatch public.marketing_campaign_dispatches_v1%rowtype;
  v_campaign public.marketing_campaigns_v1%rowtype;
  v_snapshot public.marketing_campaign_snapshots_v1%rowtype;
  v_customer public.customers%rowtype;
  v_template public.whatsapp_templates_v1%rowtype;
  v_consent record;
  v_gate jsonb;
  v_phone text;
  v_conversation jsonb;
  v_enqueue jsonb;
  v_key text;
  v_reason text;
begin
  select * into v_dispatch from public.marketing_campaign_dispatches_v1 where id=p_dispatch_id for update;
  if not found then return jsonb_build_object('ok',false,'error','dispatch_not_found'); end if;
  if v_dispatch.status<>'claimed' then return jsonb_build_object('ok',false,'error','dispatch_not_claimed','status',v_dispatch.status); end if;

  select * into v_campaign from public.marketing_campaigns_v1 where id=v_dispatch.campaign_id;
  if not found then v_reason:='campaign_not_found';
  elsif v_campaign.status='paused' then
    update public.marketing_campaign_dispatches_v1 set status='pending',claimed_at=null,available_at=now()+interval '1 minute',last_error='campaign_paused' where id=v_dispatch.id;
    return jsonb_build_object('ok',false,'error','campaign_paused','dispatch_id',v_dispatch.id);
  elsif v_campaign.status='cancelled' then v_reason:='campaign_cancelled';
  elsif v_campaign.status<>'running' then v_reason:='campaign_not_runnable';
  end if;

  if v_reason is null then
    v_gate:=public.marketing_campaign_execution_gate_v1(v_dispatch.whatsapp_account_id);
    if coalesce((v_gate->>'ok')::boolean,false) is not true then
      update public.marketing_campaign_dispatches_v1 set status='pending',claimed_at=null,available_at=now()+interval '1 minute',last_error='campaigns_disabled' where id=v_dispatch.id;
      return v_gate||jsonb_build_object('dispatch_id',v_dispatch.id);
    end if;
  end if;

  if v_reason is null then
    select * into v_snapshot from public.marketing_campaign_snapshots_v1 where id=v_dispatch.snapshot_id;
    if not found or v_snapshot.campaign_id<>v_campaign.id or v_snapshot.campaign_revision<>v_campaign.revision then v_reason:='snapshot_stale'; end if;
  end if;

  if v_reason is null then
    select * into v_template from public.whatsapp_templates_v1
    where id=v_campaign.template_id and whatsapp_account_id=v_dispatch.whatsapp_account_id
      and upper(category)='MARKETING' and upper(status)='APPROVED';
    if not found then v_reason:='template_not_sendable'; end if;
  end if;

  if v_reason is null then
    select * into v_customer from public.customers where id=v_dispatch.customer_id;
    if not found or v_customer.is_active is not true then v_reason:='inactive_customer'; end if;
  end if;

  if v_reason is null then
    select * into v_consent from public.marketing_customer_consent_current_v1 where customer_id=v_dispatch.customer_id;
    if not found or coalesce(v_consent.consent_state,'never_consented')<>'opt_in' then
      v_reason:=case when coalesce(v_consent.consent_state,'never_consented')='opt_out' then 'opted_out' else 'no_consent' end;
    elsif public.marketing_has_verified_campaign_consent_v1(v_dispatch.customer_id) is not true then
      v_reason:='consent_evidence_unverified';
    end if;
  end if;

  if v_reason is null then
    v_phone:=public.canonical_whatsapp_e164_br_v2(v_customer.primary_whatsapp_e164);
    if v_phone is null then v_reason:='invalid_phone';
    elsif v_dispatch.phone_e164 is null or v_phone<>v_dispatch.phone_e164 then v_reason:='phone_changed';
    end if;
  end if;

  if v_reason is not null then
    update public.marketing_campaign_dispatches_v1
      set status='skipped',skip_reason=v_reason,last_error=null,claimed_at=null,eligibility_checked_at=now(),updated_at=now()
      where id=v_dispatch.id;
    return jsonb_build_object('ok',false,'error','dispatch_skipped','skip_reason',v_reason,'dispatch_id',v_dispatch.id);
  end if;

  v_conversation:=public.whatsapp_resolve_conversation_v1(v_dispatch.whatsapp_account_id,v_phone,v_dispatch.customer_id,'campaign');
  if coalesce((v_conversation->>'ok')::boolean,false) is not true then
    update public.marketing_campaign_dispatches_v1 set status='retry',claimed_at=null,available_at=now()+interval '30 seconds',last_error='conversation_unavailable',updated_at=now() where id=v_dispatch.id;
    return jsonb_build_object('ok',false,'error','conversation_unavailable','dispatch_id',v_dispatch.id);
  end if;

  v_key:=format('campaign:%s:snapshot:%s:customer:%s',v_dispatch.campaign_id,v_dispatch.snapshot_id,v_dispatch.customer_id);
  v_enqueue:=public.whatsapp_enqueue_outbound_v1(
    v_key,
    v_dispatch.whatsapp_account_id,
    (v_conversation->>'conversation_id')::uuid,
    v_dispatch.customer_id,
    v_phone,
    'marketing_campaign',
    'template',
    jsonb_build_object(
      'campaign_id',v_campaign.id,
      'snapshot_id',v_snapshot.id,
      'dispatch_id',v_dispatch.id,
      'template_name',v_snapshot.template_name,
      'language_code',v_snapshot.template_language,
      'template_components',v_snapshot.template_components,
      'variable_values',v_snapshot.variable_values_snapshot,
      'deep_link',v_snapshot.deep_link_snapshot
    ),
    'automation',
    v_campaign.template_id
  );
  if coalesce((v_enqueue->>'ok')::boolean,false) is not true then
    update public.marketing_campaign_dispatches_v1 set status='retry',claimed_at=null,available_at=now()+interval '30 seconds',last_error=coalesce(v_enqueue->>'error','outbox_enqueue_failed'),updated_at=now() where id=v_dispatch.id;
    return jsonb_build_object('ok',false,'error',coalesce(v_enqueue->>'error','outbox_enqueue_failed'),'dispatch_id',v_dispatch.id);
  end if;

  update public.marketing_campaign_dispatches_v1
    set outbox_id=(v_enqueue->>'outbox_id')::uuid,eligibility_checked_at=now(),skip_reason=null,last_error=null,updated_at=now()
    where id=v_dispatch.id;

  return jsonb_build_object(
    'ok',true,'dispatch_id',v_dispatch.id,'outbox_id',(v_enqueue->>'outbox_id')::uuid,
    'campaign_id',v_campaign.id,'snapshot_id',v_snapshot.id,'whatsapp_account_id',v_dispatch.whatsapp_account_id,
    'customer_id',v_dispatch.customer_id,'customer_name',coalesce(nullif(split_part(btrim(v_customer.name),' ',1),''),'Cliente'),'to_phone_e164',v_phone,'template_id',v_campaign.template_id,
    'template_name',v_snapshot.template_name,'language_code',v_snapshot.template_language,
    'template_components',v_snapshot.template_components,'variable_values',v_snapshot.variable_values_snapshot,
    'mode',v_gate->>'mode'
  );
end;
$function$
;

-- function: marketing_schedule_campaign_v1(p_campaign_id uuid, p_expected_revision integer, p_scheduled_for timestamp with time zone)
CREATE OR REPLACE FUNCTION public.marketing_schedule_campaign_v1(p_campaign_id uuid, p_expected_revision integer, p_scheduled_for timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_campaign public.marketing_campaigns_v1%rowtype;
  v_snapshot public.marketing_campaign_snapshots_v1%rowtype;
  v_template public.whatsapp_templates_v1%rowtype;
  v_gate jsonb;
  v_when timestamptz:=coalesce(p_scheduled_for,now());
begin
  select * into v_campaign from public.marketing_campaigns_v1 where id=p_campaign_id for update;
  if not found then return jsonb_build_object('ok',false,'error','campaign_not_found'); end if;
  if v_campaign.revision<>p_expected_revision then return jsonb_build_object('ok',false,'error','revision_conflict','revision',v_campaign.revision); end if;
  if v_campaign.manual_batch_mode is true then return jsonb_build_object('ok',false,'error','manual_campaign_requires_explicit_batch'); end if;
  if v_campaign.status<>'approved' then return jsonb_build_object('ok',false,'error','campaign_invalid_transition','status',v_campaign.status); end if;
  select * into v_snapshot from public.marketing_campaign_snapshots_v1
    where campaign_id=v_campaign.id and campaign_revision=v_campaign.revision order by snapshot_version desc limit 1;
  if not found then return jsonb_build_object('ok',false,'error','snapshot_stale'); end if;
  if not exists (
    select 1
    from public.marketing_campaign_snapshot_recipients_v1 r
    where r.snapshot_id=v_snapshot.id
      and r.campaign_id=v_campaign.id
      and r.eligible_at_snapshot is true
      and public.marketing_has_verified_campaign_consent_v1(r.customer_id)
  ) then
    return jsonb_build_object('ok',false,'error','no_eligible_recipients');
  end if;
  select * into v_template from public.whatsapp_templates_v1
    where id=v_campaign.template_id and whatsapp_account_id=v_campaign.whatsapp_account_id
      and upper(category)='MARKETING' and upper(status)='APPROVED';
  if not found then return jsonb_build_object('ok',false,'error','template_not_sendable'); end if;
  v_gate:=public.marketing_campaign_execution_gate_v1(v_campaign.whatsapp_account_id);
  if coalesce((v_gate->>'ok')::boolean,false) is not true then return v_gate; end if;
  update public.marketing_campaigns_v1 set status='scheduled',scheduled_for=v_when,started_at=null,paused_at=null,
    completed_at=null,failed_at=null,execution_last_error=null,updated_at=now() where id=v_campaign.id;
  return jsonb_build_object('ok',true,'campaign_id',v_campaign.id,'revision',v_campaign.revision,
    'status','scheduled','scheduled_for',v_when,'snapshot_id',v_snapshot.id,'mode',v_gate->>'mode');
end;
$function$
;

-- function: marketing_strategy_append_event_v1(p_strategy_id uuid, p_event_type text, p_actor_user_id uuid, p_metadata jsonb)
CREATE OR REPLACE FUNCTION public.marketing_strategy_append_event_v1(p_strategy_id uuid, p_event_type text, p_actor_user_id uuid, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_run public.marketing_strategy_runs_v1%rowtype;
  v_event_id uuid;
begin
  select * into v_run
  from public.marketing_strategy_runs_v1
  where id=p_strategy_id;

  if not found then
    return jsonb_build_object('ok',false,'error','strategy_not_found');
  end if;

  if nullif(btrim(coalesce(p_event_type,'')),'') is null then
    return jsonb_build_object('ok',false,'error','invalid_event_type');
  end if;

  insert into public.marketing_strategy_events_v1(
    strategy_id,event_type,strategy_revision,from_status,to_status,actor_user_id,metadata
  ) values (
    v_run.id,btrim(p_event_type),v_run.revision,v_run.status,v_run.status,p_actor_user_id,coalesce(p_metadata,'{}'::jsonb)
  ) returning id into v_event_id;

  return jsonb_build_object('ok',true,'event_id',v_event_id,'strategy_id',v_run.id,'revision',v_run.revision,'status',v_run.status);
end;
$function$
;

-- function: marketing_strategy_approve_send_v1(p_strategy_id uuid, p_expected_revision integer, p_actor_user_id uuid)
CREATE OR REPLACE FUNCTION public.marketing_strategy_approve_send_v1(p_strategy_id uuid, p_expected_revision integer, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_strategy public.marketing_strategy_runs_v1%rowtype;
  v_campaign public.marketing_campaigns_v1%rowtype;
  v_revalidate jsonb;
  v_campaign_transition jsonb;
  v_strategy_transition jsonb;
begin
  select * into v_strategy
  from public.marketing_strategy_runs_v1
  where id=p_strategy_id
  for update;
  if not found then return jsonb_build_object('ok',false,'error','strategy_not_found'); end if;
  if v_strategy.revision<>p_expected_revision then return jsonb_build_object('ok',false,'error','revision_conflict','revision',v_strategy.revision,'status',v_strategy.status); end if;

  if v_strategy.status='send_approved' then
    return jsonb_build_object('ok',true,'idempotent',true,'strategy_id',v_strategy.id,'strategy_status',v_strategy.status,'revision',v_strategy.revision,'campaign_id',v_strategy.campaign_id);
  end if;
  if v_strategy.status<>'ready_to_send' then return jsonb_build_object('ok',false,'error','strategy_invalid_transition','from_status',v_strategy.status,'to_status','send_approved'); end if;
  if v_strategy.campaign_id is null then return jsonb_build_object('ok',false,'error','strategy_campaign_required'); end if;

  v_revalidate:=public.marketing_strategy_revalidate_commercial_v1(v_strategy.id);
  if coalesce((v_revalidate->>'ok')::boolean,false) is not true then return v_revalidate; end if;

  select * into v_campaign
  from public.marketing_campaigns_v1
  where id=v_strategy.campaign_id and strategy_id=v_strategy.id
  for update;
  if not found then return jsonb_build_object('ok',false,'error','strategy_campaign_not_found'); end if;
  if v_campaign.template_id<>v_strategy.template_id or v_campaign.whatsapp_account_id<>v_strategy.whatsapp_account_id then
    return jsonb_build_object('ok',false,'error','strategy_material_change','issues',jsonb_build_array(jsonb_build_object('reason','campaign_identity_changed')));
  end if;

  if not exists(
    select 1 from public.whatsapp_templates_v1 t
    where t.id=v_strategy.template_id and t.whatsapp_account_id=v_strategy.whatsapp_account_id
      and upper(t.category)='MARKETING' and upper(t.status)='APPROVED'
  ) then
    return jsonb_build_object('ok',false,'error','template_not_sendable');
  end if;

  if v_campaign.status='ready_for_review' then
    v_campaign_transition:=public.marketing_transition_campaign_v1(v_campaign.id,v_campaign.revision,'approved','Portão C aprovado na Estratégia');
    if coalesce((v_campaign_transition->>'ok')::boolean,false) is not true then
      raise exception 'strategy_campaign_bridge_failed:campaign_approval:%',coalesce(v_campaign_transition->>'error','unknown');
    end if;
  elsif v_campaign.status<>'approved' then
    return jsonb_build_object('ok',false,'error','campaign_invalid_transition','status',v_campaign.status);
  end if;

  v_strategy_transition:=public.marketing_strategy_transition_v1(v_strategy.id,v_strategy.revision,'send_approved',p_actor_user_id,'Portão C aprovado');
  if coalesce((v_strategy_transition->>'ok')::boolean,false) is not true then
    raise exception 'strategy_campaign_bridge_failed:strategy_approval:%',coalesce(v_strategy_transition->>'error','unknown');
  end if;

  perform public.marketing_strategy_append_event_v1(v_strategy.id,'portal_c_approved',p_actor_user_id,jsonb_build_object('campaign_id',v_campaign.id));

  return jsonb_build_object('ok',true,'idempotent',false,
    'strategy_id',v_strategy.id,'strategy_status','send_approved','revision',(v_strategy_transition->>'revision')::integer,
    'campaign_id',v_campaign.id,'campaign_status','approved');
end;
$function$
;

-- function: marketing_strategy_detail_v1(p_strategy_id uuid)
CREATE OR REPLACE FUNCTION public.marketing_strategy_detail_v1(p_strategy_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_run public.marketing_strategy_runs_v1%rowtype;
  v_offers jsonb;
  v_events jsonb;
begin
  select * into v_run from public.marketing_strategy_runs_v1 where id=p_strategy_id;
  if not found then
    return jsonb_build_object('ok',false,'error','strategy_not_found');
  end if;

  select coalesce(jsonb_agg(to_jsonb(o) order by o.position),'[]'::jsonb)
  into v_offers
  from public.marketing_strategy_offers_v1 o
  where o.strategy_id=v_run.id;

  select coalesce(jsonb_agg(to_jsonb(e) order by e.created_at,e.id),'[]'::jsonb)
  into v_events
  from public.marketing_strategy_events_v1 e
  where e.strategy_id=v_run.id;

  return jsonb_build_object(
    'ok',true,
    'strategy',to_jsonb(v_run),
    'offers',v_offers,
    'events',v_events
  );
end;
$function$
;

-- function: marketing_strategy_events_immutable_v1()
CREATE OR REPLACE FUNCTION public.marketing_strategy_events_immutable_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  raise exception 'marketing_strategy_events_append_only' using errcode='55000';
end;
$function$
;

-- function: marketing_strategy_funnel_v1(p_strategy_id uuid)
CREATE OR REPLACE FUNCTION public.marketing_strategy_funnel_v1(p_strategy_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_selected integer:=0;
  v_sent integer:=0;
  v_delivered integer:=0;
  v_read integer:=0;
  v_clicked_recipients integer:=0;
  v_storefront_opens integer:=0;
  v_checkout_started integer:=0;
  v_responded_recipients integer:=0;
  v_response_messages integer:=0;
  v_attributed_orders integer:=0;
  v_direct_orders integer:=0;
  v_assisted_orders integer:=0;
  v_cancelled_orders integer:=0;
  v_direct_revenue numeric:=0;
  v_assisted_revenue numeric:=0;
  v_attributed_revenue numeric:=0;
  v_avg_ticket numeric:=0;
  v_avg_hours_to_order numeric:=null;
  v_delivery_rate numeric:=0;
  v_read_rate numeric:=0;
  v_click_rate numeric:=0;
  v_response_rate numeric:=0;
  v_conversion_rate numeric:=0;
  v_revenue_per_1000_delivered numeric:=0;
begin
  with campaign_scope as (
    select c.id,c.strategy_id,c.whatsapp_account_id
    from public.marketing_campaigns_v1 c
    where c.strategy_id is not null
      and (p_strategy_id is null or c.strategy_id=p_strategy_id)
  ),
  dispatch_base as (
    select
      d.id,d.campaign_id,d.customer_id,d.whatsapp_account_id,d.provider_message_id,d.status,d.created_at,d.updated_at,
      cs.strategy_id,
      coalesce(m.sent_at,d.updated_at,d.created_at) as sent_anchor,
      lower(coalesce(m.status_current,'')) as message_status
    from public.marketing_campaign_dispatches_v1 d
    join campaign_scope cs on cs.id=d.campaign_id
    left join lateral (
      select wm.sent_at,wm.status_current
      from public.whatsapp_messages_v1 wm
      where wm.provider='meta'
        and wm.provider_message_id=d.provider_message_id
      order by wm.created_at desc,wm.id desc
      limit 1
    ) m on true
  ),
  dispatch_flags as (
    select
      db.*,
      (
        db.message_status in ('sent','delivered','read')
        or exists (
          select 1 from public.whatsapp_message_status_events_v1 se
          where se.provider='meta' and se.provider_message_id=db.provider_message_id
            and lower(se.status) in ('sent','delivered','read')
        )
      ) as sent_flag,
      (
        db.message_status in ('delivered','read')
        or exists (
          select 1 from public.whatsapp_message_status_events_v1 se
          where se.provider='meta' and se.provider_message_id=db.provider_message_id
            and lower(se.status) in ('delivered','read')
        )
      ) as delivered_flag,
      (
        db.message_status='read'
        or exists (
          select 1 from public.whatsapp_message_status_events_v1 se
          where se.provider='meta' and se.provider_message_id=db.provider_message_id
            and lower(se.status)='read'
        )
      ) as read_flag
    from dispatch_base db
  )
  select
    count(*)::integer,
    count(*) filter(where sent_flag)::integer,
    count(*) filter(where delivered_flag)::integer,
    count(*) filter(where read_flag)::integer
  into v_selected,v_sent,v_delivered,v_read
  from dispatch_flags;

  with scoped_links as (
    select l.*
    from public.marketing_tracking_links_v1 l
    where p_strategy_id is null or l.strategy_id=p_strategy_id
  )
  select
    count(distinct dispatch_id) filter(where first_opened_at is not null)::integer,
    coalesce(sum(open_count),0)::integer,
    count(distinct dispatch_id) filter(where checkout_started_at is not null)::integer
  into v_clicked_recipients,v_storefront_opens,v_checkout_started
  from scoped_links;

  -- Uma mensagem inbound é relacionada à campanha de Estratégia mais recente
  -- do mesmo cliente/canal nos 7 dias anteriores. Isso mede interação pós-campanha
  -- sem duplicar a mensagem na tabela de atribuição.
  with inbound_messages as (
    select
      wm.id,
      wm.customer_id,
      wm.whatsapp_account_id,
      coalesce(wm.received_at,wm.created_at) as inbound_at
    from public.whatsapp_messages_v1 wm
    where wm.direction='inbound'
      and wm.customer_id is not null
  ),
  attributed_inbound as (
    select i.id,i.customer_id,hit.dispatch_id,hit.strategy_id
    from inbound_messages i
    cross join lateral (
      select
        d.id as dispatch_id,
        c.strategy_id,
        coalesce(out_msg.sent_at,d.updated_at,d.created_at) as sent_anchor
      from public.marketing_campaign_dispatches_v1 d
      join public.marketing_campaigns_v1 c on c.id=d.campaign_id and c.strategy_id is not null
      left join lateral (
        select wm.sent_at
        from public.whatsapp_messages_v1 wm
        where wm.provider='meta' and wm.provider_message_id=d.provider_message_id
        order by wm.created_at desc,wm.id desc
        limit 1
      ) out_msg on true
      where d.customer_id=i.customer_id
        and d.whatsapp_account_id=i.whatsapp_account_id
        and d.provider_message_id is not null
        and coalesce(out_msg.sent_at,d.updated_at,d.created_at)<=i.inbound_at
        and coalesce(out_msg.sent_at,d.updated_at,d.created_at)>=i.inbound_at-interval '7 days'
      order by coalesce(out_msg.sent_at,d.updated_at,d.created_at) desc,d.id desc
      limit 1
    ) hit
    where p_strategy_id is null or hit.strategy_id=p_strategy_id
  )
  select
    count(distinct dispatch_id)::integer,
    count(*)::integer
  into v_responded_recipients,v_response_messages
  from attributed_inbound;

  select
    count(distinct e.order_id)::integer,
    count(distinct e.order_id) filter(where e.attribution_kind='direct')::integer,
    count(distinct e.order_id) filter(where e.attribution_kind='assisted')::integer,
    coalesce(sum(e.amount) filter(where e.attribution_kind='direct'),0),
    coalesce(sum(e.amount) filter(where e.attribution_kind='assisted'),0),
    coalesce(sum(e.amount),0),
    coalesce(avg(e.amount),0)
  into v_attributed_orders,v_direct_orders,v_assisted_orders,v_direct_revenue,v_assisted_revenue,v_attributed_revenue,v_avg_ticket
  from public.marketing_attribution_events_v1 e
  join public.orders o on o.id=e.order_id
  where e.event_type='order_attributed'
    and (p_strategy_id is null or e.strategy_id=p_strategy_id)
    and o.confirmed_at is not null
    and o.cancelled_at is null
    and o.returned_at is null;

  select count(distinct e.order_id)::integer
  into v_cancelled_orders
  from public.marketing_attribution_events_v1 e
  join public.orders o on o.id=e.order_id
  where e.event_type='order_attributed'
    and (p_strategy_id is null or e.strategy_id=p_strategy_id)
    and (o.cancelled_at is not null or o.returned_at is not null);

  select round(avg(extract(epoch from (o.confirmed_at-l.first_opened_at))/3600.0)::numeric,2)
  into v_avg_hours_to_order
  from public.marketing_tracking_links_v1 l
  join public.orders o on o.id=l.attributed_order_id
  where l.first_opened_at is not null
    and o.confirmed_at is not null
    and o.cancelled_at is null
    and o.returned_at is null
    and (p_strategy_id is null or l.strategy_id=p_strategy_id);

  v_delivery_rate:=case when v_sent>0 then round((v_delivered::numeric/v_sent)*100,2) else 0 end;
  v_read_rate:=case when v_delivered>0 then round((v_read::numeric/v_delivered)*100,2) else 0 end;
  v_click_rate:=case when v_delivered>0 then round((v_clicked_recipients::numeric/v_delivered)*100,2) else 0 end;
  v_response_rate:=case when v_delivered>0 then round((v_responded_recipients::numeric/v_delivered)*100,2) else 0 end;
  v_conversion_rate:=case when v_delivered>0 then round((v_attributed_orders::numeric/v_delivered)*100,2) else 0 end;
  v_revenue_per_1000_delivered:=case when v_delivered>0 then round((v_attributed_revenue/v_delivered)*1000,2) else 0 end;

  return jsonb_build_object(
    'ok',true,
    'strategy_id',p_strategy_id,
    'window_days',7,
    'selected',v_selected,
    'sent',v_sent,
    'delivered',v_delivered,
    'read',v_read,
    'delivery_rate',v_delivery_rate,
    'read_rate',v_read_rate,
    'clicked_recipients',v_clicked_recipients,
    'storefront_opens',v_storefront_opens,
    'click_rate',v_click_rate,
    'checkout_started',v_checkout_started,
    'responded_recipients',v_responded_recipients,
    'response_messages',v_response_messages,
    'response_rate',v_response_rate,
    'attributed_orders',v_attributed_orders,
    'direct_orders',v_direct_orders,
    'assisted_orders',v_assisted_orders,
    'cancelled_orders',v_cancelled_orders,
    'direct_revenue',round(v_direct_revenue,2),
    'assisted_revenue',round(v_assisted_revenue,2),
    'attributed_revenue',round(v_attributed_revenue,2),
    'avg_ticket',round(v_avg_ticket,2),
    'conversion_rate',v_conversion_rate,
    'revenue_per_1000_delivered',v_revenue_per_1000_delivered,
    'avg_hours_to_order',v_avg_hours_to_order
  );
end;
$function$
;

-- function: marketing_strategy_learnings_v1()
CREATE OR REPLACE FUNCTION public.marketing_strategy_learnings_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_funnel jsonb:=public.marketing_strategy_funnel_v1(null);
  v_performance jsonb:=public.marketing_strategy_offer_performance_v1();
  v_completed integer:=0;
  v_delivered integer:=coalesce((v_funnel->>'delivered')::integer,0);
  v_orders integer:=coalesce((v_funnel->>'attributed_orders')::integer,0);
  v_revenue numeric:=coalesce((v_funnel->>'attributed_revenue')::numeric,0);
  v_level text:='insufficient';
  v_items jsonb:='[]'::jsonb;
  v_top jsonb;
begin
  select count(*)::integer into v_completed
  from public.marketing_strategy_runs_v1 where status='completed';

  v_level:=case
    when v_delivered>=100 and v_orders>=10 then 'confirmed'
    when v_delivered>=30 or v_orders>=3 then 'trend'
    else 'insufficient'
  end;

  if coalesce((v_funnel->>'selected')::integer,0)>0 then
    v_items:=v_items||jsonb_build_array(jsonb_build_object(
      'evidence_label',case v_level when 'confirmed' then 'Aprendizado confirmado' when 'trend' then 'Tendência' else 'Sinal inicial' end,
      'title','Funil das estratégias',
      'summary',format('%s entregues · %s lidos · %s acessos · %s respostas · %s pedidos confirmados.',
        coalesce(v_funnel->>'delivered','0'),
        coalesce(v_funnel->>'read','0'),
        coalesce(v_funnel->>'clicked_recipients','0'),
        coalesce(v_funnel->>'responded_recipients','0'),
        coalesce(v_funnel->>'attributed_orders','0')
      ),
      'sample_label',format('%s estratégias concluídas · janela de 7 dias',v_completed),
      'metrics',v_funnel
    ));
  end if;

  if v_orders>0 then
    v_items:=v_items||jsonb_build_array(jsonb_build_object(
      'evidence_label',case v_level when 'confirmed' then 'Aprendizado confirmado' when 'trend' then 'Tendência' else 'Sinal inicial' end,
      'title','Resultado econômico',
      'summary',format('R$ %s atribuídos · R$ %s por 1.000 entregues · conversão de %s%%.',
        to_char(v_revenue,'FM999999990D00'),
        coalesce(v_funnel->>'revenue_per_1000_delivered','0'),
        coalesce(v_funnel->>'conversion_rate','0')
      ),
      'sample_label',format('%s pedidos diretos · %s assistidos · ticket médio R$ %s',
        coalesce(v_funnel->>'direct_orders','0'),
        coalesce(v_funnel->>'assisted_orders','0'),
        coalesce(v_funnel->>'avg_ticket','0')
      ),
      'direct_revenue',coalesce((v_funnel->>'direct_revenue')::numeric,0),
      'assisted_revenue',coalesce((v_funnel->>'assisted_revenue')::numeric,0),
      'attributed_revenue',v_revenue,
      'revenue_per_1000_delivered',coalesce((v_funnel->>'revenue_per_1000_delivered')::numeric,0)
    ));
  end if;

  v_top:=case
    when jsonb_typeof(v_performance->'items')='array' and jsonb_array_length(v_performance->'items')>0
      then (v_performance->'items')->0
    else null
  end;

  if v_top is not null and coalesce((v_top->>'orders')::integer,0)>0 then
    v_items:=v_items||jsonb_build_array(jsonb_build_object(
      'evidence_label',case coalesce(v_top->>'evidence_level','insufficient') when 'confirmed' then 'Aprendizado confirmado' when 'trend' then 'Tendência' else 'Sinal inicial' end,
      'title','Cesta/Kit com melhor retorno direto',
      'summary',format('%s gerou %s pedido(s) direto(s) e R$ %s por 1.000 entregues.',
        coalesce(v_top->>'public_name','Cesta ou Kit'),
        coalesce(v_top->>'orders','0'),
        coalesce(v_top->>'revenue_per_1000_delivered','0')
      ),
      'sample_label',format('%s mensagens entregues para estratégias com essa oferta',coalesce(v_top->>'delivered','0')),
      'commercial_id',v_top->>'commercial_id',
      'score_signal',coalesce((v_top->>'score_signal')::numeric,0)
    ));
  end if;

  return jsonb_build_object(
    'ok',true,
    'evidence_level',v_level,
    'sample',jsonb_build_object(
      'completed_strategies',v_completed,
      'delivered',v_delivered,
      'attributed_orders',v_orders,
      'window_days',7
    ),
    'funnel',v_funnel,
    'offer_performance',v_performance,
    'items',v_items
  );
end;
$function$
;

-- function: marketing_strategy_materialize_campaign_v1(p_strategy_id uuid, p_expected_revision integer, p_actor_user_id uuid)
CREATE OR REPLACE FUNCTION public.marketing_strategy_materialize_campaign_v1(p_strategy_id uuid, p_expected_revision integer, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_strategy public.marketing_strategy_runs_v1%rowtype;
  v_template public.whatsapp_templates_v1%rowtype;
  v_campaign public.marketing_campaigns_v1%rowtype;
  v_revalidate jsonb;
  v_created jsonb;
  v_snapshot jsonb;
  v_campaign_transition jsonb;
  v_strategy_transition jsonb;
  v_filters jsonb:='{}'::jsonb;
  v_variables jsonb:='{}'::jsonb;
  v_deep_link jsonb:='{}'::jsonb;
  v_offer_links jsonb:='[]'::jsonb;
  v_name text;
  v_headline text;
  v_body text;
  v_idempotency text;
  v_campaign_id uuid;
  v_campaign_revision integer;
begin
  select * into v_strategy
  from public.marketing_strategy_runs_v1
  where id=p_strategy_id
  for update;

  if not found then return jsonb_build_object('ok',false,'error','strategy_not_found'); end if;
  if v_strategy.revision<>p_expected_revision then return jsonb_build_object('ok',false,'error','revision_conflict','revision',v_strategy.revision,'status',v_strategy.status); end if;

  if v_strategy.campaign_id is not null and v_strategy.status in ('ready_to_send','send_approved','scheduled','running','completed') then
    select * into v_campaign from public.marketing_campaigns_v1 where id=v_strategy.campaign_id;
    return jsonb_build_object('ok',true,'idempotent',true,'strategy_id',v_strategy.id,'strategy_status',v_strategy.status,'revision',v_strategy.revision,'campaign_id',v_strategy.campaign_id,'campaign_status',v_campaign.status);
  end if;

  if v_strategy.status<>'meta_approved' then
    return jsonb_build_object('ok',false,'error','strategy_invalid_transition','from_status',v_strategy.status,'to_status','ready_to_send');
  end if;
  if v_strategy.template_id is null then return jsonb_build_object('ok',false,'error','strategy_template_required'); end if;

  v_revalidate:=public.marketing_strategy_revalidate_commercial_v1(v_strategy.id);
  if coalesce((v_revalidate->>'ok')::boolean,false) is not true then return v_revalidate; end if;

  select * into v_template
  from public.whatsapp_templates_v1
  where id=v_strategy.template_id
    and whatsapp_account_id=v_strategy.whatsapp_account_id
    and upper(category)='MARKETING'
    and upper(status)='APPROVED';
  if not found then return jsonb_build_object('ok',false,'error','template_not_sendable'); end if;

  if jsonb_typeof(v_strategy.audience_snapshot->'filters')='object' then
    v_filters:=v_strategy.audience_snapshot->'filters';
  end if;

  v_headline:=coalesce(nullif(btrim(v_strategy.copy_snapshot->>'headline'),''),'Oferta Dona Antônia');
  v_body:=coalesce(nullif(btrim(v_strategy.copy_snapshot->>'body'),''),'Confira nossa seleção de Cestas e Kits.');
  if v_strategy.offer_format='single' then
    v_variables:=jsonb_build_object('1',v_headline,'2',v_body,'3','https://www.donaantonia.com.br/');
  else
    v_variables:='{}'::jsonb;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'position',o.position,
    'commercial_id',o.commercial_id,
    'public_lot_id',o.public_lot_id,
    'public_name',o.public_name,
    'sale_price',o.sale_price_snapshot
  ) order by o.position),'[]'::jsonb)
  into v_offer_links
  from public.marketing_strategy_offers_v1 o
  where o.strategy_id=v_strategy.id;

  v_deep_link:=jsonb_build_object(
    'source','marketing_strategy_v1',
    'strategy_id',v_strategy.id,
    'offers',v_offer_links
  );
  v_name:=left(format('Estratégia %s · %s',to_char(v_strategy.period_start,'DD/MM/YYYY'),v_headline),160);
  v_idempotency:=format('strategy:%s:campaign',v_strategy.id);

  v_created:=public.marketing_create_campaign_v1(
    v_name,
    v_strategy.whatsapp_account_id,
    v_strategy.template_id,
    v_filters,
    v_variables,
    v_deep_link,
    v_idempotency
  );
  if coalesce((v_created->>'ok')::boolean,false) is not true then return v_created; end if;

  v_campaign_id:=(v_created->>'campaign_id')::uuid;
  select * into v_campaign from public.marketing_campaigns_v1 where id=v_campaign_id for update;
  if not found then raise exception 'strategy_campaign_bridge_failed:campaign_missing'; end if;
  if v_campaign.strategy_id is not null and v_campaign.strategy_id<>v_strategy.id then
    raise exception 'strategy_campaign_bridge_failed:campaign_strategy_conflict';
  end if;

  update public.marketing_campaigns_v1
  set strategy_id=v_strategy.id,
      metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('source','marketing_strategy_v1','strategy_revision',v_strategy.revision),
      updated_at=now()
  where id=v_campaign.id
  returning * into v_campaign;

  v_campaign_revision:=v_campaign.revision;
  v_snapshot:=public.marketing_create_campaign_snapshot_v1(v_campaign.id,v_campaign_revision,format('strategy:%s:snapshot:r%s',v_strategy.id,v_campaign_revision));
  if coalesce((v_snapshot->>'ok')::boolean,false) is not true then
    raise exception 'strategy_campaign_bridge_failed:snapshot:%',coalesce(v_snapshot->>'error','unknown');
  end if;

  if v_campaign.status='draft' then
    v_campaign_transition:=public.marketing_transition_campaign_v1(v_campaign.id,v_campaign_revision,'ready_for_review','materialized_from_strategy');
    if coalesce((v_campaign_transition->>'ok')::boolean,false) is not true then
      raise exception 'strategy_campaign_bridge_failed:campaign_transition:%',coalesce(v_campaign_transition->>'error','unknown');
    end if;
  elsif v_campaign.status<>'ready_for_review' then
    raise exception 'strategy_campaign_bridge_failed:campaign_status:%',v_campaign.status;
  end if;

  update public.marketing_strategy_runs_v1
  set campaign_id=v_campaign.id,updated_at=now()
  where id=v_strategy.id;

  v_strategy_transition:=public.marketing_strategy_transition_v1(v_strategy.id,v_strategy.revision,'ready_to_send',p_actor_user_id,'Campanha preparada para o Portão C');
  if coalesce((v_strategy_transition->>'ok')::boolean,false) is not true then
    raise exception 'strategy_campaign_bridge_failed:strategy_transition:%',coalesce(v_strategy_transition->>'error','unknown');
  end if;

  perform public.marketing_strategy_append_event_v1(v_strategy.id,'campaign_materialized',p_actor_user_id,jsonb_build_object(
    'campaign_id',v_campaign.id,
    'snapshot_id',v_snapshot->>'snapshot_id',
    'campaign_status','ready_for_review'
  ));

  return jsonb_build_object(
    'ok',true,'idempotent',coalesce((v_created->>'idempotent')::boolean,false),
    'strategy_id',v_strategy.id,'strategy_status','ready_to_send','revision',(v_strategy_transition->>'revision')::integer,
    'campaign_id',v_campaign.id,'campaign_status','ready_for_review','snapshot_id',v_snapshot->>'snapshot_id',
    'eligible_count',coalesce((v_snapshot->>'eligible_count')::integer,0)
  );
end;
$function$
;

-- function: marketing_strategy_offer_performance_v1()
CREATE OR REPLACE FUNCTION public.marketing_strategy_offer_performance_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_items jsonb:='[]'::jsonb;
begin
  with strategy_campaigns as (
    select c.id as campaign_id,c.strategy_id
    from public.marketing_campaigns_v1 c
    where c.strategy_id is not null
  ),
  dispatch_flags as (
    select
      d.id,d.campaign_id,sc.strategy_id,
      (
        lower(coalesce(m.status_current,'')) in ('delivered','read')
        or exists (
          select 1 from public.whatsapp_message_status_events_v1 se
          where se.provider='meta' and se.provider_message_id=d.provider_message_id
            and lower(se.status) in ('delivered','read')
        )
      ) as delivered_flag
    from public.marketing_campaign_dispatches_v1 d
    join strategy_campaigns sc on sc.campaign_id=d.campaign_id
    left join lateral (
      select wm.status_current
      from public.whatsapp_messages_v1 wm
      where wm.provider='meta' and wm.provider_message_id=d.provider_message_id
      order by wm.created_at desc,wm.id desc
      limit 1
    ) m on true
  ),
  delivered_by_strategy as (
    select strategy_id,count(*) filter(where delivered_flag)::integer as delivered
    from dispatch_flags
    group by strategy_id
  ),
  exposure as (
    select
      o.commercial_id,
      max(o.public_name) as public_name,
      sum(coalesce(d.delivered,0))::integer as delivered
    from public.marketing_strategy_offers_v1 o
    left join delivered_by_strategy d on d.strategy_id=o.strategy_id
    group by o.commercial_id
  ),
  sales as (
    select
      e.commercial_id,
      count(distinct e.order_id)::integer as orders,
      coalesce(sum(e.amount),0) as revenue
    from public.marketing_attribution_events_v1 e
    join public.orders ord on ord.id=e.order_id
    where e.event_type='order_attributed'
      and e.attribution_kind='direct'
      and e.commercial_id is not null
      and ord.confirmed_at is not null
      and ord.cancelled_at is null
      and ord.returned_at is null
    group by e.commercial_id
  ),
  metrics as (
    select
      x.commercial_id,x.public_name,x.delivered,
      coalesce(s.orders,0) as orders,
      coalesce(s.revenue,0) as revenue,
      case when x.delivered>0 then round((coalesce(s.orders,0)::numeric/x.delivered)*1000,2) else 0 end as orders_per_1000_delivered,
      case when x.delivered>0 then round((coalesce(s.revenue,0)/x.delivered)*1000,2) else 0 end as revenue_per_1000_delivered
    from exposure x
    left join sales s on s.commercial_id=x.commercial_id
  ),
  normalized as (
    select
      m.*,
      max(m.revenue_per_1000_delivered) over() as max_revenue_per_1000
    from metrics m
  ),
  scored as (
    select
      n.*,
      round((
        least(1,n.delivered::numeric/100)
        * case when n.max_revenue_per_1000>0 then least(1,n.revenue_per_1000_delivered/n.max_revenue_per_1000) else 0 end
      ),4) as score_signal,
      case
        when n.delivered>=100 and n.orders>=10 then 'confirmed'
        when n.delivered>=30 or n.orders>=3 then 'trend'
        else 'insufficient'
      end as evidence_level
    from normalized n
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'commercial_id',commercial_id,
    'public_name',public_name,
    'delivered',delivered,
    'orders',orders,
    'revenue',round(revenue,2),
    'orders_per_1000_delivered',orders_per_1000_delivered,
    'revenue_per_1000_delivered',revenue_per_1000_delivered,
    'score_signal',score_signal,
    'evidence_level',evidence_level
  ) order by score_signal desc,revenue_per_1000_delivered desc,commercial_id),'[]'::jsonb)
  into v_items
  from scored;

  return jsonb_build_object('ok',true,'items',v_items,'scoring','revenue_per_1000_delivered_normalized_x_evidence','minimum_evidence_delivered',100);
end;
$function$
;

-- function: marketing_strategy_revalidate_commercial_v1(p_strategy_id uuid)
CREATE OR REPLACE FUNCTION public.marketing_strategy_revalidate_commercial_v1(p_strategy_id uuid)
 RETURNS jsonb
 LANGUAGE sql
