-- function: marketing_strategy_schedule_send_v1(p_strategy_id uuid, p_expected_revision integer, p_scheduled_for timestamp with time zone, p_actor_user_id uuid)
CREATE OR REPLACE FUNCTION public.marketing_strategy_schedule_send_v1(p_strategy_id uuid, p_expected_revision integer, p_scheduled_for timestamp with time zone, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_strategy public.marketing_strategy_runs_v1%rowtype;
  v_campaign public.marketing_campaigns_v1%rowtype;
  v_revalidate jsonb;
  v_scheduled jsonb;
  v_strategy_transition jsonb;
  v_when timestamptz:=coalesce(p_scheduled_for,now());
begin
  select * into v_strategy
  from public.marketing_strategy_runs_v1
  where id=p_strategy_id
  for update;
  if not found then return jsonb_build_object('ok',false,'error','strategy_not_found'); end if;
  if v_strategy.revision<>p_expected_revision then return jsonb_build_object('ok',false,'error','revision_conflict','revision',v_strategy.revision,'status',v_strategy.status); end if;

  if v_strategy.status='scheduled' then
    return jsonb_build_object('ok',true,'idempotent',true,'strategy_id',v_strategy.id,'strategy_status','scheduled','revision',v_strategy.revision,'campaign_id',v_strategy.campaign_id);
  end if;
  if v_strategy.status<>'send_approved' then return jsonb_build_object('ok',false,'error','strategy_invalid_transition','from_status',v_strategy.status,'to_status','scheduled'); end if;
  if v_strategy.campaign_id is null then return jsonb_build_object('ok',false,'error','strategy_campaign_required'); end if;

  v_revalidate:=public.marketing_strategy_revalidate_commercial_v1(v_strategy.id);
  if coalesce((v_revalidate->>'ok')::boolean,false) is not true then return v_revalidate; end if;

  select * into v_campaign
  from public.marketing_campaigns_v1
  where id=v_strategy.campaign_id and strategy_id=v_strategy.id
  for update;
  if not found then return jsonb_build_object('ok',false,'error','strategy_campaign_not_found'); end if;
  if v_campaign.status<>'approved' then return jsonb_build_object('ok',false,'error','campaign_invalid_transition','status',v_campaign.status); end if;

  v_scheduled:=public.marketing_schedule_campaign_v1(v_campaign.id,v_campaign.revision,v_when);
  if coalesce((v_scheduled->>'ok')::boolean,false) is not true then
    -- campaigns_disabled/runtime off chega aqui sem alterar campanha ou estratégia.
    return v_scheduled||jsonb_build_object('strategy_id',v_strategy.id,'strategy_status',v_strategy.status);
  end if;

  v_strategy_transition:=public.marketing_strategy_transition_v1(v_strategy.id,v_strategy.revision,'scheduled',p_actor_user_id,'Agendamento confirmado pelo motor canônico');
  if coalesce((v_strategy_transition->>'ok')::boolean,false) is not true then
    -- Exceção garante rollback também do marketing_schedule_campaign_v1 executado acima.
    raise exception 'strategy_campaign_bridge_failed:strategy_schedule:%',coalesce(v_strategy_transition->>'error','unknown');
  end if;

  perform public.marketing_strategy_append_event_v1(v_strategy.id,'campaign_scheduled',p_actor_user_id,jsonb_build_object(
    'campaign_id',v_campaign.id,
    'scheduled_for',v_when
  ));

  return jsonb_build_object('ok',true,
    'strategy_id',v_strategy.id,'strategy_status','scheduled','revision',(v_strategy_transition->>'revision')::integer,
    'campaign_id',v_campaign.id,'campaign_status','scheduled','scheduled_for',v_when,
    'mode',v_scheduled->>'mode');
end;
$function$
;

-- function: marketing_strategy_transition_v1(p_strategy_id uuid, p_expected_revision integer, p_to_status text, p_actor_user_id uuid, p_reason text)
CREATE OR REPLACE FUNCTION public.marketing_strategy_transition_v1(p_strategy_id uuid, p_expected_revision integer, p_to_status text, p_actor_user_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_run public.marketing_strategy_runs_v1%rowtype;
  v_from text;
  v_to text:=lower(btrim(coalesce(p_to_status,'')));
  v_allowed boolean:=false;
begin
  if p_expected_revision is null or p_expected_revision < 1 or v_to='' then
    return jsonb_build_object('ok',false,'error','invalid_transition');
  end if;

  select * into v_run
  from public.marketing_strategy_runs_v1
  where id=p_strategy_id
  for update;

  if not found then
    return jsonb_build_object('ok',false,'error','strategy_not_found');
  end if;
  if v_run.revision<>p_expected_revision then
    return jsonb_build_object('ok',false,'error','revision_conflict','revision',v_run.revision,'status',v_run.status);
  end if;

  v_from:=v_run.status;
  v_allowed:=case v_from
    when 'draft' then v_to in ('awaiting_internal_approval','discarded')
    when 'awaiting_internal_approval' then v_to in ('draft','approved_internal','discarded')
    when 'approved_internal' then v_to in ('awaiting_meta','meta_approved','discarded','blocked')
    when 'awaiting_meta' then v_to in ('meta_approved','meta_rejected','blocked')
    when 'meta_rejected' then v_to in ('draft','discarded')
    when 'meta_approved' then v_to in ('ready_to_send','blocked')
    when 'ready_to_send' then v_to in ('draft','send_approved','discarded','blocked')
    when 'send_approved' then v_to in ('scheduled','running','blocked')
    when 'scheduled' then v_to in ('running','discarded','blocked')
    when 'running' then v_to in ('completed','blocked')
    when 'blocked' then v_to in ('draft','awaiting_internal_approval','discarded')
    else false
  end;

  if not v_allowed then
    return jsonb_build_object('ok',false,'error','strategy_invalid_transition','from_status',v_from,'to_status',v_to);
  end if;

  update public.marketing_strategy_runs_v1
  set status=v_to,
      revision=revision+1,
      internal_approved_at=case when v_to='approved_internal' then now() else internal_approved_at end,
      internal_approved_by=case when v_to='approved_internal' then p_actor_user_id else internal_approved_by end,
      meta_submitted_at=case when v_to='awaiting_meta' then now() else meta_submitted_at end,
      meta_approved_at=case when v_to='meta_approved' then now() else meta_approved_at end,
      meta_rejected_at=case when v_to='meta_rejected' then now() else meta_rejected_at end,
      send_approved_at=case when v_to='send_approved' then now() else send_approved_at end,
      send_approved_by=case when v_to='send_approved' then p_actor_user_id else send_approved_by end,
      completed_at=case when v_to='completed' then now() else completed_at end,
      updated_at=now()
  where id=v_run.id
  returning * into v_run;

  insert into public.marketing_strategy_events_v1(
    strategy_id,event_type,strategy_revision,from_status,to_status,actor_user_id,reason,metadata
  ) values (
    v_run.id,'status_transition',v_run.revision,v_from,v_to,p_actor_user_id,nullif(btrim(coalesce(p_reason,'')),''),
    jsonb_build_object('expected_revision',p_expected_revision)
  );

  return jsonb_build_object('ok',true,'strategy_id',v_run.id,'revision',v_run.revision,'status',v_run.status);
end;
$function$
;

-- function: marketing_template_lifecycle_approve_delete_v1(p_template_id uuid, p_actor_user_id uuid)
CREATE OR REPLACE FUNCTION public.marketing_template_lifecycle_approve_delete_v1(p_template_id uuid, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_template public.whatsapp_templates_v1%rowtype;
  v_row public.marketing_template_lifecycle_v1%rowtype;
begin
  perform public.marketing_template_lifecycle_refresh_v1();

  select t.* into v_template
  from public.whatsapp_templates_v1 t
  where t.id=p_template_id
  for update;
  if not found then return jsonb_build_object('ok',false,'error','template_not_found'); end if;
  if upper(coalesce(v_template.category,''))<>'MARKETING' then return jsonb_build_object('ok',false,'error','template_not_marketing'); end if;

  select * into v_row
  from public.marketing_template_lifecycle_v1
  where template_id=v_template.id
  for update;
  if not found then return jsonb_build_object('ok',false,'error','template_lifecycle_missing'); end if;

  if v_row.lifecycle_status='deleted_meta' or coalesce((v_template.metadata->>'meta_missing')::boolean,false)=true then
    return jsonb_build_object('ok',true,'idempotent',true,'template_id',v_template.id,'lifecycle_status','deleted_meta');
  end if;
  if v_row.protected is true then
    return jsonb_build_object('ok',false,'error','template_protected');
  end if;

  if exists(
    select 1 from public.marketing_campaigns_v1 c
    where c.template_id=v_template.id
      and c.status in ('draft','ready_for_review','approved','scheduled','running','paused')
  ) then
    return jsonb_build_object('ok',false,'error','template_campaign_dependency');
  end if;
  if exists(
    select 1 from public.marketing_strategy_runs_v1 s
    where s.template_id=v_template.id
      and s.status not in ('completed','discarded','meta_rejected')
  ) then
    return jsonb_build_object('ok',false,'error','template_strategy_dependency');
  end if;
  if v_row.candidate_after is null or v_row.candidate_after>now() then
    return jsonb_build_object('ok',false,'error','template_unused_window_not_met','candidate_after',v_row.candidate_after);
  end if;
  if v_row.lifecycle_status not in ('deletion_candidate','delete_approved') then
    return jsonb_build_object('ok',false,'error','template_not_deletion_candidate','lifecycle_status',v_row.lifecycle_status,'reason',v_row.reason);
  end if;

  if v_row.lifecycle_status='delete_approved' then
    return jsonb_build_object(
      'ok',true,'idempotent',true,
      'template_id',v_template.id,
      'whatsapp_account_id',v_template.whatsapp_account_id,
      'meta_template_id',v_template.meta_template_id,
      'name',v_template.name,
      'lifecycle_status','delete_approved',
      'revalidated',true
    );
  end if;

  update public.marketing_template_lifecycle_v1
  set lifecycle_status='delete_approved',
      delete_requested_at=now(),delete_requested_by=p_actor_user_id,
      delete_approved_at=now(),delete_approved_by=p_actor_user_id,
      reason='Exclusão aprovada por humano; aguardando Meta.',updated_at=now(),
      metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object(
        'delete_confirmation_source','admin_explicit',
        'delete_approved_at',now()
      )
  where template_id=v_template.id;

  return jsonb_build_object(
    'ok',true,'idempotent',false,
    'template_id',v_template.id,
    'whatsapp_account_id',v_template.whatsapp_account_id,
    'meta_template_id',v_template.meta_template_id,
    'name',v_template.name,
    'lifecycle_status','delete_approved',
    'revalidated',true
  );
end;
$function$
;

-- function: marketing_template_lifecycle_list_v1(p_whatsapp_account_id uuid)
CREATE OR REPLACE FUNCTION public.marketing_template_lifecycle_list_v1(p_whatsapp_account_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_items jsonb:='[]'::jsonb;
begin
  perform public.marketing_template_lifecycle_refresh_v1();
  select coalesce(jsonb_agg(jsonb_build_object(
    'template_id',t.id,'whatsapp_account_id',t.whatsapp_account_id,'meta_template_id',t.meta_template_id,
    'name',t.name,'language',t.language,'category',t.category,'meta_status',t.status,
    'protected',l.protected,'lifecycle_status',l.lifecycle_status,'last_used_at',l.last_used_at,
    'candidate_after',l.candidate_after,'reason',l.reason,'delete_approved_at',l.delete_approved_at,
    'meta_deleted_at',l.meta_deleted_at,
    'campaign_dependency_count',(select count(*) from public.marketing_campaigns_v1 c where c.template_id=t.id and c.status in ('draft','ready_for_review','approved','scheduled','running','paused')),
    'strategy_dependency_count',(select count(*) from public.marketing_strategy_runs_v1 s where s.template_id=t.id and s.status not in ('completed','discarded','meta_rejected'))
  ) order by case l.lifecycle_status when 'deletion_candidate' then 0 when 'delete_approved' then 1 when 'in_use' then 2 when 'active' then 3 else 4 end,
    coalesce(l.candidate_after,'infinity'::timestamptz),t.name),'[]'::jsonb)
  into v_items
  from public.whatsapp_templates_v1 t
  join public.marketing_template_lifecycle_v1 l on l.template_id=t.id
  where upper(coalesce(t.category,''))='MARKETING'
    and (p_whatsapp_account_id is null or t.whatsapp_account_id=p_whatsapp_account_id);
  return jsonb_build_object('ok',true,'minimum_unused_days',60,
    'candidate_count',(select count(*) from jsonb_array_elements(v_items) item where item->>'lifecycle_status'='deletion_candidate'),'items',v_items);
end;
$function$
;

-- function: marketing_template_lifecycle_mark_deleted_v1(p_template_id uuid, p_actor_user_id uuid, p_provider_payload jsonb)
CREATE OR REPLACE FUNCTION public.marketing_template_lifecycle_mark_deleted_v1(p_template_id uuid, p_actor_user_id uuid, p_provider_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_template public.whatsapp_templates_v1%rowtype; v_row public.marketing_template_lifecycle_v1%rowtype; v_now timestamptz:=now();
begin
  select * into v_template from public.whatsapp_templates_v1 where id=p_template_id for update;
  if not found then return jsonb_build_object('ok',false,'error','template_not_found'); end if;
  select * into v_row from public.marketing_template_lifecycle_v1 where template_id=v_template.id for update;
  if not found then return jsonb_build_object('ok',false,'error','template_lifecycle_missing'); end if;
  if v_row.lifecycle_status='deleted_meta' then return jsonb_build_object('ok',true,'idempotent',true,'template_id',v_template.id,'lifecycle_status','deleted_meta'); end if;
  if v_row.lifecycle_status<>'delete_approved' then return jsonb_build_object('ok',false,'error','template_delete_not_approved','lifecycle_status',v_row.lifecycle_status); end if;
  update public.marketing_template_lifecycle_v1 set lifecycle_status='deleted_meta',meta_deleted_at=v_now,reason='Excluído da Meta; histórico local preservado.',updated_at=v_now,
    metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('meta_delete_completed_by',p_actor_user_id,'meta_delete_completed_at',v_now,'provider_payload',coalesce(p_provider_payload,'{}'::jsonb)) where template_id=v_template.id;
  update public.whatsapp_templates_v1 set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('meta_missing',true,'meta_deleted_at',v_now,'meta_delete_source','marketing_template_lifecycle_v1'),updated_at=v_now where id=v_template.id;
  return jsonb_build_object('ok',true,'idempotent',false,'template_id',v_template.id,'lifecycle_status','deleted_meta','meta_deleted_at',v_now,'history_preserved',true);
end; $function$
;

-- function: marketing_template_lifecycle_refresh_v1()
CREATE OR REPLACE FUNCTION public.marketing_template_lifecycle_refresh_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  r record;
  v_last_used timestamptz;
  v_baseline timestamptz;
  v_campaign_dependency boolean;
  v_strategy_dependency boolean;
  v_status text;
  v_reason text;
  v_candidate_after timestamptz;
  v_candidates integer:=0;
  v_protected integer:=0;
  v_in_use integer:=0;
begin
  insert into public.marketing_template_lifecycle_v1(template_id,protected,lifecycle_status,metadata)
  select t.id,false,'active',jsonb_build_object('source','lifecycle_refresh_v1')
  from public.whatsapp_templates_v1 t
  where upper(coalesce(t.category,''))='MARKETING'
  on conflict(template_id) do nothing;

  for r in
    select t.id,t.created_at,t.metadata,l.protected,l.lifecycle_status,l.meta_deleted_at
    from public.whatsapp_templates_v1 t
    join public.marketing_template_lifecycle_v1 l on l.template_id=t.id
    where upper(coalesce(t.category,''))='MARKETING'
    order by t.created_at,t.id
  loop
    select max(coalesce(c.completed_at,c.started_at))
    into v_last_used
    from public.marketing_campaigns_v1 c
    where c.template_id=r.id
      and (c.started_at is not null or c.completed_at is not null);

    select exists(
      select 1
      from public.marketing_campaigns_v1 c
      where c.template_id=r.id
        and c.status in ('draft','ready_for_review','approved','scheduled','running','paused')
    ) into v_campaign_dependency;

    select exists(
      select 1
      from public.marketing_strategy_runs_v1 s
      where s.template_id=r.id
        and s.status not in ('completed','discarded','meta_rejected')
    ) into v_strategy_dependency;

    v_baseline:=coalesce(v_last_used,r.created_at,now());
    v_candidate_after:=v_baseline+interval '60 days';

    if coalesce((r.metadata->>'meta_missing')::boolean,false)=true or r.meta_deleted_at is not null or r.lifecycle_status='deleted_meta' then
      v_status:='deleted_meta';
      v_reason:='Já removido da Meta; histórico local preservado.';
    elsif r.lifecycle_status='delete_approved' then
      v_status:='delete_approved';
      v_reason:='Exclusão aprovada por humano; aguardando conclusão na Meta.';
    elsif r.protected is true then
      v_status:=case when v_campaign_dependency or v_strategy_dependency then 'in_use' else 'active' end;
      v_reason:='Protegido: nunca entra na limpeza automática.';
      v_protected:=v_protected+1;
    elsif v_campaign_dependency then
      v_status:='in_use';
      v_reason:='Há campanha ativa, em revisão, aprovada ou agendada usando este template.';
      v_in_use:=v_in_use+1;
    elsif v_strategy_dependency then
      v_status:='in_use';
      v_reason:='Há Estratégia de Marketing ainda dependente deste template.';
      v_in_use:=v_in_use+1;
    elsif v_candidate_after<=now() then
      v_status:='deletion_candidate';
      v_reason:='Sem dependências e sem uso por pelo menos 60 dias.';
      v_candidates:=v_candidates+1;
    else
      v_status:='active';
      v_reason:='Ainda dentro da janela mínima de 60 dias ou sem motivo para limpeza.';
    end if;

    update public.marketing_template_lifecycle_v1
    set lifecycle_status=v_status,
        last_used_at=v_last_used,
        retired_at=case when v_status='deletion_candidate' then coalesce(retired_at,now()) else retired_at end,
        candidate_after=v_candidate_after,
        reason=v_reason,
        updated_at=now(),
        metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object(
          'campaign_dependency',v_campaign_dependency,
          'strategy_dependency',v_strategy_dependency,
          'last_refresh_at',now()
        )
    where template_id=r.id;
  end loop;

  return jsonb_build_object('ok',true,'candidates',v_candidates,'protected',v_protected,'in_use',v_in_use,'minimum_unused_days',60);
end;
$function$
;

-- function: marketing_template_lifecycle_set_protected_v1(p_template_id uuid, p_protected boolean, p_actor_user_id uuid)
CREATE OR REPLACE FUNCTION public.marketing_template_lifecycle_set_protected_v1(p_template_id uuid, p_protected boolean, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_template public.whatsapp_templates_v1%rowtype; v_row public.marketing_template_lifecycle_v1%rowtype;
begin
  select * into v_template from public.whatsapp_templates_v1 where id=p_template_id;
  if not found then return jsonb_build_object('ok',false,'error','template_not_found'); end if;
  if upper(coalesce(v_template.category,''))<>'MARKETING' then return jsonb_build_object('ok',false,'error','template_not_marketing'); end if;
  insert into public.marketing_template_lifecycle_v1(template_id,protected,lifecycle_status,metadata)
  values(v_template.id,coalesce(p_protected,false),'active',jsonb_build_object('source','manual_protection'))
  on conflict(template_id) do update set protected=excluded.protected,
    lifecycle_status=case when excluded.protected then 'active' else public.marketing_template_lifecycle_v1.lifecycle_status end,
    delete_requested_at=case when excluded.protected then null else public.marketing_template_lifecycle_v1.delete_requested_at end,
    delete_requested_by=case when excluded.protected then null else public.marketing_template_lifecycle_v1.delete_requested_by end,
    delete_approved_at=case when excluded.protected then null else public.marketing_template_lifecycle_v1.delete_approved_at end,
    delete_approved_by=case when excluded.protected then null else public.marketing_template_lifecycle_v1.delete_approved_by end,
    reason=case when excluded.protected then 'Protegido manualmente por Admin.' else public.marketing_template_lifecycle_v1.reason end,
    updated_at=now(),metadata=coalesce(public.marketing_template_lifecycle_v1.metadata,'{}'::jsonb)||jsonb_build_object('protection_changed_by',p_actor_user_id,'protection_changed_at',now());
  perform public.marketing_template_lifecycle_refresh_v1();
  select * into v_row from public.marketing_template_lifecycle_v1 where template_id=v_template.id;
  return jsonb_build_object('ok',true,'template_id',v_template.id,'protected',v_row.protected,'lifecycle_status',v_row.lifecycle_status,'reason',v_row.reason);
end; $function$
;

-- function: marketing_track_checkout_v1(p_token text)
CREATE OR REPLACE FUNCTION public.marketing_track_checkout_v1(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_token text:=lower(btrim(coalesce(p_token,'')));
  v_hash text;
  v_link public.marketing_tracking_links_v1%rowtype;
begin
  if v_token !~ '^[0-9a-f]{36}$' then return jsonb_build_object('ok',false,'error','tracking_token_invalid'); end if;
  v_hash:=encode(extensions.digest(convert_to(v_token,'UTF8'),'sha256'),'hex');

  update public.marketing_tracking_links_v1
  set checkout_started_at=coalesce(checkout_started_at,now()),updated_at=now()
  where token_hash=v_hash and expires_at>=now()
  returning * into v_link;
  if not found then return jsonb_build_object('ok',false,'error','tracking_token_not_found'); end if;

  insert into public.marketing_attribution_events_v1(
    strategy_id,campaign_id,customer_id,commercial_id,public_lot_id,event_type,
    token_hash,idempotency_key,occurred_at,metadata
  ) values (
    v_link.strategy_id,v_link.campaign_id,v_link.customer_id,v_link.commercial_id,v_link.public_lot_id,'checkout_started',
    v_hash,format('tracking-checkout:%s',v_link.id),coalesce(v_link.checkout_started_at,now()),
    jsonb_build_object('dispatch_id',v_link.dispatch_id,'offer_position',v_link.offer_position)
  ) on conflict(idempotency_key) do nothing;

  return jsonb_build_object('ok',true,'strategy_id',v_link.strategy_id,'campaign_id',v_link.campaign_id,'offer_position',v_link.offer_position);
end;
$function$
;

-- function: marketing_transition_campaign_v1(p_campaign_id uuid, p_expected_revision integer, p_to_status text, p_reason text)
CREATE OR REPLACE FUNCTION public.marketing_transition_campaign_v1(p_campaign_id uuid, p_expected_revision integer, p_to_status text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_campaign public.marketing_campaigns_v1%rowtype;
  v_snapshot public.marketing_campaign_snapshots_v1%rowtype;
  v_template jsonb;
  v_from text;
  v_to text := lower(btrim(coalesce(p_to_status,'')));
begin
  select * into v_campaign from public.marketing_campaigns_v1 c where c.id=p_campaign_id for update;
  if not found then return jsonb_build_object('ok',false,'error','campaign_not_found'); end if;
  if v_campaign.revision <> p_expected_revision then return jsonb_build_object('ok',false,'error','revision_conflict','revision',v_campaign.revision); end if;
  v_from := v_campaign.status;

  if v_from='draft' and v_to='ready_for_review' then
    select * into v_snapshot from public.marketing_campaign_snapshots_v1 s where s.campaign_id=v_campaign.id and s.campaign_revision=v_campaign.revision limit 1;
    if not found then return jsonb_build_object('ok',false,'error','snapshot_stale'); end if;
    v_template := public.marketing_campaign_template_snapshot_v1(v_campaign.whatsapp_account_id,v_campaign.template_id);
    if coalesce((v_template->>'ok')::boolean,false) is not true then return jsonb_build_object('ok',false,'error','template_not_sendable'); end if;
  elsif v_from='ready_for_review' and v_to='draft' then
    null;
  elsif v_from='ready_for_review' and v_to='approved' then
    select * into v_snapshot from public.marketing_campaign_snapshots_v1 s where s.campaign_id=v_campaign.id and s.campaign_revision=v_campaign.revision limit 1;
    if not found then return jsonb_build_object('ok',false,'error','snapshot_stale'); end if;
    v_template := public.marketing_campaign_template_snapshot_v1(v_campaign.whatsapp_account_id,v_campaign.template_id);
    if coalesce((v_template->>'ok')::boolean,false) is not true then return jsonb_build_object('ok',false,'error','template_not_sendable'); end if;
  elsif v_to='cancelled' and v_from in ('draft','ready_for_review','approved') then
    null;
  else
    return jsonb_build_object('ok',false,'error','campaign_invalid_transition','from_status',v_from,'to_status',v_to);
  end if;

  update public.marketing_campaigns_v1 c set
    status=v_to,
    ready_for_review_at=case when v_to='ready_for_review' then now() when v_to='draft' then null else c.ready_for_review_at end,
    approved_at=case when v_to='approved' then now() else c.approved_at end,
    cancelled_at=case when v_to='cancelled' then now() else c.cancelled_at end,
    updated_at=now()
  where c.id=p_campaign_id returning * into v_campaign;

  insert into public.marketing_campaign_events_v1(campaign_id,event_type,campaign_revision,snapshot_id,from_status,to_status,reason)
  values(v_campaign.id,'status_changed',v_campaign.revision,v_snapshot.id,v_from,v_to,nullif(btrim(coalesce(p_reason,'')),''));

  return jsonb_build_object('ok',true,'campaign_id',v_campaign.id,'revision',v_campaign.revision,'status',v_campaign.status,'from_status',v_from);
end;
$function$
;

-- function: marketing_update_campaign_draft_v1(p_campaign_id uuid, p_expected_revision integer, p_patch jsonb)
CREATE OR REPLACE FUNCTION public.marketing_update_campaign_draft_v1(p_campaign_id uuid, p_expected_revision integer, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_campaign public.marketing_campaigns_v1%rowtype;
  v_unsupported text;
  v_name text;
  v_account uuid;
  v_template_id uuid;
  v_filters jsonb;
  v_variables jsonb;
  v_deep_link jsonb;
  v_notes text;
  v_semantic_changed boolean;
  v_template jsonb;
begin
  if jsonb_typeof(coalesce(p_patch,'{}'::jsonb)) <> 'object' then return jsonb_build_object('ok',false,'error','invalid_patch'); end if;
  select k into v_unsupported from jsonb_object_keys(coalesce(p_patch,'{}'::jsonb)) k
  where k <> all(array['name','whatsapp_account_id','template_id','filters','variable_values','deep_link','notes']::text[]) limit 1;
  if v_unsupported is not null then return jsonb_build_object('ok',false,'error','unsupported_patch','field',v_unsupported); end if;

  select * into v_campaign from public.marketing_campaigns_v1 c where c.id=p_campaign_id for update;
  if not found then return jsonb_build_object('ok',false,'error','campaign_not_found'); end if;
  if v_campaign.revision <> p_expected_revision then return jsonb_build_object('ok',false,'error','revision_conflict','revision',v_campaign.revision); end if;
  if v_campaign.status <> 'draft' then return jsonb_build_object('ok',false,'error','campaign_not_draft'); end if;

  begin
    v_name := case when p_patch ? 'name' then nullif(btrim(p_patch->>'name'),'') else v_campaign.name end;
    v_account := case when p_patch ? 'whatsapp_account_id' then (p_patch->>'whatsapp_account_id')::uuid else v_campaign.whatsapp_account_id end;
    v_template_id := case when p_patch ? 'template_id' then (p_patch->>'template_id')::uuid else v_campaign.template_id end;
  exception when others then return jsonb_build_object('ok',false,'error','invalid_patch'); end;
  if v_name is null then return jsonb_build_object('ok',false,'error','invalid_name'); end if;
  v_filters := case when p_patch ? 'filters' then p_patch->'filters' else v_campaign.filters end;
  v_variables := case when p_patch ? 'variable_values' then p_patch->'variable_values' else v_campaign.variable_values end;
  v_deep_link := case when p_patch ? 'deep_link' then p_patch->'deep_link' else v_campaign.deep_link end;
  v_notes := case when p_patch ? 'notes' then p_patch->>'notes' else v_campaign.notes end;
  if jsonb_typeof(coalesce(v_filters,'{}'::jsonb)) <> 'object' or jsonb_typeof(coalesce(v_variables,'{}'::jsonb)) <> 'object' or jsonb_typeof(coalesce(v_deep_link,'{}'::jsonb)) <> 'object' then
    return jsonb_build_object('ok',false,'error','invalid_patch');
  end if;

  v_semantic_changed := v_account is distinct from v_campaign.whatsapp_account_id
    or v_template_id is distinct from v_campaign.template_id
    or v_filters is distinct from v_campaign.filters
    or v_variables is distinct from v_campaign.variable_values
    or v_deep_link is distinct from v_campaign.deep_link;

  if v_semantic_changed then
    v_template := public.marketing_campaign_template_snapshot_v1(v_account,v_template_id);
    if coalesce((v_template->>'ok')::boolean,false) is not true then return v_template; end if;
    begin perform * from public.marketing_audience_candidates_v2(v_filters) limit 1;
    exception when others then return jsonb_build_object('ok',false,'error','invalid_filters','detail',sqlerrm); end;
  else
    v_template := jsonb_build_object('name',v_campaign.template_name_snapshot,'language',v_campaign.template_language_snapshot,'category',v_campaign.template_category_snapshot,'components',v_campaign.template_components_snapshot);
  end if;

  update public.marketing_campaigns_v1 c set
    name=v_name,
    whatsapp_account_id=v_account,
    template_id=v_template_id,
    filters=v_filters,
    variable_values=v_variables,
    deep_link=v_deep_link,
    notes=v_notes,
    revision=case when v_semantic_changed then c.revision+1 else c.revision end,
    template_name_snapshot=coalesce(v_template->>'name',c.template_name_snapshot),
    template_language_snapshot=coalesce(v_template->>'language',c.template_language_snapshot),
    template_category_snapshot=coalesce(v_template->>'category',c.template_category_snapshot),
    template_components_snapshot=coalesce(v_template->'components',c.template_components_snapshot),
    updated_at=now()
  where c.id=p_campaign_id
  returning * into v_campaign;

  insert into public.marketing_campaign_events_v1(campaign_id,event_type,campaign_revision,from_status,to_status,metadata)
  values(v_campaign.id,'draft_updated',v_campaign.revision,'draft','draft',jsonb_build_object('semantic_changed',v_semantic_changed));

  return jsonb_build_object('ok',true,'campaign_id',v_campaign.id,'revision',v_campaign.revision,'status',v_campaign.status,'semantic_changed',v_semantic_changed);
end;
$function$
;

-- function: merge_bling_hub_runtime_metadata_v2(p_patch jsonb)
CREATE OR REPLACE FUNCTION public.merge_bling_hub_runtime_metadata_v2(p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_metadata jsonb;
begin
  update public.bling_hub_runtime_v2
  set metadata=coalesce(metadata,'{}'::jsonb)||coalesce(p_patch,'{}'::jsonb),
      updated_at=now()
  where id=1
  returning metadata into v_metadata;

  if v_metadata is null then
    raise exception 'bling_hub_runtime_missing';
  end if;
  return v_metadata;
end
$function$
;

-- function: meta_catalog_product_link_admin_save_v1(p_whatsapp_account_id uuid, p_catalog_id text, p_product_retailer_id text, p_product_id uuid, p_link_id uuid)
CREATE OR REPLACE FUNCTION public.meta_catalog_product_link_admin_save_v1(p_whatsapp_account_id uuid, p_catalog_id text, p_product_retailer_id text, p_product_id uuid, p_link_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_role text;
  v_is_active boolean;
  v_link_id uuid;
  v_catalog_id text := nullif(btrim(coalesce(p_catalog_id, '')), '');
  v_retailer_id text := nullif(btrim(coalesce(p_product_retailer_id, '')), '');
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'error', 'admin_not_authorized');
  end if;
  if p_whatsapp_account_id is null
    or p_product_id is null
    or length(coalesce(v_catalog_id, '')) not between 1 and 256
    or length(coalesce(v_retailer_id, '')) not between 1 and 256
    or v_catalog_id ~ '[[:cntrl:]]'
    or v_retailer_id ~ '[[:cntrl:]]' then
    return jsonb_build_object('ok', false, 'error', 'invalid_mapping');
  end if;

  select u.role, u.is_active
  into v_role, v_is_active
  from public.admin_users u
  where u.user_id = auth.uid();
  if not found
    or v_is_active is distinct from true
    or coalesce(v_role, '') not in ('owner', 'admin', 'catalog_manager') then
    return jsonb_build_object('ok', false, 'error', 'admin_not_authorized');
  end if;

  perform 1
  from public.whatsapp_accounts a
  where a.id = p_whatsapp_account_id and a.is_active = true
  for share;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'whatsapp_account_unavailable');
  end if;

  perform 1
  from public.products p
  where p.id = p_product_id and p.is_active = true
  for share;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'whatsapp_product_unavailable');
  end if;

  if p_link_id is null then
    insert into whatsapp_ordering_private.meta_catalog_product_links_v1 (
      whatsapp_account_id, catalog_id, product_retailer_id, product_id,
      status, verified_at, updated_at
    ) values (
      p_whatsapp_account_id, v_catalog_id, v_retailer_id, p_product_id,
      'needs_review', null, now()
    )
    returning id into v_link_id;
  else
    update whatsapp_ordering_private.meta_catalog_product_links_v1
    set whatsapp_account_id = p_whatsapp_account_id,
        catalog_id = v_catalog_id,
        product_retailer_id = v_retailer_id,
        product_id = p_product_id,
        status = 'needs_review',
        verified_at = null,
        updated_at = now()
    where id = p_link_id
    returning id into v_link_id;
    if v_link_id is null then
      return jsonb_build_object('ok', false, 'error', 'mapping_not_found');
    end if;
  end if;

  return jsonb_build_object('ok', true, 'id', v_link_id, 'status', 'needs_review');
exception
  when unique_violation then
    return jsonb_build_object('ok', false, 'error', 'mapping_already_exists');
end;
$function$
;

-- function: meta_catalog_product_links_activate_batch_v1(p_whatsapp_account_id uuid, p_waba_id text, p_catalog_id text, p_verified_links jsonb)
CREATE OR REPLACE FUNCTION public.meta_catalog_product_links_activate_batch_v1(p_whatsapp_account_id uuid, p_waba_id text, p_catalog_id text, p_verified_links jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_catalog_id text := nullif(btrim(coalesce(p_catalog_id, '')), '');
  v_expected integer;
  v_activated integer;
begin
  if p_whatsapp_account_id is null
    or coalesce(p_waba_id, '') !~ '^[0-9]{1,256}$'
    or length(coalesce(v_catalog_id, '')) not between 1 and 256
    or v_catalog_id !~ '^[0-9]{1,256}$' then
    return jsonb_build_object('ok', false, 'error', 'invalid_verification_result');
  end if;

  if jsonb_typeof(p_verified_links) is distinct from 'array' then
    return jsonb_build_object('ok', false, 'error', 'invalid_verification_result');
  end if;

  if jsonb_array_length(p_verified_links) > 200 then
    return jsonb_build_object('ok', false, 'error', 'invalid_verification_result');
  end if;

  v_expected := jsonb_array_length(p_verified_links);
  if v_expected = 0 then
    return jsonb_build_object('ok', true, 'activated_count', 0);
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_verified_links) item(value)
    where jsonb_typeof(item.value) is distinct from 'object'
      or coalesce(item.value ->> 'id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      or coalesce(item.value ->> 'product_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      or length(coalesce(item.value ->> 'product_retailer_id', '')) not between 1 and 256
      or coalesce(item.value ->> 'product_retailer_id', '') ~ '[[:cntrl:]]'
      or coalesce(item.value ->> 'updated_at', '') = ''
  ) then
    return jsonb_build_object('ok', false, 'error', 'invalid_verification_result');
  end if;

  if (
    select count(distinct item.value ->> 'id')
    from jsonb_array_elements(p_verified_links) item(value)
  ) <> v_expected then
    return jsonb_build_object('ok', false, 'error', 'duplicate_verification_result');
  end if;

  perform 1
  from public.whatsapp_accounts a
  where a.id = p_whatsapp_account_id
    and a.waba_id = p_waba_id
    and a.is_active = true
  for share;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'whatsapp_account_changed');
  end if;

  with verified_rows as (
    select *
    from jsonb_to_recordset(p_verified_links) as item(
      id uuid,
      product_retailer_id text,
      product_id uuid,
      updated_at timestamptz
    )
  ),
  updated_rows as (
    update whatsapp_ordering_private.meta_catalog_product_links_v1 l
    set status = 'active',
        verified_at = now(),
        updated_at = now()
    from verified_rows item
    join public.products p
      on p.id = item.product_id
      and p.is_active = true
    where l.id = item.id
      and l.whatsapp_account_id = p_whatsapp_account_id
      and l.catalog_id = v_catalog_id
      and l.product_retailer_id = item.product_retailer_id
      and l.product_id = item.product_id
      and l.updated_at = item.updated_at
      and l.status = 'needs_review'
    returning l.id
  )
  select count(*)::integer into v_activated from updated_rows;

  if v_activated <> v_expected then
    raise exception using
      errcode = '40001',
      message = 'catalog_verification_snapshot_changed';
  end if;

  return jsonb_build_object('ok', true, 'activated_count', v_activated);
end;
$function$
;

-- function: meta_catalog_product_links_admin_list_v1(p_limit integer, p_query text, p_link_id uuid)
CREATE OR REPLACE FUNCTION public.meta_catalog_product_links_admin_list_v1(p_limit integer DEFAULT 100, p_query text DEFAULT NULL::text, p_link_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_role text;
  v_is_active boolean;
  v_accounts jsonb;
  v_items jsonb;
  v_query text := nullif(btrim(coalesce(p_query, '')), '');
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'error', 'admin_not_authorized');
  end if;
  if p_limit is null or p_limit < 1 or p_limit > 200
    or length(coalesce(v_query, '')) > 100 then
    return jsonb_build_object('ok', false, 'error', 'invalid_query');
  end if;

  select u.role, u.is_active
  into v_role, v_is_active
  from public.admin_users u
  where u.user_id = auth.uid();
  if not found
    or v_is_active is distinct from true
    or coalesce(v_role, '') not in ('owner', 'admin', 'catalog_manager') then
    return jsonb_build_object('ok', false, 'error', 'admin_not_authorized');
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', a.id,
        'slug', a.slug,
        'name', a.display_name,
        'phone_e164', a.phone_e164
      ) order by a.display_name, a.id
    ),
    '[]'::jsonb
  )
  into v_accounts
  from public.whatsapp_accounts a
  where a.is_active = true;

  select coalesce(
    jsonb_agg(page.item order by page.review_priority, page.updated_at desc, page.id desc),
    '[]'::jsonb
  )
  into v_items
  from (
    select
      l.id,
      l.updated_at,
      case
        when l.status = 'needs_review' and p.is_active then 0
        when l.status = 'needs_review' then 1
        else 2
      end as review_priority,
      jsonb_build_object(
        'id', l.id,
        'whatsapp_account_id', l.whatsapp_account_id,
        'account_name', a.display_name,
        'account_phone', a.phone_e164,
        'catalog_id', l.catalog_id,
        'product_retailer_id', l.product_retailer_id,
        'product_id', p.id,
        'product_name', p.name,
        'product_sku', p.sku,
        'status', l.status,
        'verified_at', l.verified_at,
        'updated_at', l.updated_at,
        'product_eligible', p.is_active
      ) as item
    from whatsapp_ordering_private.meta_catalog_product_links_v1 l
    join public.whatsapp_accounts a on a.id = l.whatsapp_account_id
    join public.products p on p.id = l.product_id
    where (p_link_id is null or l.id = p_link_id)
      and (
        v_query is null
        or l.catalog_id ilike '%' || v_query || '%'
        or l.product_retailer_id ilike '%' || v_query || '%'
        or p.name ilike '%' || v_query || '%'
        or coalesce(p.sku, '') ilike '%' || v_query || '%'
      )
    order by review_priority, l.updated_at desc, l.id desc
    limit p_limit
  ) page;

  return jsonb_build_object(
    'ok', true,
    'accounts', v_accounts,
    'items', v_items
  );
end;
$function$
;

-- function: meta_catalog_product_links_verification_candidates_v1(p_whatsapp_account_id uuid, p_catalog_id text, p_after_updated_at timestamp with time zone, p_after_id uuid)
CREATE OR REPLACE FUNCTION public.meta_catalog_product_links_verification_candidates_v1(p_whatsapp_account_id uuid, p_catalog_id text, p_after_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_after_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_catalog_id text := nullif(btrim(coalesce(p_catalog_id, '')), '');
  v_account jsonb;
  v_links jsonb;
  v_has_more boolean;
  v_next_cursor jsonb;
begin
  if p_whatsapp_account_id is null
    or length(coalesce(v_catalog_id, '')) not between 1 and 256
    or v_catalog_id !~ '^[0-9]{1,256}$' then
    return jsonb_build_object('ok', false, 'error', 'invalid_catalog_request');
  end if;

  if (p_after_updated_at is null) <> (p_after_id is null) then
    return jsonb_build_object('ok', false, 'error', 'invalid_catalog_cursor');
  end if;

  select jsonb_build_object(
    'id', a.id,
    'slug', a.slug,
    'waba_id', a.waba_id
  )
  into v_account
  from public.whatsapp_accounts a
  where a.id = p_whatsapp_account_id
    and a.is_active = true
    and a.waba_id ~ '^[0-9]{1,256}$'
  for share;

  if v_account is null then
    return jsonb_build_object('ok', false, 'error', 'whatsapp_account_unavailable');
  end if;

  with candidate_rows as (
    select
      l.id,
      l.product_retailer_id,
      l.product_id,
      l.updated_at
    from whatsapp_ordering_private.meta_catalog_product_links_v1 l
    join public.products p on p.id = l.product_id
    where l.whatsapp_account_id = p_whatsapp_account_id
      and l.catalog_id = v_catalog_id
      and l.status = 'needs_review'
      and p.is_active = true
      and (
        p_after_updated_at is null
        or (l.updated_at, l.id) > (p_after_updated_at, p_after_id)
      )
    order by l.updated_at, l.id
    limit 201
  ),
  limited_rows as (
    select *
    from candidate_rows
    order by updated_at, id
    limit 200
  )
  select
    coalesce(
      jsonb_agg(jsonb_build_object(
        'id', limited_rows.id,
        'product_retailer_id', limited_rows.product_retailer_id,
        'product_id', limited_rows.product_id,
        'updated_at', limited_rows.updated_at
      ) order by limited_rows.updated_at, limited_rows.id),
      '[]'::jsonb
    ),
    (select count(*) > 200 from candidate_rows)
  into v_links, v_has_more
  from limited_rows;

  if coalesce(v_has_more, false) then
    select jsonb_build_object(
      'updated_at', item.value ->> 'updated_at',
      'id', item.value ->> 'id'
    )
    into v_next_cursor
    from jsonb_array_elements(v_links) with ordinality item(value, ordinal)
    order by item.ordinal desc
    limit 1;
  end if;

  return jsonb_build_object(
    'ok', true,
    'account', v_account,
    'links', v_links,
    'has_more', coalesce(v_has_more, false),
    'next_cursor', v_next_cursor
  );
end;
$function$
;

-- function: normalize_local_delivery_city_v1(p_city text)
CREATE OR REPLACE FUNCTION public.normalize_local_delivery_city_v1(p_city text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select case translate(lower(trim(coalesce(p_city,''))),'áàãâéêíóôõúç','aaaaeeiooouc')
    when 'cuiaba' then 'Cuiabá'
    when 'varzea grande' then 'Várzea Grande'
    else null end
$function$
;

-- function: normalize_phone_digits(p_phone text)
CREATE OR REPLACE FUNCTION public.normalize_phone_digits(p_phone text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select regexp_replace(coalesce(p_phone,''), '[^0-9]', '', 'g');
$function$
;

-- function: normalize_storefront_phone_v2(p_phone text)
CREATE OR REPLACE FUNCTION public.normalize_storefront_phone_v2(p_phone text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare v text;
begin
  v:=public.canonical_whatsapp_e164_br_v2(p_phone);
  if v is null then raise exception using errcode='22023',message='invalid_phone'; end if;
  return v;
end;
$function$
;

-- function: ops2_accept_order_whatsapp_meta_v1(p_outbox_id uuid, p_provider_message_id text, p_accepted_at timestamp with time zone)
CREATE OR REPLACE FUNCTION public.ops2_accept_order_whatsapp_meta_v1(p_outbox_id uuid, p_provider_message_id text, p_accepted_at timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_outbox public.ops2_whatsapp_outbox_v1%rowtype;
  v_message public.whatsapp_messages_v1%rowtype;
  v_provider_message_id text:=btrim(coalesce(p_provider_message_id,''));
  v_accepted_at timestamptz:=coalesce(p_accepted_at,now());
  v_conversation_id uuid;
  v_resolved jsonb;
  v_status_result jsonb;
  v_status text;
  v_occurred_at timestamptz;
  v_replayed integer:=0;
  v_sender_kind text;
  r public.whatsapp_webhook_events_v1%rowtype;
begin
  if p_outbox_id is null then return jsonb_build_object('ok',false,'error','outbox_required'); end if;
  if v_provider_message_id not like 'wamid.%' or char_length(v_provider_message_id)>500 or v_provider_message_id ~ '[[:cntrl:][:space:]]' then
    return jsonb_build_object('ok',false,'error','provider_message_id_invalid');
  end if;

  select q.* into v_outbox
  from public.ops2_whatsapp_outbox_v1 q
  where q.id=p_outbox_id
  for update;
  if not found then return jsonb_build_object('ok',false,'error','outbox_not_found'); end if;
  if v_outbox.delivery_mode<>'utility_template' or v_outbox.message_kind<>'order_received' then
    return jsonb_build_object('ok',false,'error','outbox_not_order_template');
  end if;
  if v_outbox.whatsapp_account_id is null or nullif(btrim(coalesce(v_outbox.phone_e164,'')),'') is null then
    return jsonb_build_object('ok',false,'error','outbox_route_incomplete');
  end if;

  if v_outbox.status='sent' then
    if v_outbox.external_message_id is distinct from v_provider_message_id then
      return jsonb_build_object('ok',false,'error','already_sent_mismatch');
    end if;
    return jsonb_build_object(
      'ok',true,'already_accepted',true,'idempotent',true,'outbox_id',v_outbox.id,
      'message_id',nullif(v_outbox.payload->>'canonical_message_id','')::uuid,
      'provider_message_id',v_outbox.external_message_id,'status','sent'
    );
  end if;
  if v_outbox.status<>'sending' then
    return jsonb_build_object('ok',false,'error','outbox_not_sending','status',v_outbox.status);
  end if;

  v_conversation_id:=v_outbox.conversation_id;
  if v_conversation_id is null then
    v_resolved:=public.whatsapp_resolve_conversation_v1(
      v_outbox.whatsapp_account_id,
      v_outbox.phone_e164,
      v_outbox.customer_id,
      'website'
    );
    if coalesce((v_resolved->>'ok')::boolean,false) is not true then
      return jsonb_build_object('ok',false,'error','conversation_resolve_failed','detail',v_resolved);
    end if;
    v_conversation_id:=nullif(v_resolved->>'conversation_id','')::uuid;
    if v_conversation_id is null then return jsonb_build_object('ok',false,'error','conversation_resolve_empty'); end if;
    update public.ops2_whatsapp_outbox_v1 set conversation_id=v_conversation_id,updated_at=now() where id=v_outbox.id;
  end if;

  v_sender_kind:=case when coalesce(v_outbox.payload#>>'{meta_request,dispatch_scope}','checkout_auto')='admin_manual' then 'human' else 'automation' end;

  select m.* into v_message
  from public.whatsapp_messages_v1 m
  where m.whatsapp_account_id=v_outbox.whatsapp_account_id
    and m.provider_message_id=v_provider_message_id
  order by case when m.provider='meta' then 0 else 1 end,m.created_at,m.id
  limit 1
  for update;

  if found then
    if v_message.conversation_id is distinct from v_conversation_id then return jsonb_build_object('ok',false,'error','wamid_conversation_conflict'); end if;
    if v_message.direction<>'outbound' then return jsonb_build_object('ok',false,'error','wamid_direction_conflict'); end if;
    update public.whatsapp_messages_v1 m set
      provider='meta',
      customer_id=coalesce(m.customer_id,v_outbox.customer_id),
      message_type='template',
      status_current=case when m.status_current in ('sent','delivered','read','failed','cancelled') then m.status_current else 'accepted' end,
      sender_kind=v_sender_kind,
      sent_at=coalesce(m.sent_at,v_accepted_at),
      metadata=coalesce(m.metadata,'{}'::jsonb)||jsonb_build_object(
        'source','order_confirmation','transport','meta_cloud_api','order_outbox_id',v_outbox.id,
        'order_id',v_outbox.order_id,'meta_acceptance','accepted','meta_accepted_at',v_accepted_at,
        'template_name',v_outbox.payload#>>'{meta_request,template_name}',
        'template_language',v_outbox.payload#>>'{meta_request,language_code}',
        'promoted_from_shadow',v_message.provider='papoai'
      )
    where m.id=v_message.id
    returning * into v_message;
  else
    begin
      insert into public.whatsapp_messages_v1(
        conversation_id,whatsapp_account_id,customer_id,direction,message_type,provider,provider_message_id,
        provider_conversation_id,text_body,status_current,sender_kind,sender_ref,sent_at,metadata
      ) values (
        v_conversation_id,v_outbox.whatsapp_account_id,v_outbox.customer_id,'outbound','template','meta',v_provider_message_id,
        null,null,'accepted',v_sender_kind,null,v_accepted_at,
        jsonb_build_object(
          'source','order_confirmation','transport','meta_cloud_api','order_outbox_id',v_outbox.id,
          'order_id',v_outbox.order_id,'meta_acceptance','accepted','meta_accepted_at',v_accepted_at,
          'template_name',v_outbox.payload#>>'{meta_request,template_name}',
          'template_language',v_outbox.payload#>>'{meta_request,language_code}'
        )
      ) returning * into v_message;
    exception when unique_violation then
      select m.* into v_message
      from public.whatsapp_messages_v1 m
      where m.whatsapp_account_id=v_outbox.whatsapp_account_id and m.provider='meta' and m.provider_message_id=v_provider_message_id
      limit 1 for update;
      if not found then raise; end if;
      if v_message.conversation_id is distinct from v_conversation_id or v_message.direction<>'outbound' then
        return jsonb_build_object('ok',false,'error','wamid_race_conflict');
      end if;
    end;
  end if;

  update public.ops2_whatsapp_outbox_v1 set
    conversation_id=v_conversation_id,
    status='sent',
    external_message_id=v_provider_message_id,
    sent_at=v_accepted_at,
    last_error=null,
    locked_at=null,
    payload=coalesce(payload,'{}'::jsonb)||jsonb_build_object(
      'provider','meta','canonical_message_id',v_message.id,'meta_accepted_at',v_accepted_at
    ),
    updated_at=now()
  where id=v_outbox.id;

  update public.conversations set
    last_outbound_at=greatest(coalesce(last_outbound_at,'-infinity'::timestamptz),v_accepted_at),
    last_human_message_at=case when v_sender_kind='human' then greatest(coalesce(last_human_message_at,'-infinity'::timestamptz),v_accepted_at) else last_human_message_at end,
    updated_at=greatest(updated_at,v_accepted_at)
  where id=v_conversation_id;

  v_status_result:=public.whatsapp_record_status_v1(
    v_outbox.whatsapp_account_id,'meta',v_provider_message_id,'accepted',v_accepted_at,now(),
    null,null,null,jsonb_build_object('source','order_confirmation_send_response','order_outbox_id',v_outbox.id,'order_id',v_outbox.order_id)
  );
  if coalesce((v_status_result->>'ok')::boolean,false) is not true then
    raise exception using
      errcode='P0001',
      message='accepted_status_record_failed:'||left(coalesce(v_status_result::text,'{}'),400);
  end if;

  for r in
    select e.* from public.whatsapp_webhook_events_v1 e
    where e.whatsapp_account_id=v_outbox.whatsapp_account_id
      and e.provider='meta'
      and e.provider_message_id=v_provider_message_id
      and e.event_type like 'message.status.%'
      and e.status='received'
    order by e.received_at,e.id
    for update
  loop
    v_status:=split_part(r.event_type,'.',3);
    if v_status not in ('sent','delivered','read','failed','cancelled') then
      update public.whatsapp_webhook_events_v1 set status='ignored',processed_at=now(),last_error='status_not_supported_for_replay' where id=r.id;
      continue;
    end if;
    v_occurred_at:=case when coalesce(r.payload->>'timestamp','') ~ '^\d+(\.\d+)?$' then to_timestamp((r.payload->>'timestamp')::double precision) else r.received_at end;
    v_status_result:=public.whatsapp_record_status_v1(
      v_outbox.whatsapp_account_id,'meta',v_provider_message_id,v_status,v_occurred_at,r.received_at,
      nullif(r.payload->'errors'->0->>'code',''),nullif(r.payload->'errors'->0->>'title',''),
      nullif(coalesce(r.payload->'errors'->0->>'message',r.payload->'errors'->0->'error_data'->>'details'),''),r.payload
    );
    if coalesce((v_status_result->>'ok')::boolean,false) is true then
      update public.whatsapp_webhook_events_v1 set status='normalized',processed_at=now(),last_error=null where id=r.id;
      v_replayed:=v_replayed+1;
    else
      update public.whatsapp_webhook_events_v1 set status='review_required',processed_at=now(),last_error=left(coalesce(v_status_result->>'error','status_replay_failed'),500) where id=r.id;
    end if;
  end loop;

  return jsonb_build_object(
    'ok',true,'already_accepted',false,'idempotent',false,'outbox_id',v_outbox.id,
    'message_id',v_message.id,'conversation_id',v_conversation_id,'provider_message_id',v_provider_message_id,
    'status_current',(select m.status_current from public.whatsapp_messages_v1 m where m.id=v_message.id),
    'pending_statuses_replayed',v_replayed,'status','sent'
  );
end;
$function$
;

-- function: ops2_activate_bling_stock_authority_v1()
CREATE OR REPLACE FUNCTION public.ops2_activate_bling_stock_authority_v1()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ select jsonb_build_object('ok',false,'error','supabase_stock_authority_fixed','authority','supabase'); $function$
;

-- function: ops2_admin_ana_customer_profile_context_v1(p_conversation_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_admin_ana_customer_profile_context_v1(p_conversation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_access jsonb:=public.ops2_admin_attendance_customer_access_v1(false);
  v_conversation public.conversations%rowtype;
  v_resolution jsonb;
  v_customer_id uuid;
  v_customer public.customers%rowtype;
  v_email text;
  v_address public.customer_addresses%rowtype;
  v_messages jsonb:='[]'::jsonb;
  v_missing text[]:=array[]::text[];
begin
  if coalesce((v_access->>'ok')::boolean,false) is not true then return v_access; end if;
  if p_conversation_id is null then return jsonb_build_object('ok',false,'error','invalid_conversation_id'); end if;

  select * into v_conversation from public.conversations where id=p_conversation_id;
  if not found then return jsonb_build_object('ok',false,'error','conversation_not_found'); end if;

  v_resolution:=public.resolve_customer_by_phone_v1(v_conversation.wa_contact_e164);
  if coalesce(v_resolution->>'match_status','')='ambiguous' then
    return jsonb_build_object('ok',false,'error','ambiguous_phone','match_status','ambiguous','candidate_count',coalesce((v_resolution->>'candidate_count')::int,0));
  end if;

  v_customer_id:=v_conversation.customer_id;
  if v_customer_id is null and v_resolution->>'match_status'='matched' then
    v_customer_id:=(v_resolution->>'customer_id')::uuid;
  elsif v_customer_id is not null and v_resolution->>'match_status'='matched' and (v_resolution->>'customer_id')::uuid<>v_customer_id then
    return jsonb_build_object('ok',false,'error','customer_identity_conflict');
  end if;

  if v_customer_id is not null then
    select * into v_customer from public.customers where id=v_customer_id;
    select e.email into v_email from public.customer_emails e where e.customer_id=v_customer_id order by e.is_primary desc,e.updated_at desc limit 1;
    select * into v_address from public.customer_addresses a where a.customer_id=v_customer_id and a.is_active=true order by a.is_default desc,a.updated_at desc limit 1;
  end if;

  if v_customer_id is null or nullif(btrim(coalesce(v_customer.name,'')),'') is null then v_missing:=array_append(v_missing,'name'); end if;
  if v_customer_id is null or nullif(regexp_replace(coalesce(v_customer.cpf_cnpj,''),'\D','','g'),'') is null then v_missing:=array_append(v_missing,'cpf_cnpj'); end if;
  if nullif(btrim(coalesce(v_email,'')),'') is null then v_missing:=array_append(v_missing,'email'); end if;
  if nullif(btrim(coalesce(v_address.postal_code,'')),'') is null then v_missing:=array_append(v_missing,'postal_code'); end if;
  if nullif(btrim(coalesce(v_address.street,'')),'') is null then v_missing:=array_append(v_missing,'street'); end if;
  if nullif(btrim(coalesce(v_address.number,'')),'') is null then v_missing:=array_append(v_missing,'number'); end if;
  if nullif(btrim(coalesce(v_address.neighborhood,'')),'') is null then v_missing:=array_append(v_missing,'neighborhood'); end if;
  if nullif(btrim(coalesce(v_address.city,'')),'') is null then v_missing:=array_append(v_missing,'city'); end if;
  if nullif(btrim(coalesce(v_address.state,'')),'') is null then v_missing:=array_append(v_missing,'state'); end if;

  select coalesce(jsonb_agg(jsonb_build_object(
      'id',m.id,'direction',m.direction,'text',m.text_body,'sender_kind',m.sender_kind,
      'timestamp',coalesce(m.received_at,m.sent_at,m.created_at)
    ) order by m.created_at),'[]'::jsonb)
    into v_messages
  from (
    select w.id,w.direction,w.text_body,w.sender_kind,w.received_at,w.sent_at,w.created_at
    from public.whatsapp_messages_v1 w
    where w.conversation_id=p_conversation_id
      and w.message_type='text'
      and nullif(btrim(coalesce(w.text_body,'')),'') is not null
    order by w.created_at desc
    limit 30
  ) m;

  return jsonb_build_object(
    'ok',true,
    'conversation_id',v_conversation.id,
    'conversation_phone_e164',public.canonical_whatsapp_e164_br_v2(v_conversation.wa_contact_e164),
    'customer_id',v_customer_id,
    'match_status',coalesce(v_resolution->>'match_status','invalid'),
    'missing_fields',to_jsonb(v_missing),
    'current_profile',jsonb_build_object(
      'name',case when v_customer_id is null then null else nullif(btrim(v_customer.name),'') end,
      'cpf_cnpj_present',v_customer_id is not null and nullif(regexp_replace(coalesce(v_customer.cpf_cnpj,''),'\D','','g'),'') is not null,
      'email',nullif(btrim(coalesce(v_email,'')),''),
      'address',case when v_address.id is null then null else jsonb_build_object(
        'postal_code',v_address.postal_code,'street',v_address.street,'number',v_address.number,
        'complement',v_address.complement,'neighborhood',v_address.neighborhood,'city',v_address.city,
        'state',v_address.state,'reference',v_address.reference
      ) end
    ),
    'messages',v_messages
  );
end;
$function$
;

-- function: ops2_admin_ana_customer_profile_extract_access_v1()
CREATE OR REPLACE FUNCTION public.ops2_admin_ana_customer_profile_extract_access_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  return public.ops2_admin_attendance_customer_access_v1(true);
end;
$function$
;

-- function: ops2_admin_ana_customer_profile_metrics_v1()
CREATE OR REPLACE FUNCTION public.ops2_admin_ana_customer_profile_metrics_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_access jsonb:=public.ops2_admin_attendance_customer_access_v1(false);
  v_total bigint;
  v_pending bigint;
  v_accepted bigint;
  v_rejected bigint;
  v_by_field jsonb;
begin
  if coalesce((v_access->>'ok')::boolean,false) is not true then return v_access; end if;

  select count(*),
         count(*) filter(where status='pending'),
         count(*) filter(where status='reviewed_accepted'),
         count(*) filter(where status='reviewed_rejected')
    into v_total,v_pending,v_accepted,v_rejected
  from public.customer_profile_suggestions_v1;

  select coalesce(jsonb_agg(jsonb_build_object(
    'field_name',x.field_name,
    'total',x.total,
    'pending',x.pending,
    'accepted',x.accepted,
    'rejected',x.rejected,
    'acceptance_rate',case when (x.accepted+x.rejected)>0 then round(x.accepted::numeric/(x.accepted+x.rejected),4) else null end
  ) order by x.field_name),'[]'::jsonb)
  into v_by_field
  from (
    select field_name,count(*) total,
           count(*) filter(where status='pending') pending,
           count(*) filter(where status='reviewed_accepted') accepted,
           count(*) filter(where status='reviewed_rejected') rejected
    from public.customer_profile_suggestions_v1
    group by field_name
  ) x;

  return jsonb_build_object(
    'ok',true,'total',v_total,'pending',v_pending,'accepted',v_accepted,'rejected',v_rejected,
    'acceptance_rate',case when (v_accepted+v_rejected)>0 then round(v_accepted::numeric/(v_accepted+v_rejected),4) else null end,
    'by_field',v_by_field
  );
end;
$function$
;

-- function: ops2_admin_ana_customer_profile_review_v1(p_suggestion_id uuid, p_outcome text)
CREATE OR REPLACE FUNCTION public.ops2_admin_ana_customer_profile_review_v1(p_suggestion_id uuid, p_outcome text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_access jsonb:=public.ops2_admin_attendance_customer_access_v1(true);
  v_suggestion public.customer_profile_suggestions_v1%rowtype;
  v_outcome text:=lower(btrim(coalesce(p_outcome,'')));
  v_target_status text;
  v_user_id uuid:=auth.uid();
  v_doc text;
  v_other_customer uuid;
begin
  if coalesce((v_access->>'ok')::boolean,false) is not true then return v_access; end if;
  if p_suggestion_id is null then return jsonb_build_object('ok',false,'error','suggestion_required'); end if;
  if v_outcome not in ('accepted','rejected') then return jsonb_build_object('ok',false,'error','review_outcome_invalid'); end if;

  v_target_status:=case when v_outcome='accepted' then 'reviewed_accepted' else 'reviewed_rejected' end;

  select * into v_suggestion
  from public.customer_profile_suggestions_v1
  where id=p_suggestion_id
  for update;
  if not found then return jsonb_build_object('ok',false,'error','suggestion_not_found'); end if;

  if v_suggestion.status=v_target_status then
    return jsonb_build_object('ok',true,'suggestion_id',v_suggestion.id,'status',v_suggestion.status,'idempotent',true);
  end if;
  if v_suggestion.status<>'pending' then
    return jsonb_build_object('ok',false,'error','suggestion_already_reviewed','status',v_suggestion.status);
  end if;

  if v_outcome='accepted' and v_suggestion.recommendation='ignore' then
    return jsonb_build_object('ok',false,'error','suggestion_not_usable');
  end if;

  if v_outcome='accepted' and v_suggestion.field_name='cpf_cnpj' then
    v_doc:=regexp_replace(coalesce(v_suggestion.normalized_value,''),'[^0-9]','','g');
    if public.ops2_valid_cpf_cnpj_v1(v_doc) is not true then
      return jsonb_build_object('ok',false,'error','invalid_cpf_cnpj');
    end if;

    select c.id into v_other_customer
    from public.customers c
    where regexp_replace(coalesce(c.cpf_cnpj,''),'[^0-9]','','g')=v_doc
      and (v_suggestion.customer_id is null or c.id<>v_suggestion.customer_id)
    limit 1;
    if found then
      return jsonb_build_object('ok',false,'error','cpf_cnpj_belongs_to_other_customer');
    end if;
  end if;

  update public.customer_profile_suggestions_v1
  set status=case when v_outcome='accepted' then 'reviewed_accepted' else 'reviewed_rejected' end,
      reviewed_by_admin_user_id=v_user_id,
      reviewed_at=now(),
      updated_at=now()
  where id=p_suggestion_id
  returning * into v_suggestion;

  return jsonb_build_object(
    'ok',true,
    'suggestion_id',v_suggestion.id,
    'conversation_id',v_suggestion.conversation_id,
    'field_name',v_suggestion.field_name,
    'status',v_suggestion.status,
    'idempotent',false
  );
end;
$function$
;

-- function: ops2_admin_ana_customer_profile_suggestions_v1(p_conversation_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_admin_ana_customer_profile_suggestions_v1(p_conversation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_access jsonb:=public.ops2_admin_attendance_customer_access_v1(false);
  v_items jsonb;
begin
  if coalesce((v_access->>'ok')::boolean,false) is not true then return v_access; end if;
  if p_conversation_id is null then return jsonb_build_object('ok',false,'error','invalid_conversation_id'); end if;
  if not exists(select 1 from public.conversations where id=p_conversation_id) then return jsonb_build_object('ok',false,'error','conversation_not_found'); end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',s.id,'run_id',s.run_id,'field_name',s.field_name,'suggested_value',s.suggested_value,
    'normalized_value',case when s.field_name='cpf_cnpj' then regexp_replace(s.normalized_value,'^(.*)([0-9]{4})$','***\2') else s.normalized_value end,
    'confidence',s.confidence,'classification',s.classification,'recommendation',s.recommendation,
    'evidence_message_ids',to_jsonb(s.evidence_message_ids),'status',s.status,'created_at',s.created_at
  ) order by s.created_at desc),'[]'::jsonb) into v_items
  from public.customer_profile_suggestions_v1 s
  where s.conversation_id=p_conversation_id and s.status<>'expired';

  return jsonb_build_object('ok',true,'conversation_id',p_conversation_id,'items',v_items);
end;
$function$
;

-- function: ops2_admin_ana_preview_finish_v1(p_job_id uuid, p_status text, p_decision text, p_suggestion_text text, p_confidence numeric, p_reason text, p_model text, p_provider_response_id text, p_last_error text, p_missing_context jsonb)
CREATE OR REPLACE FUNCTION public.ops2_admin_ana_preview_finish_v1(p_job_id uuid, p_status text, p_decision text DEFAULT NULL::text, p_suggestion_text text DEFAULT NULL::text, p_confidence numeric DEFAULT NULL::numeric, p_reason text DEFAULT NULL::text, p_model text DEFAULT NULL::text, p_provider_response_id text DEFAULT NULL::text, p_last_error text DEFAULT NULL::text, p_missing_context jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user uuid:=auth.uid();
  v_job public.whatsapp_ana_jobs_v1%rowtype;
  v_status text:=lower(btrim(coalesce(p_status,'')));
  v_decision text:=nullif(lower(btrim(coalesce(p_decision,''))),'');
  v_gate jsonb;
  v_missing jsonb:=case when jsonb_typeof(coalesce(p_missing_context,'[]'::jsonb))='array' then coalesce(p_missing_context,'[]'::jsonb) else '[]'::jsonb end;
begin
  if v_user is null then return jsonb_build_object('ok',false,'error','admin_auth_required'); end if;
  if not exists (select 1 from public.admin_users a where a.user_id=v_user and a.is_active=true) then return jsonb_build_object('ok',false,'error','admin_not_authorized'); end if;
  if p_job_id is null then return jsonb_build_object('ok',false,'error','job_required'); end if;
  if v_status not in ('completed','failed') then return jsonb_build_object('ok',false,'error','status_invalid'); end if;
  if v_decision is not null and v_decision not in ('suggest','handoff','no_reply') then return jsonb_build_object('ok',false,'error','decision_invalid'); end if;
  select j.* into v_job from public.whatsapp_ana_jobs_v1 j where j.id=p_job_id for update;
  if not found then return jsonb_build_object('ok',false,'error','job_not_found'); end if;
  if v_job.dry_run is not true or coalesce(v_job.metadata->>'dry_run_not_sendable','false')<>'true' then return jsonb_build_object('ok',false,'error','job_not_dry_run'); end if;
  if coalesce(v_job.metadata->>'initiated_by','')<>v_user::text then return jsonb_build_object('ok',false,'error','job_owner_mismatch'); end if;
  if v_job.status<>'claimed' then return jsonb_build_object('ok',true,'duplicate',true,'job_id',v_job.id,'status',v_job.status); end if;
  v_gate:=public.ops2_attendance_ai_gate_v1(v_job.conversation_id);
  if coalesce((v_gate->>'ok')::boolean,false) is not true or coalesce((v_gate->>'allowed')::boolean,false) is not true then
    update public.whatsapp_ana_jobs_v1 set status='skipped',decision=null,suggestion_text=null,confidence=null,reason='human_takeover_during_generation',completed_at=now(),last_error=null,metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('dry_run_not_sendable',true,'gate',v_gate),updated_at=now() where id=v_job.id returning * into v_job;
    return jsonb_build_object('ok',true,'job_id',v_job.id,'status',v_job.status,'decision',null,'suggestion_text',null,'confidence',null,'reason',v_job.reason,'dry_run',true,'dry_run_not_sendable',true);
  end if;
  update public.whatsapp_ana_jobs_v1 set status=v_status,decision=case when v_status='completed' then v_decision else null end,suggestion_text=case when v_status='completed' then nullif(btrim(coalesce(p_suggestion_text,'')),'') else null end,confidence=case when v_status='completed' then greatest(0,least(coalesce(p_confidence,0),1)) else null end,reason=nullif(btrim(coalesce(p_reason,'')),''),model=nullif(btrim(coalesce(p_model,'')),''),provider_response_id=nullif(btrim(coalesce(p_provider_response_id,'')),''),completed_at=now(),last_error=case when v_status='failed' then left(coalesce(p_last_error,'ana_preview_failed'),500) else null end,metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('dry_run_not_sendable',true,'missing_context',v_missing,'finished_by',v_user),updated_at=now() where id=v_job.id returning * into v_job;
  return jsonb_build_object('ok',true,'job_id',v_job.id,'status',v_job.status,'decision',v_job.decision,'suggestion_text',v_job.suggestion_text,'confidence',v_job.confidence,'reason',v_job.reason,'model',v_job.model,'missing_context',coalesce(v_job.metadata->'missing_context','[]'::jsonb),'completed_at',v_job.completed_at,'dry_run',true,'dry_run_not_sendable',true);
end;
$function$
;

-- function: ops2_admin_ana_preview_metrics_v1()
CREATE OR REPLACE FUNCTION public.ops2_admin_ana_preview_metrics_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user uuid:=auth.uid();
  v_jobs jsonb;
  v_reviews jsonb;
begin
  if v_user is null then return jsonb_build_object('ok',false,'error','admin_auth_required'); end if;
  if not exists (
    select 1 from public.admin_users a
    where a.user_id=v_user and a.is_active=true
  ) then return jsonb_build_object('ok',false,'error','admin_not_authorized'); end if;

  select jsonb_build_object(
    'total',count(*),
    'completed',count(*) filter (where j.status='completed'),
    'failed',count(*) filter (where j.status='failed'),
    'handoff',count(*) filter (where j.decision='handoff'),
    'suggest',count(*) filter (where j.decision='suggest'),
    'no_reply',count(*) filter (where j.decision='no_reply'),
    'avg_confidence',round(avg(j.confidence)::numeric,3),
    'avg_latency_ms',round(avg(case when coalesce(j.metadata->>'latency_ms','') ~ '^[0-9]+$' then (j.metadata->>'latency_ms')::numeric end),0)
  ) into v_jobs
  from public.whatsapp_ana_jobs_v1 j
  where j.dry_run=true and j.created_at>=now()-interval '30 days';

  select jsonb_build_object(
    'total',count(*),
    'used',count(*) filter (where r.outcome='used'),
    'helpful',count(*) filter (where r.outcome='helpful'),
    'rejected',count(*) filter (where r.outcome='rejected')
  ) into v_reviews
  from public.whatsapp_ana_reviews_v1 r
  where r.created_at>=now()-interval '30 days';

  return jsonb_build_object(
    'ok',true,'window_days',30,'jobs',coalesce(v_jobs,'{}'::jsonb),
    'reviews',coalesce(v_reviews,'{}'::jsonb),'dry_run_not_sendable',true
  );
end;
$function$
;

-- function: ops2_admin_ana_preview_observe_v1(p_job_id uuid, p_latency_ms integer, p_cached boolean)
CREATE OR REPLACE FUNCTION public.ops2_admin_ana_preview_observe_v1(p_job_id uuid, p_latency_ms integer, p_cached boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user uuid:=auth.uid();
  v_job public.whatsapp_ana_jobs_v1%rowtype;
  v_latency integer:=greatest(0,least(coalesce(p_latency_ms,0),120000));
begin
  if v_user is null then return jsonb_build_object('ok',false,'error','admin_auth_required'); end if;
  if not exists (
    select 1 from public.admin_users a
    where a.user_id=v_user and a.is_active=true
  ) then return jsonb_build_object('ok',false,'error','admin_not_authorized'); end if;
  if p_job_id is null then return jsonb_build_object('ok',false,'error','job_required'); end if;

  select j.* into v_job
  from public.whatsapp_ana_jobs_v1 j
  where j.id=p_job_id
  for update;
  if not found then return jsonb_build_object('ok',false,'error','job_not_found'); end if;
  if v_job.dry_run is not true
     or coalesce(v_job.metadata->>'dry_run_not_sendable','false')<>'true' then
    return jsonb_build_object('ok',false,'error','job_not_dry_run');
  end if;

  update public.whatsapp_ana_jobs_v1
  set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object(
        'latency_ms',v_latency,
        'cached',coalesce(p_cached,false),
        'observed_by',v_user,
        'observed_at',now()
      ),
      updated_at=now()
  where id=v_job.id;

  return jsonb_build_object(
    'ok',true,'job_id',v_job.id,'latency_ms',v_latency,
    'cached',coalesce(p_cached,false),'dry_run_not_sendable',true
  );
end;
$function$
;

-- function: ops2_admin_ana_preview_review_v1(p_job_id uuid, p_outcome text, p_note text)
CREATE OR REPLACE FUNCTION public.ops2_admin_ana_preview_review_v1(p_job_id uuid, p_outcome text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user uuid:=auth.uid();
  v_job public.whatsapp_ana_jobs_v1%rowtype;
  v_outcome text:=lower(btrim(coalesce(p_outcome,'')));
  v_note text:=nullif(left(btrim(coalesce(p_note,'')),500),'');
  v_review_id uuid;
begin
  if v_user is null then return jsonb_build_object('ok',false,'error','admin_auth_required'); end if;
  if not exists (
    select 1 from public.admin_users a
    where a.user_id=v_user and a.is_active=true
  ) then return jsonb_build_object('ok',false,'error','admin_not_authorized'); end if;
  if p_job_id is null then return jsonb_build_object('ok',false,'error','job_required'); end if;
  if v_outcome not in ('used','helpful','rejected') then return jsonb_build_object('ok',false,'error','review_outcome_invalid'); end if;

  select j.* into v_job
  from public.whatsapp_ana_jobs_v1 j
  where j.id=p_job_id
  for update;
  if not found then return jsonb_build_object('ok',false,'error','job_not_found'); end if;
  if v_job.dry_run is not true
     or coalesce(v_job.metadata->>'dry_run_not_sendable','false')<>'true' then
    return jsonb_build_object('ok',false,'error','job_not_dry_run');
  end if;
  if not (v_job.status='completed') then
    return jsonb_build_object('ok',false,'error','ana_preview_not_completed');
  end if;

  insert into public.whatsapp_ana_reviews_v1(job_id,conversation_id,reviewer_user_id,outcome,note)
  values(v_job.id,v_job.conversation_id,v_user,v_outcome,v_note)
  returning id into v_review_id;

  update public.whatsapp_ana_jobs_v1
  set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object(
        'review_outcome',v_outcome,
        'review_note',v_note,
        'reviewed_by',v_user,
        'reviewed_at',now()
      ),
      updated_at=now()
  where id=v_job.id;

  return jsonb_build_object(
    'ok',true,'review_id',v_review_id,'job_id',v_job.id,'outcome',v_outcome,
    'reviewed_by',v_user,'dry_run',true,'dry_run_not_sendable',true
  );
end;
$function$
;

-- function: ops2_admin_ana_preview_start_v1(p_conversation_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_admin_ana_preview_start_v1(p_conversation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user uuid:=auth.uid();
  v_conversation public.conversations%rowtype;
  v_message public.whatsapp_messages_v1%rowtype;
  v_job public.whatsapp_ana_jobs_v1%rowtype;
  v_gate jsonb;
  v_history jsonb:='[]'::jsonb;
  v_recovered_stale boolean:=false;
  v_previous_claimed_at timestamptz:=null;
  v_recovery_count integer:=0;
begin
  if v_user is null then return jsonb_build_object('ok',false,'error','admin_auth_required'); end if;
  if not exists (select 1 from public.admin_users a where a.user_id=v_user and a.is_active=true) then return jsonb_build_object('ok',false,'error','admin_not_authorized'); end if;
  if p_conversation_id is null then return jsonb_build_object('ok',false,'error','invalid_conversation_id'); end if;
  select c.* into v_conversation from public.conversations c where c.id=p_conversation_id for update;
  if not found then return jsonb_build_object('ok',false,'error','conversation_not_found'); end if;
  v_gate:=public.ops2_attendance_ai_gate_v1(v_conversation.id);
  if coalesce((v_gate->>'ok')::boolean,false) is not true or coalesce((v_gate->>'allowed')::boolean,false) is not true then return jsonb_build_object('ok',false,'error','ai_gate_closed','gate',v_gate); end if;
  select m.* into v_message from public.whatsapp_messages_v1 m where m.conversation_id=v_conversation.id and m.direction='inbound' and m.message_type='text' and nullif(btrim(coalesce(m.text_body,'')),'') is not null order by coalesce(m.received_at,m.created_at) desc,m.created_at desc,m.id desc limit 1;
  if not found then return jsonb_build_object('ok',false,'error','ana_preview_no_text_inbound'); end if;
  select j.* into v_job from public.whatsapp_ana_jobs_v1 j where j.inbound_message_id=v_message.id for update;
  if found then
    if v_job.status='claimed' then
      if v_job.claimed_at is null or v_job.claimed_at > now() - interval '2 minutes' or v_job.dry_run is not true or coalesce(v_job.metadata->>'source','')<>'admin_preview' or coalesce(v_job.metadata->>'dry_run_not_sendable','false')<>'true' then return jsonb_build_object('ok',false,'error','ana_preview_busy','job_id',v_job.id); end if;
      v_recovered_stale:=true; v_previous_claimed_at:=v_job.claimed_at;
      begin v_recovery_count:=greatest(0,coalesce((v_job.metadata->>'stale_claim_recovery_count')::integer,0)); exception when others then v_recovery_count:=0; end;
    end if;
    if v_job.status='completed' then return jsonb_build_object('ok',true,'cached',true,'dry_run',true,'dry_run_not_sendable',true,'job_id',v_job.id,'status',v_job.status,'decision',v_job.decision,'suggestion_text',v_job.suggestion_text,'confidence',v_job.confidence,'reason',v_job.reason,'model',v_job.model,'missing_context',coalesce(v_job.metadata->'missing_context','[]'::jsonb),'completed_at',v_job.completed_at); end if;
    update public.whatsapp_ana_jobs_v1 j set status='claimed',claimed_at=now(),completed_at=null,last_error=null,decision=null,suggestion_text=null,confidence=null,reason=null,attempt_count=j.attempt_count+1,metadata=coalesce(j.metadata,'{}'::jsonb)||jsonb_build_object('source','admin_preview','initiated_by',v_user,'dry_run_not_sendable',true)||case when v_recovered_stale then jsonb_build_object('stale_claim_recovery_count',v_recovery_count+1,'last_stale_claim_recovered_at',now(),'last_stale_claimed_at',v_previous_claimed_at,'stale_claim_recovery_reason','lease_expired') else '{}'::jsonb end,updated_at=now() where j.id=v_job.id returning j.* into v_job;
  else
    insert into public.whatsapp_ana_jobs_v1(inbound_message_id,conversation_id,whatsapp_account_id,dry_run,status,claimed_at,attempt_count,metadata) values(v_message.id,v_conversation.id,v_message.whatsapp_account_id,true,'claimed',now(),1,jsonb_build_object('source','admin_preview','initiated_by',v_user,'provider',v_message.provider,'provider_message_id',v_message.provider_message_id,'dry_run_not_sendable',true)) returning * into v_job;
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('direction',x.direction,'text_body',x.text_body,'sender_kind',x.sender_kind,'created_at',x.occurred_at) order by x.occurred_at,x.id),'[]'::jsonb) into v_history from (select m.id,m.direction,m.text_body,m.sender_kind,coalesce(m.received_at,m.sent_at,m.created_at) occurred_at from public.whatsapp_messages_v1 m where m.conversation_id=v_conversation.id and nullif(btrim(coalesce(m.text_body,'')),'') is not null order by coalesce(m.received_at,m.sent_at,m.created_at) desc,m.created_at desc,m.id desc limit 12) x;
  return jsonb_build_object('ok',true,'cached',false,'dry_run',true,'dry_run_not_sendable',true,'job_id',v_job.id,'status',v_job.status,'inbound_message_id',v_message.id,'inbound_text',v_message.text_body,'history',v_history,'recovered_stale_claim',v_recovered_stale);
end;
$function$
;

-- function: ops2_admin_attendance_accept_meta_interactive_v1(p_outbox_id uuid, p_provider_message_id text, p_accepted_at timestamp with time zone)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_accept_meta_interactive_v1(p_outbox_id uuid, p_provider_message_id text, p_accepted_at timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_outbox public.whatsapp_outbox_v1%rowtype;
  v_message public.whatsapp_messages_v1%rowtype;
  v_provider_message_id text := btrim(coalesce(p_provider_message_id, ''));
  v_accepted_at timestamptz := coalesce(p_accepted_at, now());
  v_message_id uuid;
  v_status_result jsonb;
  v_status text;
  v_occurred_at timestamptz;
  v_replayed integer := 0;
  v_body text;
  r public.whatsapp_webhook_events_v1%rowtype;
begin
  if p_outbox_id is null then return jsonb_build_object('ok', false, 'error', 'outbox_required'); end if;
  if v_provider_message_id not like 'wamid.%'
     or char_length(v_provider_message_id) > 500
     or v_provider_message_id ~ '[[:cntrl:][:space:]]' then
    return jsonb_build_object('ok', false, 'error', 'provider_message_id_invalid');
  end if;
  select o.* into v_outbox from public.whatsapp_outbox_v1 o where o.id = p_outbox_id for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'outbox_not_found'); end if;
  if v_outbox.provider <> 'meta' or v_outbox.purpose <> 'human_attendance'
     or v_outbox.message_type <> 'interactive' or v_outbox.conversation_id is null then
    return jsonb_build_object('ok', false, 'error', 'outbox_not_meta_interactive_attendance');
  end if;
  if v_outbox.status = 'sent' then
    if v_outbox.provider_message_id is distinct from v_provider_message_id or v_outbox.message_id is null then
      return jsonb_build_object('ok', false, 'error', 'already_sent_mismatch');
    end if;
    return jsonb_build_object('ok', true, 'already_accepted', true, 'idempotent', true,
      'outbox_id', v_outbox.id, 'message_id', v_outbox.message_id,
      'provider_message_id', v_outbox.provider_message_id, 'status', 'sent');
  end if;
  if v_outbox.status <> 'claimed' then
    return jsonb_build_object('ok', false, 'error', 'outbox_not_claimed', 'status', v_outbox.status);
  end if;

  v_body := nullif(btrim(v_outbox.payload#>>'{interactive,body,text}'), '');
  if v_body is null then return jsonb_build_object('ok', false, 'error', 'outbox_payload_invalid'); end if;

  select m.* into v_message
  from public.whatsapp_messages_v1 m
  where m.whatsapp_account_id = v_outbox.whatsapp_account_id
    and m.provider_message_id = v_provider_message_id
  order by case when m.provider = 'meta' then 0 else 1 end, m.created_at, m.id
  limit 1 for update;
  if found then
    if v_message.conversation_id is distinct from v_outbox.conversation_id or v_message.direction <> 'outbound' then
      return jsonb_build_object('ok', false, 'error', 'wamid_conversation_conflict');
    end if;
    update public.whatsapp_messages_v1 m
    set provider = 'meta', customer_id = coalesce(m.customer_id, v_outbox.customer_id),
        message_type = 'interactive', text_body = coalesce(m.text_body, v_body),
        status_current = case when m.status_current in ('sent','delivered','read','failed','cancelled') then m.status_current else 'accepted' end,
        sender_kind = 'human', sender_ref = coalesce(nullif(v_outbox.metadata->>'admin_user_id',''), m.sender_ref),
        sent_at = coalesce(m.sent_at, v_accepted_at),
        metadata = coalesce(m.metadata, '{}'::jsonb) || jsonb_build_object(
          'source','attendance','transport','meta_cloud_api','outbox_id',v_outbox.id,
          'idempotency_key',v_outbox.idempotency_key,'meta_acceptance','accepted',
          'meta_accepted_at',v_accepted_at,'interactive_type',v_outbox.payload#>>'{interactive,type}')
    where m.id = v_message.id returning * into v_message;
  else
    begin
      insert into public.whatsapp_messages_v1(
        conversation_id, whatsapp_account_id, customer_id, direction, message_type, provider,
        provider_message_id, provider_conversation_id, text_body, status_current,
        sender_kind, sender_ref, sent_at, metadata
      ) values (
        v_outbox.conversation_id, v_outbox.whatsapp_account_id, v_outbox.customer_id,
        'outbound','interactive','meta',v_provider_message_id,null,v_body,'accepted','human',
        nullif(v_outbox.metadata->>'admin_user_id',''),v_accepted_at,
        jsonb_build_object('source','attendance','transport','meta_cloud_api','outbox_id',v_outbox.id,
          'idempotency_key',v_outbox.idempotency_key,'meta_acceptance','accepted',
          'meta_accepted_at',v_accepted_at,'interactive_type',v_outbox.payload#>>'{interactive,type}')
      ) returning * into v_message;
    exception when unique_violation then
      select m.* into v_message
      from public.whatsapp_messages_v1 m
      where m.whatsapp_account_id = v_outbox.whatsapp_account_id
        and m.provider_message_id = v_provider_message_id
      order by case when m.provider = 'meta' then 0 else 1 end, m.created_at, m.id
      limit 1 for update;
      if not found or v_message.conversation_id is distinct from v_outbox.conversation_id
         or v_message.direction <> 'outbound' then
        return jsonb_build_object('ok', false, 'error', 'wamid_race_conflict');
      end if;
      update public.whatsapp_messages_v1 m
      set provider='meta', message_type='interactive', text_body=coalesce(m.text_body,v_body),
          sender_kind='human', sender_ref=coalesce(nullif(v_outbox.metadata->>'admin_user_id',''),m.sender_ref),
          status_current=case when m.status_current in ('sent','delivered','read','failed','cancelled') then m.status_current else 'accepted' end,
          sent_at=coalesce(m.sent_at,v_accepted_at),
          metadata=coalesce(m.metadata,'{}'::jsonb)||jsonb_build_object(
            'source','attendance','transport','meta_cloud_api','outbox_id',v_outbox.id,
            'idempotency_key',v_outbox.idempotency_key,'meta_acceptance','accepted',
            'meta_accepted_at',v_accepted_at,'interactive_type',v_outbox.payload#>>'{interactive,type}',
            'race_reconciled',true)
      where m.id=v_message.id returning * into v_message;
    end;
  end if;

  v_message_id := v_message.id;
  update public.whatsapp_outbox_v1
  set message_id=v_message_id, provider_message_id=v_provider_message_id, status='sent',
      sent_at=v_accepted_at, last_error=null,
      metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object(
        'meta_acceptance','accepted','meta_accepted_at',v_accepted_at,'canonical_message_id',v_message_id),
      updated_at=now()
  where id=v_outbox.id;

  update public.conversations
  set last_outbound_at=greatest(coalesce(last_outbound_at,'-infinity'::timestamptz),v_accepted_at),
      last_human_message_at=greatest(coalesce(last_human_message_at,'-infinity'::timestamptz),v_accepted_at),
      updated_at=greatest(updated_at,v_accepted_at)
  where id=v_outbox.conversation_id;

  v_status_result := public.whatsapp_record_status_v1(
    v_outbox.whatsapp_account_id,'meta',v_provider_message_id,'accepted',v_accepted_at,now(),
    null,null,null,jsonb_build_object('source','graph_send_response','outbox_id',v_outbox.id));
  if coalesce((v_status_result->>'ok')::boolean,false) is not true then
    return jsonb_build_object('ok',false,'error','accepted_status_record_failed');
  end if;

  for r in
    select e.* from public.whatsapp_webhook_events_v1 e
    where e.whatsapp_account_id=v_outbox.whatsapp_account_id
      and e.provider='meta' and e.provider_message_id=v_provider_message_id
      and e.event_type like 'message.status.%' and e.status='received'
    order by e.received_at,e.id for update
  loop
    v_status := split_part(r.event_type,'.',3);
    if v_status not in ('sent','delivered','read','failed','cancelled') then
      update public.whatsapp_webhook_events_v1
      set status='ignored',processed_at=now(),last_error='status_not_supported_for_replay'
      where id=r.id;
      continue;
    end if;
    v_occurred_at := case when coalesce(r.payload->>'timestamp','') ~ '^\d+(\.\d+)?$'
      then to_timestamp((r.payload->>'timestamp')::double precision) else r.received_at end;
    v_status_result := public.whatsapp_record_status_v1(
      v_outbox.whatsapp_account_id,'meta',v_provider_message_id,v_status,
      v_occurred_at,r.received_at,nullif(r.payload->'errors'->0->>'code',''),
      nullif(r.payload->'errors'->0->>'title',''),
      nullif(coalesce(r.payload->'errors'->0->>'message',r.payload->'errors'->0->'error_data'->>'details'),''),r.payload);
    if coalesce((v_status_result->>'ok')::boolean,false) is true then
      update public.whatsapp_webhook_events_v1 set status='normalized',processed_at=now(),last_error=null where id=r.id;
      v_replayed := v_replayed + 1;
    else
      update public.whatsapp_webhook_events_v1
      set status='review_required',processed_at=now(),last_error=left(coalesce(v_status_result->>'error','status_replay_failed'),500)
      where id=r.id;
    end if;
  end loop;

  return jsonb_build_object(
    'ok',true,'already_accepted',false,'idempotent',false,'outbox_id',v_outbox.id,
    'message_id',v_message_id,'provider_message_id',v_provider_message_id,
    'status_current',(select m.status_current from public.whatsapp_messages_v1 m where m.id=v_message_id),
    'pending_statuses_replayed',v_replayed,'status','sent');
end;
$function$
;

-- function: ops2_admin_attendance_accept_meta_media_outbound_v1(p_outbox_id uuid, p_provider_message_id text, p_provider_media_id text, p_accepted_at timestamp with time zone)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_accept_meta_media_outbound_v1(p_outbox_id uuid, p_provider_message_id text, p_provider_media_id text, p_accepted_at timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_outbox public.whatsapp_outbox_v1%rowtype;
  v_message public.whatsapp_messages_v1%rowtype;
  v_provider_message_id text:=btrim(coalesce(p_provider_message_id,''));
  v_provider_media_id text:=btrim(coalesce(p_provider_media_id,''));
  v_accepted_at timestamptz:=coalesce(p_accepted_at,now());
  v_message_id uuid;
  v_status_result jsonb;
  v_replayed integer:=0;
  v_status text;
  v_occurred_at timestamptz;
  v_caption text;
  v_media jsonb;
  r public.whatsapp_webhook_events_v1%rowtype;
begin
  if p_outbox_id is null then return jsonb_build_object('ok',false,'error','outbox_required'); end if;
  if v_provider_message_id not like 'wamid.%'
     or char_length(v_provider_message_id)>500
     or v_provider_message_id ~ '[[:cntrl:][:space:]]' then
    return jsonb_build_object('ok',false,'error','provider_message_id_invalid');
  end if;
  if v_provider_media_id !~ '^[A-Za-z0-9._:-]{3,240}$' then
    return jsonb_build_object('ok',false,'error','provider_media_id_invalid');
  end if;

  select o.* into v_outbox
  from public.whatsapp_outbox_v1 o
  where o.id=p_outbox_id
  for update;
  if not found then return jsonb_build_object('ok',false,'error','outbox_not_found'); end if;
  if v_outbox.provider<>'meta'
     or v_outbox.purpose<>'human_attendance'
     or v_outbox.message_type not in ('image','audio','video','document') then
    return jsonb_build_object('ok',false,'error','outbox_not_meta_attendance_media');
  end if;
  if v_outbox.conversation_id is null then return jsonb_build_object('ok',false,'error','conversation_required'); end if;

  if v_outbox.status='sent' then
    if v_outbox.provider_message_id is distinct from v_provider_message_id or v_outbox.message_id is null then
      return jsonb_build_object('ok',false,'error','already_sent_mismatch');
    end if;
    return jsonb_build_object(
      'ok',true,'already_accepted',true,'idempotent',true,
      'outbox_id',v_outbox.id,'message_id',v_outbox.message_id,
      'provider_message_id',v_outbox.provider_message_id,'provider_media_id',v_provider_media_id,'status','sent'
    );
  end if;
  if v_outbox.status<>'claimed' then
    return jsonb_build_object('ok',false,'error','outbox_not_claimed','status',v_outbox.status);
  end if;

  v_caption:=case when v_outbox.message_type='audio' then null else nullif(v_outbox.payload->>'caption','') end;
  v_media:=jsonb_build_object(
    'provider_media_id',v_provider_media_id,
    'mime_type',nullif(v_outbox.payload->>'mime_type',''),
    'filename',nullif(v_outbox.payload->>'filename',''),
    'size_bytes',coalesce((v_outbox.payload->>'size_bytes')::bigint,0),
    'sha256',nullif(v_outbox.payload->>'sha256','')
  );

  select m.* into v_message
  from public.whatsapp_messages_v1 m
  where m.whatsapp_account_id=v_outbox.whatsapp_account_id
    and m.provider_message_id=v_provider_message_id
  order by case when m.provider='meta' then 0 else 1 end,m.created_at,m.id
  limit 1
  for update;

  if found then
    if v_message.conversation_id is distinct from v_outbox.conversation_id then
      return jsonb_build_object('ok',false,'error','wamid_conversation_conflict');
    end if;
    if v_message.direction<>'outbound' then
      return jsonb_build_object('ok',false,'error','wamid_direction_conflict');
    end if;
    update public.whatsapp_messages_v1 m
    set provider='meta',
        customer_id=coalesce(m.customer_id,v_outbox.customer_id),
        message_type=v_outbox.message_type,
        text_body=coalesce(m.text_body,v_caption),
        status_current=case when m.status_current in ('sent','delivered','read','failed','cancelled') then m.status_current else 'accepted' end,
        sender_kind='human',
        sender_ref=coalesce(nullif(v_outbox.metadata->>'admin_user_id',''),m.sender_ref),
        sent_at=coalesce(m.sent_at,v_accepted_at),
        metadata=coalesce(m.metadata,'{}'::jsonb)||jsonb_build_object(
          'source','attendance','transport','meta_cloud_api','outbox_id',v_outbox.id,
          'idempotency_key',v_outbox.idempotency_key,'meta_acceptance','accepted',
          'meta_accepted_at',v_accepted_at,'media',v_media,'promoted_from_shadow',v_message.provider='papoai'
        )
    where m.id=v_message.id
    returning * into v_message;
  else
    begin
      insert into public.whatsapp_messages_v1(
        conversation_id,whatsapp_account_id,customer_id,direction,message_type,provider,
        provider_message_id,provider_conversation_id,text_body,status_current,sender_kind,
        sender_ref,sent_at,metadata
      ) values (
        v_outbox.conversation_id,v_outbox.whatsapp_account_id,v_outbox.customer_id,
        'outbound',v_outbox.message_type,'meta',v_provider_message_id,null,
        v_caption,'accepted','human',nullif(v_outbox.metadata->>'admin_user_id',''),v_accepted_at,
        jsonb_build_object(
          'source','attendance','transport','meta_cloud_api','outbox_id',v_outbox.id,
          'idempotency_key',v_outbox.idempotency_key,'meta_acceptance','accepted',
          'meta_accepted_at',v_accepted_at,'media',v_media
        )
      ) returning * into v_message;
    exception when unique_violation then
      select m.* into v_message
      from public.whatsapp_messages_v1 m
      where m.whatsapp_account_id=v_outbox.whatsapp_account_id
        and m.provider_message_id=v_provider_message_id
      order by case when m.provider='meta' then 0 else 1 end,m.created_at,m.id
      limit 1
      for update;
      if not found then raise; end if;
      if v_message.conversation_id is distinct from v_outbox.conversation_id or v_message.direction<>'outbound' then
        return jsonb_build_object('ok',false,'error','wamid_race_conflict');
      end if;
      update public.whatsapp_messages_v1 m
      set provider='meta',message_type=v_outbox.message_type,sender_kind='human',
          sender_ref=coalesce(nullif(v_outbox.metadata->>'admin_user_id',''),m.sender_ref),
          text_body=coalesce(m.text_body,v_caption),
          status_current=case when m.status_current in ('sent','delivered','read','failed','cancelled') then m.status_current else 'accepted' end,
          sent_at=coalesce(m.sent_at,v_accepted_at),
          metadata=coalesce(m.metadata,'{}'::jsonb)||jsonb_build_object(
            'source','attendance','transport','meta_cloud_api','outbox_id',v_outbox.id,
            'idempotency_key',v_outbox.idempotency_key,'meta_acceptance','accepted',
            'meta_accepted_at',v_accepted_at,'media',v_media,'race_reconciled',true
          )
      where m.id=v_message.id
      returning * into v_message;
    end;
  end if;

  v_message_id:=v_message.id;

  update public.whatsapp_outbox_v1
  set message_id=v_message_id,provider_message_id=v_provider_message_id,status='sent',
      sent_at=v_accepted_at,last_error=null,
      metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object(
        'meta_acceptance','accepted','meta_accepted_at',v_accepted_at,
        'canonical_message_id',v_message_id,'provider_media_id',v_provider_media_id
      ),updated_at=now()
  where id=v_outbox.id;

  update public.conversations
  set last_outbound_at=greatest(coalesce(last_outbound_at,'-infinity'::timestamptz),v_accepted_at),
      last_human_message_at=greatest(coalesce(last_human_message_at,'-infinity'::timestamptz),v_accepted_at),
      updated_at=greatest(updated_at,v_accepted_at)
  where id=v_outbox.conversation_id;

  v_status_result:=public.whatsapp_record_status_v1(
    v_outbox.whatsapp_account_id,'meta',v_provider_message_id,'accepted',v_accepted_at,now(),
    null,null,null,jsonb_build_object('source','graph_send_response','outbox_id',v_outbox.id,'message_type',v_outbox.message_type)
  );
  if coalesce((v_status_result->>'ok')::boolean,false) is not true then
    return jsonb_build_object('ok',false,'error','accepted_status_record_failed','detail',v_status_result);
  end if;

  for r in
    select e.*
    from public.whatsapp_webhook_events_v1 e
    where e.whatsapp_account_id=v_outbox.whatsapp_account_id
      and e.provider='meta'
      and e.provider_message_id=v_provider_message_id
      and e.event_type like 'message.status.%'
      and e.status='received'
    order by e.received_at,e.id
    for update
  loop
    v_status:=split_part(r.event_type,'.',3);
    if v_status not in ('sent','delivered','read','failed','cancelled') then
      update public.whatsapp_webhook_events_v1
      set status='ignored',processed_at=now(),last_error='status_not_supported_for_replay'
      where id=r.id;
      continue;
    end if;
    v_occurred_at:=case
      when coalesce(r.payload->>'timestamp','') ~ '^[0-9]+([.][0-9]+)?$'
        then to_timestamp((r.payload->>'timestamp')::double precision)
      else r.received_at
    end;
    v_status_result:=public.whatsapp_record_status_v1(
      v_outbox.whatsapp_account_id,'meta',v_provider_message_id,v_status,
      v_occurred_at,r.received_at,
      nullif(r.payload->'errors'->0->>'code',''),
      nullif(r.payload->'errors'->0->>'title',''),
      nullif(coalesce(r.payload->'errors'->0->>'message',r.payload->'errors'->0->'error_data'->>'details'),''),
      r.payload
    );
    if coalesce((v_status_result->>'ok')::boolean,false) is true then
      update public.whatsapp_webhook_events_v1
      set status='normalized',processed_at=now(),last_error=null
      where id=r.id;
      v_replayed:=v_replayed+1;
    else
      update public.whatsapp_webhook_events_v1
      set status='review_required',processed_at=now(),last_error=left(coalesce(v_status_result->>'error','status_replay_failed'),500)
      where id=r.id;
    end if;
  end loop;

  return jsonb_build_object(
    'ok',true,'already_accepted',false,'idempotent',false,
    'outbox_id',v_outbox.id,'message_id',v_message_id,
    'provider_message_id',v_provider_message_id,'provider_media_id',v_provider_media_id,
    'status_current',(select m.status_current from public.whatsapp_messages_v1 m where m.id=v_message_id),
    'pending_statuses_replayed',v_replayed,'status','sent'
  );
end;
$function$
;

-- function: ops2_admin_attendance_accept_meta_outbound_v1(p_outbox_id uuid, p_provider_message_id text, p_accepted_at timestamp with time zone)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_accept_meta_outbound_v1(p_outbox_id uuid, p_provider_message_id text, p_accepted_at timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_outbox public.whatsapp_outbox_v1%rowtype;
  v_message public.whatsapp_messages_v1%rowtype;
  v_provider_message_id text:=btrim(coalesce(p_provider_message_id,''));
  v_accepted_at timestamptz:=coalesce(p_accepted_at,now());
  v_message_id uuid;
  v_status_result jsonb;
  v_replayed integer:=0;
  v_status text;
  v_occurred_at timestamptz;
  r public.whatsapp_webhook_events_v1%rowtype;
begin
  if p_outbox_id is null then
    return jsonb_build_object('ok',false,'error','outbox_required');
  end if;
  if v_provider_message_id not like 'wamid.%'
     or char_length(v_provider_message_id)>500
     or v_provider_message_id ~ '[[:cntrl:][:space:]]' then
    return jsonb_build_object('ok',false,'error','provider_message_id_invalid');
  end if;

  select o.* into v_outbox
  from public.whatsapp_outbox_v1 o
  where o.id=p_outbox_id
  for update;
  if not found then
    return jsonb_build_object('ok',false,'error','outbox_not_found');
  end if;

  if v_outbox.provider<>'meta' or v_outbox.purpose<>'human_attendance' or v_outbox.message_type<>'text' then
    return jsonb_build_object('ok',false,'error','outbox_not_meta_attendance');
  end if;
  if v_outbox.conversation_id is null then
    return jsonb_build_object('ok',false,'error','conversation_required');
  end if;

  if v_outbox.status='sent' then
    if v_outbox.provider_message_id is distinct from v_provider_message_id or v_outbox.message_id is null then
      return jsonb_build_object('ok',false,'error','already_sent_mismatch');
    end if;
    return jsonb_build_object(
      'ok',true,'already_accepted',true,'idempotent',true,
      'outbox_id',v_outbox.id,'message_id',v_outbox.message_id,
      'provider_message_id',v_outbox.provider_message_id,'status','sent'
    );
  end if;
  if v_outbox.status<>'claimed' then
    return jsonb_build_object('ok',false,'error','outbox_not_claimed','status',v_outbox.status);
  end if;

  select m.* into v_message
  from public.whatsapp_messages_v1 m
  where m.whatsapp_account_id=v_outbox.whatsapp_account_id
    and m.provider_message_id=v_provider_message_id
  order by case when m.provider='meta' then 0 else 1 end,m.created_at,m.id
  limit 1
  for update;

  if found then
    if v_message.conversation_id is distinct from v_outbox.conversation_id then
      return jsonb_build_object('ok',false,'error','wamid_conversation_conflict');
    end if;
    if v_message.direction<>'outbound' then
      return jsonb_build_object('ok',false,'error','wamid_direction_conflict');
    end if;

    update public.whatsapp_messages_v1 m
    set provider='meta',
        customer_id=coalesce(m.customer_id,v_outbox.customer_id),
        message_type='text',
        text_body=coalesce(m.text_body,nullif(v_outbox.payload->>'text','')),
        status_current=case when m.status_current in ('sent','delivered','read','failed','cancelled') then m.status_current else 'accepted' end,
        sender_kind='human',
        sender_ref=coalesce(nullif(v_outbox.metadata->>'admin_user_id',''),m.sender_ref),
        sent_at=coalesce(m.sent_at,v_accepted_at),
        metadata=coalesce(m.metadata,'{}'::jsonb)||jsonb_build_object(
          'source','attendance','transport','meta_cloud_api','outbox_id',v_outbox.id,
          'idempotency_key',v_outbox.idempotency_key,'meta_acceptance','accepted',
          'meta_accepted_at',v_accepted_at,'promoted_from_shadow',v_message.provider='papoai'
        )
    where m.id=v_message.id
    returning * into v_message;
  else
    begin
      insert into public.whatsapp_messages_v1(
        conversation_id,whatsapp_account_id,customer_id,direction,message_type,provider,
        provider_message_id,provider_conversation_id,text_body,status_current,sender_kind,
        sender_ref,sent_at,metadata
      ) values (
        v_outbox.conversation_id,v_outbox.whatsapp_account_id,v_outbox.customer_id,
        'outbound','text','meta',v_provider_message_id,null,
        nullif(v_outbox.payload->>'text',''),'accepted','human',
        nullif(v_outbox.metadata->>'admin_user_id',''),v_accepted_at,
        jsonb_build_object(
          'source','attendance','transport','meta_cloud_api','outbox_id',v_outbox.id,
          'idempotency_key',v_outbox.idempotency_key,'meta_acceptance','accepted',
          'meta_accepted_at',v_accepted_at
        )
      )
      returning * into v_message;
    exception when unique_violation then
      select m.* into v_message
      from public.whatsapp_messages_v1 m
      where m.whatsapp_account_id=v_outbox.whatsapp_account_id
        and m.provider_message_id=v_provider_message_id
      order by case when m.provider='meta' then 0 else 1 end,m.created_at,m.id
      limit 1
      for update;
      if not found then raise; end if;
      if v_message.conversation_id is distinct from v_outbox.conversation_id or v_message.direction<>'outbound' then
        return jsonb_build_object('ok',false,'error','wamid_race_conflict');
      end if;
      update public.whatsapp_messages_v1 m
      set provider='meta',sender_kind='human',
          sender_ref=coalesce(nullif(v_outbox.metadata->>'admin_user_id',''),m.sender_ref),
          text_body=coalesce(m.text_body,nullif(v_outbox.payload->>'text','')),
          status_current=case when m.status_current in ('sent','delivered','read','failed','cancelled') then m.status_current else 'accepted' end,
          sent_at=coalesce(m.sent_at,v_accepted_at),
          metadata=coalesce(m.metadata,'{}'::jsonb)||jsonb_build_object(
            'source','attendance','transport','meta_cloud_api','outbox_id',v_outbox.id,
            'idempotency_key',v_outbox.idempotency_key,'meta_acceptance','accepted',
            'meta_accepted_at',v_accepted_at,'race_reconciled',true
          )
      where m.id=v_message.id
      returning * into v_message;
    end;
  end if;

  v_message_id:=v_message.id;

  update public.whatsapp_outbox_v1
  set message_id=v_message_id,
      provider_message_id=v_provider_message_id,
      status='sent',
      sent_at=v_accepted_at,
      last_error=null,
      metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object(
        'meta_acceptance','accepted','meta_accepted_at',v_accepted_at,
        'canonical_message_id',v_message_id
      ),
      updated_at=now()
  where id=v_outbox.id;

  update public.conversations
  set last_outbound_at=greatest(coalesce(last_outbound_at,'-infinity'::timestamptz),v_accepted_at),
      last_human_message_at=greatest(coalesce(last_human_message_at,'-infinity'::timestamptz),v_accepted_at),
      updated_at=greatest(updated_at,v_accepted_at)
  where id=v_outbox.conversation_id;

  v_status_result:=public.whatsapp_record_status_v1(
    v_outbox.whatsapp_account_id,'meta',v_provider_message_id,'accepted',v_accepted_at,now(),
    null,null,null,jsonb_build_object('source','graph_send_response','outbox_id',v_outbox.id)
  );
  if coalesce((v_status_result->>'ok')::boolean,false) is not true then
    return jsonb_build_object('ok',false,'error','accepted_status_record_failed','detail',v_status_result);
  end if;

  for r in
    select e.*
    from public.whatsapp_webhook_events_v1 e
    where e.whatsapp_account_id=v_outbox.whatsapp_account_id
      and e.provider='meta'
      and e.provider_message_id=v_provider_message_id
      and e.event_type like 'message.status.%'
      and e.status='received'
    order by e.received_at,e.id
    for update
  loop
    v_status:=split_part(r.event_type,'.',3);
    if v_status not in ('sent','delivered','read','failed','cancelled') then
      update public.whatsapp_webhook_events_v1
      set status='ignored',processed_at=now(),last_error='status_not_supported_for_replay'
      where id=r.id;
      continue;
    end if;

    v_occurred_at:=case
      when coalesce(r.payload->>'timestamp','') ~ '^\d+(\.\d+)?$' then to_timestamp((r.payload->>'timestamp')::double precision)
      else r.received_at
    end;

    v_status_result:=public.whatsapp_record_status_v1(
      v_outbox.whatsapp_account_id,'meta',v_provider_message_id,v_status,
      v_occurred_at,r.received_at,
      nullif(r.payload->'errors'->0->>'code',''),
      nullif(r.payload->'errors'->0->>'title',''),
      nullif(coalesce(r.payload->'errors'->0->>'message',r.payload->'errors'->0->'error_data'->>'details'),''),
      r.payload
    );

    if coalesce((v_status_result->>'ok')::boolean,false) is true then
      update public.whatsapp_webhook_events_v1
      set status='normalized',processed_at=now(),last_error=null
      where id=r.id;
      v_replayed:=v_replayed+1;
    else
      update public.whatsapp_webhook_events_v1
      set status='review_required',processed_at=now(),
          last_error=left(coalesce(v_status_result->>'error','status_replay_failed'),500)
      where id=r.id;
    end if;
  end loop;

  return jsonb_build_object(
    'ok',true,'already_accepted',false,'idempotent',false,
    'outbox_id',v_outbox.id,'message_id',v_message_id,
    'provider_message_id',v_provider_message_id,
    'status_current',(select m.status_current from public.whatsapp_messages_v1 m where m.id=v_message_id),
    'pending_statuses_replayed',v_replayed,'status','sent'
  );
end;
$function$
;

-- function: ops2_admin_attendance_accept_meta_template_outbound_v1(p_outbox_id uuid, p_provider_message_id text, p_accepted_at timestamp with time zone)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_accept_meta_template_outbound_v1(p_outbox_id uuid, p_provider_message_id text, p_accepted_at timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_outbox public.whatsapp_outbox_v1%rowtype;
  v_message public.whatsapp_messages_v1%rowtype;
  v_provider_message_id text:=btrim(coalesce(p_provider_message_id,''));
  v_accepted_at timestamptz:=coalesce(p_accepted_at,now());
  v_message_id uuid;
  v_status_result jsonb;
  v_replayed integer:=0;
  v_status text;
  v_occurred_at timestamptz;
  r public.whatsapp_webhook_events_v1%rowtype;
begin
  if p_outbox_id is null then return jsonb_build_object('ok',false,'error','outbox_required'); end if;
  if v_provider_message_id not like 'wamid.%' or char_length(v_provider_message_id)>500 or v_provider_message_id ~ '[[:cntrl:][:space:]]' then
    return jsonb_build_object('ok',false,'error','provider_message_id_invalid');
  end if;

  select o.* into v_outbox from public.whatsapp_outbox_v1 o where o.id=p_outbox_id for update;
  if not found then return jsonb_build_object('ok',false,'error','outbox_not_found'); end if;
  if v_outbox.provider<>'meta' or v_outbox.purpose<>'human_attendance' or v_outbox.message_type<>'template' or v_outbox.template_id is null then
    return jsonb_build_object('ok',false,'error','outbox_not_meta_template_attendance');
  end if;
  if v_outbox.conversation_id is null then return jsonb_build_object('ok',false,'error','conversation_required'); end if;

  if v_outbox.status='sent' then
    if v_outbox.provider_message_id is distinct from v_provider_message_id or v_outbox.message_id is null then return jsonb_build_object('ok',false,'error','already_sent_mismatch'); end if;
    return jsonb_build_object('ok',true,'already_accepted',true,'idempotent',true,'outbox_id',v_outbox.id,'message_id',v_outbox.message_id,'provider_message_id',v_outbox.provider_message_id,'status','sent');
  end if;
  if v_outbox.status<>'claimed' then return jsonb_build_object('ok',false,'error','outbox_not_claimed','status',v_outbox.status); end if;

  select m.* into v_message from public.whatsapp_messages_v1 m
  where m.whatsapp_account_id=v_outbox.whatsapp_account_id and m.provider_message_id=v_provider_message_id
  order by case when m.provider='meta' then 0 else 1 end,m.created_at,m.id limit 1 for update;

  if found then
    if v_message.conversation_id is distinct from v_outbox.conversation_id then return jsonb_build_object('ok',false,'error','wamid_conversation_conflict'); end if;
    if v_message.direction<>'outbound' then return jsonb_build_object('ok',false,'error','wamid_direction_conflict'); end if;
    update public.whatsapp_messages_v1 m set
      provider='meta',customer_id=coalesce(m.customer_id,v_outbox.customer_id),message_type='template',
      text_body=coalesce(m.text_body,nullif(v_outbox.payload->>'rendered_text','')),
      status_current=case when m.status_current in ('sent','delivered','read','failed','cancelled') then m.status_current else 'accepted' end,
      sender_kind='human',sender_ref=coalesce(nullif(v_outbox.metadata->>'admin_user_id',''),m.sender_ref),sent_at=coalesce(m.sent_at,v_accepted_at),
      metadata=coalesce(m.metadata,'{}'::jsonb)||jsonb_build_object(
        'source','attendance','transport','meta_cloud_api','outbox_id',v_outbox.id,'idempotency_key',v_outbox.idempotency_key,
        'meta_acceptance','accepted','meta_accepted_at',v_accepted_at,'template_id',v_outbox.template_id,
        'template_name',v_outbox.payload#>>'{template,name}','template_language',v_outbox.payload#>>'{template,language,code}',
        'promoted_from_shadow',v_message.provider='papoai'
      )
    where m.id=v_message.id returning * into v_message;
  else
    begin
      insert into public.whatsapp_messages_v1(
        conversation_id,whatsapp_account_id,customer_id,direction,message_type,provider,provider_message_id,
        provider_conversation_id,text_body,status_current,sender_kind,sender_ref,sent_at,metadata
      ) values (
        v_outbox.conversation_id,v_outbox.whatsapp_account_id,v_outbox.customer_id,'outbound','template','meta',v_provider_message_id,
        null,nullif(v_outbox.payload->>'rendered_text',''),'accepted','human',nullif(v_outbox.metadata->>'admin_user_id',''),v_accepted_at,
        jsonb_build_object('source','attendance','transport','meta_cloud_api','outbox_id',v_outbox.id,'idempotency_key',v_outbox.idempotency_key,
          'meta_acceptance','accepted','meta_accepted_at',v_accepted_at,'template_id',v_outbox.template_id,
          'template_name',v_outbox.payload#>>'{template,name}','template_language',v_outbox.payload#>>'{template,language,code}')
      ) returning * into v_message;
    exception when unique_violation then
      select m.* into v_message from public.whatsapp_messages_v1 m
      where m.whatsapp_account_id=v_outbox.whatsapp_account_id and m.provider_message_id=v_provider_message_id
      order by case when m.provider='meta' then 0 else 1 end,m.created_at,m.id limit 1 for update;
      if not found then raise; end if;
      if v_message.conversation_id is distinct from v_outbox.conversation_id or v_message.direction<>'outbound' then return jsonb_build_object('ok',false,'error','wamid_race_conflict'); end if;
      update public.whatsapp_messages_v1 m set provider='meta',message_type='template',sender_kind='human',
        sender_ref=coalesce(nullif(v_outbox.metadata->>'admin_user_id',''),m.sender_ref),
        text_body=coalesce(m.text_body,nullif(v_outbox.payload->>'rendered_text','')),
        status_current=case when m.status_current in ('sent','delivered','read','failed','cancelled') then m.status_current else 'accepted' end,
        sent_at=coalesce(m.sent_at,v_accepted_at),
        metadata=coalesce(m.metadata,'{}'::jsonb)||jsonb_build_object('source','attendance','transport','meta_cloud_api','outbox_id',v_outbox.id,
          'idempotency_key',v_outbox.idempotency_key,'meta_acceptance','accepted','meta_accepted_at',v_accepted_at,'template_id',v_outbox.template_id,
          'template_name',v_outbox.payload#>>'{template,name}','template_language',v_outbox.payload#>>'{template,language,code}','race_reconciled',true)
      where m.id=v_message.id returning * into v_message;
    end;
  end if;

  v_message_id:=v_message.id;
  update public.whatsapp_outbox_v1 set message_id=v_message_id,provider_message_id=v_provider_message_id,status='sent',sent_at=v_accepted_at,last_error=null,
    metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('meta_acceptance','accepted','meta_accepted_at',v_accepted_at,'canonical_message_id',v_message_id),updated_at=now()
  where id=v_outbox.id;

  update public.conversations set
    last_outbound_at=greatest(coalesce(last_outbound_at,'-infinity'::timestamptz),v_accepted_at),
    last_human_message_at=greatest(coalesce(last_human_message_at,'-infinity'::timestamptz),v_accepted_at),
    updated_at=greatest(updated_at,v_accepted_at)
  where id=v_outbox.conversation_id;

  v_status_result:=public.whatsapp_record_status_v1(v_outbox.whatsapp_account_id,'meta',v_provider_message_id,'accepted',v_accepted_at,now(),null,null,null,jsonb_build_object('source','graph_send_response','outbox_id',v_outbox.id));
  if coalesce((v_status_result->>'ok')::boolean,false) is not true then return jsonb_build_object('ok',false,'error','accepted_status_record_failed','detail',v_status_result); end if;

  for r in select e.* from public.whatsapp_webhook_events_v1 e
    where e.whatsapp_account_id=v_outbox.whatsapp_account_id and e.provider='meta' and e.provider_message_id=v_provider_message_id
      and e.event_type like 'message.status.%' and e.status='received'
    order by e.received_at,e.id for update
  loop
    v_status:=split_part(r.event_type,'.',3);
    if v_status not in ('sent','delivered','read','failed','cancelled') then
      update public.whatsapp_webhook_events_v1 set status='ignored',processed_at=now(),last_error='status_not_supported_for_replay' where id=r.id;
      continue;
    end if;
    v_occurred_at:=case when coalesce(r.payload->>'timestamp','') ~ '^\d+(\.\d+)?$' then to_timestamp((r.payload->>'timestamp')::double precision) else r.received_at end;
    v_status_result:=public.whatsapp_record_status_v1(
      v_outbox.whatsapp_account_id,'meta',v_provider_message_id,v_status,v_occurred_at,r.received_at,
      nullif(r.payload->'errors'->0->>'code',''),nullif(r.payload->'errors'->0->>'title',''),
      nullif(coalesce(r.payload->'errors'->0->>'message',r.payload->'errors'->0->'error_data'->>'details'),''),r.payload
    );
    if coalesce((v_status_result->>'ok')::boolean,false) is true then
      update public.whatsapp_webhook_events_v1 set status='normalized',processed_at=now(),last_error=null where id=r.id; v_replayed:=v_replayed+1;
    else
      update public.whatsapp_webhook_events_v1 set status='review_required',processed_at=now(),last_error=left(coalesce(v_status_result->>'error','status_replay_failed'),500) where id=r.id;
    end if;
  end loop;

  return jsonb_build_object('ok',true,'already_accepted',false,'idempotent',false,'outbox_id',v_outbox.id,'message_id',v_message_id,
    'provider_message_id',v_provider_message_id,'status_current',(select m.status_current from public.whatsapp_messages_v1 m where m.id=v_message_id),
    'pending_statuses_replayed',v_replayed,'status','sent');
end;
$function$
;

-- function: ops2_admin_attendance_claim_interactive_outbox_v1(p_outbox_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_claim_interactive_outbox_v1(p_outbox_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_outbox public.whatsapp_outbox_v1%rowtype;
  v_conversation public.conversations%rowtype;
  v_runtime public.whatsapp_channel_runtime_v1%rowtype;
  v_account public.whatsapp_accounts%rowtype;
  v_phone text;
begin
  if p_outbox_id is null then
    return jsonb_build_object('ok', false, 'error', 'outbox_required');
  end if;

  select o.* into v_outbox
  from public.whatsapp_outbox_v1 o
  where o.id = p_outbox_id
  for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'outbox_not_found'); end if;
  if v_outbox.status = 'sent' then
    return jsonb_build_object('ok', true, 'already_sent', true, 'outbox_id', v_outbox.id, 'status', 'sent');
  end if;
  if v_outbox.status <> 'queued' then
    return jsonb_build_object('ok', false, 'error', 'outbox_not_queued', 'status', v_outbox.status);
  end if;
  if v_outbox.purpose <> 'human_attendance'
     or v_outbox.provider <> 'meta'
     or v_outbox.message_type <> 'interactive'
     or v_outbox.payload->>'type' <> 'interactive'
     or v_outbox.payload#>>'{interactive,type}' not in ('button', 'list') then
    return jsonb_build_object('ok', false, 'error', 'outbox_not_dispatchable');
  end if;

  select c.* into v_conversation
  from public.conversations c
  where c.id = v_outbox.conversation_id;
  if not found or v_conversation.whatsapp_account_id is null
     or v_conversation.whatsapp_account_id is distinct from v_outbox.whatsapp_account_id then
    return jsonb_build_object('ok', false, 'error', 'conversation_account_mismatch');
  end if;
  select wa.* into v_account
  from public.whatsapp_accounts wa
  where wa.id = v_conversation.whatsapp_account_id and wa.is_active = true;
  if not found then return jsonb_build_object('ok', false, 'error', 'account_unavailable'); end if;

  v_phone := public.canonical_whatsapp_e164_br_v2(v_conversation.wa_contact_e164);
  if v_phone is null or v_phone is distinct from public.canonical_whatsapp_e164_br_v2(v_outbox.to_phone_e164) then
    return jsonb_build_object('ok', false, 'error', 'destination_mismatch');
  end if;
  if v_conversation.last_inbound_at is null
     or now() >= v_conversation.last_inbound_at + interval '24 hours' then
    return jsonb_build_object('ok', false, 'error', 'service_window_closed');
  end if;

  select r.* into v_runtime
  from public.whatsapp_channel_runtime_v1 r
  where r.whatsapp_account_id = v_conversation.whatsapp_account_id
    and r.send_enabled = true and r.human_send_enabled = true
    and r.homologated_at is not null and r.outbound_provider = 'meta';
  if not found then return jsonb_build_object('ok', false, 'error', 'human_send_not_homologated'); end if;
  if lower(coalesce(v_runtime.metadata->>'meta_canary_enabled', 'false')) = 'true'
     and not exists (
       select 1 from jsonb_array_elements_text(
         case when jsonb_typeof(v_runtime.metadata->'meta_canary_to_e164') = 'array'
           then v_runtime.metadata->'meta_canary_to_e164' else '[]'::jsonb end
       ) allowed(value)
       where public.canonical_whatsapp_e164_br_v2(allowed.value) = v_phone
     ) then
    return jsonb_build_object('ok', false, 'error', 'meta_canary_destination_blocked');
  end if;

  update public.whatsapp_outbox_v1
  set status = 'claimed', claimed_at = now(), attempt_count = attempt_count + 1, updated_at = now()
  where id = v_outbox.id and status = 'queued';
  if not found then return jsonb_build_object('ok', false, 'error', 'outbox_claim_race'); end if;

  return jsonb_build_object(
    'ok', true, 'already_sent', false, 'outbox_id', v_outbox.id,
    'conversation_id', v_outbox.conversation_id, 'whatsapp_account_id', v_outbox.whatsapp_account_id,
    'customer_id', v_outbox.customer_id, 'provider', v_outbox.provider,
    'account_slug', v_account.slug, 'account_phone_e164', v_account.phone_e164,
    'phone_number_id', v_account.phone_number_id,
    'waba_id', v_account.waba_id, 'to_phone_e164', v_phone,
    'interactive_payload', v_outbox.payload, 'idempotency_key', v_outbox.idempotency_key,
    'admin_user_id', v_outbox.metadata->>'admin_user_id', 'status', 'claimed'
  );
end;
$function$
;

-- function: ops2_admin_attendance_claim_media_outbox_v1(p_outbox_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_claim_media_outbox_v1(p_outbox_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_outbox public.whatsapp_outbox_v1%rowtype;
  v_conversation public.conversations%rowtype;
  v_runtime public.whatsapp_channel_runtime_v1%rowtype;
  v_account public.whatsapp_accounts%rowtype;
  v_phone text;
  v_mime_type text;
  v_filename text;
  v_size_bytes bigint;
  v_sha256 text;
  v_caption text;
begin
  if p_outbox_id is null then return jsonb_build_object('ok',false,'error','outbox_required'); end if;

  select o.* into v_outbox
  from public.whatsapp_outbox_v1 o
  where o.id=p_outbox_id
  for update;
  if not found then return jsonb_build_object('ok',false,'error','outbox_not_found'); end if;
  if v_outbox.status='sent' then
    return jsonb_build_object('ok',true,'already_sent',true,'outbox_id',v_outbox.id,'provider',v_outbox.provider,'status','sent');
  end if;
  if v_outbox.status<>'queued' then
    return jsonb_build_object('ok',false,'error','outbox_not_queued','status',v_outbox.status);
  end if;
  if v_outbox.purpose<>'human_attendance'
     or v_outbox.provider<>'meta'
     or v_outbox.message_type not in ('image','audio','video','document') then
    return jsonb_build_object('ok',false,'error','outbox_not_dispatchable');
  end if;

  select c.* into v_conversation
  from public.conversations c
  where c.id=v_outbox.conversation_id;
  if not found
     or v_conversation.whatsapp_account_id is null
     or v_conversation.whatsapp_account_id is distinct from v_outbox.whatsapp_account_id then
    return jsonb_build_object('ok',false,'error','conversation_account_mismatch');
  end if;

  select wa.* into v_account
  from public.whatsapp_accounts wa
  where wa.id=v_conversation.whatsapp_account_id and wa.is_active=true;
  if not found then return jsonb_build_object('ok',false,'error','account_unavailable'); end if;

  v_phone:=public.canonical_whatsapp_e164_br_v2(v_conversation.wa_contact_e164);
  if v_phone is null
     or v_phone is distinct from public.canonical_whatsapp_e164_br_v2(v_outbox.to_phone_e164) then
    return jsonb_build_object('ok',false,'error','destination_mismatch');
  end if;

  if v_conversation.last_inbound_at is null
     or now()>=v_conversation.last_inbound_at+interval '24 hours' then
    return jsonb_build_object('ok',false,'error','service_window_closed');
  end if;

  select r.* into v_runtime
  from public.whatsapp_channel_runtime_v1 r
  where r.whatsapp_account_id=v_conversation.whatsapp_account_id
    and r.send_enabled=true
    and r.human_send_enabled=true
    and r.homologated_at is not null;
  if not found then return jsonb_build_object('ok',false,'error','human_send_not_homologated'); end if;
  if v_runtime.outbound_provider<>'meta' then return jsonb_build_object('ok',false,'error','media_provider_unavailable'); end if;

  if lower(coalesce(v_runtime.metadata->>'meta_canary_enabled','false'))='true'
     and not exists (
       select 1
       from jsonb_array_elements_text(
         case
           when jsonb_typeof(v_runtime.metadata->'meta_canary_to_e164')='array'
             then v_runtime.metadata->'meta_canary_to_e164'
           else '[]'::jsonb
         end
       ) as allowed(value)
       where public.canonical_whatsapp_e164_br_v2(allowed.value)=v_phone
     ) then
    return jsonb_build_object('ok',false,'error','meta_canary_destination_blocked');
  end if;

  v_mime_type:=lower(coalesce(v_outbox.payload->>'mime_type',''));
  v_filename:=coalesce(v_outbox.payload->>'filename','');
  v_size_bytes:=coalesce((v_outbox.payload->>'size_bytes')::bigint,0);
  v_sha256:=lower(coalesce(v_outbox.payload->>'sha256',''));
  v_caption:=nullif(coalesce(v_outbox.payload->>'caption',''),'');
  if (v_outbox.message_type='image' and v_mime_type not in ('image/jpeg','image/png'))
     or (v_outbox.message_type='audio' and v_mime_type not in ('audio/aac','audio/amr','audio/mpeg','audio/mp4','audio/ogg'))
     or (v_outbox.message_type='video' and v_mime_type not in ('video/mp4','video/3gpp'))
     or (v_outbox.message_type='document' and v_mime_type not in (
       'application/pdf','text/plain','application/msword',
       'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
       'application/vnd.ms-excel','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
       'application/vnd.ms-powerpoint','application/vnd.openxmlformats-officedocument.presentationml.presentation'
     ))
     or v_filename='' or char_length(v_filename)>240 or v_filename ~ '[[:cntrl:]\\/]'
     or v_size_bytes<1
     or (v_outbox.message_type='image' and v_size_bytes>5242880)
     or (v_outbox.message_type in ('audio','video') and v_size_bytes>16777216)
     or (v_outbox.message_type='document' and v_size_bytes>26214400)
     or v_sha256 !~ '^[0-9a-f]{64}$'
     or (v_caption is not null and char_length(v_caption)>1024) then
    return jsonb_build_object('ok',false,'error','outbox_media_invalid');
  end if;
  if v_outbox.message_type='audio' then v_caption:=null; end if;

  update public.whatsapp_outbox_v1
  set status='claimed',claimed_at=now(),attempt_count=attempt_count+1,updated_at=now()
  where id=v_outbox.id and status='queued';
  if not found then return jsonb_build_object('ok',false,'error','outbox_claim_race'); end if;

  return jsonb_build_object(
    'ok',true,'already_sent',false,'outbox_id',v_outbox.id,
    'conversation_id',v_outbox.conversation_id,'whatsapp_account_id',v_outbox.whatsapp_account_id,
    'provider','meta','account_phone_e164',v_account.phone_e164,
    'phone_number_id',v_account.phone_number_id,'waba_id',v_account.waba_id,
    'to_phone_e164',v_phone,'message_type',v_outbox.message_type,
    'mime_type',v_mime_type,'filename',v_filename,'size_bytes',v_size_bytes,
    'sha256',v_sha256,'caption',v_caption,'idempotency_key',v_outbox.idempotency_key,
    'status','claimed'
  );
end;
$function$
;

-- function: ops2_admin_attendance_claim_outbox_v1(p_outbox_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_claim_outbox_v1(p_outbox_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_outbox public.whatsapp_outbox_v1%rowtype;
  v_conversation public.conversations%rowtype;
  v_runtime public.whatsapp_channel_runtime_v1%rowtype;
  v_account public.whatsapp_accounts%rowtype;
  v_phone text;
  v_text text;
begin
  if p_outbox_id is null then
    return jsonb_build_object('ok',false,'error','outbox_required');
  end if;

  select o.* into v_outbox
  from public.whatsapp_outbox_v1 o
  where o.id=p_outbox_id
  for update;

  if not found then
    return jsonb_build_object('ok',false,'error','outbox_not_found');
  end if;

  if v_outbox.status='sent' then
    return jsonb_build_object('ok',true,'already_sent',true,'outbox_id',v_outbox.id,'message_id',v_outbox.message_id,'status','sent');
  end if;

  if v_outbox.status<>'queued' then
    return jsonb_build_object('ok',false,'error','outbox_not_queued','status',v_outbox.status);
  end if;

  if v_outbox.purpose<>'human_attendance'
     or v_outbox.provider<>'papoai'
     or v_outbox.message_type<>'text' then
    return jsonb_build_object('ok',false,'error','outbox_not_dispatchable');
  end if;

  select c.* into v_conversation
  from public.conversations c
  where c.id=v_outbox.conversation_id;

  if not found
     or v_conversation.whatsapp_account_id is null
     or v_conversation.whatsapp_account_id is distinct from v_outbox.whatsapp_account_id then
    return jsonb_build_object('ok',false,'error','conversation_account_mismatch');
  end if;

  select wa.* into v_account
  from public.whatsapp_accounts wa
  where wa.id=v_conversation.whatsapp_account_id
    and wa.is_active=true;

  if not found then
    return jsonb_build_object('ok',false,'error','account_unavailable');
  end if;

  v_phone:=public.canonical_whatsapp_e164_br_v2(v_conversation.wa_contact_e164);
  if v_phone is null
     or v_phone is distinct from public.canonical_whatsapp_e164_br_v2(v_outbox.to_phone_e164) then
    return jsonb_build_object('ok',false,'error','destination_mismatch');
  end if;

  if v_conversation.last_inbound_at is null
     or now()>=v_conversation.last_inbound_at+interval '24 hours' then
    return jsonb_build_object('ok',false,'error','service_window_closed');
  end if;

  select r.* into v_runtime
  from public.whatsapp_channel_runtime_v1 r
  where r.whatsapp_account_id=v_conversation.whatsapp_account_id
    and r.outbound_provider='papoai'
    and r.send_enabled=true
    and r.human_send_enabled=true
    and r.homologated_at is not null;

  if not found then
    return jsonb_build_object('ok',false,'error','human_send_not_homologated');
  end if;

  v_text:=btrim(coalesce(v_outbox.payload->>'text',''));
  if v_text='' or char_length(v_text)>4000 then
    return jsonb_build_object('ok',false,'error','outbox_text_invalid');
  end if;

  update public.whatsapp_outbox_v1
     set status='claimed',
         claimed_at=now(),
         attempt_count=attempt_count+1,
         updated_at=now()
   where id=v_outbox.id
     and status='queued';

  if not found then
    return jsonb_build_object('ok',false,'error','outbox_claim_race');
  end if;

  update public.whatsapp_messages_v1
     set status_current='sending'
   where id=v_outbox.message_id
     and conversation_id=v_outbox.conversation_id
     and status_current='queued';

  return jsonb_build_object(
    'ok',true,
    'already_sent',false,
    'outbox_id',v_outbox.id,
    'message_id',v_outbox.message_id,
    'conversation_id',v_outbox.conversation_id,
    'whatsapp_account_id',v_outbox.whatsapp_account_id,
    'account_phone_e164',v_account.phone_e164,
    'to_phone_e164',v_phone,
    'text',v_text,
    'idempotency_key',v_outbox.idempotency_key,
    'status','claimed'
  );
end;
$function$
;

