  select o.* into v_outbox from public.whatsapp_outbox_v1 o where o.id=p_outbox_id for update;
  if not found then return jsonb_build_object('ok',false,'error','outbox_not_found'); end if;
  if v_outbox.status='sent' then return jsonb_build_object('ok',true,'already_sent',true,'outbox_id',v_outbox.id,'provider',v_outbox.provider,'status','sent'); end if;
  if v_outbox.status<>'queued' then return jsonb_build_object('ok',false,'error','outbox_not_queued','status',v_outbox.status); end if;
  if v_outbox.purpose<>'human_attendance' or v_outbox.provider<>'meta' or v_outbox.message_type<>'template' or v_outbox.template_id is null then
    return jsonb_build_object('ok',false,'error','outbox_not_dispatchable');
  end if;

  select c.* into v_conversation from public.conversations c where c.id=v_outbox.conversation_id;
  if not found or v_conversation.whatsapp_account_id is null or v_conversation.whatsapp_account_id is distinct from v_outbox.whatsapp_account_id then
    return jsonb_build_object('ok',false,'error','conversation_account_mismatch');
  end if;
  select wa.* into v_account from public.whatsapp_accounts wa where wa.id=v_conversation.whatsapp_account_id and wa.is_active=true;
  if not found then return jsonb_build_object('ok',false,'error','account_unavailable'); end if;
  v_phone:=public.canonical_whatsapp_e164_br_v2(v_conversation.wa_contact_e164);
  if v_phone is null or v_phone is distinct from public.canonical_whatsapp_e164_br_v2(v_outbox.to_phone_e164) then
    return jsonb_build_object('ok',false,'error','destination_mismatch');
  end if;

  select r.* into v_runtime from public.whatsapp_channel_runtime_v1 r
  where r.whatsapp_account_id=v_conversation.whatsapp_account_id
    and r.send_enabled=true and r.human_send_enabled=true and r.homologated_at is not null
    and r.outbound_provider='meta' and lower(coalesce(r.metadata->>'meta_send_homologated','false'))='true';
  if not found then return jsonb_build_object('ok',false,'error','meta_template_send_not_homologated'); end if;
  if lower(coalesce(v_runtime.metadata->>'meta_canary_enabled','false'))='true'
     and not exists(
       select 1 from jsonb_array_elements_text(case when jsonb_typeof(v_runtime.metadata->'meta_canary_to_e164')='array' then v_runtime.metadata->'meta_canary_to_e164' else '[]'::jsonb end) allowed(value)
       where public.canonical_whatsapp_e164_br_v2(allowed.value)=v_phone
     ) then return jsonb_build_object('ok',false,'error','meta_canary_destination_blocked'); end if;

  select t.* into v_template from public.whatsapp_templates_v1 t
  where t.id=v_outbox.template_id and t.whatsapp_account_id=v_outbox.whatsapp_account_id
    and upper(coalesce(t.status,''))='APPROVED'
    and lower(coalesce(t.metadata->'attendance'->>'enabled','false'))='true';
  if not found then return jsonb_build_object('ok',false,'error','template_not_sendable'); end if;
  if coalesce(v_outbox.payload#>>'{template,name}','')<>v_template.name
     or coalesce(v_outbox.payload#>>'{template,language,code}','')<>v_template.language then
    return jsonb_build_object('ok',false,'error','template_payload_mismatch');
  end if;

  update public.whatsapp_outbox_v1 set status='claimed',claimed_at=now(),attempt_count=attempt_count+1,updated_at=now()
  where id=v_outbox.id and status='queued';
  if not found then return jsonb_build_object('ok',false,'error','outbox_claim_race'); end if;

  return jsonb_build_object(
    'ok',true,'already_sent',false,'outbox_id',v_outbox.id,'conversation_id',v_outbox.conversation_id,
    'whatsapp_account_id',v_outbox.whatsapp_account_id,'provider','meta','account_phone_e164',v_account.phone_e164,
    'phone_number_id',v_account.phone_number_id,'waba_id',v_account.waba_id,'to_phone_e164',v_phone,
    'template_id',v_template.id,'template_name',v_template.name,'language_code',v_template.language,
    'components',coalesce(v_outbox.payload#>'{template,components}','[]'::jsonb),
    'rendered_text',coalesce(v_outbox.payload->>'rendered_text',''),'idempotency_key',v_outbox.idempotency_key,'status','claimed'
  );
end;
$function$
;

-- function: ops2_admin_attendance_context_v1(p_conversation_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_context_v1(p_conversation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_conversation public.conversations%rowtype;
  v_customer public.customers%rowtype;
  v_address public.customer_addresses%rowtype;
  v_registration jsonb;
  v_orders jsonb := '[]'::jsonb;
  v_doc_digits text;
  v_doc_masked text;
begin
  select c.* into v_conversation
  from public.conversations c
  where c.id=p_conversation_id;

  if not found then
    return jsonb_build_object('ok',false,'error','conversation_not_found');
  end if;

  if v_conversation.customer_id is not null then
    select cu.* into v_customer
    from public.customers cu
    where cu.id=v_conversation.customer_id;

    if found then
      select a.* into v_address
      from public.customer_addresses a
      where a.customer_id=v_customer.id and a.is_active=true
      order by a.is_default desc,a.updated_at desc,a.created_at desc,a.id
      limit 1;

      v_registration:=public.ops2_customer_registration_state_v1(v_customer.id);
      v_doc_digits:=regexp_replace(coalesce(v_customer.cpf_cnpj,''),'\D','','g');
      if length(v_doc_digits)>=4 then
        v_doc_masked:=repeat('*',greatest(0,length(v_doc_digits)-4))||right(v_doc_digits,4);
      else
        v_doc_masked:=null;
      end if;

      with recent_orders as (
        select o.*
        from public.orders o
        where o.customer_id=v_customer.id
        order by coalesce(o.confirmed_at,o.created_at) desc,o.created_at desc,o.id desc
        limit 10
      )
      select coalesce(jsonb_agg(jsonb_build_object(
        'id',o.id,
        'order_number',o.order_number,
        'status',o.status,
        'total',o.total,
        'currency',btrim(o.currency),
        'source',o.source,
        'payment_method',o.payment_method,
        'confirmed_at',o.confirmed_at,
        'created_at',o.created_at,
        'items',coalesce((
          select jsonb_agg(jsonb_build_object(
            'id',oi.id,
            'product_id',oi.product_id,
            'name',oi.name_snapshot,
            'sku',oi.sku_snapshot,
            'quantity',oi.quantity,
            'unit_price',oi.unit_price,
            'line_total',oi.line_total
          ) order by oi.created_at,oi.id)
          from public.order_items oi
          where oi.order_id=o.id
        ),'[]'::jsonb)
      ) order by coalesce(o.confirmed_at,o.created_at) desc,o.created_at desc,o.id desc),'[]'::jsonb)
      into v_orders
      from recent_orders o;
    end if;
  end if;

  return jsonb_build_object(
    'ok',true,
    'conversation',jsonb_build_object(
      'id',v_conversation.id,
      'whatsapp_account_id',v_conversation.whatsapp_account_id,
      'customer_id',v_conversation.customer_id,
      'phone_e164',public.canonical_whatsapp_e164_br_v2(v_conversation.wa_contact_e164),
      'status',v_conversation.status,
      'mode',v_conversation.mode,
      'human_required',coalesce(v_conversation.human_required,false),
      'last_inbound_at',v_conversation.last_inbound_at,
      'last_outbound_at',v_conversation.last_outbound_at,
      'service_window_expires_at',v_conversation.service_window_expires_at
    ),
    'customer',case when v_customer.id is null then null else jsonb_build_object(
      'id',v_customer.id,
      'name',v_customer.name,
      'phone_e164',public.canonical_whatsapp_e164_br_v2(v_customer.primary_whatsapp_e164),
      'masked_document',v_doc_masked,
      'marketing_opt_in',v_customer.marketing_opt_in,
      'marketing_consent_updated_at',v_customer.marketing_consent_updated_at,
      'last_order_at',v_customer.last_order_at,
      'order_count',coalesce(v_customer.order_count,0),
      'lifetime_value',coalesce(v_customer.lifetime_value,0),
      'preferred_reply',v_customer.preferred_reply
    ) end,
    'address',case when v_address.id is null then null else jsonb_build_object(
      'id',v_address.id,
      'label',v_address.label,
      'street',v_address.street,
      'number',v_address.number,
      'complement',v_address.complement,
      'neighborhood',v_address.neighborhood,
      'city',v_address.city,
      'state',v_address.state,
      'postal_code',v_address.postal_code,
      'reference',v_address.reference,
      'is_default',v_address.is_default
    ) end,
    'registration',v_registration,
    'orders',v_orders
  );
end;
$function$
;

-- function: ops2_admin_attendance_conversation_v1(p_conversation_id uuid, p_before timestamp with time zone, p_limit integer)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_conversation_v1(p_conversation_id uuid, p_before timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_limit integer := least(50,greatest(1,coalesce(p_limit,30)));
  v_conversation public.conversations%rowtype;
  v_account public.whatsapp_accounts%rowtype;
  v_messages jsonb;
  v_oldest timestamptz;
begin
  select c.* into v_conversation
  from public.conversations c
  where c.id=p_conversation_id;

  if not found then
    return jsonb_build_object('ok',false,'error','conversation_not_found');
  end if;

  select wa.* into v_account
  from public.whatsapp_accounts wa
  where wa.id=v_conversation.whatsapp_account_id and wa.is_active=true;

  if not found then
    return jsonb_build_object('ok',false,'error','whatsapp_account_not_found');
  end if;

  with selected as (
    select
      m.id,
      m.conversation_id,
      m.whatsapp_account_id,
      m.customer_id,
      m.direction,
      m.message_type,
      m.provider,
      m.provider_message_id,
      m.reply_to_message_id,
      m.text_body,
      m.status_current,
      m.sender_kind,
      m.sender_ref,
      m.metadata,
      coalesce(m.received_at,m.sent_at,m.created_at) as message_at,
      m.created_at
    from public.whatsapp_messages_v1 m
    where m.conversation_id=p_conversation_id
      and m.whatsapp_account_id=v_conversation.whatsapp_account_id
      and (p_before is null or coalesce(m.received_at,m.sent_at,m.created_at)<p_before)
    order by coalesce(m.received_at,m.sent_at,m.created_at) desc,m.created_at desc,m.id desc
    limit v_limit
  ), chronological as (
    select * from selected
    order by message_at asc,created_at asc,id asc
  )
  select
    coalesce(jsonb_agg(jsonb_build_object(
      'id',m.id,
      'conversation_id',m.conversation_id,
      'whatsapp_account_id',m.whatsapp_account_id,
      'customer_id',m.customer_id,
      'direction',m.direction,
      'message_type',m.message_type,
      'provider',m.provider,
      'provider_message_id',m.provider_message_id,
      'reply_to_message_id',m.reply_to_message_id,
      'text_body',case
        when lower(coalesce(m.metadata->>'raw_type',''))='unsupported'
          then 'Mensagem recebida, mas o provedor não disponibilizou o conteúdo. Abra o WhatsApp no celular para visualizar.'
        else m.text_body
      end,
      'status_current',m.status_current,
      'sender_kind',m.sender_kind,
      'sender_ref',m.sender_ref,
      'message_at',m.message_at,
      'metadata',m.metadata
    ) order by m.message_at asc,m.created_at asc,m.id asc),'[]'::jsonb),
    min(m.message_at)
  into v_messages,v_oldest
  from chronological m;

  return jsonb_build_object(
    'ok',true,
    'conversation',jsonb_build_object(
      'id',v_conversation.id,
      'whatsapp_account_id',v_conversation.whatsapp_account_id,
      'customer_id',v_conversation.customer_id,
      'phone_e164',public.canonical_whatsapp_e164_br_v2(v_conversation.wa_contact_e164),
      'status',v_conversation.status,
      'stage',v_conversation.stage,
      'mode',v_conversation.mode,
      'human_required',coalesce(v_conversation.human_required,false),
      'last_inbound_at',v_conversation.last_inbound_at,
      'last_outbound_at',v_conversation.last_outbound_at,
      'service_window_expires_at',v_conversation.service_window_expires_at,
      'opened_at',v_conversation.opened_at
    ),
    'account',jsonb_build_object(
      'id',v_account.id,
      'slug',v_account.slug,
      'display_name',v_account.display_name,
      'phone_e164',v_account.phone_e164
    ),
    'limit',v_limit,
    'before',p_before,
    'next_before',v_oldest,
    'messages',v_messages
  );
end;
$function$
;

-- function: ops2_admin_attendance_customer_access_v1(p_write boolean)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_customer_access_v1(p_write boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user uuid:=auth.uid();
  v_role text;
begin
  if v_user is null then
    return jsonb_build_object('ok',false,'error','admin_not_authorized');
  end if;

  select coalesce(a.role,'viewer') into v_role
  from public.admin_users a
  where a.user_id=v_user and a.is_active=true
  limit 1;

  if not found then
    return jsonb_build_object('ok',false,'error','admin_not_authorized');
  end if;

  if coalesce(p_write,false) and v_role='viewer' then
    return jsonb_build_object('ok',false,'error','admin_write_forbidden','role',v_role);
  end if;

  return jsonb_build_object('ok',true,'user_id',v_user,'role',v_role,'write_allowed',v_role<>'viewer');
end;
$function$
;

-- function: ops2_admin_attendance_customer_create_browser_v1(p_conversation_id uuid, p_customer jsonb)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_customer_create_browser_v1(p_conversation_id uuid, p_customer jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_access jsonb:=public.ops2_admin_attendance_customer_access_v1(true);
  v_existing_customer uuid;
  v_phone text;
  v_payload jsonb;
  v_saved jsonb;
  v_linked jsonb;
  v_customer_id uuid;
begin
  if coalesce((v_access->>'ok')::boolean,false) is not true then return v_access; end if;
  if p_conversation_id is null then return jsonb_build_object('ok',false,'error','invalid_conversation_id'); end if;

  perform pg_advisory_xact_lock(hashtextextended('attendance-customer:'||p_conversation_id::text,0));

  select c.customer_id,public.canonical_whatsapp_e164_br_v2(c.wa_contact_e164)
  into v_existing_customer,v_phone
  from public.conversations c
  where c.id=p_conversation_id
  for update;

  if not found then return jsonb_build_object('ok',false,'error','conversation_not_found'); end if;
  if v_existing_customer is not null then
    return jsonb_build_object('ok',false,'error','conversation_already_linked','customer_id',v_existing_customer);
  end if;
  if v_phone is null then return jsonb_build_object('ok',false,'error','invalid_phone'); end if;

  v_payload:=jsonb_build_object(
    'id',null,
    'display_name',p_customer->>'display_name',
    'phone',v_phone,
    'cpf',p_customer->>'cpf',
    'email',p_customer->>'email',
    'status','active',
    'address',coalesce(p_customer->'address','{}'::jsonb)
  );

  v_saved:=public.ops2_admin_customer_save_v2(v_payload);
  if coalesce((v_saved->>'ok')::boolean,false) is not true then return v_saved; end if;

  begin v_customer_id:=(v_saved->>'customer_id')::uuid;
  exception when invalid_text_representation then v_customer_id:=null; end;
  if v_customer_id is null then return jsonb_build_object('ok',false,'error','customer_save_failed'); end if;

  v_linked:=public.ops2_admin_attendance_link_customer_v1(p_conversation_id,v_customer_id);
  if coalesce((v_linked->>'ok')::boolean,false) is not true then
    return v_linked||jsonb_build_object('created_customer_id',v_customer_id);
  end if;

  return jsonb_build_object('ok',true,'created',true,'linked',true,'customer_id',v_customer_id,'phone_e164',v_phone);
end;
$function$
;

-- function: ops2_admin_attendance_customer_editor_browser_v1(p_conversation_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_customer_editor_browser_v1(p_conversation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_access jsonb:=public.ops2_admin_attendance_customer_access_v1(false);
  v_customer_id uuid;
  v_conversation_phone text;
  v_customer record;
  v_email text;
  v_address record;
begin
  if coalesce((v_access->>'ok')::boolean,false) is not true then return v_access; end if;
  if p_conversation_id is null then return jsonb_build_object('ok',false,'error','invalid_conversation_id'); end if;

  select c.customer_id,public.canonical_whatsapp_e164_br_v2(c.wa_contact_e164)
  into v_customer_id,v_conversation_phone
  from public.conversations c
  where c.id=p_conversation_id;

  if not found then return jsonb_build_object('ok',false,'error','conversation_not_found'); end if;
  if v_customer_id is null then return jsonb_build_object('ok',false,'error','customer_not_linked'); end if;

  select c.id,c.name,c.primary_whatsapp_e164,c.cpf_cnpj,c.is_active,c.birthday_day,c.birthday_month
  into v_customer
  from public.customers c
  where c.id=v_customer_id;
  if not found then return jsonb_build_object('ok',false,'error','customer_not_found'); end if;

  select ce.email into v_email
  from public.customer_emails ce
  where ce.customer_id=v_customer_id
  order by ce.is_primary desc,ce.created_at desc
  limit 1;

  select ca.street,ca.number,ca.complement,ca.neighborhood,ca.city,ca.state,ca.postal_code,ca.reference
  into v_address
  from public.customer_addresses ca
  where ca.customer_id=v_customer_id and ca.is_active=true
  order by ca.is_default desc,ca.updated_at desc,ca.id
  limit 1;

  return jsonb_build_object(
    'ok',true,
    'conversation_id',p_conversation_id,
    'conversation_phone_e164',v_conversation_phone,
    'customer',jsonb_build_object(
      'id',v_customer.id,
      'display_name',coalesce(v_customer.name,''),
      'phone_e164',v_customer.primary_whatsapp_e164,
      'cpf',v_customer.cpf_cnpj,
      'email',v_email,
      'status',case when v_customer.is_active=false then 'inactive' else 'active' end,
      'birthday_day',v_customer.birthday_day,
      'birthday_month',v_customer.birthday_month,
      'address',case when v_address is null then '{}'::jsonb else jsonb_build_object(
        'street',v_address.street,
        'number',v_address.number,
        'complement',v_address.complement,
        'district',v_address.neighborhood,
        'city',v_address.city,
        'state',v_address.state,
        'postal_code',v_address.postal_code,
        'raw_text',v_address.reference
      ) end
    )
  );
end;
$function$
;

-- function: ops2_admin_attendance_customer_editor_safe_browser_v1(p_conversation_id uuid, p_address_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_customer_editor_safe_browser_v1(p_conversation_id uuid, p_address_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_access jsonb;
  v_customer_id uuid;
  v_conversation_phone text;
  v_customer record;
  v_email text;
  v_address_count integer;
  v_default_count integer;
  v_selected_address_id uuid;
  v_address_options jsonb;
begin
  v_access := public.ops2_admin_attendance_customer_access_v1(false);
  if coalesce((v_access ->> 'ok')::boolean, false) is distinct from true then
    return v_access;
  end if;
  if p_conversation_id is null then
    return jsonb_build_object('ok', false, 'error', 'invalid_conversation_id');
  end if;

  select c.customer_id, public.canonical_whatsapp_e164_br_v2(c.wa_contact_e164)
  into v_customer_id, v_conversation_phone
  from public.conversations c
  where c.id = p_conversation_id;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'conversation_not_found');
  end if;
  if v_customer_id is null then
    return jsonb_build_object('ok', false, 'error', 'customer_not_linked');
  end if;

  select c.id, c.name, c.primary_whatsapp_e164, c.cpf_cnpj, c.is_active, c.updated_at
  into v_customer
  from public.customers c
  where c.id = v_customer_id;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'customer_not_found');
  end if;

  select ce.email
  into v_email
  from public.customer_emails ce
  where ce.customer_id = v_customer_id
  order by ce.is_primary desc, ce.created_at desc
  limit 1;

  select count(*)::integer, count(*) filter (where ca.is_default)::integer
  into v_address_count, v_default_count
  from public.customer_addresses ca
  where ca.customer_id = v_customer_id and ca.is_active = true;
  if v_address_count > 20 then
    return jsonb_build_object('ok', false, 'error', 'address_list_too_large');
  end if;

  if p_address_id is not null then
    perform 1
    from public.customer_addresses ca
    where ca.id = p_address_id
      and ca.customer_id = v_customer_id
      and ca.is_active = true;
    if not found then
      return jsonb_build_object('ok', false, 'error', 'invalid_address');
    end if;
    v_selected_address_id := p_address_id;
  elsif v_default_count = 1 then
    select ca.id into v_selected_address_id
    from public.customer_addresses ca
    where ca.customer_id = v_customer_id
      and ca.is_active = true
      and ca.is_default = true
    order by ca.updated_at desc, ca.id
    limit 1;
  elsif v_default_count = 0 and v_address_count = 1 then
    select ca.id into v_selected_address_id
    from public.customer_addresses ca
    where ca.customer_id = v_customer_id and ca.is_active = true
    limit 1;
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', address_row.id,
        'label', coalesce(nullif(btrim(address_row.label), ''), nullif(btrim(address_row.street), ''), 'Endereço'),
        'street', coalesce(address_row.street, ''),
        'number', coalesce(address_row.number, ''),
        'complement', coalesce(address_row.complement, ''),
        'neighborhood', coalesce(address_row.neighborhood, ''),
        'city', coalesce(address_row.city, ''),
        'state', coalesce(address_row.state, ''),
        'postal_code', coalesce(address_row.postal_code, ''),
        'reference', coalesce(address_row.reference, ''),
        'is_default', address_row.is_default,
        'updated_at', address_row.updated_at
      ) order by address_row.is_default desc, address_row.updated_at desc, address_row.id
    ),
    '[]'::jsonb
  )
  into v_address_options
  from (
    select ca.id, ca.label, ca.street, ca.number, ca.complement,
      ca.neighborhood, ca.city, ca.state, ca.postal_code, ca.reference,
      ca.is_default, ca.updated_at
    from public.customer_addresses ca
    where ca.customer_id = v_customer_id and ca.is_active = true
    order by ca.is_default desc, ca.updated_at desc, ca.id
    limit 20
  ) address_row;

  return jsonb_build_object(
    'ok', true,
    'conversation_id', p_conversation_id,
    'conversation_phone_e164', v_conversation_phone,
    'selected_address_id', v_selected_address_id,
    'address_requires_choice', v_address_count > 1 and v_selected_address_id is null,
    'customer', jsonb_build_object(
      'id', v_customer.id,
      'updated_at', v_customer.updated_at,
      'display_name', coalesce(v_customer.name, ''),
      'phone_e164', v_customer.primary_whatsapp_e164,
      'masked_document', case
        when v_customer.cpf_cnpj is null then null
        when length(regexp_replace(v_customer.cpf_cnpj, '[^0-9]', '', 'g')) = 11
          then '***.***.' || right(regexp_replace(v_customer.cpf_cnpj, '[^0-9]', '', 'g'), 3) || '-**'
        when length(regexp_replace(v_customer.cpf_cnpj, '[^0-9]', '', 'g')) = 14
          then '**.***.***/****-' || right(regexp_replace(v_customer.cpf_cnpj, '[^0-9]', '', 'g'), 2)
        else 'Documento salvo'
      end,
      'email', v_email,
      'status', case when v_customer.is_active = false then 'inactive' else 'active' end
    ),
    'addresses', v_address_options
  );
end;
$function$
;

-- function: ops2_admin_attendance_customer_link_browser_v1(p_conversation_id uuid, p_customer_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_customer_link_browser_v1(p_conversation_id uuid, p_customer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_access jsonb:=public.ops2_admin_attendance_customer_access_v1(true);
begin
  if coalesce((v_access->>'ok')::boolean,false) is not true then return v_access; end if;
  if p_conversation_id is null then return jsonb_build_object('ok',false,'error','invalid_conversation_id'); end if;
  if p_customer_id is null then return jsonb_build_object('ok',false,'error','invalid_customer_id'); end if;
  return public.ops2_admin_attendance_link_customer_v1(p_conversation_id,p_customer_id);
end;
$function$
;

-- function: ops2_admin_attendance_customer_reconcile_browser_v1(p_conversation_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_customer_reconcile_browser_v1(p_conversation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_access jsonb:=public.ops2_admin_attendance_customer_access_v1(true);
begin
  if coalesce((v_access->>'ok')::boolean,false) is not true then return v_access; end if;
  if p_conversation_id is null then return jsonb_build_object('ok',false,'error','invalid_conversation_id'); end if;
  return public.ops2_admin_attendance_reconcile_customer_v1(p_conversation_id);
end;
$function$
;

-- function: ops2_admin_attendance_customer_save_browser_v1(p_conversation_id uuid, p_customer jsonb)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_customer_save_browser_v1(p_conversation_id uuid, p_customer jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_access jsonb:=public.ops2_admin_attendance_customer_access_v1(true);
  v_customer_id uuid;
  v_phone text;
  v_active boolean;
  v_payload jsonb;
  v_saved jsonb;
begin
  if coalesce((v_access->>'ok')::boolean,false) is not true then return v_access; end if;
  if p_conversation_id is null then return jsonb_build_object('ok',false,'error','invalid_conversation_id'); end if;

  select c.customer_id into v_customer_id
  from public.conversations c
  where c.id=p_conversation_id;
  if not found then return jsonb_build_object('ok',false,'error','conversation_not_found'); end if;
  if v_customer_id is null then return jsonb_build_object('ok',false,'error','customer_not_linked'); end if;

  select cu.primary_whatsapp_e164,cu.is_active into v_phone,v_active
  from public.customers cu
  where cu.id=v_customer_id
  for update;
  if not found then return jsonb_build_object('ok',false,'error','customer_not_found'); end if;

  v_payload:=jsonb_build_object(
    'id',v_customer_id,
    'display_name',p_customer->>'display_name',
    'phone',v_phone,
    'cpf',p_customer->>'cpf',
    'email',p_customer->>'email',
    'status',case when v_active=false then 'inactive' else 'active' end,
    'address',coalesce(p_customer->'address','{}'::jsonb)
  );

  v_saved:=public.ops2_admin_customer_save_v2(v_payload);
  if coalesce((v_saved->>'ok')::boolean,false) is not true then return v_saved; end if;
  return jsonb_build_object('ok',true,'saved',true,'customer_id',v_customer_id);
end;
$function$
;

-- function: ops2_admin_attendance_customer_search_browser_v1(p_query text, p_limit integer)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_customer_search_browser_v1(p_query text, p_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_access jsonb:=public.ops2_admin_attendance_customer_access_v1(false);
  v_items jsonb;
begin
  if coalesce((v_access->>'ok')::boolean,false) is not true then return v_access; end if;
  if char_length(btrim(coalesce(p_query,'')))<2 then return jsonb_build_object('ok',true,'items','[]'::jsonb); end if;

  select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb)
  into v_items
  from public.ops2_admin_attendance_customer_search_v1(p_query,least(20,greatest(1,coalesce(p_limit,10)))) x;

  return jsonb_build_object('ok',true,'items',coalesce(v_items,'[]'::jsonb));
end;
$function$
;

-- function: ops2_admin_attendance_customer_search_v1(p_query text, p_limit integer)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_customer_search_v1(p_query text, p_limit integer DEFAULT 10)
 RETURNS TABLE(customer_id uuid, customer_name text, phone_e164 text, masked_document text, is_active boolean)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with input as (
    select
      nullif(btrim(regexp_replace(coalesce(p_query,''),'\s+',' ','g')),'') as q,
      regexp_replace(coalesce(p_query,''),'[^0-9]','','g') as digits,
      least(20,greatest(1,coalesce(p_limit,10))) as lim
  ), matched_ids as (
    select c.id
    from public.customers c, input i
    where i.q is not null
      and char_length(i.q)>=2
      and (
        c.name ilike '%'||i.q||'%'
        or (i.digits<>'' and regexp_replace(coalesce(c.cpf_cnpj,''),'[^0-9]','','g') like '%'||i.digits||'%')
        or (i.digits<>'' and public.normalize_phone_digits(c.primary_whatsapp_e164) like '%'||i.digits||'%')
      )
    union
    select cp.customer_id
    from public.customer_phones cp, input i
    where i.q is not null
      and char_length(i.q)>=2
      and i.digits<>''
      and public.normalize_phone_digits(cp.phone_e164) like '%'||i.digits||'%'
  ), limited as (
    select c.id
    from matched_ids m
    join public.customers c on c.id=m.id
    order by c.is_active desc,lower(coalesce(c.name,'')),c.id
    limit (select lim from input)
  )
  select
    c.id as customer_id,
    c.name as customer_name,
    public.canonical_whatsapp_e164_br_v2(coalesce(
      c.primary_whatsapp_e164,
      (select cp.phone_e164 from public.customer_phones cp where cp.customer_id=c.id order by cp.is_primary desc,cp.created_at desc limit 1)
    )) as phone_e164,
    case
      when char_length(regexp_replace(coalesce(c.cpf_cnpj,''),'[^0-9]','','g'))>=4 then
        repeat('*',greatest(0,char_length(regexp_replace(coalesce(c.cpf_cnpj,''),'[^0-9]','','g'))-4))
        || right(regexp_replace(coalesce(c.cpf_cnpj,''),'[^0-9]','','g'),4)
      else null
    end as masked_document,
    c.is_active
  from limited l
  join public.customers c on c.id=l.id
  order by c.is_active desc,lower(coalesce(c.name,'')),c.id
$function$
;

-- function: ops2_admin_attendance_customer_update_browser_v1(p_conversation_id uuid, p_expected_customer_updated_at timestamp with time zone, p_customer_name text, p_address_id uuid, p_expected_address_updated_at timestamp with time zone, p_address jsonb)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_customer_update_browser_v1(p_conversation_id uuid, p_expected_customer_updated_at timestamp with time zone, p_customer_name text, p_address_id uuid DEFAULT NULL::uuid, p_expected_address_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_address jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_access jsonb;
  v_admin_user_id uuid := auth.uid();
  v_customer_id uuid;
  v_customer_updated_at timestamptz;
  v_name text := nullif(left(btrim(regexp_replace(coalesce(p_customer_name, ''), '[[:space:]]+', ' ', 'g')), 180), '');
  v_address_updated_at timestamptz;
  v_street text;
  v_number text;
  v_complement text;
  v_neighborhood text;
  v_city text;
  v_state_raw text;
  v_state text;
  v_postal_code text;
  v_reference text;
  v_changed_fields text[] := array[]::text[];
  v_audit_id uuid;
begin
  if v_admin_user_id is null then
    return jsonb_build_object('ok', false, 'error', 'admin_not_authorized');
  end if;
  v_access := public.ops2_admin_attendance_customer_access_v1(true);
  if coalesce((v_access ->> 'ok')::boolean, false) is distinct from true then
    return v_access;
  end if;
  if p_conversation_id is null or p_expected_customer_updated_at is null or v_name is null then
    return jsonb_build_object('ok', false, 'error', 'invalid_customer');
  end if;
  if (p_address_id is null) <> (p_expected_address_updated_at is null)
    or (p_address_id is null and p_address is not null)
    or (p_address_id is not null and coalesce(jsonb_typeof(p_address), '') <> 'object') then
    return jsonb_build_object('ok', false, 'error', 'invalid_address');
  end if;

  select c.customer_id into v_customer_id
  from public.conversations c
  where c.id = p_conversation_id
  for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'conversation_not_found');
  end if;
  if v_customer_id is null then
    return jsonb_build_object('ok', false, 'error', 'customer_not_linked');
  end if;

  select c.updated_at into v_customer_updated_at
  from public.customers c
  where c.id = v_customer_id
  for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'customer_not_found');
  end if;
  if v_customer_updated_at is distinct from p_expected_customer_updated_at then
    return jsonb_build_object('ok', false, 'error', 'stale_customer');
  end if;

  if p_address_id is not null then
    select ca.updated_at into v_address_updated_at
    from public.customer_addresses ca
    where ca.id = p_address_id
      and ca.customer_id = v_customer_id
      and ca.is_active = true
    for update;
    if not found then
      return jsonb_build_object('ok', false, 'error', 'invalid_address');
    end if;
    if v_address_updated_at is distinct from p_expected_address_updated_at then
      return jsonb_build_object('ok', false, 'error', 'stale_address');
    end if;

    v_street := nullif(left(btrim(regexp_replace(coalesce(p_address ->> 'street', ''), '[[:cntrl:]]+', ' ', 'g')), 180), '');
    v_number := nullif(left(btrim(regexp_replace(coalesce(p_address ->> 'number', ''), '[[:cntrl:]]+', ' ', 'g')), 40), '');
    v_complement := nullif(left(btrim(regexp_replace(coalesce(p_address ->> 'complement', ''), '[[:cntrl:]]+', ' ', 'g')), 140), '');
    v_neighborhood := nullif(left(btrim(regexp_replace(coalesce(p_address ->> 'neighborhood', ''), '[[:cntrl:]]+', ' ', 'g')), 140), '');
    v_city := nullif(left(btrim(regexp_replace(coalesce(p_address ->> 'city', ''), '[[:cntrl:]]+', ' ', 'g')), 120), '');
    v_state_raw := nullif(btrim(coalesce(p_address ->> 'state', '')), '');
    v_state := upper(v_state_raw);
    v_postal_code := nullif(left(regexp_replace(coalesce(p_address ->> 'postal_code', ''), '[^0-9]', '', 'g'), 8), '');
    v_reference := nullif(left(btrim(regexp_replace(coalesce(p_address ->> 'reference', ''), '[[:cntrl:]]+', ' ', 'g')), 400), '');

    if v_street is null or v_city is null
      or (v_state is not null and v_state !~ '^[A-Z]{2}$')
      or length(regexp_replace(coalesce(p_address ->> 'postal_code', ''), '[^0-9]', '', 'g')) > 8 then
      return jsonb_build_object('ok', false, 'error', 'invalid_address_fields');
    end if;
  end if;

  update public.customers c
  set name = v_name
  where c.id = v_customer_id
    and c.name is distinct from v_name;
  if found then
    v_changed_fields := array_append(v_changed_fields, 'name');
  end if;

  if p_address_id is not null then
    update public.customer_addresses ca
    set street = v_street,
      number = v_number,
      complement = v_complement,
      neighborhood = v_neighborhood,
      city = v_city,
      state = v_state,
      postal_code = v_postal_code,
      reference = v_reference
    where ca.id = p_address_id
      and ca.customer_id = v_customer_id
      and ca.is_active = true
      and (ca.street, ca.number, ca.complement, ca.neighborhood, ca.city, ca.state, ca.postal_code, ca.reference)
        is distinct from (v_street, v_number, v_complement, v_neighborhood, v_city, v_state, v_postal_code, v_reference);
    if found then
      v_changed_fields := array_append(v_changed_fields, 'delivery_address');
    end if;
  end if;

  if cardinality(v_changed_fields) = 0 then
    return jsonb_build_object('ok', true, 'saved', false, 'customer_id', v_customer_id);
  end if;

  insert into public.admin_audit_logs(admin_user_id, action, entity_type, entity_id, details)
  values (
    v_admin_user_id,
    'customer_profile_or_address_updated',
    'customer',
    v_customer_id::text,
    jsonb_build_object(
      'conversation_id', p_conversation_id,
      'address_id', p_address_id,
      'changed_fields', to_jsonb(v_changed_fields)
    )
  )
  returning id into v_audit_id;

  return jsonb_build_object(
    'ok', true,
    'saved', true,
    'customer_id', v_customer_id,
    'audit_id', v_audit_id
  );
end;
$function$
;

-- function: ops2_admin_attendance_enqueue_interactive_v1(p_conversation_id uuid, p_interactive jsonb, p_idempotency_key text, p_admin_user_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_enqueue_interactive_v1(p_conversation_id uuid, p_interactive jsonb, p_idempotency_key text, p_admin_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_conversation public.conversations%rowtype;
  v_runtime public.whatsapp_channel_runtime_v1%rowtype;
  v_existing public.whatsapp_outbox_v1%rowtype;
  v_kind text;
  v_body text;
  v_phone text;
  v_key text;
  v_client_key text := btrim(coalesce(p_idempotency_key, ''));
  v_provider text;
  v_outbox_id uuid;
  v_rows integer;
  v_unique_count integer;
  v_recent_count integer := 0;
begin
  if p_conversation_id is null then
    return jsonb_build_object('ok', false, 'error', 'conversation_required');
  end if;
  if p_admin_user_id is null or not exists (
    select 1 from public.admin_users u
    where u.user_id = p_admin_user_id and u.is_active = true
      and u.role in ('owner', 'admin', 'operator')
  ) then
    return jsonb_build_object('ok', false, 'error', 'admin_not_authorized');
  end if;
  if p_interactive is null or jsonb_typeof(p_interactive) <> 'object' then
    return jsonb_build_object('ok', false, 'error', 'interactive_invalid');
  end if;
  if exists (
    select 1 from jsonb_object_keys(p_interactive) as keys(key)
    where keys.key not in ('type', 'header', 'body', 'footer', 'action')
  ) then
    return jsonb_build_object('ok', false, 'error', 'interactive_invalid');
  end if;
  if jsonb_typeof(p_interactive->'body') is distinct from 'object'
     or jsonb_typeof(p_interactive->'action') is distinct from 'object' then
    return jsonb_build_object('ok', false, 'error', 'interactive_invalid');
  end if;
  if octet_length(p_interactive::text) > 12000 then
    return jsonb_build_object('ok', false, 'error', 'interactive_too_large');
  end if;
  if length(v_client_key) < 8 or length(v_client_key) > 120
     or v_client_key !~ '^[A-Za-z0-9._:-]+$' then
    return jsonb_build_object('ok', false, 'error', 'invalid_idempotency_key');
  end if;

  v_kind := lower(btrim(coalesce(p_interactive->>'type', '')));
  v_body := btrim(coalesce(p_interactive#>>'{body,text}', ''));
  if v_body = '' or char_length(v_body) > 1024 then
    return jsonb_build_object('ok', false, 'error', 'interactive_body_invalid');
  end if;

  if v_kind = 'button' then
    if jsonb_typeof(p_interactive#>'{action,buttons}') is distinct from 'array' then
      return jsonb_build_object('ok', false, 'error', 'interactive_buttons_invalid');
    end if;
    if jsonb_array_length(p_interactive#>'{action,buttons}') not between 1 and 3 then
      return jsonb_build_object('ok', false, 'error', 'interactive_buttons_invalid');
    end if;
    select count(*)::integer, count(distinct b.value#>>'{reply,id}')::integer
    into v_rows, v_unique_count
    from jsonb_array_elements(p_interactive#>'{action,buttons}') b(value);
    if v_rows <> v_unique_count then
      return jsonb_build_object('ok', false, 'error', 'interactive_buttons_invalid');
    end if;
    if exists (
      select 1
      from jsonb_array_elements(p_interactive#>'{action,buttons}') b(value)
      where b.value->>'type' <> 'reply'
        or coalesce(b.value#>>'{reply,id}', '') = ''
        or char_length(b.value#>>'{reply,id}') > 256
        or coalesce(b.value#>>'{reply,title}', '') = ''
        or char_length(b.value#>>'{reply,title}') > 20
    ) then
      return jsonb_build_object('ok', false, 'error', 'interactive_buttons_invalid');
    end if;
  elsif v_kind = 'list' then
    if coalesce(btrim(p_interactive#>>'{action,button}'), '') = ''
       or char_length(p_interactive#>>'{action,button}') > 20 then
      return jsonb_build_object('ok', false, 'error', 'interactive_list_invalid');
    end if;
    if jsonb_typeof(p_interactive#>'{action,sections}') is distinct from 'array' then
      return jsonb_build_object('ok', false, 'error', 'interactive_list_invalid');
    end if;
    if jsonb_array_length(p_interactive#>'{action,sections}') <> 1 then
      return jsonb_build_object('ok', false, 'error', 'interactive_list_invalid');
    end if;
    if jsonb_typeof(p_interactive#>'{action,sections,0,rows}') is distinct from 'array' then
      return jsonb_build_object('ok', false, 'error', 'interactive_list_invalid');
    end if;
    select coalesce(jsonb_array_length(s.value->'rows'), 0)
    into v_rows
    from jsonb_array_elements(p_interactive#>'{action,sections}') s(value)
    limit 1;
    if v_rows is null or v_rows < 1 or v_rows > 10 then
      return jsonb_build_object('ok', false, 'error', 'interactive_list_invalid');
    end if;
    if exists (
      select 1
      from jsonb_array_elements(p_interactive#>'{action,sections}') s(value)
      cross join lateral jsonb_array_elements(s.value->'rows') r(value)
      where coalesce(r.value->>'id', '') = ''
        or char_length(r.value->>'id') > 200
        or coalesce(r.value->>'title', '') = ''
        or char_length(r.value->>'title') > 24
        or char_length(coalesce(r.value->>'description', '')) > 72
    ) then
      return jsonb_build_object('ok', false, 'error', 'interactive_list_invalid');
    end if;
  else
    return jsonb_build_object('ok', false, 'error', 'interactive_type_unsupported');
  end if;

  if p_interactive ? 'header' and (
    jsonb_typeof(p_interactive->'header') <> 'object'
    or p_interactive#>>'{header,type}' <> 'text'
    or coalesce(btrim(p_interactive#>>'{header,text}'), '') = ''
    or char_length(p_interactive#>>'{header,text}') > 60
  ) then
    return jsonb_build_object('ok', false, 'error', 'interactive_header_invalid');
  end if;
  if p_interactive ? 'footer' and (
    jsonb_typeof(p_interactive->'footer') <> 'object'
    or coalesce(btrim(p_interactive#>>'{footer,text}'), '') = ''
    or char_length(p_interactive#>>'{footer,text}') > 60
  ) then
    return jsonb_build_object('ok', false, 'error', 'interactive_footer_invalid');
  end if;

  v_key := 'attendance-interactive-v1:' || p_conversation_id::text || ':' || v_client_key;
  perform pg_advisory_xact_lock(hashtextextended(v_key, 0));

  select c.* into v_conversation
  from public.conversations c
  join public.whatsapp_accounts wa
    on wa.id = c.whatsapp_account_id
   and wa.is_active = true
  where c.id = p_conversation_id
    and c.whatsapp_account_id is not null;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'conversation_channel_unavailable');
  end if;

  v_phone := public.canonical_whatsapp_e164_br_v2(v_conversation.wa_contact_e164);
  if v_phone is null then
    return jsonb_build_object('ok', false, 'error', 'conversation_phone_invalid');
  end if;

  select o.* into v_existing
  from public.whatsapp_outbox_v1 o
  where o.idempotency_key = v_key;
  if found then
    if v_existing.conversation_id is distinct from p_conversation_id
       or v_existing.message_type <> 'interactive'
       or v_existing.metadata->>'admin_user_id' is distinct from p_admin_user_id::text
       or v_existing.payload->'interactive' is distinct from p_interactive then
      return jsonb_build_object('ok', false, 'error', 'idempotency_conflict');
    end if;
    return jsonb_build_object(
      'ok', true, 'duplicate', true, 'conversation_id', p_conversation_id,
      'outbox_id', v_existing.id, 'provider', v_existing.provider, 'status', v_existing.status
    );
  end if;

  if v_conversation.last_inbound_at is null
     or now() >= v_conversation.last_inbound_at + interval '24 hours' then
    return jsonb_build_object('ok', false, 'error', 'service_window_closed');
  end if;

  select r.* into v_runtime
  from public.whatsapp_channel_runtime_v1 r
  where r.whatsapp_account_id = v_conversation.whatsapp_account_id
    and r.send_enabled = true
    and r.human_send_enabled = true
    and r.homologated_at is not null
    and r.outbound_provider = 'meta';
  if not found then
    return jsonb_build_object('ok', false, 'error', 'human_send_not_homologated');
  end if;
  v_provider := v_runtime.outbound_provider;

  if lower(coalesce(v_runtime.metadata->>'meta_canary_enabled', 'false')) = 'true'
     and not exists (
       select 1
       from jsonb_array_elements_text(
         case when jsonb_typeof(v_runtime.metadata->'meta_canary_to_e164') = 'array'
           then v_runtime.metadata->'meta_canary_to_e164' else '[]'::jsonb end
       ) allowed(value)
       where public.canonical_whatsapp_e164_br_v2(allowed.value) = v_phone
     ) then
    return jsonb_build_object('ok', false, 'error', 'meta_canary_destination_blocked');
  end if;

  if exists (
    select 1 from public.whatsapp_outbox_v1 o
    where o.conversation_id = p_conversation_id
      and o.provider = 'meta'
      and o.status = 'claimed'
      and o.purpose = 'human_attendance'
      and o.message_type = 'interactive'
  ) then
    return jsonb_build_object('ok', false, 'error', 'meta_send_uncertain');
  end if;

  select count(*)::integer into v_recent_count
  from public.whatsapp_outbox_v1 o
  where o.conversation_id = p_conversation_id
    and o.purpose = 'human_attendance'
    and o.created_at > now() - interval '60 seconds'
    and o.status <> 'cancelled';
  if v_recent_count >= 20 then
    return jsonb_build_object('ok', false, 'error', 'rate_limited');
  end if;

  insert into public.whatsapp_outbox_v1(
    idempotency_key, whatsapp_account_id, conversation_id, customer_id,
    to_phone_e164, purpose, message_type, payload, provider, status, metadata
  ) values (
    v_key, v_conversation.whatsapp_account_id, p_conversation_id, v_conversation.customer_id,
    v_phone, 'human_attendance', 'interactive',
    jsonb_build_object('type', 'interactive', 'interactive', p_interactive),
    v_provider, 'queued',
    jsonb_build_object(
      'source', 'attendance', 'contract', 'native_interactive_v1', 'provider', v_provider,
      'meta_canary', lower(coalesce(v_runtime.metadata->>'meta_canary_enabled', 'false')) = 'true',
      'admin_user_id', p_admin_user_id
    )
  ) returning id into v_outbox_id;

  return jsonb_build_object(
    'ok', true, 'duplicate', false, 'conversation_id', p_conversation_id,
    'outbox_id', v_outbox_id, 'provider', v_provider, 'status', 'queued'
  );
end;
$function$
;

-- function: ops2_admin_attendance_enqueue_media_v1(p_conversation_id uuid, p_media_type text, p_mime_type text, p_filename text, p_size_bytes bigint, p_sha256 text, p_caption text, p_idempotency_key text)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_enqueue_media_v1(p_conversation_id uuid, p_media_type text, p_mime_type text, p_filename text, p_size_bytes bigint, p_sha256 text, p_caption text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_conversation public.conversations%rowtype;
  v_runtime public.whatsapp_channel_runtime_v1%rowtype;
  v_existing public.whatsapp_outbox_v1%rowtype;
  v_media_type text:=lower(btrim(coalesce(p_media_type,'')));
  v_mime_type text:=lower(split_part(btrim(coalesce(p_mime_type,'')),';',1));
  v_filename text:=btrim(coalesce(p_filename,''));
  v_size_bytes bigint:=coalesce(p_size_bytes,0);
  v_sha256 text:=lower(btrim(coalesce(p_sha256,'')));
  v_caption text:=nullif(btrim(coalesce(p_caption,'')),'');
  v_client_key text:=btrim(coalesce(p_idempotency_key,''));
  v_key text;
  v_phone text;
  v_outbox_id uuid;
  v_recent_count integer:=0;
begin
  if p_conversation_id is null then
    return jsonb_build_object('ok',false,'error','conversation_required');
  end if;
  if v_media_type not in ('image','audio','video','document') then
    return jsonb_build_object('ok',false,'error','media_type_not_allowed');
  end if;
  if (v_media_type='image' and v_mime_type not in ('image/jpeg','image/png'))
     or (v_media_type='audio' and v_mime_type not in ('audio/aac','audio/amr','audio/mpeg','audio/mp4','audio/ogg'))
     or (v_media_type='video' and v_mime_type not in ('video/mp4','video/3gpp'))
     or (v_media_type='document' and v_mime_type not in (
       'application/pdf','text/plain','application/msword',
       'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
       'application/vnd.ms-excel','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
       'application/vnd.ms-powerpoint','application/vnd.openxmlformats-officedocument.presentationml.presentation'
     )) then
    return jsonb_build_object('ok',false,'error','media_mime_not_allowed');
  end if;
  if v_filename='' or char_length(v_filename)>240 or v_filename ~ '[[:cntrl:]\\/]' then
    return jsonb_build_object('ok',false,'error','media_filename_invalid');
  end if;
  if v_size_bytes<1
     or (v_media_type='image' and v_size_bytes>5242880)
     or (v_media_type in ('audio','video') and v_size_bytes>16777216)
     or (v_media_type='document' and v_size_bytes>26214400) then
    return jsonb_build_object('ok',false,'error','media_size_invalid');
  end if;
  if v_sha256 !~ '^[0-9a-f]{64}$' then
    return jsonb_build_object('ok',false,'error','media_sha256_invalid');
  end if;
  if v_caption is not null and char_length(v_caption)>1024 then
    return jsonb_build_object('ok',false,'error','media_caption_too_long');
  end if;
  if v_media_type='audio' then v_caption:=null; end if;
  if length(v_client_key)<8 or length(v_client_key)>120 or v_client_key !~ '^[A-Za-z0-9._:-]+$' then
    return jsonb_build_object('ok',false,'error','invalid_idempotency_key');
  end if;

  v_key:='attendance-media-v1:'||p_conversation_id::text||':'||v_client_key;
  perform pg_advisory_xact_lock(hashtextextended(v_key,0));

  select c.* into v_conversation
  from public.conversations c
  join public.whatsapp_accounts wa
    on wa.id=c.whatsapp_account_id
   and wa.is_active=true
  where c.id=p_conversation_id
    and c.whatsapp_account_id is not null;
  if not found then
    return jsonb_build_object('ok',false,'error','conversation_channel_unavailable');
  end if;

  v_phone:=public.canonical_whatsapp_e164_br_v2(v_conversation.wa_contact_e164);
  if v_phone is null then
    return jsonb_build_object('ok',false,'error','conversation_phone_invalid');
  end if;

  select o.* into v_existing
  from public.whatsapp_outbox_v1 o
  where o.idempotency_key=v_key;
  if found then
    if v_existing.conversation_id is distinct from p_conversation_id
       or v_existing.message_type is distinct from v_media_type
       or coalesce(v_existing.payload->>'mime_type','')<>v_mime_type
       or coalesce(v_existing.payload->>'filename','')<>v_filename
       or coalesce((v_existing.payload->>'size_bytes')::bigint,0)<>v_size_bytes
       or coalesce(v_existing.payload->>'sha256','')<>v_sha256
       or coalesce(v_existing.payload->>'caption','')<>coalesce(v_caption,'') then
      return jsonb_build_object('ok',false,'error','idempotency_conflict');
    end if;
    return jsonb_build_object(
      'ok',true,'duplicate',true,'conversation_id',p_conversation_id,
      'outbox_id',v_existing.id,'provider',v_existing.provider,'status',v_existing.status,
      'message_type',v_existing.message_type
    );
  end if;

  if v_conversation.last_inbound_at is null
     or now()>=v_conversation.last_inbound_at+interval '24 hours' then
    return jsonb_build_object('ok',false,'error','service_window_closed');
  end if;

  select r.* into v_runtime
  from public.whatsapp_channel_runtime_v1 r
  where r.whatsapp_account_id=v_conversation.whatsapp_account_id
    and r.send_enabled=true
    and r.human_send_enabled=true
    and r.homologated_at is not null;
  if not found then
    return jsonb_build_object('ok',false,'error','human_send_not_homologated');
  end if;

  if v_runtime.outbound_provider<>'meta' then
    return jsonb_build_object('ok',false,'error','media_provider_unavailable');
  end if;

  if lower(coalesce(v_runtime.metadata->>'meta_canary_enabled','false'))='true'
     and not exists (
       select 1
       from jsonb_array_elements_text(
         case
           when jsonb_typeof(v_runtime.metadata->'meta_canary_to_e164')='array'
             then v_runtime.metadata->'meta_canary_to_e164'
           else '[]'::jsonb
         end
       ) as allowed(value)
       where public.canonical_whatsapp_e164_br_v2(allowed.value)=v_phone
     ) then
    return jsonb_build_object('ok',false,'error','meta_canary_destination_blocked');
  end if;

  select count(*)::integer into v_recent_count
  from public.whatsapp_outbox_v1 o
  where o.conversation_id=p_conversation_id
    and o.purpose='human_attendance'
    and o.created_at>now()-interval '60 seconds'
    and o.status<>'cancelled';
  if v_recent_count>=20 then
    return jsonb_build_object('ok',false,'error','rate_limited');
  end if;

  insert into public.whatsapp_outbox_v1(
    idempotency_key,whatsapp_account_id,conversation_id,customer_id,to_phone_e164,
    purpose,message_type,payload,provider,status,metadata
  ) values (
    v_key,v_conversation.whatsapp_account_id,p_conversation_id,v_conversation.customer_id,v_phone,
    'human_attendance',v_media_type,
    jsonb_build_object(
      'mime_type',v_mime_type,'filename',v_filename,'size_bytes',v_size_bytes,
      'sha256',v_sha256,'caption',v_caption
    ),
    'meta','queued',
    jsonb_build_object(
      'source','attendance','contract','meta_media_v1','provider','meta',
      'meta_canary',lower(coalesce(v_runtime.metadata->>'meta_canary_enabled','false'))='true'
    )
  ) returning id into v_outbox_id;

  return jsonb_build_object(
    'ok',true,'duplicate',false,'conversation_id',p_conversation_id,
    'outbox_id',v_outbox_id,'provider','meta','status','queued','message_type',v_media_type
  );
end;
$function$
;

-- function: ops2_admin_attendance_enqueue_template_v1(p_conversation_id uuid, p_template_id uuid, p_parameters jsonb, p_idempotency_key text)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_enqueue_template_v1(p_conversation_id uuid, p_template_id uuid, p_parameters jsonb, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_conversation public.conversations%rowtype;
  v_runtime public.whatsapp_channel_runtime_v1%rowtype;
  v_template public.whatsapp_templates_v1%rowtype;
  v_existing public.whatsapp_outbox_v1%rowtype;
  v_key text;
  v_client_key text:=btrim(coalesce(p_idempotency_key,''));
  v_phone text;
  v_expected integer:=0;
  v_received integer:=0;
  v_rendered text:='';
  v_components jsonb:='[]'::jsonb;
  v_parameter_objects jsonb:='[]'::jsonb;
  v_recent_count integer:=0;
  v_outbox_id uuid;
  v_value text;
  v_index integer:=0;
  v_param record;
begin
  if p_conversation_id is null then return jsonb_build_object('ok',false,'error','conversation_required'); end if;
  if p_template_id is null then return jsonb_build_object('ok',false,'error','template_required'); end if;
  if length(v_client_key)<8 or length(v_client_key)>120 or v_client_key !~ '^[A-Za-z0-9._:-]+$' then
    return jsonb_build_object('ok',false,'error','invalid_idempotency_key');
  end if;
  if p_parameters is null or jsonb_typeof(p_parameters)<>'array' then
    return jsonb_build_object('ok',false,'error','template_parameters_invalid');
  end if;

  v_key:='attendance-template-v1:'||p_conversation_id::text||':'||v_client_key;
  perform pg_advisory_xact_lock(hashtextextended(v_key,0));

  select c.* into v_conversation
  from public.conversations c
  join public.whatsapp_accounts wa on wa.id=c.whatsapp_account_id and wa.is_active=true
  where c.id=p_conversation_id and c.whatsapp_account_id is not null;
  if not found then return jsonb_build_object('ok',false,'error','conversation_channel_unavailable'); end if;

  v_phone:=public.canonical_whatsapp_e164_br_v2(v_conversation.wa_contact_e164);
  if v_phone is null then return jsonb_build_object('ok',false,'error','conversation_phone_invalid'); end if;

  select t.* into v_template
  from public.whatsapp_templates_v1 t
  where t.id=p_template_id
    and t.whatsapp_account_id=v_conversation.whatsapp_account_id
    and upper(coalesce(t.status,''))='APPROVED'
    and lower(coalesce(t.metadata->'attendance'->>'enabled','false'))='true';
  if not found then return jsonb_build_object('ok',false,'error','template_not_sendable'); end if;

  if exists(
    select 1 from jsonb_array_elements(coalesce(v_template.components,'[]'::jsonb)) c
    where upper(coalesce(c->>'type',''))<>'BODY' and c::text like '%{{%'
  ) then
    return jsonb_build_object('ok',false,'error','template_dynamic_component_unsupported');
  end if;

  select coalesce(max((m)[1]::integer),0) into v_expected
  from jsonb_array_elements(coalesce(v_template.components,'[]'::jsonb)) c
  cross join lateral regexp_matches(coalesce(c->>'text',''),'\{\{([0-9]+)\}\}','g') m
  where upper(coalesce(c->>'type',''))='BODY';

  v_received:=jsonb_array_length(p_parameters);
  if v_received<>v_expected then
    return jsonb_build_object('ok',false,'error','template_parameter_count_mismatch','expected',v_expected,'received',v_received);
  end if;

  for v_param in select value,ordinality from jsonb_array_elements(p_parameters) with ordinality loop
    if jsonb_typeof(v_param.value)<>'string' then return jsonb_build_object('ok',false,'error','template_parameter_invalid','index',v_param.ordinality); end if;
    v_value:=v_param.value #>> '{}';
    if btrim(v_value)='' or char_length(v_value)>1024 then return jsonb_build_object('ok',false,'error','template_parameter_invalid','index',v_param.ordinality); end if;
  end loop;

  select coalesce(jsonb_agg(jsonb_build_object('type','text','text',value #>> '{}') order by ordinality),'[]'::jsonb)
  into v_parameter_objects
  from jsonb_array_elements(p_parameters) with ordinality;

  if v_expected>0 then
    v_components:=jsonb_build_array(jsonb_build_object('type','body','parameters',v_parameter_objects));
  end if;

  select coalesce(c->>'text','') into v_rendered
  from jsonb_array_elements(coalesce(v_template.components,'[]'::jsonb)) c
  where upper(coalesce(c->>'type',''))='BODY'
  limit 1;
  if v_rendered is null then v_rendered:=''; end if;
  if v_expected>0 then
    for v_index in 1..v_expected loop
      v_rendered:=replace(v_rendered,'{{'||v_index::text||'}}',p_parameters->>(v_index-1));
    end loop;
  end if;

  select o.* into v_existing from public.whatsapp_outbox_v1 o where o.idempotency_key=v_key;
  if found then
    if v_existing.conversation_id is distinct from p_conversation_id
       or v_existing.template_id is distinct from p_template_id
       or coalesce(v_existing.payload->'parameters','[]'::jsonb) is distinct from p_parameters then
      return jsonb_build_object('ok',false,'error','idempotency_conflict');
    end if;
    return jsonb_build_object('ok',true,'duplicate',true,'conversation_id',p_conversation_id,'outbox_id',v_existing.id,'provider',v_existing.provider,'status',v_existing.status);
  end if;

  select rt.* into v_runtime
  from public.whatsapp_channel_runtime_v1 rt
  where rt.whatsapp_account_id=v_conversation.whatsapp_account_id
    and rt.send_enabled=true and rt.human_send_enabled=true and rt.homologated_at is not null
    and rt.outbound_provider='meta'
    and lower(coalesce(rt.metadata->>'meta_send_homologated','false'))='true';
  if not found then return jsonb_build_object('ok',false,'error','meta_template_send_not_homologated'); end if;

  if lower(coalesce(v_runtime.metadata->>'meta_canary_enabled','false'))='true'
     and not exists(
       select 1 from jsonb_array_elements_text(
         case when jsonb_typeof(v_runtime.metadata->'meta_canary_to_e164')='array' then v_runtime.metadata->'meta_canary_to_e164' else '[]'::jsonb end
       ) allowed(value)
       where public.canonical_whatsapp_e164_br_v2(allowed.value)=v_phone
     ) then
    return jsonb_build_object('ok',false,'error','meta_canary_destination_blocked');
  end if;

  if exists(
    select 1 from public.whatsapp_outbox_v1 o
    where o.conversation_id=p_conversation_id and o.provider='meta' and o.status='claimed'
      and coalesce(o.last_error,'') like 'meta_send_uncertain:%'
  ) then return jsonb_build_object('ok',false,'error','meta_send_uncertain'); end if;

  select count(*)::integer into v_recent_count
  from public.whatsapp_outbox_v1 o
  where o.conversation_id=p_conversation_id and o.purpose='human_attendance'
    and o.created_at>now()-interval '60 seconds' and o.status<>'cancelled';
  if v_recent_count>=20 then return jsonb_build_object('ok',false,'error','rate_limited'); end if;

  insert into public.whatsapp_outbox_v1(
    idempotency_key,whatsapp_account_id,conversation_id,customer_id,to_phone_e164,
    purpose,message_type,template_id,payload,provider,status,metadata
  ) values (
    v_key,v_conversation.whatsapp_account_id,p_conversation_id,v_conversation.customer_id,v_phone,
    'human_attendance','template',v_template.id,
    jsonb_build_object(
      'template',jsonb_build_object('name',v_template.name,'language',jsonb_build_object('code',v_template.language),'components',v_components),
      'parameters',p_parameters,'rendered_text',v_rendered
    ),
    'meta','queued',jsonb_build_object('source','attendance','contract','meta_template_v1','provider','meta','template_name',v_template.name,'template_language',v_template.language,'meta_canary',lower(coalesce(v_runtime.metadata->>'meta_canary_enabled','false'))='true')
  ) returning id into v_outbox_id;

  return jsonb_build_object('ok',true,'duplicate',false,'conversation_id',p_conversation_id,'outbox_id',v_outbox_id,'provider','meta','status','queued','template_id',v_template.id,'template_name',v_template.name);
end;
$function$
;

-- function: ops2_admin_attendance_enqueue_text_v1(p_conversation_id uuid, p_text text, p_idempotency_key text)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_enqueue_text_v1(p_conversation_id uuid, p_text text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_conversation public.conversations%rowtype;
  v_runtime public.whatsapp_channel_runtime_v1%rowtype;
  v_existing public.whatsapp_outbox_v1%rowtype;
  v_text text := btrim(coalesce(p_text,''));
  v_client_key text := btrim(coalesce(p_idempotency_key,''));
  v_key text;
  v_phone text;
  v_message_id uuid;
  v_outbox_id uuid;
  v_recent_count integer := 0;
  v_purpose text := 'human_attendance';
  v_sender_kind text := 'human';
  v_status_current text := 'queued';
  v_outbox_status text := 'queued';
begin
  if p_conversation_id is null then
    return jsonb_build_object('ok',false,'error','conversation_required');
  end if;

  if v_text='' then
    return jsonb_build_object('ok',false,'error','message_empty');
  end if;

  if char_length(v_text)>4000 then
    return jsonb_build_object('ok',false,'error','message_too_long');
  end if;

  if length(v_client_key)<8
     or length(v_client_key)>120
     or v_client_key !~ '^[A-Za-z0-9._:-]+$' then
    return jsonb_build_object('ok',false,'error','invalid_idempotency_key');
  end if;

  v_key:='attendance:'||p_conversation_id::text||':'||v_client_key;
  perform pg_advisory_xact_lock(hashtextextended(v_key,0));

  select c.* into v_conversation
  from public.conversations c
  join public.whatsapp_accounts wa
    on wa.id=c.whatsapp_account_id
   and wa.is_active=true
  where c.id=p_conversation_id
    and c.whatsapp_account_id is not null;

  if not found then
    return jsonb_build_object('ok',false,'error','conversation_channel_unavailable');
  end if;

  v_phone:=public.canonical_whatsapp_e164_br_v2(v_conversation.wa_contact_e164);
  if v_phone is null then
    return jsonb_build_object('ok',false,'error','conversation_phone_invalid');
  end if;

  select o.* into v_existing
  from public.whatsapp_outbox_v1 o
  where o.idempotency_key=v_key;

  if found then
    if v_existing.conversation_id is distinct from p_conversation_id
       or coalesce(v_existing.payload->>'text','')<>v_text then
      return jsonb_build_object('ok',false,'error','idempotency_conflict');
    end if;
    return jsonb_build_object(
      'ok',true,
      'duplicate',true,
      'conversation_id',p_conversation_id,
      'message_id',v_existing.message_id,
      'outbox_id',v_existing.id,
      'status',v_existing.status
    );
  end if;

  if v_conversation.last_inbound_at is null
     or now()>=v_conversation.last_inbound_at+interval '24 hours' then
    return jsonb_build_object('ok',false,'error','service_window_closed');
  end if;

  select r.* into v_runtime
  from public.whatsapp_channel_runtime_v1 r
  where r.whatsapp_account_id=v_conversation.whatsapp_account_id
    and r.outbound_provider='papoai'
    and r.send_enabled=true
    and r.human_send_enabled=true
    and r.homologated_at is not null;

  if not found then
    return jsonb_build_object('ok',false,'error','human_send_not_homologated');
  end if;

  select count(*)::integer into v_recent_count
  from public.whatsapp_outbox_v1 o
  where o.conversation_id=p_conversation_id
    and o.purpose='human_attendance'
    and o.created_at > now() - interval '60 seconds'
    and o.status<>'cancelled';

  if v_recent_count>=20 then
    return jsonb_build_object('ok',false,'error','rate_limited');
  end if;

  insert into public.whatsapp_messages_v1(
    conversation_id,
    whatsapp_account_id,
    customer_id,
    direction,
    message_type,
    provider,
    text_body,
    status_current,
    sender_kind,
    sender_ref,
    metadata
  ) values (
    p_conversation_id,
    v_conversation.whatsapp_account_id,
    v_conversation.customer_id,
    'outbound',
    'text',
    'papoai',
    v_text,
    v_status_current,
    v_sender_kind,
    'vitrine_admin_attendance',
    jsonb_build_object(
      'source','attendance',
      'idempotency_key',v_key,
      'queued_by','admin'
    )
  ) returning id into v_message_id;

  insert into public.whatsapp_outbox_v1(
    idempotency_key,
    whatsapp_account_id,
    conversation_id,
    customer_id,
    to_phone_e164,
    message_id,
    purpose,
    message_type,
    payload,
    provider,
    status,
    metadata
  ) values (
    v_key,
    v_conversation.whatsapp_account_id,
    p_conversation_id,
    v_conversation.customer_id,
    v_phone,
    v_message_id,
    v_purpose,
    'text',
    jsonb_build_object('text',v_text,'message_id',v_message_id),
    'papoai',
    v_outbox_status,
    jsonb_build_object('source','attendance','transport_pending',true)
  ) returning id into v_outbox_id;

  return jsonb_build_object(
    'ok',true,
    'duplicate',false,
    'conversation_id',p_conversation_id,
    'message_id',v_message_id,
    'outbox_id',v_outbox_id,
    'status','queued'
  );
end;
$function$
;

-- function: ops2_admin_attendance_enqueue_text_v2(p_conversation_id uuid, p_text text, p_idempotency_key text)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_enqueue_text_v2(p_conversation_id uuid, p_text text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_conversation public.conversations%rowtype;
  v_runtime public.whatsapp_channel_runtime_v1%rowtype;
  v_existing public.whatsapp_outbox_v1%rowtype;
  v_text text:=btrim(coalesce(p_text,''));
  v_client_key text:=btrim(coalesce(p_idempotency_key,''));
  v_key text;
  v_phone text;
  v_outbox_id uuid;
  v_recent_count integer:=0;
begin
  if p_conversation_id is null then return jsonb_build_object('ok',false,'error','conversation_required'); end if;
  if v_text='' then return jsonb_build_object('ok',false,'error','message_empty'); end if;
  if char_length(v_text)>4000 then return jsonb_build_object('ok',false,'error','message_too_long'); end if;
  if length(v_client_key)<8 or length(v_client_key)>120 or v_client_key !~ '^[A-Za-z0-9._:-]+$' then
    return jsonb_build_object('ok',false,'error','invalid_idempotency_key');
  end if;

  v_key:='attendance-v2:'||p_conversation_id::text||':'||v_client_key;
  perform pg_advisory_xact_lock(hashtextextended(v_key,0));

  select c.* into v_conversation
  from public.conversations c
  join public.whatsapp_accounts wa on wa.id=c.whatsapp_account_id and wa.is_active=true
  where c.id=p_conversation_id and c.whatsapp_account_id is not null;
  if not found then return jsonb_build_object('ok',false,'error','conversation_channel_unavailable'); end if;

  v_phone:=public.canonical_whatsapp_e164_br_v2(v_conversation.wa_contact_e164);
  if v_phone is null then return jsonb_build_object('ok',false,'error','conversation_phone_invalid'); end if;

  select o.* into v_existing from public.whatsapp_outbox_v1 o where o.idempotency_key=v_key;
  if found then
    if v_existing.conversation_id is distinct from p_conversation_id or coalesce(v_existing.payload->>'text','')<>v_text then
      return jsonb_build_object('ok',false,'error','idempotency_conflict');
    end if;
    return jsonb_build_object('ok',true,'duplicate',true,'conversation_id',p_conversation_id,'outbox_id',v_existing.id,'status',v_existing.status);
  end if;

  if v_conversation.last_inbound_at is null or now()>=v_conversation.last_inbound_at+interval '24 hours' then
    return jsonb_build_object('ok',false,'error','service_window_closed');
  end if;

  select r.* into v_runtime
  from public.whatsapp_channel_runtime_v1 r
  where r.whatsapp_account_id=v_conversation.whatsapp_account_id
    and r.outbound_provider='papoai'
    and r.send_enabled=true
    and r.human_send_enabled=true
    and r.homologated_at is not null;
  if not found then return jsonb_build_object('ok',false,'error','human_send_not_homologated'); end if;

  select count(*)::integer into v_recent_count
  from public.whatsapp_outbox_v1 o
  where o.conversation_id=p_conversation_id
    and o.purpose='human_attendance'
    and o.created_at>now()-interval '60 seconds'
    and o.status<>'cancelled';
  if v_recent_count>=20 then return jsonb_build_object('ok',false,'error','rate_limited'); end if;

  insert into public.whatsapp_outbox_v1(
    idempotency_key,whatsapp_account_id,conversation_id,customer_id,to_phone_e164,
    purpose,message_type,payload,provider,status,metadata
  ) values (
    v_key,v_conversation.whatsapp_account_id,p_conversation_id,v_conversation.customer_id,v_phone,
    'human_attendance','text',jsonb_build_object('text',v_text),'papoai','queued',
    jsonb_build_object('source','attendance','transport','papoai_inbound_webhook','canonical_message_source','message.sent')
  ) returning id into v_outbox_id;

  return jsonb_build_object('ok',true,'duplicate',false,'conversation_id',p_conversation_id,'outbox_id',v_outbox_id,'status','queued');
end;
$function$
;

-- function: ops2_admin_attendance_enqueue_text_v3(p_conversation_id uuid, p_text text, p_idempotency_key text)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_enqueue_text_v3(p_conversation_id uuid, p_text text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_conversation public.conversations%rowtype;
  v_runtime public.whatsapp_channel_runtime_v1%rowtype;
  v_existing public.whatsapp_outbox_v1%rowtype;
  v_text text:=btrim(coalesce(p_text,''));
  v_client_key text:=btrim(coalesce(p_idempotency_key,''));
  v_key text;
  v_phone text;
  v_provider text;
  v_outbox_id uuid;
  v_recent_count integer:=0;
begin
  if p_conversation_id is null then
    return jsonb_build_object('ok',false,'error','conversation_required');
  end if;
  if v_text='' then
    return jsonb_build_object('ok',false,'error','message_empty');
  end if;
  if char_length(v_text)>4000 then
    return jsonb_build_object('ok',false,'error','message_too_long');
  end if;
  if length(v_client_key)<8 or length(v_client_key)>120 or v_client_key !~ '^[A-Za-z0-9._:-]+$' then
    return jsonb_build_object('ok',false,'error','invalid_idempotency_key');
  end if;

  v_key:='attendance-v3:'||p_conversation_id::text||':'||v_client_key;
  perform pg_advisory_xact_lock(hashtextextended(v_key,0));

  select c.* into v_conversation
  from public.conversations c
  join public.whatsapp_accounts wa
    on wa.id=c.whatsapp_account_id
   and wa.is_active=true
  where c.id=p_conversation_id
    and c.whatsapp_account_id is not null;
  if not found then
    return jsonb_build_object('ok',false,'error','conversation_channel_unavailable');
  end if;

  v_phone:=public.canonical_whatsapp_e164_br_v2(v_conversation.wa_contact_e164);
  if v_phone is null then
    return jsonb_build_object('ok',false,'error','conversation_phone_invalid');
  end if;

  select o.* into v_existing
  from public.whatsapp_outbox_v1 o
  where o.idempotency_key=v_key;
  if found then
    if v_existing.conversation_id is distinct from p_conversation_id
       or coalesce(v_existing.payload->>'text','')<>v_text then
      return jsonb_build_object('ok',false,'error','idempotency_conflict');
    end if;
    return jsonb_build_object(
      'ok',true,
      'duplicate',true,
      'conversation_id',p_conversation_id,
      'outbox_id',v_existing.id,
      'provider',v_existing.provider,
      'status',v_existing.status
    );
  end if;

  if v_conversation.last_inbound_at is null
     or now()>=v_conversation.last_inbound_at+interval '24 hours' then
    return jsonb_build_object('ok',false,'error','service_window_closed');
  end if;

  select r.* into v_runtime
  from public.whatsapp_channel_runtime_v1 r
  where r.whatsapp_account_id=v_conversation.whatsapp_account_id
    and r.send_enabled=true
    and r.human_send_enabled=true
    and r.homologated_at is not null;
  if not found then
    return jsonb_build_object('ok',false,'error','human_send_not_homologated');
  end if;

  v_provider:=v_runtime.outbound_provider;
  if v_provider not in ('papoai','meta') then
    return jsonb_build_object('ok',false,'error','outbound_provider_unavailable');
  end if;

  if v_provider='meta'
     and lower(coalesce(v_runtime.metadata->>'meta_canary_enabled','false'))='true'
     and not exists (
       select 1
       from jsonb_array_elements_text(
         case
           when jsonb_typeof(v_runtime.metadata->'meta_canary_to_e164')='array'
             then v_runtime.metadata->'meta_canary_to_e164'
           else '[]'::jsonb
         end
       ) as allowed(value)
       where public.canonical_whatsapp_e164_br_v2(allowed.value)=v_phone
     ) then
    return jsonb_build_object('ok',false,'error','meta_canary_destination_blocked');
  end if;

  select count(*)::integer into v_recent_count
  from public.whatsapp_outbox_v1 o
  where o.conversation_id=p_conversation_id
    and o.purpose='human_attendance'
    and o.created_at>now()-interval '60 seconds'
    and o.status<>'cancelled';
  if v_recent_count>=20 then
    return jsonb_build_object('ok',false,'error','rate_limited');
  end if;

  insert into public.whatsapp_outbox_v1(
    idempotency_key,
    whatsapp_account_id,
    conversation_id,
    customer_id,
    to_phone_e164,
    purpose,
    message_type,
    payload,
    provider,status,metadata
  ) values (
    v_key,
    v_conversation.whatsapp_account_id,
    p_conversation_id,
    v_conversation.customer_id,
    v_phone,
    'human_attendance',
    'text',
    jsonb_build_object('text',v_text),
    v_provider,'queued',
    jsonb_build_object(
      'source','attendance',
      'contract','provider_neutral_v3',
      'provider',v_provider,
      'meta_canary',v_provider='meta' and lower(coalesce(v_runtime.metadata->>'meta_canary_enabled','false'))='true'
    )
  ) returning id into v_outbox_id;

  return jsonb_build_object(
    'ok',true,
    'duplicate',false,
    'conversation_id',p_conversation_id,
    'outbox_id',v_outbox_id,
    'provider',v_provider,
    'status','queued'
  );
end;
$function$
;

-- function: ops2_admin_attendance_follow_up_v1(p_conversation_id uuid, p_follow_up_at timestamp with time zone)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_follow_up_v1(p_conversation_id uuid, p_follow_up_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_exists boolean;
begin
  select exists(select 1 from public.conversations c where c.id=p_conversation_id) into v_exists;
  if not v_exists then
    return jsonb_build_object('ok',false,'error','conversation_not_found');
  end if;

  if p_follow_up_at is not null and p_follow_up_at<=now() then
    return jsonb_build_object('ok',false,'error','follow_up_must_be_future');
  end if;

  insert into public.attendance_conversation_state_v1(conversation_id,follow_up_at,updated_at)
  values(p_conversation_id,p_follow_up_at,now())
  on conflict(conversation_id) do update set
    follow_up_at=excluded.follow_up_at,
    updated_at=now();

  return jsonb_build_object('ok',true,'conversation_id',p_conversation_id,'follow_up_at',p_follow_up_at);
end;
$function$
;

-- function: ops2_admin_attendance_library_audit_v1(p_admin_user_id uuid, p_item_id uuid, p_conversation_id uuid, p_whatsapp_account_id uuid, p_action text, p_result text, p_error_code text, p_outbox_id uuid, p_message_id uuid, p_provider_message_id text, p_metadata jsonb)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_library_audit_v1(p_admin_user_id uuid, p_item_id uuid, p_conversation_id uuid, p_whatsapp_account_id uuid, p_action text, p_result text, p_error_code text, p_outbox_id uuid, p_message_id uuid, p_provider_message_id text, p_metadata jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid;
begin
  if p_admin_user_id is null or not exists (
    select 1 from public.admin_users a where a.user_id=p_admin_user_id and a.is_active=true
  ) then return jsonb_build_object('ok',false,'error','admin_not_authorized'); end if;
  if trim(coalesce(p_action,''))='' then return jsonb_build_object('ok',false,'error','audit_action_required'); end if;
  if trim(coalesce(p_result,''))='' then return jsonb_build_object('ok',false,'error','audit_result_required'); end if;

  insert into public.attendance_library_audit_v1(
    admin_user_id,item_id,conversation_id,whatsapp_account_id,action,result,error_code,outbox_id,message_id,provider_message_id,metadata
  ) values (
    p_admin_user_id,p_item_id,p_conversation_id,p_whatsapp_account_id,left(trim(p_action),80),left(trim(p_result),40),
    nullif(left(trim(coalesce(p_error_code,'')),180),''),p_outbox_id,p_message_id,nullif(left(trim(coalesce(p_provider_message_id,'')),240),''),coalesce(p_metadata,'{}'::jsonb)
  ) returning id into v_id;
  return jsonb_build_object('ok',true,'audit_id',v_id);
end;
$function$
;

-- function: ops2_admin_attendance_library_deactivate_v1(p_item_id uuid, p_admin_user_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_library_deactivate_v1(p_item_id uuid, p_admin_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid;
begin
  if p_admin_user_id is null or not exists (
    select 1 from public.admin_users a where a.user_id=p_admin_user_id and a.is_active=true
  ) then return jsonb_build_object('ok',false,'error','admin_not_authorized'); end if;

  update public.attendance_library_items_v1
  set is_active=false,deleted_at=coalesce(deleted_at,now()),deleted_by=p_admin_user_id,updated_by=p_admin_user_id,updated_at=now()
  where id=p_item_id and deleted_at is null
  returning id into v_id;
  if v_id is null then return jsonb_build_object('ok',false,'error','library_item_not_found'); end if;

  insert into public.attendance_library_audit_v1(admin_user_id,item_id,action,result)
  values (p_admin_user_id,p_item_id,'item_deactivate','success');
  return jsonb_build_object('ok',true,'item_id',v_id);
end;
$function$
;

-- function: ops2_admin_attendance_library_finalize_v1(p_item_id uuid, p_stored_size_bytes bigint, p_width integer, p_height integer, p_duration_seconds numeric, p_admin_user_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_library_finalize_v1(p_item_id uuid, p_stored_size_bytes bigint, p_width integer, p_height integer, p_duration_seconds numeric, p_admin_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_item public.attendance_library_items_v1%rowtype;
  v_object record;
  v_thumb record;
  v_actual_size bigint;
  v_actual_mime text;
begin
  if p_admin_user_id is null or not exists (
    select 1 from public.admin_users a where a.user_id=p_admin_user_id and a.is_active=true
  ) then
    return jsonb_build_object('ok',false,'error','admin_not_authorized');
  end if;
  if p_item_id is null then return jsonb_build_object('ok',false,'error','library_item_required'); end if;

  select * into v_item from public.attendance_library_items_v1 where id=p_item_id for update;
  if not found then return jsonb_build_object('ok',false,'error','library_item_not_found'); end if;
  if v_item.deleted_at is not null then return jsonb_build_object('ok',false,'error','library_item_inactive'); end if;
  if v_item.upload_status<>'pending' then return jsonb_build_object('ok',false,'error','library_upload_not_pending'); end if;
  if v_item.upload_expires_at is null or v_item.upload_expires_at<now() then
    update public.attendance_library_items_v1 set upload_status='failed',updated_at=now(),updated_by=p_admin_user_id where id=p_item_id;
    return jsonb_build_object('ok',false,'error','library_upload_expired');
  end if;

  select o.name,o.metadata into v_object
  from storage.objects o
  where o.bucket_id='attendance-library-v1' and o.name=v_item.storage_path
  limit 1;
  if not found then return jsonb_build_object('ok',false,'error','library_storage_object_missing'); end if;

  v_actual_size:=case
    when coalesce(v_object.metadata->>'size','') ~ '^[0-9]+$' then (v_object.metadata->>'size')::bigint
    else 0
  end;
  v_actual_mime:=lower(coalesce(v_object.metadata->>'mimetype',v_object.metadata->>'contentType',v_object.metadata->>'content-type',''));

  if v_actual_size<1 or v_actual_size>26214400 then return jsonb_build_object('ok',false,'error','library_stored_size_invalid'); end if;
  if p_stored_size_bytes is null or p_stored_size_bytes<>v_actual_size then return jsonb_build_object('ok',false,'error','library_stored_size_mismatch'); end if;
  if v_actual_mime<>v_item.mime_type then return jsonb_build_object('ok',false,'error','library_storage_mime_mismatch'); end if;

  if v_item.thumbnail_path is not null then
    select o.name,o.metadata into v_thumb
    from storage.objects o
    where o.bucket_id='attendance-library-v1' and o.name=v_item.thumbnail_path
    limit 1;
    if not found then return jsonb_build_object('ok',false,'error','library_thumbnail_missing'); end if;
  end if;

  update public.attendance_library_items_v1
  set stored_size_bytes=v_actual_size,
      width=case when p_width is null or p_width<1 then null else p_width end,
      height=case when p_height is null or p_height<1 then null else p_height end,
      duration_seconds=case when p_duration_seconds is null or p_duration_seconds<0 then null else p_duration_seconds end,
      upload_status='ready',upload_expires_at=null,is_active=true,updated_at=now(),updated_by=p_admin_user_id
  where id=p_item_id
  returning * into v_item;

  insert into public.attendance_library_audit_v1(admin_user_id,item_id,action,result,metadata)
  values (p_admin_user_id,p_item_id,'item_upload_complete','success',jsonb_build_object('stored_size_bytes',v_actual_size));

  return jsonb_build_object('ok',true,'item',to_jsonb(v_item));
end;
$function$
;

-- function: ops2_admin_attendance_library_reserve_v1(p_title text, p_media_kind text, p_mime_type text, p_original_filename text, p_original_size_bytes bigint, p_category text, p_tags text[], p_admin_user_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_library_reserve_v1(p_title text, p_media_kind text, p_mime_type text, p_original_filename text, p_original_size_bytes bigint, p_category text, p_tags text[], p_admin_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid:=gen_random_uuid();
  v_title text:=trim(coalesce(p_title,''));
  v_kind text:=lower(trim(coalesce(p_media_kind,'')));
  v_mime text:=lower(trim(coalesce(p_mime_type,'')));
  v_filename text:=trim(coalesce(p_original_filename,''));
  v_ext text;
  v_storage_path text;
  v_thumbnail_path text;
  v_category text:=nullif(trim(coalesce(p_category,'')),'');
  v_tags text[]:=coalesce(p_tags,'{}'::text[]);
  v_expires timestamptz:=now()+interval '2 hours';
begin
  if p_admin_user_id is null or not exists (
    select 1 from public.admin_users a where a.user_id=p_admin_user_id and a.is_active=true
  ) then
    return jsonb_build_object('ok',false,'error','admin_not_authorized');
  end if;
  if v_title='' then return jsonb_build_object('ok',false,'error','library_title_required'); end if;
  if length(v_title)>120 then return jsonb_build_object('ok',false,'error','library_title_too_long'); end if;
  if v_filename='' then return jsonb_build_object('ok',false,'error','library_filename_required'); end if;
  if p_original_size_bytes is null or p_original_size_bytes<1 or p_original_size_bytes>52428800 then
    return jsonb_build_object('ok',false,'error','library_original_size_invalid');
  end if;
  if v_kind not in ('image','video','audio','document') then
    return jsonb_build_object('ok',false,'error','library_media_kind_invalid');
  end if;

  if v_kind='image' and v_mime not in ('image/jpeg','image/png') then
    return jsonb_build_object('ok',false,'error','library_mime_invalid');
  elsif v_kind='video' and v_mime not in ('video/mp4','video/3gpp') then
    return jsonb_build_object('ok',false,'error','library_mime_invalid');
  elsif v_kind='audio' and v_mime not in ('audio/aac','audio/amr','audio/mpeg','audio/mp4','audio/ogg') then
    return jsonb_build_object('ok',false,'error','library_mime_invalid');
  elsif v_kind='document' and v_mime not in (
    'application/pdf','text/plain','application/msword',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'application/vnd.ms-excel','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    'application/vnd.ms-powerpoint','application/vnd.openxmlformats-officedocument.presentationml.presentation'
  ) then
    return jsonb_build_object('ok',false,'error','library_mime_invalid');
  end if;

  v_ext:=case v_mime
    when 'image/jpeg' then 'jpg'
    when 'image/png' then 'png'
    when 'video/mp4' then 'mp4'
    when 'video/3gpp' then '3gp'
    when 'audio/aac' then 'aac'
    when 'audio/amr' then 'amr'
    when 'audio/mpeg' then 'mp3'
    when 'audio/mp4' then 'm4a'
    when 'audio/ogg' then 'ogg'
    when 'application/pdf' then 'pdf'
    when 'text/plain' then 'txt'
    when 'application/msword' then 'doc'
    when 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' then 'docx'
    when 'application/vnd.ms-excel' then 'xls'
    when 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' then 'xlsx'
    when 'application/vnd.ms-powerpoint' then 'ppt'
    when 'application/vnd.openxmlformats-officedocument.presentationml.presentation' then 'pptx'
    else null
  end;
  if v_ext is null then return jsonb_build_object('ok',false,'error','library_mime_invalid'); end if;

  v_storage_path:='items/'||v_id::text||'/asset.'||v_ext;
  v_thumbnail_path:=case when v_kind='image' then 'items/'||v_id::text||'/thumb.jpg' else null end;

  insert into public.attendance_library_items_v1(
    id,title,media_kind,mime_type,storage_path,thumbnail_path,original_filename,original_size_bytes,
    category,tags,upload_status,upload_expires_at,is_active,created_by,updated_by
  ) values (
    v_id,v_title,v_kind,v_mime,v_storage_path,v_thumbnail_path,left(v_filename,255),p_original_size_bytes,
    v_category,v_tags,'pending',v_expires,false,p_admin_user_id,p_admin_user_id
  );

  insert into public.attendance_library_audit_v1(admin_user_id,item_id,action,result,metadata)
  values (p_admin_user_id,v_id,'item_create','success',jsonb_build_object('media_kind',v_kind,'mime_type',v_mime));

  return jsonb_build_object(
    'ok',true,
    'item_id',v_id,
    'storage_path',v_storage_path,
    'thumbnail_path',v_thumbnail_path,
    'upload_expires_at',v_expires
  );
end;
$function$
;

-- function: ops2_admin_attendance_library_update_v1(p_item_id uuid, p_title text, p_category text, p_tags text[], p_sort_order integer, p_admin_user_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_library_update_v1(p_item_id uuid, p_title text, p_category text, p_tags text[], p_sort_order integer, p_admin_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_item public.attendance_library_items_v1%rowtype;
  v_title text:=trim(coalesce(p_title,''));
begin
  if p_admin_user_id is null or not exists (
    select 1 from public.admin_users a where a.user_id=p_admin_user_id and a.is_active=true
  ) then return jsonb_build_object('ok',false,'error','admin_not_authorized'); end if;
  if v_title='' then return jsonb_build_object('ok',false,'error','library_title_required'); end if;
  if length(v_title)>120 then return jsonb_build_object('ok',false,'error','library_title_too_long'); end if;

  update public.attendance_library_items_v1
  set title=v_title,category=nullif(trim(coalesce(p_category,'')),''),tags=coalesce(p_tags,'{}'::text[]),
      sort_order=coalesce(p_sort_order,0),updated_by=p_admin_user_id,updated_at=now()
  where id=p_item_id and is_active=true and upload_status='ready' and deleted_at is null
  returning * into v_item;
  if not found then return jsonb_build_object('ok',false,'error','library_item_inactive'); end if;

  insert into public.attendance_library_audit_v1(admin_user_id,item_id,action,result)
  values (p_admin_user_id,p_item_id,'item_update','success');
  return jsonb_build_object('ok',true,'item',to_jsonb(v_item));
end;
$function$
;

-- function: ops2_admin_attendance_link_customer_v1(p_conversation_id uuid, p_customer_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_link_customer_v1(p_conversation_id uuid, p_customer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_conversation public.conversations%rowtype;
  v_phone text;
begin
  if p_conversation_id is null then
    return jsonb_build_object('ok',false,'error','invalid_conversation_id');
  end if;
  if p_customer_id is null then
    return jsonb_build_object('ok',false,'error','invalid_customer_id');
  end if;
  if not exists(select 1 from public.customers c where c.id=p_customer_id) then
    return jsonb_build_object('ok',false,'error','customer_not_found');
  end if;

  perform pg_advisory_xact_lock(hashtextextended('attendance-customer:'||p_conversation_id::text,0));

  select c.* into v_conversation
  from public.conversations c
  where c.id=p_conversation_id
  for update;

  if not found then
    return jsonb_build_object('ok',false,'error','conversation_not_found');
  end if;

  v_phone:=public.canonical_whatsapp_e164_br_v2(v_conversation.wa_contact_e164);

  if v_conversation.customer_id is not null and v_conversation.customer_id<>p_customer_id then
    return jsonb_build_object(
      'ok',false,
      'error','conversation_already_linked',
      'customer_id',v_conversation.customer_id,
      'phone_e164',v_phone
    );
  end if;

  update public.conversations
  set customer_id=p_customer_id,updated_at=now()
  where id=p_conversation_id;

  update public.whatsapp_messages_v1
  set customer_id=p_customer_id
  where conversation_id=p_conversation_id and customer_id is null;

  return jsonb_build_object(
    'ok',true,
    'linked',true,
    'changed',v_conversation.customer_id is null,
    'customer_id',p_customer_id,
    'phone_e164',v_phone
  );
end;
$function$
;

-- function: ops2_admin_attendance_mark_read_v1(p_conversation_id uuid, p_message_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_mark_read_v1(p_conversation_id uuid, p_message_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_message_at timestamptz;
  v_last_read_at timestamptz;
begin
  select coalesce(m.received_at,m.sent_at,m.created_at)
    into v_message_at
  from public.whatsapp_messages_v1 m
  where m.id=p_message_id and m.conversation_id=p_conversation_id;

  if not found then
    return jsonb_build_object('ok',false,'error','message_not_in_conversation');
  end if;

  insert into public.attendance_conversation_state_v1(
    conversation_id,last_read_message_id,last_read_at,updated_at
  ) values (
    p_conversation_id,p_message_id,v_message_at,now()
  )
  on conflict (conversation_id) do update set
    last_read_message_id=case
      when public.attendance_conversation_state_v1.last_read_at is null
        or excluded.last_read_at>=public.attendance_conversation_state_v1.last_read_at
      then excluded.last_read_message_id
      else public.attendance_conversation_state_v1.last_read_message_id
    end,
    last_read_at=greatest(
      coalesce(public.attendance_conversation_state_v1.last_read_at,'epoch'::timestamptz),
      excluded.last_read_at
    ),
    updated_at=now()
  returning last_read_at into v_last_read_at;

  return jsonb_build_object('ok',true,'conversation_id',p_conversation_id,'last_read_at',v_last_read_at);
end;
$function$
;

-- function: ops2_admin_attendance_marketing_optout_v1(p_conversation_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_marketing_optout_v1(p_conversation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_customer_id uuid; v_previous_opt_in boolean; v_record jsonb; begin
  if p_conversation_id is null then return jsonb_build_object('ok',false,'error','invalid_conversation_id'); end if;
  select c.customer_id into v_customer_id from public.conversations c where c.id=p_conversation_id limit 1;
  if not found then return jsonb_build_object('ok',false,'error','conversation_not_found'); end if;
  if v_customer_id is null then return jsonb_build_object('ok',false,'error','customer_not_linked'); end if;
  select coalesce(marketing_opt_in,false) into v_previous_opt_in from public.customers where id=v_customer_id;
  v_record := public.marketing_record_consent_v1(v_customer_id,'opt_out','attendance_manual_optout',p_conversation_id::text,null,null,null,now(),'admin_attendance',jsonb_build_object('conversation_id',p_conversation_id));
  if coalesce((v_record->>'ok')::boolean,false) is not true then return v_record; end if;
  perform public.marketing_repurchase_recalc_v1(v_customer_id);
  return jsonb_build_object('ok',true,'customer_id',v_customer_id,'marketing_opt_in',false,'changed',v_previous_opt_in,'consent_event_id',v_record->>'event_id');
end; $function$
;

-- function: ops2_admin_attendance_media_canary_guard_v1()
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_media_canary_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_runtime public.whatsapp_channel_runtime_v1%rowtype;
  v_phone text;
  v_live boolean:=false;
  v_canary boolean:=false;
  v_image_live boolean:=false;
  v_document_live boolean:=false;
  v_readiness jsonb;
begin
  if new.purpose='human_attendance'
     and new.provider='meta'
     and new.message_type in ('image','audio','document')
     and (
       tg_op='INSERT'
       or (tg_op='UPDATE' and old.status is distinct from new.status and new.status='claimed')
     ) then

    select r.* into v_runtime
    from public.whatsapp_channel_runtime_v1 r
    where r.whatsapp_account_id=new.whatsapp_account_id
      and r.send_enabled=true
      and r.human_send_enabled=true
      and r.homologated_at is not null
      and r.outbound_provider='meta';

    if not found then
      raise exception using errcode='P0001',message='human_send_not_homologated';
    end if;

    v_live:=lower(coalesce(v_runtime.metadata->>'meta_media_live_enabled','false'))='true';
    v_canary:=lower(coalesce(v_runtime.metadata->>'meta_media_canary_enabled','false'))='true';
    v_image_live:=new.message_type='image'
      and lower(coalesce(v_runtime.metadata->>'meta_image_live_enabled','false'))='true';
    v_document_live:=new.message_type='document'
      and lower(coalesce(v_runtime.metadata->>'meta_document_live_enabled','false'))='true';
    v_phone:=public.canonical_whatsapp_e164_br_v2(new.to_phone_e164);

    if v_phone is null then
      raise exception using errcode='P0001',message='meta_canary_destination_blocked';
    end if;

    if v_live then
      v_readiness:=public.ops2_attendance_media_live_readiness_v1(new.whatsapp_account_id);
      if coalesce((v_readiness->>'ready')::boolean,false) is not true then
        raise exception using errcode='P0001',message='meta_media_live_not_ready';
      end if;
    elsif v_image_live or v_document_live then
      -- Graduacao independente de imagem/documento, sem abrir audio.
      -- Validacoes de destino, MIME/tamanho, janela e transporte ja ocorrem
      -- no caminho de enqueue/claim e no gateway Meta existente.
      null;
    else
      if not v_canary then
        raise exception using errcode='P0001',message='meta_media_canary_not_enabled';
      end if;

      if not exists (
        select 1
        from jsonb_array_elements_text(
          case
            when jsonb_typeof(v_runtime.metadata->'meta_media_canary_to_e164')='array'
              then v_runtime.metadata->'meta_media_canary_to_e164'
            else '[]'::jsonb
          end
        ) as allowed(value)
        where public.canonical_whatsapp_e164_br_v2(allowed.value)=v_phone
      ) then
        raise exception using errcode='P0001',message='meta_canary_destination_blocked';
      end if;
    end if;

    new.metadata:=coalesce(new.metadata,'{}'::jsonb)||jsonb_build_object(
      'meta_media_mode',case when v_live or v_image_live or v_document_live then 'live' else 'canary' end,
      'meta_media_live',v_live,
      'meta_image_live',v_image_live,
      'meta_document_live',v_document_live,
      'meta_media_canary',not (v_live or v_image_live or v_document_live) and v_canary
    );
  end if;

  return new;
end;
$function$
;

-- function: ops2_admin_attendance_queue_v1(p_whatsapp_account_id uuid, p_limit integer, p_search text, p_filter text)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_queue_v1(p_whatsapp_account_id uuid, p_limit integer DEFAULT 50, p_search text DEFAULT NULL::text, p_filter text DEFAULT 'all'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_limit integer := least(50,greatest(1,coalesce(p_limit,50)));
  v_search text := nullif(btrim(coalesce(p_search,'')),'');
  v_filter text := case lower(btrim(coalesce(p_filter,'all')))
    when 'unread' then 'unread'
    when 'human' then 'human'
    else 'all'
  end;
  v_account public.whatsapp_accounts%rowtype;
  v_rows jsonb;
begin
  select wa.* into v_account
  from public.whatsapp_accounts wa
  where wa.id=p_whatsapp_account_id and wa.is_active=true;

  if not found then
    return jsonb_build_object('ok',false,'error','whatsapp_account_not_found');
  end if;

  with queue_base as (
    select
      c.id as conversation_id,
      c.whatsapp_account_id,
      c.customer_id,
      coalesce(nullif(btrim(cu.name),''),public.canonical_whatsapp_e164_br_v2(c.wa_contact_e164),c.wa_contact_e164) as display_name,
      public.canonical_whatsapp_e164_br_v2(c.wa_contact_e164) as phone_e164,
      c.status,
      c.mode,
      c.stage,
      coalesce(c.human_required,false) as human_required,
      c.last_inbound_at,
      c.last_outbound_at,
      c.service_window_expires_at,
      greatest(
        coalesce(lm.message_at,'epoch'::timestamptz),
        coalesce(c.last_inbound_at,'epoch'::timestamptz),
        coalesce(c.last_outbound_at,'epoch'::timestamptz),
        coalesce(c.created_at,'epoch'::timestamptz)
      ) as last_activity_at,
      coalesce(st.follow_up_at,null) as follow_up_at,
      coalesce(unread.unread_count,0)::integer as unread_count,
      lm.text_body as last_message_text,
      lm.message_type as last_message_type,
      lm.direction as last_message_direction,
      lm.message_at as last_message_at,
      exists(
        select 1 from public.orders o
        where o.conversation_id=c.id
           or (c.customer_id is not null and o.customer_id=c.customer_id)
      ) as has_order,
      case
        when c.customer_id is null then true
        else coalesce((public.ops2_customer_registration_state_v1(c.customer_id)->>'registration_complete')::boolean,false) is not true
      end as registration_incomplete
    from public.conversations c
    left join public.customers cu on cu.id=c.customer_id
    left join public.attendance_conversation_state_v1 st on st.conversation_id=c.id
    left join lateral (
      select count(*)::integer as unread_count
      from public.whatsapp_messages_v1 m
      where m.conversation_id=c.id
        and m.whatsapp_account_id=c.whatsapp_account_id
        and m.direction='inbound'
        and coalesce(m.received_at,m.sent_at,m.created_at) > coalesce(st.last_read_at,'epoch'::timestamptz)
    ) unread on true
    left join lateral (
      select
        m.text_body,
        m.message_type,
        m.direction,
        coalesce(m.received_at,m.sent_at,m.created_at) as message_at
      from public.whatsapp_messages_v1 m
      where m.conversation_id=c.id
        and m.whatsapp_account_id=c.whatsapp_account_id
      order by coalesce(m.received_at,m.sent_at,m.created_at) desc,m.created_at desc,m.id desc
      limit 1
    ) lm on true
    where c.whatsapp_account_id=p_whatsapp_account_id
      and (
        v_search is null
        or coalesce(cu.name,'') ilike '%'||v_search||'%'
        or coalesce(public.canonical_whatsapp_e164_br_v2(c.wa_contact_e164),c.wa_contact_e164,'') ilike '%'||v_search||'%'
      )
  ), filtered as (
    select q.*
    from queue_base q
    where v_filter='all'
       or (v_filter='unread' and q.unread_count>0)
       or (v_filter='human' and (q.human_required or q.mode in ('human','human_copilot') or q.status='needs_human'))
  ), limited as (
    select q.*
    from filtered q
    order by q.last_activity_at desc, q.conversation_id
    limit v_limit
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'conversation_id',q.conversation_id,
    'whatsapp_account_id',q.whatsapp_account_id,
    'customer_id',q.customer_id,
    'display_name',q.display_name,
    'phone_e164',q.phone_e164,
    'status',q.status,
    'mode',q.mode,
    'stage',q.stage,
    'human_required',q.human_required,
    'unread_count',q.unread_count,
    'last_message_text',q.last_message_text,
    'last_message_type',q.last_message_type,
    'last_message_direction',q.last_message_direction,
    'last_message_at',q.last_message_at,
    'last_inbound_at',q.last_inbound_at,
    'last_outbound_at',q.last_outbound_at,
    'service_window_expires_at',q.service_window_expires_at,
    'last_activity_at',q.last_activity_at,
    'follow_up_at',q.follow_up_at,
    'has_order',q.has_order,
    'registration_incomplete',q.registration_incomplete
  ) order by q.last_activity_at desc, q.conversation_id),'[]'::jsonb)
  into v_rows
  from limited q;

  return jsonb_build_object(
    'ok',true,
    'account',jsonb_build_object(
      'id',v_account.id,
      'slug',v_account.slug,
      'display_name',v_account.display_name,
      'phone_e164',v_account.phone_e164
    ),
    'filter',v_filter,
    'limit',v_limit,
    'items',v_rows
  );
end;
$function$
;

-- function: ops2_admin_attendance_queue_v2(p_whatsapp_account_id uuid, p_limit integer, p_search text)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_queue_v2(p_whatsapp_account_id uuid, p_limit integer DEFAULT 50, p_search text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_limit integer := least(50,greatest(1,coalesce(p_limit,50)));
  v_search text := nullif(btrim(coalesce(p_search,'')),'');
  v_account public.whatsapp_accounts%rowtype;
  v_rows jsonb;
begin
  select wa.* into v_account
  from public.whatsapp_accounts wa
  where wa.id=p_whatsapp_account_id and wa.is_active=true;

  if not found then
    return jsonb_build_object('ok',false,'error','whatsapp_account_not_found');
  end if;

  with queue_base as (
    select
      c.id as conversation_id,
      c.whatsapp_account_id,
      c.customer_id,
      coalesce(nullif(btrim(cu.name),''),public.canonical_whatsapp_e164_br_v2(c.wa_contact_e164),c.wa_contact_e164) as display_name,
      public.canonical_whatsapp_e164_br_v2(c.wa_contact_e164) as phone_e164,
      c.status,
      c.mode,
      c.stage,
      coalesce(c.human_required,false) as human_required,
      c.last_inbound_at,
      c.last_outbound_at,
      c.service_window_expires_at,
      coalesce(lm.message_at,c.created_at) as last_message_at,
      st.follow_up_at,
      coalesce(unread.unread_count,0)::integer as unread_count,
      lm.text_body as last_message_text,
      lm.message_type as last_message_type,
      lm.direction as last_message_direction,
      exists(
        select 1
        from public.orders o
        where o.conversation_id=c.id
           or (c.customer_id is not null and o.customer_id=c.customer_id)
      ) as has_order,
      case
        when c.customer_id is null then true
        else coalesce((public.ops2_customer_registration_state_v1(c.customer_id)->>'registration_complete')::boolean,false) is not true
      end as registration_incomplete
    from public.conversations c
    left join public.customers cu on cu.id=c.customer_id
    left join public.attendance_conversation_state_v1 st on st.conversation_id=c.id
    left join lateral (
      select count(*)::integer as unread_count
      from public.whatsapp_messages_v1 m
      where m.conversation_id=c.id
        and m.whatsapp_account_id=c.whatsapp_account_id
        and m.direction='inbound'
        and coalesce(m.received_at,m.sent_at,m.created_at) > coalesce(st.last_read_at,'epoch'::timestamptz)
    ) unread on true
    left join lateral (
      select
        m.text_body,
        m.message_type,
        m.direction,
        coalesce(m.received_at,m.sent_at,m.created_at) as message_at
      from public.whatsapp_messages_v1 m
      where m.conversation_id=c.id
        and m.whatsapp_account_id=c.whatsapp_account_id
      order by coalesce(m.received_at,m.sent_at,m.created_at) desc,m.created_at desc,m.id desc
      limit 1
    ) lm on true
    where c.whatsapp_account_id=p_whatsapp_account_id
      and (
        v_search is null
        or coalesce(cu.name,'') ilike '%'||v_search||'%'
        or coalesce(public.canonical_whatsapp_e164_br_v2(c.wa_contact_e164),c.wa_contact_e164,'') ilike '%'||v_search||'%'
      )
  ), limited as (
    select q.*
    from queue_base q
    order by q.last_message_at desc, q.conversation_id
    limit v_limit
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'conversation_id',q.conversation_id,
    'whatsapp_account_id',q.whatsapp_account_id,
    'customer_id',q.customer_id,
    'display_name',q.display_name,
    'phone_e164',q.phone_e164,
    'status',q.status,
    'mode',q.mode,
    'stage',q.stage,
    'human_required',q.human_required,
    'unread_count',q.unread_count,
    'last_message_text',q.last_message_text,
    'last_message_type',q.last_message_type,
    'last_message_direction',q.last_message_direction,
    'last_message_at',q.last_message_at,
    'canonical_last_message_at',q.last_message_at,
    'last_activity_at',q.last_message_at,
    'last_inbound_at',q.last_inbound_at,
    'last_outbound_at',q.last_outbound_at,
    'service_window_expires_at',q.service_window_expires_at,
    'follow_up_at',q.follow_up_at,
    'has_order',q.has_order,
    'registration_incomplete',q.registration_incomplete
  ) order by q.last_message_at desc, q.conversation_id),'[]'::jsonb)
  into v_rows
  from limited q;

  return jsonb_build_object(
    'ok',true,
    'account',jsonb_build_object(
      'id',v_account.id,
      'slug',v_account.slug,
      'display_name',v_account.display_name,
      'phone_e164',v_account.phone_e164
    ),
    'limit',v_limit,
    'items',v_rows
  );
end;
$function$
;

-- function: ops2_admin_attendance_queue_v3(p_whatsapp_account_id uuid, p_limit integer, p_search text, p_label_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_queue_v3(p_whatsapp_account_id uuid, p_limit integer DEFAULT 50, p_search text DEFAULT NULL::text, p_label_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select public.ops2_admin_attendance_queue_v4(
    p_whatsapp_account_id,
    p_limit,
    p_search,
    p_label_id
  );
$function$
;

-- function: ops2_admin_attendance_queue_v4(p_whatsapp_account_id uuid, p_limit integer, p_search text, p_label_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_queue_v4(p_whatsapp_account_id uuid, p_limit integer DEFAULT 50, p_search text DEFAULT NULL::text, p_label_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_limit integer := least(50,greatest(1,coalesce(p_limit,50)));
  v_search text := nullif(btrim(coalesce(p_search,'')),'');
  v_account public.whatsapp_accounts%rowtype;
  v_rows jsonb;
  v_recent_from timestamptz := ((((now() at time zone 'America/Cuiaba')::date - 2)::timestamp) at time zone 'America/Cuiaba');
begin
  select wa.* into v_account
  from public.whatsapp_accounts wa
  where wa.id=p_whatsapp_account_id and wa.is_active=true;
  if not found then return jsonb_build_object('ok',false,'error','whatsapp_account_not_found'); end if;

  if p_label_id is not null and not exists(
    select 1 from public.attendance_labels_v1 l where l.id=p_label_id and l.is_active=true
  ) then
    return jsonb_build_object('ok',false,'error','attendance_label_not_found');
  end if;

  with latest_message_dates as materialized (
    select m.conversation_id,
           max(coalesce(m.received_at,m.sent_at,m.created_at)) as message_at
      from public.whatsapp_messages_v1 m
     where m.whatsapp_account_id=p_whatsapp_account_id
     group by m.conversation_id
  ), pending_orders as materialized (
    select o.id,o.created_at,o.conversation_id,o.whatsapp_account_id,o.customer_id,
           public.canonical_whatsapp_e164_br_v2(o.phone_e164) as phone_key
      from public.orders o
     where o.status='storefront_received'
       and o.confirmed_at is null
       and o.cancelled_at is null
       and o.created_at>=now()-interval '3 days'
  ), conversation_keys as materialized (
    select c.id,c.whatsapp_account_id,c.customer_id,
           public.canonical_whatsapp_e164_br_v2(c.wa_contact_e164) as phone_key
      from public.conversations c
  ), order_candidates as materialized (
    select o.id as order_id,o.created_at as received_at,c.id as conversation_id,
           o.whatsapp_account_id,o.conversation_id as explicit_conversation_id,
           count(*) over(partition by o.id)::integer as candidate_count
      from pending_orders o
      join conversation_keys c
        on (
          (o.conversation_id is not null and c.id=o.conversation_id)
          or (
            o.conversation_id is null
            and (o.whatsapp_account_id is null or o.whatsapp_account_id=c.whatsapp_account_id)
            and (
              (o.customer_id is not null and c.customer_id=o.customer_id)
              or (o.phone_key is not null and c.phone_key=o.phone_key)
            )
          )
        )
  ), priority_orders as materialized (
    select oc.conversation_id,max(oc.received_at) as received_at
      from order_candidates oc
     where oc.explicit_conversation_id is not null
        or oc.whatsapp_account_id is not null
        or oc.candidate_count=1
     group by oc.conversation_id
  ), priority_candidates as materialized (
    select c.id,
           coalesce(lm.message_at,c.created_at) as latest_at,
           po.received_at
      from public.conversations c
      left join latest_message_dates lm on lm.conversation_id=c.id
      left join priority_orders po on po.conversation_id=c.id
     where c.whatsapp_account_id=p_whatsapp_account_id
       and (
         v_search is null
         or exists (
           select 1 from public.customers cu
            where cu.id=c.customer_id and coalesce(cu.name,'') ilike '%'||v_search||'%'
         )
         or coalesce(public.canonical_whatsapp_e164_br_v2(c.wa_contact_e164),c.wa_contact_e164,'') ilike '%'||v_search||'%'
       )
       and (
         p_label_id is null
         or exists (
           select 1 from public.attendance_conversation_labels_v1 al
            where al.conversation_id=c.id and al.label_id=p_label_id
         )
       )
  ),
  selected_conversations as materialized (
    select c.*
      from priority_candidates pc
      join public.conversations c on c.id=pc.id
     order by (pc.received_at is not null) desc,
              pc.received_at desc,pc.latest_at desc,pc.id
     limit v_limit
  ), queue_base as (
    select
      c.id as conversation_id,
      c.whatsapp_account_id,
      c.customer_id,
      coalesce(nullif(btrim(cu.name),''),public.canonical_whatsapp_e164_br_v2(c.wa_contact_e164),c.wa_contact_e164) as display_name,
      public.canonical_whatsapp_e164_br_v2(c.wa_contact_e164) as phone_e164,
      c.status,c.mode,c.stage,coalesce(c.human_required,false) as human_required,
      c.last_inbound_at,c.last_outbound_at,c.service_window_expires_at,
      coalesce(lm.message_at,c.created_at) as canonical_last_message_at,
      st.follow_up_at,
      coalesce(unread.unread_count,0)::integer as unread_count,
      lm.text_body as last_message_text,lm.message_type as last_message_type,lm.direction as last_message_direction,
      coalesce(lbl.labels,'[]'::jsonb) as labels,
      exists(
        select 1 from public.orders o
        where o.conversation_id=c.id or (c.customer_id is not null and o.customer_id=c.customer_id)
      ) as has_order,
      recent_order.recent_order_at,
      received_order.received_order_id,
      received_order.received_order_number,
      received_order.received_order_at,
      received_order.received_order_count,
      (recent_order.recent_order_at is not null) as has_recent_order,
      case
        when c.customer_id is null then true
        else coalesce((public.ops2_customer_registration_state_v1(c.customer_id)->>'registration_complete')::boolean,false) is not true
      end as registration_incomplete
    from selected_conversations c
    left join public.customers cu on cu.id=c.customer_id
    left join public.attendance_conversation_state_v1 st on st.conversation_id=c.id
    left join lateral (
      select count(*)::integer as unread_count from public.whatsapp_messages_v1 m
      where m.conversation_id=c.id and m.whatsapp_account_id=c.whatsapp_account_id and m.direction='inbound'
        and coalesce(m.received_at,m.sent_at,m.created_at)>coalesce(st.last_read_at,'epoch'::timestamptz)
    ) unread on true
    left join lateral (
      select m.text_body,m.message_type,m.direction,coalesce(m.received_at,m.sent_at,m.created_at) as message_at
      from public.whatsapp_messages_v1 m
      where m.conversation_id=c.id and m.whatsapp_account_id=c.whatsapp_account_id
      order by coalesce(m.received_at,m.sent_at,m.created_at) desc,m.created_at desc,m.id desc limit 1
    ) lm on true
    left join lateral (
      select jsonb_agg(
        jsonb_build_object('id',l.id,'name',l.name,'color',l.color,'sort_order',l.sort_order)
        order by l.sort_order,l.name
      ) as labels
      from public.attendance_conversation_labels_v1 cl
      join public.attendance_labels_v1 l on l.id=cl.label_id and l.is_active=true
      where cl.conversation_id=c.id
    ) lbl on true
    left join lateral (
      select max(o.created_at) as recent_order_at
      from public.orders o
      where (o.conversation_id=c.id or (c.customer_id is not null and o.customer_id=c.customer_id))
        and o.created_at >= v_recent_from
    ) recent_order on true
    left join lateral (
      select
        o.id as received_order_id,
        o.order_number as received_order_number,
        o.created_at as received_order_at,
        count(*) over()::integer as received_order_count
      from public.orders o
      where o.status='storefront_received'
        and o.confirmed_at is null
        and o.cancelled_at is null
        and o.created_at >= now()-interval '3 days'
        and (
          o.conversation_id=c.id
          or (
            o.conversation_id is null
            and (o.whatsapp_account_id is null or o.whatsapp_account_id=c.whatsapp_account_id)
            and (
              (o.customer_id is not null and o.customer_id=c.customer_id)
              or (
                public.canonical_whatsapp_e164_br_v2(o.phone_e164) is not null
                and public.canonical_whatsapp_e164_br_v2(o.phone_e164)=public.canonical_whatsapp_e164_br_v2(c.wa_contact_e164)
              )
            )
            -- Um pedido sem canal não deve ser associado a conversas ambíguas.
            and (
              o.whatsapp_account_id is not null
              or not exists (
                select 1 from public.conversations alt
                where alt.id<>c.id
                  and (
                    (o.customer_id is not null and alt.customer_id=o.customer_id)
                    or (
                      public.canonical_whatsapp_e164_br_v2(o.phone_e164) is not null
                      and public.canonical_whatsapp_e164_br_v2(alt.wa_contact_e164)=public.canonical_whatsapp_e164_br_v2(o.phone_e164)
                    )
                  )
              )
            )
          )
        )
      order by o.created_at desc,o.id desc
      limit 1
    ) received_order on true
    where c.whatsapp_account_id=p_whatsapp_account_id
      and (
        v_search is null
        or coalesce(cu.name,'') ilike '%'||v_search||'%'
        or coalesce(public.canonical_whatsapp_e164_br_v2(c.wa_contact_e164),c.wa_contact_e164,'') ilike '%'||v_search||'%'
      )
      and (
        p_label_id is null
        or exists(
          select 1 from public.attendance_conversation_labels_v1 f
          where f.conversation_id=c.id and f.label_id=p_label_id
        )
      )
  ), limited as (
    select q.* from queue_base q
    order by (q.received_order_id is not null) desc, q.received_order_at desc, q.canonical_last_message_at desc,q.conversation_id
    limit v_limit
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'conversation_id',q.conversation_id,
    'whatsapp_account_id',q.whatsapp_account_id,
    'customer_id',q.customer_id,
    'display_name',q.display_name,
    'phone_e164',q.phone_e164,
    'status',q.status,
    'mode',q.mode,
    'stage',q.stage,
    'human_required',q.human_required,
    'unread_count',q.unread_count,
    'last_message_text',q.last_message_text,
    'last_message_type',q.last_message_type,
    'last_message_direction',q.last_message_direction,
    'last_message_at',q.canonical_last_message_at,
    'canonical_last_message_at',q.canonical_last_message_at,
    'last_activity_at',q.canonical_last_message_at,
    'last_inbound_at',q.last_inbound_at,
    'last_outbound_at',q.last_outbound_at,
    'service_window_expires_at',q.service_window_expires_at,
    'follow_up_at',q.follow_up_at,
    'has_order',q.has_order,
    'has_recent_order',q.has_recent_order,
    'recent_order_at',q.recent_order_at,
    'received_order_id',q.received_order_id,
    'received_order_number',q.received_order_number,
    'received_order_at',q.received_order_at,
    'received_order_count',coalesce(q.received_order_count,0),
    'registration_incomplete',q.registration_incomplete,
    'labels',q.labels
  ) order by (q.received_order_id is not null) desc, q.received_order_at desc, q.canonical_last_message_at desc,q.conversation_id),'[]'::jsonb)
  into v_rows from limited q;

  return jsonb_build_object(
    'ok',true,
    'account',jsonb_build_object('id',v_account.id,'slug',v_account.slug,'display_name',v_account.display_name,'phone_e164',v_account.phone_e164),
    'limit',v_limit,
    'label_id',p_label_id,
    'recent_from',v_recent_from,
    'items',v_rows
  );
end;
$function$
;

-- function: ops2_admin_attendance_reconcile_customer_v1(p_conversation_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_reconcile_customer_v1(p_conversation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_conversation public.conversations%rowtype;
  v_resolution jsonb;
  v_customer_id uuid;
  v_phone text;
  v_order_customer_count integer;
  v_order_customer_id uuid;
begin
  if p_conversation_id is null then
    return jsonb_build_object('ok',false,'error','invalid_conversation_id');
  end if;

  perform pg_advisory_xact_lock(hashtextextended('attendance-customer:'||p_conversation_id::text,0));

  select c.* into v_conversation
  from public.conversations c
  where c.id=p_conversation_id
  for update;

  if not found then
    return jsonb_build_object('ok',false,'error','conversation_not_found');
  end if;

  v_phone:=public.canonical_whatsapp_e164_br_v2(v_conversation.wa_contact_e164);
  if v_phone is null then
    return jsonb_build_object('ok',false,'error','invalid_phone','match_status','invalid');
  end if;

  if v_conversation.customer_id is not null then
    return jsonb_build_object(
      'ok',true,
      'match_status','linked',
      'linked',true,
      'changed',false,
      'customer_id',v_conversation.customer_id,
      'phone_e164',v_phone
    );
  end if;

  v_resolution:=public.resolve_customer_by_phone_v1(v_phone);

  if v_resolution->>'match_status'='ambiguous' then
    -- A conversation may have an explicit storefront order, which is stronger
    -- evidence than phone variants shared by multiple historical registrations.
    -- Never guess based solely on name, Bling presence, or completion level.
    select count(distinct o.customer_id), min(o.customer_id::text)::uuid
      into v_order_customer_count,v_order_customer_id
      from public.orders o
      join public.customers cu on cu.id=o.customer_id and cu.is_active=true
     where o.conversation_id=p_conversation_id
       and public.canonical_whatsapp_e164_br_v2(o.phone_e164)=v_phone
       and public.canonical_whatsapp_e164_br_v2(cu.primary_whatsapp_e164)=v_phone
       and o.customer_id in (
         select ids.customer_id
           from public.customer_ids_by_phone_variants_v1(v_phone) ids
       );
    if v_order_customer_count=1 then
      v_resolution:=jsonb_build_object('ok',true,'match_status','matched',
        'customer_id',v_order_customer_id,'reason','conversation_order_verified');
    else
      return jsonb_build_object(
        'ok',true,
        'match_status','ambiguous',
        'linked',false,
        'changed',false,
        'candidate_count',coalesce((v_resolution->>'candidate_count')::integer,0),
        'phone_e164',v_phone
      );
    end if;
  end if;

  if v_resolution->>'match_status'='none' then
    return jsonb_build_object(
      'ok',true,
      'match_status','none',
      'linked',false,
      'changed',false,
      'candidate_count',0,
      'phone_e164',v_phone
    );
  end if;

  if v_resolution->>'match_status'<>'matched' then
    return jsonb_build_object(
      'ok',false,
      'error',coalesce(v_resolution->>'error','customer_resolution_failed'),
      'match_status',coalesce(v_resolution->>'match_status','invalid'),
      'linked',false,
      'phone_e164',v_phone
    );
  end if;

  v_customer_id:=nullif(v_resolution->>'customer_id','')::uuid;
  if v_customer_id is null or not exists(select 1 from public.customers c where c.id=v_customer_id) then
    return jsonb_build_object('ok',false,'error','customer_resolution_failed','match_status','invalid');
  end if;

  update public.conversations
  set customer_id=v_customer_id,updated_at=now()
  where id=p_conversation_id and customer_id is null;

  update public.whatsapp_messages_v1
  set customer_id=v_customer_id
  where conversation_id=p_conversation_id and customer_id is null;

  return jsonb_build_object(
    'ok',true,
    'match_status','matched',
    'linked',true,
    'changed',true,
    'customer_id',v_customer_id,
    'phone_e164',v_phone
  );
end;
$function$
;

-- function: ops2_admin_attendance_requeue_failed_media_v1(p_outbox_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_requeue_failed_media_v1(p_outbox_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_outbox public.whatsapp_outbox_v1%rowtype;
begin
  if p_outbox_id is null then
    return jsonb_build_object('ok',false,'error','outbox_required');
  end if;

  select o.* into v_outbox
  from public.whatsapp_outbox_v1 o
  where o.id=p_outbox_id
  for update;

  if not found then
    return jsonb_build_object('ok',false,'error','outbox_not_found');
  end if;
  if v_outbox.purpose<>'human_attendance'
     or v_outbox.provider<>'meta'
     or v_outbox.message_type not in ('image','audio','document') then
    return jsonb_build_object('ok',false,'error','outbox_not_retryable_media');
  end if;
  if v_outbox.status='queued' then
    return jsonb_build_object('ok',true,'already_queued',true,'outbox_id',v_outbox.id,'status','queued');
  end if;
  if v_outbox.status<>'failed' then
    return jsonb_build_object('ok',false,'error','media_retry_not_safe','status',v_outbox.status);
  end if;

  update public.whatsapp_outbox_v1
  set status='queued',
      claimed_at=null,
      available_at=now(),
      last_error=null,
      updated_at=now()
  where id=v_outbox.id
    and status='failed';

  if not found then
    return jsonb_build_object('ok',false,'error','media_retry_race');
  end if;

  return jsonb_build_object('ok',true,'already_queued',false,'outbox_id',v_outbox.id,'status','queued');
end;
$function$
;

-- function: ops2_admin_attendance_resume_ai_v1(p_conversation_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_resume_ai_v1(p_conversation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_user uuid:=auth.uid(); v_conversation public.conversations%rowtype; v_before text;
begin
  if p_conversation_id is null then return jsonb_build_object('ok',false,'error','conversation_required'); end if;
  if v_user is null or not exists (select 1 from public.admin_users a where a.user_id=v_user and a.is_active=true) then return jsonb_build_object('ok',false,'error','admin_not_authorized'); end if;
  select c.* into v_conversation from public.conversations c where c.id=p_conversation_id for update;
  if not found then return jsonb_build_object('ok',false,'error','conversation_not_found'); end if;
  v_before:=v_conversation.mode;
  update public.conversations set mode='ai',human_required=false,ai_resume_at=now(),assigned_admin_user_id=null,updated_at=now() where id=p_conversation_id returning * into v_conversation;
  if v_before is distinct from 'ai' then insert into public.attendance_human_ai_audit_v1(conversation_id,action,admin_user_id,from_mode,to_mode,source) values (p_conversation_id,'resume_ai',v_user,v_before,'ai','admin'); end if;
  return jsonb_build_object('ok',true,'conversation_id',v_conversation.id,'mode',v_conversation.mode,'human_takeover_at',v_conversation.human_takeover_at,'ai_resume_at',v_conversation.ai_resume_at,'assigned_admin_user_id',v_conversation.assigned_admin_user_id,'human_required',v_conversation.human_required);
end;$function$
;

-- function: ops2_admin_attendance_set_labels_v1(p_conversation_id uuid, p_label_ids uuid[])
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_set_labels_v1(p_conversation_id uuid, p_label_ids uuid[] DEFAULT '{}'::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_ids uuid[]:=coalesce(p_label_ids,'{}'::uuid[]);
  v_old_manual_ids uuid[]:='{}'::uuid[];
  v_distinct integer;
  v_valid integer;
  v_labels jsonb;
begin
  if p_conversation_id is null or not exists(select 1 from public.conversations c where c.id=p_conversation_id) then
    return jsonb_build_object('ok',false,'error','conversation_not_found');
  end if;
  if coalesce(array_length(v_ids,1),0)>20 then
    return jsonb_build_object('ok',false,'error','too_many_labels');
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_conversation_id::text,6801));

  select count(distinct x)::integer into v_distinct from unnest(v_ids) x;
  select count(*)::integer into v_valid
  from public.attendance_labels_v1 l
  where l.id=any(v_ids) and l.is_active=true;
  if coalesce(v_distinct,0)<>coalesce(v_valid,0) then
    return jsonb_build_object('ok',false,'error','invalid_or_inactive_label');
  end if;

  select coalesce(array_agg(label_id),'{}'::uuid[]) into v_old_manual_ids
  from public.attendance_conversation_manual_labels_v1
  where conversation_id=p_conversation_id;

  delete from public.attendance_conversation_manual_labels_v1
  where conversation_id=p_conversation_id;
  insert into public.attendance_conversation_manual_labels_v1(conversation_id,label_id)
  select p_conversation_id,x
  from (select distinct unnest(v_ids) as x) selected
  where x is not null
    and (
      not exists (
        select 1 from public.attendance_conversation_auto_labels_v1 automatic_label
        where automatic_label.conversation_id=p_conversation_id
          and automatic_label.label_id=x
      )
      or x=any(v_old_manual_ids)
    )
  on conflict (conversation_id,label_id) do nothing;

  delete from public.attendance_conversation_labels_v1 current_label
  where current_label.conversation_id=p_conversation_id
    and not exists (
      select 1 from public.attendance_conversation_manual_labels_v1 manual_label
      where manual_label.conversation_id=current_label.conversation_id
        and manual_label.label_id=current_label.label_id
    )
    and not exists (
      select 1 from public.attendance_conversation_auto_labels_v1 automatic_label
      where automatic_label.conversation_id=current_label.conversation_id
        and automatic_label.label_id=current_label.label_id
    );

  insert into public.attendance_conversation_labels_v1(conversation_id,label_id)
  select p_conversation_id,owned.label_id
  from (
    select label_id from public.attendance_conversation_manual_labels_v1 where conversation_id=p_conversation_id
    union
    select label_id from public.attendance_conversation_auto_labels_v1 where conversation_id=p_conversation_id
  ) owned
  on conflict (conversation_id,label_id) do nothing;

  select coalesce(jsonb_agg(jsonb_build_object('id',l.id,'name',l.name,'color',l.color,'sort_order',l.sort_order) order by l.sort_order,l.name),'[]'::jsonb)
  into v_labels
  from public.attendance_conversation_labels_v1 cl
  join public.attendance_labels_v1 l on l.id=cl.label_id
  where cl.conversation_id=p_conversation_id and l.is_active=true;

  return jsonb_build_object('ok',true,'conversation_id',p_conversation_id,'labels',v_labels);
end;
$function$
;

-- function: ops2_admin_attendance_takeover_v1(p_conversation_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_takeover_v1(p_conversation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_user uuid:=auth.uid(); v_conversation public.conversations%rowtype; v_before text;
begin
  if p_conversation_id is null then return jsonb_build_object('ok',false,'error','conversation_required'); end if;
  if v_user is null or not exists (select 1 from public.admin_users a where a.user_id=v_user and a.is_active=true) then return jsonb_build_object('ok',false,'error','admin_not_authorized'); end if;
  select c.* into v_conversation from public.conversations c where c.id=p_conversation_id for update;
  if not found then return jsonb_build_object('ok',false,'error','conversation_not_found'); end if;
  if v_conversation.mode='human' and v_conversation.assigned_admin_user_id is not null and v_conversation.assigned_admin_user_id<>v_user then return jsonb_build_object('ok',false,'error','conversation_owned_by_other_admin'); end if;
  v_before:=v_conversation.mode;
  update public.conversations set mode='human',human_required=true,human_takeover_at=case when mode='human' then coalesce(human_takeover_at,now()) else now() end,ai_resume_at=null,assigned_admin_user_id=v_user,updated_at=now() where id=p_conversation_id returning * into v_conversation;
  if v_before is distinct from 'human' then insert into public.attendance_human_ai_audit_v1(conversation_id,action,admin_user_id,from_mode,to_mode,source) values (p_conversation_id,'takeover',v_user,v_before,'human','admin'); end if;
  return jsonb_build_object('ok',true,'conversation_id',v_conversation.id,'mode',v_conversation.mode,'human_takeover_at',v_conversation.human_takeover_at,'ai_resume_at',v_conversation.ai_resume_at,'assigned_admin_user_id',v_conversation.assigned_admin_user_id,'human_required',v_conversation.human_required);
end;$function$
;

