 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  update public.marketing_weekly_consent_requests_v1 set status='send_failed',updated_at=now() where id=p_request_id and decision is null;
  if not found then return jsonb_build_object('ok',false,'error','weekly_consent_request_not_found'); end if;
  return jsonb_build_object('ok',true,'request_id',p_request_id,'status','send_failed');
end;
$function$
;

-- function: ops2_admin_attendance_weekly_consent_mark_sent_browser_v1(p_request_id uuid, p_outbox_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_weekly_consent_mark_sent_browser_v1(p_request_id uuid, p_outbox_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_access jsonb:=public.ops2_admin_attendance_customer_access_v1(true);
  v_request public.marketing_weekly_consent_requests_v1%rowtype;
  v_outbox public.whatsapp_outbox_v1%rowtype;
begin
  if coalesce((v_access->>'ok')::boolean,false) is not true then return v_access; end if;
  if p_request_id is null or p_outbox_id is null then return jsonb_build_object('ok',false,'error','invalid_consent_send_reference'); end if;

  select * into v_request from public.marketing_weekly_consent_requests_v1 where id=p_request_id limit 1;
  if not found then return jsonb_build_object('ok',false,'error','weekly_consent_request_not_found'); end if;

  select * into v_outbox from public.whatsapp_outbox_v1 where id=p_outbox_id limit 1;
  if not found then return jsonb_build_object('ok',false,'error','weekly_consent_outbox_not_found'); end if;
  if v_outbox.conversation_id is distinct from v_request.conversation_id then return jsonb_build_object('ok',false,'error','weekly_consent_outbox_mismatch'); end if;
  if v_outbox.status<>'sent' then return jsonb_build_object('ok',false,'error','weekly_consent_outbox_not_sent'); end if;
  if coalesce(v_outbox.payload->>'text','') is distinct from v_request.consent_text_snapshot then
    return jsonb_build_object('ok',false,'error','weekly_consent_text_mismatch');
  end if;

  return public.ops2_admin_attendance_weekly_consent_mark_sent_v1(p_request_id,p_outbox_id,v_outbox.provider_message_id);
end;
$function$
;

-- function: ops2_admin_attendance_weekly_consent_mark_sent_v1(p_request_id uuid, p_outbox_id uuid, p_provider_message_id text)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_weekly_consent_mark_sent_v1(p_request_id uuid, p_outbox_id uuid, p_provider_message_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  update public.marketing_weekly_consent_requests_v1
     set status='sent',outbox_id=p_outbox_id,provider_message_id=nullif(btrim(coalesce(p_provider_message_id,'')),''),asked_at=coalesce(asked_at,now()),updated_at=now()
   where id=p_request_id and decision is null;
  if not found then return jsonb_build_object('ok',false,'error','weekly_consent_request_not_found'); end if;
  return jsonb_build_object('ok',true,'request_id',p_request_id,'status','sent');
end;
$function$
;

-- function: ops2_admin_attendance_weekly_consent_prepare_browser_v1(p_conversation_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_weekly_consent_prepare_browser_v1(p_conversation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_access jsonb:=public.ops2_admin_attendance_customer_access_v1(true);
begin
  if coalesce((v_access->>'ok')::boolean,false) is not true then return v_access; end if;
  return public.ops2_admin_attendance_weekly_consent_prepare_v1(p_conversation_id);
end;
$function$
;

-- function: ops2_admin_attendance_weekly_consent_prepare_v1(p_conversation_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_weekly_consent_prepare_v1(p_conversation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_conversation public.conversations%rowtype;
  v_request public.marketing_weekly_consent_requests_v1%rowtype;
  v_existing_event uuid;
  v_prompt constant text:='Quer receber ofertas e cupons da Dona Antônia pelo WhatsApp? Enviamos no máximo 1 vez por semana. Você pode cancelar quando quiser.';
  v_phone text;
begin
  if p_conversation_id is null then return jsonb_build_object('ok',false,'error','invalid_conversation_id'); end if;
  perform pg_advisory_xact_lock(hashtextextended('weekly-consent:'||p_conversation_id::text,0));

  select * into v_conversation
  from public.conversations
  where id=p_conversation_id
  for update;

  if not found then return jsonb_build_object('ok',false,'error','conversation_not_found'); end if;
  if v_conversation.customer_id is null then return jsonb_build_object('ok',false,'error','customer_not_linked'); end if;
  if v_conversation.last_inbound_at is null or now()>=v_conversation.last_inbound_at+interval '24 hours' then
    return jsonb_build_object('ok',false,'error','service_window_closed');
  end if;

  select e.id into v_existing_event
  from public.marketing_consent_events_v1 e
  where e.customer_id=v_conversation.customer_id
    and coalesce(e.metadata->>'scope','')='weekly_offers_coupons'
  order by e.occurred_at desc,e.created_at desc
  limit 1;

  if v_existing_event is not null then
    return jsonb_build_object('ok',false,'error','weekly_consent_already_decided');
  end if;

  select * into v_request
  from public.marketing_weekly_consent_requests_v1
  where customer_id=v_conversation.customer_id
    and consent_scope='weekly_offers_coupons'
  for update;

  if found and v_request.status='sent' then
    return jsonb_build_object('ok',false,'error','weekly_consent_already_requested','request_id',v_request.id);
  end if;

  v_phone:=public.canonical_whatsapp_e164_br_v2(v_conversation.wa_contact_e164);
  if v_phone is null then return jsonb_build_object('ok',false,'error','invalid_phone'); end if;

  if found and v_request.status='prepared' then
    update public.marketing_weekly_consent_requests_v1
       set conversation_id=p_conversation_id,
           phone_e164=v_phone,
           consent_text_snapshot=v_prompt,
           updated_at=now()
     where id=v_request.id
     returning * into v_request;
  elsif found and v_request.status='send_failed' then
    update public.marketing_weekly_consent_requests_v1
       set conversation_id=p_conversation_id,
           phone_e164=v_phone,
           consent_text_snapshot=v_prompt,
           status='prepared',
           attempt_count=attempt_count+1,
           outbox_id=null,
           provider_message_id=null,
           updated_at=now()
     where id=v_request.id
     returning * into v_request;
  elsif found then
    return jsonb_build_object('ok',false,'error','weekly_consent_request_state_invalid','request_id',v_request.id,'status',v_request.status);
  else
    insert into public.marketing_weekly_consent_requests_v1(
      customer_id,conversation_id,phone_e164,consent_text_snapshot
    ) values(
      v_conversation.customer_id,p_conversation_id,v_phone,v_prompt
    ) returning * into v_request;
  end if;

  return jsonb_build_object(
    'ok',true,
    'request_id',v_request.id,
    'attempt_count',v_request.attempt_count,
    'prompt',v_prompt,
    'consent_text_version',v_request.consent_text_version,
    'scope',v_request.consent_scope
  );
end;
$function$
;

-- function: ops2_admin_attendance_weekly_consent_state_browser_v1(p_conversation_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_weekly_consent_state_browser_v1(p_conversation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_access jsonb:=public.ops2_admin_attendance_customer_access_v1(false);
begin
  if coalesce((v_access->>'ok')::boolean,false) is not true then return v_access; end if;
  return public.ops2_admin_attendance_weekly_consent_state_v1(p_conversation_id);
end;
$function$
;

-- function: ops2_admin_attendance_weekly_consent_state_v1(p_conversation_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_admin_attendance_weekly_consent_state_v1(p_conversation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_conversation public.conversations%rowtype;
  v_request public.marketing_weekly_consent_requests_v1%rowtype;
  v_event public.marketing_consent_events_v1%rowtype;
  v_window_open boolean:=false;
  v_state text:='never_asked';
begin
  if p_conversation_id is null then return jsonb_build_object('ok',false,'error','invalid_conversation_id'); end if;
  select * into v_conversation from public.conversations where id=p_conversation_id limit 1;
  if not found then return jsonb_build_object('ok',false,'error','conversation_not_found'); end if;
  v_window_open:=v_conversation.last_inbound_at is not null and now()<v_conversation.last_inbound_at+interval '24 hours';
  if v_conversation.customer_id is null then
    return jsonb_build_object('ok',true,'conversation_id',p_conversation_id,'customer_linked',false,'consent_state','unlinked','can_ask',false,'service_window_open',v_window_open);
  end if;

  select e.* into v_event
  from public.marketing_consent_events_v1 e
  where e.customer_id=v_conversation.customer_id
    and coalesce(e.metadata->>'scope','')='weekly_offers_coupons'
  order by e.occurred_at desc,e.created_at desc,e.id desc
  limit 1;

  select r.* into v_request
  from public.marketing_weekly_consent_requests_v1 r
  where r.customer_id=v_conversation.customer_id and r.consent_scope='weekly_offers_coupons'
  order by r.created_at desc
  limit 1;

  if v_event.id is not null then v_state:=v_event.decision;
  elsif v_request.id is not null and v_request.status='sent' then v_state:='pending';
  elsif v_request.id is not null then v_state:=v_request.status;
  end if;

  return jsonb_build_object(
    'ok',true,'conversation_id',p_conversation_id,'customer_linked',true,
    'customer_id',v_conversation.customer_id,'consent_state',v_state,
    'service_window_open',v_window_open,
    'can_ask',v_window_open and v_event.id is null and (v_request.id is null or v_request.status in ('prepared','send_failed')),
    'request_id',v_request.id,'asked_at',v_request.asked_at,'responded_at',coalesce(v_event.occurred_at,v_request.responded_at),
    'consent_text_version',coalesce(v_event.consent_text_version,v_request.consent_text_version),
    'latest_event_id',v_event.id,'latest_source',v_event.source
  );
end;
$function$
;

-- function: ops2_admin_cancel_site_order_v1(p_order_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_admin_cancel_site_order_v1(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_order public.orders%ROWTYPE;
  v_now timestamptz := now();
BEGIN
  IF p_order_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_order_id');
  END IF;

  SELECT * INTO v_order
  FROM public.orders
  WHERE id = p_order_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'order_not_found');
  END IF;

  IF v_order.status = 'cancelled' THEN
    RETURN jsonb_build_object('ok', true, 'status', 'already_cancelled', 'order_id', p_order_id);
  END IF;

  IF v_order.status NOT IN ('storefront_received', 'received', 'confirmed', 'processing')
     OR v_order.bling_order_id IS NOT NULL
     OR v_order.sync_status <> 'local'
     OR EXISTS (
       SELECT 1 FROM public.order_separation_completions_v1
       WHERE order_id = p_order_id
     ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'order_cancel_not_allowed', 'status', v_order.status);
  END IF;

  UPDATE public.vitrine_stock_reservations
  SET status = 'released', released_at = v_now, consumed_at = NULL, updated_at = v_now
  WHERE order_id = p_order_id AND status = 'reserved';

  UPDATE public.orders
  SET status = 'cancelled', cancelled_at = v_now, updated_at = v_now
  WHERE id = p_order_id;

  RETURN jsonb_build_object('ok', true, 'status', 'cancelled', 'order_id', p_order_id);
END;
$function$
;

-- function: ops2_admin_customer_delete_v1(p_customer_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_admin_customer_delete_v1(p_customer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_orders integer:=0;
  v_carts integer:=0;
  v_conversations integer:=0;
begin
  if p_customer_id is null or not exists(select 1 from public.customers where id=p_customer_id) then
    return jsonb_build_object('ok',false,'error','customer_not_found');
  end if;

  update public.orders set customer_id=null,updated_at=now() where customer_id=p_customer_id;
  get diagnostics v_orders=row_count;
  update public.carts set customer_id=null,updated_at=now() where customer_id=p_customer_id;
  get diagnostics v_carts=row_count;
  update public.conversations set customer_id=null,updated_at=now() where customer_id=p_customer_id;
  get diagnostics v_conversations=row_count;

  delete from public.customers where id=p_customer_id;

  return jsonb_build_object(
    'ok',true,'deleted',true,
    'preserved_history',jsonb_build_object('orders',v_orders,'carts',v_carts,'conversations',v_conversations)
  );
end;
$function$
;

-- function: ops2_admin_customer_save_v2(p_payload jsonb)
CREATE OR REPLACE FUNCTION public.ops2_admin_customer_save_v2(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid;
  v_name text:=nullif(left(btrim(regexp_replace(coalesce(p_payload->>'display_name',''),'\s+',' ','g')),180),'');
  v_phone_input text:=nullif(btrim(coalesce(p_payload->>'phone','')),'');
  v_phone text;
  v_cpf text:=nullif(left(regexp_replace(coalesce(p_payload->>'cpf',''),'[^0-9]','','g'),14),'');
  v_email text:=nullif(lower(left(btrim(coalesce(p_payload->>'email','')),180)),'');
  v_day integer;
  v_month integer;
  v_active boolean:=coalesce(p_payload->>'status','active') not in ('inactive','blocked');
  v_address jsonb:=coalesce(p_payload->'address','{}'::jsonb);
  v_has_address boolean;
  v_other uuid;
  v_phone_row uuid;
  v_same_phone_row uuid;
  v_email_row uuid;
  v_address_id uuid;
begin
  if v_name is null then return jsonb_build_object('ok',false,'error','name_required'); end if;
  if nullif(p_payload->>'id','') is not null then
    begin v_id:=(p_payload->>'id')::uuid; exception when invalid_text_representation then return jsonb_build_object('ok',false,'error','invalid_customer'); end;
    if not exists(select 1 from public.customers where id=v_id) then return jsonb_build_object('ok',false,'error','customer_not_found'); end if;
  end if;

  if v_phone_input is not null then
    v_phone:=public.canonical_whatsapp_e164_br_v2(v_phone_input);
    if v_phone is null then return jsonb_build_object('ok',false,'error','invalid_phone'); end if;
  end if;

  begin v_day:=nullif(p_payload->>'birthday_day','')::integer; exception when invalid_text_representation then v_day:=null; end;
  begin v_month:=nullif(p_payload->>'birthday_month','')::integer; exception when invalid_text_representation then v_month:=null; end;
  if v_day is not null and (v_day<1 or v_day>31) then v_day:=null; end if;
  if v_month is not null and (v_month<1 or v_month>12) then v_month:=null; end if;

  if v_phone is not null then
    select x.customer_id into v_other
      from public.customer_ids_by_phone_variants_v1(v_phone) x
     where v_id is null or x.customer_id<>v_id
     limit 1;
    if v_other is not null then return jsonb_build_object('ok',false,'error','phone_already_in_use'); end if;
  end if;

  if v_cpf is not null then
    select c.id into v_other from public.customers c
     where (v_id is null or c.id<>v_id)
       and regexp_replace(coalesce(c.cpf_cnpj,''),'[^0-9]','','g')=v_cpf
     limit 1;
    if v_other is not null then return jsonb_build_object('ok',false,'error','cpf_already_in_use'); end if;
  end if;

  if v_id is null then
    insert into public.customers(name,cpf_cnpj,primary_whatsapp_e164,is_active,birthday_day,birthday_month,created_at,updated_at)
    values(v_name,v_cpf,v_phone,v_active,v_day,v_month,now(),now()) returning id into v_id;
  else
    update public.customers set
      name=v_name,cpf_cnpj=v_cpf,primary_whatsapp_e164=v_phone,is_active=v_active,
      birthday_day=v_day,birthday_month=v_month,updated_at=now()
    where id=v_id;
  end if;

  select cp.id into v_phone_row from public.customer_phones cp
   where cp.customer_id=v_id and cp.is_primary=true order by cp.created_at desc limit 1 for update;

  if v_phone is not null then
    select cp.id into v_same_phone_row from public.customer_phones cp
     where cp.customer_id=v_id and public.normalize_phone_digits(cp.phone_e164)=public.normalize_phone_digits(v_phone)
     order by cp.created_at desc limit 1;
    update public.customer_phones set is_primary=false where customer_id=v_id and is_primary=true;
    if v_same_phone_row is not null then
      update public.customer_phones set phone_e164=v_phone,is_primary=true,source='vitrine_admin' where id=v_same_phone_row;
    elsif v_phone_row is not null then
      update public.customer_phones set phone_e164=v_phone,is_primary=true,source='vitrine_admin' where id=v_phone_row;
    else
      insert into public.customer_phones(customer_id,phone_e164,source,is_primary) values(v_id,v_phone,'vitrine_admin',true);
    end if;
  else
    update public.customer_phones set is_primary=false where customer_id=v_id and is_primary=true;
  end if;

  select ce.id into v_email_row from public.customer_emails ce
   where ce.customer_id=v_id order by ce.is_primary desc,ce.created_at desc limit 1 for update;
  update public.customer_emails set is_primary=false,updated_at=now() where customer_id=v_id and is_primary=true;
  if v_email is not null then
    if v_email_row is not null then
      update public.customer_emails set email=v_email,is_primary=true,source='vitrine_admin',updated_at=now() where id=v_email_row;
    else
      insert into public.customer_emails(customer_id,email,is_primary,source,updated_at)
      values(v_id,v_email,true,'vitrine_admin',now());
    end if;
  end if;

  v_has_address:=coalesce(nullif(btrim(v_address->>'postal_code'),''),nullif(btrim(v_address->>'street'),''),nullif(btrim(v_address->>'number'),''),nullif(btrim(v_address->>'district'),''),nullif(btrim(v_address->>'complement'),''),nullif(btrim(v_address->>'city'),''),nullif(btrim(v_address->>'state'),''),nullif(btrim(v_address->>'raw_text'),'')) is not null;
  select ca.id into v_address_id from public.customer_addresses ca
   where ca.customer_id=v_id and ca.is_default=true and ca.is_active=true order by ca.updated_at desc limit 1 for update;

  if v_address_id is not null then
    update public.customer_addresses set
      street=nullif(left(btrim(coalesce(v_address->>'street','')),180),''),
      number=nullif(left(btrim(coalesce(v_address->>'number','')),40),''),
      complement=nullif(left(btrim(coalesce(v_address->>'complement','')),140),''),
      neighborhood=nullif(left(btrim(coalesce(v_address->>'district','')),140),''),
      city=nullif(left(btrim(coalesce(v_address->>'city','')),120),''),
      state=nullif(upper(left(btrim(coalesce(v_address->>'state','')),2)),''),
      postal_code=nullif(left(regexp_replace(coalesce(v_address->>'postal_code',''),'[^0-9]','','g'),8),''),
      reference=nullif(left(btrim(coalesce(v_address->>'raw_text','')),400),''),
      is_default=v_has_address,is_active=v_has_address,updated_at=now()
    where id=v_address_id;
  elsif v_has_address then
    insert into public.customer_addresses(customer_id,label,street,number,complement,neighborhood,city,state,postal_code,reference,is_default,is_active,created_at,updated_at)
    values(v_id,'Entrega',nullif(left(btrim(coalesce(v_address->>'street','')),180),''),nullif(left(btrim(coalesce(v_address->>'number','')),40),''),nullif(left(btrim(coalesce(v_address->>'complement','')),140),''),nullif(left(btrim(coalesce(v_address->>'district','')),140),''),nullif(left(btrim(coalesce(v_address->>'city','')),120),''),nullif(upper(left(btrim(coalesce(v_address->>'state','')),2)),''),nullif(left(regexp_replace(coalesce(v_address->>'postal_code',''),'[^0-9]','','g'),8),''),nullif(left(btrim(coalesce(v_address->>'raw_text','')),400),''),true,true,now(),now());
  end if;

  insert into public.customer_identity_profiles_v1(customer_id,identity_status,created_from,canonical_phone_e164,last_source_key,metadata,updated_at)
  values(v_id,'verified_existing','vitrine_admin',v_phone,'vitrine_admin','{}'::jsonb,now())
  on conflict(customer_id) do update set canonical_phone_e164=excluded.canonical_phone_e164,last_source_key='vitrine_admin',updated_at=now();

  return jsonb_build_object('ok',true,'customer_id',v_id);
exception when unique_violation then
  return jsonb_build_object('ok',false,'error','duplicate_customer_identity');
end;
$function$
;

-- function: ops2_admin_set_order_separation_item_v1(p_order_id uuid, p_order_item_id uuid, p_state text, p_expected_order_updated_at timestamp with time zone, p_separator_key text, p_replacement_product_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_admin_set_order_separation_item_v1(p_order_id uuid, p_order_item_id uuid, p_state text, p_expected_order_updated_at timestamp with time zone, p_separator_key text, p_replacement_product_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_order public.orders%ROWTYPE;
  v_item public.order_items%ROWTYPE;
  v_separation public.order_separation_items_v1%ROWTYPE;
  v_replacement public.products%ROWTYPE;
  v_original_reservation public.vitrine_stock_reservations%ROWTYPE;
  v_replacement_reservation public.vitrine_stock_reservations%ROWTYPE;
  v_state text := lower(trim(coalesce(p_state, '')));
  v_separator text := nullif(lower(trim(coalesce(p_separator_key, ''))), '');
  v_reserved numeric := 0;
  v_available numeric := 0;
  v_now timestamptz := now();
  v_result jsonb;
BEGIN
  IF p_order_id IS NULL OR p_order_item_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_order_item');
  END IF;

  IF v_state NOT IN ('separated', 'missing', 'substituted') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_separation_state');
  END IF;

  IF v_separator = 'claudenil' THEN v_separator := 'claudio'; END IF;
  IF v_separator IS NULL OR v_separator NOT IN ('jose', 'claudio', 'kelly', 'jovenil') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_separator');
  END IF;

  SELECT * INTO v_order
  FROM public.orders
  WHERE id = p_order_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'order_not_found');
  END IF;

  IF v_order.status NOT IN ('confirmed', 'processing') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'order_not_in_separation', 'status', v_order.status);
  END IF;

  IF p_expected_order_updated_at IS NULL OR v_order.updated_at IS DISTINCT FROM p_expected_order_updated_at THEN
    RETURN jsonb_build_object('ok', false, 'error', 'stale_order_version', 'order_updated_at', v_order.updated_at);
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.order_separation_completions_v1
    WHERE order_id = p_order_id
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'separation_already_completed');
  END IF;

  SELECT * INTO v_item
  FROM public.order_items
  WHERE id = p_order_item_id AND order_id = p_order_id AND quantity > 0
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'order_item_not_found');
  END IF;

  SELECT * INTO v_separation
  FROM public.order_separation_items_v1
  WHERE order_id = p_order_id AND order_item_id = p_order_item_id
  FOR UPDATE;

  IF FOUND AND v_separation.state <> 'pending' THEN
    IF v_state = 'substituted'
       AND v_separation.state = 'separated'
       AND v_item.metadata ? 'separation_substitution'
       AND v_item.metadata->'separation_substitution'->>'replacement_product_id' = p_replacement_product_id::text THEN
      RETURN jsonb_build_object('ok', true, 'status', 'already_applied', 'state', 'substituted',
        'order_item_id', p_order_item_id, 'order_updated_at', v_order.updated_at);
    END IF;
    RETURN jsonb_build_object('ok', false, 'error', 'item_already_checked');
  END IF;

  IF v_state = 'substituted' THEN
    IF p_replacement_product_id IS NULL OR v_item.product_id IS NULL
       OR p_replacement_product_id = v_item.product_id THEN
      RETURN jsonb_build_object('ok', false, 'error', 'replacement_product_invalid');
    END IF;

    SELECT * INTO v_replacement
    FROM public.products
    WHERE id = p_replacement_product_id
    FOR UPDATE;
    IF NOT FOUND OR v_replacement.is_active IS DISTINCT FROM true
       OR v_replacement.stock IS NULL OR v_replacement.stock <= 0 THEN
      RETURN jsonb_build_object('ok', false, 'error', 'replacement_product_unavailable');
    END IF;

    SELECT coalesce(sum(r.quantity), 0)
    INTO v_reserved
    FROM public.vitrine_stock_reservations r
    JOIN public.orders o ON o.id = r.order_id
    WHERE r.product_id = p_replacement_product_id
      AND r.status = 'reserved'
      AND o.status NOT IN ('cancelled', 'returned', 'delivered');

    v_available := greatest(0, v_replacement.stock - v_reserved);
    IF v_available < v_item.quantity THEN
      RETURN jsonb_build_object('ok', false, 'error', 'insufficient_replacement_stock',
        'available_stock', v_available, 'requested_quantity', v_item.quantity);
    END IF;

    SELECT * INTO v_replacement_reservation
    FROM public.vitrine_stock_reservations
    WHERE order_id = p_order_id AND product_id = p_replacement_product_id
    FOR UPDATE;
    IF FOUND AND v_replacement_reservation.status = 'consumed' THEN
      RETURN jsonb_build_object('ok', false, 'error', 'replacement_stock_already_consumed');
    END IF;
  END IF;

  IF v_item.product_id IS NOT NULL THEN
    SELECT * INTO v_original_reservation
    FROM public.vitrine_stock_reservations
    WHERE order_id = p_order_id AND product_id = v_item.product_id
    FOR UPDATE;
    IF FOUND AND v_original_reservation.status = 'consumed' THEN
      RETURN jsonb_build_object('ok', false, 'error', 'replacement_stock_already_consumed');
    END IF;
  END IF;

  v_result := public.ops2_set_order_separation_item_v2(
    p_order_id,
    p_order_item_id,
    CASE WHEN v_state = 'substituted' THEN 'separated' ELSE v_state END,
    p_expected_order_updated_at,
    v_separator
  );
  IF coalesce((v_result->>'ok')::boolean, false) IS NOT TRUE THEN
    RETURN v_result;
  END IF;

  IF v_state IN ('missing', 'substituted') AND v_item.product_id IS NOT NULL THEN
    UPDATE public.products SET is_active = false WHERE id = v_item.product_id;

    IF v_original_reservation.status = 'reserved' THEN
      IF v_original_reservation.quantity > v_item.quantity THEN
        UPDATE public.vitrine_stock_reservations
        SET quantity = quantity - v_item.quantity, updated_at = v_now
        WHERE id = v_original_reservation.id;
      ELSE
        UPDATE public.vitrine_stock_reservations
        SET status = 'released', released_at = v_now, consumed_at = NULL, updated_at = v_now
        WHERE id = v_original_reservation.id;
      END IF;
    END IF;
  END IF;

  IF v_state = 'substituted' THEN
    INSERT INTO public.vitrine_stock_reservations (
      order_id, product_id, quantity, status, created_at, updated_at, expires_at
    )
    VALUES (
      p_order_id, p_replacement_product_id, v_item.quantity, 'reserved', v_now, v_now, v_now + interval '2 hours'
    )
    ON CONFLICT (order_id, product_id) DO UPDATE
    SET quantity = CASE
          WHEN public.vitrine_stock_reservations.status = 'reserved'
            THEN public.vitrine_stock_reservations.quantity + EXCLUDED.quantity
          ELSE EXCLUDED.quantity
        END,
        status = 'reserved',
        updated_at = EXCLUDED.updated_at,
        expires_at = greatest(public.vitrine_stock_reservations.expires_at, EXCLUDED.expires_at),
        consumed_at = NULL,
        released_at = NULL;

    UPDATE public.order_items
    SET product_id = v_replacement.id,
        sku_snapshot = v_replacement.sku,
        name_snapshot = v_replacement.name,
        metadata = coalesce(metadata, '{}'::jsonb)
          || jsonb_build_object(
            'image_url', coalesce(nullif(v_replacement.image_url, ''), metadata->>'image_url'),
            'separation_substitution', jsonb_build_object(
              'original_product_id', v_item.product_id,
              'original_name', v_item.name_snapshot,
              'original_sku', v_item.sku_snapshot,
              'original_image_url', v_item.metadata->>'image_url',
              'original_preassembled_units', v_item.metadata->>'preassembled_units',
              'replacement_product_id', v_replacement.id,
              'replacement_name', v_replacement.name,
              'replacement_sku', v_replacement.sku,
              'replacement_gtin', v_replacement.gtin,
              'replacement_image_url', v_replacement.image_url,
              'replaced_at', v_now,
              'separator_key', v_separator,
              'price_policy', 'original_order_price'
            )
          )
          || CASE
               WHEN coalesce(v_item.metadata->>'history_kind', '') = 'basket_component'
                 THEN jsonb_build_object('preassembled_units', 0)
               ELSE '{}'::jsonb
             END,
        updated_at = v_now
    WHERE id = p_order_item_id AND order_id = p_order_id;

    UPDATE public.order_separation_items_v1
    SET product_id = v_replacement.id, updated_at = v_now
    WHERE order_id = p_order_id AND order_item_id = p_order_item_id;
  END IF;

  RETURN v_result || jsonb_build_object(
    'state', v_state,
    'order_updated_at', v_now,
    'replacement_product_id', CASE WHEN v_state = 'substituted' THEN p_replacement_product_id ELSE NULL END
  );
END;
$function$
;

-- function: ops2_ana_accept_live_outbound_v1(p_outbox_id uuid, p_provider_message_id text, p_accepted_at timestamp with time zone)
CREATE OR REPLACE FUNCTION public.ops2_ana_accept_live_outbound_v1(p_outbox_id uuid, p_provider_message_id text, p_accepted_at timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_outbox public.whatsapp_outbox_v1%rowtype;
  v_message public.whatsapp_messages_v1%rowtype;
  v_message_id uuid;
  v_status jsonb;
begin
  if p_outbox_id is null or coalesce(p_provider_message_id,'') not like 'wamid.%' then return jsonb_build_object('ok',false,'error','live_outbound_invalid'); end if;
  select * into v_outbox from public.whatsapp_outbox_v1 where id=p_outbox_id for update;
  if not found or v_outbox.provider<>'meta' or v_outbox.purpose<>'ai_attendance' or v_outbox.message_type<>'text'
     or v_outbox.status<>'claimed' then return jsonb_build_object('ok',false,'error','live_outbox_not_claimed'); end if;
  select * into v_message from public.whatsapp_messages_v1 where whatsapp_account_id=v_outbox.whatsapp_account_id
    and provider_message_id=p_provider_message_id limit 1 for update;
  if found then
    if v_message.conversation_id is distinct from v_outbox.conversation_id or v_message.direction<>'outbound' then
      return jsonb_build_object('ok',false,'error','live_wamid_conflict');
    end if;
    update public.whatsapp_messages_v1 set provider='meta',text_body=coalesce(text_body,nullif(v_outbox.payload->>'text','')),
      status_current=case when status_current in ('sent','delivered','read','failed','cancelled') then status_current else 'accepted' end,
      sender_kind='ana_ai',sender_ref='ana',sent_at=coalesce(sent_at,p_accepted_at,now()),
      metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('source','ana','transport','meta_cloud_api',
        'outbox_id',v_outbox.id,'idempotency_key',v_outbox.idempotency_key,'promoted_from_shadow',v_message.provider='papoai')
      where id=v_message.id returning * into v_message;
    v_message_id:=v_message.id;
  else
    insert into public.whatsapp_messages_v1(conversation_id,whatsapp_account_id,customer_id,direction,message_type,provider,
      provider_message_id,text_body,status_current,sender_kind,sender_ref,sent_at,metadata)
    values(v_outbox.conversation_id,v_outbox.whatsapp_account_id,v_outbox.customer_id,'outbound','text','meta',
      p_provider_message_id,nullif(v_outbox.payload->>'text',''),'accepted','ana_ai','ana',coalesce(p_accepted_at,now()),
      jsonb_build_object('source','ana','transport','meta_cloud_api','outbox_id',v_outbox.id,'idempotency_key',v_outbox.idempotency_key))
    returning id into v_message_id;
  end if;
  update public.whatsapp_outbox_v1 set message_id=v_message_id,provider_message_id=p_provider_message_id,status='sent',
    sent_at=coalesce(p_accepted_at,now()),last_error=null,updated_at=now() where id=v_outbox.id;
  update public.conversations set last_outbound_at=greatest(coalesce(last_outbound_at,'-infinity'::timestamptz),coalesce(p_accepted_at,now())),
    updated_at=greatest(updated_at,coalesce(p_accepted_at,now())) where id=v_outbox.conversation_id;
  v_status:=public.whatsapp_record_status_v1(v_outbox.whatsapp_account_id,'meta',p_provider_message_id,'accepted',
    coalesce(p_accepted_at,now()),now(),null,null,null,jsonb_build_object('source','ana_send','outbox_id',v_outbox.id));
  if coalesce((v_status->>'ok')::boolean,false) is not true then raise exception 'ana_status_record_failed'; end if;
  return jsonb_build_object('ok',true,'message_id',v_message_id,'outbox_id',v_outbox.id,'status','sent');
end;
$function$
;

-- function: ops2_ana_active_config_v1()
CREATE OR REPLACE FUNCTION public.ops2_ana_active_config_v1()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
  SELECT jsonb_build_object('ok',true,'version',v.version,'version_id',v.id,'configuration',v.configuration)
  FROM private.whatsapp_ana_admin_runtime_v1 r JOIN private.whatsapp_ana_admin_versions_v1 v ON v.id=r.active_version_id
  WHERE r.singleton;
$function$
;

-- function: ops2_ana_admin_load_v1()
CREATE OR REPLACE FUNCTION public.ops2_ana_admin_load_v1()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
  SELECT jsonb_build_object(
    'ok', true,
    'draft', (SELECT jsonb_build_object('configuration', d.configuration, 'revision', d.revision, 'updated_at', d.updated_at)
              FROM private.whatsapp_ana_admin_draft_v1 d WHERE d.singleton),
    'active', (SELECT jsonb_build_object('id', v.id, 'version', v.version, 'configuration', v.configuration, 'created_at', v.created_at)
               FROM private.whatsapp_ana_admin_runtime_v1 r JOIN private.whatsapp_ana_admin_versions_v1 v ON v.id = r.active_version_id WHERE r.singleton),
    'versions', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', v.id, 'version', v.version, 'actor_id', v.actor_id, 'change_note', v.change_note, 'created_at', v.created_at) ORDER BY v.version DESC), '[]'::jsonb)
                 FROM (SELECT * FROM private.whatsapp_ana_admin_versions_v1 ORDER BY version DESC LIMIT 20) v),
    'test_runs', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'draft_revision', t.draft_revision, 'scenario_keys', t.scenario_keys, 'passed_count', t.passed_count, 'failed_count', t.failed_count, 'safe_reasons', t.safe_reasons, 'latency_ms', t.latency_ms, 'created_at', t.created_at) ORDER BY t.created_at DESC), '[]'::jsonb)
                  FROM (SELECT * FROM private.whatsapp_ana_admin_test_runs_v1 ORDER BY created_at DESC LIMIT 20) t),
    'events', (SELECT coalesce(jsonb_agg(jsonb_build_object('action', e.action, 'actor_id', e.actor_id, 'version_id', e.version_id, 'draft_revision', e.draft_revision, 'channel_key', e.channel_key, 'detail', e.detail, 'created_at', e.created_at) ORDER BY e.created_at DESC), '[]'::jsonb)
               FROM (SELECT * FROM private.whatsapp_ana_admin_events_v1 ORDER BY created_at DESC LIMIT 30) e)
  );
$function$
;

-- function: ops2_ana_admin_publish_v1(p_test_run_id uuid, p_note text, p_actor_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_ana_admin_publish_v1(p_test_run_id uuid, p_note text DEFAULT ''::text, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
declare
  d private.whatsapp_ana_admin_draft_v1%rowtype;
  t private.whatsapp_ana_admin_test_runs_v1%rowtype;
  required_keys text[] := array[]::text[];
  next_version integer;
  new_id bigint;
begin
  select * into d
  from private.whatsapp_ana_admin_draft_v1
  where singleton
  for update;

  select coalesce(array_agg(item->>'key' order by ord),array[]::text[])
    into required_keys
  from jsonb_array_elements(coalesce(d.configuration->'test_cases','[]'::jsonb))
       with ordinality as x(item,ord);

  select * into t
  from private.whatsapp_ana_admin_test_runs_v1
  where id=p_test_run_id;

  if not found
     or t.draft_revision<>d.revision
     or cardinality(required_keys)=0
     or t.failed_count<>0
     or t.passed_count<>cardinality(required_keys)
     or t.scenario_keys is distinct from required_keys then
    return jsonb_build_object('ok',false,'error','test_run_missing_stale_or_failed');
  end if;

  select coalesce(max(version),0)+1 into next_version
  from private.whatsapp_ana_admin_versions_v1;

  insert into private.whatsapp_ana_admin_versions_v1(version,configuration,actor_id,change_note)
    values(next_version,d.configuration,p_actor_id,left(coalesce(p_note,''),240))
    returning id into new_id;

  insert into private.whatsapp_ana_admin_runtime_v1(singleton,active_version_id,updated_at,updated_by)
    values(true,new_id,now(),p_actor_id)
    on conflict(singleton) do update
      set active_version_id=excluded.active_version_id,
          updated_at=excluded.updated_at,
          updated_by=excluded.updated_by;

  insert into private.whatsapp_ana_admin_events_v1(action,actor_id,version_id,draft_revision,detail)
    values('published',p_actor_id,new_id,d.revision,
      jsonb_build_object('version',next_version,'test_run_id',p_test_run_id,'note',left(coalesce(p_note,''),240)));

  return jsonb_build_object('ok',true,'version',next_version,'version_id',new_id,'draft_revision',d.revision);
end;
$function$
;

-- function: ops2_ana_admin_record_test_run_v1(p_draft_revision bigint, p_scenario_keys text[], p_passed_count integer, p_failed_count integer, p_safe_reasons jsonb, p_latency_ms integer, p_actor_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_ana_admin_record_test_run_v1(p_draft_revision bigint, p_scenario_keys text[], p_passed_count integer, p_failed_count integer, p_safe_reasons jsonb, p_latency_ms integer, p_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
declare
  run_id uuid;
  d private.whatsapp_ana_admin_draft_v1%rowtype;
  expected_keys text[];
  scenario_count integer;
begin
  select * into d
  from private.whatsapp_ana_admin_draft_v1
  where singleton;

  select coalesce(array_agg(item->>'key' order by ord),'{}'::text[])
  into expected_keys
  from jsonb_array_elements(coalesce(d.configuration->'test_cases','[]'::jsonb))
       with ordinality as suite(item,ord);

  scenario_count := coalesce(cardinality(p_scenario_keys),0);

  if d.revision is null or p_draft_revision is distinct from d.revision then
    return jsonb_build_object('ok',false,'error','test_run_revision_stale');
  end if;

  if coalesce(cardinality(expected_keys),0) < 1
     or coalesce(cardinality(expected_keys),0) > 20
     or p_scenario_keys is distinct from expected_keys
     or scenario_count <> cardinality(expected_keys)
     or p_passed_count is null
     or p_failed_count is null
     or p_passed_count < 0
     or p_failed_count < 0
     or p_passed_count + p_failed_count <> scenario_count
     or coalesce(p_latency_ms,0) < 0 then
    return jsonb_build_object('ok',false,'error','test_run_input_invalid');
  end if;

  if p_safe_reasons is null
     or jsonb_typeof(p_safe_reasons) <> 'array'
     or jsonb_array_length(p_safe_reasons) <> scenario_count then
    return jsonb_build_object('ok',false,'error','test_run_privacy_input_invalid');
  end if;

  if exists(
       select 1
       from jsonb_array_elements(p_safe_reasons) as items(value)
       where jsonb_typeof(items.value) <> 'string'
          or length(items.value#>>'{}') > 80
     )
     or exists(
       select 1
       from unnest(coalesce(p_scenario_keys,'{}'::text[])) k
       where k !~ '^[a-z0-9][a-z0-9_-]{0,39}$'
     )
     or (
       select count(*) <> count(distinct k)
       from unnest(coalesce(p_scenario_keys,'{}'::text[])) k
     ) then
    return jsonb_build_object('ok',false,'error','test_run_privacy_input_invalid');
  end if;

  insert into private.whatsapp_ana_admin_test_runs_v1(
    draft_revision,scenario_keys,passed_count,failed_count,safe_reasons,latency_ms,actor_id
  ) values(
    p_draft_revision,p_scenario_keys,p_passed_count,p_failed_count,p_safe_reasons,p_latency_ms,p_actor_id
  )
  returning id into run_id;

  return jsonb_build_object(
    'ok',true,
    'id',run_id,
    'draft_revision',p_draft_revision,
    'passed_count',p_passed_count,
    'failed_count',p_failed_count
  );
end;
$function$
;

-- function: ops2_ana_admin_rollback_v1(p_version_id bigint, p_note text, p_actor_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_ana_admin_rollback_v1(p_version_id bigint, p_note text DEFAULT ''::text, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
DECLARE target private.whatsapp_ana_admin_versions_v1%ROWTYPE;
BEGIN
  SELECT * INTO target FROM private.whatsapp_ana_admin_versions_v1 WHERE id=p_version_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'error','version_not_found'); END IF;
  INSERT INTO private.whatsapp_ana_admin_runtime_v1(singleton,active_version_id,updated_at,updated_by)
    VALUES(true,target.id,now(),p_actor_id)
    ON CONFLICT(singleton) DO UPDATE SET active_version_id=excluded.active_version_id,updated_at=excluded.updated_at,updated_by=excluded.updated_by;
  INSERT INTO private.whatsapp_ana_admin_events_v1(action,actor_id,version_id,detail)
    VALUES('rolled_back',p_actor_id,target.id,jsonb_build_object('version',target.version,'note',left(coalesce(p_note,''),240)));
  RETURN jsonb_build_object('ok',true,'version',target.version,'version_id',target.id);
END;
$function$
;

-- function: ops2_ana_admin_save_draft_v1(p_configuration jsonb, p_expected_revision bigint, p_note text, p_actor_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_ana_admin_save_draft_v1(p_configuration jsonb, p_expected_revision bigint, p_note text DEFAULT ''::text, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
DECLARE current_row private.whatsapp_ana_admin_draft_v1%ROWTYPE;
BEGIN
  IF jsonb_typeof(p_configuration) <> 'object' OR jsonb_typeof(p_configuration->'behavior') <> 'object'
     OR jsonb_typeof(p_configuration->'knowledge') <> 'array' OR jsonb_typeof(p_configuration->'triggers') <> 'array'
     OR jsonb_typeof(p_configuration->'test_cases') <> 'array' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'configuration_shape_invalid');
  END IF;
  SELECT * INTO current_row FROM private.whatsapp_ana_admin_draft_v1 WHERE singleton FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'draft_missing'); END IF;
  IF current_row.revision <> p_expected_revision THEN
    RETURN jsonb_build_object('ok', false, 'error', 'revision_conflict', 'revision', current_row.revision);
  END IF;
  UPDATE private.whatsapp_ana_admin_draft_v1 SET configuration = p_configuration, revision = revision + 1,
    updated_at = now(), updated_by = p_actor_id WHERE singleton RETURNING * INTO current_row;
  INSERT INTO private.whatsapp_ana_admin_events_v1(action, actor_id, draft_revision, detail)
    VALUES ('draft_saved', p_actor_id, current_row.revision, jsonb_build_object('note', left(coalesce(p_note,''),240)));
  RETURN jsonb_build_object('ok', true, 'revision', current_row.revision, 'updated_at', current_row.updated_at);
END;
$function$
;

-- function: ops2_ana_admin_set_channel_v1(p_whatsapp_account_id uuid, p_enabled boolean, p_actor_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_ana_admin_set_channel_v1(p_whatsapp_account_id uuid, p_enabled boolean, p_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
DECLARE changed_id uuid; channel_suffix text;
BEGIN
  IF p_enabled IS TRUE AND NOT EXISTS(
    SELECT 1 FROM public.whatsapp_channel_runtime_v1 r
    WHERE r.whatsapp_account_id=p_whatsapp_account_id AND r.capture_enabled IS TRUE
      AND r.send_enabled IS TRUE AND r.outbound_provider='meta' AND r.homologated_at IS NOT NULL
  ) THEN
    RETURN jsonb_build_object('ok',false,'error','channel_not_ready_for_ana');
  END IF;
  UPDATE public.whatsapp_channel_runtime_v1 SET ana_enabled = p_enabled, updated_at = now()
    WHERE whatsapp_account_id = p_whatsapp_account_id RETURNING whatsapp_account_id INTO changed_id;
  IF changed_id IS NULL THEN RETURN jsonb_build_object('ok',false,'error','channel_not_found'); END IF;
  SELECT right(regexp_replace(coalesce(a.phone_e164,''),'\\D','','g'),4) INTO channel_suffix
    FROM public.whatsapp_accounts a WHERE a.id = changed_id;
  INSERT INTO private.whatsapp_ana_admin_events_v1(action,actor_id,channel_key,detail)
    VALUES('channel_toggled',p_actor_id,channel_suffix,jsonb_build_object('ana_enabled',p_enabled));
  RETURN jsonb_build_object('ok',true,'channel_key',channel_suffix,'ana_enabled',p_enabled);
END;
$function$
;

-- function: ops2_ana_apply_trigger_label_v1(p_conversation_id uuid, p_label_id uuid, p_trigger_key text)
CREATE OR REPLACE FUNCTION public.ops2_ana_apply_trigger_label_v1(p_conversation_id uuid, p_label_id uuid, p_trigger_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE label_source uuid; inserted_count integer:=0;
BEGIN
  IF p_conversation_id IS NULL OR p_label_id IS NULL OR btrim(coalesce(p_trigger_key,''))='' OR char_length(p_trigger_key)>40 THEN
    RETURN jsonb_build_object('ok',false,'error','trigger_label_input_invalid');
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.conversations WHERE id=p_conversation_id) THEN
    RETURN jsonb_build_object('ok',false,'error','conversation_not_found');
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.attendance_labels_v1 WHERE id=p_label_id AND is_active=true) THEN
    RETURN jsonb_build_object('ok',false,'error','label_not_active');
  END IF;
  label_source:=md5('ana-trigger:'||p_trigger_key)::uuid;
  INSERT INTO public.attendance_conversation_auto_labels_v1(conversation_id,label_id,source_kind,source_ref)
    VALUES(p_conversation_id,p_label_id,'ana_trigger',label_source) ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS inserted_count=ROW_COUNT;
  INSERT INTO public.attendance_conversation_labels_v1(conversation_id,label_id)
    VALUES(p_conversation_id,p_label_id) ON CONFLICT DO NOTHING;
  RETURN jsonb_build_object('ok',true,'applied',inserted_count>0);
END;
$function$
;

-- function: ops2_ana_begin_live_send_v1(p_job_id uuid, p_text text)
CREATE OR REPLACE FUNCTION public.ops2_ana_begin_live_send_v1(p_job_id uuid, p_text text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_job public.whatsapp_ana_jobs_v1%rowtype;
  v_conversation public.conversations%rowtype;
  v_runtime public.whatsapp_channel_runtime_v1%rowtype;
  v_account public.whatsapp_accounts%rowtype;
  v_gate jsonb;
  v_key text;
  v_outbox public.whatsapp_outbox_v1%rowtype;
  v_text text:=btrim(coalesce(p_text,''));
  v_phone text;
begin
  if p_job_id is null or v_text='' or char_length(v_text)>1200 then return jsonb_build_object('ok',false,'error','live_reply_invalid'); end if;
  select * into v_job from public.whatsapp_ana_jobs_v1 where id=p_job_id for update;
  if not found or v_job.dry_run is not false or v_job.status<>'claimed' then return jsonb_build_object('ok',false,'error','live_job_not_claimed'); end if;
  v_gate:=public.ops2_attendance_ai_gate_v1(v_job.conversation_id);
  if coalesce((v_gate->>'allowed')::boolean,false) is not true then return jsonb_build_object('ok',false,'error','ai_gate_closed'); end if;
  select * into v_conversation from public.conversations where id=v_job.conversation_id for update;
  if not found or v_conversation.whatsapp_account_id is distinct from v_job.whatsapp_account_id
     or v_conversation.last_inbound_at is null or now()>=v_conversation.last_inbound_at+interval '24 hours' then
    return jsonb_build_object('ok',false,'error','service_window_or_conversation_invalid');
  end if;
  select * into v_runtime from public.whatsapp_channel_runtime_v1 where whatsapp_account_id=v_job.whatsapp_account_id;
  if not found or v_runtime.ana_enabled is not true or v_runtime.send_enabled is not true
     or v_runtime.outbound_provider is distinct from 'meta' or v_runtime.homologated_at is null then return jsonb_build_object('ok',false,'error','ana_channel_gate_closed'); end if;
  select * into v_account from public.whatsapp_accounts where id=v_job.whatsapp_account_id and is_active=true;
  v_phone:=public.canonical_whatsapp_e164_br_v2(v_conversation.wa_contact_e164);
  if not found or v_phone is null or v_account.phone_number_id is null then return jsonb_build_object('ok',false,'error','meta_account_unavailable'); end if;
  v_key:='ana-live:'||v_job.id::text;
  perform pg_advisory_xact_lock(hashtextextended(v_key,0));
  select * into v_outbox from public.whatsapp_outbox_v1 where idempotency_key=v_key;
  if found then return jsonb_build_object('ok',false,'error','live_send_already_started','outbox_id',v_outbox.id,'status',v_outbox.status); end if;
  insert into public.whatsapp_outbox_v1(idempotency_key,whatsapp_account_id,conversation_id,customer_id,to_phone_e164,
    purpose,message_type,payload,provider,status,metadata)
  values(v_key,v_job.whatsapp_account_id,v_job.conversation_id,v_conversation.customer_id,v_phone,
    'ai_attendance','text',jsonb_build_object('text',v_text),'meta','queued',
    jsonb_build_object('source','ana','job_id',v_job.id,'provider','meta')) returning * into v_outbox;
  update public.whatsapp_outbox_v1 set status='claimed',claimed_at=now(),attempt_count=attempt_count+1,updated_at=now()
    where id=v_outbox.id returning * into v_outbox;
  return jsonb_build_object('ok',true,'outbox_id',v_outbox.id,'phone_number_id',v_account.phone_number_id,
    'to_phone_e164',v_phone,'text',v_text,'whatsapp_account_id',v_job.whatsapp_account_id,'conversation_id',v_job.conversation_id);
end;
$function$
;

-- function: ops2_ana_claim_dry_run_job_v1(p_job_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_ana_claim_dry_run_job_v1(p_job_id uuid)
 RETURNS SETOF whatsapp_ana_jobs_v1
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_job_id is null then return; end if;

  return query
  with picked as (
    select j.id
    from public.whatsapp_ana_jobs_v1 j
    where j.id=p_job_id
      and j.status='queued'
      and j.dry_run=true
      and j.available_at<=now()
    for update skip locked
  ), claimed as (
    update public.whatsapp_ana_jobs_v1 j
    set status='claimed',
        claimed_at=now(),
        attempt_count=j.attempt_count+1,
        updated_at=now(),
        last_error=null
    from picked p
    where j.id=p.id
    returning j.*
  )
  select * from claimed;
end;
$function$
;

-- function: ops2_ana_claim_dry_run_v1(p_limit integer)
CREATE OR REPLACE FUNCTION public.ops2_ana_claim_dry_run_v1(p_limit integer DEFAULT 1)
 RETURNS SETOF whatsapp_ana_jobs_v1
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_limit integer:=greatest(1,least(coalesce(p_limit,1),5));
begin
  return query with picked as (
    select j.id from public.whatsapp_ana_jobs_v1 j where j.status='queued' and j.dry_run=true and j.available_at<=now() order by j.created_at,j.id for update skip locked limit v_limit
  ), claimed as (
    update public.whatsapp_ana_jobs_v1 j set status='claimed',claimed_at=now(),attempt_count=j.attempt_count+1,updated_at=now(),last_error=null from picked p where j.id=p.id returning j.*
  ) select * from claimed;
end;$function$
;

-- function: ops2_ana_claim_live_v1(p_limit integer)
CREATE OR REPLACE FUNCTION public.ops2_ana_claim_live_v1(p_limit integer DEFAULT 1)
 RETURNS SETOF whatsapp_ana_jobs_v1
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_limit integer:=greatest(1,least(coalesce(p_limit,1),3));
begin
  return query with picked as (
    select j.id from public.whatsapp_ana_jobs_v1 j
    where j.status='queued' and j.dry_run=false and j.available_at<=now()
    order by j.created_at,j.id for update skip locked limit v_limit
  ), claimed as (
    update public.whatsapp_ana_jobs_v1 j set status='claimed',claimed_at=now(),attempt_count=j.attempt_count+1,
      updated_at=now(),last_error=null from picked p where j.id=p.id returning j.*
  ) select * from claimed;
end;
$function$
;

-- function: ops2_ana_customer_confirmation_apply_signal_v1(p_request_id uuid, p_message_id uuid, p_decision text)
CREATE OR REPLACE FUNCTION public.ops2_ana_customer_confirmation_apply_signal_v1(p_request_id uuid, p_message_id uuid, p_decision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_request public.customer_profile_confirmation_requests_v1%rowtype;
  v_message public.whatsapp_messages_v1%rowtype;
  v_outbound public.whatsapp_messages_v1%rowtype;
  v_decision text:=lower(btrim(coalesce(p_decision,'')));
  v_target_status text;
begin
  if coalesce(auth.role(),'')<>'service_role' then return jsonb_build_object('ok',false,'error','service_role_required'); end if;
  if p_request_id is null or p_message_id is null then return jsonb_build_object('ok',false,'error','confirmation_signal_required'); end if;
  if v_decision not in ('confirm','correct') then return jsonb_build_object('ok',false,'error','confirmation_decision_invalid'); end if;

  select * into v_request from public.customer_profile_confirmation_requests_v1 where id=p_request_id for update;
  if not found then return jsonb_build_object('ok',false,'error','confirmation_request_not_found'); end if;
  v_target_status:=case when v_decision='confirm' then 'confirmed' else 'corrected' end;
  if v_request.status=v_target_status and v_request.confirmation_inbound_message_id=p_message_id then
    return jsonb_build_object('ok',true,'request_id',v_request.id,'status',v_request.status,'idempotent',true);
  end if;
  if v_request.status<>'pending' then return jsonb_build_object('ok',false,'error','confirmation_request_not_pending'); end if;

  select * into v_message from public.whatsapp_messages_v1 where id=p_message_id;
  if not found or v_message.direction<>'inbound' or v_message.conversation_id<>v_request.conversation_id then
    return jsonb_build_object('ok',false,'error','confirmation_message_mismatch');
  end if;
  if v_request.expires_at<=now() or v_message.received_at is null or v_message.received_at>v_request.expires_at then
    return jsonb_build_object('ok',false,'error','confirmation_request_expired');
  end if;
  if v_request.outbound_message_id is null then return jsonb_build_object('ok',false,'error','confirmation_request_not_sent'); end if;
  select * into v_outbound from public.whatsapp_messages_v1 where id=v_request.outbound_message_id;
  if not found or v_outbound.direction<>'outbound' or v_outbound.conversation_id<>v_request.conversation_id then
    return jsonb_build_object('ok',false,'error','confirmation_outbound_message_mismatch');
  end if;
  if v_message.received_at<=coalesce(v_outbound.sent_at,v_outbound.created_at) then
    return jsonb_build_object('ok',false,'error','confirmation_message_before_request');
  end if;

  update public.customer_profile_confirmation_requests_v1
  set status=v_target_status,confirmation_inbound_message_id=p_message_id,completed_at=now(),updated_at=now()
  where id=p_request_id and status='pending';

  if v_decision='correct' then
    update public.customer_profile_suggestions_v1
    set status='expired',updated_at=now()
    where id=any(v_request.suggestion_ids) and conversation_id=v_request.conversation_id and status='pending';
  end if;

  return jsonb_build_object('ok',true,'request_id',p_request_id,'message_id',p_message_id,'status',v_target_status,'idempotent',false);
exception when unique_violation then
  return jsonb_build_object('ok',false,'error','confirmation_message_already_used');
end;
$function$
;

-- function: ops2_ana_customer_confirmation_bind_outbound_v1(p_request_id uuid, p_message_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_ana_customer_confirmation_bind_outbound_v1(p_request_id uuid, p_message_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_access jsonb:=public.ops2_admin_attendance_customer_access_v1(false);
  v_request public.customer_profile_confirmation_requests_v1%rowtype;
  v_message public.whatsapp_messages_v1%rowtype;
begin
  if coalesce((v_access->>'ok')::boolean,false) is not true then return v_access; end if;
  if p_request_id is null or p_message_id is null then return jsonb_build_object('ok',false,'error','confirmation_binding_required'); end if;

  select * into v_request from public.customer_profile_confirmation_requests_v1 where id=p_request_id for update;
  if not found then return jsonb_build_object('ok',false,'error','confirmation_request_not_found'); end if;
  if v_request.status<>'pending' or v_request.expires_at<=now() then
    return jsonb_build_object('ok',false,'error','confirmation_request_not_pending');
  end if;
  if v_request.outbound_message_id=p_message_id then
    return jsonb_build_object('ok',true,'request_id',v_request.id,'message_id',p_message_id,'idempotent',true);
  end if;
  if v_request.outbound_message_id is not null then
    return jsonb_build_object('ok',false,'error','confirmation_already_bound');
  end if;

  select * into v_message from public.whatsapp_messages_v1 where id=p_message_id;
  if not found or v_message.direction<>'outbound' or v_message.provider<>'meta'
    or v_message.conversation_id<>v_request.conversation_id or v_message.sent_at is null
    or v_message.sent_at<v_request.requested_at then
    return jsonb_build_object('ok',false,'error','confirmation_outbound_message_mismatch');
  end if;

  update public.customer_profile_confirmation_requests_v1
    set outbound_message_id=p_message_id,updated_at=now()
    where id=v_request.id and status='pending' and outbound_message_id is null;

  return jsonb_build_object('ok',true,'request_id',v_request.id,'message_id',p_message_id,'idempotent',false);
end;
$function$
;

-- function: ops2_ana_customer_confirmation_create_v1(p_conversation_id uuid, p_suggestion_ids uuid[])
CREATE OR REPLACE FUNCTION public.ops2_ana_customer_confirmation_create_v1(p_conversation_id uuid, p_suggestion_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_access jsonb:=public.ops2_admin_attendance_customer_access_v1(true);
  v_conversation public.conversations%rowtype;
  v_resolution jsonb;
  v_customer_id uuid;
  v_ids uuid[];
  v_count integer;
  v_customer_mismatch integer;
  v_existing public.customer_profile_confirmation_requests_v1%rowtype;
  v_request public.customer_profile_confirmation_requests_v1%rowtype;
  v_summary jsonb;
  v_user_id uuid:=auth.uid();
begin
  if coalesce((v_access->>'ok')::boolean,false) is not true then return v_access; end if;
  if p_conversation_id is null then return jsonb_build_object('ok',false,'error','invalid_conversation_id'); end if;
  if coalesce(cardinality(p_suggestion_ids),0) not between 1 and 8 or array_position(p_suggestion_ids,null) is not null then
    return jsonb_build_object('ok',false,'error','suggestions_required');
  end if;

  select array_agg(distinct suggestion_id order by suggestion_id) into v_ids
  from unnest(p_suggestion_ids) as ids(suggestion_id);
  if cardinality(v_ids)<>cardinality(p_suggestion_ids) then return jsonb_build_object('ok',false,'error','duplicate_suggestion_ids'); end if;

  perform pg_advisory_xact_lock(hashtextextended(p_conversation_id::text,0));
  select * into v_conversation from public.conversations where id=p_conversation_id for update;
  if not found then return jsonb_build_object('ok',false,'error','conversation_not_found'); end if;

  v_resolution:=public.resolve_customer_by_phone_v1(v_conversation.wa_contact_e164);
  if v_resolution->>'match_status'='ambiguous' then return jsonb_build_object('ok',false,'error','ambiguous_phone'); end if;
  v_customer_id:=v_conversation.customer_id;
  if v_customer_id is null and v_resolution->>'match_status'='matched' then
    v_customer_id:=(v_resolution->>'customer_id')::uuid;
  elsif v_customer_id is not null and v_resolution->>'match_status'='matched'
      and (v_resolution->>'customer_id')::uuid<>v_customer_id then
    return jsonb_build_object('ok',false,'error','customer_identity_conflict');
  end if;

  select count(*),count(*) filter(where s.customer_id is distinct from v_customer_id)
    into v_count,v_customer_mismatch
  from public.customer_profile_suggestions_v1 s
  where s.id=any(v_ids) and s.conversation_id=p_conversation_id and s.status='pending';
  if v_count<>cardinality(v_ids) then return jsonb_build_object('ok',false,'error','suggestion_not_pending_for_conversation'); end if;
  if v_customer_mismatch>0 then return jsonb_build_object('ok',false,'error','suggestion_customer_mismatch'); end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'suggestion_id',s.id,
    'field_name',s.field_name,
    'label',case s.field_name
      when 'name' then 'Nome' when 'cpf_cnpj' then 'CPF/CNPJ' when 'email' then 'E-mail'
      when 'postal_code' then 'CEP' when 'street' then 'Rua' when 'number' then 'Número'
      when 'complement' then 'Complemento' when 'neighborhood' then 'Bairro'
      when 'city' then 'Cidade' when 'state' then 'Estado' when 'reference' then 'Referência'
      else 'Dado'
    end,
    'value',case when s.field_name='cpf_cnpj'
      then '***'||right(regexp_replace(coalesce(s.normalized_value,''),'[^0-9]','','g'),4)
      else coalesce(s.normalized_value,'') end
  ) order by s.created_at,s.id),'[]'::jsonb)
    into v_summary
  from public.customer_profile_suggestions_v1 s
  where s.id=any(v_ids) and s.conversation_id=p_conversation_id and s.status='pending';

  select * into v_existing from public.customer_profile_confirmation_requests_v1
  where conversation_id=p_conversation_id and status='pending' for update;
  if found and v_existing.expires_at>now() and v_existing.suggestion_ids=v_ids then
    return jsonb_build_object('ok',true,'request_id',v_existing.id,'status','pending','expires_at',v_existing.expires_at,'summary',v_existing.confirmation_summary,'idempotent',true);
  end if;
  if found then
    update public.customer_profile_confirmation_requests_v1
      set status=case when expires_at<=now() then 'expired' else 'cancelled' end,
          completed_at=now(),updated_at=now()
      where id=v_existing.id;
  end if;

  insert into public.customer_profile_confirmation_requests_v1(
    conversation_id,customer_id,suggestion_ids,confirmation_summary,created_by_admin_user_id
  ) values (p_conversation_id,v_customer_id,v_ids,v_summary,v_user_id)
  returning * into v_request;

  return jsonb_build_object('ok',true,'request_id',v_request.id,'status',v_request.status,'expires_at',v_request.expires_at,'summary',v_request.confirmation_summary,'idempotent',false);
end;
$function$
;

-- function: ops2_ana_customer_confirmation_pending_v1(p_conversation_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_ana_customer_confirmation_pending_v1(p_conversation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_access jsonb:=public.ops2_admin_attendance_customer_access_v1(false);
  v_request public.customer_profile_confirmation_requests_v1%rowtype;
begin
  if coalesce((v_access->>'ok')::boolean,false) is not true then return v_access; end if;
  if p_conversation_id is null then return jsonb_build_object('ok',false,'error','invalid_conversation_id'); end if;
  if not exists(select 1 from public.conversations where id=p_conversation_id) then return jsonb_build_object('ok',false,'error','conversation_not_found'); end if;

  select * into v_request from public.customer_profile_confirmation_requests_v1
  where conversation_id=p_conversation_id and status='pending' and expires_at>now()
  order by requested_at desc limit 1;
  if not found then return jsonb_build_object('ok',true,'pending',false,'conversation_id',p_conversation_id); end if;

  return jsonb_build_object(
    'ok',true,'pending',true,'request_id',v_request.id,'customer_id',v_request.customer_id,
    'conversation_id',v_request.conversation_id,'suggestion_ids',to_jsonb(v_request.suggestion_ids),
    'summary',v_request.confirmation_summary,'expires_at',v_request.expires_at,
    'outbound_message_id',v_request.outbound_message_id
  );
end;
$function$
;

-- function: ops2_ana_customer_profile_persist_v1(p_conversation_id uuid, p_customer_id uuid, p_conversation_phone_e164 text, p_snapshot_key text, p_model text, p_provider_response_id text, p_metadata jsonb, p_created_by_admin_user_id uuid, p_candidates jsonb)
CREATE OR REPLACE FUNCTION public.ops2_ana_customer_profile_persist_v1(p_conversation_id uuid, p_customer_id uuid, p_conversation_phone_e164 text, p_snapshot_key text, p_model text, p_provider_response_id text, p_metadata jsonb, p_created_by_admin_user_id uuid, p_candidates jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_run_id uuid;
  v_candidate jsonb;
  v_field text;
  v_value text;
  v_normalized text;
  v_classification text;
  v_recommendation text;
  v_confidence numeric;
  v_evidence uuid[];
  v_doc text;
  v_doc_conflict boolean:=false;
  v_items jsonb:='[]'::jsonb;
begin
  if p_conversation_id is null or nullif(btrim(coalesce(p_snapshot_key,'')),'') is null then
    return jsonb_build_object('ok',false,'error','invalid_profile_snapshot');
  end if;
  if not exists(select 1 from public.conversations c where c.id=p_conversation_id) then
    return jsonb_build_object('ok',false,'error','conversation_not_found');
  end if;

  insert into public.customer_profile_extraction_runs_v1(
    conversation_id,customer_id,conversation_phone_e164,snapshot_key,status,model,
    provider_response_id,metadata,created_by_admin_user_id
  ) values(
    p_conversation_id,p_customer_id,nullif(btrim(coalesce(p_conversation_phone_e164,'')),''),
    p_snapshot_key,'completed',nullif(btrim(coalesce(p_model,'')),''),
    nullif(btrim(coalesce(p_provider_response_id,'')),''),coalesce(p_metadata,'{}'::jsonb),p_created_by_admin_user_id
  )
  on conflict(conversation_id,snapshot_key) do nothing
  returning id into v_run_id;

  if v_run_id is null then
    select r.id into v_run_id
    from public.customer_profile_extraction_runs_v1 r
    where r.conversation_id=p_conversation_id and r.snapshot_key=p_snapshot_key;

    select coalesce(jsonb_agg(jsonb_build_object(
      'id',s.id,'run_id',s.run_id,'field_name',s.field_name,'normalized_value',s.normalized_value,
      'confidence',s.confidence,'classification',s.classification,'recommendation',s.recommendation,
      'evidence_message_ids',to_jsonb(s.evidence_message_ids),'status',s.status,'created_at',s.created_at
    ) order by s.created_at),'[]'::jsonb)
    into v_items
    from public.customer_profile_suggestions_v1 s where s.run_id=v_run_id;

    return jsonb_build_object('ok',true,'reused',true,'run_id',v_run_id,'suggestions',v_items);
  end if;

  for v_candidate in
    select value from jsonb_array_elements(coalesce(p_candidates,'[]'::jsonb))
  loop
    v_field:=lower(btrim(coalesce(v_candidate->>'field_name','')));
    if not (v_field=any(array['name','cpf_cnpj','email','postal_code','street','number','complement','neighborhood','city','state','reference']::text[])) then
      continue;
    end if;

    v_value:=nullif(left(btrim(coalesce(v_candidate->>'value','')),1200),'');
    if v_value is null then continue; end if;
    v_confidence:=greatest(0,least(1,coalesce((v_candidate->>'confidence')::numeric,0)));
    v_classification:=case when v_candidate->>'classification' in ('explicit','derived','ambiguous') then v_candidate->>'classification' else 'ambiguous' end;
    v_recommendation:=case when v_candidate->>'recommendation' in ('auto_apply','confirm','ignore') then v_candidate->>'recommendation' else 'ignore' end;

    select coalesce(array_agg(m.id order by m.created_at),array[]::uuid[])
    into v_evidence
    from jsonb_array_elements_text(coalesce(v_candidate->'evidence_message_ids','[]'::jsonb)) e(id_text)
    join public.whatsapp_messages_v1 m
      on m.id=e.id_text::uuid and m.conversation_id=p_conversation_id;
    if coalesce(array_length(v_evidence,1),0)=0 then continue; end if;

    v_normalized:=v_value;
    if v_field='cpf_cnpj' then
      v_doc:=regexp_replace(v_value,'[^0-9]','','g');
      v_normalized:=v_doc;
      if public.ops2_valid_cpf_cnpj_v1(v_doc) is not true then
        v_recommendation:='ignore';
      else
        select exists(
          select 1 from public.customers c
          where regexp_replace(coalesce(c.cpf_cnpj,''),'[^0-9]','','g')=v_doc
            and (p_customer_id is null or c.id<>p_customer_id)
        ) into v_doc_conflict;
        if v_doc_conflict then v_recommendation:='ignore'; end if;
      end if;
    end if;

    insert into public.customer_profile_suggestions_v1(
      run_id,conversation_id,customer_id,field_name,suggested_value,normalized_value,
      confidence,classification,recommendation,evidence_message_ids,model,policy_version
    ) values(
      v_run_id,p_conversation_id,p_customer_id,v_field,jsonb_build_object('value',v_value),v_normalized,
      v_confidence,v_classification,v_recommendation,v_evidence,nullif(btrim(coalesce(p_model,'')),''),'ana_customer_profile_v1'
    )
    on conflict(run_id,field_name,normalized_value) do nothing;
  end loop;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',s.id,'run_id',s.run_id,'field_name',s.field_name,'normalized_value',s.normalized_value,
    'confidence',s.confidence,'classification',s.classification,'recommendation',s.recommendation,
    'evidence_message_ids',to_jsonb(s.evidence_message_ids),'status',s.status,'created_at',s.created_at
  ) order by s.created_at),'[]'::jsonb)
  into v_items
  from public.customer_profile_suggestions_v1 s where s.run_id=v_run_id;

  return jsonb_build_object('ok',true,'reused',false,'run_id',v_run_id,'suggestions',v_items);
end;
$function$
;

-- function: ops2_ana_enqueue_dry_run_v1(p_inbound_message_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_ana_enqueue_dry_run_v1(p_inbound_message_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_message public.whatsapp_messages_v1%rowtype; v_gate jsonb; v_existing public.whatsapp_ana_jobs_v1%rowtype; v_job_id uuid;
begin
  if p_inbound_message_id is null then return jsonb_build_object('ok',false,'error','inbound_message_required'); end if;
  select m.* into v_message from public.whatsapp_messages_v1 m where m.id=p_inbound_message_id;
  if not found then return jsonb_build_object('ok',false,'error','inbound_message_not_found'); end if;
  if v_message.direction<>'inbound' then return jsonb_build_object('ok',false,'error','message_not_inbound'); end if;
  if v_message.message_type<>'text' or nullif(btrim(coalesce(v_message.text_body,'')),'') is null then return jsonb_build_object('ok',false,'error','message_type_not_supported'); end if;
  select j.* into v_existing from public.whatsapp_ana_jobs_v1 j where j.inbound_message_id=p_inbound_message_id;
  if found then return jsonb_build_object('ok',true,'duplicate',true,'job_id',v_existing.id,'status',v_existing.status,'dry_run',v_existing.dry_run); end if;
  v_gate:=public.ops2_attendance_ai_gate_v1(v_message.conversation_id);
  if coalesce((v_gate->>'ok')::boolean,false) is not true or coalesce((v_gate->>'allowed')::boolean,false) is not true then return jsonb_build_object('ok',false,'error','ai_gate_closed','gate',v_gate); end if;
  insert into public.whatsapp_ana_jobs_v1(inbound_message_id,conversation_id,whatsapp_account_id,dry_run,status,metadata)
  values(v_message.id,v_message.conversation_id,v_message.whatsapp_account_id,true,'queued',jsonb_build_object('source','explicit_dry_run_enqueue','provider',v_message.provider,'provider_message_id',v_message.provider_message_id)) returning id into v_job_id;
  return jsonb_build_object('ok',true,'duplicate',false,'job_id',v_job_id,'status','queued','dry_run',true);
exception when unique_violation then
  select j.* into v_existing from public.whatsapp_ana_jobs_v1 j where j.inbound_message_id=p_inbound_message_id;
  return jsonb_build_object('ok',true,'duplicate',true,'job_id',v_existing.id,'status',v_existing.status,'dry_run',v_existing.dry_run);
end;$function$
;

-- function: ops2_ana_enqueue_live_job_v1(p_inbound_message_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_ana_enqueue_live_job_v1(p_inbound_message_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_message public.whatsapp_messages_v1%rowtype;
  v_runtime public.whatsapp_channel_runtime_v1%rowtype;
  v_gate jsonb;
  v_job public.whatsapp_ana_jobs_v1%rowtype;
begin
  if p_inbound_message_id is null then return jsonb_build_object('ok',false,'error','inbound_message_required'); end if;
  select * into v_message from public.whatsapp_messages_v1 where id=p_inbound_message_id;
  if not found or v_message.direction<>'inbound' then return jsonb_build_object('ok',false,'error','inbound_message_required'); end if;
  if v_message.message_type<>'text' or nullif(btrim(coalesce(v_message.text_body,'')),'') is null then
    return jsonb_build_object('ok',false,'error','message_type_not_supported');
  end if;
  select * into v_runtime from public.whatsapp_channel_runtime_v1
    where whatsapp_account_id=v_message.whatsapp_account_id;
  if not found or v_runtime.ana_enabled is not true or v_runtime.send_enabled is not true
     or v_runtime.outbound_provider is distinct from 'meta' or v_runtime.homologated_at is null then
    return jsonb_build_object('ok',false,'error','ana_channel_gate_closed');
  end if;
  v_gate:=public.ops2_attendance_ai_gate_v1(v_message.conversation_id);
  if coalesce((v_gate->>'allowed')::boolean,false) is not true then
    return jsonb_build_object('ok',false,'error','ai_gate_closed','gate',v_gate);
  end if;
  select * into v_job from public.whatsapp_ana_jobs_v1 where inbound_message_id=v_message.id;
  if found then return jsonb_build_object('ok',true,'duplicate',true,'job_id',v_job.id,'status',v_job.status); end if;
  insert into public.whatsapp_ana_jobs_v1(inbound_message_id,conversation_id,whatsapp_account_id,dry_run,status,metadata)
  values(v_message.id,v_message.conversation_id,v_message.whatsapp_account_id,false,'queued',
    jsonb_build_object('source','meta_webhook','provider',v_message.provider,'provider_message_id',v_message.provider_message_id))
  returning * into v_job;
  return jsonb_build_object('ok',true,'duplicate',false,'job_id',v_job.id,'status',v_job.status);
exception when unique_violation then
  select * into v_job from public.whatsapp_ana_jobs_v1 where inbound_message_id=p_inbound_message_id;
  return jsonb_build_object('ok',true,'duplicate',true,'job_id',v_job.id,'status',v_job.status);
end;
$function$
;

-- function: ops2_ana_fail_live_send_v1(p_outbox_id uuid, p_reason text)
CREATE OR REPLACE FUNCTION public.ops2_ana_fail_live_send_v1(p_outbox_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_outbox public.whatsapp_outbox_v1%rowtype;
begin
  update public.whatsapp_outbox_v1 set status='failed',last_error=left(coalesce(p_reason,'meta_send_uncertain'),250),updated_at=now()
    where id=p_outbox_id and purpose='ai_attendance' and status='claimed' returning * into v_outbox;
  if not found then return jsonb_build_object('ok',false,'error','live_outbox_not_claimed'); end if;
  return jsonb_build_object('ok',true,'outbox_id',v_outbox.id,'status',v_outbox.status);
end;
$function$
;

-- function: ops2_ana_finish_dry_run_v1(p_job_id uuid, p_status text, p_decision text, p_suggestion_text text, p_confidence numeric, p_reason text, p_model text, p_provider_response_id text, p_last_error text, p_metadata jsonb)
CREATE OR REPLACE FUNCTION public.ops2_ana_finish_dry_run_v1(p_job_id uuid, p_status text, p_decision text DEFAULT NULL::text, p_suggestion_text text DEFAULT NULL::text, p_confidence numeric DEFAULT NULL::numeric, p_reason text DEFAULT NULL::text, p_model text DEFAULT NULL::text, p_provider_response_id text DEFAULT NULL::text, p_last_error text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_job public.whatsapp_ana_jobs_v1%rowtype; v_status text:=lower(btrim(coalesce(p_status,''))); v_decision text:=nullif(lower(btrim(coalesce(p_decision,''))),'');
begin
  if p_job_id is null then return jsonb_build_object('ok',false,'error','job_required'); end if;
  if v_status not in ('completed','skipped','failed') then return jsonb_build_object('ok',false,'error','status_invalid'); end if;
  if v_decision is not null and v_decision not in ('suggest','handoff','no_reply') then return jsonb_build_object('ok',false,'error','decision_invalid'); end if;
  select j.* into v_job from public.whatsapp_ana_jobs_v1 j where j.id=p_job_id for update;
  if not found then return jsonb_build_object('ok',false,'error','job_not_found'); end if;
  if v_job.status not in ('claimed','queued') then return jsonb_build_object('ok',true,'duplicate',true,'job_id',v_job.id,'status',v_job.status); end if;
  update public.whatsapp_ana_jobs_v1 set status=v_status,decision=case when v_status='completed' then v_decision else null end,suggestion_text=case when v_status='completed' then nullif(btrim(coalesce(p_suggestion_text,'')),'') else null end,confidence=case when v_status='completed' then greatest(0,least(coalesce(p_confidence,0),1)) else null end,reason=nullif(btrim(coalesce(p_reason,'')),''),model=nullif(btrim(coalesce(p_model,'')),''),provider_response_id=nullif(btrim(coalesce(p_provider_response_id,'')),''),completed_at=now(),last_error=case when v_status='failed' then left(coalesce(p_last_error,'ana_dry_run_failed'),500) else null end,metadata=coalesce(metadata,'{}'::jsonb)||coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('dry_run_not_sendable',true),updated_at=now() where id=p_job_id returning * into v_job;
  return jsonb_build_object('ok',true,'duplicate',false,'job_id',v_job.id,'status',v_job.status,'decision',v_job.decision,'dry_run',v_job.dry_run);
end;$function$
;

-- function: ops2_ana_finish_live_job_v1(p_job_id uuid, p_status text, p_decision text, p_text text, p_confidence numeric, p_reason text, p_model text, p_provider_response_id text, p_error text, p_metadata jsonb)
CREATE OR REPLACE FUNCTION public.ops2_ana_finish_live_job_v1(p_job_id uuid, p_status text, p_decision text DEFAULT NULL::text, p_text text DEFAULT NULL::text, p_confidence numeric DEFAULT NULL::numeric, p_reason text DEFAULT NULL::text, p_model text DEFAULT NULL::text, p_provider_response_id text DEFAULT NULL::text, p_error text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_job public.whatsapp_ana_jobs_v1%rowtype;
begin
  if p_status not in ('completed','skipped','failed') or coalesce(p_decision,'') not in ('suggest','handoff','no_reply') then
    return jsonb_build_object('ok',false,'error','live_job_result_invalid');
  end if;
  select * into v_job from public.whatsapp_ana_jobs_v1 where id=p_job_id for update;
  if not found or v_job.dry_run is not false or v_job.status not in ('claimed','queued') then
    return jsonb_build_object('ok',false,'error','live_job_not_claimed');
  end if;
  update public.whatsapp_ana_jobs_v1 set status=p_status,decision=p_decision,suggestion_text=nullif(btrim(coalesce(p_text,'')),''),
    confidence=greatest(0,least(coalesce(p_confidence,0),1)),reason=left(coalesce(p_reason,''),300),
    model=left(coalesce(p_model,''),120),provider_response_id=left(coalesce(p_provider_response_id,''),500),
    completed_at=now(),last_error=case when p_status='failed' then left(coalesce(p_error,'ana_live_failed'),500) else null end,
    metadata=coalesce(metadata,'{}'::jsonb)||coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('dry_run_not_sendable',false),updated_at=now()
  where id=p_job_id returning * into v_job;
  return jsonb_build_object('ok',true,'job_id',v_job.id,'status',v_job.status,'decision',v_job.decision);
end;
$function$
;

-- function: ops2_ana_remove_trigger_label_v1(p_conversation_id uuid, p_label_id uuid, p_trigger_key text)
CREATE OR REPLACE FUNCTION public.ops2_ana_remove_trigger_label_v1(p_conversation_id uuid, p_label_id uuid, p_trigger_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  label_source uuid;
  removed_count integer := 0;
  consolidated_removed integer := 0;
  has_other_origin boolean := false;
begin
  if p_conversation_id is null
     or p_label_id is null
     or btrim(coalesce(p_trigger_key,'')) = ''
     or char_length(p_trigger_key) > 40 then
    return jsonb_build_object('ok',false,'error','trigger_label_input_invalid');
  end if;

  if not exists(select 1 from public.conversations where id=p_conversation_id) then
    return jsonb_build_object('ok',false,'error','conversation_not_found');
  end if;

  if not exists(select 1 from public.attendance_labels_v1 where id=p_label_id) then
    return jsonb_build_object('ok',false,'error','label_not_found');
  end if;

  label_source := md5('ana-trigger:' || p_trigger_key)::uuid;

  delete from public.attendance_conversation_auto_labels_v1
  where conversation_id=p_conversation_id
    and label_id=p_label_id
    and source_kind='ana_trigger'
    and source_ref=label_source;
  get diagnostics removed_count = row_count;

  select
    exists(
      select 1
      from public.attendance_conversation_auto_labels_v1
      where conversation_id=p_conversation_id and label_id=p_label_id
    )
    or exists(
      select 1
      from public.attendance_conversation_manual_labels_v1
      where conversation_id=p_conversation_id and label_id=p_label_id
    )
  into has_other_origin;

  if not has_other_origin then
    delete from public.attendance_conversation_labels_v1
    where conversation_id=p_conversation_id and label_id=p_label_id;
    get diagnostics consolidated_removed = row_count;
  end if;

  return jsonb_build_object(
    'ok',true,
    'removed',removed_count > 0,
    'consolidated_removed',consolidated_removed > 0,
    'preserved_by_other_origin',has_other_origin
  );
end;
$function$
;

-- function: ops2_apply_order_separation_stock_v2(p_order_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_apply_order_separation_stock_v2(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_completion public.order_separation_completions_v1%rowtype;
  v_missing_components jsonb := '[]'::jsonb;
  v_now timestamptz := now();
  v_order_status text;
  v_cutover timestamptz;
  r record;
  v_delta numeric;
  v_stock numeric;
  v_deliverable_qty numeric;
begin
  if p_order_id is null then return jsonb_build_object('ok',false,'error','invalid_order_id'); end if;
  select status into v_order_status from public.orders where id=p_order_id for update;
  if not found then return jsonb_build_object('ok',false,'error','order_not_found'); end if;
  select * into v_completion from public.order_separation_completions_v1 where order_id=p_order_id for update;
  if not found then return jsonb_build_object('ok',false,'error','separation_completion_not_prepared'); end if;
  if coalesce((v_completion.metadata->>'stock_applied')::boolean,false) then
    if v_order_status in ('confirmed','processing') then
      update public.orders set status='ready',updated_at=v_now where id=p_order_id;
      v_order_status:='ready';
    end if;
    return jsonb_build_object('ok',true,'status','already_applied','physical_stock_changed',false,
      'stock_source','supabase_products_stock','phase',v_completion.phase,'local_order_status',v_order_status,'metadata',v_completion.metadata);
  end if;
  if v_order_status not in ('confirmed','processing','ready') then
    return jsonb_build_object('ok',false,'error','order_not_in_separation','status',v_order_status);
  end if;
  select nullif(metadata->>'ops2_supabase_stock_authority_at','')::timestamptz into v_cutover
  from public.bling_hub_runtime_v2 where id=1;

  for r in
    select vr.id,vr.product_id,vr.quantity,vr.status,vr.consumed_at,
      coalesce(d.deliverable_qty,0)::numeric as deliverable_qty
    from public.vitrine_stock_reservations vr
    left join (
      select s.product_id,
        sum(case when coalesce(oi.metadata->>'history_kind','')='basket_component'
          then greatest(0,s.quantity-coalesce(nullif(oi.metadata->>'preassembled_units','')::numeric,0))
          else s.quantity end)::numeric as deliverable_qty
      from public.order_separation_items_v1 s
      join public.order_items oi on oi.id=s.order_item_id
      where s.order_id=p_order_id and s.state='separated' and s.product_id is not null
      group by s.product_id
    ) d on d.product_id=vr.product_id
    where vr.order_id=p_order_id
    order by vr.product_id
    for update of vr
  loop
    if r.status='consumed' and coalesce(r.consumed_at,v_now)>=v_cutover then
      v_delta:=r.quantity-r.deliverable_qty;
    else
      v_delta:=-r.deliverable_qty;
    end if;
    if v_delta<>0 then
      select coalesce(stock,0) into v_stock from public.products where id=r.product_id for update;
      if not found then raise exception 'separation_stock_product_missing:%',r.product_id using errcode='P0001'; end if;
      if v_stock+v_delta<0 then
        raise exception 'separation_stock_below_zero:%:%',r.product_id,v_stock+v_delta using errcode='P0001';
      end if;
      update public.products set stock=v_stock+v_delta,updated_at=v_now where id=r.product_id;
    end if;
    if r.deliverable_qty<=0 then
      update public.vitrine_stock_reservations set status='released',released_at=v_now,consumed_at=null,updated_at=v_now where id=r.id;
    else
      update public.vitrine_stock_reservations set quantity=r.deliverable_qty,status='consumed',consumed_at=v_now,released_at=null,updated_at=v_now where id=r.id;
    end if;
  end loop;

  -- Older orders without a reservation row use only the quantities marked as separated.
  -- Historical preassembled quantities remain read from their order-item snapshot.
  for r in
    select s.product_id,
      sum(case when coalesce(oi.metadata->>'history_kind','')='basket_component'
        then greatest(0,s.quantity-coalesce(nullif(oi.metadata->>'preassembled_units','')::numeric,0))
        else s.quantity end)::numeric as quantity
    from public.order_separation_items_v1 s
    join public.order_items oi on oi.id=s.order_item_id
    where s.order_id=p_order_id and s.state='separated' and s.product_id is not null
      and not exists(select 1 from public.vitrine_stock_reservations vr where vr.order_id=p_order_id and vr.product_id=s.product_id)
    group by s.product_id
  loop
    if r.quantity>0 then
      select coalesce(stock,0) into v_stock from public.products where id=r.product_id for update;
      if not found then raise exception 'separation_stock_product_missing:%',r.product_id using errcode='P0001'; end if;
      if v_stock<r.quantity then raise exception 'separation_stock_below_zero:%:%',r.product_id,v_stock-r.quantity using errcode='P0001'; end if;
      update public.products set stock=v_stock-r.quantity,updated_at=v_now where id=r.product_id;
    end if;
  end loop;

  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'order_item_id',s.order_item_id,'product_id',s.product_id,'quantity',s.quantity,
    'basket_id',nullif(oi.metadata->>'basket_id',''),'basket_name',nullif(oi.metadata->>'basket_name','')))),'[]'::jsonb)
    into v_missing_components
  from public.order_separation_items_v1 s join public.order_items oi on oi.id=s.order_item_id
  where s.order_id=p_order_id and s.state='missing';
  update public.order_separation_completions_v1
    set phase='stock_applied',metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object(
      'stock_applied',true,'stock_authority','supabase','stock_source','products.stock',
      'physical_stock_changed',true,'missing_components',v_missing_components,'stock_applied_at',v_now),updated_at=v_now
    where order_id=p_order_id;
  if v_order_status in ('confirmed','processing') then
    update public.orders set status='ready',updated_at=v_now where id=p_order_id;
    v_order_status:='ready';
  end if;
  return jsonb_build_object('ok',true,'status','stock_applied','stock_authority','supabase',
    'stock_source','products.stock','physical_stock_changed',true,'local_order_status',v_order_status,
    'missing_components',v_missing_components);
end;
$function$
;

-- function: ops2_apply_papoai_customer_flow_v1(p_event_key text, p_phone text, p_name text, p_conversation_ref text)
CREATE OR REPLACE FUNCTION public.ops2_apply_papoai_customer_flow_v1(p_event_key text, p_phone text, p_name text, p_conversation_ref text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  return public.ops2_apply_papoai_customer_flow_v2(
    p_event_key,p_phone,p_name,null,null,null,null,'MT',p_conversation_ref,null,null
  );
end;
$function$
;

-- function: ops2_apply_papoai_customer_flow_v2(p_event_key text, p_phone text, p_name text, p_document text, p_address text, p_district text, p_city text, p_state text, p_conversation_ref text, p_capture_id uuid, p_flow_token text)
CREATE OR REPLACE FUNCTION public.ops2_apply_papoai_customer_flow_v2(p_event_key text, p_phone text, p_name text, p_document text DEFAULT NULL::text, p_address text DEFAULT NULL::text, p_district text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_state text DEFAULT 'MT'::text, p_conversation_ref text DEFAULT NULL::text, p_capture_id uuid DEFAULT NULL::uuid, p_flow_token text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_event text:=nullif(left(btrim(coalesce(p_event_key,'')),220),'');
  v_phone text:=public.canonical_whatsapp_e164_br_v2(p_phone);
  v_name text:=nullif(left(btrim(regexp_replace(coalesce(p_name,''),'\s+',' ','g')),180),'');
  v_doc text:=regexp_replace(coalesce(p_document,''),'[^0-9]','','g');
  v_doc_valid boolean:=false;
  v_customer_id uuid;
  v_doc_customer_id uuid;
  v_identity jsonb;
  v_created boolean:=false;
  v_profile_status text;
  v_provisional_id uuid;
  v_conversation_id uuid;
  v_whatsapp_account_id uuid;
  v_order_id uuid;
  v_order_number text;
  v_order_suffix text;
  v_order_count integer:=0;
  v_address_id uuid;
  v_street text:=nullif(left(btrim(regexp_replace(coalesce(p_address,''),'\s+',' ','g')),300),'');
  v_district text:=nullif(left(btrim(regexp_replace(coalesce(p_district,''),'\s+',' ','g')),180),'');
  v_city text:=nullif(left(btrim(regexp_replace(coalesce(p_city,''),'\s+',' ','g')),120),'');
  v_state text:=upper(nullif(left(btrim(coalesce(p_state,'')),2),''));
  v_existing public.papoai_customer_flow_events_v1%rowtype;
  v_prior_text text;
  v_orders_linked integer:=0;
  v_merged boolean:=false;
begin
  if v_event is null then raise exception 'flow_event_key_required'; end if;
  if v_phone is null then raise exception 'invalid_phone'; end if;
  if v_name is null or length(v_name)<2 then raise exception 'customer_name_required'; end if;
  if v_state is null then v_state:='MT'; end if;

  select * into v_existing
  from public.papoai_customer_flow_events_v1
  where event_key=v_event;
  if found then
    return coalesce(v_existing.result,'{}'::jsonb)
      || jsonb_build_object('ok',v_existing.status='processed','duplicate',true,'event_key',v_event);
  end if;

  perform pg_advisory_xact_lock(hashtextextended('ops2:papoai-flow-v2:'||public.normalize_phone_digits(v_phone),0));

  v_doc_valid:=public.ops2_valid_cpf_cnpj_v1(v_doc);
  if v_doc_valid then
    select id into v_doc_customer_id
    from public.customers
    where regexp_replace(coalesce(cpf_cnpj,''),'[^0-9]','','g')=v_doc
    order by is_active desc,updated_at desc
    limit 1;
  end if;

  if v_doc_customer_id is not null then
    v_customer_id:=v_doc_customer_id;

    -- A site checkout may have created a provisional identity minutes earlier.
    -- Merge only that explicitly provisional, non-ERP identity; never arbitrary legacy customers.
    select c.id into v_provisional_id
    from public.customers c
    join public.customer_identity_profiles_v1 ip on ip.customer_id=c.id
    where c.id<>v_customer_id
      and ip.identity_status='provisional'
      and c.bling_contact_id is null
      and nullif(regexp_replace(coalesce(c.cpf_cnpj,''),'[^0-9]','','g'),'') is null
      and public.normalize_phone_digits(c.primary_whatsapp_e164)=public.normalize_phone_digits(v_phone)
    order by c.created_at desc
    limit 1
    for update;

    if v_provisional_id is not null then
      update public.orders
         set customer_id=v_customer_id,
             customer_snapshot=coalesce(customer_snapshot,'{}'::jsonb)
               || jsonb_build_object('customer_id',v_customer_id,'identity_merged_from',v_provisional_id),
             updated_at=now()
       where customer_id=v_provisional_id;

      update public.conversations
         set customer_id=v_customer_id,updated_at=now()
       where customer_id=v_provisional_id;

      update public.catalog_sessions
         set customer_id=v_customer_id
       where customer_id=v_provisional_id;

      update public.customer_phones
         set customer_id=v_customer_id,is_primary=false
       where customer_id=v_provisional_id
         and not exists(
           select 1 from public.customer_phones x
           where x.customer_id=v_customer_id and x.phone_e164=public.customer_phones.phone_e164
         );

      delete from public.customer_phones cp
       where cp.customer_id=v_provisional_id
         and exists(
           select 1 from public.customer_phones x
           where x.customer_id=v_customer_id and x.phone_e164=cp.phone_e164
         );

      update public.customers
         set primary_whatsapp_e164=null,is_active=false,updated_at=now()
       where id=v_provisional_id;

      update public.customer_identity_profiles_v1
         set identity_status='merged',
             metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('merged_into',v_customer_id,'merged_at',now()),
             updated_at=now()
       where customer_id=v_provisional_id;
      v_merged:=true;
    end if;

    update public.customers
       set name=case
             when nullif(btrim(coalesce(name,'')),'') is null then v_name
             else name
           end,
           primary_whatsapp_e164=case
             when primary_whatsapp_e164 is null
              and not exists(select 1 from public.customers x where x.id<>v_customer_id and x.primary_whatsapp_e164=v_phone)
             then v_phone else primary_whatsapp_e164 end,
           is_active=true,updated_at=now()
     where id=v_customer_id;

    if not exists(
      select 1 from public.customer_phones cp
      where cp.customer_id=v_customer_id
        and public.normalize_phone_digits(cp.phone_e164)=public.normalize_phone_digits(v_phone)
    ) and not exists(
      select 1 from public.customer_phones cp
      where cp.customer_id<>v_customer_id and cp.phone_e164=v_phone
    ) then
      insert into public.customer_phones(customer_id,phone_e164,source,is_primary,verified_at)
      values(v_customer_id,v_phone,'papoai_flow',false,now())
      on conflict(phone_e164) do nothing;
    end if;
    v_created:=false;
  else
    v_identity:=public.ensure_storefront_customer_v2(v_phone,v_name,v_event);
    if coalesce((v_identity->>'ok')::boolean,false) is not true then
      insert into public.papoai_customer_flow_events_v1(event_key,phone_e164,status,result)
      values(v_event,v_phone,'review_required',
        jsonb_build_object('ok',false,'error',coalesce(v_identity->>'error','identity_failed'),'external_write',false));
      return jsonb_build_object('ok',false,'error',coalesce(v_identity->>'error','identity_failed'),'review_required',true);
    end if;
    v_customer_id:=(v_identity->>'customer_id')::uuid;
    v_created:=coalesce((v_identity->>'created')::boolean,false);

    update public.customers
       set name=v_name,
           cpf_cnpj=case
             when v_doc_valid
              and not exists(
                select 1 from public.customers x
                where x.id<>v_customer_id
                  and regexp_replace(coalesce(x.cpf_cnpj,''),'[^0-9]','','g')=v_doc
              )
             then v_doc
             else cpf_cnpj end,
           is_active=true,updated_at=now()
     where id=v_customer_id;
  end if;

  if v_doc_valid then
    update public.customers
       set cpf_cnpj=case
         when nullif(regexp_replace(coalesce(cpf_cnpj,''),'[^0-9]','','g'),'') is null
          and not exists(
            select 1 from public.customers x
            where x.id<>v_customer_id
              and regexp_replace(coalesce(x.cpf_cnpj,''),'[^0-9]','','g')=v_doc
          )
         then v_doc else cpf_cnpj end,
           updated_at=now()
     where id=v_customer_id;
  end if;

  insert into public.customer_identity_profiles_v1(
    customer_id,identity_status,created_from,canonical_phone_e164,last_source_key,verified_at,metadata,updated_at
  ) values(
    v_customer_id,'verified_flow','papoai_flow',v_phone,coalesce(p_flow_token,v_event),now(),
    jsonb_strip_nulls(jsonb_build_object(
      'flow_capture_id',p_capture_id,'flow_token',p_flow_token,
      'document_received',nullif(v_doc,''),'document_valid',v_doc_valid,
      'provisional_merged',v_merged
    )),now()
  )
  on conflict(customer_id) do update set
    identity_status='verified_flow',
    canonical_phone_e164=excluded.canonical_phone_e164,
    last_source_key=excluded.last_source_key,
    verified_at=now(),
    metadata=coalesce(public.customer_identity_profiles_v1.metadata,'{}'::jsonb)||excluded.metadata,
    updated_at=now();

  -- User-submitted Flow data is treated as the latest confirmed delivery address.
  if v_street is not null or v_district is not null or v_city is not null then
    select id into v_address_id
    from public.customer_addresses
    where customer_id=v_customer_id and is_active=true
    order by is_default desc,last_confirmed_at desc nulls last,updated_at desc
    limit 1
    for update;

    if v_address_id is null then
      insert into public.customer_addresses(
        customer_id,label,street,number,neighborhood,city,state,is_default,is_active,last_confirmed_at,created_at,updated_at
      ) values(
        v_customer_id,'Entrega',v_street,null,v_district,v_city,v_state,true,true,now(),now(),now()
      )
      returning id into v_address_id;
    else
      update public.customer_addresses
         set street=coalesce(v_street,street),
             number=case when v_street is not null then null else number end,
             neighborhood=coalesce(v_district,neighborhood),
             city=coalesce(v_city,city),
             state=coalesce(v_state,state),
             is_default=true,is_active=true,last_confirmed_at=now(),updated_at=now()
       where id=v_address_id;
      update public.customer_addresses
         set is_default=false,updated_at=now()
       where customer_id=v_customer_id and id<>v_address_id and is_default=true;
    end if;
  end if;

  -- Conversation was normally resolved by the capture processor first.
  if p_capture_id is not null then
    begin
      select nullif(metadata->>'conversation_id','')::uuid,
             nullif(metadata->>'whatsapp_account_id','')::uuid
        into v_conversation_id,v_whatsapp_account_id
      from public.papoai_webhook_inbox_v2 where id=p_capture_id;
    exception when others then
      v_conversation_id:=null;v_whatsapp_account_id:=null;
    end;
  end if;

  if v_conversation_id is null and nullif(btrim(coalesce(p_conversation_ref,'')),'') is not null then
    select id,whatsapp_account_id into v_conversation_id,v_whatsapp_account_id
    from public.conversations
    where referral->>'papoai_session_uid'=p_conversation_ref
      and public.normalize_phone_digits(wa_contact_e164)=any(public.phone_variants_br(v_phone))
    order by updated_at desc limit 1;
  end if;

  if v_conversation_id is not null then
    update public.conversations
       set customer_id=v_customer_id,updated_at=now()
     where id=v_conversation_id
       and (customer_id is null or customer_id=v_customer_id
            or customer_id in (
              select ip.customer_id from public.customer_identity_profiles_v1 ip
              where ip.identity_status='merged' and ip.metadata->>'merged_into'=v_customer_id::text
            ));
  end if;

  -- Prefer the explicit order number that the site sent to PapoAI before the Flow.
  if p_capture_id is not null then
    select coalesce(i.payload#>>'{data,message,content}',i.payload#>>'{data,message,text}',i.payload#>>'{data,message,body}','')
      into v_prior_text
    from public.papoai_webhook_inbox_v2 i
    join public.papoai_webhook_inbox_v2 cur on cur.id=p_capture_id
    where i.received_at between cur.received_at-interval '24 hours' and cur.received_at
      and public.normalize_phone_digits(i.phone_candidate)=any(public.phone_variants_br(v_phone))
      and coalesce(i.payload#>>'{data,message,content}',i.payload#>>'{data,message,text}',i.payload#>>'{data,message,body}','') ~* '(?m)^NUMERO:\s*'
    order by i.received_at desc
    limit 1;

    v_order_suffix:=upper(nullif(substring(coalesce(v_prior_text,'') from '(?im)^NUMERO:\s*([A-Z0-9-]+)'),''));
  end if;

  if v_order_suffix is not null then
    select count(*),(array_agg(o.id order by o.created_at desc))[1]
      into v_order_count,v_order_id
    from public.orders o
    where o.source in ('vitrine','storefront_v2')
      and upper(right(coalesce(o.order_number,''),length(v_order_suffix)))=v_order_suffix
      and public.normalize_phone_digits(o.phone_e164)=any(public.phone_variants_br(v_phone))
      and (o.customer_id is null or o.customer_id=v_customer_id
           or o.customer_id in (
             select ip.customer_id from public.customer_identity_profiles_v1 ip
             where ip.identity_status='merged' and ip.metadata->>'merged_into'=v_customer_id::text
           ));
    if v_order_count<>1 then v_order_id:=null; end if;
  end if;

  if v_order_id is null and p_capture_id is not null then
    select count(*),(array_agg(o.id order by o.created_at desc))[1]
      into v_order_count,v_order_id
    from public.orders o
    join public.papoai_webhook_inbox_v2 cur on cur.id=p_capture_id
    where o.source in ('vitrine','storefront_v2')
      and o.created_at between cur.received_at-interval '6 hours' and cur.received_at+interval '15 minutes'
      and public.normalize_phone_digits(o.phone_e164)=any(public.phone_variants_br(v_phone))
      and (o.customer_id is null or o.customer_id=v_customer_id
           or o.customer_id in (
             select ip.customer_id from public.customer_identity_profiles_v1 ip
             where ip.identity_status='merged' and ip.metadata->>'merged_into'=v_customer_id::text
           ));
    if v_order_count<>1 then v_order_id:=null; end if;
  end if;

  if v_order_id is not null then
    update public.orders
       set customer_id=v_customer_id,
           conversation_id=coalesce(conversation_id,v_conversation_id),
           whatsapp_account_id=coalesce(whatsapp_account_id,v_whatsapp_account_id),
           phone_e164=v_phone,
           customer_snapshot=coalesce(customer_snapshot,'{}'::jsonb)
             || jsonb_strip_nulls(jsonb_build_object(
               'customer_id',v_customer_id,'name',v_name,'phone_e164',v_phone,
               'cpf_cnpj',case when v_doc_valid then v_doc else null end,
               'identity_status','verified_flow','papoai_flow_linked_at',now()
             )),
           delivery_address=coalesce(delivery_address,'{}'::jsonb)
             || jsonb_strip_nulls(jsonb_build_object(
               'source_customer_id',v_customer_id,'customer_name',v_name,'phone',v_phone,
               'street',v_street,'neighborhood',v_district,'city',v_city,'state',v_state
             )),
           updated_at=now()
     where id=v_order_id
     returning order_number into v_order_number;
    get diagnostics v_orders_linked=row_count;
  end if;

  begin perform public.refresh_customer_purchase_profile(v_customer_id); exception when others then null; end;

  select identity_status into v_profile_status
  from public.customer_identity_profiles_v1 where customer_id=v_customer_id;

  insert into public.papoai_customer_flow_events_v1(
    event_key,phone_e164,customer_id,conversation_id,customer_created,orders_linked,status,result
  ) values(
    v_event,v_phone,v_customer_id,v_conversation_id,v_created,v_orders_linked,'processed',
    jsonb_build_object(
      'ok',true,'customer_id',v_customer_id,'customer_created',v_created,
      'identity_status',v_profile_status,'conversation_id',v_conversation_id,
      'orders_linked',v_orders_linked,'order_id',v_order_id,'order_number',v_order_number,
      'document_valid',v_doc_valid,'address_saved',v_address_id is not null,
      'provisional_merged',v_merged,'external_order_created',false
    )
  );

  return jsonb_build_object(
    'ok',true,'duplicate',false,'event_key',v_event,'customer_id',v_customer_id,
    'customer_created',v_created,'identity_status',v_profile_status,
    'conversation_id',v_conversation_id,'orders_linked',v_orders_linked,
    'order_id',v_order_id,'order_number',v_order_number,
    'document_valid',v_doc_valid,'address_saved',v_address_id is not null,
    'provisional_merged',v_merged,'external_order_created',false
  );
end;
$function$
;

-- function: ops2_apply_virtual_stock_webhook_shadow_v1()
CREATE OR REPLACE FUNCTION public.ops2_apply_virtual_stock_webhook_shadow_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_enabled boolean := false;
  v_complex boolean := false;
  v_bling_id bigint;
  v_product_id uuid;
  v_link_count integer := 0;
  v_physical numeric;
  v_virtual numeric;
  v_deposits jsonb := '{}'::jsonb;
  v_apply jsonb;
begin
  if new.signature_verified is not true
     or new.resource <> 'virtual_stock'
     or new.action <> 'updated'
     or new.status not in ('held','received') then
    return new;
  end if;

  select coalesce(
    (jsonb_extract_path_text(r.metadata,'ops2_stock_mirror_events_enabled'))::boolean,
    false
  )
    into v_enabled
    from public.bling_hub_runtime_v2 r
   where r.id=1;

  if v_enabled is not true then
    return new;
  end if;

  v_complex := coalesce((new.payload->'data'->>'vinculoComplexo')::boolean,false);
  if v_complex then
    update public.bling_webhook_inbox_v2
       set result=jsonb_build_object(
             'classification','virtual_stock_complex_requires_api',
             'shadow_only',true,
             'local_product_stock_mutation',false,
             'external_write',false
           ),
           updated_at=now()
     where event_id=new.event_id;
    return new;
  end if;

  begin
    v_bling_id := nullif(new.provider_entity_id,'')::bigint;
  exception when others then
    v_bling_id := null;
  end;

  if coalesce(v_bling_id,0)<=0 then
    update public.bling_webhook_inbox_v2
       set status='review_required',
           last_error='virtual_stock_provider_id_missing',
           result=jsonb_build_object(
             'classification','virtual_stock_provider_id_missing',
             'shadow_only',true,
             'local_product_stock_mutation',false,
             'external_write',false
           ),
           processed_at=now(),
           updated_at=now()
     where event_id=new.event_id;
    return new;
  end if;

  select count(*)
    into v_link_count
    from public.bling_hub_entity_links_v2 l
   where l.source_system='vitrine_qx'
     and l.entity_type='product'
     and l.status='matched'
     and l.bling_id=v_bling_id;

  if v_link_count=1 then
    select l.source_id::uuid
      into v_product_id
      from public.bling_hub_entity_links_v2 l
     where l.source_system='vitrine_qx'
       and l.entity_type='product'
       and l.status='matched'
       and l.bling_id=v_bling_id
     limit 1;
  end if;

  if v_link_count<>1 or v_product_id is null then
    update public.bling_webhook_inbox_v2
       set status='review_required',
           last_error='virtual_stock_product_not_safely_linked',
           result=jsonb_build_object(
             'classification','virtual_stock_product_not_safely_linked',
             'bling_product_id',v_bling_id,
             'match_count',v_link_count,
             'shadow_only',true,
             'local_product_stock_mutation',false,
             'external_write',false
           ),
           processed_at=now(),
           updated_at=now()
     where event_id=new.event_id;
    return new;
  end if;

  begin
    v_physical := (new.payload->'data'->>'saldoFisicoTotal')::numeric;
    v_virtual := (new.payload->'data'->>'saldoVirtualTotal')::numeric;
  exception when others then
    v_physical := null;
    v_virtual := null;
  end;

  if v_physical is null or v_virtual is null then
    update public.bling_webhook_inbox_v2
       set status='review_required',
           last_error='virtual_stock_totals_invalid',
           result=jsonb_build_object(
             'classification','virtual_stock_totals_invalid',
             'bling_product_id',v_bling_id,
             'product_id',v_product_id,
             'shadow_only',true,
             'local_product_stock_mutation',false,
             'external_write',false
           ),
           processed_at=now(),
           updated_at=now()
     where event_id=new.event_id;
    return new;
  end if;

  select coalesce(
           jsonb_object_agg(
             d.item->>'id',
             jsonb_build_object(
               'physical',coalesce((d.item->>'saldoFisico')::numeric,0),
               'virtual',coalesce((d.item->>'saldoVirtual')::numeric,0)
             )
           ),
           '{}'::jsonb
         )
    into v_deposits
    from jsonb_array_elements(coalesce(new.payload->'data'->'depositos','[]'::jsonb)) as d(item)
   where nullif(d.item->>'id','') is not null;

  select public.apply_bling_stock_mirror_event_v2(
    v_product_id,
    v_bling_id,
    v_physical,
    v_virtual,
    v_deposits,
    coalesce(new.event_at,new.received_at,now()),
    new.event_id,
    'virtual_stock',
    true
  )
    into v_apply;

  update public.bling_webhook_inbox_v2
     set status='processed',
         result=jsonb_build_object(
           'classification',
             case when coalesce((v_apply->>'applied')::boolean,false)
               then 'stock_mirror_applied'
               else 'stock_mirror_stale_ignored'
             end,
           'mirror',v_apply,
           'shadow_only',true,
           'local_product_stock_mutation',false,
           'external_write',false,
           'processing_path','db_trigger'
         ),
         last_error=null,
         processed_at=now(),
         updated_at=now()
   where event_id=new.event_id;

  insert into public.bling_hub_audit_v2(
    event_type,severity,domain,source_system,source_id,details
  )
  values(
    'virtual_stock_shadow_applied',
    'info',
    'stock',
    'bling_webhook',
    new.event_id,
    jsonb_build_object(
      'bling_product_id',v_bling_id,
      'product_id',v_product_id,
      'physical_total',v_physical,
      'virtual_total',v_virtual,
      'stale_ignored',coalesce((v_apply->>'stale_ignored')::boolean,false),
      'shadow_only',true,
      'local_product_stock_mutation',false,
      'external_write',false
    )
  );

  return new;
end
$function$
;

-- function: ops2_arm_catalog_stock_canary_band_v1(p_canary uuid, p_band integer, p_confirmation text)
CREATE OR REPLACE FUNCTION public.ops2_arm_catalog_stock_canary_band_v1(p_canary uuid, p_band integer, p_confirmation text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_count int; v_status text; v_cap int;
begin
  if p_band<2 or p_band>10 then raise exception 'unsupported_auto_band'; end if;
  if p_confirmation<>('ARMAR_CANARIO_ESTOQUE_BLING_DELTA_'||p_band::text) then raise exception 'confirmation_required'; end if;
  v_cap:=case when p_band<=5 then 5 else 3 end;

  select status,item_count into v_status,v_count
  from public.ops2_catalog_sync_canaries where id=p_canary for update;
  if not found then raise exception 'canary_not_found'; end if;
  if v_status<>'prepared' then raise exception 'canary_not_prepared'; end if;
  if v_count<1 or v_count>v_cap then raise exception 'invalid_canary_size'; end if;
  if exists(select 1 from public.ops2_catalog_sync_canary_items where canary_id=p_canary and abs(delta)<>p_band) then raise exception 'wrong_risk_band'; end if;
  if exists(
    select 1 from public.ops2_catalog_sync_canary_items i
    join public.products p on p.id=i.product_id
    where i.canary_id=p_canary and p.stock is distinct from i.desired_stock
  ) then raise exception 'live_supabase_stock_drift'; end if;

  update public.ops2_catalog_sync_canaries
     set status='armed',external_write_enabled=true,risk_band=p_band
   where id=p_canary;
  return jsonb_build_object('ok',true,'canary_id',p_canary,'status','armed','item_count',v_count,'risk_band',p_band,'live_stock_guard',true);
end $function$
;

-- function: ops2_arm_catalog_stock_canary_delta2_v1(p_canary uuid, p_confirmation text)
CREATE OR REPLACE FUNCTION public.ops2_arm_catalog_stock_canary_delta2_v1(p_canary uuid, p_confirmation text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_count int;v_status text;
begin
 if p_confirmation<>'ARMAR_CANARIO_ESTOQUE_BLING_DELTA2' then raise exception 'confirmation_required';end if;
 select status,item_count into v_status,v_count from public.ops2_catalog_sync_canaries where id=p_canary for update;
 if not found then raise exception 'canary_not_found';end if;
 if v_status<>'prepared' then raise exception 'canary_not_prepared';end if;
 if v_count<1 or v_count>5 then raise exception 'invalid_canary_size';end if;
 if exists(select 1 from public.ops2_catalog_sync_canary_items where canary_id=p_canary and abs(delta)>2) then raise exception 'delta_too_large';end if;
 if exists(select 1 from public.ops2_catalog_sync_canary_items i join public.products p on p.id=i.product_id where i.canary_id=p_canary and p.stock is distinct from i.desired_stock) then raise exception 'live_supabase_stock_drift';end if;
 update public.ops2_catalog_sync_canaries set status='armed',external_write_enabled=true where id=p_canary;
 return jsonb_build_object('ok',true,'canary_id',p_canary,'status','armed','item_count',v_count,'max_abs_delta',2,'live_stock_guard',true);
end $function$
;

-- function: ops2_arm_catalog_stock_canary_highrisk_v1(p_canary uuid, p_band integer, p_confirmation text)
CREATE OR REPLACE FUNCTION public.ops2_arm_catalog_stock_canary_highrisk_v1(p_canary uuid, p_band integer, p_confirmation text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_count int; v_status text;
begin
  if p_band<11 or p_band>20 then raise exception 'unsupported_highrisk_band'; end if;
  if p_confirmation<>('ARMAR_CANARIO_ESTOQUE_BLING_ALTO_RISCO_DELTA_'||p_band::text) then raise exception 'confirmation_required'; end if;
  select status,item_count into v_status,v_count from public.ops2_catalog_sync_canaries where id=p_canary for update;
  if not found then raise exception 'canary_not_found'; end if;
  if v_status<>'prepared' then raise exception 'canary_not_prepared'; end if;
  if v_count<>1 then raise exception 'highrisk_requires_singleton'; end if;
  if exists(select 1 from public.ops2_catalog_sync_canary_items where canary_id=p_canary and abs(delta)<>p_band) then raise exception 'wrong_risk_band'; end if;
  if exists(
    select 1 from public.ops2_catalog_sync_canary_items i
    join public.products p on p.id=i.product_id
    where i.canary_id=p_canary and p.stock is distinct from i.desired_stock
  ) then raise exception 'live_supabase_stock_drift'; end if;
  update public.ops2_catalog_sync_canaries
     set status='armed',external_write_enabled=true,risk_band=p_band
   where id=p_canary;
  return jsonb_build_object('ok',true,'canary_id',p_canary,'status','armed','item_count',v_count,'risk_band',p_band,'singleton',true,'live_stock_guard',true);
end $function$
;

-- function: ops2_arm_catalog_stock_canary_v1(p_canary uuid, p_confirmation text)
CREATE OR REPLACE FUNCTION public.ops2_arm_catalog_stock_canary_v1(p_canary uuid, p_confirmation text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_count int; v_status text;
begin
 if p_confirmation <> 'ARMAR_CANARIO_ESTOQUE_BLING' then raise exception 'confirmation_required'; end if;
 select status,item_count into v_status,v_count from ops2_catalog_sync_canaries where id=p_canary for update;
 if not found then raise exception 'canary_not_found'; end if;
 if v_status <> 'prepared' then raise exception 'canary_not_prepared'; end if;
 if v_count < 1 or v_count > 5 then raise exception 'invalid_canary_size'; end if;
 if exists(select 1 from ops2_catalog_sync_canary_items where canary_id=p_canary and abs(delta)>1) then raise exception 'delta_too_large'; end if;
 if exists(
   select 1
   from ops2_catalog_sync_canary_items i
   join products p on p.id=i.product_id
   where i.canary_id=p_canary
     and p.stock is distinct from i.desired_stock
 ) then raise exception 'live_supabase_stock_drift'; end if;
 update ops2_catalog_sync_canaries set status='armed',external_write_enabled=true where id=p_canary;
 return jsonb_build_object('ok',true,'canary_id',p_canary,'status','armed','item_count',v_count,'live_stock_guard',true);
end $function$
;

-- function: ops2_attendance_ai_gate_v1(p_conversation_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_attendance_ai_gate_v1(p_conversation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_conversation public.conversations%rowtype;
begin
  if p_conversation_id is null then return jsonb_build_object('ok',false,'error','conversation_required','allowed',false); end if;
  select c.* into v_conversation from public.conversations c where c.id=p_conversation_id;
  if not found then return jsonb_build_object('ok',false,'error','conversation_not_found','allowed',false); end if;
  return jsonb_build_object('ok',true,'allowed',v_conversation.mode='ai' and v_conversation.human_required=false,'mode',v_conversation.mode,'human_required',v_conversation.human_required,'updated_at',v_conversation.updated_at);
end;$function$
;

-- function: ops2_attendance_delivery_date_v1(p_value text)
CREATE OR REPLACE FUNCTION public.ops2_attendance_delivery_date_v1(p_value text)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_date date;
begin
  if p_value is null or p_value !~ '^\d{4}-\d{2}-\d{2}$' then return null; end if;
  begin
    v_date:=p_value::date;
  exception when others then
    return null;
  end;
  return v_date;
end;
$function$
;

-- function: ops2_attendance_media_live_readiness_v1(p_whatsapp_account_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_attendance_media_live_readiness_v1(p_whatsapp_account_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_runtime public.whatsapp_channel_runtime_v1%rowtype;
  v_image_count integer:=0;
  v_audio_count integer:=0;
  v_document_count integer:=0;
  v_duplicate_wamid_count integer:=0;
  v_unhealthy_queue_count integer:=0;
  v_ready boolean:=false;
begin
  if p_whatsapp_account_id is null then
    return jsonb_build_object('ok',false,'ready',false,'error','whatsapp_account_required');
  end if;

  select r.* into v_runtime
  from public.whatsapp_channel_runtime_v1 r
  where r.whatsapp_account_id=p_whatsapp_account_id
    and r.send_enabled=true
    and r.human_send_enabled=true
    and r.homologated_at is not null
    and r.outbound_provider='meta';

  if not found then
    return jsonb_build_object('ok',true,'ready',false,'reason','human_send_not_homologated');
  end if;

  with evidence as (
    select o.message_type,o.provider_message_id
    from public.whatsapp_outbox_v1 o
    join public.whatsapp_messages_v1 m on m.id=o.message_id
    where o.whatsapp_account_id=p_whatsapp_account_id
      and o.purpose='human_attendance'
      and o.provider='meta'
      and o.message_type in ('image','audio','document')
      and o.status='sent'
      and o.provider_message_id is not null
      and m.provider='meta'
      and m.direction='outbound'
      and m.provider_message_id=o.provider_message_id
      and m.status_current in ('sent','delivered','read')
      and lower(coalesce(o.metadata->>'meta_media_canary',o.metadata->>'meta_canary','false'))='true'
      and exists (
        select 1
        from jsonb_array_elements_text(
          case
            when jsonb_typeof(v_runtime.metadata->'meta_media_canary_to_e164')='array'
              then v_runtime.metadata->'meta_media_canary_to_e164'
            else '[]'::jsonb
          end
        ) allowed(value)
        where public.canonical_whatsapp_e164_br_v2(allowed.value)
              = public.canonical_whatsapp_e164_br_v2(o.to_phone_e164)
      )
  )
  select
    count(*) filter (where message_type='image')::integer,
    count(*) filter (where message_type='audio')::integer,
    count(*) filter (where message_type='document')::integer
  into v_image_count,v_audio_count,v_document_count
  from evidence;

  select count(*)::integer into v_duplicate_wamid_count
  from (
    select o.provider_message_id
    from public.whatsapp_outbox_v1 o
    where o.whatsapp_account_id=p_whatsapp_account_id
      and o.purpose='human_attendance'
      and o.provider='meta'
      and o.message_type in ('image','audio','document')
      and o.status='sent'
      and o.provider_message_id is not null
      and lower(coalesce(o.metadata->>'meta_media_canary',o.metadata->>'meta_canary','false'))='true'
      and exists (
        select 1
        from jsonb_array_elements_text(
          case
            when jsonb_typeof(v_runtime.metadata->'meta_media_canary_to_e164')='array'
              then v_runtime.metadata->'meta_media_canary_to_e164'
            else '[]'::jsonb
          end
        ) allowed(value)
        where public.canonical_whatsapp_e164_br_v2(allowed.value)
              = public.canonical_whatsapp_e164_br_v2(o.to_phone_e164)
      )
    group by o.provider_message_id
    having count(*)>1
  ) duplicated;

  select count(*)::integer into v_unhealthy_queue_count
  from public.whatsapp_outbox_v1 o
  where o.whatsapp_account_id=p_whatsapp_account_id
    and o.purpose='human_attendance'
    and o.provider='meta'
    and o.message_type in ('image','audio','document')
    and o.status in ('queued','claimed','failed')
    and o.created_at>=now()-interval '24 hours';

  v_ready:=
    lower(coalesce(v_runtime.metadata->>'meta_media_canary_enabled','false'))='true'
    and v_image_count>0
    and v_audio_count>0
    and v_document_count>0
    and v_duplicate_wamid_count=0
    and v_unhealthy_queue_count=0;

  return jsonb_build_object(
    'ok',true,
    'ready',v_ready,
    'evidence',jsonb_build_object(
      'image',v_image_count,
      'audio',v_audio_count,
      'document',v_document_count,
      'duplicate_wamid',v_duplicate_wamid_count,
      'unhealthy_queue_24h',v_unhealthy_queue_count
    ),
    'requires',jsonb_build_array(
      'strict_media_canary_enabled',
      'image_meta_canary_with_wamid_and_status',
      'audio_meta_canary_with_wamid_and_status',
      'document_meta_canary_with_wamid_and_status',
      'no_duplicate_wamid',
      'clean_media_queue_24h'
    )
  );
end;
$function$
;

-- function: ops2_attendance_orders_refresh_delivery_labels_trigger_v1()
CREATE OR REPLACE FUNCTION public.ops2_attendance_orders_refresh_delivery_labels_trigger_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op='INSERT' then
    if new.conversation_id is not null then
      perform public.ops2_attendance_refresh_delivery_day_labels_v1(new.conversation_id);
    end if;
    return new;
  elsif tg_op='DELETE' then
    if old.conversation_id is not null then
      perform public.ops2_attendance_refresh_delivery_day_labels_v1(old.conversation_id);
    end if;
    return old;
  end if;

  if old.conversation_id is distinct from new.conversation_id and old.conversation_id is not null then
    perform public.ops2_attendance_refresh_delivery_day_labels_v1(old.conversation_id);
  end if;
  if new.conversation_id is not null then
    perform public.ops2_attendance_refresh_delivery_day_labels_v1(new.conversation_id);
  end if;
  return new;
end;
$function$
;

-- function: ops2_attendance_outbox_human_ai_guard_v1()
CREATE OR REPLACE FUNCTION public.ops2_attendance_outbox_human_ai_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_conversation public.conversations%rowtype; v_before text;
begin
  if new.conversation_id is null then return new; end if;
  if tg_op='INSERT' and new.purpose='human_attendance' then
    select c.* into v_conversation from public.conversations c where c.id=new.conversation_id for update;
    if not found then raise exception 'conversation_not_found'; end if;
    v_before:=v_conversation.mode;
    if v_conversation.mode<>'human' or v_conversation.human_required=false then
      update public.conversations set mode='human',human_required=true,human_takeover_at=case when mode='human' then coalesce(human_takeover_at,now()) else now() end,ai_resume_at=null,updated_at=now() where id=new.conversation_id;
      insert into public.attendance_human_ai_audit_v1(conversation_id,action,from_mode,to_mode,source,metadata) values (new.conversation_id,'human_outbox_takeover',v_before,'human','outbox',jsonb_build_object('outbox_id',new.id));
    end if;
    return new;
  end if;
  if new.purpose='ai_attendance' and (tg_op='INSERT' or (tg_op='UPDATE' and old.status='queued' and new.status='claimed')) then
    select c.* into v_conversation from public.conversations c where c.id=new.conversation_id for update;
    if not found then raise exception 'conversation_not_found'; end if;
    if v_conversation.mode<>'ai' or v_conversation.human_required=true then raise exception 'ai_blocked_by_human_takeover'; end if;
  end if;
  return new;
end;$function$
;

-- function: ops2_attendance_product_interest_item_trigger_v1()
CREATE OR REPLACE FUNCTION public.ops2_attendance_product_interest_item_trigger_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op='DELETE' then
    perform public.ops2_attendance_refresh_product_interest_labels_v1(old.order_id);
    return old;
  end if;
  perform public.ops2_attendance_refresh_product_interest_labels_v1(new.order_id);
  if tg_op='UPDATE' and old.order_id is distinct from new.order_id then
    perform public.ops2_attendance_refresh_product_interest_labels_v1(old.order_id);
  end if;
  return new;
end;
$function$
;

-- function: ops2_attendance_product_interest_order_trigger_v1()
CREATE OR REPLACE FUNCTION public.ops2_attendance_product_interest_order_trigger_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op='DELETE' then
    perform public.ops2_attendance_refresh_product_interest_labels_v1(old.id);
    return old;
  end if;
  perform public.ops2_attendance_refresh_product_interest_labels_v1(new.id);
  if tg_op='UPDATE' and old.id is distinct from new.id then
    perform public.ops2_attendance_refresh_product_interest_labels_v1(old.id);
  end if;
  return new;
end;
$function$
;

-- function: ops2_attendance_refresh_delivery_day_labels_v1(p_conversation_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_attendance_refresh_delivery_day_labels_v1(p_conversation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_created integer:=0;
  v_removed integer:=0;
begin
  if p_conversation_id is null or not exists (
    select 1 from public.conversations c where c.id=p_conversation_id
  ) then
    return jsonb_build_object('ok',false,'error','conversation_not_found');
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_conversation_id::text,6801));

  delete from public.attendance_conversation_auto_labels_v1 a
  where a.conversation_id=p_conversation_id and a.source_kind='delivery_schedule';
  get diagnostics v_removed = row_count;

  insert into public.attendance_conversation_auto_labels_v1(conversation_id,label_id,source_kind,source_ref)
  select distinct o.conversation_id,l.id,'delivery_schedule',o.id
  from public.orders o
  cross join lateral (
    select public.ops2_attendance_delivery_date_v1(
      coalesce(
        nullif(btrim(o.delivery_address->>'delivery_date'),''),
        nullif(btrim(o.checkout_snapshot->'delivery'->>'date'),'')
      )
    ) as delivery_date
  ) d
  cross join lateral (
    select case extract(isodow from d.delivery_date)::integer
      when 1 then 'Segunda'
      when 2 then 'Terça'
      when 3 then 'Quarta'
      when 4 then 'Quinta'
      when 5 then 'Sexta'
      when 6 then 'Sábado'
      when 7 then 'Domingo'
    end as label_name
  ) w
  join public.attendance_labels_v1 l
    on lower(btrim(l.name))=lower(btrim(w.label_name)) and l.is_active=true
  where o.conversation_id=p_conversation_id
    and o.status in ('storefront_received','confirmed','processing','ready')
    and d.delivery_date >= (now() at time zone 'America/Cuiaba')::date
  on conflict (conversation_id,label_id,source_kind,source_ref) do nothing;
  get diagnostics v_created = row_count;

  delete from public.attendance_conversation_labels_v1 current_label
  where current_label.conversation_id=p_conversation_id
    and not exists (
      select 1 from public.attendance_conversation_manual_labels_v1 manual_label
      where manual_label.conversation_id=current_label.conversation_id
        and manual_label.label_id=current_label.label_id
    )
    and not exists (
      select 1 from public.attendance_conversation_auto_labels_v1 auto_label
      where auto_label.conversation_id=current_label.conversation_id
        and auto_label.label_id=current_label.label_id
    );

  insert into public.attendance_conversation_labels_v1(conversation_id,label_id)
  select p_conversation_id,owned.label_id
  from (
    select label_id from public.attendance_conversation_manual_labels_v1
    where conversation_id=p_conversation_id
    union
    select label_id from public.attendance_conversation_auto_labels_v1
    where conversation_id=p_conversation_id
  ) owned
  on conflict (conversation_id,label_id) do nothing;

  return jsonb_build_object('ok',true,'conversation_id',p_conversation_id,'automatic_sources',v_created,'stale_sources_removed',v_removed);
end;
$function$
;

-- function: ops2_attendance_refresh_product_interest_labels_v1(p_order_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_attendance_refresh_product_interest_labels_v1(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_order public.orders%rowtype;
  v_label_id uuid;
  v_changed integer:=0;
  v_order_found boolean:=false;
  v_customer_id uuid;
  v_customer_ids uuid[]:='{}'::uuid[];
begin
  if p_order_id is null then return jsonb_build_object('ok',false,'error','order_required'); end if;
  select * into v_order from public.orders where id=p_order_id;
  v_order_found:=found;

  select coalesce(array_agg(distinct cv.customer_id) filter(where cv.customer_id is not null),'{}'::uuid[])
    into v_customer_ids
  from public.attendance_conversation_auto_labels_v1 a
  join public.conversations cv on cv.id=a.conversation_id
  where a.source_kind='product_purchase' and a.source_ref=p_order_id;
  if v_order_found and v_order.customer_id is not null then
    v_customer_ids:=array_append(v_customer_ids,v_order.customer_id);
  end if;
  if coalesce(array_length(v_customer_ids,1),0)=0 then
    perform pg_advisory_xact_lock(hashtextextended('attendance:product-interest:order:'||p_order_id::text,6802));
  else
    foreach v_customer_id in array v_customer_ids loop
      perform pg_advisory_xact_lock(hashtextextended('attendance:product-interest:'||v_customer_id::text,6802));
    end loop;
  end if;

  select id into v_label_id
  from public.attendance_labels_v1
  where lower(btrim(name))=lower('Comprou: cuidados femininos') and is_active=true
  order by created_at,id limit 1;

  delete from public.attendance_conversation_auto_labels_v1
  where source_kind='product_purchase' and source_ref=p_order_id;

  if v_order_found
     and v_order.customer_id is not null
     and v_order.status in ('confirmed','processing','ready','delivered')
     and v_order.cancelled_at is null
     and v_order.returned_at is null
     and v_label_id is not null then
    insert into public.attendance_conversation_auto_labels_v1(conversation_id,label_id,source_kind,source_ref)
    select distinct cv.id,v_label_id,'product_purchase',v_order.id
    from public.conversations cv
    where cv.customer_id=v_order.customer_id
      and exists(
        select 1
        from public.order_items oi
        join public.products p on p.id=oi.product_id
        where oi.order_id=v_order.id
          and lower(btrim(coalesce(p.customer_subsubcategory,'')))='cuidados femininos'
          and lower(coalesce(p.customer_taxonomy_confidence,''))='high'
          and lower(coalesce(p.customer_taxonomy_review_status,'')) in ('reviewed','auto_classified')
      )
    on conflict(conversation_id,label_id,source_kind,source_ref) do nothing;
    get diagnostics v_changed=row_count;
  end if;

  foreach v_customer_id in array v_customer_ids loop
    delete from public.attendance_conversation_labels_v1 current_label
    using public.conversations cv
    where cv.id=current_label.conversation_id and cv.customer_id=v_customer_id
      and not exists(select 1 from public.attendance_conversation_manual_labels_v1 m where m.conversation_id=current_label.conversation_id and m.label_id=current_label.label_id)
      and not exists(select 1 from public.attendance_conversation_auto_labels_v1 a where a.conversation_id=current_label.conversation_id and a.label_id=current_label.label_id);

    insert into public.attendance_conversation_labels_v1(conversation_id,label_id)
    select cv.id,owned.label_id
    from public.conversations cv
    cross join lateral (
      select label_id from public.attendance_conversation_manual_labels_v1 where conversation_id=cv.id
      union
      select label_id from public.attendance_conversation_auto_labels_v1 where conversation_id=cv.id
    ) owned
    where cv.customer_id=v_customer_id
    on conflict(conversation_id,label_id) do nothing;
  end loop;

  return jsonb_build_object('ok',true,'order_id',p_order_id,'labels_added',v_changed);
end;
$function$
;

-- function: ops2_auto_process_papoai_flow_v2()
CREATE OR REPLACE FUNCTION public.ops2_auto_process_papoai_flow_v2()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_text text;
begin
  if new.status='normalized'
     and old.status is distinct from new.status
     and new.event_name='message.received'
  then
    v_text:=coalesce(new.payload#>>'{data,message,content}',new.payload#>>'{data,message,text}',new.payload#>>'{data,message,body}','');
    if v_text ~* '(?m)^flow_token\s*:' then
      perform public.ops2_process_papoai_flow_capture_v2(new.id);
    end if;
  end if;
  return new;
end;
$function$
;

-- function: ops2_bling_stock_worker_health_summary_v1()
CREATE OR REPLACE FUNCTION public.ops2_bling_stock_worker_health_summary_v1()
 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO 'public'
AS $function$
 select jsonb_build_object(
  'processing',processing,'stale_90s',stale_90s,'retry',retry,'review_required',review_required,
  'oldest_processing_at',oldest_processing_at,'last_stock_job_at',last_stock_job_at,
  'healthy',(stale_90s=0 and retry=0)
 ) from public.ops2_bling_stock_worker_health_v1;
$function$
;

-- function: ops2_build_catalog_sync_plan_v1(p_run uuid)
CREATE OR REPLACE FUNCTION public.ops2_build_catalog_sync_plan_v1(p_run uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
 if not exists(select 1 from ops2_catalog_baseline_runs where id=p_run and status='captured') then raise exception 'baseline_not_captured'; end if;
 delete from ops2_catalog_sync_plan_items where run_id=p_run;
 insert into ops2_catalog_sync_plan_items(run_id,product_id,bling_product_id,operation,desired_stock,current_bling_physical,desired_sale_price,state,reason)
 select run_id,product_id,bling_product_id,
 case when identity_state<>'unique_mirror_identity' then 'identity_review'
      when stock is distinct from bling_physical_before then 'stock_update'
      else 'noop' end,
 stock,bling_physical_before,sale_price,
 case when identity_state<>'unique_mirror_identity' then 'blocked' else 'planned' end,
 case when identity_state<>'unique_mirror_identity' then identity_state
      when stock is distinct from bling_physical_before then 'supabase_transition_baseline_diff'
      else 'already_aligned' end
 from ops2_catalog_baseline_items where run_id=p_run and bling_product_id is not null;
 update ops2_catalog_baseline_runs set status='planned' where id=p_run;
 return (select jsonb_build_object('run_id',p_run,'items',count(*),'stock_updates',count(*) filter(where operation='stock_update'),'noop',count(*) filter(where operation='noop'),'blocked',count(*) filter(where state='blocked')) from ops2_catalog_sync_plan_items where run_id=p_run);
end $function$
;

-- function: ops2_capture_catalog_baseline_v1(p_notes text)
CREATE OR REPLACE FUNCTION public.ops2_capture_catalog_baseline_v1(p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_run uuid;
begin
 insert into ops2_catalog_baseline_runs(notes) values(p_notes) returning id into v_run;
 insert into ops2_catalog_baseline_items(run_id,product_id,bling_product_id,sku,gtin,is_active,sale_price,stock,bling_physical_before,bling_virtual_before,bling_observed_at,identity_state)
 select v_run,p.id,m.bling_product_id,p.sku,p.gtin,p.is_active,p.price,p.stock,m.physical_total,m.virtual_total,m.observed_at,
 case when m.bling_product_id is null then 'missing'
      when count(*) over(partition by m.bling_product_id)>1 then 'duplicate_bling_id'
      else 'unique_mirror_identity' end
 from products p left join bling_stock_mirror_v2 m on m.product_id=p.id
 where p.is_active is true;
 update ops2_catalog_baseline_runs set product_count=(select count(*) from ops2_catalog_baseline_items where run_id=v_run) where id=v_run;
 return v_run;
end $function$
;

-- function: ops2_check_stock_cutover_canary_v1(p_run_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_check_stock_cutover_canary_v1(p_run_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_run public.ops2_stock_cutover_runs%rowtype;
  v_authority text;
  v_bad integer;
  v_result jsonb;
begin
  select * into v_run from public.ops2_stock_cutover_runs where id=p_run_id for update;
  if not found then raise exception 'cutover_run_not_found'; end if;
  select coalesce(metadata->>'ops2_stock_authority','legacy_shadow') into v_authority
    from public.bling_hub_runtime_v2 where id=1;
  select count(*) into v_bad from public.ops2_sellable_stock_v1
    where stock_authority<>'supabase' or effective_sellable_stock<0;
  v_result:=jsonb_build_object('authority',v_authority,'stock_source','supabase.products.stock',
    'invalid_stock_rows',v_bad,'healthy',v_authority='supabase' and v_bad=0);
  update public.ops2_stock_cutover_runs set checked_at=now(),check_result=v_result,
    status=case when coalesce((v_result->>'healthy')::boolean,false) then 'passed' else status end,updated_at=now()
  where id=p_run_id;
  return v_result;
end;
$function$
;

-- function: ops2_claim_checkout_order_whatsapp_v1(p_order_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_claim_checkout_order_whatsapp_v1(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_runtime_mode text;
  v_canary_order_id uuid;
  v_item public.ops2_whatsapp_outbox_v1%rowtype;
begin
  if p_order_id is null then return jsonb_build_object('ok',false,'error','order_id_required'); end if;

  select r.mode,r.canary_order_id into v_runtime_mode,v_canary_order_id
  from public.ops2_whatsapp_order_runtime_v1 r where r.id=1;
  v_runtime_mode:=coalesce(v_runtime_mode,'off');

  if v_runtime_mode='off' then
    return jsonb_build_object('ok',true,'found',false,'reason','runtime_off');
  end if;
  if v_runtime_mode='canary' and p_order_id is distinct from v_canary_order_id then
    return jsonb_build_object('ok',true,'found',false,'reason','not_canary_order');
  end if;

  update public.ops2_whatsapp_outbox_v1
     set status='retry',locked_at=null,updated_at=now(),last_error=coalesce(last_error,'stale_sending_recovered')
   where order_id=p_order_id and recipient_kind='customer'
     and status='sending' and locked_at<now()-interval '15 minutes' and attempt_count<5;

  with next_item as (
    select q.id from public.ops2_whatsapp_outbox_v1 q
    where q.order_id=p_order_id and q.recipient_kind='customer'
      and q.status in ('pending','retry') and q.delivery_mode='utility_template'
      and q.available_at<=now() and q.attempt_count<5
    order by q.available_at,q.created_at
    for update skip locked limit 1
  )
  update public.ops2_whatsapp_outbox_v1 q
     set status='sending',attempt_count=q.attempt_count+1,locked_at=now(),updated_at=now(),last_error=null
    from next_item n where q.id=n.id
  returning q.* into v_item;

  if not found then return jsonb_build_object('ok',true,'found',false); end if;
  return jsonb_build_object('ok',true,'found',true,'item',to_jsonb(v_item));
end;
$function$
;

-- function: ops2_claim_order_whatsapp_outbox_v1(p_order_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_claim_order_whatsapp_outbox_v1(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_item public.ops2_whatsapp_outbox_v1%rowtype;
begin
  if p_order_id is null then
    return jsonb_build_object('ok',false,'error','order_id_required');
  end if;

  update public.ops2_whatsapp_outbox_v1
     set status='retry',locked_at=null,updated_at=now(),last_error=coalesce(last_error,'stale_sending_recovered')
   where order_id=p_order_id
     and status='sending'
     and locked_at<now()-interval '15 minutes'
     and attempt_count<5;

  with next_item as (
    select q.id
    from public.ops2_whatsapp_outbox_v1 q
    where q.order_id=p_order_id
      and q.status in ('pending','retry')
      and q.delivery_mode='utility_template'
      and q.available_at<=now()
      and q.attempt_count<5
    order by case q.recipient_kind when 'customer' then 0 else 1 end,q.created_at
    for update skip locked
    limit 1
  )
  update public.ops2_whatsapp_outbox_v1 q
     set status='sending',attempt_count=q.attempt_count+1,locked_at=now(),updated_at=now(),last_error=null
    from next_item n
   where q.id=n.id
  returning q.* into v_item;

  if not found then
    return jsonb_build_object('ok',true,'found',false);
  end if;
  return jsonb_build_object('ok',true,'found',true,'item',to_jsonb(v_item));
end;
$function$
;

-- function: ops2_claim_papoai_order_signal_v1()
CREATE OR REPLACE FUNCTION public.ops2_claim_papoai_order_signal_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_mode text; v_canary uuid; v_item public.ops2_papoai_order_signal_outbox_v1%rowtype;
begin
  select mode,canary_order_id into v_mode,v_canary from public.ops2_papoai_order_signal_runtime_v1 where id=1;
  v_mode:=coalesce(v_mode,'off');
  if v_mode='off' then return jsonb_build_object('ok',true,'found',false,'reason','runtime_off'); end if;
  update public.ops2_papoai_order_signal_outbox_v1 set status='retry',locked_at=null,updated_at=now(),last_error=coalesce(last_error,'stale_sending_recovered')
    where status='sending' and locked_at<now()-interval '15 minutes' and attempt_count<5
      and (v_mode='live' or order_id=v_canary);
  with next_item as (
    select id from public.ops2_papoai_order_signal_outbox_v1
    where status in ('pending','retry') and available_at<=now() and attempt_count<5
      and (v_mode='live' or order_id=v_canary)
    order by available_at,created_at for update skip locked limit 1
  )
  update public.ops2_papoai_order_signal_outbox_v1 q set status='sending',attempt_count=q.attempt_count+1,locked_at=now(),updated_at=now(),last_error=null
    from next_item n where q.id=n.id returning q.* into v_item;
  if not found then return jsonb_build_object('ok',true,'found',false); end if;
  return jsonb_build_object('ok',true,'found',true,'item',to_jsonb(v_item));
end $function$
;

-- function: ops2_claim_whatsapp_outbox_v1(p_channel_origin text)
CREATE OR REPLACE FUNCTION public.ops2_claim_whatsapp_outbox_v1(p_channel_origin text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_item public.ops2_whatsapp_outbox_v1%rowtype;
  v_channel text:=nullif(btrim(coalesce(p_channel_origin,'')),'');
  v_runtime_mode text;
  v_canary_order_id uuid;
begin
  select r.mode,r.canary_order_id
    into v_runtime_mode,v_canary_order_id
  from public.ops2_whatsapp_order_runtime_v1 r
  where r.id=1;

  v_runtime_mode:=coalesce(v_runtime_mode,'off');

  if v_runtime_mode='off' then
    return jsonb_build_object('ok',true,'found',false,'reason','runtime_off');
  end if;

  if v_runtime_mode='canary' and v_canary_order_id is null then
    return jsonb_build_object('ok',true,'found',false,'reason','canary_order_missing');
  end if;

  update public.ops2_whatsapp_outbox_v1
     set status='retry',
         locked_at=null,
         updated_at=now(),
         last_error=coalesce(last_error,'stale_sending_recovered')
   where status='sending'
     and locked_at < now()-interval '15 minutes'
     and attempt_count < 5
     and (v_runtime_mode='live' or order_id=v_canary_order_id);

  with next_item as (
    select q.id
    from public.ops2_whatsapp_outbox_v1 q
    where q.status in ('pending','retry')
      and q.delivery_mode='utility_template'
      and q.available_at <= now()
      and q.attempt_count < 5
      and (v_channel is null or q.channel_origin=v_channel)
      and (v_runtime_mode='live' or q.order_id=v_canary_order_id)
    order by q.available_at,q.created_at
    for update skip locked
    limit 1
  )
  update public.ops2_whatsapp_outbox_v1 q
     set status='sending',
         attempt_count=q.attempt_count+1,
         locked_at=now(),
         updated_at=now(),
         last_error=null
    from next_item n
   where q.id=n.id
  returning q.* into v_item;

  if not found then
    return jsonb_build_object('ok',true,'found',false);
  end if;

  return jsonb_build_object('ok',true,'found',true,'item',to_jsonb(v_item));
end;
$function$
;

-- function: ops2_consume_order_registration_link_v1(p_token text, p_customer_id uuid, p_phone text)
CREATE OR REPLACE FUNCTION public.ops2_consume_order_registration_link_v1(p_token text, p_customer_id uuid, p_phone text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_hash text;
  v_link public.ops2_order_registration_links_v1%rowtype;
  v_order public.orders%rowtype;
  v_customer public.customers%rowtype;
  v_existing public.customers%rowtype;
  v_phone text;
  v_existing_phone text;
  v_existing_provisional boolean:=false;
begin
  if nullif(btrim(coalesce(p_token,'')),'') is null then
    return jsonb_build_object('ok',false,'error','order_token_required');
  end if;
  if p_customer_id is null then
    return jsonb_build_object('ok',false,'error','customer_id_required');
  end if;

  v_hash:=encode(extensions.digest(btrim(p_token),'sha256'),'hex');
  select l.* into v_link
  from public.ops2_order_registration_links_v1 l
  where l.token_hash=v_hash
  for update;
  if not found or v_link.revoked_at is not null then
    return jsonb_build_object('ok',false,'error','order_token_invalid');
  end if;
  if v_link.consumed_at is not null then
    return jsonb_build_object('ok',false,'error','token_already_used');
  end if;
  if v_link.expires_at<=now() then
    return jsonb_build_object('ok',false,'error','token_expired');
  end if;

  select c.* into v_customer from public.customers c where c.id=p_customer_id;
  if not found then
    return jsonb_build_object('ok',false,'error','customer_not_found');
  end if;

  v_phone:=public.canonical_whatsapp_e164_br_v2(coalesce(p_phone,v_customer.primary_whatsapp_e164));
  if v_phone is null or v_phone<>v_link.phone_e164 then
    return jsonb_build_object('ok',false,'error','phone_mismatch');
  end if;
  if public.canonical_whatsapp_e164_br_v2(v_customer.primary_whatsapp_e164) is distinct from v_link.phone_e164 then
    return jsonb_build_object('ok',false,'error','phone_mismatch');
  end if;

  select o.* into v_order from public.orders o where o.id=v_link.order_id for update;
  if not found then
    return jsonb_build_object('ok',false,'error','order_not_found');
  end if;

  if v_order.customer_id is not null and v_order.customer_id<>p_customer_id then
    select c.* into v_existing from public.customers c where c.id=v_order.customer_id;
    v_existing_phone:=public.canonical_whatsapp_e164_br_v2(v_existing.primary_whatsapp_e164);
    select exists(
      select 1 from public.customer_identity_profiles_v1 ip
      where ip.customer_id=v_order.customer_id and ip.identity_status='provisional'
    ) into v_existing_provisional;

    if v_existing_phone is distinct from v_link.phone_e164
       or nullif(regexp_replace(coalesce(v_existing.cpf_cnpj,''),'[^0-9]','','g'),'') is not null
       or coalesce(v_existing.bling_contact_id,0)<>0
       or v_existing_provisional is not true then
      return jsonb_build_object('ok',false,'error','order_already_linked');
    end if;
  end if;

  update public.orders
     set customer_id=p_customer_id,
         phone_e164=v_link.phone_e164,
         customer_snapshot=coalesce(customer_snapshot,'{}'::jsonb)
           || jsonb_strip_nulls(jsonb_build_object(
                'customer_id',p_customer_id,
                'name',nullif(btrim(v_customer.name),''),
                'phone_e164',v_link.phone_e164,
                'registration_link_consumed_at',now()
              )),
         updated_at=now()
   where id=v_order.id;

  if v_order.conversation_id is not null then
    update public.conversations
       set customer_id=p_customer_id,updated_at=now()
     where id=v_order.conversation_id
       and (customer_id is null or customer_id=v_order.customer_id or customer_id=p_customer_id);
  end if;

  update public.ops2_order_registration_links_v1
     set consumed_at=now(),consumed_customer_id=p_customer_id,updated_at=now()
   where id=v_link.id;

  begin
    perform public.ops2_refresh_customer_registration_journeys_v1(p_customer_id,true);
  exception when undefined_function then
    null;
  end;

  return jsonb_build_object(
    'ok',true,
    'order_id',v_order.id,
    'customer_id',p_customer_id,
    'phone_e164',v_link.phone_e164,
    'linked',true
  );
end;
$function$
;

-- function: ops2_customer_address_number_fill_v1()
CREATE OR REPLACE FUNCTION public.ops2_customer_address_number_fill_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if nullif(btrim(coalesce(new.number,'')),'') is null then
    new.number:=public.ops2_extract_address_number_v1(new.street);
  end if;
  return new;
end;
$function$
;

-- function: ops2_customer_address_registration_journey_trigger_v1()
CREATE OR REPLACE FUNCTION public.ops2_customer_address_registration_journey_trigger_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op='DELETE' then
    perform public.ops2_refresh_customer_registration_journeys_v1(old.customer_id,true);
    return old;
  end if;

  if tg_op='UPDATE' and old.customer_id is distinct from new.customer_id then
    perform public.ops2_refresh_customer_registration_journeys_v1(old.customer_id,true);
  end if;

  perform public.ops2_refresh_customer_registration_journeys_v1(new.customer_id,true);
  return new;
end;
$function$
;

-- function: ops2_customer_identity_summary_v1()
CREATE OR REPLACE FUNCTION public.ops2_customer_identity_summary_v1()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select public.ops2_customer_identity_summary_v2()
$function$
;

-- function: ops2_customer_identity_summary_v2()
CREATE OR REPLACE FUNCTION public.ops2_customer_identity_summary_v2()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'generated_at',now(),
    'site_orders_31d',(
      select count(*) from public.orders
      where created_at>=now()-interval '31 days' and source in ('vitrine','storefront_v2')
    ),
    'site_orders_without_customer_31d',(
      select count(*) from public.orders
      where created_at>=now()-interval '31 days' and source in ('vitrine','storefront_v2') and customer_id is null
    ),
    'site_orders_linked_conversation_31d',(
      select count(*) from public.orders
      where created_at>=now()-interval '31 days' and source in ('vitrine','storefront_v2') and conversation_id is not null
    ),
    'registration_pending_orders',(
      select count(*) from public.ops2_customer_registration_journeys_v1 where workflow_open=true and registration_state='pending'
    ),
    'registration_complete_orders',(
      select count(*) from public.ops2_customer_registration_journeys_v1 where registration_state='complete'
    ),
    'flow_required_orders',(
      select count(*)
      from public.ops2_customer_registration_journeys_v1 j
      where j.workflow_open=true
        and j.registration_state='pending'
        and public.ops2_customer_registration_state_v1(j.customer_id)->>'flow_required'='true'
    ),
    'flow_required_with_conversation',(
      select count(*)
      from public.ops2_customer_registration_journeys_v1 j
      join public.orders o on o.id=j.order_id
      where j.workflow_open=true
        and j.registration_state='pending'
        and public.ops2_customer_registration_state_v1(j.customer_id)->>'flow_required'='true'
        and o.conversation_id is not null
    ),
    'flow_required_without_conversation',(
      select count(*)
      from public.ops2_customer_registration_journeys_v1 j
      join public.orders o on o.id=j.order_id
      where j.workflow_open=true
        and j.registration_state='pending'
        and public.ops2_customer_registration_state_v1(j.customer_id)->>'flow_required'='true'
        and o.conversation_id is null
    ),
    'document_only_pending_orders',(
      select count(*)
      from public.ops2_customer_registration_journeys_v1 j
      where j.workflow_open=true
        and j.registration_state='pending'
        and public.ops2_customer_registration_state_v1(j.customer_id)->>'document_only_pending'='true'
    ),
    'pending_with_conversation',(
      select count(*)
      from public.ops2_customer_registration_journeys_v1 j
      join public.orders o on o.id=j.order_id
      where j.workflow_open=true and j.registration_state='pending' and o.conversation_id is not null
    ),
    'pending_without_conversation',(
      select count(*)
      from public.ops2_customer_registration_journeys_v1 j
      join public.orders o on o.id=j.order_id
      where j.workflow_open=true and j.registration_state='pending' and o.conversation_id is null
    ),
    'pending_missing_name',(
      select count(*) from public.ops2_customer_registration_journeys_v1
      where workflow_open=true and registration_state='pending' and missing_fields @> array['name']::text[]
    ),
    'pending_missing_document',(
      select count(*) from public.ops2_customer_registration_journeys_v1
      where workflow_open=true and registration_state='pending' and missing_fields @> array['document']::text[]
    ),
    'pending_missing_address',(
      select count(*) from public.ops2_customer_registration_journeys_v1
      where workflow_open=true and registration_state='pending' and missing_fields @> array['address']::text[]
    ),
    'pending_missing_city',(
      select count(*) from public.ops2_customer_registration_journeys_v1
      where workflow_open=true and registration_state='pending' and missing_fields @> array['city']::text[]
    ),
    'provisional_customers',(
      select count(*) from public.customer_identity_profiles_v1 where identity_status='provisional'
    ),
    'provisional_without_name',(
      select count(*)
      from public.customer_identity_profiles_v1 ip
      join public.customers c on c.id=ip.customer_id
      where ip.identity_status='provisional' and nullif(btrim(coalesce(c.name,'')),'') is null
    ),
    'verified_flow_customers',(
      select count(*) from public.customer_identity_profiles_v1 where identity_status='verified_flow'
    ),
    'flow_events_total',(select count(*) from public.papoai_customer_flow_events_v1),
    'flow_events_review',(select count(*) from public.papoai_customer_flow_events_v1 where status<>'processed')
  )
$function$
;

-- function: ops2_customer_registration_journey_trigger_v1()
CREATE OR REPLACE FUNCTION public.ops2_customer_registration_journey_trigger_v1()
 RETURNS trigger
 LANGUAGE plpgsql
