  return new;
end;
$function$
;

-- function: ops2_customer_registration_state_v1(p_customer_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_customer_registration_state_v1(p_customer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_customer public.customers%rowtype;
  v_phone text;
  v_name_ok boolean:=false;
  v_phone_ok boolean:=false;
  v_document_ok boolean:=false;
  v_has_street boolean:=false;
  v_has_number boolean:=false;
  v_has_neighborhood boolean:=false;
  v_has_city boolean:=false;
  v_registration_complete boolean:=false;
  v_already_linked_bling boolean:=false;
  v_bling_ready boolean:=false;
  v_document_only_pending boolean:=false;
  v_missing text[]:=array[]::text[];
begin
  select c.* into v_customer from public.customers c where c.id=p_customer_id;
  if not found then
    return jsonb_build_object(
      'ok',false,'error','customer_not_found','customer_id',p_customer_id,
      'identity_ready',false,'registration_complete',false,'bling_ready',false,
      'already_linked_bling',false,'flow_required',false,'document_only_pending',false,
      'missing_fields',to_jsonb(array['name','phone','document','address','number','neighborhood','city']::text[])
    );
  end if;

  v_name_ok:=nullif(btrim(coalesce(v_customer.name,'')),'') is not null;
  v_phone:=public.canonical_whatsapp_e164_br_v2(v_customer.primary_whatsapp_e164);
  v_phone_ok:=v_phone is not null;
  v_document_ok:=public.ops2_valid_cpf_cnpj_v1(v_customer.cpf_cnpj);

  select
    coalesce(bool_or(nullif(btrim(coalesce(a.street,'')),'') is not null),false),
    coalesce(bool_or(nullif(btrim(coalesce(a.number,'')),'') is not null),false),
    coalesce(bool_or(nullif(btrim(coalesce(a.neighborhood,'')),'') is not null),false),
    coalesce(bool_or(nullif(btrim(coalesce(a.city,'')),'') is not null),false)
  into v_has_street,v_has_number,v_has_neighborhood,v_has_city
  from public.customer_addresses a
  where a.customer_id=p_customer_id and a.is_active=true;

  v_registration_complete:=v_name_ok and v_phone_ok and v_document_ok
    and v_has_street and v_has_number and v_has_neighborhood and v_has_city;
  v_already_linked_bling:=coalesce(v_customer.bling_contact_id,0)>0;
  v_bling_ready:=v_already_linked_bling or v_registration_complete;

  if not v_name_ok then v_missing:=array_append(v_missing,'name'); end if;
  if not v_phone_ok then v_missing:=array_append(v_missing,'phone'); end if;
  if not v_document_ok then v_missing:=array_append(v_missing,'document'); end if;
  if not v_has_street then v_missing:=array_append(v_missing,'address'); end if;
  if not v_has_number then v_missing:=array_append(v_missing,'number'); end if;
  if not v_has_neighborhood then v_missing:=array_append(v_missing,'neighborhood'); end if;
  if not v_has_city then v_missing:=array_append(v_missing,'city'); end if;

  v_document_only_pending:=v_name_ok and v_phone_ok and v_has_street and v_has_number
    and v_has_neighborhood and v_has_city and not v_document_ok;

  return jsonb_build_object(
    'ok',true,'customer_id',p_customer_id,
    'identity_ready',v_name_ok and v_phone_ok,
    'registration_complete',v_registration_complete,
    'bling_ready',v_bling_ready,
    'already_linked_bling',v_already_linked_bling,
    'flow_required',false,
    'document_only_pending',v_document_only_pending,
    'missing_fields',to_jsonb(v_missing)
  );
end;
$function$
;

-- function: ops2_customer_registration_summary_v1(p_days integer)
CREATE OR REPLACE FUNCTION public.ops2_customer_registration_summary_v1(p_days integer DEFAULT 31)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_days integer:=greatest(1,least(365,coalesce(p_days,31)));
  v_since timestamptz:=now()-make_interval(days=>greatest(1,least(365,coalesce(p_days,31))));
  v_result jsonb;
begin
  with recent_orders as (
    select o.id,o.customer_id
    from public.orders o
    where o.created_at>=v_since
      and o.source in ('vitrine','storefront_v2')
  ), distinct_customers as (
    select distinct ro.customer_id
    from recent_orders ro
    where ro.customer_id is not null
  ), customer_states as (
    select dc.customer_id,public.ops2_customer_registration_state_v1(dc.customer_id) as state
    from distinct_customers dc
  ), order_states as (
    select ro.id,ro.customer_id,cs.state
    from recent_orders ro
    left join customer_states cs on cs.customer_id=ro.customer_id
  )
  select jsonb_build_object(
    'generated_at',now(),
    'days',v_days,
    'recent_site_orders',(select count(*) from recent_orders),
    'recent_site_orders_incomplete_registration',(
      select count(*) from order_states os
      where os.customer_id is null or coalesce((os.state->>'registration_complete')::boolean,false)=false
    ),
    'recent_site_orders_flow_required',(
      select count(*) from order_states os
      where os.customer_id is null or coalesce((os.state->>'flow_required')::boolean,true)=true
    ),
    'distinct_customers_incomplete_registration',(
      select count(*) from customer_states cs
      where coalesce((cs.state->>'registration_complete')::boolean,false)=false
    ),
    'distinct_customers_registration_complete',(
      select count(*) from customer_states cs
      where coalesce((cs.state->>'registration_complete')::boolean,false)=true
    ),
    'distinct_customers_flow_required',(
      select count(*) from customer_states cs
      where coalesce((cs.state->>'flow_required')::boolean,true)=true
    ),
    'distinct_customers_document_only_pending',(
      select count(*) from customer_states cs
      where coalesce((cs.state->>'document_only_pending')::boolean,false)=true
    ),
    'distinct_customers_bling_ready_unlinked',(
      select count(*) from customer_states cs
      where coalesce((cs.state->>'bling_ready')::boolean,false)=true
        and coalesce((cs.state->>'already_linked_bling')::boolean,false)=false
    ),
    'flow_events_total',(
      select count(*) from public.papoai_customer_flow_events_v1 f where f.created_at>=v_since
    ),
    'flow_events_review',(
      select count(*) from public.papoai_customer_flow_events_v1 f
      where f.created_at>=v_since and f.status<>'processed'
    )
  ) into v_result;
  return v_result;
end;
$function$
;

-- function: ops2_enqueue_admin_order_whatsapp_v1(p_order_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_enqueue_admin_order_whatsapp_v1(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_order public.orders%rowtype;
  v_customer public.customers%rowtype;
  v_conversation public.conversations%rowtype;
  v_customer_account public.whatsapp_accounts%rowtype;
  v_ops_account public.whatsapp_accounts%rowtype;
  v_customer_phone text;
  v_customer_channel text;
  v_customer_channel_phone text;
  v_payload jsonb;
  v_customer_row public.ops2_whatsapp_outbox_v1%rowtype;
  v_ops_row public.ops2_whatsapp_outbox_v1%rowtype;
begin
  if p_order_id is null then
    return jsonb_build_object('ok',false,'error','order_id_required');
  end if;

  select o.* into v_order from public.orders o where o.id=p_order_id;
  if not found then
    return jsonb_build_object('ok',false,'error','order_not_found');
  end if;

  if v_order.customer_id is not null then
    select c.* into v_customer from public.customers c where c.id=v_order.customer_id;
  end if;
  v_customer_phone:=public.canonical_whatsapp_e164_br_v2(coalesce(v_order.phone_e164,v_customer.primary_whatsapp_e164));
  if v_customer_phone is null then
    return jsonb_build_object('ok',false,'error','customer_phone_missing');
  end if;

  if v_order.conversation_id is not null then
    select c.* into v_conversation from public.conversations c where c.id=v_order.conversation_id limit 1;
  end if;
  if v_conversation.id is null then
    select c.* into v_conversation
    from public.conversations c
    where c.whatsapp_account_id is not null
      and (
        (v_order.customer_id is not null and c.customer_id=v_order.customer_id)
        or public.canonical_whatsapp_e164_br_v2(c.wa_contact_e164)=v_customer_phone
      )
    order by greatest(
      coalesce(c.last_inbound_at,'epoch'::timestamptz),
      coalesce(c.last_outbound_at,'epoch'::timestamptz),
      coalesce(c.updated_at,'epoch'::timestamptz),
      coalesce(c.created_at,'epoch'::timestamptz)
    ) desc
    limit 1;
  end if;

  if v_order.whatsapp_account_id is not null then
    select wa.* into v_customer_account
    from public.whatsapp_accounts wa
    where wa.id=v_order.whatsapp_account_id and wa.is_active=true limit 1;
  end if;
  if v_customer_account.id is null and v_conversation.whatsapp_account_id is not null then
    select wa.* into v_customer_account
    from public.whatsapp_accounts wa
    where wa.id=v_conversation.whatsapp_account_id and wa.is_active=true limit 1;
  end if;

  v_customer_channel_phone:=public.canonical_whatsapp_e164_br_v2(v_customer_account.phone_e164);
  if right(coalesce(v_customer_channel_phone,''),4)='1018' then
    v_customer_channel:='1018';
  elsif right(coalesce(v_customer_channel_phone,''),4)='0975' then
    v_customer_channel:='0975';
  else
    v_customer_channel:='0975';
    select wa.* into v_customer_account
    from public.whatsapp_accounts wa
    where wa.is_active=true
      and right(regexp_replace(coalesce(wa.phone_e164,''),'\D','','g'),4)='0975'
    order by wa.updated_at desc nulls last,wa.created_at desc nulls last
    limit 1;
    v_customer_channel_phone:=coalesce(public.canonical_whatsapp_e164_br_v2(v_customer_account.phone_e164),'+5565998150975');
  end if;

  select wa.* into v_ops_account
  from public.whatsapp_accounts wa
  where wa.is_active=true
    and right(regexp_replace(coalesce(wa.phone_e164,''),'\D','','g'),4)='1018'
  order by wa.updated_at desc nulls last,wa.created_at desc nulls last
  limit 1;
  if v_ops_account.id is null then
    return jsonb_build_object('ok',false,'error','ops_1018_channel_unavailable');
  end if;

  v_payload:=jsonb_build_object(
    'kind','order_received',
    'order_id',v_order.id,
    'order_number',v_order.order_number,
    'order',jsonb_build_object(
      'id',v_order.id,
      'order_number',v_order.order_number,
      'status',v_order.status,
      'total',v_order.total,
      'currency',v_order.currency,
      'payment_method',v_order.payment_method,
      'delivery',coalesce(v_order.checkout_snapshot->'delivery','{}'::jsonb)
    )
  );

  insert into public.ops2_whatsapp_outbox_v1 as q(
    order_id,customer_id,conversation_id,whatsapp_account_id,recipient_kind,
    phone_e164,channel_origin,channel_phone_e164,delivery_mode,message_kind,payload,status
  ) values (
    v_order.id,v_order.customer_id,coalesce(v_order.conversation_id,v_conversation.id),v_customer_account.id,'customer',
    v_customer_phone,v_customer_channel,v_customer_channel_phone,'utility_template','order_received',
    v_payload||jsonb_build_object('recipient_kind','customer','phone_e164',v_customer_phone,'channel_origin',v_customer_channel),
    'pending'
  )
  on conflict (order_id,message_kind,recipient_kind) do update
     set customer_id=excluded.customer_id,
         conversation_id=coalesce(excluded.conversation_id,q.conversation_id),
         whatsapp_account_id=coalesce(excluded.whatsapp_account_id,q.whatsapp_account_id),
         phone_e164=excluded.phone_e164,
         channel_origin=excluded.channel_origin,
         channel_phone_e164=excluded.channel_phone_e164,
         payload=excluded.payload,
         status=case when q.status='failed' then 'pending' else q.status end,
         available_at=case when q.status='failed' then now() else q.available_at end,
         locked_at=case when q.status='failed' then null else q.locked_at end,
         last_error=case when q.status='failed' then null else q.last_error end,
         updated_at=now()
   where q.status in ('pending','retry','failed')
  returning * into v_customer_row;
  if not found then
    select * into v_customer_row from public.ops2_whatsapp_outbox_v1
    where order_id=v_order.id and message_kind='order_received' and recipient_kind='customer';
  end if;

  insert into public.ops2_whatsapp_outbox_v1 as q(
    order_id,customer_id,conversation_id,whatsapp_account_id,recipient_kind,
    phone_e164,channel_origin,channel_phone_e164,delivery_mode,message_kind,payload,status
  ) values (
    v_order.id,v_order.customer_id,null,v_ops_account.id,'ops_0975',
    '+5565998150975','1018',coalesce(public.canonical_whatsapp_e164_br_v2(v_ops_account.phone_e164),'+5565984491018'),
    'utility_template','order_received',
    v_payload||jsonb_build_object('recipient_kind','ops_0975','phone_e164','+5565998150975','channel_origin','1018'),
    'pending'
  )
  on conflict (order_id,message_kind,recipient_kind) do update
     set customer_id=excluded.customer_id,
         whatsapp_account_id=excluded.whatsapp_account_id,
         phone_e164=excluded.phone_e164,
         channel_origin='1018',
         channel_phone_e164=excluded.channel_phone_e164,
         payload=excluded.payload,
         status=case when q.status='failed' then 'pending' else q.status end,
         available_at=case when q.status='failed' then now() else q.available_at end,
         locked_at=case when q.status='failed' then null else q.locked_at end,
         last_error=case when q.status='failed' then null else q.last_error end,
         updated_at=now()
   where q.status in ('pending','retry','failed')
  returning * into v_ops_row;
  if not found then
    select * into v_ops_row from public.ops2_whatsapp_outbox_v1
    where order_id=v_order.id and message_kind='order_received' and recipient_kind='ops_0975';
  end if;

  return jsonb_build_object(
    'ok',true,
    'order_id',v_order.id,
    'customer',jsonb_build_object('outbox_id',v_customer_row.id,'status',v_customer_row.status,'phone_e164',v_customer_row.phone_e164,'channel_origin',v_customer_row.channel_origin),
    'ops_0975',jsonb_build_object('outbox_id',v_ops_row.id,'status',v_ops_row.status,'phone_e164',v_ops_row.phone_e164,'channel_origin',v_ops_row.channel_origin)
  );
end;
$function$
;

-- function: ops2_enqueue_order_whatsapp_v1(p_order_id uuid, p_message_kind text)
CREATE OR REPLACE FUNCTION public.ops2_enqueue_order_whatsapp_v1(p_order_id uuid, p_message_kind text DEFAULT 'order_received'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_runtime_mode text;
  v_canary_order_id uuid;
begin
  select r.mode,r.canary_order_id
    into v_runtime_mode,v_canary_order_id
  from public.ops2_whatsapp_order_runtime_v1 r
  where r.id=1;

  v_runtime_mode:=coalesce(v_runtime_mode,'off');

  if v_runtime_mode='off' then
    return jsonb_build_object('ok',true,'skipped',true,'reason','runtime_off');
  end if;

  if v_runtime_mode='canary' and p_order_id is distinct from v_canary_order_id then
    return jsonb_build_object('ok',true,'skipped',true,'reason','not_canary_order');
  end if;

  return public.ops2_enqueue_order_whatsapp_v1_base(p_order_id,p_message_kind);
end;
$function$
;

-- function: ops2_enqueue_order_whatsapp_v1_base(p_order_id uuid, p_message_kind text)
CREATE OR REPLACE FUNCTION public.ops2_enqueue_order_whatsapp_v1_base(p_order_id uuid, p_message_kind text DEFAULT 'order_received'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_order public.orders%rowtype;
  v_customer public.customers%rowtype;
  v_conversation public.conversations%rowtype;
  v_account public.whatsapp_accounts%rowtype;
  v_phone text;
  v_kind text:=coalesce(nullif(btrim(p_message_kind),''),'order_received');
  v_channel_origin text;
  v_channel_phone_e164 text;
  v_checkout_origin text;
  v_payload jsonb;
  v_outbox public.ops2_whatsapp_outbox_v1%rowtype;
  v_reused boolean:=false;
begin
  if p_order_id is null then
    return jsonb_build_object('ok',false,'error','order_id_required');
  end if;
  if v_kind <> 'order_received' then
    return jsonb_build_object('ok',false,'error','unsupported_message_kind');
  end if;

  select o.* into v_order from public.orders o where o.id=p_order_id;
  if not found then
    return jsonb_build_object('ok',false,'error','order_not_found');
  end if;

  v_checkout_origin:=lower(coalesce(v_order.checkout_snapshot#>>'{customer,whatsapp_origin}',''));
  if v_checkout_origin not in ('0975','1018') then v_checkout_origin:=''; end if;

  if v_order.customer_id is not null then
    select c.* into v_customer from public.customers c where c.id=v_order.customer_id;
  end if;
  v_phone:=public.canonical_whatsapp_e164_br_v2(coalesce(v_order.phone_e164,v_customer.primary_whatsapp_e164));
  if v_phone is null then
    return jsonb_build_object('ok',false,'error','customer_phone_missing');
  end if;

  if v_order.conversation_id is not null then
    select c.* into v_conversation from public.conversations c where c.id=v_order.conversation_id limit 1;
  end if;
  if v_conversation.id is null then
    select c.* into v_conversation
    from public.conversations c
    where c.whatsapp_account_id is not null
      and ((v_order.customer_id is not null and c.customer_id=v_order.customer_id)
        or public.canonical_whatsapp_e164_br_v2(c.wa_contact_e164)=v_phone)
    order by greatest(
      coalesce(c.last_inbound_at,'epoch'::timestamptz),
      coalesce(c.last_outbound_at,'epoch'::timestamptz),
      coalesce(c.updated_at,'epoch'::timestamptz),
      coalesce(c.created_at,'epoch'::timestamptz)
    ) desc
    limit 1;
  end if;

  if v_order.whatsapp_account_id is not null then
    select wa.* into v_account from public.whatsapp_accounts wa
    where wa.id=v_order.whatsapp_account_id and wa.is_active=true limit 1;
  end if;
  if v_account.id is null and v_conversation.whatsapp_account_id is not null then
    select wa.* into v_account from public.whatsapp_accounts wa
    where wa.id=v_conversation.whatsapp_account_id and wa.is_active=true limit 1;
  end if;

  v_channel_phone_e164:=public.canonical_whatsapp_e164_br_v2(v_account.phone_e164);
  if right(coalesce(v_channel_phone_e164,''),4)='1018' then
    v_channel_origin:='1018';
  elsif right(coalesce(v_channel_phone_e164,''),4)='0975' then
    v_channel_origin:='0975';
  elsif v_checkout_origin='1018' then
    v_channel_origin:='1018';
    select public.canonical_whatsapp_e164_br_v2(wa.phone_e164) into v_channel_phone_e164
    from public.whatsapp_accounts wa
    where wa.is_active=true and right(regexp_replace(coalesce(wa.phone_e164,''),'\D','','g'),4)='1018'
    order by wa.updated_at desc nulls last,wa.created_at desc nulls last limit 1;
    v_channel_phone_e164:=coalesce(v_channel_phone_e164,'+5565984491018');
  else
    v_channel_origin:='0975';
    select public.canonical_whatsapp_e164_br_v2(wa.phone_e164) into v_channel_phone_e164
    from public.whatsapp_accounts wa
    where wa.is_active=true and right(regexp_replace(coalesce(wa.phone_e164,''),'\D','','g'),4)='0975'
    order by wa.updated_at desc nulls last,wa.created_at desc nulls last limit 1;
    v_channel_phone_e164:=coalesce(v_channel_phone_e164,'+5565998150975');
  end if;

  v_payload:=jsonb_build_object(
    'kind',v_kind,
    'recipient_kind','customer',
    'order_id',v_order.id,
    'order_number',v_order.order_number,
    'phone_e164',v_phone,
    'channel_origin',v_channel_origin,
    'channel_phone_e164',v_channel_phone_e164,
    'delivery_mode','utility_template',
    'order',jsonb_build_object(
      'id',v_order.id,'order_number',v_order.order_number,'status',v_order.status,
      'total',v_order.total,'currency',v_order.currency,'payment_method',v_order.payment_method,
      'delivery',coalesce(v_order.checkout_snapshot->'delivery','{}'::jsonb)
    )
  );

  select exists(
    select 1 from public.ops2_whatsapp_outbox_v1 q
    where q.order_id=v_order.id and q.message_kind=v_kind and q.recipient_kind='customer'
  ) into v_reused;

  insert into public.ops2_whatsapp_outbox_v1 as q(
    order_id,customer_id,conversation_id,whatsapp_account_id,recipient_kind,
    phone_e164,channel_origin,channel_phone_e164,delivery_mode,message_kind,payload,status
  ) values (
    v_order.id,v_order.customer_id,coalesce(v_order.conversation_id,v_conversation.id),coalesce(v_order.whatsapp_account_id,v_account.id),'customer',
    v_phone,v_channel_origin,v_channel_phone_e164,'utility_template',v_kind,v_payload,'pending'
  )
  on conflict (order_id,message_kind,recipient_kind) do update
     set customer_id=excluded.customer_id,
         conversation_id=coalesce(excluded.conversation_id,q.conversation_id),
         whatsapp_account_id=coalesce(excluded.whatsapp_account_id,q.whatsapp_account_id),
         phone_e164=excluded.phone_e164,
         channel_origin=excluded.channel_origin,
         channel_phone_e164=excluded.channel_phone_e164,
         delivery_mode='utility_template',
         payload=excluded.payload,
         updated_at=now()
   where q.status in ('pending','retry')
  returning * into v_outbox;

  if not found then
    select existing.* into v_outbox from public.ops2_whatsapp_outbox_v1 existing
    where existing.order_id=v_order.id and existing.message_kind=v_kind and existing.recipient_kind='customer';
  end if;

  return jsonb_build_object(
    'ok',true,'outbox_id',v_outbox.id,'status',v_outbox.status,'recipient_kind',v_outbox.recipient_kind,
    'delivery_mode',v_outbox.delivery_mode,'channel_origin',v_outbox.channel_origin,
    'channel_phone_e164',v_outbox.channel_phone_e164,'phone_e164',v_outbox.phone_e164,'reused',v_reused
  );
end;
$function$
;

-- function: ops2_enqueue_papoai_order_signals_v1(p_order_id uuid, p_channel_origin text, p_phone_e164 text, p_signal_keys text[])
CREATE OR REPLACE FUNCTION public.ops2_enqueue_papoai_order_signals_v1(p_order_id uuid, p_channel_origin text, p_phone_e164 text, p_signal_keys text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_mode text; v_canary uuid; v_channel text; v_phone text; v_signal text; v_count integer:=0;
begin
  select mode,canary_order_id into v_mode,v_canary from public.ops2_papoai_order_signal_runtime_v1 where id=1;
  v_mode:=coalesce(v_mode,'off');
  if v_mode='off' then return jsonb_build_object('ok',true,'skipped',true,'reason','runtime_off','enqueued',0); end if;
  if v_mode='canary' and p_order_id is distinct from v_canary then
    return jsonb_build_object('ok',true,'skipped',true,'reason','not_canary_order','enqueued',0);
  end if;
  if p_order_id is null then return jsonb_build_object('ok',false,'error','order_id_required'); end if;
  v_channel:=btrim(coalesce(p_channel_origin,''));
  if v_channel not in ('0975','1018') then return jsonb_build_object('ok',false,'error','unsupported_channel'); end if;
  v_phone:=public.canonical_whatsapp_e164_br_v2(p_phone_e164);
  if v_phone is null then return jsonb_build_object('ok',false,'error','invalid_phone'); end if;
  foreach v_signal in array coalesce(p_signal_keys,array[]::text[]) loop
    v_signal:=upper(btrim(coalesce(v_signal,'')));
    if public.ops2_papoai_signal_allowed_v1(v_signal) then
      insert into public.ops2_papoai_order_signal_outbox_v1(order_id,phone_e164,channel_origin,signal_key,status)
      values(p_order_id,v_phone,v_channel,v_signal,'pending')
      on conflict(order_id,channel_origin,signal_key) do nothing;
      if found then v_count:=v_count+1; end if;
    end if;
  end loop;
  return jsonb_build_object('ok',true,'enqueued',v_count,'mode',v_mode);
end $function$
;

-- function: ops2_enqueue_storefront_order_whatsapp_v1()
CREATE OR REPLACE FUNCTION public.ops2_enqueue_storefront_order_whatsapp_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.source not in ('vitrine','storefront_v2') then
    return new;
  end if;

  begin
    perform public.ops2_enqueue_order_whatsapp_v1(new.id,'order_received');
  exception when others then
    raise warning 'ops2_enqueue_storefront_order_whatsapp_v1 failed for order %: %',new.id,sqlerrm;
  end;

  return new;
end;
$function$
;

-- function: ops2_enrich_storefront_order_result_v1(p_result jsonb)
CREATE OR REPLACE FUNCTION public.ops2_enrich_storefront_order_result_v1(p_result jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_result jsonb:=coalesce(p_result,'{}'::jsonb);
  v_order_id uuid;
  v_customer_id uuid;
  v_state jsonb;
  v_complete boolean:=false;
  v_flow_required boolean:=true;
  v_document_only_pending boolean:=false;
  v_missing jsonb:='[]'::jsonb;
  v_whatsapp_return_phone text;
  v_whatsapp_return_origin text;
begin
  begin
    v_order_id:=nullif(v_result->>'order_id','')::uuid;
  exception when others then
    v_order_id:=null;
  end;

  if v_order_id is not null then
    select customer_id into v_customer_id from public.orders where id=v_order_id;

    select q.channel_phone_e164,q.channel_origin
      into v_whatsapp_return_phone,v_whatsapp_return_origin
      from public.ops2_whatsapp_outbox_v1 q
     where q.order_id=v_order_id
       and q.recipient_kind='customer'
       and q.message_kind='order_received'
     order by q.created_at desc
     limit 1;
  end if;

  if v_customer_id is not null then
    v_state:=public.ops2_customer_registration_state_v1(v_customer_id);
    v_complete:=coalesce((v_state->>'registration_complete')::boolean,false);
    v_flow_required:=coalesce((v_state->>'flow_required')::boolean,true);
    v_document_only_pending:=coalesce((v_state->>'document_only_pending')::boolean,false);
    v_missing:=coalesce(v_state->'missing_fields','[]'::jsonb);
  else
    v_missing:='["customer"]'::jsonb;
  end if;

  return v_result || jsonb_build_object(
    'registration_complete',v_complete,
    'registration_state',case when v_complete then 'complete' else 'pending' end,
    'registration_missing_fields',v_missing,
    'flow_required',v_flow_required,
    'document_only_pending',v_document_only_pending,
    'whatsapp_return_phone',v_whatsapp_return_phone,
    'whatsapp_return_origin',v_whatsapp_return_origin
  );
end;
$function$
;

-- function: ops2_extract_address_number_v1(p_street text)
CREATE OR REPLACE FUNCTION public.ops2_extract_address_number_v1(p_street text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  v text:=btrim(coalesce(p_street,''));
  m text[];
begin
  if v='' or v ~* '(^|[^a-z])s\s*/?\s*n([^a-z]|$)' then return null; end if;
  m:=regexp_match(v,'(?i)(?:^|[ ,;-])(?:n(?:[º°o.]|umero|úmero)?)[[:space:]]*[:#-]?[[:space:]]*([0-9]+[A-Za-z]?)');
  if m is not null then return m[1]; end if;
  m:=regexp_match(v,'(?i)(?:^|[ ,;-])casa[[:space:]]*(?:n(?:[º°o.]|umero|úmero)?[[:space:]]*)?[:#-]?[[:space:]]*([0-9]+[A-Za-z]?)');
  if m is not null then return m[1]; end if;
  m:=regexp_match(v,',\s*([0-9]+[A-Za-z]?)\s*(?:[,;-]|$)');
  if m is not null then return m[1]; end if;
  return null;
end;
$function$
;

-- function: ops2_fefo_preview_v1(p_product_id uuid, p_quantity numeric)
CREATE OR REPLACE FUNCTION public.ops2_fefo_preview_v1(p_product_id uuid, p_quantity numeric)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
with eligible as (
  select id,lot_code,expiration_date,
         greatest(coalesce(quantity_on_hand,0)-coalesce(quantity_reserved,0),0)::numeric(14,3) available
  from public.product_inventory_lots
  where product_id=p_product_id
    and status='active'
    and expiration_date>=current_date
    and quantity_on_hand is not null
    and greatest(quantity_on_hand-quantity_reserved,0)>0
  order by expiration_date,id
),
walk as (
  select id,lot_code,expiration_date,available,
         sum(available) over(order by expiration_date,id rows unbounded preceding) cumulative
  from eligible
),
alloc as (
  select id,lot_code,expiration_date,available,
         greatest(least(available,p_quantity-(cumulative-available)),0)::numeric(14,3) allocate
  from walk
)
select jsonb_build_object(
  'ok',true,
  'product_id',p_product_id,
  'requested_quantity',p_quantity,
  'available_quantity',coalesce((select sum(available) from eligible),0),
  'fully_allocatable',coalesce((select sum(available) from eligible),0)>=p_quantity,
  'allocations',coalesce((
    select jsonb_agg(jsonb_build_object(
      'lot_id',id,'lot_code',lot_code,'expiration_date',expiration_date,
      'available',available,'allocate',allocate
    ) order by expiration_date,id)
    from alloc where allocate>0
  ),'[]'::jsonb)
)
$function$
;

-- function: ops2_finish_papoai_order_signal_v1(p_outbox_id uuid, p_status text, p_external_ref text, p_last_error text, p_retry_after_seconds integer)
CREATE OR REPLACE FUNCTION public.ops2_finish_papoai_order_signal_v1(p_outbox_id uuid, p_status text, p_external_ref text DEFAULT NULL::text, p_last_error text DEFAULT NULL::text, p_retry_after_seconds integer DEFAULT 300)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_status text:=lower(btrim(coalesce(p_status,''))); v_item public.ops2_papoai_order_signal_outbox_v1%rowtype;
begin
  if v_status not in ('sent','retry','failed','suppressed') then return jsonb_build_object('ok',false,'error','invalid_status'); end if;
  update public.ops2_papoai_order_signal_outbox_v1 set status=v_status,
    external_ref=case when v_status='sent' then nullif(btrim(coalesce(p_external_ref,'')),'') else external_ref end,
    last_error=case when v_status='sent' then null else nullif(left(coalesce(p_last_error,''),500),'') end,
    sent_at=case when v_status='sent' then now() else sent_at end,
    available_at=case when v_status='retry' then now()+make_interval(secs=>greatest(60,least(coalesce(p_retry_after_seconds,300),3600))) else available_at end,
    locked_at=null,updated_at=now()
  where id=p_outbox_id returning * into v_item;
  if not found then return jsonb_build_object('ok',false,'error','outbox_not_found'); end if;
  return jsonb_build_object('ok',true,'status',v_item.status,'attempt_count',v_item.attempt_count);
end $function$
;

-- function: ops2_finish_whatsapp_outbox_v1(p_outbox_id uuid, p_status text, p_external_message_id text, p_last_error text, p_retry_after_seconds integer)
CREATE OR REPLACE FUNCTION public.ops2_finish_whatsapp_outbox_v1(p_outbox_id uuid, p_status text, p_external_message_id text DEFAULT NULL::text, p_last_error text DEFAULT NULL::text, p_retry_after_seconds integer DEFAULT 300)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_status text:=lower(coalesce(btrim(p_status),''));
  v_item public.ops2_whatsapp_outbox_v1%rowtype;
begin
  if p_outbox_id is null then
    return jsonb_build_object('ok',false,'error','outbox_id_required');
  end if;
  if v_status not in ('accepted','sent','retry','failed','suppressed') then
    return jsonb_build_object('ok',false,'error','invalid_finish_status');
  end if;
  if v_status='sent' and nullif(btrim(coalesce(p_external_message_id,'')),'') is null then
    return jsonb_build_object('ok',false,'error','sent_requires_external_message_id');
  end if;

  if v_status='accepted' then
    select * into v_item
    from public.ops2_whatsapp_outbox_v1
    where id=p_outbox_id;
    if found and v_item.status='sent' and nullif(btrim(coalesce(v_item.external_message_id,'')),'') is not null then
      return jsonb_build_object(
        'ok',true,
        'outbox_id',v_item.id,
        'status',v_item.status,
        'attempt_count',v_item.attempt_count,
        'external_message_id',v_item.external_message_id,
        'race_resolved',true
      );
    end if;
  end if;

  update public.ops2_whatsapp_outbox_v1
     set status=v_status,
         external_message_id=case when v_status='sent' then nullif(btrim(p_external_message_id),'') else external_message_id end,
         last_error=case when v_status in ('accepted','sent') then null else nullif(left(coalesce(p_last_error,''),500),'') end,
         sent_at=case when v_status='sent' then now() when v_status='accepted' then null else sent_at end,
         available_at=case when v_status='retry' then now()+make_interval(secs=>greatest(60,least(coalesce(p_retry_after_seconds,300),3600))) else available_at end,
         locked_at=null,
         updated_at=now()
   where id=p_outbox_id
     and status='sending'
  returning * into v_item;

  if not found then
    return jsonb_build_object('ok',false,'error','outbox_not_sending');
  end if;

  return jsonb_build_object(
    'ok',true,
    'outbox_id',v_item.id,
    'status',v_item.status,
    'attempt_count',v_item.attempt_count,
    'external_message_id',v_item.external_message_id
  );
end;
$function$
;

-- function: ops2_fiscal_dispatch_preflight_v1(p_order_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_fiscal_dispatch_preflight_v1(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  o public.orders%rowtype;
  s public.order_separation_completions_v1%rowtype;
  readiness jsonb;
  item_sum numeric(14,2):=0;
  expected_total numeric(14,2):=0;
  link_status text;
  link_meta jsonb:='{}'::jsonb;
  runtime_meta jsonb:='{}'::jsonb;
  target_verified_id bigint:=0;
  blockers text[]:='{}';
  v_item_count integer:=0;
  v_pending integer:=0;
begin
  select * into o from public.orders where id=p_order_id;
  if not found then
    return jsonb_build_object('ok',false,'ready',false,'blockers',jsonb_build_array('order_not_found'));
  end if;

  readiness:=public.refresh_order_fiscal_readiness_v1(o.id);
  select * into s from public.order_separation_completions_v1 where order_id=o.id;

  select
    count(*),
    count(*) filter(where si.state='pending'),
    round(coalesce(sum(si.line_total) filter(where si.state='separated'),0)::numeric,2)
  into v_item_count,v_pending,item_sum
  from public.order_separation_items_v1 si
  join public.order_items oi on oi.id=si.order_item_id
  where si.order_id=o.id
    and not (
      coalesce(oi.metadata->>'history_kind','') in ('basket','basket_mold')
      and exists(
        select 1 from public.order_items c
        where c.order_id=o.id
          and coalesce(c.metadata->>'history_kind','') in ('basket_component','basket_mold_component')
          and (
            (
              nullif(oi.metadata->>'basket_id','') is not null
              and nullif(c.metadata->>'basket_id','')=nullif(oi.metadata->>'basket_id','')
            )
            or lower(trim(coalesce(nullif(c.metadata->>'basket_name',''),nullif(c.metadata->>'parent_basket_name',''),'')))
               = lower(trim(coalesce(nullif(oi.metadata->>'basket_name',''),oi.name_snapshot,'')))
          )
      )
    );

  expected_total:=round((coalesce(o.fiscal_subtotal,0)+coalesce(o.other_expenses,0)-coalesce(o.discount,0))::numeric,2);

  if o.status<>'ready' then blockers:=array_append(blockers,'order_not_ready'); end if;
  if s.id is null or s.completed_at is null then blockers:=array_append(blockers,'separation_not_completed'); end if;
  if s.id is not null and coalesce((s.metadata->>'stock_applied')::boolean,false) is not true then blockers:=array_append(blockers,'separation_stock_not_applied'); end if;
  if v_item_count=0 then blockers:=array_append(blockers,'separation_items_missing'); end if;
  if v_pending>0 then blockers:=array_append(blockers,'separation_has_pending_items'); end if;
  if s.id is not null and abs(round(coalesce(s.final_total,0)::numeric,2)-round(coalesce(o.total,0)::numeric,2))>0.01 then blockers:=array_append(blockers,'final_total_mismatch'); end if;
  if abs(item_sum-round(coalesce(o.fiscal_subtotal,0)::numeric,2))>0.01 then blockers:=array_append(blockers,'fiscal_subtotal_item_sum_mismatch'); end if;
  if abs(round(coalesce(o.total,0)::numeric,2)-expected_total)>0.01 then blockers:=array_append(blockers,'canonical_total_not_balanced'); end if;
  if coalesce(o.other_expenses,0)<0 then blockers:=array_append(blockers,'negative_other_expenses'); end if;
  if coalesce(o.discount,0)<0 then blockers:=array_append(blockers,'negative_discount'); end if;
  if coalesce(readiness->>'fiscal_status','blocked')<>'ready' and coalesce(readiness->>'block_reason','')<>'' then
    blockers:=array_append(blockers,coalesce(readiness->>'block_reason','fiscal_not_ready'));
  end if;

  select status,coalesce(metadata,'{}'::jsonb)
    into link_status,link_meta
    from public.bling_hub_entity_links_v2
   where source_system='vitrine_qx' and entity_type='order' and source_id=o.id::text
   limit 1;
  if coalesce(link_status,'')<>'matched' and o.bling_order_id is null then blockers:=array_append(blockers,'bling_order_not_linked'); end if;

  select coalesce(metadata,'{}'::jsonb)
    into runtime_meta
    from public.bling_hub_runtime_v2
   where id=1;
  if coalesce(runtime_meta->>'ops2_direct_order_state_enabled','false')::boolean
     and coalesce(runtime_meta->>'ops2_live_cutover_at','')<>'' then
    target_verified_id:=coalesce((runtime_meta->'ops2_order_status_mapping'->>'verified_id')::bigint,0);
    if coalesce(link_meta->>'ops2_target_key','')<>'verified'
       or coalesce((link_meta->>'ops2_target_status_id')::bigint,0)<>target_verified_id then
      blockers:=array_append(blockers,'bling_order_not_verified');
    end if;
  end if;

  return jsonb_build_object(
    'ok',true,'order_id',o.id,'order_number',o.order_number,
    'ready',coalesce(array_length(blockers,1),0)=0,'blockers',to_jsonb(blockers),
    'item_sum',item_sum,'fiscal_subtotal',round(coalesce(o.fiscal_subtotal,0)::numeric,2),
    'other_expenses',round(coalesce(o.other_expenses,0)::numeric,2),'discount',round(coalesce(o.discount,0)::numeric,2),
    'canonical_total',round(coalesce(o.total,0)::numeric,2),'final_total',round(coalesce(s.final_total,o.total,0)::numeric,2),
    'recomposed_total',expected_total,'basket_hidden_adjustment',round(coalesce(o.basket_hidden_adjustment,0)::numeric,2),
    'separation_v4',s.id is not null,'separation_completed_at',s.completed_at,
    'bling_link_status',link_status,'bling_target_key',link_meta->>'ops2_target_key',
    'bling_target_status_id',link_meta->>'ops2_target_status_id','readiness',readiness
  );
end;
$function$
;

-- function: ops2_format_order_public_code_v1(p_value bigint)
CREATE OR REPLACE FUNCTION public.ops2_format_order_public_code_v1(p_value bigint)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE STRICT
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select chr(65 + (((p_value / 1000) / 26) % 26)::int)
      || chr(65 + ((p_value / 1000) % 26)::int)
      || lpad((p_value % 1000)::text, 3, '0')
$function$
;

-- function: ops2_get_order_separation_v2(p_order_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_get_order_separation_v2(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_order public.orders%rowtype;
  v_assignment jsonb := null;
  v_completion jsonb := null;
  v_items jsonb := '[]'::jsonb;
  v_pending integer := 0;
  v_separated integer := 0;
  v_missing integer := 0;
  v_init jsonb;
  v_live_missing_subtotal numeric(14,2) := 0;
  v_original_total numeric(14,2) := 0;
  v_final_total numeric(14,2) := 0;
begin
  if p_order_id is null then
    return jsonb_build_object('ok',false,'error','invalid_order_id');
  end if;

  select * into v_order from public.orders where id=p_order_id;
  if not found then
    return jsonb_build_object('ok',false,'error','order_not_found');
  end if;

  if v_order.status in ('confirmed','processing')
     and not exists(select 1 from public.order_separation_completions_v1 where order_id=p_order_id) then
    v_init := public.ops2_init_order_separation_v2(p_order_id);
    if coalesce((v_init->>'ok')::boolean,false) is not true then
      return v_init;
    end if;
  end if;

  select jsonb_build_object(
    'separator_key',a.separator_key,
    'separator_label',a.separator_label,
    'assigned_at',a.assigned_at,
    'updated_at',a.updated_at
  ) into v_assignment
  from public.order_separation_assignments_v1 a
  where a.order_id=p_order_id;

  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'id',s.id,
    'order_item_id',s.order_item_id,
    'product_id',s.product_id,
    'state',s.state,
    'quantity',s.quantity,
    'unit_price',s.unit_price,
    'line_total',s.line_total,
    'changed_at',s.changed_at,
    'changed_by_separator_key',s.changed_by_separator_key,
    'name',oi.name_snapshot,
    'sku',oi.sku_snapshot,
    'image_url',nullif(coalesce(oi.metadata->>'image_url',p.image_url,''),''),
    'basket_name',nullif(oi.metadata->>'basket_name',''),
    'basket_id',nullif(oi.metadata->>'basket_id',''),
    'kind',coalesce(nullif(oi.metadata->>'history_kind',''),'product'),
    'updated_at',s.updated_at
  )) order by oi.created_at,oi.id),'[]'::jsonb)
  into v_items
  from public.order_separation_items_v1 s
  join public.order_items oi on oi.id=s.order_item_id
  left join public.products p on p.id=s.product_id
  where s.order_id=p_order_id
    and not (
      coalesce(oi.metadata->>'history_kind','') in ('basket','basket_mold')
      and exists(
        select 1 from public.order_items c
        where c.order_id=p_order_id
          and coalesce(c.metadata->>'history_kind','') in ('basket_component','basket_mold_component')
          and (
            (
              nullif(oi.metadata->>'basket_id','') is not null
              and nullif(c.metadata->>'basket_id','')=nullif(oi.metadata->>'basket_id','')
            )
            or lower(trim(coalesce(nullif(c.metadata->>'basket_name',''),nullif(c.metadata->>'parent_basket_name',''),'')))
               = lower(trim(coalesce(nullif(oi.metadata->>'basket_name',''),oi.name_snapshot,'')))
          )
      )
    );

  select
    count(*) filter(where s.state='pending'),
    count(*) filter(where s.state='separated'),
    count(*) filter(where s.state='missing'),
    round(coalesce(sum(s.line_total) filter(where s.state='missing'),0)::numeric,2)
  into v_pending,v_separated,v_missing,v_live_missing_subtotal
  from public.order_separation_items_v1 s
  join public.order_items oi on oi.id=s.order_item_id
  where s.order_id=p_order_id
    and not (
      coalesce(oi.metadata->>'history_kind','') in ('basket','basket_mold')
      and exists(
        select 1 from public.order_items c
        where c.order_id=p_order_id
          and coalesce(c.metadata->>'history_kind','') in ('basket_component','basket_mold_component')
          and (
            (
              nullif(oi.metadata->>'basket_id','') is not null
              and nullif(c.metadata->>'basket_id','')=nullif(oi.metadata->>'basket_id','')
            )
            or lower(trim(coalesce(nullif(c.metadata->>'basket_name',''),nullif(c.metadata->>'parent_basket_name',''),'')))
               = lower(trim(coalesce(nullif(oi.metadata->>'basket_name',''),oi.name_snapshot,'')))
          )
      )
    );

  select jsonb_strip_nulls(jsonb_build_object(
    'id',c.id,
    'phase',c.phase,
    'original_total',c.original_total,
    'missing_subtotal',c.missing_subtotal,
    'final_total',c.final_total,
    'separator_key',c.separator_key,
    'prepared_at',c.prepared_at,
    'completed_at',c.completed_at,
    'metadata',c.metadata
  )) into v_completion
  from public.order_separation_completions_v1 c
  where c.order_id=p_order_id;

  v_original_total := round(coalesce((v_completion->>'original_total')::numeric,v_order.total,0)::numeric,2);
  if v_completion is not null and v_completion <> 'null'::jsonb then
    v_live_missing_subtotal := round(coalesce((v_completion->>'missing_subtotal')::numeric,v_live_missing_subtotal,0)::numeric,2);
    v_final_total := round(coalesce((v_completion->>'final_total')::numeric,v_order.total,0)::numeric,2);
  else
    v_final_total := greatest(0,round(v_original_total-v_live_missing_subtotal,2));
  end if;

  return jsonb_build_object(
    'ok',true,
    'order_id',v_order.id,
    'order_number',v_order.order_number,
    'status',v_order.status,
    'order_updated_at',v_order.updated_at,
    'customer_name',coalesce(nullif(v_order.customer_snapshot->>'name',''),nullif(v_order.delivery_address->>'customer_name',''),'Cliente'),
    'delivery',v_order.delivery_address,
    'original_total',v_original_total,
    'missing_subtotal',v_live_missing_subtotal,
    'final_total',v_final_total,
    'total',v_order.total,
    'assignment',coalesce(v_assignment,'null'::jsonb),
    'items',v_items,
    'counts',jsonb_build_object('pending',v_pending,'separated',v_separated,'missing',v_missing,'total',v_pending+v_separated+v_missing),
    'completion',coalesce(v_completion,'null'::jsonb)
  );
end;
$function$
;

-- function: ops2_guard_dispatch_fiscal_job_v1()
CREATE OR REPLACE FUNCTION public.ops2_guard_dispatch_fiscal_job_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  key_digits text;
begin
  if new.status='authorized' then
    key_digits:=regexp_replace(coalesce(new.access_key,''),'[^0-9]','','g');
    if coalesce(new.bling_invoice_id,0)<=0 then
      raise exception 'authorized_fiscal_job_missing_invoice_id';
    end if;
    if length(key_digits)<>44 then
      raise exception 'authorized_fiscal_job_invalid_access_key';
    end if;
    if nullif(trim(coalesce(new.sefaz_status,'')),'') is null then
      raise exception 'authorized_fiscal_job_missing_sefaz_status';
    end if;
    new.finished_at:=coalesce(new.finished_at,now());
  end if;

  if new.status in ('generating','authorizing') and new.attempts>new.max_attempts then
    raise exception 'fiscal_job_attempt_limit_exceeded';
  end if;

  return new;
end;
$function$
;

-- function: ops2_guard_fiscal_runtime_arm_v1()
CREATE OR REPLACE FUNCTION public.ops2_guard_fiscal_runtime_arm_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  p jsonb;
begin
  if new.dispatch_fiscal_canary_enabled=true
     or new.dispatch_invoice_generate_enabled=true
     or new.dispatch_invoice_authorize_enabled=true then

    if new.dispatch_invoice_canary_source_order_id is null then
      raise exception 'fiscal_canary_source_order_required';
    end if;

    p:=public.ops2_fiscal_dispatch_preflight_v1(new.dispatch_invoice_canary_source_order_id);

    if coalesce((p->>'ready')::boolean,false) is not true then
      raise exception 'fiscal_dispatch_preflight_failed:%',coalesce(p->'blockers','[]'::jsonb)::text;
    end if;
  end if;

  return new;
end;
$function$
;

-- function: ops2_init_order_separation_v2(p_order_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_init_order_separation_v2(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_order public.orders%rowtype;
  v_inserted integer:=0;
  v_count integer:=0;
begin
  if p_order_id is null then return jsonb_build_object('ok',false,'error','invalid_order_id'); end if;
  select * into v_order from public.orders where id=p_order_id;
  if not found then return jsonb_build_object('ok',false,'error','order_not_found'); end if;
  if v_order.status not in ('confirmed','processing') then
    return jsonb_build_object('ok',false,'error','order_not_in_separation','status',v_order.status);
  end if;
  if exists(select 1 from public.order_separation_completions_v1 where order_id=p_order_id) then
    select count(*) into v_count
    from public.order_separation_items_v1 s
    join public.order_items oi on oi.id=s.order_item_id
    where s.order_id=p_order_id
      and not (
        coalesce(oi.metadata->>'history_kind','') in ('basket','basket_mold')
        and exists(
          select 1 from public.order_items c
          where c.order_id=p_order_id
            and coalesce(c.metadata->>'history_kind','') in ('basket_component','basket_mold_component')
            and (
              (
                nullif(oi.metadata->>'basket_id','') is not null
                and nullif(c.metadata->>'basket_id','')=nullif(oi.metadata->>'basket_id','')
              )
              or lower(trim(coalesce(nullif(c.metadata->>'basket_name',''),nullif(c.metadata->>'parent_basket_name',''),'')))
                 = lower(trim(coalesce(nullif(oi.metadata->>'basket_name',''),oi.name_snapshot,'')))
            )
        )
      );
    return jsonb_build_object('ok',true,'status','already_completed','item_count',v_count,'order_updated_at',v_order.updated_at);
  end if;

  delete from public.order_separation_items_v1 s
  using public.order_items oi
  where s.order_id=p_order_id
    and s.order_item_id=oi.id
    and oi.order_id=p_order_id
    and coalesce(oi.metadata->>'history_kind','') in ('basket','basket_mold')
    and exists(
      select 1
      from public.order_items c
      where c.order_id=p_order_id
        and coalesce(c.metadata->>'history_kind','') in ('basket_component','basket_mold_component')
        and (
          (
            nullif(oi.metadata->>'basket_id','') is not null
            and nullif(c.metadata->>'basket_id','')=nullif(oi.metadata->>'basket_id','')
          )
          or lower(trim(coalesce(nullif(c.metadata->>'basket_name',''),nullif(c.metadata->>'parent_basket_name',''),'')))
             = lower(trim(coalesce(nullif(oi.metadata->>'basket_name',''),oi.name_snapshot,'')))
        )
    );

  insert into public.order_separation_items_v1(
    order_id,order_item_id,product_id,state,quantity,unit_price,line_total,created_at,updated_at
  )
  select oi.order_id,oi.id,oi.product_id,'pending',oi.quantity,oi.unit_price,oi.line_total,now(),now()
  from public.order_items oi
  where oi.order_id=p_order_id
    and oi.quantity>0
    and not (
      coalesce(oi.metadata->>'history_kind','') in ('basket','basket_mold')
      and exists(
        select 1
        from public.order_items c
        where c.order_id=p_order_id
          and coalesce(c.metadata->>'history_kind','') in ('basket_component','basket_mold_component')
          and (
            (
              nullif(oi.metadata->>'basket_id','') is not null
              and nullif(c.metadata->>'basket_id','')=nullif(oi.metadata->>'basket_id','')
            )
            or lower(trim(coalesce(nullif(c.metadata->>'basket_name',''),nullif(c.metadata->>'parent_basket_name',''),'')))
               = lower(trim(coalesce(nullif(oi.metadata->>'basket_name',''),oi.name_snapshot,'')))
          )
      )
    )
  on conflict (order_id,order_item_id) do update
    set product_id=excluded.product_id,
        quantity=excluded.quantity,
        unit_price=excluded.unit_price,
        line_total=excluded.line_total,
        updated_at=now()
    where public.order_separation_items_v1.state='pending'
      and not exists(
        select 1 from public.order_separation_completions_v1 c
        where c.order_id=public.order_separation_items_v1.order_id
      );

  get diagnostics v_inserted=row_count;
  select count(*) into v_count
  from public.order_separation_items_v1 s
  join public.order_items oi on oi.id=s.order_item_id
  where s.order_id=p_order_id
    and not (
      coalesce(oi.metadata->>'history_kind','') in ('basket','basket_mold')
      and exists(
        select 1 from public.order_items c
        where c.order_id=p_order_id
          and coalesce(c.metadata->>'history_kind','') in ('basket_component','basket_mold_component')
          and (
            (
              nullif(oi.metadata->>'basket_id','') is not null
              and nullif(c.metadata->>'basket_id','')=nullif(oi.metadata->>'basket_id','')
            )
            or lower(trim(coalesce(nullif(c.metadata->>'basket_name',''),nullif(c.metadata->>'parent_basket_name',''),'')))
               = lower(trim(coalesce(nullif(oi.metadata->>'basket_name',''),oi.name_snapshot,'')))
          )
      )
    );
  if v_count=0 and coalesce(jsonb_array_length(coalesce(v_order.checkout_snapshot->'separation_plan','[]'::jsonb)),0)=0 then
    return jsonb_build_object('ok',false,'error','order_has_no_items');
  end if;
  return jsonb_build_object('ok',true,'status','initialized','rows_touched',v_inserted,'item_count',v_count,'order_updated_at',v_order.updated_at);
end;
$function$
;

-- function: ops2_integrated_readiness_summary_v1()
CREATE OR REPLACE FUNCTION public.ops2_integrated_readiness_summary_v1()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
select jsonb_build_object(
 'orders_total',count(*),
 'bling_id_without_sync_proof',count(*) filter(where bling_observability_state='bling_id_without_sync_proof'),
 'legacy_or_missing_ean_evidence',count(*) filter(where evidence_state='legacy_or_missing_ean_evidence'),
 'legacy_or_missing_fiscal_evidence',count(*) filter(where evidence_state='legacy_or_missing_fiscal_evidence'),
 'legacy_or_missing_payment_evidence',count(*) filter(where evidence_state='legacy_or_missing_payment_evidence'),
 'consistent_with_current_evidence',count(*) filter(where evidence_state='consistent_with_current_evidence'),
 'generated_at',now()
) from public.ops2_integrated_order_readiness_v1
$function$
;

-- function: ops2_issue_order_registration_link_v1(p_order_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_issue_order_registration_link_v1(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_order public.orders%rowtype;
  v_customer public.customers%rowtype;
  v_phone text;
  v_token text;
  v_hash text;
  v_id uuid;
  v_expires timestamptz:=now()+interval '24 hours';
begin
  if p_order_id is null then
    return jsonb_build_object('ok',false,'error','order_id_required');
  end if;

  select o.* into v_order
  from public.orders o
  where o.id=p_order_id
  for update;
  if not found then
    return jsonb_build_object('ok',false,'error','order_not_found');
  end if;

  if v_order.customer_id is not null then
    select c.* into v_customer from public.customers c where c.id=v_order.customer_id;
  end if;

  v_phone:=public.canonical_whatsapp_e164_br_v2(coalesce(v_order.phone_e164,v_customer.primary_whatsapp_e164));
  if v_phone is null then
    return jsonb_build_object('ok',false,'error','customer_phone_missing');
  end if;

  update public.ops2_order_registration_links_v1
     set revoked_at=now(),updated_at=now()
   where order_id=p_order_id
     and consumed_at is null
     and revoked_at is null;

  v_token:=encode(extensions.gen_random_bytes(24),'hex');
  v_hash:=encode(extensions.digest(v_token,'sha256'),'hex');

  insert into public.ops2_order_registration_links_v1(order_id,phone_e164,token_hash,expires_at)
  values(p_order_id,v_phone,v_hash,v_expires)
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,
    'link_id',v_id,
    'token',v_token,
    'phone_e164',v_phone,
    'expires_at',v_expires,
    'registration_url','https://www.donaantonia.com.br/cadastro/?order_token='||v_token
  );
end;
$function$
;

-- function: ops2_issue_papoai_catalog_link_v1(p_phone text, p_conversation_id uuid, p_source_event_key text)
CREATE OR REPLACE FUNCTION public.ops2_issue_papoai_catalog_link_v1(p_phone text, p_conversation_id uuid DEFAULT NULL::uuid, p_source_event_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_cfg public.ops2_papoai_bridge_runtime_v1%rowtype;
  v_source_event_key text:=left(trim(coalesce(p_source_event_key,'')),220);
begin
  if v_source_event_key like 'attendance:%' then
    return public.ops2_issue_storefront_catalog_link_v1(p_phone,p_conversation_id,p_source_event_key,'attendance',120);
  end if;
  select * into v_cfg from public.ops2_papoai_bridge_runtime_v1 where id=1;
  if not found or v_cfg.identity_link_enabled is not true then raise exception 'papoai_identity_link_disabled'; end if;
  return public.ops2_issue_storefront_catalog_link_v1(p_phone,p_conversation_id,p_source_event_key,'papoai',v_cfg.identity_link_ttl_minutes);
end;
$function$
;

-- function: ops2_issue_registration_catalog_return_v1(p_customer_id uuid, p_registration_job_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_issue_registration_catalog_return_v1(p_customer_id uuid, p_registration_job_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_customer public.customers%rowtype;
  v_state jsonb;
  v_phone text;
  v_job public.bling_hub_jobs_v2%rowtype;
  v_conversation_id uuid;
  v_whatsapp_account_id uuid;
  v_channel_phone_e164 text;
  v_link jsonb;
  v_gate boolean;
begin
  if p_customer_id is null or p_registration_job_id is null then
    return jsonb_build_object('ok',false,'error','registration_receipt_required');
  end if;

  v_gate:=public.consume_public_rate_limit(
    'registration-catalog-return:job:'||p_registration_job_id::text,
    'registration_catalog_return',
    6,
    600
  );
  if v_gate is distinct from true then
    return jsonb_build_object('ok',false,'error','rate_limited');
  end if;

  select j.* into v_job
  from public.bling_hub_jobs_v2 j
  where j.id=p_registration_job_id
    and j.domain='customer'
    and j.operation='sync_customer'
    and j.source_system='canonical_ssbes'
    and j.source_id=p_customer_id::text;

  if not found then
    return jsonb_build_object('ok',false,'error','invalid_registration_receipt');
  end if;

  select c.* into v_customer
  from public.customers c
  where c.id=p_customer_id;

  if not found then
    return jsonb_build_object('ok',false,'error','customer_not_found');
  end if;

  if v_customer.updated_at < now()-interval '15 minutes' then
    return jsonb_build_object('ok',false,'error','registration_receipt_expired');
  end if;

  v_state:=public.ops2_customer_registration_state_v1(p_customer_id);
  if coalesce((v_state->>'registration_complete')::boolean,false) is not true then
    return jsonb_build_object('ok',false,'error','registration_incomplete');
  end if;

  v_phone:=public.canonical_whatsapp_e164_br_v2(v_customer.primary_whatsapp_e164);
  if v_phone is null then
    return jsonb_build_object('ok',false,'error','customer_phone_missing');
  end if;

  select c.id,c.whatsapp_account_id,wa.phone_e164
    into v_conversation_id,v_whatsapp_account_id,v_channel_phone_e164
  from public.conversations c
  left join public.whatsapp_accounts wa
    on wa.id=c.whatsapp_account_id and wa.is_active=true
  where c.whatsapp_account_id is not null
    and c.updated_at >= now()-interval '31 days'
    and (
      c.customer_id=p_customer_id
      or public.canonical_whatsapp_e164_br_v2(c.wa_contact_e164)=v_phone
    )
  order by
    (c.customer_id=p_customer_id) desc,
    greatest(
      coalesce(c.last_inbound_at,'epoch'::timestamptz),
      coalesce(c.last_outbound_at,'epoch'::timestamptz),
      coalesce(c.updated_at,'epoch'::timestamptz),
      coalesce(c.created_at,'epoch'::timestamptz)
    ) desc
  limit 1;

  begin
    v_link:=public.ops2_issue_storefront_catalog_link_v1(
      v_phone,
      v_conversation_id,
      'registration-return:'||p_registration_job_id::text,
      'registration',
      120
    );
  exception when others then
    return jsonb_build_object('ok',false,'error','catalog_link_unavailable');
  end;

  if coalesce((v_link->>'ok')::boolean,false) is not true then
    return jsonb_build_object('ok',false,'error',coalesce(v_link->>'error','catalog_link_failed'));
  end if;

  return jsonb_build_object(
    'ok',true,
    'customer_id',p_customer_id,
    'conversation_id',v_conversation_id,
    'conversation_found',v_conversation_id is not null,
    'whatsapp_account_id',v_whatsapp_account_id,
    'channel_phone_e164',v_channel_phone_e164,
    'catalog_path',v_link->>'catalog_path',
    'catalog_url','https://www.donaantonia.com.br'||coalesce(v_link->>'catalog_path',''),
    'catalog_expires_at',v_link->>'expires_at',
    'catalog_reused',coalesce((v_link->>'reused')::boolean,false)
  );
end;
$function$
;

-- function: ops2_issue_storefront_catalog_link_v1(p_phone text, p_conversation_id uuid, p_source_event_key text, p_source text, p_ttl_minutes integer)
CREATE OR REPLACE FUNCTION public.ops2_issue_storefront_catalog_link_v1(p_phone text, p_conversation_id uuid DEFAULT NULL::uuid, p_source_event_key text DEFAULT NULL::text, p_source text DEFAULT 'attendance'::text, p_ttl_minutes integer DEFAULT 120)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_phone text;
  v_digits text;
  v_customer_id uuid;
  v_conv public.conversations%rowtype;
  v_existing public.storefront_identity_tokens%rowtype;
  v_code text;
  v_hash text;
  v_exp timestamptz;
  v_try integer:=0;
  v_source text:=lower(coalesce(nullif(btrim(p_source),''),'attendance'));
  v_ttl integer:=greatest(5,least(coalesce(p_ttl_minutes,120),1440));
begin
  if v_source !~ '^[a-z0-9_-]{2,40}$' then raise exception 'invalid_catalog_link_source'; end if;
  v_phone:=public.normalize_storefront_phone_v2(p_phone);
  v_digits:=regexp_replace(coalesce(v_phone,''),'\D','','g');
  if length(v_digits)<10 then raise exception 'invalid_phone'; end if;
  if p_conversation_id is not null then
    select * into v_conv from public.conversations where id=p_conversation_id;
    if not found then raise exception 'conversation_not_found'; end if;
    if regexp_replace(coalesce(v_conv.wa_contact_e164,''),'\D','','g')<>v_digits then raise exception 'conversation_phone_mismatch'; end if;
  end if;
  select c.id into v_customer_id from public.customers c where regexp_replace(coalesce(c.primary_whatsapp_e164,''),'\D','','g')=v_digits limit 1;
  if v_customer_id is null then
    select cp.customer_id into v_customer_id from public.customer_phones cp
    where regexp_replace(coalesce(cp.phone_e164,''),'\D','','g')=v_digits
    order by cp.is_primary desc,cp.created_at asc limit 1;
  end if;
  if p_conversation_id is not null and v_conv.customer_id is not null then
    if v_customer_id is not null and v_customer_id<>v_conv.customer_id then raise exception 'conversation_customer_conflict'; end if;
    v_customer_id:=v_conv.customer_id;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('ops2:storefront:identity:'||v_digits,0));
  select * into v_existing from public.storefront_identity_tokens t
  where regexp_replace(coalesce(t.phone_e164,''),'\D','','g')=v_digits
    and t.redeemed_at is null and t.expires_at>now()
    and (p_conversation_id is null or t.conversation_id=p_conversation_id)
  order by t.created_at desc limit 1 for update;
  if found then
    return jsonb_build_object('ok',true,'reused',true,'token_id',v_existing.id,'short_code',v_existing.short_code,
      'catalog_path','/catalogo_'||v_existing.short_code,'expires_at',v_existing.expires_at,
      'customer_linked',v_existing.customer_id is not null,'conversation_linked',v_existing.conversation_id is not null,'source',v_existing.source);
  end if;
  perform pg_advisory_xact_lock(hashtextextended('ops2:storefront:identity-code-pool',0));
  v_exp:=now()+make_interval(mins=>v_ttl);
  loop
    v_try:=v_try+1;
    if v_try>60 then raise exception 'identity_code_pool_busy'; end if;
    v_code:=lpad((1000+floor(random()*9000)::integer)::text,4,'0');
    exit when not exists(select 1 from public.storefront_identity_tokens where short_code=v_code and redeemed_at is null and expires_at>now());
  end loop;
  v_hash:=encode(digest(v_code,'sha256'),'hex');
  insert into public.storefront_identity_tokens(token_hash,phone_e164,contact_name,source,expires_at,use_count,short_code,conversation_id,customer_id,source_event_key)
  values(v_hash,v_phone,null,v_source,v_exp,0,v_code,p_conversation_id,v_customer_id,nullif(left(trim(coalesce(p_source_event_key,'')),220),''))
  returning * into v_existing;
  return jsonb_build_object('ok',true,'reused',false,'token_id',v_existing.id,'short_code',v_code,'catalog_path','/catalogo_'||v_code,
    'expires_at',v_exp,'customer_linked',v_customer_id is not null,'conversation_linked',p_conversation_id is not null,'source',v_source);
end;
$function$
;

-- function: ops2_link_papoai_capture_order_v1(p_capture_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_link_papoai_capture_order_v1(p_capture_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row public.papoai_webhook_inbox_v2%rowtype;
  v_content text;
  v_suffix text;
  v_conversation_id uuid;
  v_customer_id uuid;
  v_account_id uuid;
  v_phone text;
  v_order public.orders%rowtype;
  v_count integer:=0;
  v_reason text:=null;
begin
  select * into v_row
  from public.papoai_webhook_inbox_v2
  where id=p_capture_id
  for update;

  if not found then return jsonb_build_object('ok',false,'error','capture_not_found'); end if;
  if coalesce(v_row.event_name,'')<>'message.received' then
    return jsonb_build_object('ok',true,'linked',false,'reason','not_inbound_message');
  end if;

  begin v_conversation_id:=nullif(v_row.metadata->>'conversation_id','')::uuid; exception when others then v_conversation_id:=null; end;
  begin v_customer_id:=nullif(v_row.metadata->>'customer_id','')::uuid; exception when others then v_customer_id:=null; end;
  begin v_account_id:=nullif(v_row.metadata->>'whatsapp_account_id','')::uuid; exception when others then v_account_id:=null; end;
  v_phone:=public.canonical_whatsapp_e164_br_v2(coalesce(v_row.metadata->>'canonical_phone_e164',v_row.phone_candidate));

  if v_conversation_id is null then
    return jsonb_build_object('ok',true,'linked',false,'reason','conversation_not_linked');
  end if;

  v_content:=coalesce(
    v_row.payload#>>'{data,message,content}',
    v_row.payload#>>'{data,message,text}',
    v_row.payload#>>'{data,message,body}',
    ''
  );
  select upper((regexp_match(v_content,'NUMERO:[[:space:]]*([A-Fa-f0-9]{8})'))[1]) into v_suffix;

  if v_suffix is not null then
    select count(*) into v_count
    from public.orders o
    where o.source in ('vitrine','storefront_v2')
      and upper(right(coalesce(o.order_number,''),8))=v_suffix
      and o.created_at between v_row.received_at-interval '12 hours' and v_row.received_at+interval '30 minutes'
      and (v_customer_id is null or o.customer_id is null or o.customer_id=v_customer_id)
      and (v_phone is null or public.normalize_phone_digits(o.phone_e164)=any(public.phone_variants_br(v_phone)));

    if v_count=1 then
      select * into v_order
      from public.orders o
      where o.source in ('vitrine','storefront_v2')
        and upper(right(coalesce(o.order_number,''),8))=v_suffix
        and o.created_at between v_row.received_at-interval '12 hours' and v_row.received_at+interval '30 minutes'
        and (v_customer_id is null or o.customer_id is null or o.customer_id=v_customer_id)
        and (v_phone is null or public.normalize_phone_digits(o.phone_e164)=any(public.phone_variants_br(v_phone)))
      order by o.created_at desc
      limit 1
      for update;
      v_reason:='order_number_exact';
    elsif v_count>1 then
      return jsonb_build_object('ok',true,'linked',false,'reason','order_number_ambiguous','suffix',v_suffix,'matches',v_count);
    end if;
  end if;

  if v_order.id is null then
    select count(*) into v_count
    from public.orders o
    where o.source in ('vitrine','storefront_v2')
      and o.conversation_id is null
      and o.created_at between v_row.received_at-interval '6 hours' and v_row.received_at+interval '30 minutes'
      and (
        (v_customer_id is not null and o.customer_id=v_customer_id)
        or (v_phone is not null and public.normalize_phone_digits(o.phone_e164)=any(public.phone_variants_br(v_phone)))
      );

    if v_count=1 then
      select * into v_order
      from public.orders o
      where o.source in ('vitrine','storefront_v2')
        and o.conversation_id is null
        and o.created_at between v_row.received_at-interval '6 hours' and v_row.received_at+interval '30 minutes'
        and (
          (v_customer_id is not null and o.customer_id=v_customer_id)
          or (v_phone is not null and public.normalize_phone_digits(o.phone_e164)=any(public.phone_variants_br(v_phone)))
        )
      order by o.created_at desc
      limit 1
      for update;
      v_reason:='single_recent_customer_order';
    elsif v_count>1 then
      return jsonb_build_object('ok',true,'linked',false,'reason','recent_order_ambiguous','matches',v_count);
    else
      return jsonb_build_object('ok',true,'linked',false,'reason',case when v_suffix is null then 'order_marker_missing_no_fallback' else 'order_not_found' end,'suffix',v_suffix);
    end if;
  end if;

  if v_order.conversation_id is not null and v_order.conversation_id<>v_conversation_id then
    return jsonb_build_object('ok',true,'linked',false,'reason','order_already_linked_elsewhere','order_id',v_order.id,'order_number',v_order.order_number);
  end if;

  update public.orders
     set conversation_id=v_conversation_id,
         whatsapp_account_id=coalesce(whatsapp_account_id,v_account_id),
         customer_id=coalesce(customer_id,v_customer_id),
         checkout_snapshot=coalesce(checkout_snapshot,'{}'::jsonb)
           || jsonb_strip_nulls(jsonb_build_object(
             'papoai_order_linked',true,
             'papoai_order_link_reason',v_reason,
             'papoai_capture_id',p_capture_id,
             'papoai_order_linked_at',now()
           )),
         updated_at=now()
   where id=v_order.id;

  update public.papoai_webhook_inbox_v2
     set metadata=coalesce(metadata,'{}'::jsonb)
       || jsonb_build_object(
         'order_id',v_order.id,
         'order_number',v_order.order_number,
         'order_linked',true,
         'order_link_reason',v_reason
       )
   where id=p_capture_id;

  return jsonb_build_object('ok',true,'linked',true,'order_id',v_order.id,'order_number',v_order.order_number,'conversation_id',v_conversation_id,'reason',v_reason);
end;
$function$
;

-- function: ops2_link_storefront_order_from_identity_v1(p_order_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_link_storefront_order_from_identity_v1(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_order public.orders%rowtype;
  v_digits text;
  v_token public.storefront_identity_tokens%rowtype;
  v_matches integer:=0;
begin
  select * into v_order from public.orders where id=p_order_id for update;
  if not found then raise exception 'order_not_found'; end if;

  if v_order.source<>'vitrine' then
    return jsonb_build_object('ok',true,'linked',false,'reason','order_source_not_vitrine');
  end if;

  if v_order.conversation_id is not null then
    return jsonb_build_object('ok',true,'linked',true,'idempotent_replay',true,
      'conversation_id',v_order.conversation_id,'customer_id',v_order.customer_id);
  end if;

  v_digits:=regexp_replace(coalesce(v_order.phone_e164,''),'\D','','g');
  if length(v_digits)<10 then
    return jsonb_build_object('ok',true,'linked',false,'reason','order_phone_missing');
  end if;

  select count(*) into v_matches
  from public.storefront_identity_tokens t
  where regexp_replace(coalesce(t.phone_e164,''),'\D','','g')=v_digits
    and t.redeemed_at is not null
    and t.redeemed_at>=v_order.created_at-interval '30 minutes'
    and t.redeemed_at<=v_order.created_at+interval '6 hours'
    and t.conversation_id is not null;

  if v_matches=0 then
    return jsonb_build_object('ok',true,'linked',false,'reason','no_redeemed_identity_link');
  end if;

  select * into v_token
  from public.storefront_identity_tokens t
  where regexp_replace(coalesce(t.phone_e164,''),'\D','','g')=v_digits
    and t.redeemed_at is not null
    and t.redeemed_at>=v_order.created_at-interval '30 minutes'
    and t.redeemed_at<=v_order.created_at+interval '6 hours'
    and t.conversation_id is not null
  order by t.redeemed_at desc
  limit 1;

  if exists(
    select 1 from public.storefront_identity_tokens t
    where regexp_replace(coalesce(t.phone_e164,''),'\D','','g')=v_digits
      and t.redeemed_at is not null
      and t.redeemed_at>=v_order.created_at-interval '30 minutes'
      and t.redeemed_at<=v_order.created_at+interval '6 hours'
      and t.conversation_id is not null
      and t.conversation_id<>v_token.conversation_id
  ) then
    return jsonb_build_object('ok',true,'linked',false,'reason','identity_conversation_ambiguous');
  end if;

  if not exists(
    select 1 from public.conversations c
    where c.id=v_token.conversation_id
      and regexp_replace(coalesce(c.wa_contact_e164,''),'\D','','g')=v_digits
  ) then
    return jsonb_build_object('ok',true,'linked',false,'reason','identity_conversation_phone_mismatch');
  end if;

  update public.orders
     set conversation_id=v_token.conversation_id,
         whatsapp_account_id=coalesce(whatsapp_account_id,(select c.whatsapp_account_id from public.conversations c where c.id=v_token.conversation_id)),
         customer_id=coalesce(customer_id,v_token.customer_id),
         checkout_snapshot=coalesce(checkout_snapshot,'{}'::jsonb)
           || jsonb_build_object(
             'papoai_identity_token_id',v_token.id,
             'papoai_identity_redeemed_at',v_token.redeemed_at,
             'papoai_conversation_linked',true
           ),
         updated_at=now()
   where id=p_order_id;

  return jsonb_build_object(
    'ok',true,'linked',true,'conversation_id',v_token.conversation_id,
    'customer_id',coalesce(v_order.customer_id,v_token.customer_id),
    'identity_token_id',v_token.id
  );
end;
$function$
;

-- function: ops2_mark_order_separation_completion_v2(p_order_id uuid, p_phase text, p_metadata jsonb)
CREATE OR REPLACE FUNCTION public.ops2_mark_order_separation_completion_v2(p_order_id uuid, p_phase text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_phase text := lower(trim(coalesce(p_phase,'')));
  v_now timestamptz := now();
  v_row public.order_separation_completions_v1%rowtype;
begin
  if v_phase not in ('prepared','stock_applied','bling_verified','ready','physical_stock_launched','needs_attention','completed') then
    return jsonb_build_object('ok',false,'error','invalid_completion_phase');
  end if;

  update public.order_separation_completions_v1
  set phase=v_phase,
      metadata=coalesce(metadata,'{}'::jsonb) || coalesce(p_metadata,'{}'::jsonb),
      completed_at=case when v_phase='completed' then coalesce(completed_at,v_now) else completed_at end,
      updated_at=v_now
  where order_id=p_order_id
  returning * into v_row;

  if not found then
    return jsonb_build_object('ok',false,'error','separation_completion_not_found');
  end if;

  return jsonb_build_object(
    'ok',true,
    'order_id',p_order_id,
    'phase',v_row.phase,
    'original_total',v_row.original_total,
    'missing_subtotal',v_row.missing_subtotal,
    'final_total',v_row.final_total,
    'completed_at',v_row.completed_at,
    'metadata',v_row.metadata
  );
end;
$function$
;

-- function: ops2_materialize_catalog_bindings_v1(p_run uuid)
CREATE OR REPLACE FUNCTION public.ops2_materialize_catalog_bindings_v1(p_run uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_updated int:=0; v_events int:=0;
begin
 if exists(select 1 from ops2_catalog_baseline_items where run_id=p_run and identity_state<>'unique_mirror_identity') then raise exception 'identity_gate_failed'; end if;
 if exists(select 1 from products p join ops2_catalog_baseline_items b on b.product_id=p.id and b.run_id=p_run where p.bling_product_id is not null and p.bling_product_id<>b.bling_product_id) then raise exception 'existing_binding_conflict'; end if;
 update products p set bling_product_id=b.bling_product_id
 from ops2_catalog_baseline_items b
 where b.run_id=p_run and b.product_id=p.id and b.identity_state='unique_mirror_identity' and p.bling_product_id is null;
 get diagnostics v_updated=row_count;
 insert into bling_product_binding_events(product_id,bling_product_id,binding_source,external_key)
 select b.product_id,b.bling_product_id,'ops2_verified_mirror_baseline',p_run::text
 from ops2_catalog_baseline_items b
 where b.run_id=p_run and b.identity_state='unique_mirror_identity'
 and not exists(select 1 from bling_product_binding_events e where e.product_id=b.product_id and e.bling_product_id=b.bling_product_id and e.external_key=p_run::text);
 get diagnostics v_events=row_count;
 return jsonb_build_object('run_id',p_run,'products_materialized',v_updated,'binding_events',v_events);
end $function$
;

-- function: ops2_maybe_enqueue_customer_bling_v1(p_customer_id uuid, p_reason text)
CREATE OR REPLACE FUNCTION public.ops2_maybe_enqueue_customer_bling_v1(p_customer_id uuid, p_reason text DEFAULT 'registration_state_change'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_state jsonb;
  v_customer public.customers%rowtype;
  v_address_updated_at timestamptz;
  v_existing uuid;
  v_job uuid;
  v_fingerprint text;
begin
  if p_customer_id is null then return null; end if;

  select * into v_customer
  from public.customers
  where id=p_customer_id;
  if not found then return null; end if;

  v_state:=public.ops2_customer_registration_state_v1(p_customer_id);

  -- Never create a new Bling contact until the canonical registration is complete.
  -- Already-linked contacts may still be updated when relevant registration data changes.
  if coalesce((v_state->>'bling_ready')::boolean,false)=false then
    return null;
  end if;

  -- Avoid parallel duplicate work for the same customer.
  select j.id into v_existing
  from public.bling_hub_jobs_v2 j
  where j.domain='customer'
    and j.operation='sync_customer'
    and j.source_system='canonical_ssbes'
    and j.source_id=p_customer_id::text
    and j.status in ('pending','processing','retry')
  order by j.created_at desc,j.id desc
  limit 1;
  if v_existing is not null then return v_existing; end if;

  select max(a.updated_at) into v_address_updated_at
  from public.customer_addresses a
  where a.customer_id=p_customer_id and a.is_active=true;

  v_fingerprint:=md5(
    coalesce(v_state::text,'')||'|'||
    coalesce(v_customer.updated_at::text,'')||'|'||
    coalesce(v_address_updated_at::text,'')
  );

  v_job:=public.enqueue_bling_hub_job_v2(
    'customer',
    'sync_customer',
    'canonical_ssbes',
    p_customer_id::text,
    'canonical_ssbes:customer:'||p_customer_id::text||':registration:'||v_fingerprint,
    jsonb_build_object(
      'customer_id',p_customer_id,
      'allow_create',true,
      'requested_from','registration_state_trigger',
      'reason',coalesce(nullif(trim(p_reason),''),'registration_state_change'),
      'canonical_registration_state',v_state
    ),
    1
  );

  return v_job;
end;
$function$
;

-- function: ops2_meta_dispatch_readiness_v1(p_intent_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_meta_dispatch_readiness_v1(p_intent_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_intent public.ops2_papoai_outbound_intents_v1%rowtype;
  v_route jsonb;
  v_guard jsonb;
  v_account_id uuid;
  v_sender public.ops2_meta_whatsapp_senders_v1%rowtype;
  v_flow public.ops2_meta_whatsapp_flow_bindings_v1%rowtype;
  v_route_available boolean:=false;
  v_ready boolean:=false;
begin
  select i.* into v_intent
  from public.ops2_papoai_outbound_intents_v1 i
  where i.id=p_intent_id;
  if not found then
    return jsonb_build_object('ok',false,'error','intent_not_found','ready',false);
  end if;

  v_route:=public.ops2_papoai_route_context_v1(v_intent.order_id);
  v_route_available:=coalesce((v_route->>'route_available')::boolean,false);
  if v_route_available then
    v_account_id:=nullif(v_route->>'whatsapp_account_id','')::uuid;
  end if;

  if v_account_id is not null then
    select s.* into v_sender
    from public.ops2_meta_whatsapp_senders_v1 s
    where s.whatsapp_account_id=v_account_id;

    select f.* into v_flow
    from public.ops2_meta_whatsapp_flow_bindings_v1 f
    where f.whatsapp_account_id=v_account_id
      and f.purpose=v_intent.purpose;
  end if;

  v_guard:=public.ops2_papoai_dispatch_guard_v1(p_intent_id);

  v_ready:=v_route_available
    and v_sender.whatsapp_account_id is not null
    and coalesce(v_sender.is_verified,false)
    and coalesce(v_sender.is_send_enabled,false)
    and v_flow.id is not null
    and coalesce(v_flow.is_verified,false)
    and coalesce(v_flow.is_send_enabled,false)
    and coalesce((v_guard->>'allowed')::boolean,false);

  return jsonb_build_object(
    'ok',true,
    'intent_id',p_intent_id,
    'purpose',v_intent.purpose,
    'ready',v_ready,
    'guard_allowed',coalesce((v_guard->>'allowed')::boolean,false),
    'guard_reason',v_guard->>'reason',
    'route_available',v_route_available,
    'whatsapp_account_id',v_account_id,
    'sender_present',v_sender.whatsapp_account_id is not null,
    'sender_verified',coalesce(v_sender.is_verified,false),
    'sender_send_enabled',coalesce(v_sender.is_send_enabled,false),
    'flow_binding_present',v_flow.id is not null,
    'flow_verified',coalesce(v_flow.is_verified,false),
    'flow_send_enabled',coalesce(v_flow.is_send_enabled,false)
  );
end;
$function$
;

-- function: ops2_operational_ux_state_v1()
CREATE OR REPLACE FUNCTION public.ops2_operational_ux_state_v1()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
with o as (
 select
  count(*) filter (where status='created') created,
  count(*) filter (where status='confirmed') confirmed,
  count(*) filter (where status='processing') processing,
  count(*) filter (where status='ready') ready,
  count(*) filter (where status='out_for_delivery') out_for_delivery
 from public.orders
),
a as (
 select
  count(*) filter (where status in ('open','acknowledged')) open_attention,
  count(*) filter (where status in ('open','acknowledged') and priority in ('high','critical')) urgent_attention
 from public.ops_attention
),
r as (
 select count(*) filter (where status='returned_review') return_review
 from public.order_delivery_return_cases
),
p as (
 select count(*) filter (where status in ('queued','presented')) pending_prints
 from public.ops_print_jobs
)
select jsonb_build_object(
 'orders',jsonb_build_object(
   'new',o.created,'confirmed',o.confirmed,'separating',o.processing,
   'ready',o.ready,'on_route',o.out_for_delivery
 ),
 'attention',jsonb_build_object('open',a.open_attention,'urgent',a.urgent_attention),
 'returns',jsonb_build_object('needs_review',r.return_review),
 'printing',jsonb_build_object('pending',p.pending_prints),
 'recommended_surface',
 case
   when a.urgent_attention>0 then 'central_attention'
   when r.return_review>0 then 'inventory_returns'
   when o.processing>0 then 'tablet_separation'
   when o.ready>0 then 'dispatch'
   when o.out_for_delivery>0 then 'driver'
   when o.created+o.confirmed>0 then 'orders'
   else 'central'
 end,
 'generated_at',now()
)
from o,a,r,p
$function$
;

-- function: ops2_order_delivery_number_fill_v1()
CREATE OR REPLACE FUNCTION public.ops2_order_delivery_number_fill_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_street text;
  v_number text;
begin
  if new.delivery_address is null or jsonb_typeof(new.delivery_address)<>'object' then return new; end if;
  if nullif(btrim(coalesce(new.delivery_address->>'number','')),'') is not null then return new; end if;
  v_street:=nullif(btrim(coalesce(new.delivery_address->>'street','')),'');
  if v_street is null then return new; end if;
  v_number:=public.ops2_extract_address_number_v1(v_street);
  if v_number is not null then
    new.delivery_address:=new.delivery_address||jsonb_build_object('number',v_number);
  end if;
  return new;
end;
$function$
;

