-- function: ops2_orders_ensure_site_customer_v1()
CREATE OR REPLACE FUNCTION public.ops2_orders_ensure_site_customer_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_name text;
  v_identity jsonb;
  v_customer_id uuid;
  v_phone text;
begin
  if new.source not in ('vitrine','storefront_v2') then
    return new;
  end if;

  v_name:=nullif(btrim(coalesce(
    new.customer_snapshot->>'name',
    new.customer_snapshot->>'display_name',
    new.delivery_address->>'customer_name',
    new.checkout_snapshot#>>'{customer,display_name}'
  )), '');

  if new.customer_id is null
     and nullif(btrim(coalesce(new.phone_e164,'')),'') is not null
  then
    v_identity:=public.ensure_storefront_customer_v2(
      new.phone_e164,
      v_name,
      coalesce(new.order_number,new.id::text)
    );

    if coalesce((v_identity->>'ok')::boolean,false) is true then
      v_customer_id:=(v_identity->>'customer_id')::uuid;
      v_phone:=v_identity->>'canonical_phone_e164';
      new.customer_id:=v_customer_id;
      new.phone_e164:=coalesce(v_phone,new.phone_e164);
      new.customer_snapshot:=coalesce(new.customer_snapshot,'{}'::jsonb)
        || jsonb_strip_nulls(jsonb_build_object(
          'customer_id',v_customer_id,
          'phone_e164',coalesce(v_phone,new.phone_e164),
          'identity_status',v_identity->>'status'
        ));
      new.delivery_address:=coalesce(new.delivery_address,'{}'::jsonb)
        || jsonb_build_object('source_customer_id',v_customer_id);
    end if;
  end if;

  return new;
end;
$function$
;

-- function: ops2_papoai_attendance_provider_store_v1(p_channel text, p_url text)
CREATE OR REPLACE FUNCTION public.ops2_papoai_attendance_provider_store_v1(p_channel text, p_url text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_name text;
  v_url text;
  v_secret_id uuid;
  v_description text;
begin
  v_name:=case btrim(coalesce(p_channel,''))
    when '0975' then 'papoai_attendance_text_webhook_0975_url_v1'
    when '1018' then 'papoai_attendance_text_webhook_1018_url_v1'
    else null
  end;
  if v_name is null then return jsonb_build_object('ok',false,'error','unsupported_channel'); end if;

  v_url:=nullif(btrim(coalesce(p_url,'')),'');
  if v_url is null or length(v_url)>2048 or v_url !~* '^https://webpublic\.papoai\.com\.br(?:/|$)' then
    return jsonb_build_object('ok',false,'error','invalid_provider_url','channel',p_channel);
  end if;

  v_description:=format('Dona Antônia PapoAI attendance text webhook %s',p_channel);
  select s.id into v_secret_id
  from vault.secrets s
  where s.name=v_name
  order by s.updated_at desc nulls last,s.created_at desc
  limit 1;

  if v_secret_id is null then
    v_secret_id:=vault.create_secret(v_url,v_name,v_description,null);
  else
    perform vault.update_secret(v_secret_id,v_url,v_name,v_description,null);
  end if;

  return jsonb_build_object('ok',true,'channel',p_channel,'stored',true);
end;
$function$
;

-- function: ops2_papoai_attendance_provider_url_v1(p_channel text)
CREATE OR REPLACE FUNCTION public.ops2_papoai_attendance_provider_url_v1(p_channel text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_name text;
  v_secret text;
begin
  v_name:=case btrim(coalesce(p_channel,''))
    when '0975' then 'papoai_attendance_text_webhook_0975_url_v1'
    when '1018' then 'papoai_attendance_text_webhook_1018_url_v1'
    else null
  end;
  if v_name is null then return null; end if;

  select ds.decrypted_secret into v_secret
  from vault.decrypted_secrets ds
  where ds.name=v_name
  order by ds.updated_at desc nulls last,ds.created_at desc
  limit 1;

  v_secret:=nullif(btrim(coalesce(v_secret,'')),'');
  if v_secret is null or v_secret !~* '^https://webpublic\.papoai\.com\.br(?:/|$)' then
    return null;
  end if;
  return v_secret;
end;
$function$
;

-- function: ops2_papoai_capture_order_link_trigger_v1()
CREATE OR REPLACE FUNCTION public.ops2_papoai_capture_order_link_trigger_v1()
 RETURNS trigger
 LANGUAGE plpgsql
