$function$
;

-- function: ops2_papoai_dispatch_guard_v1(p_intent_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_papoai_dispatch_guard_v1(p_intent_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_intent public.ops2_papoai_outbound_intents_v1%rowtype;
  v_runtime public.ops2_papoai_outbound_runtime_v1%rowtype;
  v_journey public.ops2_customer_registration_journeys_v1%rowtype;
  v_order public.orders%rowtype;
  v_customer public.customers%rowtype;
  v_route jsonb;
  v_route_account uuid;
  v_route_conversation uuid;
  v_route_agentbot text;
  v_route_channel text;
  v_route_session text;
  v_route_contact text;
  v_binding public.ops2_papoai_channel_bindings_v1%rowtype;
  v_target_phone text;
begin
  select i.* into v_intent
  from public.ops2_papoai_outbound_intents_v1 i
  where i.id=p_intent_id;
  if not found then
    return jsonb_build_object('ok',false,'allowed',false,'reason','intent_not_found','intent_id',p_intent_id);
  end if;

  if v_intent.purpose<>'registration_flow' then
    return jsonb_build_object('ok',true,'allowed',false,'reason','unsupported_purpose','intent_id',p_intent_id);
  end if;

  if v_intent.status in ('sent','cancelled') then
    return jsonb_build_object('ok',true,'allowed',false,'reason','intent_terminal','intent_id',p_intent_id,'status',v_intent.status);
  end if;

  select r.* into v_runtime from public.ops2_papoai_outbound_runtime_v1 r where r.id=1;
  if not found then
    return jsonb_build_object('ok',false,'allowed',false,'reason','runtime_missing','intent_id',p_intent_id);
  end if;

  if coalesce(v_runtime.transport_verified,false)=false then
    return jsonb_build_object('ok',true,'allowed',false,'reason','transport_unverified','intent_id',p_intent_id,'dispatch_mode',v_runtime.dispatch_mode);
  end if;

  if coalesce(v_runtime.dispatch_enabled,false)=false then
    return jsonb_build_object('ok',true,'allowed',false,'reason','dispatch_disabled','intent_id',p_intent_id,'dispatch_mode',v_runtime.dispatch_mode);
  end if;

  if v_runtime.dispatch_mode='disabled' then
    return jsonb_build_object('ok',true,'allowed',false,'reason','dispatch_mode_disabled','intent_id',p_intent_id);
  end if;

  select j.* into v_journey
  from public.ops2_customer_registration_journeys_v1 j
  where j.order_id=v_intent.order_id;
  if not found or v_journey.registration_state<>'pending' or v_journey.workflow_open=false then
    return jsonb_build_object('ok',true,'allowed',false,'reason','registration_not_pending','intent_id',p_intent_id);
  end if;

  if v_journey.transition_seq<>v_intent.transition_seq then
    return jsonb_build_object('ok',true,'allowed',false,'reason','stale_transition','intent_id',p_intent_id,'current_transition_seq',v_journey.transition_seq,'intent_transition_seq',v_intent.transition_seq);
  end if;

  v_route:=public.ops2_papoai_route_context_v1(v_intent.order_id);
  if coalesce((v_route->>'route_available')::boolean,false)=false then
    return jsonb_build_object('ok',true,'allowed',false,'reason',coalesce(v_route->>'reason','route_unavailable'),'intent_id',p_intent_id);
  end if;

  v_route_account:=nullif(v_route->>'whatsapp_account_id','')::uuid;
  v_route_conversation:=nullif(v_route->>'conversation_id','')::uuid;
  v_route_agentbot:=nullif(v_route->>'papoai_agentbot_id','');
  v_route_channel:=nullif(v_route->>'channel_phone_e164','');
  v_route_session:=nullif(v_route->>'papoai_session_uid','');
  v_route_contact:=nullif(v_route->>'papoai_contact_id','');

  select b.* into v_binding
  from public.ops2_papoai_channel_bindings_v1 b
  where b.whatsapp_account_id=v_route_account
    and b.is_active=true;
  if not found then
    return jsonb_build_object('ok',true,'allowed',false,'reason','channel_binding_missing','intent_id',p_intent_id);
  end if;

  if v_binding.papoai_agentbot_id is distinct from v_route_agentbot then
    return jsonb_build_object('ok',true,'allowed',false,'reason','agentbot_binding_mismatch','intent_id',p_intent_id);
  end if;

  if v_binding.expected_phone_e164 is distinct from v_route_channel then
    return jsonb_build_object('ok',true,'allowed',false,'reason','channel_phone_mismatch','intent_id',p_intent_id);
  end if;

  select o.* into v_order from public.orders o where o.id=v_intent.order_id;
  select c.* into v_customer from public.customers c where c.id=v_order.customer_id;
  v_target_phone:=public.canonical_whatsapp_e164_br_v2(coalesce(nullif(v_order.phone_e164,''),nullif(v_customer.primary_whatsapp_e164,'')));
  if v_target_phone is null then
    return jsonb_build_object('ok',true,'allowed',false,'reason','target_phone_missing','intent_id',p_intent_id);
  end if;

  if v_runtime.dispatch_mode='homologation' and not exists (
    select 1 from public.ops2_papoai_homologation_targets_v1 h
    where h.target_phone_e164=v_target_phone and h.is_active=true
  ) then
    return jsonb_build_object('ok',true,'allowed',false,'reason','target_not_allowlisted','intent_id',p_intent_id,'target_phone_e164',v_target_phone);
  end if;

  if v_runtime.dispatch_mode not in ('homologation','production') then
    return jsonb_build_object('ok',true,'allowed',false,'reason','invalid_dispatch_mode','intent_id',p_intent_id);
  end if;

  return jsonb_build_object(
    'ok',true,
    'allowed',true,
    'reason','guard_passed',
    'intent_id',p_intent_id,
    'order_id',v_intent.order_id,
    'dispatch_mode',v_runtime.dispatch_mode,
    'target_phone_e164',v_target_phone,
    'conversation_id',v_route_conversation,
    'whatsapp_account_id',v_route_account,
    'channel_phone_e164',v_route_channel,
    'papoai_session_uid',v_route_session,
    'papoai_contact_id',v_route_contact,
    'papoai_agentbot_id',v_route_agentbot,
    'transition_seq',v_journey.transition_seq
  );
end;
$function$
;

-- function: ops2_papoai_flow_text_field_v1(p_text text, p_key text)
CREATE OR REPLACE FUNCTION public.ops2_papoai_flow_text_field_v1(p_text text, p_key text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select nullif(btrim(regexp_replace(line,'^[^:]+:\s*','','i')),'')
  from regexp_split_to_table(coalesce(p_text,''),E'\r?\n') line
  where lower(btrim(split_part(line,':',1)))=lower(btrim(coalesce(p_key,'')))
  limit 1
$function$
;

-- function: ops2_papoai_operational_summary_v1()
CREATE OR REPLACE FUNCTION public.ops2_papoai_operational_summary_v1()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
select jsonb_build_object(
 'capture_enabled',(select capture_enabled from public.papoai_webhook_runtime_v2 where id=1),
 'last_seen_at',(select last_seen_at from public.papoai_webhook_runtime_v2 where id=1),
 'last_event_key',(select last_event_key from public.papoai_webhook_runtime_v2 where id=1),
 'last_runtime_error',(select last_error from public.papoai_webhook_runtime_v2 where id=1),
 'events_total',(select count(*) from public.papoai_webhook_inbox_v2),
 'events_processed',(select count(*) from public.papoai_webhook_inbox_v2 where processed_at is not null),
 'events_with_error',(select count(*) from public.papoai_webhook_inbox_v2 where last_error is not null),
 'events_without_phone',(select count(*) from public.papoai_webhook_inbox_v2 where nullif(phone_candidate,'') is null),
 'drafts_total',(select count(*) from public.papoai_order_drafts_v2),
 'drafts_confirmed_without_order',(select count(*) from public.papoai_order_drafts_v2 where status='confirmed' and canonical_order_id is null),
 'orders_linked',(select count(*) from public.papoai_order_drafts_v2 where canonical_order_id is not null),
 'identity_tokens_total',(select count(*) from public.storefront_identity_tokens),
 'generated_at',now()
)
$function$
;

-- function: ops2_papoai_order_provider_store_v1(p_channel text, p_url text)
CREATE OR REPLACE FUNCTION public.ops2_papoai_order_provider_store_v1(p_channel text, p_url text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_name text;
  v_url text;
  v_secret_id uuid;
  v_description text;
begin
  v_name:=case btrim(coalesce(p_channel,''))
    when '0975' then 'papoai_order_template_webhook_0975_url_v1'
    when '1018' then 'papoai_order_template_webhook_1018_url_v1'
    else null
  end;

  if v_name is null then
    return jsonb_build_object('ok',false,'error','unsupported_channel');
  end if;

  v_url:=nullif(btrim(coalesce(p_url,'')),'');
  if v_url is null or length(v_url)>2048 or v_url !~* '^https://[^[:space:]]+$' then
    return jsonb_build_object('ok',false,'error','invalid_https_url','channel',p_channel);
  end if;

  v_description:=format('Dona Antônia PapoAI order template webhook %s',p_channel);

  select s.id into v_secret_id
  from vault.secrets s
  where s.name=v_name
  order by s.updated_at desc nulls last,s.created_at desc
  limit 1;

  if v_secret_id is null then
    v_secret_id:=vault.create_secret(v_url,v_name,v_description,null);
  else
    perform vault.update_secret(v_secret_id,v_url,v_name,v_description,null);
  end if;

  return jsonb_build_object('ok',true,'channel',p_channel,'stored',true);
end;
$function$
;

-- function: ops2_papoai_order_provider_url_v1(p_channel text)
CREATE OR REPLACE FUNCTION public.ops2_papoai_order_provider_url_v1(p_channel text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_name text;
  v_secret text;
begin
  v_name:=case btrim(coalesce(p_channel,''))
    when '0975' then 'papoai_order_template_webhook_0975_url_v1'
    when '1018' then 'papoai_order_template_webhook_1018_url_v1'
    else null
  end;

  if v_name is null then return null; end if;

  select ds.decrypted_secret
    into v_secret
  from vault.decrypted_secrets ds
  where ds.name=v_name
  order by ds.updated_at desc nulls last, ds.created_at desc
  limit 1;

  return nullif(btrim(coalesce(v_secret,'')),'');
end;
$function$
;

-- function: ops2_papoai_outbound_summary_v1()
CREATE OR REPLACE FUNCTION public.ops2_papoai_outbound_summary_v1()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
select jsonb_build_object(
  'dispatch_enabled',(select dispatch_enabled from public.ops2_papoai_outbound_runtime_v1 where id=1),
  'transport_verified',(select transport_verified from public.ops2_papoai_outbound_runtime_v1 where id=1),
  'total',(select count(*) from public.ops2_papoai_outbound_intents_v1),
  'waiting_route',(select count(*) from public.ops2_papoai_outbound_intents_v1 where status='waiting_route'),
  'blocked_transport',(select count(*) from public.ops2_papoai_outbound_intents_v1 where status='blocked_transport'),
  'cancelled',(select count(*) from public.ops2_papoai_outbound_intents_v1 where status='cancelled'),
  'sent',(select count(*) from public.ops2_papoai_outbound_intents_v1 where status='sent'),
  'failed',(select count(*) from public.ops2_papoai_outbound_intents_v1 where status='failed'),
  'with_route',(select count(*) from public.ops2_papoai_outbound_intents_v1 where papoai_session_uid is not null and papoai_contact_id is not null and papoai_agentbot_id is not null),
  'generated_at',now()
);
$function$
;

-- function: ops2_papoai_route_context_v1(p_order_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_papoai_route_context_v1(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_order public.orders%rowtype;
  v_customer public.customers%rowtype;
  v_inbox public.papoai_webhook_inbox_v2%rowtype;
  v_phone text;
  v_account_id uuid;
  v_conversation_id uuid;
  v_session_uid text;
  v_contact_id text;
  v_agentbot_id text;
  v_channel_phone text;
begin
  select o.* into v_order from public.orders o where o.id=p_order_id;
  if not found then
    return jsonb_build_object('ok',false,'error','order_not_found','order_id',p_order_id);
  end if;

  if v_order.customer_id is null then
    return jsonb_build_object('ok',false,'error','customer_missing','order_id',p_order_id);
  end if;

  select c.* into v_customer from public.customers c where c.id=v_order.customer_id;
  v_phone:=coalesce(nullif(v_order.phone_e164,''),nullif(v_customer.primary_whatsapp_e164,''));

  -- Priority 1: exact internal conversation already linked to the order.
  if v_order.conversation_id is not null then
    select i.* into v_inbox
    from public.papoai_webhook_inbox_v2 i
    where nullif(i.metadata->>'conversation_id','')=v_order.conversation_id::text
    order by i.received_at desc
    limit 1;
  end if;

  -- Priority 2: latest event already linked to this canonical customer.
  if v_inbox.id is null then
    select i.* into v_inbox
    from public.papoai_webhook_inbox_v2 i
    where nullif(i.metadata->>'customer_id','')=v_order.customer_id::text
      and i.received_at>=greatest(v_order.created_at-interval '2 hours',now()-interval '31 days')
    order by i.received_at desc
    limit 1;
  end if;

  if v_inbox.id is null then
    return jsonb_build_object(
      'ok',true,'route_available',false,'order_id',p_order_id,'customer_id',v_order.customer_id,
      'reason','no_linked_papoai_session'
    );
  end if;

  v_session_uid:=coalesce(nullif(v_inbox.payload#>>'{data,session,uid}',''),nullif(v_inbox.conversation_ref,''));
  v_contact_id:=coalesce(nullif(v_inbox.payload#>>'{data,session,contact_id}',''),nullif(v_inbox.payload#>>'{data,contact,id}',''));
  v_agentbot_id:=nullif(v_inbox.payload#>>'{data,session,agentbot_id}','');
  v_channel_phone:=nullif(v_inbox.metadata->>'business_phone_e164','');
  v_conversation_id:=nullif(v_inbox.metadata->>'conversation_id','')::uuid;
  v_account_id:=nullif(v_inbox.metadata->>'whatsapp_account_id','')::uuid;

  if v_session_uid is null or v_contact_id is null or v_agentbot_id is null or v_account_id is null or v_conversation_id is null then
    return jsonb_build_object(
      'ok',true,'route_available',false,'order_id',p_order_id,'customer_id',v_order.customer_id,
      'reason','linked_session_missing_identifiers',
      'conversation_id',v_conversation_id,'whatsapp_account_id',v_account_id,
      'channel_phone_e164',v_channel_phone,'papoai_session_uid',v_session_uid,
      'papoai_contact_id',v_contact_id,'papoai_agentbot_id',v_agentbot_id
    );
  end if;

  return jsonb_build_object(
    'ok',true,'route_available',true,'order_id',p_order_id,'customer_id',v_order.customer_id,
    'conversation_id',v_conversation_id,'whatsapp_account_id',v_account_id,
    'channel_phone_e164',v_channel_phone,'papoai_session_uid',v_session_uid,
    'papoai_contact_id',v_contact_id,'papoai_agentbot_id',v_agentbot_id,
    'source_event_received_at',v_inbox.received_at,
    'source_external_message_id',v_inbox.external_message_id
  );
end;
$function$
;

-- function: ops2_papoai_signal_allowed_v1(p_signal text)
CREATE OR REPLACE FUNCTION public.ops2_papoai_signal_allowed_v1(p_signal text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select upper(btrim(coalesce(p_signal,''))) = any(array[
    'PEDIDO_SITE',
    'INT_CESTAS','INT_BEBE','INT_CABELOS','INT_BELEZA','INT_HIGIENE','INT_LIMPEZA','INT_LAVANDERIA','INT_PET','INT_CASA','INT_DOCES_LANCHES',
    'BR_NIVEA','BR_ELSEVE',
    'CTA_OFERTAS','CTA_BEBE','CTA_CABELOS','CTA_BELEZA','CTA_LIMPEZA','CTA_LAVANDERIA','CTA_PET'
  ]::text[])
$function$
;

-- function: ops2_papoai_signal_provider_store_v1(p_channel text, p_signal text, p_url text)
CREATE OR REPLACE FUNCTION public.ops2_papoai_signal_provider_store_v1(p_channel text, p_signal text, p_url text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_channel text:=btrim(coalesce(p_channel,'')); v_signal text:=upper(btrim(coalesce(p_signal,''))); v_url text:=nullif(btrim(coalesce(p_url,'')),''); v_name text; v_secret_id uuid;
begin
  if v_channel not in ('0975','1018') then return jsonb_build_object('ok',false,'error','unsupported_channel'); end if;
  if not public.ops2_papoai_signal_allowed_v1(v_signal) then return jsonb_build_object('ok',false,'error','unsupported_signal'); end if;
  if v_url is null or length(v_url)>2048 or v_url !~* '^https://[^[:space:]]+$' then return jsonb_build_object('ok',false,'error','invalid_https_url'); end if;
  v_name:='papoai_signal_webhook_'||v_channel||'_'||lower(v_signal)||'_v1';
  select s.id into v_secret_id from vault.secrets s where s.name=v_name order by s.updated_at desc nulls last,s.created_at desc limit 1;
  if v_secret_id is null then v_secret_id:=vault.create_secret(v_url,v_name,'Dona Antônia PapoAI internal order signal',null);
  else perform vault.update_secret(v_secret_id,v_url,v_name,'Dona Antônia PapoAI internal order signal',null); end if;
  return jsonb_build_object('ok',true,'channel',v_channel,'signal',v_signal,'stored',true);
end $function$
;

-- function: ops2_papoai_signal_provider_url_v1(p_channel text, p_signal text)
CREATE OR REPLACE FUNCTION public.ops2_papoai_signal_provider_url_v1(p_channel text, p_signal text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_channel text:=btrim(coalesce(p_channel,'')); v_signal text:=upper(btrim(coalesce(p_signal,''))); v_name text; v_secret text;
begin
  if v_channel not in ('0975','1018') or not public.ops2_papoai_signal_allowed_v1(v_signal) then return null; end if;
  v_name:='papoai_signal_webhook_'||v_channel||'_'||lower(v_signal)||'_v1';
  select ds.decrypted_secret into v_secret from vault.decrypted_secrets ds where ds.name=v_name order by ds.updated_at desc nulls last,ds.created_at desc limit 1;
  return nullif(btrim(coalesce(v_secret,'')),'');
end $function$
;

-- function: ops2_plan_registration_flow_intent_v1(p_order_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_plan_registration_flow_intent_v1(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_journey public.ops2_customer_registration_journeys_v1%rowtype;
  v_route jsonb;
  v_status text;
  v_reason text;
  v_key text;
  v_intent public.ops2_papoai_outbound_intents_v1%rowtype;
  v_dispatch boolean;
  v_verified boolean;
begin
  select j.* into v_journey
  from public.ops2_customer_registration_journeys_v1 j
  where j.order_id=p_order_id;

  if not found then
    return jsonb_build_object('ok',false,'error','registration_journey_missing','order_id',p_order_id);
  end if;

  if v_journey.registration_state<>'pending' or v_journey.workflow_open=false then
    update public.ops2_papoai_outbound_intents_v1
    set status='cancelled',reason='registration_not_pending',cancelled_at=coalesce(cancelled_at,now()),updated_at=now()
    where order_id=p_order_id and purpose='registration_flow' and status in ('waiting_route','blocked_transport');
    return jsonb_build_object('ok',true,'planned',false,'cancelled',true,'order_id',p_order_id);
  end if;

  v_route:=public.ops2_papoai_route_context_v1(p_order_id);
  select r.dispatch_enabled,r.transport_verified into v_dispatch,v_verified
  from public.ops2_papoai_outbound_runtime_v1 r where r.id=1;

  if coalesce((v_route->>'route_available')::boolean,false)=false then
    v_status:='waiting_route';
    v_reason:=coalesce(v_route->>'reason','route_unavailable');
  else
    -- Even with a route, transport remains blocked until supplier contract is verified.
    v_status:='blocked_transport';
    v_reason:=case
      when coalesce(v_verified,false)=false then 'transport_unverified'
      when coalesce(v_dispatch,false)=false then 'dispatch_disabled'
      else 'dispatcher_not_implemented'
    end;
  end if;

  v_key:=format('registration_flow:%s:%s',p_order_id,v_journey.transition_seq);

  insert into public.ops2_papoai_outbound_intents_v1(
    purpose,order_id,customer_id,conversation_id,whatsapp_account_id,channel_phone_e164,
    papoai_session_uid,papoai_contact_id,papoai_agentbot_id,transition_seq,status,reason,idempotency_key,payload
  ) values (
    'registration_flow',p_order_id,v_journey.customer_id,
    nullif(v_route->>'conversation_id','')::uuid,
    nullif(v_route->>'whatsapp_account_id','')::uuid,
    nullif(v_route->>'channel_phone_e164',''),
    nullif(v_route->>'papoai_session_uid',''),
    nullif(v_route->>'papoai_contact_id',''),
    nullif(v_route->>'papoai_agentbot_id',''),
    v_journey.transition_seq,v_status,v_reason,v_key,
    jsonb_build_object('route_available',coalesce((v_route->>'route_available')::boolean,false),'planned_at',now())
  )
  on conflict (idempotency_key) do update
  set conversation_id=coalesce(excluded.conversation_id,public.ops2_papoai_outbound_intents_v1.conversation_id),
      whatsapp_account_id=coalesce(excluded.whatsapp_account_id,public.ops2_papoai_outbound_intents_v1.whatsapp_account_id),
      channel_phone_e164=coalesce(excluded.channel_phone_e164,public.ops2_papoai_outbound_intents_v1.channel_phone_e164),
      papoai_session_uid=coalesce(excluded.papoai_session_uid,public.ops2_papoai_outbound_intents_v1.papoai_session_uid),
      papoai_contact_id=coalesce(excluded.papoai_contact_id,public.ops2_papoai_outbound_intents_v1.papoai_contact_id),
      papoai_agentbot_id=coalesce(excluded.papoai_agentbot_id,public.ops2_papoai_outbound_intents_v1.papoai_agentbot_id),
      status=case when public.ops2_papoai_outbound_intents_v1.status in ('sent','cancelled') then public.ops2_papoai_outbound_intents_v1.status else excluded.status end,
      reason=case when public.ops2_papoai_outbound_intents_v1.status in ('sent','cancelled') then public.ops2_papoai_outbound_intents_v1.reason else excluded.reason end,
      updated_at=now()
  returning * into v_intent;

  return jsonb_build_object(
    'ok',true,'planned',true,'intent_id',v_intent.id,'status',v_intent.status,'reason',v_intent.reason,
    'order_id',p_order_id,'transition_seq',v_journey.transition_seq,
    'route_available',coalesce((v_route->>'route_available')::boolean,false),
    'channel_phone_e164',v_intent.channel_phone_e164,'papoai_agentbot_id',v_intent.papoai_agentbot_id
  );
end;
$function$
;

-- function: ops2_pre_human_catalog_readiness_summary_v1()
CREATE OR REPLACE FUNCTION public.ops2_pre_human_catalog_readiness_summary_v1()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
 select jsonb_build_object(
 'active_products',count(*) filter(where is_active),
 'mirror_identity_ready',count(*) filter(where is_active and mirror_bling_product_id is not null),
 'identity_conflicts',count(*) filter(where is_active and readiness_state='identity_conflict'),
 'missing_bling_identity',count(*) filter(where is_active and readiness_state='missing_bling_identity'),
 'ready_to_push_supabase_baseline',count(*) filter(where is_active and readiness_state='ready_to_push_supabase_baseline'),
 'already_stock_aligned',count(*) filter(where is_active and readiness_state='already_stock_aligned'),
 'generated_at',now())
 from public.ops2_pre_human_catalog_readiness_v1;
$function$
;

-- function: ops2_prepare_catalog_stock_canary_band_v1(p_run uuid, p_abs_delta integer, p_limit integer)
CREATE OR REPLACE FUNCTION public.ops2_prepare_catalog_stock_canary_band_v1(p_run uuid, p_abs_delta integer, p_limit integer DEFAULT 5)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid;
  v_band int:=greatest(1,coalesce(p_abs_delta,1));
  v_cap int;
  v_lim int;
  v_count int;
begin
  if v_band>10 then raise exception 'band_requires_manual_or_high_risk_gate'; end if;
  v_cap:=case when v_band<=5 then 5 else 3 end;
  v_lim:=greatest(1,least(coalesce(p_limit,v_cap),v_cap));
  perform pg_advisory_xact_lock(hashtextextended('ops2_catalog_stock_canary:'||p_run::text,0));

  if not exists(select 1 from public.ops2_catalog_baseline_runs where id=p_run and status='planned') then raise exception 'run_not_planned'; end if;
  if exists(select 1 from public.ops2_catalog_sync_plan_items where run_id=p_run and state='blocked') then raise exception 'plan_has_blockers'; end if;

  insert into public.ops2_catalog_sync_canaries(run_id,max_items,risk_band,notes)
  values(p_run,v_lim,v_band,'exact risk-band canary; external writes disabled')
  returning id into v_id;

  insert into public.ops2_catalog_sync_canary_items(canary_id,run_id,product_id,bling_product_id,desired_stock,bling_physical_before,delta)
  select v_id,p_run,p.product_id,p.bling_product_id,p.desired_stock,p.current_bling_physical,
         p.desired_stock-coalesce(p.current_bling_physical,0)
  from public.ops2_catalog_sync_plan_items p
  where p.run_id=p_run and p.operation='stock_update' and p.state='planned'
    and abs(p.desired_stock-coalesce(p.current_bling_physical,0))=v_band
    and not exists(
      select 1 from public.ops2_catalog_sync_canary_items ai
      join public.ops2_catalog_sync_canaries ac on ac.id=ai.canary_id
      where ai.product_id=p.product_id and ai.run_id=p.run_id
        and ac.status in ('prepared','armed','queued','sent','divergent')
    )
  order by p.product_id
  limit v_lim;

  select count(*) into v_count from public.ops2_catalog_sync_canary_items where canary_id=v_id;
  update public.ops2_catalog_sync_canaries
     set item_count=v_count,
         status=case when v_count=0 then 'rolled_back' else status end,
         notes=case when v_count=0 then 'no eligible unreserved items for exact risk band' else notes end
   where id=v_id;
  return v_id;
end $function$
;

-- function: ops2_prepare_catalog_stock_canary_highrisk_v1(p_run uuid, p_abs_delta integer)
CREATE OR REPLACE FUNCTION public.ops2_prepare_catalog_stock_canary_highrisk_v1(p_run uuid, p_abs_delta integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid; v_band int:=coalesce(p_abs_delta,0); v_count int;
begin
  if v_band<11 or v_band>20 then raise exception 'unsupported_highrisk_band'; end if;
  perform pg_advisory_xact_lock(hashtextextended('ops2_catalog_stock_canary:'||p_run::text,0));
  if not exists(select 1 from public.ops2_catalog_baseline_runs where id=p_run and status='planned') then raise exception 'run_not_planned'; end if;
  if exists(select 1 from public.ops2_catalog_sync_plan_items where run_id=p_run and state='blocked') then raise exception 'plan_has_blockers'; end if;

  insert into public.ops2_catalog_sync_canaries(run_id,max_items,risk_band,notes)
  values(p_run,1,v_band,'high-risk exact-band singleton; remote snapshot must be revalidated before write')
  returning id into v_id;

  insert into public.ops2_catalog_sync_canary_items(
    canary_id,run_id,product_id,bling_product_id,desired_stock,bling_physical_before,delta
  )
  select v_id,p_run,p.product_id,p.bling_product_id,p.desired_stock,p.current_bling_physical,
         p.desired_stock-coalesce(p.current_bling_physical,0)
  from public.ops2_catalog_sync_plan_items p
  where p.run_id=p_run and p.operation='stock_update' and p.state='planned'
    and abs(p.desired_stock-coalesce(p.current_bling_physical,0))=v_band
    and not exists(
      select 1 from public.ops2_catalog_sync_canary_items ai
      join public.ops2_catalog_sync_canaries ac on ac.id=ai.canary_id
      where ai.product_id=p.product_id and ai.run_id=p.run_id
        and ac.status in ('prepared','armed','queued','sent','divergent')
    )
  order by p.product_id
  limit 1;

  select count(*) into v_count from public.ops2_catalog_sync_canary_items where canary_id=v_id;
  update public.ops2_catalog_sync_canaries
     set item_count=v_count,
         status=case when v_count=0 then 'rolled_back' else status end,
         notes=case when v_count=0 then 'no eligible unreserved item for high-risk exact band' else notes end
   where id=v_id;
  return v_id;
end $function$
;

-- function: ops2_prepare_catalog_stock_canary_v1(p_run uuid, p_limit integer)
CREATE OR REPLACE FUNCTION public.ops2_prepare_catalog_stock_canary_v1(p_run uuid, p_limit integer DEFAULT 5)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid;
  v_lim int:=greatest(1,least(coalesce(p_limit,5),20));
  v_count int;
begin
  perform pg_advisory_xact_lock(hashtextextended('ops2_catalog_stock_canary:'||p_run::text,0));

  if not exists(select 1 from public.ops2_catalog_baseline_runs where id=p_run and status='planned') then
    raise exception 'run_not_planned';
  end if;
  if exists(select 1 from public.ops2_catalog_sync_plan_items where run_id=p_run and state='blocked') then
    raise exception 'plan_has_blockers';
  end if;

  insert into public.ops2_catalog_sync_canaries(run_id,max_items,notes)
  values(p_run,v_lim,'deterministic risk-band canary; external writes disabled')
  returning id into v_id;

  insert into public.ops2_catalog_sync_canary_items(
    canary_id,run_id,product_id,bling_product_id,desired_stock,bling_physical_before,delta
  )
  select v_id,p_run,p.product_id,p.bling_product_id,p.desired_stock,p.current_bling_physical,
         p.desired_stock-coalesce(p.current_bling_physical,0)
  from public.ops2_catalog_sync_plan_items p
  where p.run_id=p_run
    and p.operation='stock_update'
    and p.state='planned'
    and not exists(
      select 1
      from public.ops2_catalog_sync_canary_items ai
      join public.ops2_catalog_sync_canaries ac on ac.id=ai.canary_id
      where ai.product_id=p.product_id
        and ai.run_id=p.run_id
        and ac.status in ('prepared','armed','queued','sent','divergent')
    )
  order by abs(p.desired_stock-coalesce(p.current_bling_physical,0)),p.product_id
  limit v_lim;

  select count(*) into v_count from public.ops2_catalog_sync_canary_items where canary_id=v_id;
  update public.ops2_catalog_sync_canaries
     set item_count=v_count,
         status=case when v_count=0 then 'rolled_back' else status end,
         notes=case when v_count=0 then 'no eligible unreserved items' else notes end
   where id=v_id;

  return v_id;
end $function$
;

-- function: ops2_prepare_order_separation_completion_v2(p_order_id uuid, p_expected_order_updated_at timestamp with time zone)
CREATE OR REPLACE FUNCTION public.ops2_prepare_order_separation_completion_v2(p_order_id uuid, p_expected_order_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_order public.orders%rowtype;
  v_existing public.order_separation_completions_v1%rowtype;
  v_pending integer := 0;
  v_total_items integer := 0;
  v_original_total numeric(14,2) := 0;
  v_original_subtotal numeric(14,2) := 0;
  v_original_fiscal_subtotal numeric(14,2) := 0;
  v_missing_subtotal numeric(14,2) := 0;
  v_final_total numeric(14,2) := 0;
  v_new_subtotal numeric(14,2) := 0;
  v_new_fiscal_subtotal numeric(14,2) := 0;
  v_missing_items jsonb := '[]'::jsonb;
  v_deliverable_ids uuid[] := '{}'::uuid[];
  v_separator text := null;
  v_now timestamptz := now();
begin
  if p_order_id is null then
    return jsonb_build_object('ok',false,'error','invalid_order_id');
  end if;

  select * into v_order
  from public.orders
  where id=p_order_id
  for update;

  if not found then
    return jsonb_build_object('ok',false,'error','order_not_found');
  end if;

  select * into v_existing
  from public.order_separation_completions_v1
  where order_id=p_order_id;

  if found then
    return jsonb_build_object(
      'ok',true,
      'status','already_prepared',
      'order_id',p_order_id,
      'phase',v_existing.phase,
      'original_total',v_existing.original_total,
      'missing_subtotal',v_existing.missing_subtotal,
      'final_total',v_existing.final_total,
      'deliverable_order_item_ids',to_jsonb(v_existing.deliverable_order_item_ids),
      'metadata',v_existing.metadata
    );
  end if;

  if v_order.status not in ('confirmed','processing') then
    return jsonb_build_object('ok',false,'error','order_not_in_separation','status',v_order.status);
  end if;

  if p_expected_order_updated_at is null or v_order.updated_at is distinct from p_expected_order_updated_at then
    return jsonb_build_object(
      'ok',false,
      'error','stale_order_version',
      'conflict','order_version_conflict',
      'order_updated_at',v_order.updated_at
    );
  end if;

  perform public.ops2_init_order_separation_v2(p_order_id);

  select
    count(*) filter(where state='pending'),
    count(*)
  into v_pending,v_total_items
  from public.order_separation_items_v1
  where order_id=p_order_id;

  if v_total_items=0 then
    return jsonb_build_object('ok',false,'error','order_has_no_items');
  end if;
  if v_pending>0 then
    return jsonb_build_object('ok',false,'error','separation_incomplete','pending_count',v_pending);
  end if;

  select round(coalesce(sum(line_total),0)::numeric,2)
  into v_missing_subtotal
  from public.order_separation_items_v1
  where order_id=p_order_id and state='missing';

  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'order_item_id',s.order_item_id,
    'product_id',s.product_id,
    'name',oi.name_snapshot,
    'quantity',s.quantity,
    'unit_price',s.unit_price,
    'line_total',s.line_total,
    'basket_name',nullif(oi.metadata->>'basket_name',''),
    'basket_id',nullif(oi.metadata->>'basket_id',''),
    'kind',coalesce(nullif(oi.metadata->>'history_kind',''),'product')
  )) order by oi.created_at,oi.id),'[]'::jsonb)
  into v_missing_items
  from public.order_separation_items_v1 s
  join public.order_items oi on oi.id=s.order_item_id
  where s.order_id=p_order_id and s.state='missing';

  select coalesce(array_agg(order_item_id order by order_item_id) filter(where state='separated'),'{}'::uuid[])
  into v_deliverable_ids
  from public.order_separation_items_v1
  where order_id=p_order_id;

  select separator_key into v_separator
  from public.order_separation_assignments_v1
  where order_id=p_order_id;

  v_original_total := round(coalesce(v_order.total,0)::numeric,2);
  v_original_subtotal := round(coalesce(v_order.subtotal,0)::numeric,2);
  v_original_fiscal_subtotal := round(coalesce(v_order.fiscal_subtotal,0)::numeric,2);
  v_final_total := round(v_original_total - v_missing_subtotal,2);
  v_new_subtotal := round(v_original_subtotal - v_missing_subtotal,2);
  v_new_fiscal_subtotal := round(v_original_fiscal_subtotal - v_missing_subtotal,2);

  if v_final_total<0 or v_new_subtotal<0 or v_new_fiscal_subtotal<0 then
    return jsonb_build_object(
      'ok',false,
      'error','missing_adjustment_exceeds_order_value',
      'missing_subtotal',v_missing_subtotal,
      'original_total',v_original_total,
      'original_subtotal',v_original_subtotal,
      'original_fiscal_subtotal',v_original_fiscal_subtotal
    );
  end if;

  insert into public.order_separation_completions_v1(
    order_id,order_number,phase,
    original_total,original_subtotal,original_fiscal_subtotal,
    original_discount,original_other_expenses,original_basket_hidden_adjustment,
    missing_subtotal,final_total,missing_items,deliverable_order_item_ids,
    separator_key,metadata,prepared_at,created_at,updated_at
  ) values(
    p_order_id,v_order.order_number,'prepared',
    v_original_total,v_original_subtotal,v_original_fiscal_subtotal,
    coalesce(v_order.discount,0),coalesce(v_order.other_expenses,0),coalesce(v_order.basket_hidden_adjustment,0),
    v_missing_subtotal,v_final_total,v_missing_items,v_deliverable_ids,
    v_separator,
    jsonb_build_object(
      'financial_applied',true,
      'stock_applied',false,
      'physical_stock_launched',false,
      'original_order_updated_at',v_order.updated_at,
      'prepared_by','order_separation_v2'
    ),
    v_now,v_now,v_now
  )
  on conflict (order_id) do nothing;

  update public.orders
  set total=v_final_total,
      subtotal=v_new_subtotal,
      fiscal_subtotal=v_new_fiscal_subtotal,
      updated_at=v_now
  where id=p_order_id;

  return jsonb_build_object(
    'ok',true,
    'status','prepared',
    'order_id',p_order_id,
    'order_number',v_order.order_number,
    'original_total',v_original_total,
    'missing_subtotal',v_missing_subtotal,
    'final_total',v_final_total,
    'subtotal',v_new_subtotal,
    'fiscal_subtotal',v_new_fiscal_subtotal,
    'discount',coalesce(v_order.discount,0),
    'other_expenses',coalesce(v_order.other_expenses,0),
    'basket_hidden_adjustment',coalesce(v_order.basket_hidden_adjustment,0),
    'missing_items',v_missing_items,
    'deliverable_order_item_ids',to_jsonb(v_deliverable_ids),
    'order_updated_at',v_now
  );
end;
$function$
;

-- function: ops2_prepare_stock_cutover_canary_v1()
CREATE OR REPLACE FUNCTION public.ops2_prepare_stock_cutover_canary_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare p jsonb; rid uuid;
begin
 p:=public.get_ops2_stock_cutover_preflight_v1();
 insert into public.ops2_stock_cutover_runs(status,preflight) values('prepared',p) returning id into rid;
 return jsonb_build_object('run_id',rid,'ready',coalesce((p->>'ready')::boolean,false),'preflight',p);
end $function$
;

-- function: ops2_process_papoai_flow_capture_v2(p_capture_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_process_papoai_flow_capture_v2(p_capture_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r public.papoai_webhook_inbox_v2%rowtype;
  v_text text;
  v_token text;
  v_consent text;
  v_name text;
  v_doc text;
  v_address text;
  v_district text;
  v_city text;
  v_bridge jsonb;
  v_result jsonb;
  v_tmp text;
begin
  select * into r from public.papoai_webhook_inbox_v2 where id=p_capture_id for update;
  if not found then return jsonb_build_object('ok',false,'error','capture_not_found'); end if;

  v_text:=coalesce(r.payload#>>'{data,message,content}',r.payload#>>'{data,message,text}',r.payload#>>'{data,message,body}','');
  v_token:=public.ops2_papoai_flow_text_field_v1(v_text,'flow_token');
  if v_token is null then return jsonb_build_object('ok',true,'skipped',true,'reason','not_flow_text'); end if;

  v_consent:=lower(coalesce(public.ops2_papoai_flow_text_field_v1(v_text,'data_sharing_consent'),''));
  if v_consent not in ('true','1','yes','sim') then
    update public.papoai_webhook_inbox_v2
       set status='review_required',last_error='flow_consent_missing_or_false',
           processed_at=now(),
           metadata=coalesce(metadata,'{}'::jsonb)
             || jsonb_build_object('structured_mode','papoai_flow_text_v2','structured_processed',false)
     where id=p_capture_id;
    return jsonb_build_object('ok',false,'error','flow_consent_missing_or_false');
  end if;

  v_name:=public.ops2_papoai_flow_text_field_v1(v_text,'custom_5');
  v_doc:=public.ops2_papoai_flow_text_field_v1(v_text,'custom_3');
  v_address:=public.ops2_papoai_flow_text_field_v1(v_text,'custom_4');
  v_district:=public.ops2_papoai_flow_text_field_v1(v_text,'custom_1');
  v_city:=public.ops2_papoai_flow_text_field_v1(v_text,'custom_2');

  -- Some Flow responses occasionally place only the street type ("Rua") in custom_4
  -- and the actual address in custom_1. Preserve the user's richer text rather than
  -- storing a clearly incomplete street.
  if v_address is not null
     and length(btrim(v_address))<=10
     and lower(regexp_replace(btrim(v_address),'[. ]','','g')) in
       ('rua','r','avenida','av','travessa','tv','estrada','rodovia','alameda')
     and v_district is not null
     and (v_district ~ '[0-9]' or length(v_district)>20)
  then
    v_tmp:=v_address;
    v_address:=v_district;
    v_district:=null;
  end if;

  v_bridge:=public.papoai_ensure_conversation_v2(p_capture_id);
  if coalesce((v_bridge->>'ok')::boolean,false) is not true then
    update public.papoai_webhook_inbox_v2
       set status='review_required',last_error=coalesce(v_bridge->>'error','conversation_bridge_failed'),
           processed_at=now(),
           metadata=coalesce(metadata,'{}'::jsonb)
             || jsonb_build_object('structured_mode','papoai_flow_text_v2','structured_processed',false)
     where id=p_capture_id;
    return v_bridge||jsonb_build_object('flow_detected',true);
  end if;

  v_result:=public.ops2_apply_papoai_customer_flow_v2(
    v_token,r.phone_candidate,v_name,v_doc,v_address,v_district,v_city,'MT',
    coalesce(r.conversation_ref,v_bridge->>'conversation_id'),p_capture_id,v_token
  );

  update public.papoai_webhook_inbox_v2
     set status=case when coalesce((v_result->>'ok')::boolean,false) then 'processed' else 'review_required' end,
         last_error=case when coalesce((v_result->>'ok')::boolean,false) then null else coalesce(v_result->>'error','flow_processing_failed') end,
         processed_at=now(),
         metadata=coalesce(metadata,'{}'::jsonb)
           || jsonb_strip_nulls(jsonb_build_object(
             'structured_mode','papoai_flow_text_v2',
             'structured_processed',coalesce((v_result->>'ok')::boolean,false),
             'flow_token',v_token,'customer_id',v_result->>'customer_id',
             'conversation_id',coalesce(v_result->>'conversation_id',v_bridge->>'conversation_id'),
             'orders_linked',coalesce((v_result->>'orders_linked')::integer,0),
             'order_id',v_result->>'order_id','order_number',v_result->>'order_number',
             'document_valid',coalesce((v_result->>'document_valid')::boolean,false)
           ))
   where id=p_capture_id;

  return v_result||jsonb_build_object('flow_detected',true,'flow_token',v_token);
end;
$function$
;

-- function: ops2_purchase_xml_receipt_gate_v1(p_document_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_purchase_xml_receipt_gate_v1(p_document_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'document_id', r.document_id,
    'ready',
      coalesce(r.conversion_ready,false)
      and r.finance_guard_ok
      and r.unmatched_items = 0
      and r.conversion_review_items = 0
      and r.invalid_conversion_items = 0
      and r.quantity_review_items = 0
      and r.processing_status = 'processed'
      and r.receipt_status = 'ready',
    'unmatched_items', r.unmatched_items,
    'conversion_review_items', r.conversion_review_items,
    'invalid_conversion_items', r.invalid_conversion_items,
    'quantity_review_items', r.quantity_review_items,
    'finance_guard_ok', r.finance_guard_ok,
    'recipient_kind', r.recipient_kind,
    'receipt_status', r.receipt_status,
    'processing_status', r.processing_status
  )
  from public.ops2_purchase_xml_conversion_readiness_v1 r
  where r.document_id = p_document_id
$function$
;

-- function: ops2_reconcile_lot_expiry_status_v1()
CREATE OR REPLACE FUNCTION public.ops2_reconcile_lot_expiry_status_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_expired integer:=0;
  v_reactivated integer:=0;
  v_depleted integer:=0;
begin
  update public.product_inventory_lots
     set status='expired',updated_at=now()
   where status='active' and expiration_date<current_date;
  get diagnostics v_expired=row_count;

  update public.product_inventory_lots
     set status='depleted',updated_at=now()
   where status='active' and quantity_on_hand is not null
     and greatest(quantity_on_hand-quantity_reserved,0)<=0;
  get diagnostics v_depleted=row_count;

  update public.product_inventory_lots
     set status='active',updated_at=now()
   where status in ('expired','depleted')
     and expiration_date>=current_date
     and quantity_on_hand is not null
     and greatest(quantity_on_hand-quantity_reserved,0)>0;
  get diagnostics v_reactivated=row_count;

  return jsonb_build_object('ok',true,'expired',v_expired,'depleted',v_depleted,'reactivated',v_reactivated);
end;
$function$
;

-- function: ops2_reconcile_order_whatsapp_sent_v1()
CREATE OR REPLACE FUNCTION public.ops2_reconcile_order_whatsapp_sent_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_order_number text;
  v_order_id uuid;
begin
  if new.direction is distinct from 'outbound'
     or new.provider is distinct from 'papoai'
     or new.provider_message_id is null
     or new.provider_message_id not like 'wamid.%' then
    return new;
  end if;

  v_order_number:=substring(coalesce(new.text_body,'') from '(DA-[0-9]{6}-[A-Z0-9]+)');
  if v_order_number is null then
    return new;
  end if;

  select o.id into v_order_id
  from public.orders o
  where o.order_number=v_order_number
  limit 1;

  if v_order_id is null then
    return new;
  end if;

  update public.ops2_whatsapp_outbox_v1 q
     set status='sent',
         external_message_id=new.provider_message_id,
         sent_at=coalesce(new.sent_at,new.created_at,now()),
         last_error=null,
         locked_at=null,
         payload=coalesce(q.payload,'{}'::jsonb)||jsonb_build_object(
           'delivery_confirmation',jsonb_build_object(
             'source','papoai_message.sent',
             'canonical_message_id',new.id,
             'confirmed_at',now()
           )
         ),
         updated_at=now()
   where q.order_id=v_order_id
     and q.recipient_kind='customer'
     and q.whatsapp_account_id=new.whatsapp_account_id
     and q.status in ('sending','accepted','sent')
     and (q.external_message_id is null or q.external_message_id=new.provider_message_id);

  return new;
end;
$function$
;

-- function: ops2_reconcile_papoai_inbound_v1(p_since timestamp with time zone, p_limit integer)
CREATE OR REPLACE FUNCTION public.ops2_reconcile_papoai_inbound_v1(p_since timestamp with time zone DEFAULT (now() - '3 days'::interval), p_limit integer DEFAULT 500)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_limit integer := least(500,greatest(1,coalesce(p_limit,500)));
  r record;
  v_account_id uuid;
  v_conversation_id uuid;
  v_customer_id uuid;
  v_phone text;
  v_source text;
  v_provider_message_id text;
  v_provider_conversation_id text;
  v_raw_type text;
  v_mime_type text;
  v_filename text;
  v_message_type text;
  v_text_body text;
  v_message_at timestamptz;
  v_description jsonb;
  v_location jsonb;
  v_media jsonb;
  v_message jsonb;
  v_result jsonb;
  v_event_id uuid;
  v_message_id uuid;
  v_existing_message_id uuid;
  v_processed integer := 0;
  v_duplicates integer := 0;
  v_skipped integer := 0;
  v_errors integer := 0;
  v_considered integer := 0;
begin
  for r in
    select i.*
    from public.papoai_webhook_inbox_v2 i
    where i.received_at >= coalesce(p_since,now()-interval '3 days')
      and coalesce(i.payload#>>'{event,type}',i.event_name,i.payload->>'event_name')='message.received'
      and nullif(i.metadata->>'canonical_message_id','') is null
    order by i.received_at asc,i.id asc
    limit v_limit
  loop
    v_considered:=v_considered+1;
    v_account_id:=null;v_conversation_id:=null;v_customer_id:=null;v_phone:=null;v_source:=null;
    v_provider_message_id:=null;v_provider_conversation_id:=null;v_description:=null;v_location:=null;v_media:=null;
    v_result:=null;v_event_id:=null;v_message_id:=null;v_existing_message_id:=null;

    begin
      begin v_conversation_id:=nullif(r.metadata->>'conversation_id','')::uuid; exception when others then v_conversation_id:=null; end;
      begin v_account_id:=nullif(r.metadata->>'whatsapp_account_id','')::uuid; exception when others then v_account_id:=null; end;
      begin v_customer_id:=nullif(r.metadata->>'customer_id','')::uuid; exception when others then v_customer_id:=null; end;

      if v_conversation_id is not null then
        select coalesce(v_account_id,c.whatsapp_account_id),coalesce(v_customer_id,c.customer_id),
               coalesce(nullif(r.metadata->>'canonical_phone_e164',''),c.wa_contact_e164),c.source
          into v_account_id,v_customer_id,v_phone,v_source
        from public.conversations c
        where c.id=v_conversation_id;
      end if;

      if v_account_id is null or v_conversation_id is null or nullif(btrim(coalesce(v_phone,'')),'') is null then
        v_skipped:=v_skipped+1;
        continue;
      end if;

      v_provider_message_id:=nullif(btrim(coalesce(
        r.metadata->>'whatsapp_message_id',
        r.payload#>>'{data,message,external_id}',
        r.external_message_id,
        r.payload#>>'{data,message,id}'
      )), '');
      if v_provider_message_id is null then
        v_skipped:=v_skipped+1;
        continue;
      end if;

      v_provider_conversation_id:=nullif(btrim(coalesce(r.payload#>>'{data,session,uid}',r.conversation_ref)),'');
      v_raw_type:=lower(nullif(btrim(coalesce(r.payload#>>'{data,message,type}',r.payload#>>'{data,message,mimetype}','unknown')),''));
      v_mime_type:=nullif(btrim(coalesce(r.payload#>>'{data,message,mimetype}',case when position('/' in coalesce(v_raw_type,''))>0 then v_raw_type end)), '');
      v_filename:=nullif(btrim(r.payload#>>'{data,message,filename}'),'');
      v_text_body:=nullif(btrim(coalesce(
        r.payload#>>'{data,message,content}',
        r.payload#>>'{data,message,body}',
        r.payload#>>'{data,message,text}',
        r.payload#>>'{data,message,caption}'
      )), '');

      v_message_at:=r.received_at;
      begin
        if nullif(r.metadata->>'occurred_at','') is not null then
          v_message_at:=(r.metadata->>'occurred_at')::timestamptz;
        elsif nullif(r.payload#>>'{data,message,created_at}','') is not null then
          v_message_at:=(r.payload#>>'{data,message,created_at}')::timestamptz;
        elsif nullif(r.payload#>>'{data,message,timestamp}','') ~ '^\d+(\.\d+)?$' then
          v_message_at:=to_timestamp((r.payload#>>'{data,message,timestamp}')::double precision);
        end if;
      exception when others then
        v_message_at:=r.received_at;
      end;

      if nullif(r.payload#>>'{data,message,description}','') is not null then
        begin v_description:=(r.payload#>>'{data,message,description}')::jsonb; exception when others then v_description:=null; end;
      end if;
      if v_description is not null
         and jsonb_typeof(v_description)='object'
         and (v_description->>'latitude') ~ '^-?[0-9]+(\.[0-9]+)?$'
         and (v_description->>'longitude') ~ '^-?[0-9]+(\.[0-9]+)?$' then
        v_location:=jsonb_strip_nulls(jsonb_build_object(
          'name',nullif(btrim(v_description->>'name'),''),
          'address',nullif(btrim(v_description->>'address'),''),
          'latitude',(v_description->>'latitude')::numeric,
          'longitude',(v_description->>'longitude')::numeric
        ));
      end if;

      v_message_type:=case
        when v_location is not null then 'location'
        when v_raw_type='text' then 'text'
        when v_raw_type in ('audio','voice','ptt') or v_raw_type like 'audio/%' then 'audio'
        when v_raw_type='image' or v_raw_type like 'image/%' then 'image'
        when v_raw_type='document' or v_raw_type='file' or v_raw_type like 'application/%' then 'document'
        else 'unknown'
      end;

      if v_message_type in ('image','audio','document') then
        v_media:=jsonb_strip_nulls(jsonb_build_object(
          'kind',v_message_type,
          'mime_type',v_mime_type,
          'filename',v_filename,
          'has_provider_url',nullif(r.payload#>>'{data,message,media_url}','') is not null
        ));
      end if;

      v_message:=jsonb_strip_nulls(jsonb_build_object(
        'direction','inbound',
        'message_type',v_message_type,
        'provider_conversation_id',v_provider_conversation_id,
        'text_body',v_text_body,
        'status_current','received',
        'sender_kind','customer',
        'received_at',v_message_at,
        'customer_id',v_customer_id,
        'source',coalesce(nullif(v_source,''),'unknown'),
        'metadata',jsonb_strip_nulls(jsonb_build_object(
          'source','papoai',
          'raw_type',v_raw_type,
          'media',v_media,
          'location',v_location,
          'legacy_capture_id',r.id,
          'legacy_event_key',r.event_key,
          'legacy_conversation_id',v_conversation_id
        ))
      ));

      v_result:=public.whatsapp_ingest_event_v1(
        v_account_id,
        'papoai',
        r.event_key,
        'message.received',
        v_provider_message_id,
        v_phone,
        v_message_at,
        r.body_hash,
        coalesce(r.payload,'{}'::jsonb),
        v_message
      );

      if coalesce((v_result->>'ok')::boolean,false) is not true then
        v_errors:=v_errors+1;
        continue;
      end if;

      begin v_event_id:=nullif(v_result->>'event_id','')::uuid; exception when others then v_event_id:=null; end;
      begin v_message_id:=nullif(v_result->>'message_id','')::uuid; exception when others then v_message_id:=null; end;

      if coalesce((v_result->>'duplicate')::boolean,false) then
        v_duplicates:=v_duplicates+1;
        if v_message_id is null then
          select m.id into v_existing_message_id
          from public.whatsapp_messages_v1 m
          where m.whatsapp_account_id=v_account_id
            and m.provider='papoai'
            and m.provider_message_id=v_provider_message_id
          order by m.created_at desc
          limit 1;
          v_message_id:=v_existing_message_id;
        end if;
      else
        v_processed:=v_processed+1;
      end if;

      if v_message_id is null then
        v_errors:=v_errors+1;
        continue;
      end if;

      update public.papoai_webhook_inbox_v2
         set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_strip_nulls(jsonb_build_object(
               'canonical_mirror',true,
               'canonical_reconciled_at',now(),
               'canonical_event_id',v_event_id,
               'canonical_message_id',v_message_id
             )),
             last_error=null
       where id=r.id;
    exception when others then
      v_errors:=v_errors+1;
    end;
  end loop;

  return jsonb_build_object(
    'ok',true,
    'since',coalesce(p_since,now()-interval '3 days'),
    'limit',v_limit,
    'considered',v_considered,
    'processed',v_processed,
    'duplicates',v_duplicates,
    'skipped',v_skipped,
    'errors',v_errors
  );
end;
$function$
;

-- function: ops2_reconcile_unlinked_site_orders_v2(p_days integer)
CREATE OR REPLACE FUNCTION public.ops2_reconcile_unlinked_site_orders_v2(p_days integer DEFAULT 31)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r record;
  v_identity jsonb;
  v_customer_id uuid;
  v_name text;
  v_linked integer:=0;
  v_failed integer:=0;
begin
  for r in
    select *
    from public.orders
    where customer_id is null
      and source in ('vitrine','storefront_v2')
      and created_at>=now()-make_interval(days=>greatest(1,least(coalesce(p_days,31),365)))
      and nullif(btrim(coalesce(phone_e164,'')),'') is not null
    order by created_at
  loop
    v_name:=nullif(btrim(coalesce(
      r.customer_snapshot->>'name',
      r.customer_snapshot->>'display_name',
      r.delivery_address->>'customer_name',
      r.checkout_snapshot#>>'{customer,display_name}'
    )),'');
    if v_name is null and nullif(r.order_number,'') is not null then
      select nullif(btrim(i.metadata->>'contact_name'),'') into v_name
      from public.papoai_webhook_inbox_v2 i
      where public.normalize_phone_digits(i.phone_candidate)=any(public.phone_variants_br(r.phone_e164))
        and i.received_at between r.created_at-interval '30 minutes' and r.created_at+interval '12 hours'
        and coalesce(i.payload#>>'{data,message,content}',i.payload#>>'{data,message,text}',i.payload#>>'{data,message,body}','')
              ilike '%'||right(r.order_number,8)||'%'
      order by abs(extract(epoch from (i.received_at-r.created_at)))
      limit 1;
      if v_name in ('.','-','_','"."' ) then v_name:=null; end if;
    end if;

    v_identity:=public.ensure_storefront_customer_v2(r.phone_e164,v_name,r.order_number);
    if coalesce((v_identity->>'ok')::boolean,false) is true then
      v_customer_id:=(v_identity->>'customer_id')::uuid;
      update public.orders
         set customer_id=v_customer_id,
             phone_e164=coalesce(v_identity->>'canonical_phone_e164',phone_e164),
             customer_snapshot=coalesce(customer_snapshot,'{}'::jsonb)
               || jsonb_strip_nulls(jsonb_build_object(
                 'customer_id',v_customer_id,
                 'name',v_name,
                 'phone_e164',coalesce(v_identity->>'canonical_phone_e164',phone_e164),
                 'identity_status',v_identity->>'status',
                 'identity_backfilled_at',now()
               )),
             delivery_address=coalesce(delivery_address,'{}'::jsonb)
               || jsonb_build_object('source_customer_id',v_customer_id),
             updated_at=now()
       where id=r.id and customer_id is null;
      if found then v_linked:=v_linked+1; end if;
    else
      v_failed:=v_failed+1;
    end if;
  end loop;

  return jsonb_build_object('ok',true,'linked',v_linked,'failed',v_failed);
end;
$function$
;

-- function: ops2_refresh_customer_registration_journeys_v1(p_customer_id uuid, p_emit_event boolean)
CREATE OR REPLACE FUNCTION public.ops2_refresh_customer_registration_journeys_v1(p_customer_id uuid, p_emit_event boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_order_id uuid;
  v_count integer:=0;
  v_bling_job uuid;
begin
  if p_customer_id is null then
    return jsonb_build_object('ok',false,'error','customer_id_required','refreshed_orders',0);
  end if;

  for v_order_id in
    select o.id
    from public.orders o
    where o.customer_id=p_customer_id
      and o.source in ('vitrine','storefront_v2')
  loop
    perform public.ops2_refresh_order_registration_journey_v1(v_order_id,p_emit_event);
    v_count:=v_count+1;
  end loop;

  -- Same canonical refresh now also drives Bling customer sync.
  -- This is intentionally centralized here so customer and address triggers
  -- cannot drift into separate definitions of "complete".
  v_bling_job:=public.ops2_maybe_enqueue_customer_bling_v1(
    p_customer_id,
    'registration_journey_refresh'
  );

  return jsonb_build_object(
    'ok',true,
    'customer_id',p_customer_id,
    'refreshed_orders',v_count,
    'bling_job_id',v_bling_job
  );
end;
$function$
;

-- function: ops2_refresh_order_public_snapshot_v1(p_order_id uuid)
CREATE OR REPLACE FUNCTION public.ops2_refresh_order_public_snapshot_v1(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_order public.orders%rowtype;
  v_completion public.order_separation_completions_v1%rowtype;
  v_snapshot jsonb;
  v_live_missing_subtotal numeric(14,2) := 0;
  v_original_total numeric(14,2) := 0;
  v_final_total numeric(14,2) := 0;
begin
  select * into v_order from public.orders where id=p_order_id;
  if not found then return null; end if;

  select * into v_completion
  from public.order_separation_completions_v1
  where order_id=p_order_id;

  select round(coalesce(sum(s.line_total),0)::numeric,2)
  into v_live_missing_subtotal
  from public.order_separation_items_v1 s
  join public.order_items oi on oi.id=s.order_item_id
  where s.order_id=p_order_id
    and s.state='missing'
    and not (
      coalesce(oi.metadata->>'history_kind','') in ('basket','basket_mold')
      and exists(
        select 1 from public.order_items c
        where c.order_id=p_order_id
          and coalesce(c.metadata->>'history_kind','') in ('basket_component','basket_mold_component')
          and (
            (
              nullif(oi.metadata->>'basket_id','') is not null
              and nullif(c.metadata->>'basket_id','')=nullif(oi.metadata->>'basket_id','')
            )
            or lower(trim(coalesce(nullif(c.metadata->>'basket_name',''),nullif(c.metadata->>'parent_basket_name',''),'')))
               = lower(trim(coalesce(nullif(oi.metadata->>'basket_name',''),oi.name_snapshot,'')))
          )
      )
    );

  if v_completion.id is not null then
    v_original_total := round(coalesce(v_completion.original_total,v_order.total,0)::numeric,2);
    v_live_missing_subtotal := round(coalesce(v_completion.missing_subtotal,v_live_missing_subtotal,0)::numeric,2);
    v_final_total := round(coalesce(v_completion.final_total,v_order.total,0)::numeric,2);
  else
    v_original_total := round(coalesce(v_order.total,0)::numeric,2);
    v_final_total := greatest(0,round(v_original_total-v_live_missing_subtotal,2));
  end if;

  select jsonb_strip_nulls(jsonb_build_object(
    'version',3,
    'order_id',v_order.id::text,
    'order_number',v_order.order_number,
    'created_at',v_order.created_at,
    'total',v_final_total,
    'subtotal',case when v_completion.id is not null then v_order.subtotal else greatest(0,round(coalesce(v_order.subtotal,0)-v_live_missing_subtotal,2)) end,
    'original_total',v_original_total,
    'missing_subtotal',v_live_missing_subtotal,
    'final_total',v_final_total,
    'separation_completed_at',v_completion.completed_at,
    'payment_label',coalesce(nullif(v_order.checkout_snapshot->>'payment_label',''),nullif(v_order.payment_method,''),'A confirmar'),
    'customer_name',coalesce(nullif(v_order.customer_snapshot->>'name',''),nullif(v_order.customer_snapshot->>'display_name',''),nullif(v_order.delivery_address->>'customer_name',''),'Cliente'),
    'delivery',jsonb_strip_nulls(jsonb_build_object(
      'street',v_order.delivery_address->>'street',
      'number',v_order.delivery_address->>'number',
      'complement',v_order.delivery_address->>'complement',
      'district',coalesce(nullif(v_order.delivery_address->>'district',''),nullif(v_order.delivery_address->>'neighborhood','')),
      'city',v_order.delivery_address->>'city',
      'state',v_order.delivery_address->>'state',
      'reference',coalesce(nullif(v_order.delivery_address->>'reference',''),nullif(v_order.delivery_address->>'raw_text','')),
      'delivery_date',v_order.delivery_address->>'delivery_date',
      'delivery_label',v_order.delivery_address->>'delivery_label'
    )),
    'baskets',coalesce((
      select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
        'id',coalesce(bt.id::text,x.item->>'id'),
        'name',coalesce(bt.name,v_order.basket_name_snapshot,'Cesta'),
        'image_url',nullif(bt.image_url,''),
        'quantity',coalesce(nullif(x.item->>'qty','')::numeric,1)
      )) order by x.ord)
      from jsonb_array_elements(coalesce(v_order.checkout_snapshot->'cart','[]'::jsonb)) with ordinality as x(item,ord)
      left join public.basket_templates bt on bt.id::text=x.item->>'id'
      where x.item->>'type' in ('basket','basket_mold')
    ),'[]'::jsonb),
    'items',coalesce((
      select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
        'order_item_id',oi.id::text,
        'name',oi.name_snapshot,
        'quantity',oi.quantity,
        'unit_price',oi.unit_price,
        'line_total',oi.line_total,
        'image_url',nullif(coalesce(oi.metadata->>'image_url',p.image_url,''),''),
        'basket_name',nullif(oi.metadata->>'basket_name',''),
        'basket_id',nullif(oi.metadata->>'basket_id',''),
        'kind',coalesce(nullif(oi.metadata->>'history_kind',''),'product'),
        'separation_state',si.state
      )) order by oi.created_at,oi.id)
      from public.order_items oi
      left join public.products p on p.id=oi.product_id
      left join public.order_separation_items_v1 si
        on si.order_id=oi.order_id and si.order_item_id=oi.id
      where oi.order_id=p_order_id
        and oi.quantity>0
        and not (
          coalesce(oi.metadata->>'history_kind','') in ('basket','basket_mold')
          and exists(
            select 1
            from public.order_items c
            where c.order_id=p_order_id
              and coalesce(c.metadata->>'history_kind','') in ('basket_component','basket_mold_component')
              and (
                (
                  nullif(oi.metadata->>'basket_id','') is not null
                  and nullif(c.metadata->>'basket_id','')=nullif(oi.metadata->>'basket_id','')
                )
                or lower(trim(coalesce(nullif(c.metadata->>'basket_name',''),nullif(c.metadata->>'parent_basket_name',''),'')))
                   = lower(trim(coalesce(nullif(oi.metadata->>'basket_name',''),oi.name_snapshot,'')))
              )
          )
        )
    ),'[]'::jsonb)
  )) into v_snapshot;

  insert into public.order_public_snapshots_v1 as existing_snapshot
    (order_id,public_code,snapshot,refreshed_at)
  values(
    p_order_id,
    case
      when v_order.order_number ~ '^[A-Z]{2}[0-9]{3}$'
      then v_order.order_number
      else public.ops2_format_order_public_code_v1(nextval('public.order_public_code_seq_v1'::regclass))
    end,
    v_snapshot,
    now()
  )
  on conflict(order_id) do update
    set public_code = case
          when v_order.order_number ~ '^[A-Z]{2}[0-9]{3}$'
      then excluded.public_code
          else existing_snapshot.public_code
        end,
        snapshot=excluded.snapshot,
        refreshed_at=now();

  return v_snapshot;
end;
$function$
;

-- function: ops2_refresh_order_registration_journey_v1(p_order_id uuid, p_emit_event boolean)
CREATE OR REPLACE FUNCTION public.ops2_refresh_order_registration_journey_v1(p_order_id uuid, p_emit_event boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_order public.orders%rowtype;
  v_state jsonb;
  v_new_state text;
  v_old_state text;
  v_missing text[] := '{}'::text[];
  v_workflow_open boolean := false;
  v_seq integer := 1;
  v_event_type text;
  v_existing public.ops2_customer_registration_journeys_v1%rowtype;
  v_event_id uuid;
begin
  select o.* into v_order
  from public.orders o
  where o.id=p_order_id;

  if not found then
    return jsonb_build_object('ok',false,'error','order_not_found','order_id',p_order_id);
  end if;

  if v_order.source not in ('vitrine','storefront_v2') then
    delete from public.ops2_customer_registration_journeys_v1 j where j.order_id=p_order_id;
    return jsonb_build_object('ok',true,'skipped',true,'reason','not_site_order','order_id',p_order_id);
  end if;

  if v_order.customer_id is null then
    delete from public.ops2_customer_registration_journeys_v1 j where j.order_id=p_order_id;
    return jsonb_build_object('ok',false,'error','customer_missing','order_id',p_order_id);
  end if;

  v_state:=public.ops2_customer_registration_state_v1(v_order.customer_id);
  if coalesce((v_state->>'ok')::boolean,false)=false then
    return jsonb_build_object('ok',false,'error',coalesce(v_state->>'error','registration_state_failed'),'order_id',p_order_id);
  end if;

  v_new_state:=case when coalesce((v_state->>'registration_complete')::boolean,false) then 'complete' else 'pending' end;

  select coalesce(array_agg(x.value order by x.ord),'{}'::text[])
    into v_missing
  from jsonb_array_elements_text(coalesce(v_state->'missing_fields','[]'::jsonb)) with ordinality as x(value,ord);

  v_workflow_open:=v_new_state='pending'
    and v_order.status not in ('delivered','cancelled','returned');

  select j.* into v_existing
  from public.ops2_customer_registration_journeys_v1 j
  where j.order_id=p_order_id
  for update;

  if not found then
    v_seq:=1;
    insert into public.ops2_customer_registration_journeys_v1(
      order_id,customer_id,registration_state,missing_fields,workflow_open,transition_seq,
      first_evaluated_at,first_pending_at,completed_at,last_transition_at,last_evaluated_at,
      order_status_snapshot,metadata
    ) values (
      p_order_id,v_order.customer_id,v_new_state,v_missing,v_workflow_open,v_seq,
      now(),case when v_new_state='pending' then now() end,
      case when v_new_state='complete' then now() end,
      now(),now(),v_order.status,
      jsonb_build_object('source','derived','initial_state',true)
    );

    if p_emit_event then
      v_event_type:=case when v_new_state='pending' then 'customer.registration_required' else 'customer.registration_completed' end;
    end if;
  else
    v_old_state:=v_existing.registration_state;
    v_seq:=v_existing.transition_seq;

    if v_old_state is distinct from v_new_state then
      v_seq:=v_seq+1;
      update public.ops2_customer_registration_journeys_v1
      set customer_id=v_order.customer_id,
          registration_state=v_new_state,
          missing_fields=v_missing,
          workflow_open=v_workflow_open,
          transition_seq=v_seq,
          first_pending_at=case
            when v_new_state='pending' then coalesce(first_pending_at,now())
            else first_pending_at
          end,
          completed_at=case when v_new_state='complete' then now() else null end,
          last_transition_at=now(),
          last_evaluated_at=now(),
          order_status_snapshot=v_order.status,
          metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('source','derived','initial_state',false)
      where order_id=p_order_id;

      if p_emit_event then
        v_event_type:=case
          when v_new_state='complete' then 'customer.registration_completed'
          else 'customer.registration_reopened'
        end;
      end if;
    else
      update public.ops2_customer_registration_journeys_v1
      set customer_id=v_order.customer_id,
          missing_fields=v_missing,
          workflow_open=v_workflow_open,
          last_evaluated_at=now(),
          order_status_snapshot=v_order.status
      where order_id=p_order_id;
    end if;
  end if;

  if p_emit_event and v_event_type is not null then
    insert into public.ops_events(
      domain,event_type,entity_type,entity_id,correlation_id,
      actor_type,source_system,severity,summary,payload,idempotency_key
    ) values (
      'customer',v_event_type,'order',p_order_id::text,p_order_id::text,
      'system','dona_antonia','info',
      case v_event_type
        when 'customer.registration_required' then 'Customer registration required for site order'
        when 'customer.registration_completed' then 'Customer registration completed for site order'
        else 'Customer registration reopened for site order'
      end,
      jsonb_build_object(
        'order_id',p_order_id,
        'customer_id',v_order.customer_id,
        'registration_state',v_new_state,
        'missing_fields',to_jsonb(v_missing),
        'workflow_open',v_workflow_open,
        'transition_seq',v_seq
      ),
      format('customer_registration:%s:%s:%s',p_order_id,v_new_state,v_seq)
    )
    on conflict (idempotency_key) where idempotency_key is not null do nothing
    returning id into v_event_id;
  end if;

  return jsonb_build_object(
    'ok',true,
    'order_id',p_order_id,
    'customer_id',v_order.customer_id,
    'registration_state',v_new_state,
    'missing_fields',to_jsonb(v_missing),
    'workflow_open',v_workflow_open,
    'transition_seq',v_seq,
    'event_type',v_event_type,
    'event_created',v_event_id is not null
  );
end;
$function$
;

-- function: ops2_refresh_storefront_order_whatsapp_v1()
CREATE OR REPLACE FUNCTION public.ops2_refresh_storefront_order_whatsapp_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.source not in ('vitrine','storefront_v2') then
    return new;
  end if;

  if new.conversation_id is not distinct from old.conversation_id
     and new.whatsapp_account_id is not distinct from old.whatsapp_account_id
     and new.customer_id is not distinct from old.customer_id
     and new.phone_e164 is not distinct from old.phone_e164 then
    return new;
  end if;

  begin
    perform public.ops2_enqueue_order_whatsapp_v1(new.id,'order_received');
  exception when others then
    raise warning 'ops2_refresh_storefront_order_whatsapp_v1 failed for order %: %',new.id,sqlerrm;
  end;
  return new;
end;
$function$
;

-- function: ops2_registration_journey_outbound_intent_trigger_v1()
CREATE OR REPLACE FUNCTION public.ops2_registration_journey_outbound_intent_trigger_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform public.ops2_plan_registration_flow_intent_v1(new.order_id);
  return new;
end;
$function$
;

-- function: ops2_render_whatsapp_template_body_v1(p_whatsapp_account_id uuid, p_template_name text, p_components jsonb, p_variable_values jsonb)
CREATE OR REPLACE FUNCTION public.ops2_render_whatsapp_template_body_v1(p_whatsapp_account_id uuid, p_template_name text, p_components jsonb DEFAULT '[]'::jsonb, p_variable_values jsonb DEFAULT '{}'::jsonb)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_body text;
  v_parameters jsonb:='[]'::jsonb;
  v_values jsonb:=case when jsonb_typeof(p_variable_values)='object' then p_variable_values else '{}'::jsonb end;
  v_index integer;
  v_value text;
begin
  if p_whatsapp_account_id is null or nullif(btrim(coalesce(p_template_name,'')),'') is null then return null; end if;
  select component->>'text' into v_body
  from public.whatsapp_templates_v1 t
  cross join lateral jsonb_array_elements(
    case when jsonb_typeof(t.components)='array' then t.components else '[]'::jsonb end
  ) component
  where t.whatsapp_account_id=p_whatsapp_account_id
    and t.name=p_template_name
    and upper(coalesce(component->>'type',''))='BODY'
    and t.language='pt_BR'
  order by t.updated_at desc
  limit 1;
  if nullif(btrim(coalesce(v_body,'')),'') is null then return null; end if;

  select component->'parameters' into v_parameters
  from jsonb_array_elements(
    case when jsonb_typeof(p_components)='array' then p_components else '[]'::jsonb end
  ) component
  where lower(coalesce(component->>'type',''))='body'
  limit 1;
  if jsonb_typeof(v_parameters)<>'array' then v_parameters:='[]'::jsonb; end if;

  for v_index in 1..80 loop
    if position('{{'||v_index::text||'}}' in v_body)>0 then
      v_value:=nullif(v_values->>v_index::text,'');
      if v_value is null and jsonb_array_length(v_parameters)>=v_index then
        v_value:=nullif(v_parameters->(v_index-1)->>'text','');
      end if;
      if v_value is null then return null; end if;
      v_body:=replace(v_body,'{{'||v_index::text||'}}',v_value);
    end if;
  end loop;
  if v_body ~ '\{\{[0-9]+\}\}' then return null; end if;
  return v_body;
end;
$function$
;

-- function: ops2_require_separator_completion_v4()
CREATE OR REPLACE FUNCTION public.ops2_require_separator_completion_v4()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.separator_key is null
     or new.separator_key not in ('jose','claudio','jovenil','kelly') then
    raise exception 'separator_required_before_completion';
  end if;
  return new;
end;
$function$
;

-- function: ops2_resolve_order_registration_link_v1(p_token text)
CREATE OR REPLACE FUNCTION public.ops2_resolve_order_registration_link_v1(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_hash text;
  v_link public.ops2_order_registration_links_v1%rowtype;
begin
  if nullif(btrim(coalesce(p_token,'')),'') is null then
    return jsonb_build_object('ok',false,'error','order_token_required');
  end if;
  v_hash:=encode(extensions.digest(btrim(p_token),'sha256'),'hex');

  select l.* into v_link
  from public.ops2_order_registration_links_v1 l
  where l.token_hash=v_hash;
  if not found then
    return jsonb_build_object('ok',false,'error','order_token_invalid');
  end if;
  if v_link.revoked_at is not null then
    return jsonb_build_object('ok',false,'error','order_token_invalid');
  end if;
  if v_link.consumed_at is not null then
    return jsonb_build_object('ok',false,'error','token_already_used');
  end if;
  if v_link.expires_at<=now() then
    return jsonb_build_object('ok',false,'error','token_expired');
  end if;

  return jsonb_build_object(
    'ok',true,
    'phone_e164',v_link.phone_e164,
    'expires_at',v_link.expires_at
  );
end;
$function$
;

-- function: ops2_rollback_bling_stock_authority_v1(p_reason text)
CREATE OR REPLACE FUNCTION public.ops2_rollback_bling_stock_authority_v1(p_reason text)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ select jsonb_build_object('ok',false,'error','supabase_stock_authority_fixed','authority','supabase'); $function$
;

-- function: ops2_set_lot_tracking_complete_v1(p_product_id uuid, p_complete boolean, p_operator text)
CREATE OR REPLACE FUNCTION public.ops2_set_lot_tracking_complete_v1(p_product_id uuid, p_complete boolean, p_operator text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_product public.products%rowtype;
  v_count integer;
  v_unquantified integer;
  v_tracked numeric(14,3);
  v_catalog_stock numeric(14,3);
begin
  select * into v_product from public.products where id=p_product_id for update;
  if not found then raise exception 'product_not_found'; end if;
  v_catalog_stock:=round(coalesce(v_product.stock,0),3);
  select count(*) filter(where status<>'cancelled'),
         count(*) filter(where status<>'cancelled' and quantity_on_hand is null),
         coalesce(sum(coalesce(quantity_on_hand,0)) filter(where status<>'cancelled' and source<>'bling'),0)
    into v_count,v_unquantified,v_tracked
    from public.product_inventory_lots
   where product_id=p_product_id and source<>'bling';
  if p_complete then
    if v_count=0 then raise exception 'lot_tracking_requires_lot'; end if;
    if v_unquantified>0 then raise exception 'lot_tracking_has_unquantified_lot'; end if;
    if abs(coalesce(v_tracked,0)-coalesce(v_catalog_stock,0))>0.001 then
      raise exception 'lot_tracking_catalog_stock_mismatch tracked=% supabase=%',v_tracked,v_catalog_stock;
    end if;
  end if;
  update public.products
     set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object(
       'lot_tracking_complete',coalesce(p_complete,false),
       'lot_tracking_updated_at',now(),
       'lot_tracking_updated_by',nullif(trim(coalesce(p_operator,'')),''),
       'lot_tracking_catalog_qty',v_tracked,
       'lot_tracking_stock_source','supabase.products.stock'
     ),updated_at=now()
   where id=p_product_id;
  return jsonb_build_object('ok',true,'product_id',p_product_id,'lot_tracking_complete',coalesce(p_complete,false),
    'lots',v_count,'unquantified_lots',v_unquantified,'tracked_quantity',v_tracked,
    'catalog_stock',v_catalog_stock,'stock_source','supabase.products.stock');
end;
$function$
;

-- function: ops2_set_order_separation_item_v2(p_order_id uuid, p_order_item_id uuid, p_state text, p_expected_order_updated_at timestamp with time zone, p_separator_key text)
CREATE OR REPLACE FUNCTION public.ops2_set_order_separation_item_v2(p_order_id uuid, p_order_item_id uuid, p_state text, p_expected_order_updated_at timestamp with time zone, p_separator_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_order public.orders%rowtype;
  v_item public.order_items%rowtype;
  v_state text := lower(trim(coalesce(p_state,'')));
  v_separator text := nullif(lower(trim(coalesce(p_separator_key,''))), '');
  v_now timestamptz := now();
begin
  if p_order_id is null or p_order_item_id is null then
    return jsonb_build_object('ok',false,'error','invalid_order_item');
  end if;

  if v_state not in ('separated','missing') then
    return jsonb_build_object('ok',false,'error','invalid_separation_state');
  end if;

  if v_separator='claudenil' then v_separator:='claudio'; end if;
  if v_separator is not null and v_separator not in ('jose','claudio','kelly','jovenil') then
    return jsonb_build_object('ok',false,'error','invalid_separator');
  end if;

  select * into v_order from public.orders where id=p_order_id for update;
  if not found then return jsonb_build_object('ok',false,'error','order_not_found'); end if;

  if v_order.status not in ('confirmed','processing') then
    return jsonb_build_object('ok',false,'error','order_not_in_separation','status',v_order.status);
  end if;

  if p_expected_order_updated_at is null or v_order.updated_at is distinct from p_expected_order_updated_at then
    return jsonb_build_object('ok',false,'error','stale_order_version','conflict','order_version_conflict','order_updated_at',v_order.updated_at);
  end if;

  if exists(select 1 from public.order_separation_completions_v1 where order_id=p_order_id) then
    return jsonb_build_object('ok',false,'error','separation_already_completed');
  end if;

  select * into v_item
  from public.order_items
  where id=p_order_item_id and order_id=p_order_id and quantity>0;
  if not found then return jsonb_build_object('ok',false,'error','order_item_not_found'); end if;

  insert into public.order_separation_items_v1(
    order_id,order_item_id,product_id,state,quantity,unit_price,line_total,
    changed_at,changed_by_separator_key,created_at,updated_at
  ) values(
    p_order_id,v_item.id,v_item.product_id,v_state,v_item.quantity,v_item.unit_price,v_item.line_total,
    v_now,v_separator,v_now,v_now
  )
  on conflict (order_id,order_item_id) do update
    set state=excluded.state,
        changed_at=v_now,
        changed_by_separator_key=v_separator,
        updated_at=v_now;

  update public.orders set updated_at=v_now where id=p_order_id;

  return jsonb_build_object(
    'ok',true,
    'order_id',p_order_id,
    'order_item_id',p_order_item_id,
    'state',v_state,
    'changed_by_separator_key',v_separator,
    'order_updated_at',v_now
  );
end;
$function$
;

-- function: ops2_set_order_separator_v2(p_order_id uuid, p_separator_key text)
CREATE OR REPLACE FUNCTION public.ops2_set_order_separator_v2(p_order_id uuid, p_separator_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_order public.orders%rowtype;
  v_completion public.order_separation_completions_v1%rowtype;
  v_key text := nullif(lower(trim(coalesce(p_separator_key,''))), '');
  v_label text;
  v_now timestamptz := now();
begin
  if p_order_id is null then
    return jsonb_build_object('ok',false,'error','invalid_order_id');
  end if;

  if v_key is not null and v_key not in ('jose','claudio','jovenil','kelly') then
    return jsonb_build_object('ok',false,'error','invalid_separator');
  end if;

  select * into v_order
  from public.orders
  where id=p_order_id
  for update;

  if not found then
    return jsonb_build_object('ok',false,'error','order_not_found');
  end if;

  if v_order.status not in ('confirmed','processing','ready') then
    return jsonb_build_object('ok',false,'error','order_not_in_separation','status',v_order.status);
  end if;

  select * into v_completion
  from public.order_separation_completions_v1
  where order_id=p_order_id
  for update;

  if found and v_completion.completed_at is not null then
    return jsonb_build_object('ok',false,'error','separation_already_completed');
  end if;

  v_label := case v_key
    when 'jose' then 'José'
    when 'claudio' then 'Cláudio'
    when 'jovenil' then 'Jovenil'
    when 'kelly' then 'Kelly'
    else null
  end;

  insert into public.order_separation_assignments_v1(
    order_id,separator_key,separator_label,assigned_at,created_at,updated_at
  ) values(
    p_order_id,v_key,v_label,case when v_key is null then null else v_now end,v_now,v_now
  )
  on conflict (order_id) do update
    set separator_key=excluded.separator_key,
        separator_label=excluded.separator_label,
        assigned_at=excluded.assigned_at,
        updated_at=v_now;

  if v_completion.id is not null and v_completion.completed_at is null then
    update public.order_separation_completions_v1
    set separator_key=v_key,
        metadata=coalesce(metadata,'{}'::jsonb) || jsonb_build_object(
          'separator_reassigned_at',v_now,
          'separator_label',v_label
        ),
        updated_at=v_now
    where order_id=p_order_id;
  end if;

  update public.orders
  set updated_at=v_now
  where id=p_order_id;

  return jsonb_build_object(
    'ok',true,
    'order_id',p_order_id,
    'separator_key',v_key,
    'separator_label',v_label,
    'assigned_at',case when v_key is null then null else v_now end,
    'order_updated_at',v_now
  );
end;
$function$
;

-- function: ops2_site_admin_customer_by_document_v1(p_document text)
CREATE OR REPLACE FUNCTION public.ops2_site_admin_customer_by_document_v1(p_document text)
 RETURNS uuid
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  select c.id from public.customers c
  where c.is_active=true
    and regexp_replace(coalesce(c.cpf_cnpj,''), '[^0-9]', '', 'g') = regexp_replace(coalesce(p_document,''), '[^0-9]', '', 'g')
    and length(regexp_replace(coalesce(p_document,''), '[^0-9]', '', 'g')) in (11,14)
  limit 1;
$function$
;

-- function: ops2_site_admin_customer_delete_v1(p_customer_id uuid, p_expected_customer_updated_at timestamp with time zone)
CREATE OR REPLACE FUNCTION public.ops2_site_admin_customer_delete_v1(p_customer_id uuid, p_expected_customer_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_customer public.customers%rowtype;
  v_when timestamptz := clock_timestamp();
begin
  if p_customer_id is null or p_expected_customer_updated_at is null then
    return jsonb_build_object('ok', false, 'error', 'invalid_customer_snapshot');
  end if;
  select * into v_customer
    from public.customers
    where id=p_customer_id and is_active=true
    for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'customer_not_found');
  end if;
  if v_customer.updated_at is distinct from p_expected_customer_updated_at then
    return jsonb_build_object('ok', false, 'error', 'customer_changed');
  end if;

  update public.customers
     set is_active=false,
         cpf_cnpj=null,
         primary_whatsapp_e164=null,
         marketing_opt_in=false,
         updated_at=v_when
   where id=p_customer_id;

  delete from public.customer_phones where customer_id=p_customer_id;
  delete from public.customer_emails where customer_id=p_customer_id;
  update public.customer_addresses
    set is_active=false, is_default=false, updated_at=v_when
    where customer_id=p_customer_id and is_active=true;
  update public.customer_identity_profiles_v1
    set canonical_phone_e164=null, updated_at=v_when
    where customer_id=p_customer_id;

  insert into public.admin_audit_logs (
    admin_user_id,action,entity_type,entity_id,details
  ) values (
    null,'customer_delete_admin_code','customer',p_customer_id::text,
    jsonb_build_object('source','site_admin_code','mode','deactivate_and_release_identifiers',
                       'preserves','orders_and_commercial_history')
  );
  return jsonb_build_object('ok',true,'deleted',true,'customer_id',p_customer_id);
end;
$function$
;

-- function: ops2_site_admin_customer_update_v1(p_customer_id uuid, p_expected_customer_updated_at timestamp with time zone, p_name text, p_address_id uuid, p_expected_address_updated_at timestamp with time zone, p_address jsonb)
CREATE OR REPLACE FUNCTION public.ops2_site_admin_customer_update_v1(p_customer_id uuid, p_expected_customer_updated_at timestamp with time zone, p_name text, p_address_id uuid, p_expected_address_updated_at timestamp with time zone, p_address jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_customer_updated_at timestamptz;
  v_address_updated_at timestamptz;
  v_address_id uuid := p_address_id;
  v_now timestamptz := clock_timestamp();
  v_name text := btrim(coalesce(p_name, ''));
  v_street text := btrim(coalesce(p_address->>'street', ''));
  v_number text := btrim(coalesce(p_address->>'number', ''));
  v_complement text := nullif(btrim(coalesce(p_address->>'complement', '')), '');
  v_neighborhood text := btrim(coalesce(p_address->>'neighborhood', ''));
  v_city text := btrim(coalesce(p_address->>'city', ''));
  v_state text := upper(btrim(coalesce(p_address->>'state', '')));
  v_postal_code text := nullif(btrim(coalesce(p_address->>'postal_code', '')), '');
  v_reference text := nullif(btrim(coalesce(p_address->>'reference', '')), '');
  v_has_address boolean;
begin
  if p_customer_id is null or p_expected_customer_updated_at is null then
    return jsonb_build_object('ok', false, 'error', 'invalid_customer_snapshot');
  end if;
  if length(v_name) < 2 or length(v_name) > 180 then
    return jsonb_build_object('ok', false, 'error', 'customer_name_required');
  end if;

  v_has_address := concat_ws('', v_street, v_number, v_complement, v_neighborhood, v_city, v_state, v_postal_code, v_reference) <> '';
  if v_has_address and (
    v_street = '' or v_number = '' or v_neighborhood = '' or v_city = '' or length(v_state) <> 2
  ) then
    return jsonb_build_object('ok', false, 'error', 'invalid_customer_address');
  end if;
  if p_address_id is not null and (not v_has_address or p_expected_address_updated_at is null) then
    return jsonb_build_object('ok', false, 'error', 'invalid_address_snapshot');
  end if;

  select c.updated_at
    into v_customer_updated_at
  from public.customers as c
  where c.id = p_customer_id and c.is_active = true
  for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'customer_not_found');
  end if;
  if v_customer_updated_at is distinct from p_expected_customer_updated_at then
    return jsonb_build_object('ok', false, 'error', 'customer_changed');
  end if;

  if p_address_id is not null then
    select a.updated_at
      into v_address_updated_at
    from public.customer_addresses as a
    where a.id = p_address_id and a.customer_id = p_customer_id and a.is_active = true
    for update;
    if not found then
      return jsonb_build_object('ok', false, 'error', 'customer_address_not_found');
    end if;
    if v_address_updated_at is distinct from p_expected_address_updated_at then
      return jsonb_build_object('ok', false, 'error', 'customer_changed');
    end if;
  end if;

  update public.customers
  set name = v_name, updated_at = v_now
  where id = p_customer_id
  returning updated_at into v_customer_updated_at;

  if p_address_id is not null then
    update public.customer_addresses
    set street = v_street,
        number = v_number,
        complement = v_complement,
        neighborhood = v_neighborhood,
        city = v_city,
        state = v_state,
        postal_code = v_postal_code,
        reference = v_reference,
        updated_at = v_now
    where id = p_address_id and customer_id = p_customer_id
    returning id, updated_at into v_address_id, v_address_updated_at;
  elsif v_has_address then
    insert into public.customer_addresses (
      customer_id, street, number, complement, neighborhood, city, state,
      postal_code, reference, is_default, is_active, updated_at
    )
    values (
      p_customer_id, v_street, v_number, v_complement, v_neighborhood, v_city, v_state,
      v_postal_code, v_reference, false, true, v_now
    )
    returning id, updated_at into v_address_id, v_address_updated_at;
  end if;

  insert into public.admin_audit_logs (
    admin_user_id, action, entity_type, entity_id, details
  )
  values (
    null,
    'customer_update_admin_code',
    'customer',
    p_customer_id::text,
    jsonb_build_object(
      'source', 'site_admin_code',
      'fields', case when v_address_id is null then jsonb_build_array('name')
                     else jsonb_build_array('name', 'address') end,
      'address_id', v_address_id
    )
  );

  return jsonb_build_object(
    'ok', true,
    'customer_updated_at', v_customer_updated_at,
    'address_id', v_address_id,
    'address_updated_at', v_address_updated_at
  );
end;
$function$
;

-- function: ops2_site_admin_customer_update_v2(p_customer_id uuid, p_expected_customer_updated_at timestamp with time zone, p_name text, p_address_id uuid, p_expected_address_updated_at timestamp with time zone, p_address jsonb, p_document text)
CREATE OR REPLACE FUNCTION public.ops2_site_admin_customer_update_v2(p_customer_id uuid, p_expected_customer_updated_at timestamp with time zone, p_name text, p_address_id uuid, p_expected_address_updated_at timestamp with time zone, p_address jsonb, p_document text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_customer_updated_at timestamptz;
  v_address_updated_at timestamptz;
  v_address_id uuid := p_address_id;
  v_now timestamptz := clock_timestamp();
  v_name text := btrim(coalesce(p_name, ''));
  v_street text := btrim(coalesce(p_address->>'street', ''));
  v_number text := btrim(coalesce(p_address->>'number', ''));
  v_complement text := nullif(btrim(coalesce(p_address->>'complement', '')), '');
  v_neighborhood text := btrim(coalesce(p_address->>'neighborhood', ''));
  v_city text := btrim(coalesce(p_address->>'city', ''));
  v_state text := upper(btrim(coalesce(p_address->>'state', '')));
  v_postal_code text := nullif(btrim(coalesce(p_address->>'postal_code', '')), '');
  v_reference text := nullif(btrim(coalesce(p_address->>'reference', '')), '');
  v_has_address boolean;
  v_document text := regexp_replace(coalesce(p_document, ''), '[^0-9]', '', 'g');
  v_previous_document text;
begin
  if p_customer_id is null or p_expected_customer_updated_at is null then
    return jsonb_build_object('ok', false, 'error', 'invalid_customer_snapshot');
  end if;
  if length(v_name) < 2 or length(v_name) > 180 then
    return jsonb_build_object('ok', false, 'error', 'customer_name_required');
  end if;

  v_has_address := concat_ws('', v_street, v_number, v_complement, v_neighborhood, v_city, v_state, v_postal_code, v_reference) <> '';
  if v_has_address and (
    v_street = '' or v_number = '' or v_neighborhood = '' or v_city = '' or length(v_state) <> 2
  ) then
    return jsonb_build_object('ok', false, 'error', 'invalid_customer_address');
  end if;
  if p_address_id is not null and (not v_has_address or p_expected_address_updated_at is null) then
    return jsonb_build_object('ok', false, 'error', 'invalid_address_snapshot');
  end if;

  select c.updated_at, c.cpf_cnpj
    into v_customer_updated_at, v_previous_document
  from public.customers as c
  where c.id = p_customer_id and c.is_active = true
  for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'customer_not_found');
  end if;
  if v_customer_updated_at is distinct from p_expected_customer_updated_at then
    return jsonb_build_object('ok', false, 'error', 'customer_changed');
  end if;

  if v_document <> '' and not public.ops2_valid_cpf_cnpj_v1(v_document)
    and v_document is distinct from regexp_replace(coalesce(v_previous_document, ''), '[^0-9]', '', 'g') then
    return jsonb_build_object('ok', false, 'error', 'invalid_document');
  end if;
  if v_document <> '' and exists (
    select 1 from public.customers c
    where c.id <> p_customer_id
      and regexp_replace(coalesce(c.cpf_cnpj,''), '[^0-9]', '', 'g') = v_document
  ) then
    return jsonb_build_object('ok', false, 'error', 'document_already_in_use');
  end if;

  if p_address_id is not null then
    select a.updated_at
      into v_address_updated_at
    from public.customer_addresses as a
    where a.id = p_address_id and a.customer_id = p_customer_id and a.is_active = true
    for update;
    if not found then
      return jsonb_build_object('ok', false, 'error', 'customer_address_not_found');
    end if;
    if v_address_updated_at is distinct from p_expected_address_updated_at then
      return jsonb_build_object('ok', false, 'error', 'customer_changed');
    end if;
  end if;

  update public.customers
  set name = v_name, cpf_cnpj = nullif(v_document,''), updated_at = v_now
  where id = p_customer_id
  returning updated_at into v_customer_updated_at;

  if p_address_id is not null then
    update public.customer_addresses
    set street = v_street,
        number = v_number,
        complement = v_complement,
        neighborhood = v_neighborhood,
        city = v_city,
        state = v_state,
        postal_code = v_postal_code,
        reference = v_reference,
        updated_at = v_now
    where id = p_address_id and customer_id = p_customer_id
    returning id, updated_at into v_address_id, v_address_updated_at;
  elsif v_has_address then
    insert into public.customer_addresses (
      customer_id, street, number, complement, neighborhood, city, state,
      postal_code, reference, is_default, is_active, updated_at
    )
    values (
      p_customer_id, v_street, v_number, v_complement, v_neighborhood, v_city, v_state,
      v_postal_code, v_reference, false, true, v_now
    )
    returning id, updated_at into v_address_id, v_address_updated_at;
  end if;

  insert into public.admin_audit_logs (
    admin_user_id, action, entity_type, entity_id, details
  )
  values (
    null,
    'customer_update_admin_code',
    'customer',
    p_customer_id::text,
    jsonb_build_object(
      'source', 'site_admin_code',
      'fields', case when v_address_id is null then jsonb_build_array('name')
                     else jsonb_build_array('name', 'address') end
      || case when nullif(regexp_replace(coalesce(v_previous_document,''), '[^0-9]', '', 'g'),'') is distinct from nullif(v_document,'')
            then jsonb_build_array('cpf_cnpj') else '[]'::jsonb end,
      'address_id', v_address_id
    )
  );

  return jsonb_build_object(
    'ok', true,
    'customer_updated_at', v_customer_updated_at,
    'address_id', v_address_id,
    'address_updated_at', v_address_updated_at
  );
end;
$function$
;

-- function: ops2_site_admin_customer_update_v3(p_customer_id uuid, p_expected_customer_updated_at timestamp with time zone, p_name text, p_address_id uuid, p_expected_address_updated_at timestamp with time zone, p_address jsonb, p_document text, p_phone text)
CREATE OR REPLACE FUNCTION public.ops2_site_admin_customer_update_v3(p_customer_id uuid, p_expected_customer_updated_at timestamp with time zone, p_name text, p_address_id uuid, p_expected_address_updated_at timestamp with time zone, p_address jsonb, p_document text, p_phone text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_customer_updated_at timestamptz;
  v_address_updated_at timestamptz;
  v_address_id uuid := p_address_id;
  v_now timestamptz := clock_timestamp();
  v_name text := btrim(coalesce(p_name, ''));
  v_street text := btrim(coalesce(p_address->>'street', ''));
  v_number text := btrim(coalesce(p_address->>'number', ''));
  v_complement text := nullif(btrim(coalesce(p_address->>'complement', '')), '');
  v_neighborhood text := btrim(coalesce(p_address->>'neighborhood', ''));
  v_city text := btrim(coalesce(p_address->>'city', ''));
  v_state text := upper(btrim(coalesce(p_address->>'state', '')));
  v_postal_code text := nullif(btrim(coalesce(p_address->>'postal_code', '')), '');
  v_reference text := nullif(btrim(coalesce(p_address->>'reference', '')), '');
  v_has_address boolean;
  v_document text := regexp_replace(coalesce(p_document, ''), '[^0-9]', '', 'g');
  v_previous_document text;
  v_previous_phone text;
  v_phone text := btrim(coalesce(p_phone, ''));
  v_phone_row_id uuid;
begin
  if p_customer_id is null or p_expected_customer_updated_at is null then
    return jsonb_build_object('ok', false, 'error', 'invalid_customer_snapshot');
  end if;
  if v_phone !~ '^\+55[1-9][0-9]{9,10}$' then
    return jsonb_build_object('ok', false, 'error', 'invalid_phone');
  end if;
  if length(v_name) < 2 or length(v_name) > 180 then
    return jsonb_build_object('ok', false, 'error', 'customer_name_required');
  end if;

  v_has_address := concat_ws('', v_street, v_number, v_complement, v_neighborhood, v_city, v_state, v_postal_code, v_reference) <> '';
  if v_has_address and (
    v_street = '' or v_number = '' or v_neighborhood = '' or v_city = '' or length(v_state) <> 2
  ) then
    return jsonb_build_object('ok', false, 'error', 'invalid_customer_address');
  end if;
  if p_address_id is not null and (not v_has_address or p_expected_address_updated_at is null) then
    return jsonb_build_object('ok', false, 'error', 'invalid_address_snapshot');
  end if;

  select c.updated_at, c.cpf_cnpj, c.primary_whatsapp_e164
    into v_customer_updated_at, v_previous_document, v_previous_phone
  from public.customers as c
  where c.id = p_customer_id and c.is_active = true
  for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'customer_not_found');
  end if;
  if v_customer_updated_at is distinct from p_expected_customer_updated_at then
    return jsonb_build_object('ok', false, 'error', 'customer_changed');
  end if;

  if v_document <> '' and not public.ops2_valid_cpf_cnpj_v1(v_document)
    and v_document is distinct from regexp_replace(coalesce(v_previous_document, ''), '[^0-9]', '', 'g') then
    return jsonb_build_object('ok', false, 'error', 'invalid_document');
  end if;
  if v_document <> '' and exists (
    select 1 from public.customers c
    where c.id <> p_customer_id
      and regexp_replace(coalesce(c.cpf_cnpj,''), '[^0-9]', '', 'g') = v_document
  ) then
    return jsonb_build_object('ok', false, 'error', 'document_already_in_use');
  end if;

  if v_phone <> coalesce(v_previous_phone,'') and (
    exists(select 1 from public.customers c where c.id <> p_customer_id and c.primary_whatsapp_e164 = v_phone)
    or exists(select 1 from public.customer_phones cp where cp.customer_id <> p_customer_id
      and public.normalize_phone_digits(cp.phone_e164)=public.normalize_phone_digits(v_phone))
  ) then
    return jsonb_build_object('ok', false, 'error', 'phone_already_in_use');
  end if;

  if p_address_id is not null then
    select a.updated_at
      into v_address_updated_at
    from public.customer_addresses as a
    where a.id = p_address_id and a.customer_id = p_customer_id and a.is_active = true
    for update;
    if not found then
      return jsonb_build_object('ok', false, 'error', 'customer_address_not_found');
    end if;
    if v_address_updated_at is distinct from p_expected_address_updated_at then
      return jsonb_build_object('ok', false, 'error', 'customer_changed');
    end if;
  end if;

  update public.customers
  set name = v_name, cpf_cnpj = nullif(v_document,''), primary_whatsapp_e164 = v_phone, updated_at = v_now
  where id = p_customer_id
  returning updated_at into v_customer_updated_at;

  if v_phone is distinct from v_previous_phone then
    select cp.id into v_phone_row_id from public.customer_phones cp
      where cp.customer_id = p_customer_id and cp.phone_e164 = v_phone limit 1;
    if v_phone_row_id is null then
      select cp.id into v_phone_row_id from public.customer_phones cp
        where cp.customer_id = p_customer_id and cp.phone_e164 = v_previous_phone limit 1;
      if v_phone_row_id is not null then
        update public.customer_phones set phone_e164=v_phone where id=v_phone_row_id;
      else
        insert into public.customer_phones(customer_id,phone_e164,source,is_primary)
          values(p_customer_id,v_phone,'vitrine_admin',true);
      end if;
    end if;
    update public.customer_phones set is_primary=(phone_e164=v_phone)
      where customer_id=p_customer_id and is_primary is distinct from (phone_e164=v_phone);
  end if;

  if p_address_id is not null then
    update public.customer_addresses
    set street = v_street,
        number = v_number,
        complement = v_complement,
        neighborhood = v_neighborhood,
        city = v_city,
        state = v_state,
        postal_code = v_postal_code,
        reference = v_reference,
        updated_at = v_now
    where id = p_address_id and customer_id = p_customer_id
    returning id, updated_at into v_address_id, v_address_updated_at;
  elsif v_has_address then
    insert into public.customer_addresses (
      customer_id, street, number, complement, neighborhood, city, state,
      postal_code, reference, is_default, is_active, updated_at
    )
    values (
      p_customer_id, v_street, v_number, v_complement, v_neighborhood, v_city, v_state,
      v_postal_code, v_reference, not exists(
        select 1 from public.customer_addresses existing_address
        where existing_address.customer_id=p_customer_id and existing_address.is_active=true
      ), true, v_now
    )
    returning id, updated_at into v_address_id, v_address_updated_at;
  end if;

  insert into public.admin_audit_logs (
    admin_user_id, action, entity_type, entity_id, details
  )
  values (
    null,
    'customer_update_admin_code',
    'customer',
    p_customer_id::text,
    jsonb_build_object(
      'source', 'site_admin_code',
      'fields', case when v_address_id is null then jsonb_build_array('name')
                     else jsonb_build_array('name', 'address') end
      || case when nullif(regexp_replace(coalesce(v_previous_document,''), '[^0-9]', '', 'g'),'') is distinct from nullif(v_document,'')
            then jsonb_build_array('cpf_cnpj') else '[]'::jsonb end
      || case when v_phone is distinct from v_previous_phone then jsonb_build_array('primary_whatsapp_e164') else '[]'::jsonb end,
      'address_id', v_address_id
    )
  );

  return jsonb_build_object(
    'ok', true,
    'customer_updated_at', v_customer_updated_at,
    'address_id', v_address_id,
    'address_updated_at', v_address_updated_at
  );
end;
$function$
;

-- function: ops2_upsert_product_lot_v1(p_product_id uuid, p_lot_code text, p_expiration_date date, p_quantity_on_hand numeric, p_source text, p_source_ref text, p_received_at timestamp with time zone, p_metadata jsonb)
CREATE OR REPLACE FUNCTION public.ops2_upsert_product_lot_v1(p_product_id uuid, p_lot_code text, p_expiration_date date, p_quantity_on_hand numeric DEFAULT NULL::numeric, p_source text DEFAULT 'manual'::text, p_source_ref text DEFAULT NULL::text, p_received_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
begin
  if p_product_id is null or p_expiration_date is null then
    raise exception 'invalid_product_lot';
  end if;
  if p_quantity_on_hand is not null and p_quantity_on_hand<0 then
    raise exception 'invalid_lot_quantity';
  end if;
  if lower(trim(coalesce(p_source,''))) not in ('manual','inventory_count','purchase_xml','bling','legacy') then
    raise exception 'invalid_lot_source';
  end if;

  insert into public.product_inventory_lots(
    product_id,lot_code,expiration_date,quantity_on_hand,status,source,source_ref,received_at,metadata,updated_at
  ) values(
    p_product_id,nullif(trim(coalesce(p_lot_code,'')),''),
    p_expiration_date,p_quantity_on_hand,
    case when p_expiration_date<current_date then 'expired' else 'active' end,
    lower(trim(p_source)),nullif(trim(coalesce(p_source_ref,'')),''),
    p_received_at,coalesce(p_metadata,'{}'::jsonb),now()
  )
  on conflict(product_id,lot_code,expiration_date,source_ref)
  do update set
    quantity_on_hand=excluded.quantity_on_hand,
    status=case
      when product_inventory_lots.status in ('quarantine','cancelled') then product_inventory_lots.status
      when excluded.expiration_date<current_date then 'expired'
      when coalesce(excluded.quantity_on_hand,0)=0 and excluded.quantity_on_hand is not null then 'depleted'
      else 'active' end,
    received_at=coalesce(excluded.received_at,product_inventory_lots.received_at),
    metadata=coalesce(product_inventory_lots.metadata,'{}'::jsonb)||coalesce(excluded.metadata,'{}'::jsonb),
    updated_at=now()
  returning id into v_id;

  return jsonb_build_object('ok',true,'lot_id',v_id,'product_id',p_product_id,'expiration_date',p_expiration_date);
end;
$function$
;

-- function: ops2_upsert_storefront_registration_v1(p_phone text, p_name text, p_document text, p_street text, p_number text, p_neighborhood text, p_city text, p_complement text, p_reference text, p_postal_code text, p_marketing_opt_in boolean, p_source_key text)
CREATE OR REPLACE FUNCTION public.ops2_upsert_storefront_registration_v1(p_phone text, p_name text, p_document text, p_street text, p_number text, p_neighborhood text, p_city text, p_complement text DEFAULT NULL::text, p_reference text DEFAULT NULL::text, p_postal_code text DEFAULT NULL::text, p_marketing_opt_in boolean DEFAULT NULL::boolean, p_source_key text DEFAULT 'site_checkout'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_name text:=nullif(left(btrim(regexp_replace(coalesce(p_name,''),'\s+',' ','g')),180),'');
  v_document text:=regexp_replace(coalesce(p_document,''),'[^0-9]','','g');
  v_street text:=nullif(left(btrim(regexp_replace(coalesce(p_street,''),'\s+',' ','g')),180),'');
  v_number text:=nullif(left(btrim(regexp_replace(coalesce(p_number,''),'\s+',' ','g')),40),'');
  v_neighborhood text:=nullif(left(btrim(regexp_replace(coalesce(p_neighborhood,''),'\s+',' ','g')),120),'');
  v_city_input text:=nullif(left(btrim(regexp_replace(coalesce(p_city,''),'\s+',' ','g')),100),'');
  v_city_key text;
  v_city text;
  v_complement text:=nullif(left(btrim(regexp_replace(coalesce(p_complement,''),'\s+',' ','g')),180),'');
  v_reference text:=nullif(left(btrim(regexp_replace(coalesce(p_reference,''),'\s+',' ','g')),220),'');
  v_postal_code text:=nullif(left(regexp_replace(coalesce(p_postal_code,''),'[^0-9]','','g'),8),'');
  v_phone text:=public.canonical_whatsapp_e164_br_v2(p_phone);
  v_candidate_ids uuid[];
  v_doc_candidate_ids uuid[];
  v_identity jsonb;
  v_customer_id uuid;
  v_doc_owner uuid;
  v_existing_document text;
  v_existing_name text;
  v_address_id uuid;
  v_state jsonb;
  v_job uuid;
begin
  if v_name is null or char_length(v_name)<2 then return jsonb_build_object('ok',false,'error','name_required'); end if;
  if v_phone is null then return jsonb_build_object('ok',false,'error','invalid_phone'); end if;
  if not public.ops2_valid_cpf_cnpj_v1(v_document) then return jsonb_build_object('ok',false,'error','invalid_document'); end if;
  if v_street is null then return jsonb_build_object('ok',false,'error','street_required'); end if;
  if v_number is null then return jsonb_build_object('ok',false,'error','number_required'); end if;
  if v_neighborhood is null then return jsonb_build_object('ok',false,'error','neighborhood_required'); end if;
  if v_city_input is null then return jsonb_build_object('ok',false,'error','city_required'); end if;

  v_city_key:=translate(lower(v_city_input),'áàâãäéèêëíìîïóòôõöúùûüç','aaaaaeeeeiiiiooooouuuuc');
  if v_city_key='cuiaba' then v_city:='Cuiabá';
  elsif v_city_key='varzea grande' then v_city:='Várzea Grande';
  else return jsonb_build_object('ok',false,'error','unsupported_city','allowed_cities',jsonb_build_array('Cuiabá','Várzea Grande'));
  end if;

  perform pg_advisory_xact_lock(hashtextextended('ops2:customer-phone:'||v_phone,0));
  select coalesce(array_agg(x.customer_id order by x.customer_id),array[]::uuid[])
    into v_candidate_ids
    from public.customer_ids_by_phone_variants_v1(v_phone) x;

  if coalesce(array_length(v_candidate_ids,1),0)>1 then
    select coalesce(array_agg(c.id order by c.id),array[]::uuid[])
      into v_doc_candidate_ids
      from public.customers c
     where c.id=any(v_candidate_ids)
       and regexp_replace(coalesce(c.cpf_cnpj,''),'[^0-9]','','g')=v_document;

    if coalesce(array_length(v_doc_candidate_ids,1),0)=1 then
      v_customer_id:=v_doc_candidate_ids[1];
      v_identity:=jsonb_build_object(
        'ok',true,'customer_id',v_customer_id,'created',false,'status','verified_existing',
        'canonical_phone_e164',v_phone,'ambiguous_variants_observed',true
      );
    else
      return jsonb_build_object('ok',false,'error','ambiguous_phone','candidate_count',array_length(v_candidate_ids,1));
    end if;
  else
    v_identity:=public.ensure_storefront_customer_v2(v_phone,v_name,coalesce(nullif(p_source_key,''),'site_checkout'));
    if coalesce((v_identity->>'ok')::boolean,false) is not true then return v_identity; end if;
    v_customer_id:=(v_identity->>'customer_id')::uuid;
  end if;

  select regexp_replace(coalesce(c.cpf_cnpj,''),'[^0-9]','','g'),nullif(btrim(coalesce(c.name,'')),'')
    into v_existing_document,v_existing_name
    from public.customers c where c.id=v_customer_id;

  if public.ops2_valid_cpf_cnpj_v1(v_existing_document) and v_existing_document<>v_document then
    return jsonb_build_object('ok',false,'error','document_mismatch');
  end if;
  if not public.ops2_valid_cpf_cnpj_v1(v_existing_document)
     and v_existing_name is not null
     and lower(v_existing_name)<>lower(v_name) then
    return jsonb_build_object('ok',false,'error','identity_mismatch');
  end if;

  select c.id into v_doc_owner from public.customers c
   where c.id<>v_customer_id and regexp_replace(coalesce(c.cpf_cnpj,''),'[^0-9]','','g')=v_document limit 1;
  if v_doc_owner is not null then return jsonb_build_object('ok',false,'error','document_already_in_use'); end if;

  update public.customers
     set name=v_name,cpf_cnpj=v_document,primary_whatsapp_e164=v_phone,
         marketing_opt_in=case when p_marketing_opt_in is null then marketing_opt_in else p_marketing_opt_in end,
         marketing_consent_updated_at=case when p_marketing_opt_in is null then marketing_consent_updated_at else now() end,
         is_active=true,updated_at=now()
   where id=v_customer_id;

  select a.id into v_address_id from public.customer_addresses a
   where a.customer_id=v_customer_id and a.is_active=true
   order by a.is_default desc,a.updated_at desc,a.id limit 1 for update;

  update public.customer_addresses set is_default=false,updated_at=now()
   where customer_id=v_customer_id and is_active=true and id is distinct from v_address_id;

  if v_address_id is null then
    insert into public.customer_addresses(customer_id,label,street,number,complement,neighborhood,city,state,postal_code,reference,is_default,is_active,last_confirmed_at,created_at,updated_at)
    values(v_customer_id,'Entrega',v_street,v_number,v_complement,v_neighborhood,v_city,'MT',v_postal_code,v_reference,true,true,now(),now(),now())
    returning id into v_address_id;
  else
    update public.customer_addresses
       set label=coalesce(nullif(label,''),'Entrega'),street=v_street,number=v_number,complement=v_complement,
           neighborhood=v_neighborhood,city=v_city,state='MT',postal_code=v_postal_code,reference=v_reference,
           is_default=true,is_active=true,last_confirmed_at=now(),google_maps_url=null,latitude=null,longitude=null,updated_at=now()
     where id=v_address_id;
  end if;

  update public.customer_identity_profiles_v1
     set identity_status='verified_existing',canonical_phone_e164=v_phone,
         last_source_key=coalesce(nullif(left(p_source_key,220),''),last_source_key),
         metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('site_registration_completed_at',now()),updated_at=now()
   where customer_id=v_customer_id;

  v_state:=public.ops2_customer_registration_state_v1(v_customer_id);
  if coalesce((v_state->>'registration_complete')::boolean,false) is not true then
    return jsonb_build_object('ok',false,'error','registration_incomplete','customer_id',v_customer_id,'state',v_state);
  end if;

  v_job:=public.ops2_maybe_enqueue_customer_bling_v1(v_customer_id,'site_registration_completed');
  return jsonb_build_object('ok',true,'customer_id',v_customer_id,'canonical_phone_e164',v_phone,
    'registration_complete',true,'registration_state',v_state,'bling_job_id',v_job,
    'address',jsonb_build_object('id',v_address_id,'street',v_street,'number',v_number,'complement',v_complement,
      'neighborhood',v_neighborhood,'city',v_city,'state','MT','postal_code',v_postal_code,'reference',v_reference));
end;
$function$
;

-- function: ops2_valid_cpf_cnpj_v1(p_document text)
CREATE OR REPLACE FUNCTION public.ops2_valid_cpf_cnpj_v1(p_document text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  d text:=regexp_replace(coalesce(p_document,''),'[^0-9]','','g');
  i integer;
  s integer;
  w integer;
  digit integer;
begin
  if d ~ '^([0-9])\1+$' then return false; end if;

  if length(d)=11 then
    s:=0;
    for i in 1..9 loop
      s:=s+(substr(d,i,1)::integer)*(11-i);
    end loop;
    digit:=case when (s*10)%11=10 then 0 else (s*10)%11 end;
    if digit<>substr(d,10,1)::integer then return false; end if;

    s:=0;
    for i in 1..10 loop
      s:=s+(substr(d,i,1)::integer)*(12-i);
    end loop;
    digit:=case when (s*10)%11=10 then 0 else (s*10)%11 end;
    return digit=substr(d,11,1)::integer;
  end if;

  if length(d)=14 then
    s:=0;
    for i in 1..12 loop
      w:=case when i<=4 then 6-i else 14-i end;
      s:=s+(substr(d,i,1)::integer)*w;
    end loop;
    digit:=case when s%11<2 then 0 else 11-(s%11) end;
    if digit<>substr(d,13,1)::integer then return false; end if;

    s:=0;
    for i in 1..13 loop
      w:=case when i<=5 then 7-i else 15-i end;
      s:=s+(substr(d,i,1)::integer)*w;
    end loop;
    digit:=case when s%11<2 then 0 else 11-(s%11) end;
    return digit=substr(d,14,1)::integer;
  end if;

  return false;
end;
$function$
;

-- function: ops2_verify_catalog_stock_canary_v1(p_canary uuid)
CREATE OR REPLACE FUNCTION public.ops2_verify_catalog_stock_canary_v1(p_canary uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_confirmed int; v_divergent int;
begin
 update ops2_catalog_sync_canary_items i set
  verified_bling_physical=m.physical_total,
  verified_at=now(),
  state=case when m.physical_total is not distinct from i.desired_stock then 'confirmed' else 'divergent' end
 from bling_stock_mirror_v2 m
 where i.canary_id=p_canary and m.product_id=i.product_id and i.state in ('sent','queued');
 select count(*) filter(where state='confirmed'),count(*) filter(where state='divergent') into v_confirmed,v_divergent from ops2_catalog_sync_canary_items where canary_id=p_canary;
 update ops2_catalog_sync_canaries set status=case when v_divergent>0 then 'divergent' when v_confirmed=item_count and item_count>0 then 'verified' else status end where id=p_canary;
 return jsonb_build_object('canary_id',p_canary,'confirmed',v_confirmed,'divergent',v_divergent);
end $function$
;

-- function: ops2_verify_catalog_stock_canary_v2(p_canary uuid)
CREATE OR REPLACE FUNCTION public.ops2_verify_catalog_stock_canary_v2(p_canary uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_confirmed int:=0;
  v_divergent int:=0;
  v_pending int:=0;
begin
  if not exists(select 1 from public.ops2_catalog_sync_canaries where id=p_canary) then
    raise exception 'canary_not_found';
  end if;

  with evidence as (
    select i.canary_id,i.product_id,i.desired_stock,i.error,
           j.status job_status,j.result job_result,
           m.physical_total mirror_stock
    from public.ops2_catalog_sync_canary_items i
    join public.bling_hub_jobs_v2 j on j.id=i.job_id
    left join public.bling_stock_mirror_v2 m on m.product_id=i.product_id
    where i.canary_id=p_canary
  )
  update public.ops2_catalog_sync_canary_items i
  set verified_bling_physical = case
        when e.job_status='synced' and coalesce((e.job_result->>'verified')::boolean,false)
          then nullif(e.job_result->>'stock','')::numeric
        else e.mirror_stock
      end,
      verified_at=now(),
      state=case
        when e.job_status='synced'
         and coalesce((e.job_result->>'verified')::boolean,false)
         and nullif(e.job_result->>'stock','')::numeric is not distinct from e.desired_stock
          then 'confirmed'
        when e.mirror_stock is not distinct from e.desired_stock
          then 'confirmed'
        when e.job_status in ('pending','processing','retry') then 'queued'
        else 'divergent'
      end,
      error=case
        when e.job_status='synced'
         and coalesce((e.job_result->>'verified')::boolean,false)
         and nullif(e.job_result->>'stock','')::numeric is not distinct from e.desired_stock
          then null
        else e.error
      end
  from evidence e
  where i.canary_id=e.canary_id and i.product_id=e.product_id;

  select count(*) filter(where state='confirmed'),
         count(*) filter(where state='divergent'),
         count(*) filter(where state not in ('confirmed','divergent'))
  into v_confirmed,v_divergent,v_pending
  from public.ops2_catalog_sync_canary_items where canary_id=p_canary;

  if v_divergent=0 and v_pending=0 and v_confirmed>0 then
    update public.ops2_catalog_sync_plan_items p
       set state='confirmed',current_bling_physical=i.desired_stock,updated_at=now()
      from public.ops2_catalog_sync_canary_items i
     where i.canary_id=p_canary and i.product_id=p.product_id and p.run_id=i.run_id and i.state='confirmed';

    update public.ops2_catalog_sync_canaries
       set status='verified',external_write_enabled=false
     where id=p_canary;
  elsif v_divergent>0 then
    update public.ops2_catalog_sync_canaries
       set status='divergent',external_write_enabled=false
     where id=p_canary;
  end if;

  return jsonb_build_object('canary_id',p_canary,'confirmed',v_confirmed,'divergent',v_divergent,'pending',v_pending,'evidence','job_read_after_write_or_mirror');
end $function$
;

-- function: ops2_whatsapp_canonical_template_body_v1(p_message_id uuid, p_whatsapp_account_id uuid, p_metadata jsonb)
CREATE OR REPLACE FUNCTION public.ops2_whatsapp_canonical_template_body_v1(p_message_id uuid, p_whatsapp_account_id uuid, p_metadata jsonb)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_source text:=coalesce(p_metadata->>'source','');
  v_template_name text:=nullif(p_metadata->>'template_name','');
  v_components jsonb:='[]'::jsonb;
  v_values jsonb:='{}'::jsonb;
  v_body text;
  v_ref text;
begin
  if v_source='order_confirmation' then
    v_ref:=p_metadata->>'order_outbox_id';
    if coalesce(v_ref,'') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      select coalesce(q.payload#>>'{meta_request,template_name}',v_template_name),
             q.payload#>'{meta_request,components}'
      into v_template_name,v_components
      from public.ops2_whatsapp_outbox_v1 q
      where q.id=v_ref::uuid and q.whatsapp_account_id=p_whatsapp_account_id;
    end if;
  elsif v_source='order_separation_notification' then
    v_ref:=p_metadata->>'notification_id';
    if coalesce(v_ref,'') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      select coalesce(q.template_name,v_template_name),q.payload->'components'
      into v_template_name,v_components
      from public.order_separation_customer_notifications_v1 q
      where q.id=v_ref::uuid and q.whatsapp_account_id=p_whatsapp_account_id;
    end if;
  elsif v_source='marketing_campaign_worker' or v_source='marketing_campaign' then
    select coalesce(o.payload->>'template_name',v_template_name),
           o.payload->'variable_values'
    into v_template_name,v_values
    from public.whatsapp_outbox_v1 o
    where o.message_id=p_message_id
      and o.whatsapp_account_id=p_whatsapp_account_id
      and o.purpose='marketing_campaign'
    limit 1;
  end if;

  v_body:=public.ops2_render_whatsapp_template_body_v1(
    p_whatsapp_account_id,v_template_name,v_components,v_values
  );
  if nullif(btrim(coalesce(v_body,'')),'') is not null then return v_body; end if;
  if nullif(btrim(coalesce(v_template_name,'')),'') is not null then
    return 'Modelo de WhatsApp: '||v_template_name||' (conteúdo não recuperável neste histórico).';
  end if;
  return 'Mensagem automática do WhatsApp (conteúdo não recuperável neste histórico).';
end;
$function$
;

-- function: ops2_whatsapp_capture_template_text_v1()
CREATE OR REPLACE FUNCTION public.ops2_whatsapp_capture_template_text_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.direction='outbound'
     and new.message_type='template'
     and new.provider='meta'
     and new.provider_message_id like 'wamid.%'
     and nullif(btrim(coalesce(new.text_body,'')),'') is null then
    new.text_body:=public.ops2_whatsapp_canonical_template_body_v1(
      new.id,new.whatsapp_account_id,coalesce(new.metadata,'{}'::jsonb)
    );
  end if;
  return new;
end;
$function$
;

-- function: ops3_add_items_to_existing_order_v1(p_token_hash text, p_request_key text, p_items jsonb)
CREATE OR REPLACE FUNCTION public.ops3_add_items_to_existing_order_v1(p_token_hash text, p_request_key text, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_token_hash text:=lower(trim(coalesce(p_token_hash,'')));
  v_request_key text:=trim(coalesce(p_request_key,''));
  v_runtime private.order_addon_runtime_v1%rowtype;
  v_session private.order_addon_sessions_v1%rowtype;
  v_order public.orders%rowtype;
  v_existing_op private.order_addon_operations_v1%rowtype;
  v_product public.products%rowtype;
  v_existing_item public.order_items%rowtype;
  v_line jsonb;
  v_pair record;
  v_product_id uuid;
  v_qty numeric;
  v_aggregate_qty numeric;
  v_demand jsonb:='{}'::jsonb;
  v_normalized_items jsonb:='[]'::jsonb;
  v_distinct_count integer:=0;
  v_fingerprint text;
  v_unit numeric;
  v_added_total numeric(14,2):=0;
  v_added_items jsonb:='[]'::jsonb;
  v_reservation jsonb;
  v_result jsonb;
  v_old_total numeric(14,2);
  v_new_total numeric(14,2);
  v_line_id uuid;
  v_operation_count integer;
begin
  if v_token_hash !~ '^[a-f0-9]{64}$' then return jsonb_build_object('ok',false,'error','invalid_token'); end if;
  if v_request_key !~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,79}$' then return jsonb_build_object('ok',false,'error','invalid_request_key'); end if;
  if p_items is null or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then return jsonb_build_object('ok',false,'error','items_required'); end if;
  if jsonb_array_length(p_items)>40 then return jsonb_build_object('ok',false,'error','too_many_items'); end if;

  for v_line in select value from jsonb_array_elements(p_items)
  loop
    if jsonb_typeof(v_line)<>'object' then return jsonb_build_object('ok',false,'error','item_must_be_object'); end if;
    if exists(select 1 from jsonb_object_keys(v_line) as k(key) where k.key not in ('product_id','quantity')) then
      return jsonb_build_object('ok',false,'error','invalid_item_fields');
    end if;
    begin v_product_id:=(v_line->>'product_id')::uuid;
    exception when others then return jsonb_build_object('ok',false,'error','invalid_product_id'); end;
    begin v_qty:=(v_line->>'quantity')::numeric;
    exception when others then return jsonb_build_object('ok',false,'error','invalid_quantity','product_id',v_product_id); end;
    if v_qty<=0 or v_qty>30 or trunc(v_qty)<>v_qty then return jsonb_build_object('ok',false,'error','invalid_quantity','product_id',v_product_id); end if;
    v_aggregate_qty:=coalesce((v_demand->>v_product_id::text)::numeric,0)+v_qty;
    if v_aggregate_qty>30 then return jsonb_build_object('ok',false,'error','quantity_limit_exceeded','product_id',v_product_id); end if;
    v_demand:=jsonb_set(v_demand,array[v_product_id::text],to_jsonb(v_aggregate_qty),true);
  end loop;

  select count(*) into v_distinct_count from jsonb_object_keys(v_demand);
  select coalesce(jsonb_agg(jsonb_build_object('product_id',e.key,'quantity',e.value::numeric) order by e.key),'[]'::jsonb)
  into v_normalized_items from jsonb_each_text(v_demand) e;

  v_fingerprint:=encode(extensions.digest(convert_to(v_normalized_items::text,'UTF8'),'sha256'),'hex');

  select * into v_session from private.order_addon_sessions_v1 where token_hash=v_token_hash for update;
  if not found then return jsonb_build_object('ok',false,'error','session_not_found'); end if;

  select * into v_existing_op
  from private.order_addon_operations_v1
  where session_id=v_session.id and request_key=v_request_key;

  if found then
    if v_existing_op.payload_fingerprint<>v_fingerprint then return jsonb_build_object('ok',false,'error','idempotency_key_reused'); end if;
    if v_existing_op.status='applied' then return coalesce(v_existing_op.result,'{}'::jsonb)||jsonb_build_object('idempotent_replay',true); end if;
    if v_existing_op.status='rejected' then return coalesce(v_existing_op.result,'{}'::jsonb)||jsonb_build_object('idempotent_replay',true); end if;
    return jsonb_build_object('ok',false,'error','operation_in_progress');
  end if;

  select * into v_runtime from private.order_addon_runtime_v1 where singleton;
  if not found or coalesce(v_runtime.enabled,false) is not true then return jsonb_build_object('ok',false,'error','feature_disabled'); end if;
  if v_distinct_count>v_runtime.max_distinct_products_per_operation then
    return jsonb_build_object('ok',false,'error','too_many_distinct_products','max',v_runtime.max_distinct_products_per_operation);
  end if;

  if v_session.status<>'open' then return jsonb_build_object('ok',false,'error','session_closed'); end if;
  if now()>=v_session.expires_at then return jsonb_build_object('ok',false,'error','session_expired'); end if;
  if v_session.operation_count>=v_session.max_operations then return jsonb_build_object('ok',false,'error','operation_limit_reached'); end if;

  select * into v_order from public.orders where id=v_session.order_id for update;
  if not found then return jsonb_build_object('ok',false,'error','order_not_found'); end if;
  if coalesce(v_order.source,'') not in ('vitrine','storefront_v2') then return jsonb_build_object('ok',false,'error','order_source_not_supported'); end if;
  if coalesce(v_order.status,'')<>'storefront_received' then return jsonb_build_object('ok',false,'error','order_status_closed','status',v_order.status); end if;
  if v_order.confirmed_at is not null then return jsonb_build_object('ok',false,'error','order_already_confirmed'); end if;
  if v_order.bling_order_id is not null or v_order.bling_synced_at is not null or coalesce(v_order.sync_status,'local')<>'local' then
    return jsonb_build_object('ok',false,'error','bling_sync_started');
  end if;
  if exists(select 1 from public.order_separation_assignments_v1 x where x.order_id=v_order.id)
     or exists(select 1 from public.order_separation_items_v1 x where x.order_id=v_order.id)
     or exists(select 1 from public.order_separation_completions_v1 x where x.order_id=v_order.id) then
    return jsonb_build_object('ok',false,'error','separation_started');
  end if;
  if exists(select 1 from public.vitrine_stock_reservations x where x.order_id=v_order.id and x.status='consumed') then
    return jsonb_build_object('ok',false,'error','stock_already_consumed');
  end if;

  for v_pair in select key,value from jsonb_each_text(v_demand) order by key
  loop
    v_product_id:=v_pair.key::uuid;
    select * into v_product from public.products where id=v_product_id and is_active=true for update;
    if not found or coalesce(v_product.is_offer,false) is not true
      or v_product.offer_price is null or v_product.offer_price<0
      or v_product.price is null or v_product.price<0 then
      return jsonb_build_object('ok',false,'error','offer_unavailable','product_id',v_product_id);
    end if;
    v_unit:=round(case when coalesce(v_product.is_offer,false) and v_product.offer_price is not null and v_product.offer_price>=0
                        then v_product.offer_price else v_product.price end,2);
    if v_unit<0 then return jsonb_build_object('ok',false,'error','product_unavailable','product_id',v_product_id); end if;
  end loop;

  insert into private.order_addon_operations_v1(session_id,order_id,request_key,payload_fingerprint,status,result)
  values(v_session.id,v_order.id,v_request_key,v_fingerprint,'pending','{}'::jsonb);

  v_old_total:=round(coalesce(v_order.total,0),2);

  for v_pair in select key,value from jsonb_each_text(v_demand) order by key
  loop
    v_product_id:=v_pair.key::uuid;
    v_qty:=v_pair.value::numeric;
    select * into v_product from public.products where id=v_product_id and is_active=true;
    if not found or coalesce(v_product.is_offer,false) is not true or v_product.offer_price is null or v_product.offer_price<0
      then raise exception 'offer_changed_during_addon' using errcode='P0001'; end if;
    v_unit:=round(case when coalesce(v_product.is_offer,false) and v_product.offer_price is not null and v_product.offer_price>=0
                        then v_product.offer_price else v_product.price end,2);

    select * into v_existing_item
    from public.order_items
    where order_id=v_order.id
      and product_id=v_product_id
      and coalesce(metadata->>'history_kind','product')='product'
      and coalesce(metadata->>'basket_id','')=''
      and unit_price=v_unit
    order by case when metadata->>'source'='order_addon' then 0 else 1 end,created_at,id
    limit 1 for update;

    if found then
      v_line_id:=v_existing_item.id;
      update public.order_items
      set quantity=quantity+v_qty,
          line_total=round(unit_price*(quantity+v_qty),2),
          metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object(
            'addon_last_session_id',v_session.id,'addon_last_request_key',v_request_key,'addon_last_at',now()
          ),
          updated_at=now()
      where id=v_line_id;
    else
      insert into public.order_items(order_id,product_id,sku_snapshot,name_snapshot,quantity,unit_price,line_total,metadata)
      values(
        v_order.id,v_product.id,v_product.sku,v_product.name,v_qty,v_unit,round(v_unit*v_qty,2),
        jsonb_build_object(
          'source','order_addon','history_kind','product','image_url',coalesce(v_product.image_url,''),
          'addon_session_id',v_session.id,'addon_request_key',v_request_key,'addon_added_at',now()
        )
      ) returning id into v_line_id;
    end if;

    v_added_total:=round(v_added_total+round(v_unit*v_qty,2),2);
    v_added_items:=v_added_items||jsonb_build_array(jsonb_build_object(
      'order_item_id',v_line_id,'product_id',v_product.id,'name',v_product.name,
      'quantity_added',v_qty,'unit_price',v_unit,'line_total_added',round(v_unit*v_qty,2)
    ));
  end loop;

  update public.orders
  set total=round(coalesce(total,0)+v_added_total,2),
      subtotal=round(coalesce(subtotal,total,0)+v_added_total,2),
      fiscal_subtotal=round(coalesce(fiscal_subtotal,subtotal,total,0)+v_added_total,2),
      checkout_snapshot=jsonb_set(
        coalesce(checkout_snapshot,'{}'::jsonb),'{order_addon}',
        coalesce(checkout_snapshot->'order_addon','{}'::jsonb)||jsonb_build_object(
          'last_at',now(),'last_request_key',v_request_key,'last_added_total',v_added_total
        ),true
      ),
      updated_at=now()
  where id=v_order.id
  returning total into v_new_total;

  v_reservation:=public.reserve_vitrine_order_stock_v1(v_order.id);
  if coalesce((v_reservation->>'ok')::boolean,false) is not true then
    raise exception 'stock_reservation_failed:%',coalesce(v_reservation->>'error','unknown') using errcode='P0001';
  end if;

  perform public.ops2_refresh_order_public_snapshot_v1(v_order.id);

  update private.order_addon_sessions_v1
  set operation_count=operation_count+1,updated_at=now()
  where id=v_session.id
  returning operation_count into v_operation_count;

  v_result:=jsonb_build_object(
    'ok',true,'order_id',v_order.id,'order_number',v_order.order_number,'previous_total',v_old_total,
    'added_total',v_added_total,'total',v_new_total,'added_items',v_added_items,
    'operation_count',v_operation_count,'max_operations',v_session.max_operations,
    'expires_at',v_session.expires_at,'reservation_status',coalesce(v_reservation->>'status','reserved'),
    'idempotent_replay',false
  );

  update private.order_addon_operations_v1
  set status='applied',result=v_result,completed_at=now()
  where session_id=v_session.id and request_key=v_request_key;

  begin
    perform public.ops_record_event_v1(
      'order','order.addon_items_added','Itens acrescentados ao pedido existente.','customer',
      'order',v_order.id::text,v_order.id::text,null,null,'dona_antonia','info',
      jsonb_build_object(
        'session_id',v_session.id,'request_key',v_request_key,'distinct_products',v_distinct_count,
        'added_total',v_added_total,'new_total',v_new_total
      ),
      null,'order-addon:'||v_session.id::text||':'||v_request_key,now()
    );
  exception when others then null;
  end;

  return v_result;
end;
$function$
;

-- function: ops3_complete_delivery_v1(p_order_id uuid, p_method text, p_amount_cents bigint, p_operator_label text, p_idempotency_key text)
CREATE OR REPLACE FUNCTION public.ops3_complete_delivery_v1(p_order_id uuid, p_method text, p_amount_cents bigint, p_operator_label text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_order public.orders%rowtype;
  v_completion public.order_separation_completions_v1%rowtype;
  v_control public.order_fiscal_controls%rowtype;
  v_existing public.order_payment_settlements%rowtype;
  v_existing_method text;
  v_existing_amount bigint;
  v_expected bigint;
  v_method text:=lower(trim(coalesce(p_method,'')));
  v_key text;
  v_settlement_id uuid;
  v_now timestamptz:=now();
begin
  if p_order_id is null then raise exception 'invalid_order'; end if;
  if v_method not in ('pix','cash','credit_card','food_card','meal_card','other') then raise exception 'invalid_payment_method'; end if;

  select * into v_order from public.orders where id=p_order_id for update;
  if not found then raise exception 'order_not_found'; end if;

  v_expected:=round(coalesce(v_order.total,0)*100)::bigint;
  if v_expected<=0 then raise exception 'invalid_order_total'; end if;
  if p_amount_cents is null or p_amount_cents<>v_expected then raise exception 'payment_total_mismatch'; end if;

  select * into v_completion from public.order_separation_completions_v1 where order_id=p_order_id;
  select * into v_control from public.order_fiscal_controls where order_id=p_order_id;

  if v_order.status<>'delivered' then
    if v_order.status<>'out_for_delivery' then raise exception 'order_not_out_for_delivery'; end if;
    if v_completion.id is null or v_completion.completed_at is null then raise exception 'separation_not_completed'; end if;
    if v_control.order_id is null or v_control.dispatch_fiscal_status not in ('authorized','not_required') then raise exception 'fiscal_authorization_required_before_delivery'; end if;
    if v_control.dispatch_started_at is null then raise exception 'dispatch_not_started'; end if;
  end if;

  select * into v_existing from public.order_payment_settlements where order_id=p_order_id;
  if found then
    select method,amount_cents into v_existing_method,v_existing_amount
      from public.order_payment_parts where settlement_id=v_existing.id order by sequence limit 1;
    if v_existing.status not in ('captured','synced','needs_review')
       or v_existing.expected_total_cents<>v_expected
       or v_existing.captured_total_cents<>v_expected
       or v_existing_method is distinct from v_method
       or v_existing_amount is distinct from v_expected
       or (select count(*) from public.order_payment_parts where settlement_id=v_existing.id)<>1 then
      raise exception 'payment_already_captured';
    end if;
    v_settlement_id:=v_existing.id;
  else
    if v_order.status='delivered' then raise exception 'delivered_order_without_settlement'; end if;
    v_key:=coalesce(nullif(trim(coalesce(p_idempotency_key,'')),''),'delivery-v4:'||p_order_id::text);
    insert into public.order_payment_settlements(
      order_id,status,expected_total_cents,captured_total_cents,planned_method,
      operator_label,source,bling_sync_state,idempotency_key,metadata,captured_at
    ) values(
      p_order_id,'captured',v_expected,v_expected,v_order.payment_method,
      left(nullif(trim(coalesce(p_operator_label,'')),''),80),'delivery','blocked_homologation',v_key,
      jsonb_build_object('captured_order_status',v_order.status,'flow','orders_v4'),v_now
    ) returning id into v_settlement_id;
    insert into public.order_payment_parts(settlement_id,sequence,method,amount_cents,detail)
    values(v_settlement_id,1,v_method,v_expected,'{}'::jsonb);
  end if;

  if v_order.status<>'delivered' then
    update public.orders set status='delivered',delivered_at=coalesce(delivered_at,v_now),updated_at=v_now where id=p_order_id;
    update public.order_fiscal_controls
       set delivery_status='delivered',delivery_confirmed_at=coalesce(delivery_confirmed_at,v_now),updated_at=v_now
     where order_id=p_order_id;
  end if;

  perform public.ops2_refresh_order_public_snapshot_v1(p_order_id);
  begin
    perform public.ops_record_event_v1(
      'order','order.delivered','Entrega e pagamento confirmados.','human','order',p_order_id::text,p_order_id::text,
      null,left(nullif(trim(coalesce(p_operator_label,'')),''),80),'dona_antonia','info',
      jsonb_build_object('settlement_id',v_settlement_id,'payment_method',v_method,'amount_cents',v_expected,'flow','orders_v4'),
      null,'order-delivered-v4:'||p_order_id::text,now()
    );
  exception when others then null;
  end;

  return jsonb_build_object(
    'ok',true,'order_id',p_order_id,'status','delivered','delivered_at',coalesce(v_order.delivered_at,v_now),
    'settlement_id',v_settlement_id,'payment_method',v_method,'amount_cents',v_expected,
    'already_delivered',v_order.status='delivered'
  );
end;
$function$
;

-- function: ops3_confirm_customer_order_v1(p_token_hash text, p_expected_total numeric, p_expected_updated_at timestamp with time zone)
CREATE OR REPLACE FUNCTION public.ops3_confirm_customer_order_v1(p_token_hash text, p_expected_total numeric, p_expected_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a private.order_customer_actions_v1%rowtype; o public.orders%rowtype;
  d jsonb; stock jsonb; problems text[]:=array[]::text[];
begin
  if p_token_hash !~ '^[a-f0-9]{64}$' or p_expected_total is null or p_expected_updated_at is null
    then return jsonb_build_object('ok',false,'error','invalid_request'); end if;
  select * into a from private.order_customer_actions_v1 where token_hash=p_token_hash for update;
  if not found then return jsonb_build_object('ok',false,'error','invalid_token'); end if;
  select * into o from public.orders where id=a.order_id for update;
  if not found then return jsonb_build_object('ok',false,'error','order_not_found'); end if;
  if a.confirmed_at is not null and o.status='confirmed' then
    return jsonb_build_object('ok',true,'already_confirmed',true,'order_id',o.id,'status','confirmed','total',o.total);
  end if;
  if now()>a.expires_at then return jsonb_build_object('ok',false,'error','session_expired'); end if;
  if o.source not in ('vitrine','storefront_v2') or o.status<>'storefront_received' or o.confirmed_at is not null
     or o.cancelled_at is not null then return jsonb_build_object('ok',false,'error','order_status_closed','status',o.status); end if;
  if o.bling_order_id is not null or o.bling_synced_at is not null or coalesce(o.sync_status,'local')<>'local'
     then return jsonb_build_object('ok',false,'error','bling_sync_started'); end if;
  if exists(select 1 from public.order_separation_assignments_v1 x where x.order_id=o.id)
     or exists(select 1 from public.order_separation_items_v1 x where x.order_id=o.id)
     then return jsonb_build_object('ok',false,'error','separation_started'); end if;
  if o.updated_at<>p_expected_updated_at or round(o.total,2)<>round(p_expected_total,2) then
    return jsonb_build_object('ok',false,'error','order_changed','current_total',o.total,'updated_at',o.updated_at);
  end if;
  d:=coalesce(o.delivery_address,'{}'::jsonb);
  if nullif(btrim(coalesce(d->>'customer_name',d->>'recipient_name','')),'') is null then problems:=array_append(problems,'customer_required'); end if;
  if nullif(btrim(coalesce(d->>'street','')),'') is null then problems:=array_append(problems,'delivery_street_required'); end if;
  if nullif(btrim(coalesce(d->>'number','')),'') is null then problems:=array_append(problems,'delivery_number_required'); end if;
  if nullif(btrim(coalesce(d->>'city','')),'') is null then problems:=array_append(problems,'delivery_city_required'); end if;
  if nullif(btrim(coalesce(d->>'state','')),'') is null then problems:=array_append(problems,'delivery_state_required'); end if;
  if nullif(btrim(coalesce(o.payment_method,'')),'') is null then problems:=array_append(problems,'payment_method_required'); end if;
  if array_length(problems,1)>0 then return jsonb_build_object('ok',false,'error','order_operational_data_incomplete','blockers',to_jsonb(problems)); end if;
  stock:=public.reserve_vitrine_order_stock_v1(o.id);
  if coalesce((stock->>'ok')::boolean,false) is not true then
    raise exception 'customer_confirm_stock_unavailable:%',coalesce(stock->>'error','unknown') using errcode='P0001';
  end if;
  update public.orders
     set status='confirmed',
         confirmed_at=now(),
         checkout_snapshot=jsonb_set(coalesce(o.checkout_snapshot,'{}'::jsonb),
                                     '{customer_confirmed}','true'::jsonb,true),
         updated_at=now()
   where id=o.id;
  update private.order_customer_actions_v1 set confirmed_at=now(),confirmed_total=o.total where order_id=o.id;
  perform public.ops2_refresh_order_public_snapshot_v1(o.id);
  return jsonb_build_object('ok',true,'order_id',o.id,'status','confirmed','total',o.total,'confirmed_at',now());
end;$function$
;

-- function: ops3_create_order_addon_session_v1(p_order_id uuid, p_token_hash text, p_source text, p_metadata jsonb)
CREATE OR REPLACE FUNCTION public.ops3_create_order_addon_session_v1(p_order_id uuid, p_token_hash text, p_source text DEFAULT 'post_checkout'::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_runtime private.order_addon_runtime_v1%rowtype;
  v_order public.orders%rowtype;
  v_session private.order_addon_sessions_v1%rowtype;
  v_token_hash text:=lower(trim(coalesce(p_token_hash,'')));
  v_source text:=lower(trim(coalesce(p_source,'post_checkout')));
  v_expires_at timestamptz;
begin
  if p_order_id is null then return jsonb_build_object('ok',false,'error','invalid_order_id'); end if;
  if v_token_hash !~ '^[a-f0-9]{64}$' then return jsonb_build_object('ok',false,'error','invalid_token_hash'); end if;
  if v_source !~ '^[a-z0-9][a-z0-9_-]{0,39}$' then return jsonb_build_object('ok',false,'error','invalid_source'); end if;
  if p_metadata is null or jsonb_typeof(p_metadata)<>'object' then return jsonb_build_object('ok',false,'error','invalid_metadata'); end if;

  select * into v_runtime from private.order_addon_runtime_v1 where singleton for update;
  if not found or coalesce(v_runtime.enabled,false) is not true then return jsonb_build_object('ok',false,'error','feature_disabled'); end if;

  select * into v_order from public.orders where id=p_order_id for update;
  if not found then return jsonb_build_object('ok',false,'error','order_not_found'); end if;
  if coalesce(v_order.source,'') not in ('vitrine','storefront_v2') then return jsonb_build_object('ok',false,'error','order_source_not_supported'); end if;
  if coalesce(v_order.status,'') <> 'storefront_received' then return jsonb_build_object('ok',false,'error','order_status_closed','status',v_order.status); end if;
  if v_order.confirmed_at is not null then return jsonb_build_object('ok',false,'error','order_already_confirmed'); end if;
  if v_order.bling_order_id is not null or v_order.bling_synced_at is not null or coalesce(v_order.sync_status,'local') <> 'local' then
    return jsonb_build_object('ok',false,'error','bling_sync_started');
  end if;
  if exists(select 1 from public.order_separation_assignments_v1 x where x.order_id=p_order_id)
     or exists(select 1 from public.order_separation_items_v1 x where x.order_id=p_order_id)
     or exists(select 1 from public.order_separation_completions_v1 x where x.order_id=p_order_id) then
    return jsonb_build_object('ok',false,'error','separation_started');
  end if;

  v_expires_at:=v_order.created_at + make_interval(mins=>v_runtime.window_minutes);
  if now() >= v_expires_at then return jsonb_build_object('ok',false,'error','addon_window_expired','expires_at',v_expires_at); end if;

  update private.order_addon_sessions_v1
  set status='closed',closed_at=coalesce(closed_at,now()),close_reason=coalesce(close_reason,'superseded'),updated_at=now()
  where order_id=p_order_id and status='open';

  insert into private.order_addon_sessions_v1(order_id,token_hash,status,source,expires_at,max_operations,metadata)
  values(p_order_id,v_token_hash,'open',v_source,v_expires_at,v_runtime.max_operations,p_metadata)
  returning * into v_session;

  return jsonb_build_object(
    'ok',true,'session_id',v_session.id,'order_id',v_order.id,'order_number',v_order.order_number,
    'expires_at',v_session.expires_at,'max_operations',v_session.max_operations
  );
end;
$function$
;

-- function: ops3_enqueue_confirmed_storefront_v1()
CREATE OR REPLACE FUNCTION public.ops3_enqueue_confirmed_storefront_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.source not in ('vitrine','storefront_v2')
    or new.status <> 'confirmed'
    or old.status = 'confirmed'
    or old.status not in ('storefront_received','received') then
    return new;
  end if;

  -- Do not start picking. Only add the fully confirmed order to the queue.
  -- No service or synthetic UUID is impersonated as an Admin employee.
  insert into public.order_manual_separation_queue_v1(
    order_id,selected_by,selected_source
  ) values (
    new.id,null,
    case when coalesce((new.checkout_snapshot->>'customer_confirmed'), '')='true'
      then 'customer_confirmed' else 'admin_confirmed' end
  )
  on conflict (order_id) do nothing;

  return new;
end;
$function$
;

-- function: ops3_get_customer_order_action_v1(p_token_hash text)
CREATE OR REPLACE FUNCTION public.ops3_get_customer_order_action_v1(p_token_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a private.order_customer_actions_v1%rowtype; o public.orders%rowtype; v_public text; v_code text;
begin
  if p_token_hash !~ '^[a-f0-9]{64}$' then return jsonb_build_object('ok',false,'error','invalid_token'); end if;
  select * into a from private.order_customer_actions_v1 where token_hash=p_token_hash;
  if not found then return jsonb_build_object('ok',false,'error','not_found'); end if;
  select * into o from public.orders where id=a.order_id;
  if not found then return jsonb_build_object('ok',false,'error','not_found'); end if;
  select public_token,public_code into v_public,v_code from public.order_public_snapshots_v1 where order_id=o.id;
  if v_public is null then return jsonb_build_object('ok',false,'error','snapshot_missing'); end if;
  return jsonb_build_object('ok',true,'order_id',o.id,'public_token',v_public,'public_code',v_code,
    'status',o.status,'total',o.total,'updated_at',o.updated_at,
    'confirmed',o.status='confirmed' and o.confirmed_at is not null,
    'can_confirm',a.expires_at>now() and a.confirmed_at is null and o.status='storefront_received' and o.confirmed_at is null,
    'expires_at',a.expires_at);
end;$function$
;

-- function: ops3_get_order_addon_session_v1(p_token_hash text)
CREATE OR REPLACE FUNCTION public.ops3_get_order_addon_session_v1(p_token_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_runtime private.order_addon_runtime_v1%rowtype;
  v_session private.order_addon_sessions_v1%rowtype;
  v_order public.orders%rowtype;
  v_token_hash text:=lower(trim(coalesce(p_token_hash,'')));
begin
  if v_token_hash !~ '^[a-f0-9]{64}$' then return jsonb_build_object('ok',false,'eligible',false,'reason','invalid_token'); end if;
  select * into v_runtime from private.order_addon_runtime_v1 where singleton;
  if not found or coalesce(v_runtime.enabled,false) is not true then return jsonb_build_object('ok',true,'eligible',false,'reason','feature_disabled'); end if;
  select * into v_session from private.order_addon_sessions_v1 where token_hash=v_token_hash;
  if not found then return jsonb_build_object('ok',false,'eligible',false,'reason','session_not_found'); end if;
  if v_session.status<>'open' then return jsonb_build_object('ok',true,'eligible',false,'reason','session_closed'); end if;
  if now()>=v_session.expires_at then return jsonb_build_object('ok',true,'eligible',false,'reason','session_expired','expires_at',v_session.expires_at); end if;
  if v_session.operation_count>=v_session.max_operations then return jsonb_build_object('ok',true,'eligible',false,'reason','operation_limit_reached'); end if;

  select * into v_order from public.orders where id=v_session.order_id;
  if not found then return jsonb_build_object('ok',false,'eligible',false,'reason','order_not_found'); end if;
  if coalesce(v_order.status,'')<>'storefront_received' or v_order.confirmed_at is not null then
    return jsonb_build_object('ok',true,'eligible',false,'reason','order_status_closed','status',v_order.status);
  end if;
  if v_order.bling_order_id is not null or v_order.bling_synced_at is not null or coalesce(v_order.sync_status,'local')<>'local' then
    return jsonb_build_object('ok',true,'eligible',false,'reason','bling_sync_started');
  end if;
  if exists(select 1 from public.order_separation_assignments_v1 x where x.order_id=v_order.id)
     or exists(select 1 from public.order_separation_items_v1 x where x.order_id=v_order.id)
     or exists(select 1 from public.order_separation_completions_v1 x where x.order_id=v_order.id) then
    return jsonb_build_object('ok',true,'eligible',false,'reason','separation_started');
  end if;
  return jsonb_build_object(
    'ok',true,'eligible',true,'reason','eligible','session_id',v_session.id,
    'order_id',v_order.id,'order_number',v_order.order_number,'expires_at',v_session.expires_at,
    'operation_count',v_session.operation_count,'max_operations',v_session.max_operations,'current_total',v_order.total
  );
end;
$function$
;

-- function: ops3_issue_customer_order_action_v1(p_order_id uuid, p_token_hash text)
CREATE OR REPLACE FUNCTION public.ops3_issue_customer_order_action_v1(p_order_id uuid, p_token_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o public.orders%rowtype;
begin
  if p_token_hash !~ '^[a-f0-9]{64}$' then return jsonb_build_object('ok',false,'error','invalid_token_hash'); end if;
  select * into o from public.orders where id=p_order_id for update;
  if not found then return jsonb_build_object('ok',false,'error','order_not_found'); end if;
  if o.source not in ('vitrine','storefront_v2') or o.status<>'storefront_received' or o.confirmed_at is not null
     or o.cancelled_at is not null then return jsonb_build_object('ok',false,'error','order_not_eligible'); end if;
  insert into private.order_customer_actions_v1(order_id,token_hash,expires_at)
  values(o.id,p_token_hash,now()+interval '7 days')
  on conflict(order_id) do update set token_hash=excluded.token_hash,issued_at=now(),expires_at=excluded.expires_at,
    confirmed_at=null,confirmed_total=null;
  return jsonb_build_object('ok',true,'order_id',o.id);
end;$function$
;

-- function: ops3_mark_delivery_prepaid_v1(p_order_id uuid, p_method text, p_reference text, p_operator_label text)
CREATE OR REPLACE FUNCTION public.ops3_mark_delivery_prepaid_v1(p_order_id uuid, p_method text, p_reference text DEFAULT NULL::text, p_operator_label text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_order public.orders%rowtype;
  v_settlement public.order_payment_settlements%rowtype;
  v_method text := lower(trim(coalesce(p_method, '')));
  v_expected bigint;
  v_existing_method text;
  v_existing_amount bigint;
  v_now timestamptz := now();
  v_settlement_id uuid;
begin
  if p_order_id is null then raise exception 'invalid_order'; end if;
  if v_method not in ('pix', 'credit_card') then raise exception 'invalid_prepaid_method'; end if;
  select * into v_order from public.orders where id = p_order_id for update;
  if not found then raise exception 'order_not_found'; end if;
  if v_order.status not in ('ready', 'out_for_delivery') then raise exception 'order_not_ready_for_prepaid'; end if;
  v_expected := round(coalesce(v_order.total, 0) * 100)::bigint;
  if v_expected <= 0 then raise exception 'invalid_order_total'; end if;

  select * into v_settlement from public.order_payment_settlements where order_id = p_order_id for update;
  if found then
    select method, amount_cents into v_existing_method, v_existing_amount
      from public.order_payment_parts where settlement_id = v_settlement.id order by sequence limit 1;
    if v_settlement.status not in ('captured', 'synced')
       or v_settlement.expected_total_cents <> v_expected
       or v_settlement.captured_total_cents <> v_expected
       or v_existing_method is distinct from v_method
       or v_existing_amount is distinct from v_expected
       or (select count(*) from public.order_payment_parts where settlement_id = v_settlement.id) <> 1 then
      raise exception 'prepaid_settlement_mismatch';
    end if;
    v_settlement_id := v_settlement.id;
    update public.order_payment_settlements
       set metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
         'prepaid_verified', true, 'prepaid_verified_at', v_now,
         'prepaid_reference', nullif(left(trim(coalesce(p_reference, '')), 120), ''),
         'prepaid_operator', nullif(left(trim(coalesce(p_operator_label, '')), 80), '')
       ), updated_at = v_now
     where id = v_settlement.id;
  else
    insert into public.order_payment_settlements(
      order_id, status, expected_total_cents, captured_total_cents, planned_method,
      operator_label, source, bling_sync_state, idempotency_key, metadata, captured_at
    ) values (
      p_order_id, 'captured', v_expected, v_expected, v_method,
      nullif(left(trim(coalesce(p_operator_label, '')), 80), ''), 'admin_prepaid_verification',
      'blocked_homologation', 'prepaid-verify:' || p_order_id::text,
      jsonb_build_object('prepaid_verified', true, 'prepaid_verified_at', v_now,
        'prepaid_reference', nullif(left(trim(coalesce(p_reference, '')), 120), ''),
        'prepaid_operator', nullif(left(trim(coalesce(p_operator_label, '')), 80), '')),
      v_now
    ) returning id into v_settlement_id;
    insert into public.order_payment_parts(settlement_id, sequence, method, amount_cents, detail)
    values(v_settlement_id, 1, v_method, v_expected,
      jsonb_build_object('source', 'admin_prepaid_verification'));
  end if;

  update public.orders
     set delivery_paid_ahead = true,
         delivery_paid_ahead_method = v_method,
         delivery_paid_ahead_reference = nullif(left(trim(coalesce(p_reference, '')), 120), ''),
         delivery_paid_ahead_at = coalesce(delivery_paid_ahead_at, v_now),
         delivery_paid_ahead_by = coalesce(nullif(left(trim(coalesce(p_operator_label, '')), 80), ''), delivery_paid_ahead_by),
         payment_method = v_method,
         updated_at = v_now
   where id = p_order_id;

  insert into public.admin_audit_logs(admin_user_id, action, entity_type, entity_id, details)
  values(null, 'order.delivery_marked_prepaid', 'order', p_order_id::text,
    jsonb_build_object('method', v_method, 'reference', nullif(left(trim(coalesce(p_reference, '')), 120), ''),
      'settlement_id', v_settlement_id, 'operator', nullif(left(trim(coalesce(p_operator_label, '')), 80), '')));

  perform public.ops2_refresh_order_public_snapshot_v1(p_order_id);
  return jsonb_build_object('ok', true, 'order_id', p_order_id, 'method', v_method,
    'settlement_id', v_settlement_id, 'amount_cents', v_expected, 'delivery_paid_ahead', true);
end;
$function$
;

-- function: ops3_order_addon_eligibility_v1(p_order_id uuid)
CREATE OR REPLACE FUNCTION public.ops3_order_addon_eligibility_v1(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_runtime private.order_addon_runtime_v1%rowtype;
  v_order public.orders%rowtype;
  v_expires_at timestamptz;
begin
  if p_order_id is null then
    return jsonb_build_object('ok',false,'eligible',false,'reason','invalid_order_id');
  end if;
  select * into v_runtime from private.order_addon_runtime_v1 where singleton;
  if not found or coalesce(v_runtime.enabled,false) is not true then
    return jsonb_build_object('ok',true,'eligible',false,'reason','feature_disabled');
  end if;
  select * into v_order from public.orders where id=p_order_id;
  if not found then return jsonb_build_object('ok',false,'eligible',false,'reason','order_not_found'); end if;
  if coalesce(v_order.source,'') not in ('vitrine','storefront_v2') then
    return jsonb_build_object('ok',true,'eligible',false,'reason','order_source_not_supported');
  end if;
  if coalesce(v_order.status,'') <> 'storefront_received' then
    return jsonb_build_object('ok',true,'eligible',false,'reason','order_status_closed','status',v_order.status);
  end if;
  if v_order.confirmed_at is not null then
    return jsonb_build_object('ok',true,'eligible',false,'reason','order_already_confirmed');
  end if;
  if v_order.bling_order_id is not null or v_order.bling_synced_at is not null or coalesce(v_order.sync_status,'local') <> 'local' then
    return jsonb_build_object('ok',true,'eligible',false,'reason','bling_sync_started');
  end if;
  if exists(select 1 from public.order_separation_assignments_v1 x where x.order_id=p_order_id)
     or exists(select 1 from public.order_separation_items_v1 x where x.order_id=p_order_id)
     or exists(select 1 from public.order_separation_completions_v1 x where x.order_id=p_order_id) then
    return jsonb_build_object('ok',true,'eligible',false,'reason','separation_started');
  end if;
  v_expires_at:=v_order.created_at + make_interval(mins=>v_runtime.window_minutes);
  if now() >= v_expires_at then
    return jsonb_build_object('ok',true,'eligible',false,'reason','addon_window_expired','expires_at',v_expires_at);
  end if;
  return jsonb_build_object(
    'ok',true,'eligible',true,'reason','eligible',
    'order_id',v_order.id,'order_number',v_order.order_number,'expires_at',v_expires_at,
    'window_minutes',v_runtime.window_minutes,'max_operations',v_runtime.max_operations,
    'max_distinct_products_per_operation',v_runtime.max_distinct_products_per_operation
  );
end;
$function$
;

-- function: ops3_reopen_order_v1(p_order_id uuid, p_operator_label text)
CREATE OR REPLACE FUNCTION public.ops3_reopen_order_v1(p_order_id uuid, p_operator_label text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_order public.orders%rowtype;
  v_release jsonb;
  v_started integer:=0;
begin
  select * into v_order from public.orders where id=p_order_id for update;
  if not found then raise exception 'order_not_found'; end if;
  if v_order.status<>'confirmed' then raise exception 'order_not_confirmed'; end if;
  if exists(select 1 from public.order_separation_completions_v1 where order_id=p_order_id) then raise exception 'separation_already_started'; end if;
  select count(*) into v_started from public.order_separation_items_v1 where order_id=p_order_id and state<>'pending';
  if v_started>0 then raise exception 'separation_already_started'; end if;
  v_release:=public.release_vitrine_order_stock_v1(p_order_id);
  if coalesce((v_release->>'ok')::boolean,false) is not true then raise exception 'stock_release_failed'; end if;
  delete from public.order_separation_items_v1 where order_id=p_order_id and state='pending';
  delete from public.order_separation_assignments_v1 where order_id=p_order_id;
  update public.orders set status='storefront_received',confirmed_at=null,updated_at=now() where id=p_order_id;
  perform public.ops2_refresh_order_public_snapshot_v1(p_order_id);
  return jsonb_build_object('ok',true,'order_id',p_order_id,'status','storefront_received','stock_release',v_release);
end;
$function$
;

-- function: ops3_site_admin_customer_address_manage_v1(p_action text, p_customer_id uuid, p_address_id uuid, p_expected_updated_at timestamp with time zone, p_label text, p_address jsonb)
CREATE OR REPLACE FUNCTION public.ops3_site_admin_customer_address_manage_v1(p_action text, p_customer_id uuid, p_address_id uuid DEFAULT NULL::uuid, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_label text DEFAULT NULL::text, p_address jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_action text := lower(btrim(coalesce(p_action, '')));
  v_label text := left(btrim(regexp_replace(coalesce(p_label, ''), '\s+', ' ', 'g')), 60);
  v_street text := left(btrim(regexp_replace(coalesce(p_address->>'street', ''), '\s+', ' ', 'g')), 180);
  v_number text := left(btrim(regexp_replace(coalesce(p_address->>'number', ''), '\s+', ' ', 'g')), 40);
  v_complement text := nullif(left(btrim(regexp_replace(coalesce(p_address->>'complement', ''), '\s+', ' ', 'g')), 180), '');
  v_neighborhood text := left(btrim(regexp_replace(coalesce(p_address->>'neighborhood', ''), '\s+', ' ', 'g')), 120);
  v_city_input text := left(btrim(regexp_replace(coalesce(p_address->>'city', ''), '\s+', ' ', 'g')), 100);
  v_city_key text;
  v_city text;
  v_state text := upper(left(btrim(coalesce(p_address->>'state', 'MT')), 2));
  v_postal_code text := nullif(left(regexp_replace(coalesce(p_address->>'postal_code', ''), '[^0-9]', '', 'g'), 8), '');
  v_reference text := nullif(left(btrim(regexp_replace(coalesce(p_address->>'reference', ''), '\s+', ' ', 'g')), 220), '');
  v_id uuid;
  v_was_default boolean := false;
  v_replacement uuid;
  v_customer_found boolean := false;
  v_row public.customer_addresses%rowtype;
begin
  if p_customer_id is null then
    return jsonb_build_object('ok', false, 'error', 'invalid_customer_id');
  end if;

  perform 1 from public.customers c
   where c.id = p_customer_id and c.is_active = true
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'customer_not_found');
  end if;

  if v_action in ('create', 'update') then
    if length(v_label) < 1 then
      return jsonb_build_object('ok', false, 'error', 'address_label_required');
    end if;
    if v_street = '' or v_number = '' or v_neighborhood = '' or v_city_input = '' or length(v_state) <> 2 then
      return jsonb_build_object('ok', false, 'error', 'invalid_customer_address');
    end if;

    v_city_key := translate(lower(v_city_input), 'áàâãäéèêëíìîïóòôõöúùûüç', 'aaaaaeeeeiiiiooooouuuuc');
    if v_city_key = 'cuiaba' then
      v_city := 'Cuiabá';
    elsif v_city_key = 'varzea grande' then
      v_city := 'Várzea Grande';
    else
      return jsonb_build_object('ok', false, 'error', 'unsupported_city');
    end if;

    if v_action = 'create' then
      select a.id into v_id
        from public.customer_addresses a
       where a.customer_id = p_customer_id
         and a.is_active = true
         and lower(btrim(a.street)) = lower(v_street)
         and lower(btrim(a.number)) = lower(v_number)
         and lower(btrim(coalesce(a.complement, ''))) = lower(coalesce(v_complement, ''))
         and lower(btrim(a.neighborhood)) = lower(v_neighborhood)
         and lower(btrim(a.city)) = lower(v_city)
       order by a.is_default desc, a.created_at asc
       limit 1
       for update;
      if v_id is not null then
        select * into v_row from public.customer_addresses where id = v_id;
        return jsonb_build_object('ok', true, 'created', false, 'address', jsonb_build_object(
          'id', v_row.id, 'label', v_row.label, 'street', v_row.street, 'number', v_row.number,
          'complement', v_row.complement, 'neighborhood', v_row.neighborhood, 'city', v_row.city,
          'state', v_row.state, 'postal_code', v_row.postal_code, 'reference', v_row.reference,
          'is_default', v_row.is_default, 'is_active', v_row.is_active, 'updated_at', v_row.updated_at
        ));
      end if;

      select not exists (
        select 1 from public.customer_addresses a
        where a.customer_id = p_customer_id and a.is_active = true
      ) into v_customer_found;
      insert into public.customer_addresses (
        customer_id, label, street, number, complement, neighborhood, city, state,
        postal_code, reference, is_default, is_active, last_confirmed_at, created_at, updated_at
      ) values (
        p_customer_id, v_label, v_street, v_number, v_complement, v_neighborhood, v_city, v_state,
        v_postal_code, v_reference, v_customer_found, true, clock_timestamp(), clock_timestamp(), clock_timestamp()
      ) returning id into v_id;
    else
      if p_address_id is null or p_expected_updated_at is null then
        return jsonb_build_object('ok', false, 'error', 'invalid_address_snapshot');
      end if;
      select a.is_default into v_was_default
        from public.customer_addresses a
       where a.id = p_address_id and a.customer_id = p_customer_id and a.is_active = true
       for update;
      if not found then
        return jsonb_build_object('ok', false, 'error', 'customer_address_not_found');
      end if;
      if not exists (
        select 1 from public.customer_addresses a
        where a.id = p_address_id and a.customer_id = p_customer_id and a.updated_at = p_expected_updated_at
      ) then
        return jsonb_build_object('ok', false, 'error', 'address_changed');
      end if;
      update public.customer_addresses
         set label = v_label, street = v_street, number = v_number, complement = v_complement,
             neighborhood = v_neighborhood, city = v_city, state = v_state,
             postal_code = v_postal_code, reference = v_reference, updated_at = clock_timestamp()
       where id = p_address_id and customer_id = p_customer_id
       returning id into v_id;
    end if;
  elsif v_action = 'set_default' then
    if p_address_id is null then
      return jsonb_build_object('ok', false, 'error', 'invalid_address_id');
    end if;
    select a.id into v_replacement
      from public.customer_addresses a
     where a.id = p_address_id and a.customer_id = p_customer_id and a.is_active = true
     for update;
    if not found then
      return jsonb_build_object('ok', false, 'error', 'customer_address_not_found');
    end if;
    update public.customer_addresses
       set is_default = false, updated_at = clock_timestamp()
     where customer_id = p_customer_id and is_active = true and id <> p_address_id and is_default = true;
    update public.customer_addresses
       set is_default = true, updated_at = clock_timestamp()
     where id = p_address_id and customer_id = p_customer_id and is_active = true
     returning id into v_id;
  elsif v_action = 'deactivate' then
    if p_address_id is null then
      return jsonb_build_object('ok', false, 'error', 'invalid_address_id');
    end if;
    select a.is_default into v_was_default
      from public.customer_addresses a
     where a.id = p_address_id and a.customer_id = p_customer_id and a.is_active = true
     for update;
    if not found then
      return jsonb_build_object('ok', false, 'error', 'customer_address_not_found');
    end if;
    update public.customer_addresses
       set is_active = false, is_default = false, updated_at = clock_timestamp()
     where id = p_address_id and customer_id = p_customer_id
     returning id into v_id;
    if v_was_default then
      select a.id into v_replacement
        from public.customer_addresses a
       where a.customer_id = p_customer_id and a.is_active = true
       order by a.created_at asc, a.id
       limit 1
       for update;
      if v_replacement is not null then
        update public.customer_addresses
           set is_default = true, updated_at = clock_timestamp()
         where id = v_replacement;
      end if;
    end if;
  else
    return jsonb_build_object('ok', false, 'error', 'invalid_address_action');
  end if;

  select * into v_row from public.customer_addresses where id = v_id;
  insert into public.admin_audit_logs (admin_user_id, action, entity_type, entity_id, details)
  values (
    null,
    'customer_address_' || v_action,
    'customer_address',
    v_id::text,
    jsonb_build_object(
      'source', 'site_admin_code',
      'customer_id', p_customer_id,
      'label', v_row.label,
      'is_default', v_row.is_default,
      'is_active', v_row.is_active
    )
  );

  return jsonb_build_object('ok', true, 'created', v_action = 'create', 'address', jsonb_build_object(
    'id', v_row.id, 'label', v_row.label, 'street', v_row.street, 'number', v_row.number,
    'complement', v_row.complement, 'neighborhood', v_row.neighborhood, 'city', v_row.city,
    'state', v_row.state, 'postal_code', v_row.postal_code, 'reference', v_row.reference,
    'is_default', v_row.is_default, 'is_active', v_row.is_active, 'updated_at', v_row.updated_at
  ));
end;
$function$
;

-- function: ops3_storefront_customer_address_add_v1(p_customer_id uuid, p_phone text, p_document_last4 text, p_label text, p_address jsonb)
CREATE OR REPLACE FUNCTION public.ops3_storefront_customer_address_add_v1(p_customer_id uuid, p_phone text, p_document_last4 text, p_label text, p_address jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_phone text := btrim(coalesce(p_phone, ''));
  v_last4 text := regexp_replace(coalesce(p_document_last4, ''), '[^0-9]', '', 'g');
  v_label text := left(btrim(regexp_replace(coalesce(p_label, ''), '\s+', ' ', 'g')), 60);
  v_street text := left(btrim(regexp_replace(coalesce(p_address->>'street', ''), '\s+', ' ', 'g')), 180);
  v_number text := left(btrim(regexp_replace(coalesce(p_address->>'number', ''), '\s+', ' ', 'g')), 40);
  v_complement text := nullif(left(btrim(regexp_replace(coalesce(p_address->>'complement', ''), '\s+', ' ', 'g')), 180), '');
  v_neighborhood text := left(btrim(regexp_replace(coalesce(p_address->>'neighborhood', ''), '\s+', ' ', 'g')), 120);
  v_city_input text := left(btrim(regexp_replace(coalesce(p_address->>'city', ''), '\s+', ' ', 'g')), 100);
  v_city_key text;
  v_city text;
  v_postal_code text := nullif(left(regexp_replace(coalesce(p_address->>'postal_code', ''), '[^0-9]', '', 'g'), 8), '');
  v_reference text := nullif(left(btrim(regexp_replace(coalesce(p_address->>'reference', ''), '\s+', ' ', 'g')), 220), '');
  v_doc text;
  v_default boolean;
  v_phone_matches boolean;
  v_address_id uuid;
  v_row public.customer_addresses%rowtype;
begin
  if p_customer_id is null or v_phone !~ '^\+55[1-9][0-9]{9,10}$' then
    return jsonb_build_object('ok', false, 'error', 'invalid_customer');
  end if;
  if length(v_last4) <> 4 or length(v_label) < 1 then
    return jsonb_build_object('ok', false, 'error', 'document_confirmation_required');
  end if;
  if v_street = '' or v_number = '' or v_neighborhood = '' or v_city_input = '' then
    return jsonb_build_object('ok', false, 'error', 'invalid_customer_address');
  end if;

  v_city_key := translate(lower(v_city_input), 'áàâãäéèêëíìîïóòôõöúùûüç', 'aaaaaeeeeiiiiooooouuuuc');
  if v_city_key = 'cuiaba' then
    v_city := 'Cuiabá';
  elsif v_city_key = 'varzea grande' then
    v_city := 'Várzea Grande';
  else
    return jsonb_build_object('ok', false, 'error', 'unsupported_city');
  end if;

  perform 1 from public.customers c
   where c.id = p_customer_id and c.is_active = true
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'customer_not_found');
  end if;
  select public.normalize_phone_digits(c.primary_whatsapp_e164) = public.normalize_phone_digits(v_phone)
      or exists (
        select 1 from public.customer_phones cp
        where cp.customer_id = c.id
          and public.normalize_phone_digits(cp.phone_e164) = public.normalize_phone_digits(v_phone)
      )
    into v_phone_matches
    from public.customers c
   where c.id = p_customer_id and c.is_active = true;
  if not coalesce(v_phone_matches, false) then
    return jsonb_build_object('ok', false, 'error', 'customer_not_found');
  end if;

  select regexp_replace(coalesce(c.cpf_cnpj, ''), '[^0-9]', '', 'g')
    into v_doc from public.customers c where c.id = p_customer_id;
  if length(coalesce(v_doc, '')) not in (11, 14) or right(v_doc, 4) <> v_last4 then
    return jsonb_build_object('ok', false, 'error', 'document_mismatch');
  end if;

  select a.id into v_address_id
    from public.customer_addresses a
   where a.customer_id = p_customer_id and a.is_active = true
     and lower(btrim(a.street)) = lower(v_street)
     and lower(btrim(a.number)) = lower(v_number)
     and lower(btrim(coalesce(a.complement, ''))) = lower(coalesce(v_complement, ''))
     and lower(btrim(a.neighborhood)) = lower(v_neighborhood)
     and lower(btrim(a.city)) = lower(v_city)
   order by a.is_default desc, a.created_at asc
   limit 1
   for update;
  if v_address_id is not null then
    select * into v_row from public.customer_addresses where id = v_address_id;
    return jsonb_build_object('ok', true, 'created', false, 'address', jsonb_build_object(
      'id', v_row.id, 'label', v_row.label, 'street', v_row.street, 'number', v_row.number,
      'complement', v_row.complement, 'neighborhood', v_row.neighborhood, 'city', v_row.city,
      'state', v_row.state, 'postal_code', v_row.postal_code, 'reference', v_row.reference,
      'is_default', v_row.is_default, 'updated_at', v_row.updated_at
    ));
  end if;

  select not exists (
    select 1 from public.customer_addresses a
    where a.customer_id = p_customer_id and a.is_active = true
  ) into v_default;
  insert into public.customer_addresses (
    customer_id, label, street, number, complement, neighborhood, city, state,
    postal_code, reference, is_default, is_active, last_confirmed_at, created_at, updated_at
  ) values (
    p_customer_id, v_label, v_street, v_number, v_complement, v_neighborhood, v_city, 'MT',
    v_postal_code, v_reference, v_default, true, clock_timestamp(), clock_timestamp(), clock_timestamp()
  ) returning id into v_address_id;

  select * into v_row from public.customer_addresses where id = v_address_id;
  return jsonb_build_object('ok', true, 'created', true, 'address', jsonb_build_object(
    'id', v_row.id, 'label', v_row.label, 'street', v_row.street, 'number', v_row.number,
    'complement', v_row.complement, 'neighborhood', v_row.neighborhood, 'city', v_row.city,
    'state', v_row.state, 'postal_code', v_row.postal_code, 'reference', v_row.reference,
    'is_default', v_row.is_default, 'updated_at', v_row.updated_at
  ));
end;
$function$
;

-- function: ops3_storefront_customer_document_bind_v1(p_customer_id uuid, p_phone text, p_document text)
CREATE OR REPLACE FUNCTION public.ops3_storefront_customer_document_bind_v1(p_customer_id uuid, p_phone text, p_document text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_phone text := btrim(coalesce(p_phone, ''));
  v_document text := regexp_replace(coalesce(p_document, ''), '[^0-9]', '', 'g');
  v_existing_document text;
begin
  if p_customer_id is null or v_phone !~ '^\+55[1-9][0-9]{9,10}$'
     or not public.ops2_valid_cpf_cnpj_v1(v_document) then
    return jsonb_build_object('ok', false, 'error', 'invalid_document_confirmation');
  end if;

  perform pg_advisory_xact_lock(hashtextextended('ops3:customer-document:' || v_document, 0));
  select regexp_replace(coalesce(c.cpf_cnpj, ''), '[^0-9]', '', 'g')
    into v_existing_document
    from public.customers c
   where c.id = p_customer_id and c.is_active = true
     and (
       public.normalize_phone_digits(c.primary_whatsapp_e164) = public.normalize_phone_digits(v_phone)
       or exists (
         select 1 from public.customer_phones cp
         where cp.customer_id = c.id
           and public.normalize_phone_digits(cp.phone_e164) = public.normalize_phone_digits(v_phone)
       )
     )
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'customer_not_found');
  end if;

  if coalesce(v_existing_document, '') <> '' then
    if v_existing_document = v_document then
      return jsonb_build_object('ok', true, 'already_bound', true);
    end if;
    return jsonb_build_object('ok', false, 'error', 'document_mismatch');
  end if;
  if exists (
    select 1 from public.customers c
    where c.id <> p_customer_id
      and regexp_replace(coalesce(c.cpf_cnpj, ''), '[^0-9]', '', 'g') = v_document
  ) then
    return jsonb_build_object('ok', false, 'error', 'document_already_in_use');
  end if;

  update public.customers
     set cpf_cnpj = v_document, updated_at = clock_timestamp()
   where id = p_customer_id and is_active = true;
  insert into public.admin_audit_logs (admin_user_id, action, entity_type, entity_id, details)
  values (null, 'customer_document_confirmed_checkout', 'customer', p_customer_id::text,
    jsonb_build_object('source', 'storefront_checkout', 'document_last4', right(v_document, 4)));
  return jsonb_build_object('ok', true, 'already_bound', false);
end;
$function$
;

-- function: ops3_storefront_customer_register_v1(p_phone text, p_name text, p_document text, p_street text, p_number text, p_neighborhood text, p_city text, p_complement text, p_reference text, p_postal_code text, p_marketing_opt_in boolean, p_source_key text, p_address_label text)
CREATE OR REPLACE FUNCTION public.ops3_storefront_customer_register_v1(p_phone text, p_name text, p_document text, p_street text, p_number text, p_neighborhood text, p_city text, p_complement text DEFAULT NULL::text, p_reference text DEFAULT NULL::text, p_postal_code text DEFAULT NULL::text, p_marketing_opt_in boolean DEFAULT NULL::boolean, p_source_key text DEFAULT 'site_checkout'::text, p_address_label text DEFAULT 'Casa'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_phone text := public.canonical_whatsapp_e164_br_v2(p_phone);
  v_document text := regexp_replace(coalesce(p_document, ''), '[^0-9]', '', 'g');
  v_result jsonb;
  v_address_id uuid;
  v_label text := left(btrim(regexp_replace(coalesce(p_address_label, 'Casa'), '\s+', ' ', 'g')), 60);
begin
  if v_phone is null or not public.ops2_valid_cpf_cnpj_v1(v_document) then
    return jsonb_build_object('ok', false, 'error', case when v_phone is null then 'invalid_phone' else 'invalid_document' end);
  end if;
  if length(v_label) < 1 then v_label := 'Casa'; end if;

  perform pg_advisory_xact_lock(hashtextextended('ops3:registration-phone:' || v_phone, 0));
  perform pg_advisory_xact_lock(hashtextextended('ops3:customer-document:' || v_document, 0));

  if exists (
    select 1 from public.customer_ids_by_phone_variants_v1(v_phone) x
  ) then
    return jsonb_build_object('ok', false, 'error', 'existing_customer_requires_verification');
  end if;
  if exists (
    select 1 from public.customers c
    where regexp_replace(coalesce(c.cpf_cnpj, ''), '[^0-9]', '', 'g') = v_document
  ) then
    return jsonb_build_object('ok', false, 'error', 'document_already_in_use');
  end if;

  v_result := public.ops2_upsert_storefront_registration_v1(
    p_phone, p_name, p_document, p_street, p_number, p_neighborhood, p_city,
    p_complement, p_reference, p_postal_code, p_marketing_opt_in, p_source_key
  );
  if coalesce((v_result->>'ok')::boolean, false) is not true then
    return v_result;
  end if;
  begin
    v_address_id := nullif(v_result#>>'{address,id}', '')::uuid;
  exception when others then
    v_address_id := null;
  end;
  if v_address_id is not null then
    update public.customer_addresses
       set label = v_label, updated_at = clock_timestamp()
     where id = v_address_id and is_active = true;
    v_result := jsonb_set(v_result, '{address,label}', to_jsonb(v_label), true);
  end if;
  return v_result;
end;
$function$
;

-- function: ops4_apply_postorder_quickreply_v1(p_order_id uuid, p_account_id uuid, p_phone_e164 text, p_action text, p_nonce_hash text, p_provider_message_id text)
CREATE OR REPLACE FUNCTION public.ops4_apply_postorder_quickreply_v1(p_order_id uuid, p_account_id uuid, p_phone_e164 text, p_action text, p_nonce_hash text, p_provider_message_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare f private.ops4_postorder_followups_v1%rowtype;
  v_token_hash text; v_result jsonb;
begin
  if p_action not in ('confirm','edit')
    or p_nonce_hash !~ '^[a-f0-9]{64}$'
    or nullif(btrim(coalesce(p_provider_message_id,'')),'') is null then
    return jsonb_build_object('ok',false,'error','invalid_reply');
  end if;
  select * into f from private.ops4_postorder_followups_v1
    where order_id=p_order_id for update;
  if not found or f.confirm_status<>'sent'
    or f.whatsapp_account_id is distinct from p_account_id
    or f.phone_e164 is distinct from p_phone_e164
    or f.confirm_nonce_hash is distinct from p_nonce_hash
    or f.sent_at is null or now()>f.expires_at then
    return jsonb_build_object('ok',false,'error','reply_not_applicable');
  end if;
  if p_action='edit' then
    update private.ops4_postorder_followups_v1
      set confirm_status='changes_requested',
          reply_provider_message_id=p_provider_message_id,updated_at=now()
      where order_id=p_order_id;
    return jsonb_build_object('ok',true,'action','edit','order_id',p_order_id);
  end if;
  select token_hash into v_token_hash from private.order_customer_actions_v1
    where order_id=p_order_id;
  if v_token_hash is null then
    return jsonb_build_object('ok',false,'error','customer_action_missing');
  end if;
  v_result:=public.ops3_confirm_customer_order_v1(
    v_token_hash,f.confirm_total,f.confirm_order_updated_at
  );
  if coalesce((v_result->>'ok')::boolean,false) is true then
    update private.ops4_postorder_followups_v1
      set confirm_status='confirmed',reply_provider_message_id=p_provider_message_id,
          updated_at=now() where order_id=p_order_id;
  elsif v_result->>'error' in ('order_changed','order_status_closed','session_expired') then
    update private.ops4_postorder_followups_v1
      set confirm_status='conflict',last_error=v_result->>'error',updated_at=now()
      where order_id=p_order_id;
  end if;
  return v_result||jsonb_build_object('action','confirm','order_id',p_order_id);
end;$function$
;

-- function: ops4_claim_due_postorder_followups_v1(p_limit integer)
CREATE OR REPLACE FUNCTION public.ops4_claim_due_postorder_followups_v1(p_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_rows jsonb;
begin
  with candidate as (
    select f.order_id from private.ops4_postorder_followups_v1 f
    where f.confirm_status='pending' and f.confirm_due_at<=now()
      and f.attempts<2 and f.expires_at>now()
      and exists(
        select 1 from public.whatsapp_templates_v1 t
        where t.whatsapp_account_id=f.whatsapp_account_id
          and t.name='pedidoconfirmacao'||f.channel||'v1'
          and t.language='pt_BR' and t.status='APPROVED'
      )
    order by f.confirm_due_at,f.created_at
    limit greatest(1,least(coalesce(p_limit,10),15))
    for update skip locked
  ), updated as (
    update private.ops4_postorder_followups_v1 f
       set confirm_status='claimed',claimed_at=now(),attempts=attempts+1,updated_at=now()
    where f.order_id in (select order_id from candidate)
    returning f.order_id,f.whatsapp_account_id,f.phone_e164,f.channel,f.expires_at
  )
  select coalesce(jsonb_agg(to_jsonb(u)),'[]'::jsonb) into v_rows from updated u;
  return jsonb_build_object('ok',true,'items',v_rows);
end;$function$
;

-- function: ops4_claim_meta_postorder_command_v1(p_token_hash text)
CREATE OR REPLACE FUNCTION public.ops4_claim_meta_postorder_command_v1(p_token_hash text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid;
begin
  if p_token_hash is null or p_token_hash !~ '^[0-9a-f]{64}$' then return false; end if;
  update private.ops4_meta_postorder_commands_v1
  set claimed_at=now(),status='claimed'
  where token_hash=p_token_hash
    and claimed_at is null and expires_at>now()
    and status='queued'
  returning id into v_id;
  return v_id is not null;
end;$function$
;

-- function: ops4_claim_postorder_dispatch_command_v1(p_token_hash text)
CREATE OR REPLACE FUNCTION public.ops4_claim_postorder_dispatch_command_v1(p_token_hash text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_token_hash is null or p_token_hash !~ '^[a-f0-9]{64}$' then return false; end if;
  update private.ops4_postorder_dispatch_commands_v1
  set claimed_at=now()
  where token_hash=p_token_hash and claimed_at is null and expires_at>now();
  return found;
end;$function$
;

-- function: ops4_complete_postorder_confirm_send_v1(p_order_id uuid, p_status text, p_nonce_hash text, p_expected_total numeric, p_expected_updated_at timestamp with time zone, p_provider_message_id text, p_error text)
CREATE OR REPLACE FUNCTION public.ops4_complete_postorder_confirm_send_v1(p_order_id uuid, p_status text, p_nonce_hash text DEFAULT NULL::text, p_expected_total numeric DEFAULT NULL::numeric, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_provider_message_id text DEFAULT NULL::text, p_error text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_status not in ('sent','failed','suppressed','pending') then return false; end if;
  if p_status='sent' and (p_nonce_hash !~ '^[0-9a-f]{64}$'
    or p_expected_total is null or p_expected_updated_at is null
    or nullif(p_provider_message_id,'') is null) then return false; end if;
  update private.ops4_postorder_followups_v1
  set confirm_status=p_status,confirm_nonce_hash=case when p_status='sent' then p_nonce_hash else null end,
      confirm_total=case when p_status='sent' then p_expected_total else null end,
      confirm_order_updated_at=case when p_status='sent' then p_expected_updated_at else null end,
      confirm_provider_message_id=case when p_status='sent' then p_provider_message_id else null end,
      sent_at=case when p_status='sent' then now() else null end,
      last_error=left(p_error,200),updated_at=now()
  where order_id=p_order_id and confirm_status='claimed';
  return found;
end;$function$
;

-- function: ops4_dispatch_due_postorder_confirmation_v1()
CREATE OR REPLACE FUNCTION public.ops4_dispatch_due_postorder_confirmation_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_token text:=encode(extensions.gen_random_bytes(32),'hex');
  v_id uuid;
  v_request_id bigint;
begin
  -- If nothing is due and already approved by Meta, no HTTP invocation.
  if not exists(
    select 1 from private.ops4_postorder_followups_v1 f
    where f.confirm_status='pending' and f.confirm_due_at<=now()
      and f.expires_at>now() and f.attempts<2
      and exists(select 1 from public.whatsapp_templates_v1 t
         where t.whatsapp_account_id=f.whatsapp_account_id and t.language='pt_BR'
           and t.name='pedidoconfirmacao'||f.channel||'v1' and t.status='APPROVED')
  ) then return jsonb_build_object('ok',true,'status','idle'); end if;
  insert into private.ops4_postorder_dispatch_commands_v1(token_hash,expires_at)
  values(encode(pg_catalog.sha256(pg_catalog.convert_to(v_token,'UTF8')),'hex'),now()+interval '4 minutes')
  returning id into v_id;
  select net.http_post(
    url:='https://ssbesxgaijknwsjbsbcz.supabase.co/functions/v1/order-postorder-confirm-v1',
    headers:=jsonb_build_object('Content-Type','application/json','x-postorder-once',v_token),
    body:='{}'::jsonb,
    timeout_milliseconds:=105000
  ) into v_request_id;
  update private.ops4_postorder_dispatch_commands_v1
    set request_id=v_request_id where id=v_id;
  return jsonb_build_object('ok',true,'status','dispatched','request_id',v_request_id);
end;$function$
;

-- function: ops4_dispatch_meta_postorder_v1()
CREATE OR REPLACE FUNCTION public.ops4_dispatch_meta_postorder_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_token text:=encode(extensions.gen_random_bytes(32),'hex');
  v_id uuid;
  v_request_id bigint;
begin
  insert into private.ops4_meta_postorder_commands_v1(token_hash,expires_at)
  values(encode(pg_catalog.sha256(pg_catalog.convert_to(v_token,'UTF8')),'hex'),now()+interval '4 minutes')
  returning id into v_id;
  select net.http_post(
    url:='https://ssbesxgaijknwsjbsbcz.supabase.co/functions/v1/admin-whatsapp-templates-v1?action=postorder_provision_system',
    headers:=jsonb_build_object('Content-Type','application/json','x-meta-provision-once',v_token),
    body:='{}'::jsonb,
    timeout_milliseconds:=25000
  ) into v_request_id;
  update private.ops4_meta_postorder_commands_v1 set request_id=v_request_id where id=v_id;
  return jsonb_build_object('ok',true,'command_id',v_id,'request_id',v_request_id);
end;$function$
;

-- function: ops4_meta_postorder_approval_tick_v1()
CREATE OR REPLACE FUNCTION public.ops4_meta_postorder_approval_tick_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_approved integer;
  v_dispatch jsonb;
  v_job text:='donaantonia-meta-postorder-v3-approval';
begin
  select count(distinct t.name)::integer into v_approved
  from public.whatsapp_templates_v1 t
  join public.whatsapp_accounts a on a.id=t.whatsapp_account_id
  where (a.slug='dona-antonia-0975' and t.name='pedidoorganizadosite0975v3'
         or a.slug='dona-antonia-1018' and t.name='pedidoorganizadosite1018v3')
    and t.status='APPROVED' and t.language='pt_BR';
  if v_approved=2 or now()>=timestamptz '2026-10-22 00:00:00+00' then
    if exists (select 1 from cron.job j where j.jobname=v_job and j.active) then
      perform cron.unschedule(v_job);
    end if;
    return jsonb_build_object('ok',true,'complete',v_approved=2,'approved_channels',v_approved,'stopped',true);
  end if;
  v_dispatch:=public.ops4_dispatch_meta_postorder_v1();
  return jsonb_build_object('ok',true,'approved_channels',v_approved,'dispatch',v_dispatch);
end;$function$
;

-- function: ops4_offer_send_result_v1(p_order_id uuid, p_status text, p_provider_message_id text)
CREATE OR REPLACE FUNCTION public.ops4_offer_send_result_v1(p_order_id uuid, p_status text, p_provider_message_id text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_status not in ('sent','skipped','failed','uncertain') then return false; end if;
  update private.ops4_postorder_followups_v1
    set offer_status=p_status,offer_provider_message_id=p_provider_message_id,updated_at=now()
    where order_id=p_order_id and offer_status='pending';
  return found;
end;$function$
;

-- function: ops4_register_postorder_followup_v1(p_order_id uuid, p_whatsapp_account_id uuid, p_phone_e164 text, p_channel text)
CREATE OR REPLACE FUNCTION public.ops4_register_postorder_followup_v1(p_order_id uuid, p_whatsapp_account_id uuid, p_phone_e164 text, p_channel text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  o public.orders%rowtype;
  a public.whatsapp_accounts%rowtype;
  n integer;
begin
  if p_order_id is null or p_whatsapp_account_id is null or
    p_channel not in ('0975','1018') or
    p_phone_e164 !~ '^55[0-9]{10,11}$' then
    return jsonb_build_object('ok',false,'error','invalid_followup_request');
  end if;
  select * into o from public.orders where id=p_order_id;
  select * into a from public.whatsapp_accounts where id=p_whatsapp_account_id;
  if o.id is null or o.source not in ('vitrine','storefront_v2') or o.status<>'storefront_received'
    or a.id is null or a.is_active is not true
    or a.slug <> 'dona-antonia-'||p_channel
    or regexp_replace(coalesce(o.phone_e164,''),'\D','','g') <> p_phone_e164 then
    return jsonb_build_object('ok',false,'error','order_not_eligible');
  end if;
  if not exists(select 1 from private.order_customer_actions_v1 c where c.order_id=o.id
     and c.expires_at>now()) then
    return jsonb_build_object('ok',false,'error','customer_action_not_issued');
  end if;
  insert into private.ops4_postorder_followups_v1
    (order_id,whatsapp_account_id,phone_e164,channel,confirm_due_at)
  values (o.id,a.id,p_phone_e164,p_channel,greatest(now(),o.created_at+interval '20 minutes'))
  on conflict(order_id) do nothing;
  get diagnostics n=row_count;
  return jsonb_build_object('ok',true,'created',n=1,
    'order_id',o.id,'confirm_due_at',greatest(now(),o.created_at+interval '20 minutes'));
end;$function$
;

-- function: ops4_start_dispatch_v1(p_order_id uuid, p_operator_label text, p_idempotency_key text)
CREATE OR REPLACE FUNCTION public.ops4_start_dispatch_v1(p_order_id uuid, p_operator_label text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  o public.orders%rowtype;
  s public.order_separation_completions_v1%rowtype;
  c public.order_fiscal_controls%rowtype;
  gate jsonb;
  v_now timestamptz := now();
  v_key text;
begin
  if p_order_id is null then raise exception 'invalid_order'; end if;
  select * into o from public.orders where id = p_order_id for update;
  if not found then raise exception 'order_not_found'; end if;

  insert into public.order_fiscal_controls(order_id) values (o.id)
  on conflict (order_id) do nothing;
  select * into c from public.order_fiscal_controls where order_id = o.id for update;

  if o.status = 'out_for_delivery' then
    return jsonb_build_object(
      'ok', true, 'order_id', o.id, 'status', o.status,
      'dispatch_started_at', c.dispatch_started_at, 'already_started', true
    );
  end if;
  if o.status <> 'ready' then raise exception 'order_not_ready_for_dispatch'; end if;

  select * into s from public.order_separation_completions_v1 where order_id = o.id;
  if s.id is null or s.completed_at is null then raise exception 'separation_not_completed'; end if;
  if coalesce((s.metadata->>'stock_applied')::boolean, false) is not true then
    raise exception 'separation_stock_not_applied';
  end if;
  if exists (
    select 1 from public.order_separation_items_v1
     where order_id = o.id and state = 'pending'
  ) then raise exception 'separation_has_pending_items'; end if;

  -- The fiscal authorization requirement is temporarily disabled. The shared gate
  -- still blocks dispatch when the external physical-stock launch is required.
  gate := public.check_order_dispatch_fiscal_gate_v1(o.id);
  if coalesce((gate->>'allowed')::boolean, false) is not true then
    raise exception '%', coalesce(gate->>'reason', 'dispatch_not_allowed');
  end if;

  v_key := coalesce(
    nullif(trim(coalesce(p_idempotency_key, '')), ''),
    'dispatch-v4:' || o.id::text
  );
  update public.order_fiscal_controls
     set dispatch_started_at = coalesce(dispatch_started_at, v_now),
         dispatch_started_by = coalesce(
           dispatch_started_by,
           left(nullif(trim(coalesce(p_operator_label, '')), ''), 80)
         ),
         dispatch_idempotency_key = coalesce(dispatch_idempotency_key, v_key),
         delivery_status = 'out_for_delivery',
         updated_at = v_now
   where order_id = o.id;

  update public.orders set status = 'out_for_delivery', updated_at = v_now where id = o.id;

  begin
    perform public.ops_record_event_v1(
      'order', 'order.out_for_delivery', 'Pedido saiu para entrega.', 'human',
      'order', o.id::text, o.id::text, null,
      left(nullif(trim(coalesce(p_operator_label, '')), ''), 80),
      'dona_antonia', 'info',
      jsonb_build_object(
        'flow', 'orders_v4',
        'dispatch_fiscal_status', gate->>'dispatch_fiscal_status',
        'bling_invoice_id', gate->>'bling_invoice_id',
        'fiscal_invoice_sending', 'not_attempted'
      ),
      null, 'order-dispatch-v4:' || o.id::text, now()
    );
  exception when others then null;
  end;

  return jsonb_build_object(
    'ok', true, 'order_id', o.id, 'status', 'out_for_delivery',
    'dispatch_started_at', v_now, 'already_started', false, 'gate', gate,
    'fiscal_invoice_sending', 'not_attempted'
  );
end;
$function$
;

-- function: ops_apply_stock_recount_result_v1(p_product_id uuid, p_count_id uuid, p_counted_quantity numeric, p_operator_label text)
CREATE OR REPLACE FUNCTION public.ops_apply_stock_recount_result_v1(p_product_id uuid, p_count_id uuid, p_counted_quantity numeric, p_operator_label text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_attention public.ops_attention%rowtype;
  v_catalog_stock numeric;
  v_match boolean;
  v_now timestamptz:=now();
  v_review uuid;
begin
  select * into v_attention from public.ops_attention
   where entity_type='product' and entity_id=p_product_id::text
     and status in ('open','acknowledged')
     and idempotency_key='ops2:stock-recount:'||p_product_id::text
   for update;
  if not found then return jsonb_build_object('tracked',false); end if;
  select round(coalesce(stock,0),3) into v_catalog_stock from public.products where id=p_product_id for update;
  if not found then return jsonb_build_object('tracked',true,'error','product_not_found','stock_source','supabase.products.stock'); end if;
  v_match:=abs(round(coalesce(p_counted_quantity,0),3)-v_catalog_stock)<=0.0001;
  if not v_match then
    insert into public.ops_stock_reconciliation_reviews(attention_id,product_id,count_id,counted_quantity,bling_physical_snapshot,difference_to_bling,operator_label)
    values(v_attention.id,p_product_id,p_count_id,round(p_counted_quantity,3),v_catalog_stock,
      round(p_counted_quantity-v_catalog_stock,3),left(nullif(trim(coalesce(p_operator_label,'')),''),80))
    on conflict(attention_id,count_id) do update set counted_quantity=excluded.counted_quantity,
      bling_physical_snapshot=excluded.bling_physical_snapshot,difference_to_bling=excluded.difference_to_bling,
      operator_label=excluded.operator_label,updated_at=now()
    returning id into v_review;
  end if;
  update public.ops_attention
     set evidence=coalesce(evidence,'{}'::jsonb)||jsonb_build_object(
       'latest_count_id',p_count_id,'latest_counted_quantity',round(p_counted_quantity,3),
       'latest_counted_at',v_now,'latest_operator',left(nullif(trim(coalesce(p_operator_label,'')),''),80),
       'current_supabase_stock',v_catalog_stock,'matches_supabase_stock',v_match,
       'stock_source','supabase.products.stock','reconciliation_review_id',v_review,'automatic_stock_write',false),
       status=case when v_match then 'resolved' else 'open' end,
       resolved_at=case when v_match then v_now else null end,
       resolution=case when v_match then 'Recontagem coincide com o saldo cadastrado no Supabase.' else null end,
       resolution_ref=case when v_match then 'inventory-count:'||p_count_id::text else null end,
       recommended_action=case when v_match then recommended_action else 'Confirme a contagem e classifique a diferença antes de regularizar o saldo local.' end,
       updated_at=v_now
   where id=v_attention.id;
  return jsonb_build_object('tracked',true,'matches_supabase_stock',v_match,
    'supabase_stock',v_catalog_stock,'counted_quantity',round(p_counted_quantity,3),
    'attention_status',case when v_match then 'resolved' else 'open' end,
    'review_id',v_review,'classification_required',not v_match,'automatic_stock_write',false,
    'stock_source','supabase.products.stock');
end;
$function$
;

-- function: ops_cancel_print_jobs_for_entity_v1(p_entity_type text, p_entity_id text, p_reason text)
CREATE OR REPLACE FUNCTION public.ops_cancel_print_jobs_for_entity_v1(p_entity_type text, p_entity_id text, p_reason text DEFAULT 'entity_cancelled'::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_count integer;
begin
  update public.ops_print_jobs
     set status='cancelled',
         last_error=left(coalesce(p_reason,'entity_cancelled'),500),
         updated_at=now()
   where entity_type=p_entity_type
     and entity_id=p_entity_id
     and status in ('pending','failed');
  get diagnostics v_count = row_count;
  return v_count;
end;
$function$
;

-- function: ops_claim_print_jobs_v1(p_worker text, p_limit integer)
CREATE OR REPLACE FUNCTION public.ops_claim_print_jobs_v1(p_worker text, p_limit integer DEFAULT 3)
 RETURNS SETOF ops_print_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  return query
  with picked as (
    select id
      from public.ops_print_jobs
     where status in ('pending','failed')
     order by created_at
     for update skip locked
     limit greatest(1,least(10,coalesce(p_limit,3)))
  )
  update public.ops_print_jobs j
     set status='claimed',
         claimed_at=now(),
         claimed_by=left(coalesce(p_worker,'unknown'),120),
         attempts=j.attempts+1,
         updated_at=now(),
         last_error=null
    from picked
   where j.id=picked.id
  returning j.*;
end;
$function$
;

-- function: ops_classify_stock_reconciliation_v1(p_attention_id uuid, p_cause_code text, p_cause_note text, p_evidence_ref text, p_operator_label text)
CREATE OR REPLACE FUNCTION public.ops_classify_stock_reconciliation_v1(p_attention_id uuid, p_cause_code text, p_cause_note text, p_evidence_ref text DEFAULT NULL::text, p_operator_label text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v public.ops_stock_reconciliation_reviews%rowtype; c text:=lower(trim(coalesce(p_cause_code,'')));
begin
 if c not in ('documented_entry','loss_damage_expiry','counting_error','erp_movement_missing','surplus_unknown','other') then raise exception 'invalid_cause_code'; end if;
 if length(trim(coalesce(p_cause_note,'')))<5 then raise exception 'cause_note_required'; end if;
 select * into v from public.ops_stock_reconciliation_reviews where attention_id=p_attention_id order by created_at desc limit 1 for update;
 if not found then raise exception 'reconciliation_review_not_found'; end if;
 update public.ops_stock_reconciliation_reviews set cause_code=c,cause_note=left(trim(p_cause_note),500),evidence_ref=left(nullif(trim(coalesce(p_evidence_ref,'')),''),300),operator_label=left(nullif(trim(coalesce(p_operator_label,'')),''),80),status='ready_for_erp_review',updated_at=now() where id=v.id;
 update public.ops_attention set evidence=coalesce(evidence,'{}'::jsonb)||jsonb_build_object('cause_code',c,'cause_note',left(trim(p_cause_note),500),'evidence_ref',left(nullif(trim(coalesce(p_evidence_ref,'')),''),300),'classification_at',now(),'automatic_stock_write',false),recommended_action='Causa classificada. Revisar evidência e somente então executar o movimento oficial adequado no Bling.',updated_at=now() where id=p_attention_id;
 return jsonb_build_object('review_id',v.id,'status','ready_for_erp_review','cause_code',c,'automatic_stock_write',false);
end $function$
;

-- function: ops_confirm_delivery_return_v1(p_case_id uuid, p_disposition text, p_operator_label text)
CREATE OR REPLACE FUNCTION public.ops_confirm_delivery_return_v1(p_case_id uuid, p_disposition text, p_operator_label text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_case public.order_delivery_return_cases%rowtype;
  v_order public.orders%rowtype;
  v_disp text:=lower(trim(coalesce(p_disposition,'')));
  v_attention_id uuid;
begin
  select * into v_case
  from public.order_delivery_return_cases
  where id=p_case_id
  for update;

  if not found then raise exception 'delivery_return_case_not_found'; end if;

  if v_case.status<>'returning' then
    return jsonb_build_object(
      'case_id',v_case.id,
      'order_id',v_case.order_id,
      'status',v_case.status,
      'already_returned',true
    );
  end if;

  if v_disp not in ('redelivery','review') then
    raise exception 'invalid_return_disposition';
  end if;

  select * into v_order
  from public.orders
  where id=v_case.order_id
  for update;

  if not found then raise exception 'order_not_found'; end if;
  if v_order.status<>'out_for_delivery' then raise exception 'order_not_in_delivery'; end if;

  if v_disp='redelivery' then
    update public.order_delivery_return_cases
       set status='returned_redelivery',
           final_disposition='redelivery',
           returned_at=now(),
           returned_by=left(nullif(trim(coalesce(p_operator_label,'')),''),80),
           closed_at=now(),
           resolution='Mercadoria retornou e permanece alocada ao pedido para reentrega.'
     where id=v_case.id;

    update public.orders
       set status='ready',
           updated_at=now()
     where id=v_case.order_id;

    perform public.ops_record_event_v1(
      'delivery','delivery.returned_for_redelivery',
      'Mercadoria retornou ao depósito e o pedido ficou pronto para reentrega.',
      'human','order',v_case.order_id::text,v_case.order_id::text,
      null,left(nullif(trim(coalesce(p_operator_label,'')),''),80),
      'dona_antonia','info',
      jsonb_build_object(
        'case_id',v_case.id,
        'attempt_number',v_case.attempt_number,
        'stock_restored',false,
        'stock_remains_allocated',true
      ),
      null,'delivery-returned-redelivery:'||v_case.id::text,now()
    );

    return jsonb_build_object(
      'case_id',v_case.id,
      'order_id',v_case.order_id,
      'status','returned_redelivery',
      'order_status','ready',
      'dispatch_blocked',false
    );
  end if;

  update public.order_delivery_return_cases
     set status='returned_review',
         final_disposition='review',
         returned_at=now(),
         returned_by=left(nullif(trim(coalesce(p_operator_label,'')),''),80),
         resolution='Mercadoria retornou e aguarda inspeção / decisão comercial-fiscal.'
   where id=v_case.id;

  update public.orders
     set status='ready',
         updated_at=now()
   where id=v_case.order_id;

  v_attention_id:=public.ops_open_attention_v1(
    'delivery_return_review',
    'Retorno de entrega precisa de revisão antes de nova saída.',
    'order',v_case.order_id::text,v_case.order_id::text,
    'high','supervisor',
    'Inspecionar a mercadoria. Não reenviar nem devolver ao estoque geral antes de resolver o retorno.',
    jsonb_build_object(
      'case_id',v_case.id,
      'attempt_number',v_case.attempt_number,
      'reason_code',v_case.reason_code,
      'reason_label',v_case.reason_label,
      'stock_restored',false
    ),
    'dona_antonia',
    'delivery-return-review:'||v_case.id::text,
    null
  );

  perform public.ops_record_event_v1(
    'delivery','delivery.returned_for_review',
    'Mercadoria retornou e ficou bloqueada para revisão.',
    'human','order',v_case.order_id::text,v_case.order_id::text,
    null,left(nullif(trim(coalesce(p_operator_label,'')),''),80),
    'dona_antonia','warning',
    jsonb_build_object(
      'case_id',v_case.id,
      'attempt_number',v_case.attempt_number,
      'attention_id',v_attention_id,
      'stock_restored',false,
      'dispatch_blocked',true
    ),
    null,'delivery-returned-review:'||v_case.id::text,now()
  );

  return jsonb_build_object(
    'case_id',v_case.id,
    'order_id',v_case.order_id,
    'status','returned_review',
    'order_status','ready',
    'dispatch_blocked',true,
    'attention_id',v_attention_id
  );
end;
$function$
;

-- function: ops_enforce_delivery_payment_before_delivered_v1()
CREATE OR REPLACE FUNCTION public.ops_enforce_delivery_payment_before_delivered_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_expected bigint;
  v_valid integer:=0;
  v_return_open integer:=0;
begin
  if new.status='delivered' and old.status is distinct from 'delivered' then
    v_expected:=round(coalesce(new.total,0)*100)::bigint;
    select count(*) into v_return_open from public.order_delivery_return_cases where order_id=new.id and status in ('returning','returned_review');
    if v_return_open>0 then raise exception 'delivery_return_open'; end if;
    select count(*) into v_valid
    from public.order_payment_settlements s
    where s.order_id=new.id
      and s.source='delivery'
      and s.status in ('captured','synced','needs_review')
      and s.expected_total_cents=v_expected
      and s.captured_total_cents=v_expected
      and exists(
        select 1 from public.order_payment_parts p
        where p.settlement_id=s.id
        group by p.settlement_id
        having sum(p.amount_cents)=v_expected
      );
    if v_valid<>1 then raise exception 'delivery_payment_required_before_delivered'; end if;
  end if;
  return new;
end;
$function$
;

-- function: ops_enforce_fiscal_before_dispatch_v1()
CREATE OR REPLACE FUNCTION public.ops_enforce_fiscal_before_dispatch_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  fiscal_allowed boolean:=false;
  authority text:='legacy_shadow';
  physical_state text:=null;
begin
  if new.status='out_for_delivery' and old.status='ready' then
    select c.dispatch_fiscal_status in ('authorized','not_required') into fiscal_allowed
    from public.order_fiscal_controls c where c.order_id=new.id;
    if coalesce(fiscal_allowed,false) is not true then
      raise exception 'fiscal_authorization_required_before_dispatch';
    end if;

    select coalesce(r.metadata->>'ops2_stock_authority','legacy_shadow') into authority
    from public.bling_hub_runtime_v2 r where r.id=1;

    if authority='bling' then
      select s.state into physical_state from public.bling_order_stock_controls_v2 s where s.source_order_id=new.id;
      if coalesce(physical_state,'') <> 'launched' then
        raise exception 'bling_physical_stock_launch_required_before_dispatch';
      end if;
    end if;
  end if;
  return new;
end $function$
;

-- function: ops_enforce_order_check_before_ready_v1()
CREATE OR REPLACE FUNCTION public.ops_enforce_order_check_before_ready_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.status='ready' and old.status='processing' then
    if not exists(
      select 1 from public.ops_order_check_sessions s
      where s.order_id=new.id and s.status='verified' and s.verified_at is not null
    )
    and not (
      exists(
        select 1 from public.order_separation_completions_v1 c
        where c.order_id=new.id and coalesce((c.metadata->>'stock_applied')::boolean,false)=true
      )
      and exists(
        select 1 from public.order_separation_items_v1 s where s.order_id=new.id
      )
      and not exists(
        select 1 from public.order_separation_items_v1 s where s.order_id=new.id and s.state='pending'
      )
    ) then
      raise exception 'order_check_required_before_ready';
    end if;
  end if;
  return new;
end
$function$
;

-- function: ops_enqueue_print_job_v1(p_job_type text, p_entity_type text, p_entity_id text, p_version_key text, p_printer_profile text, p_copies integer, p_payload jsonb, p_source_system text, p_idempotency_key text)
CREATE OR REPLACE FUNCTION public.ops_enqueue_print_job_v1(p_job_type text, p_entity_type text, p_entity_id text, p_version_key text, p_printer_profile text DEFAULT 'separation_85mm'::text, p_copies integer DEFAULT 1, p_payload jsonb DEFAULT '{}'::jsonb, p_source_system text DEFAULT 'dona_antonia'::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
  v_key text;
begin
  v_key := coalesce(nullif(trim(p_idempotency_key),''), p_job_type||':'||p_entity_type||':'||p_entity_id||':'||p_version_key);

  select id into v_id
  from public.ops_print_jobs
  where idempotency_key=v_key
  limit 1;

  if v_id is not null then return v_id; end if;

  insert into public.ops_print_jobs(
    job_type,entity_type,entity_id,version_key,printer_profile,copies,payload,source_system,idempotency_key
  ) values (
    p_job_type,p_entity_type,p_entity_id,p_version_key,p_printer_profile,
    greatest(1,least(5,coalesce(p_copies,1))),coalesce(p_payload,'{}'::jsonb),p_source_system,v_key
  )
  returning id into v_id;

  return v_id;
exception when unique_violation then
  select id into v_id from public.ops_print_jobs where idempotency_key=v_key limit 1;
  return v_id;
end;
$function$
;

-- function: ops_finish_order_check_v1(p_order_id uuid, p_operator_label text)
CREATE OR REPLACE FUNCTION public.ops_finish_order_check_v1(p_order_id uuid, p_operator_label text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare o public.orders%rowtype; s public.ops_order_check_sessions%rowtype; missing int;
begin
 select * into o from public.orders where id=p_order_id for update; if not found then raise exception 'order_not_found'; end if; if o.status<>'processing' then raise exception 'order_not_in_separation'; end if;
 select * into s from public.ops_order_check_sessions where order_id=p_order_id and status='open' order by started_at desc limit 1 for update; if not found then raise exception 'check_session_not_found'; end if;
 select count(*) into missing from public.ops_order_check_items where session_id=s.id and checked_quantity<>expected_quantity; if missing>0 then return jsonb_build_object('ok',false,'error','check_incomplete','remaining_items',missing,'session_id',s.id); end if;
 update public.ops_order_check_sessions set status='verified',verified_at=now(),operator_label=coalesce(left(nullif(trim(coalesce(p_operator_label,'')),''),80),operator_label),updated_at=now() where id=s.id;
 return jsonb_build_object('ok',true,'verified',true,'session_id',s.id,'order_id',p_order_id);
end $function$
;

-- function: ops_finish_print_job_v1(p_job_id uuid, p_status text, p_error text)
CREATE OR REPLACE FUNCTION public.ops_finish_print_job_v1(p_job_id uuid, p_status text, p_error text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_status not in ('printed','failed') then
    raise exception 'invalid_print_finish_status';
  end if;

  update public.ops_print_jobs
     set status=p_status,
         printed_at=case when p_status='printed' then now() else printed_at end,
         last_error=case when p_status='failed' then left(coalesce(p_error,'print_failed'),500) else null end,
         updated_at=now()
   where id=p_job_id
     and status='claimed';

  return found;
end;
$function$
;

-- function: ops_get_order_check_v1(p_order_id uuid)
CREATE OR REPLACE FUNCTION public.ops_get_order_check_v1(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
select coalesce((select jsonb_build_object('session_id',s.id,'status',s.status,'started_at',s.started_at,'verified_at',s.verified_at,'items',coalesce((select jsonb_agg(jsonb_build_object('product_id',i.product_id,'gtin',i.gtin,'name',i.name_snapshot,'expected_quantity',i.expected_quantity,'checked_quantity',i.checked_quantity,'complete',i.checked_quantity=i.expected_quantity) order by i.name_snapshot) from public.ops_order_check_items i where i.session_id=s.id),'[]'::jsonb),'complete',not exists(select 1 from public.ops_order_check_items x where x.session_id=s.id and x.checked_quantity<>x.expected_quantity)) from public.ops_order_check_sessions s where s.order_id=p_order_id order by s.started_at desc limit 1),jsonb_build_object('status','not_started','items','[]'::jsonb,'complete',false)) $function$
;

-- function: ops_mark_delivery_stop_failed_v1(p_order_id uuid, p_reason text)
CREATE OR REPLACE FUNCTION public.ops_mark_delivery_stop_failed_v1(p_order_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_count integer;
begin
  update public.ops_delivery_stops s
     set status='failed',
         updated_at=now()
   where s.order_id=p_order_id
     and s.status='out_for_delivery'
     and exists (
       select 1 from public.ops_delivery_runs r
       where r.id=s.run_id and r.status in ('planned','dispatched')
     );
  get diagnostics v_count=row_count;

  update public.ops_delivery_runs r
     set status='completed',
         completed_at=coalesce(completed_at,now()),
         updated_at=now()
   where r.status='dispatched'
     and not exists (
       select 1 from public.ops_delivery_stops s
       where s.run_id=r.id
         and s.status not in ('delivered','failed','cancelled')
     );

  return v_count;
end;
$function$
;

-- function: ops_open_attention_v1(p_type text, p_summary text, p_entity_type text, p_entity_id text, p_correlation_id text, p_priority text, p_owner_role text, p_recommended_action text, p_evidence jsonb, p_source_system text, p_idempotency_key text, p_due_at timestamp with time zone)
CREATE OR REPLACE FUNCTION public.ops_open_attention_v1(p_type text, p_summary text, p_entity_type text DEFAULT NULL::text, p_entity_id text DEFAULT NULL::text, p_correlation_id text DEFAULT NULL::text, p_priority text DEFAULT 'normal'::text, p_owner_role text DEFAULT 'supervisor'::text, p_recommended_action text DEFAULT NULL::text, p_evidence jsonb DEFAULT '{}'::jsonb, p_source_system text DEFAULT 'dona_antonia'::text, p_idempotency_key text DEFAULT NULL::text, p_due_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
begin
  if p_idempotency_key is not null then
    select id into v_id
    from public.ops_attention
    where idempotency_key=p_idempotency_key
      and status in ('open','acknowledged')
    limit 1;

    if v_id is not null then
      update public.ops_attention
      set updated_at=now(),
          summary=p_summary,
          priority=p_priority,
          owner_role=p_owner_role,
          recommended_action=p_recommended_action,
          evidence=coalesce(p_evidence,'{}'::jsonb),
          due_at=p_due_at
      where id=v_id;
      return v_id;
    end if;
  end if;

  insert into public.ops_attention(
    type,entity_type,entity_id,correlation_id,priority,owner_role,status,
    summary,recommended_action,evidence,source_system,idempotency_key,due_at
  ) values (
    p_type,p_entity_type,p_entity_id,p_correlation_id,p_priority,p_owner_role,'open',
    p_summary,p_recommended_action,coalesce(p_evidence,'{}'::jsonb),p_source_system,p_idempotency_key,p_due_at
  )
  returning id into v_id;

  return v_id;
exception when unique_violation then
  select id into v_id from public.ops_attention where idempotency_key=p_idempotency_key limit 1;
  return v_id;
end;
$function$
;

-- function: ops_payment_bling_shadow_status_v1()
CREATE OR REPLACE FUNCTION public.ops_payment_bling_shadow_status_v1()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
 select jsonb_build_object(
   'mode','shadow_only','external_write',false,
   'mappings',coalesce((select jsonb_agg(jsonb_build_object(
     'method',method,'mapping_state',mapping_state,
     'payment_method_mapped',bling_payment_method_id is not null,
     'financial_account_mapped',bling_financial_account_id is not null,
     'category_mapped',bling_category_id is not null
   ) order by method) from public.ops_payment_bling_method_map_v1),'[]'::jsonb),
   'plans',jsonb_build_object(
     'blocked_mapping',(select count(*) from public.ops_payment_bling_shadow_plans_v1 where state='blocked_mapping'),
     'ready_shadow',(select count(*) from public.ops_payment_bling_shadow_plans_v1 where state='ready_shadow'),
     'review_required',(select count(*) from public.ops_payment_bling_shadow_plans_v1 where state='review_required')
   )
 ) $function$
;

-- function: ops_plan_delivery_run_v1(p_vehicle_key text, p_order_ids uuid[], p_operator_label text)
CREATE OR REPLACE FUNCTION public.ops_plan_delivery_run_v1(p_vehicle_key text, p_order_ids uuid[], p_operator_label text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_run_id uuid := gen_random_uuid();
  v_today date := (now() at time zone 'America/Cuiaba')::date;
  v_order_ids uuid[] := '{}'::uuid[];
  v_order_id uuid;
  v_seq integer := 0;
  v_order public.orders%rowtype;
  v_existing_run uuid;
  v_existing_status text;
  v_existing_run_row public.ops_delivery_runs%rowtype;
  v_existing_order_id uuid;
  v_vehicle_key text := lower(trim(coalesce(p_vehicle_key, '')));
begin
  if v_vehicle_key !~ '^(car_[12]|driver_[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$' then
    raise exception 'invalid_vehicle';
  end if;
  if coalesce(array_length(p_order_ids, 1), 0) < 1 or array_length(p_order_ids, 1) > 30 then
    raise exception 'invalid_route_size';
  end if;
  if (select count(distinct x) from unnest(p_order_ids) x) <> array_length(p_order_ids, 1) then
    raise exception 'duplicate_order_in_route';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('ops_delivery_run:' || v_today::text || ':' || v_vehicle_key, 0)
  );

  if exists (
    select 1 from public.ops_delivery_runs
    where service_date = v_today and vehicle_key = v_vehicle_key and status = 'dispatched'
  ) then
    raise exception 'vehicle_already_dispatched';
  end if;

  if left(v_vehicle_key, 7) = 'driver_' then
    for v_existing_run_row in
      select * from public.ops_delivery_runs
      where service_date = v_today and vehicle_key = v_vehicle_key and status = 'planned'
      order by created_at, id
      for update
    loop
      if v_existing_run_row.loading_started_at is not null
         or v_existing_run_row.loaded_at is not null
         or exists (
           select 1 from public.ops_delivery_stops
           where run_id = v_existing_run_row.id
             and (loaded_at is not null or custody_confirmed_at is not null)
         ) then
        raise exception 'route_locked';
      end if;

      for v_existing_order_id in
        select order_id from public.ops_delivery_stops
        where run_id = v_existing_run_row.id and status = 'planned'
        order by sequence, created_at, id
      loop
        if array_position(v_order_ids, v_existing_order_id) is null then
          v_order_ids := array_append(v_order_ids, v_existing_order_id);
        end if;
      end loop;
    end loop;

    foreach v_order_id in array p_order_ids loop
      if array_position(v_order_ids, v_order_id) is null then
        v_order_ids := array_append(v_order_ids, v_order_id);
      end if;
    end loop;

    if array_length(v_order_ids, 1) > 30 then
      raise exception 'invalid_route_size';
    end if;
  else
    v_order_ids := p_order_ids;
  end if;

  update public.ops_delivery_runs
     set status = 'cancelled', updated_at = now()
   where service_date = v_today and vehicle_key = v_vehicle_key and status = 'planned';

  insert into public.ops_delivery_runs(id, service_date, vehicle_key, status, operator_label)
  values(v_run_id, v_today, v_vehicle_key, 'planned', nullif(trim(coalesce(p_operator_label, '')), ''));

  foreach v_order_id in array v_order_ids loop
    select * into v_order from public.orders
     where id = v_order_id and status = 'ready'
     for update;
    if not found then raise exception 'order_not_ready:%', v_order_id; end if;

    if exists (
      select 1 from public.order_delivery_return_cases
      where order_id = v_order_id and status = 'returned_review'
    ) then raise exception 'delivery_return_review_open:%', v_order_id; end if;

    select r.id, r.status into v_existing_run, v_existing_status
    from public.ops_delivery_stops s
    join public.ops_delivery_runs r on r.id = s.run_id
    where s.order_id = v_order_id
      and r.service_date = v_today
      and r.status in ('planned', 'dispatched')
      and r.id <> v_run_id
    order by case r.status when 'dispatched' then 0 else 1 end, r.created_at desc
    limit 1;

    if v_existing_run is not null and v_existing_status = 'dispatched' then
      raise exception 'order_already_dispatched:%', v_order_id;
    end if;

    if v_existing_run is not null then
      delete from public.ops_delivery_stops where run_id = v_existing_run and order_id = v_order_id;
      update public.ops_delivery_runs
         set status = 'cancelled', updated_at = now()
       where id = v_existing_run and status = 'planned'
         and not exists (select 1 from public.ops_delivery_stops where run_id = v_existing_run);
    end if;

    v_seq := v_seq + 1;
    insert into public.ops_delivery_stops(
      run_id, order_id, sequence, status, address_snapshot, phone_snapshot,
      customer_name_snapshot, order_number_snapshot, total_cents, payment_method_snapshot, maps_url_snapshot
    ) values (
      v_run_id, v_order.id, v_seq, 'planned', coalesce(v_order.delivery_address, '{}'::jsonb),
      coalesce(v_order.phone_e164, v_order.delivery_address->>'phone'),
      coalesce(v_order.customer_snapshot->>'name', v_order.delivery_address->>'customer_name', v_order.delivery_address->>'recipient_name'),
      v_order.order_number, round(coalesce(v_order.total, 0) * 100)::bigint, v_order.payment_method,
      v_order.delivery_address->>'google_maps_url'
    );
    v_existing_run := null;
    v_existing_status := null;
  end loop;

  return v_run_id;
end;
$function$
;

-- function: ops_prepare_delivery_payment_bling_shadow_v1(p_settlement_id uuid)
CREATE OR REPLACE FUNCTION public.ops_prepare_delivery_payment_bling_shadow_v1(p_settlement_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
 s public.order_payment_settlements%rowtype;
 p record; m public.ops_payment_bling_method_map_v1%rowtype;
 parts jsonb := '[]'::jsonb; blockers jsonb := '[]'::jsonb;
 fp text; st text; plan_id uuid; part_sum bigint := 0;
begin
 select * into s from public.order_payment_settlements where id=p_settlement_id;
 if not found then raise exception 'settlement_not_found'; end if;
 if s.source <> 'delivery' or s.status not in ('captured','needs_review','synced') then raise exception 'settlement_not_eligible'; end if;
 if s.expected_total_cents <> s.captured_total_cents then raise exception 'settlement_total_mismatch'; end if;

 for p in select sequence,method,amount_cents from public.order_payment_parts where settlement_id=s.id order by sequence loop
   part_sum:=part_sum+p.amount_cents;
   select * into m from public.ops_payment_bling_method_map_v1 where method=p.method;
   if not found or m.mapping_state not in ('shadow_verified','live_approved')
      or m.bling_payment_method_id is null or m.bling_financial_account_id is null or m.bling_category_id is null then
     blockers:=blockers||jsonb_build_array(jsonb_build_object('sequence',p.sequence,'method',p.method,'reason','bling_mapping_not_shadow_verified'));
   end if;
   parts:=parts||jsonb_build_array(jsonb_build_object(
     'sequence',p.sequence,'method',p.method,'amount_cents',p.amount_cents,
     'bling_payment_method_id',m.bling_payment_method_id,
     'bling_financial_account_id',m.bling_financial_account_id,
     'bling_category_id',m.bling_category_id,
     'mapping_state',coalesce(m.mapping_state,'unmapped')
   ));
 end loop;
 if part_sum<>s.captured_total_cents then raise exception 'payment_parts_total_mismatch'; end if;
 if jsonb_array_length(parts)=0 then raise exception 'payment_parts_missing'; end if;

 fp:=encode(digest(s.id::text||':'||s.order_id::text||':'||s.captured_total_cents::text||':'||parts::text,'sha256'),'hex');
 st:=case when jsonb_array_length(blockers)=0 then 'ready_shadow' else 'blocked_mapping' end;

 insert into public.ops_payment_bling_shadow_plans_v1(settlement_id,order_id,plan_fingerprint,state,total_cents,plan,blockers)
 values(s.id,s.order_id,fp,st,s.captured_total_cents,jsonb_build_object(
   'mode','shadow_only','automatic_retry',false,'external_write',false,
   'settlement_id',s.id,'order_id',s.order_id,'parts',parts
 ),blockers)
 on conflict(settlement_id,plan_fingerprint) do update set
   state=excluded.state,plan=excluded.plan,blockers=excluded.blockers,updated_at=now()
 returning id into plan_id;

 return jsonb_build_object('ok',true,'shadow_only',true,'external_write',false,'automatic_retry',false,
   'plan_id',plan_id,'state',st,'fingerprint',fp,'total_cents',s.captured_total_cents,'parts',parts,'blockers',blockers);
end $function$
;

-- function: ops_present_print_job_v1(p_entity_type text, p_entity_id text, p_job_type text)
CREATE OR REPLACE FUNCTION public.ops_present_print_job_v1(p_entity_type text, p_entity_id text, p_job_type text DEFAULT 'picking'::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_count integer;
begin
  update public.ops_print_jobs
     set status='presented',
         updated_at=now(),
         last_error=null
   where id in (
     select id
       from public.ops_print_jobs
      where entity_type=p_entity_type
        and entity_id=p_entity_id
        and job_type=p_job_type
        and status in ('pending','failed')
      order by created_at
      limit 1
   );
  get diagnostics v_count = row_count;
  return v_count;
end;
$function$
;

-- function: ops_quick_balance_save_v1(p_product_id uuid, p_scanned_ean text, p_counted_quantity numeric, p_validity_date date, p_gondola text, p_expected_stock numeric, p_expected_validity_date date, p_expected_gondola text, p_operator_label text)
CREATE OR REPLACE FUNCTION public.ops_quick_balance_save_v1(p_product_id uuid, p_scanned_ean text, p_counted_quantity numeric, p_validity_date date, p_gondola text, p_expected_stock numeric, p_expected_validity_date date, p_expected_gondola text, p_operator_label text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_product public.products%ROWTYPE;
  v_scanned_digits text;
  v_gtin_digits text;
  v_canonical_ean text;
  v_ean_candidates text[];
  v_ean_matches boolean;
  v_gondola text;
  v_diff numeric(14,3);
  v_count_id uuid;
  v_now timestamptz := now();
BEGIN
  IF p_counted_quantity IS NULL OR p_counted_quantity < 0 OR p_counted_quantity > 999999.999 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_count');
  END IF;

  v_scanned_digits := regexp_replace(coalesce(p_scanned_ean, ''), '[^0-9]', '', 'g');
  IF length(v_scanned_digits) < 8 OR length(v_scanned_digits) > 14 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_ean');
  END IF;

  v_canonical_ean := coalesce(nullif(regexp_replace(v_scanned_digits, '^0+', ''), ''), '0');
  v_ean_candidates := ARRAY[v_scanned_digits, v_canonical_ean];
  FOREACH v_gtin_digits IN ARRAY ARRAY['8','12','13','14'] LOOP
    IF length(v_canonical_ean) <= v_gtin_digits::integer THEN
      v_ean_candidates := array_append(v_ean_candidates, lpad(v_canonical_ean, v_gtin_digits::integer, '0'));
    END IF;
  END LOOP;

  SELECT * INTO v_product
  FROM public.products
  WHERE id = p_product_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'product_not_found');
  END IF;

  v_gtin_digits := regexp_replace(coalesce(v_product.gtin, ''), '[^0-9]', '', 'g');
  v_ean_matches := v_gtin_digits = ANY(v_ean_candidates)
    OR EXISTS (
      SELECT 1
      FROM public.ean_capture_records_v1 e
      WHERE e.matched_product_id = p_product_id
        AND e.sync_status = 'found'
        AND regexp_replace(coalesce(e.ean, ''), '[^0-9]', '', 'g') = ANY(v_ean_candidates)
    );
  IF NOT coalesce(v_ean_matches, false) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'ean_mismatch');
  END IF;

  IF v_product.stock IS DISTINCT FROM p_expected_stock
    OR v_product.validity_date IS DISTINCT FROM p_expected_validity_date
    OR v_product.gondola IS DISTINCT FROM p_expected_gondola THEN
    RETURN jsonb_build_object('ok', false, 'error', 'product_changed');
  END IF;

  v_gondola := nullif(left(trim(coalesce(p_gondola, '')), 24), '');
  IF v_gondola IS NOT NULL
    AND v_gondola IS DISTINCT FROM v_product.gondola
    AND NOT EXISTS (
      SELECT 1 FROM public.vitrine_gondolas g
      WHERE g.active = true AND g.number::text = v_gondola
    ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_gondola');
  END IF;

  v_diff := round(p_counted_quantity - coalesce(v_product.stock, 0), 3);

  UPDATE public.products
  SET stock = round(p_counted_quantity, 3),
      validity_date = p_validity_date,
      gondola = v_gondola,
      last_counted_at = v_now,
      physically_verified = true,
      updated_at = v_now
  WHERE id = p_product_id;

  INSERT INTO public.ops_inventory_counts(
    product_id, product_name_snapshot, gtin_snapshot, sku_snapshot,
    system_quantity_before, counted_quantity, difference, operator_label,
    source, local_stock_applied, reconciliation_state, notes
  ) VALUES (
    v_product.id, v_product.name, v_product.gtin, v_product.sku,
    coalesce(v_product.stock, 0), round(p_counted_quantity, 3), v_diff,
    left(nullif(trim(coalesce(p_operator_label, '')), ''), 80),
    'mobile_balance', true,
    CASE WHEN v_diff = 0 THEN 'matched' ELSE 'pending_erp_reconciliation' END,
    'Contagem física aplicada ao estoque no Supabase; autoridade atual de vendas mantida.'
  ) RETURNING id INTO v_count_id;

  RETURN jsonb_build_object(
    'ok', true,
    'count', jsonb_build_object(
      'count_id', v_count_id,
      'product_id', v_product.id,
      'previous_stock', coalesce(v_product.stock, 0),
      'counted_stock', round(p_counted_quantity, 3),
      'difference', v_diff,
      'local_stock_applied', true,
      'validity_date', p_validity_date,
      'gondola', v_gondola
    ),
    'product', jsonb_build_object(
      'id', v_product.id,
      'stock', round(p_counted_quantity, 3),
      'validity_date', p_validity_date,
      'gondola', v_gondola
    )
  );
END;
$function$
;

-- function: ops_record_delivery_payment_v1(p_order_id uuid, p_parts jsonb, p_operator_label text, p_idempotency_key text)
CREATE OR REPLACE FUNCTION public.ops_record_delivery_payment_v1(p_order_id uuid, p_parts jsonb, p_operator_label text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_order public.orders%rowtype;
  v_existing public.order_payment_settlements%rowtype;
  v_existing_parts jsonb;
  v_normalized jsonb:='[]'::jsonb;
  v_item jsonb;
  v_method text;
  v_amount bigint;
  v_total bigint:=0;
  v_expected bigint;
  v_seq integer:=0;
  v_settlement_id uuid;
  v_key text;
  v_shadow jsonb;
begin
  if p_order_id is null then raise exception 'invalid_order'; end if;
  if jsonb_typeof(p_parts)<>'array' or jsonb_array_length(p_parts)<1 or jsonb_array_length(p_parts)>8 then
    raise exception 'invalid_payment_parts';
  end if;

  select * into v_order
  from public.orders
  where id=p_order_id
  for update;

  if not found then raise exception 'order_not_found'; end if;
  if v_order.status not in ('out_for_delivery','delivered') then
    raise exception 'order_not_in_delivery';
  end if;

  v_expected:=round(coalesce(v_order.total,0)*100)::bigint;
  if v_expected<=0 then raise exception 'invalid_order_total'; end if;

  for v_item in select value from jsonb_array_elements(p_parts) loop
    v_seq:=v_seq+1;
    v_method:=lower(trim(coalesce(v_item->>'method','')));
    begin
      v_amount:=(v_item->>'amount_cents')::bigint;
    exception when others then
      raise exception 'invalid_payment_amount';
    end;

    if v_method not in ('pix','cash','credit_card','food_card','meal_card','other') then
      raise exception 'invalid_payment_method';
    end if;
    if v_amount is null or v_amount<=0 then raise exception 'invalid_payment_amount'; end if;

    v_total:=v_total+v_amount;
    v_normalized:=v_normalized||jsonb_build_array(jsonb_build_object(
      'sequence',v_seq,
      'method',v_method,
      'amount_cents',v_amount
    ));
  end loop;

  if v_total<>v_expected then
    raise exception 'payment_total_mismatch';
  end if;

  select * into v_existing
  from public.order_payment_settlements
  where order_id=p_order_id;

  if found then
    select coalesce(
      jsonb_agg(jsonb_build_object(
        'sequence',sequence,
        'method',method,
        'amount_cents',amount_cents
      ) order by sequence),
      '[]'::jsonb
    )
    into v_existing_parts
    from public.order_payment_parts
    where settlement_id=v_existing.id;

    if v_existing.status in ('captured','synced','needs_review')
       and v_existing.captured_total_cents=v_total
       and v_existing_parts=v_normalized then
      begin
        v_shadow:=public.ops_prepare_delivery_payment_bling_shadow_v1(v_existing.id);
      exception when others then
        v_shadow:=jsonb_build_object('ok',false,'shadow_only',true,'external_write',false,'error','shadow_prepare_failed','detail',sqlerrm);
      end;
      return jsonb_build_object(
        'settlement_id',v_existing.id,
        'order_id',p_order_id,
        'expected_total_cents',v_expected,
        'captured_total_cents',v_total,
        'parts',v_existing_parts,
        'status',v_existing.status,
        'bling_sync_state',v_existing.bling_sync_state,
        'already_captured',true,
        'bling_shadow',v_shadow
      );
    end if;

    raise exception 'payment_already_captured';
  end if;

  v_key:=coalesce(
    nullif(trim(coalesce(p_idempotency_key,'')),''),
    'delivery-payment:'||p_order_id::text
  );

  insert into public.order_payment_settlements(
    order_id,status,expected_total_cents,captured_total_cents,planned_method,
    operator_label,source,bling_sync_state,idempotency_key,metadata
  ) values (
    p_order_id,'captured',v_expected,v_total,v_order.payment_method,
    left(nullif(trim(coalesce(p_operator_label,'')),''),80),
    'delivery','blocked_homologation',v_key,
    jsonb_build_object(
      'captured_order_status',v_order.status,
      'fiscal_runtime_dependency','pending_homologation'
    )
  )
  returning id into v_settlement_id;

  for v_item in select value from jsonb_array_elements(v_normalized) loop
    insert into public.order_payment_parts(
      settlement_id,sequence,method,amount_cents,detail
    ) values (
      v_settlement_id,
      (v_item->>'sequence')::integer,
      v_item->>'method',
      (v_item->>'amount_cents')::bigint,
      '{}'::jsonb
    );
  end loop;

  perform public.ops_record_event_v1(
    'finance','payment.delivery_captured',
    'Pagamento efetivo da entrega registrado.',
    'human','order',p_order_id::text,p_order_id::text,
    null,left(nullif(trim(coalesce(p_operator_label,'')),''),80),
    'dona_antonia','info',
    jsonb_build_object(
      'settlement_id',v_settlement_id,
      'planned_method',v_order.payment_method,
      'expected_total_cents',v_expected,
      'captured_total_cents',v_total,
      'parts',v_normalized,
      'bling_sync_state','blocked_homologation'
    ),
    null,'payment-delivery:'||v_settlement_id::text,now()
  );

  begin
    v_shadow:=public.ops_prepare_delivery_payment_bling_shadow_v1(v_settlement_id);
  exception when others then
    v_shadow:=jsonb_build_object('ok',false,'shadow_only',true,'external_write',false,'error','shadow_prepare_failed','detail',sqlerrm);
  end;

  return jsonb_build_object(
    'settlement_id',v_settlement_id,
    'order_id',p_order_id,
    'expected_total_cents',v_expected,
    'captured_total_cents',v_total,
    'parts',v_normalized,
    'status','captured',
    'bling_sync_state','blocked_homologation',
    'already_captured',false,
    'bling_shadow',v_shadow
  );
end;
$function$
;

-- function: ops_record_event_v1(p_domain text, p_event_type text, p_summary text, p_actor_type text, p_entity_type text, p_entity_id text, p_correlation_id text, p_actor_id text, p_actor_label text, p_source_system text, p_severity text, p_payload jsonb, p_external_ref text, p_idempotency_key text, p_occurred_at timestamp with time zone)
CREATE OR REPLACE FUNCTION public.ops_record_event_v1(p_domain text, p_event_type text, p_summary text, p_actor_type text DEFAULT 'system'::text, p_entity_type text DEFAULT NULL::text, p_entity_id text DEFAULT NULL::text, p_correlation_id text DEFAULT NULL::text, p_actor_id text DEFAULT NULL::text, p_actor_label text DEFAULT NULL::text, p_source_system text DEFAULT 'dona_antonia'::text, p_severity text DEFAULT 'info'::text, p_payload jsonb DEFAULT '{}'::jsonb, p_external_ref text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_occurred_at timestamp with time zone DEFAULT now())
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
begin
  if p_idempotency_key is not null then
    select id into v_id
    from public.ops_events
    where idempotency_key=p_idempotency_key
    limit 1;
    if v_id is not null then return v_id; end if;
  end if;

  insert into public.ops_events(
    occurred_at,domain,event_type,entity_type,entity_id,correlation_id,
    actor_type,actor_id,actor_label,source_system,severity,summary,payload,
    external_ref,idempotency_key
  ) values (
    coalesce(p_occurred_at,now()),p_domain,p_event_type,p_entity_type,p_entity_id,p_correlation_id,
    p_actor_type,p_actor_id,p_actor_label,p_source_system,p_severity,p_summary,coalesce(p_payload,'{}'::jsonb),
    p_external_ref,p_idempotency_key
  )
  returning id into v_id;

  return v_id;
exception when unique_violation then
  select id into v_id from public.ops_events where idempotency_key=p_idempotency_key limit 1;
  return v_id;
end;
$function$
;

-- function: ops_record_inventory_count_v1(p_product_id uuid, p_counted_quantity numeric, p_operator_label text)
CREATE OR REPLACE FUNCTION public.ops_record_inventory_count_v1(p_product_id uuid, p_counted_quantity numeric, p_operator_label text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_product public.products%rowtype; v_diff numeric(14,3); v_state text; v_count_id uuid; v_authority text;
begin
 if p_counted_quantity is null or p_counted_quantity<0 then raise exception 'invalid_quantity'; end if;
 select * into v_product from public.products where id=p_product_id for update;
 if not found then raise exception 'product_not_found'; end if;
 select coalesce(metadata->>'ops2_stock_authority','legacy_shadow') into v_authority from public.bling_hub_runtime_v2 where id=1;
 v_diff:=round(p_counted_quantity-coalesce(v_product.stock,0),3);
 v_state:=case when v_authority='bling' then 'pending_erp_reconciliation' when v_diff=0 then 'matched' else 'pending_erp_reconciliation' end;
 if v_authority<>'bling' then
  update public.products set stock=round(p_counted_quantity,3),last_counted_at=now(),physically_verified=true,updated_at=now() where id=p_product_id;
 else
  update public.products set last_counted_at=now(),physically_verified=true,updated_at=now() where id=p_product_id;
 end if;
 insert into public.ops_inventory_counts(product_id,product_name_snapshot,gtin_snapshot,sku_snapshot,system_quantity_before,counted_quantity,difference,operator_label,reconciliation_state)
 values(v_product.id,v_product.name,v_product.gtin,v_product.sku,coalesce(v_product.stock,0),round(p_counted_quantity,3),v_diff,left(nullif(trim(coalesce(p_operator_label,'')),''),80),v_state) returning id into v_count_id;
 perform public.ops_record_event_v1('inventory','inventory.count_recorded',case when v_diff=0 then 'Contagem física conferida sem diferença.' else 'Contagem física registrou diferença de estoque.' end,'human','product',v_product.id::text,v_product.id::text,null,left(nullif(trim(coalesce(p_operator_label,'')),''),80),'dona_antonia',case when v_diff=0 then 'info' else 'warning' end,jsonb_build_object('count_id',v_count_id,'system_before',coalesce(v_product.stock,0),'counted',round(p_counted_quantity,3),'difference',v_diff,'stock_authority',v_authority,'local_stock_applied',v_authority<>'bling','erp_reconciliation',v_state),null,'inventory-count:'||v_count_id::text,now());
 if v_diff<>0 then perform public.ops_open_attention_v1('inventory_count_difference','Balanço encontrou diferença em '||v_product.name||'.','product',v_product.id::text,v_product.id::text,'normal','supervisor','Revisar a causa da diferença antes da regularização definitiva no Bling/fiscal.',jsonb_build_object('count_id',v_count_id,'system_before',coalesce(v_product.stock,0),'counted',round(p_counted_quantity,3),'difference',v_diff,'stock_authority',v_authority,'local_stock_applied',v_authority<>'bling'),'dona_antonia','inventory-count-difference:'||v_count_id::text,null); end if;
 return jsonb_build_object('count_id',v_count_id,'product_id',v_product.id,'previous_stock',coalesce(v_product.stock,0),'counted_stock',round(p_counted_quantity,3),'difference',v_diff,'stock_authority',v_authority,'local_stock_applied',v_authority<>'bling','reconciliation_state',v_state);
end $function$
;

-- function: ops_record_inventory_incident_v1(p_product_id uuid, p_incident_type text, p_quantity numeric, p_operator_label text, p_note text, p_source_order_id uuid)
CREATE OR REPLACE FUNCTION public.ops_record_inventory_incident_v1(p_product_id uuid, p_incident_type text, p_quantity numeric, p_operator_label text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_source_order_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_product public.products%rowtype; v_type text:=lower(trim(coalesce(p_incident_type,''))); v_before numeric(14,3); v_delta numeric(14,3):=0; v_after numeric(14,3); v_apply boolean:=false; v_incident_id uuid; v_priority text:='normal'; v_authority text;
begin
 if v_type not in ('damage','expired','loss','return','other') then raise exception 'invalid_incident_type'; end if;
 if p_quantity is null or p_quantity<=0 then raise exception 'invalid_quantity'; end if;
 select * into v_product from public.products where id=p_product_id for update; if not found then raise exception 'product_not_found'; end if;
 select coalesce(metadata->>'ops2_stock_authority','legacy_shadow') into v_authority from public.bling_hub_runtime_v2 where id=1;
 v_before:=coalesce(v_product.stock,0);
 v_apply:=v_authority<>'bling' and v_type in ('damage','expired','loss');
 if v_apply then v_delta:=-least(round(p_quantity,3),v_before); v_after:=greatest(v_before+v_delta,0); update public.products set stock=v_after,updated_at=now() where id=v_product.id; if p_quantity>v_before then v_priority:='high'; end if; else v_after:=v_before; end if;
 insert into public.ops_inventory_incidents(incident_type,status,product_id,product_name_snapshot,gtin_snapshot,sku_snapshot,quantity,local_stock_before,local_stock_delta,local_stock_after,local_stock_applied,needs_bling_reconciliation,source_order_id,operator_label,note,evidence)
 values(v_type,'open',v_product.id,v_product.name,v_product.gtin,v_product.sku,round(p_quantity,3),v_before,v_delta,v_after,v_apply,true,p_source_order_id,left(nullif(trim(coalesce(p_operator_label,'')),''),80),left(nullif(trim(coalesce(p_note,'')),''),500),jsonb_build_object('target','bling_quarantine_or_fiscal_reconciliation','transition_mode',v_authority<>'bling','stock_authority',v_authority,'requested_quantity',round(p_quantity,3),'available_local_stock_before',v_before)) returning id into v_incident_id;
 perform public.ops_record_event_v1('inventory','inventory.incident_recorded',case v_type when 'damage' then 'Avaria registrada.' when 'expired' then 'Produto vencido registrado.' when 'loss' then 'Perda/extravio registrado.' when 'return' then 'Retorno físico registrado para inspeção.' else 'Ocorrência de estoque registrada.' end,'human','product',v_product.id::text,v_product.id::text,null,left(nullif(trim(coalesce(p_operator_label,'')),''),80),'dona_antonia',case when v_priority='high' then 'warning' else 'info' end,jsonb_build_object('incident_id',v_incident_id,'incident_type',v_type,'quantity',round(p_quantity,3),'stock_authority',v_authority,'local_stock_before',v_before,'local_stock_delta',v_delta,'local_stock_after',v_after,'local_stock_applied',v_apply,'needs_bling_reconciliation',true),null,'inventory-incident:'||v_incident_id::text,now());
 perform public.ops_open_attention_v1('inventory_incident',case v_type when 'damage' then 'Avaria aguardando destino/reconciliação: '||v_product.name when 'expired' then 'Produto vencido aguardando descarte/reconciliação: '||v_product.name when 'loss' then 'Perda/extravio aguardando regularização: '||v_product.name when 'return' then 'Produto retornado aguardando inspeção: '||v_product.name else 'Ocorrência de estoque aguardando revisão: '||v_product.name end,'inventory_incident',v_incident_id::text,v_product.id::text,v_priority,'supervisor',case when v_type='return' then 'Inspecionar e decidir: voltar ao Geral, devolver fornecedor ou descartar.' else 'Revisar destino físico e conciliar no Bling/fiscal conforme a causa.' end,jsonb_build_object('incident_id',v_incident_id,'product_id',v_product.id,'incident_type',v_type,'quantity',round(p_quantity,3),'stock_authority',v_authority,'local_stock_applied',v_apply,'local_stock_delta',v_delta),'dona_antonia','inventory-incident:'||v_incident_id::text,null);
 return jsonb_build_object('incident_id',v_incident_id,'product_id',v_product.id,'incident_type',v_type,'quantity',round(p_quantity,3),'stock_authority',v_authority,'local_stock_before',v_before,'local_stock_delta',v_delta,'local_stock_after',v_after,'local_stock_applied',v_apply,'needs_bling_reconciliation',true);
end $function$
;

-- function: ops_register_failed_delivery_v1(p_order_id uuid, p_reason_code text, p_note text, p_operator_label text)
CREATE OR REPLACE FUNCTION public.ops_register_failed_delivery_v1(p_order_id uuid, p_reason_code text, p_note text DEFAULT NULL::text, p_operator_label text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_order public.orders%rowtype;
  v_code text:=lower(trim(coalesce(p_reason_code,'')));
  v_label text;
  v_recommended text;
  v_attempt integer;
  v_case_id uuid;
  v_existing uuid;
  v_payment_count integer;
begin
  select * into v_order
  from public.orders
  where id=p_order_id
  for update;

  if not found then raise exception 'order_not_found'; end if;
  if v_order.status<>'out_for_delivery' then raise exception 'order_not_in_delivery'; end if;

  select count(*) into v_payment_count
  from public.order_payment_settlements
  where order_id=p_order_id and status in ('captured','synced','needs_review');

  if v_payment_count>0 then
    raise exception 'payment_already_captured';
  end if;

  select id into v_existing
  from public.order_delivery_return_cases
  where order_id=p_order_id
    and status in ('returning','returned_review')
  limit 1;

  if v_existing is not null then
    return jsonb_build_object(
      'case_id',v_existing,
      'order_id',p_order_id,
      'already_open',true
    );
  end if;

  v_label:=case v_code
    when 'customer_absent' then 'Cliente ausente'
    when 'address_not_found' then 'Endereço não encontrado'
    when 'reschedule' then 'Cliente pediu reagendamento'
    when 'payment_failed' then 'Problema no pagamento'
    when 'customer_refused' then 'Cliente recusou/desistiu'
    when 'vehicle_route' then 'Veículo / rota'
    when 'other' then 'Outro'
    else null
  end;

  if v_label is null then raise exception 'invalid_delivery_failure_reason'; end if;

  v_recommended:=case
    when v_code in ('payment_failed','customer_refused','other') then 'review'
    else 'redelivery'
  end;

  select coalesce(max(attempt_number),0)+1 into v_attempt
  from public.order_delivery_return_cases
  where order_id=p_order_id;

  insert into public.order_delivery_return_cases(
    order_id,attempt_number,reason_code,reason_label,note,status,
    recommended_disposition,failed_by,idempotency_key,metadata
  ) values (
    p_order_id,v_attempt,v_code,v_label,
    left(nullif(trim(coalesce(p_note,'')),''),500),
    'returning',v_recommended,
    left(nullif(trim(coalesce(p_operator_label,'')),''),80),
    'delivery-return:'||p_order_id::text||':'||v_attempt::text,
    jsonb_build_object(
      'stock_already_consumed',true,
      'return_stock_to_general_automatically',false
    )
  )
  returning id into v_case_id;

  perform public.ops_record_event_v1(
    'delivery','delivery.failed',
    'Entrega não concluída: '||v_label||'.',
    'human','order',p_order_id::text,p_order_id::text,
    null,left(nullif(trim(coalesce(p_operator_label,'')),''),80),
    'dona_antonia','warning',
    jsonb_build_object(
      'case_id',v_case_id,
      'attempt_number',v_attempt,
      'reason_code',v_code,
      'recommended_disposition',v_recommended,
      'stock_stays_consumed',true
    ),
    null,'delivery-failed:'||v_case_id::text,now()
  );

  return jsonb_build_object(
    'case_id',v_case_id,
    'order_id',p_order_id,
    'attempt_number',v_attempt,
    'reason_code',v_code,
    'reason_label',v_label,
    'status','returning',
    'recommended_disposition',v_recommended,
    'already_open',false
  );
end;
$function$
;

-- function: ops_request_approval_v1(p_action_type text, p_summary text, p_risk text, p_entity_type text, p_entity_id text, p_correlation_id text, p_requested_by_type text, p_requested_by_id text, p_requested_by_label text, p_proposed_action jsonb, p_evidence jsonb, p_idempotency_key text, p_expires_at timestamp with time zone)
CREATE OR REPLACE FUNCTION public.ops_request_approval_v1(p_action_type text, p_summary text, p_risk text DEFAULT 'medium'::text, p_entity_type text DEFAULT NULL::text, p_entity_id text DEFAULT NULL::text, p_correlation_id text DEFAULT NULL::text, p_requested_by_type text DEFAULT 'automation'::text, p_requested_by_id text DEFAULT NULL::text, p_requested_by_label text DEFAULT NULL::text, p_proposed_action jsonb DEFAULT '{}'::jsonb, p_evidence jsonb DEFAULT '{}'::jsonb, p_idempotency_key text DEFAULT NULL::text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
begin
  if p_idempotency_key is not null then
    select id into v_id
    from public.ops_approvals
    where idempotency_key=p_idempotency_key
    limit 1;
    if v_id is not null then return v_id; end if;
  end if;

  insert into public.ops_approvals(
    status,risk,action_type,entity_type,entity_id,correlation_id,
    requested_by_type,requested_by_id,requested_by_label,summary,
    proposed_action,evidence,idempotency_key,expires_at
  ) values (
    'pending',p_risk,p_action_type,p_entity_type,p_entity_id,p_correlation_id,
    p_requested_by_type,p_requested_by_id,p_requested_by_label,p_summary,
    coalesce(p_proposed_action,'{}'::jsonb),coalesce(p_evidence,'{}'::jsonb),p_idempotency_key,p_expires_at
  )
  returning id into v_id;

  return v_id;
exception when unique_violation then
  select id into v_id from public.ops_approvals where idempotency_key=p_idempotency_key limit 1;
  return v_id;
end;
$function$
;

-- function: ops_resolve_attention_v1(p_attention_id uuid, p_resolution text, p_resolution_ref text)
CREATE OR REPLACE FUNCTION public.ops_resolve_attention_v1(p_attention_id uuid, p_resolution text, p_resolution_ref text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.ops_attention
  set status='resolved',
      updated_at=now(),
      resolved_at=now(),
      resolution=p_resolution,
      resolution_ref=p_resolution_ref
  where id=p_attention_id
    and status in ('open','acknowledged');

  return found;
end;
$function$
;

-- function: ops_resolve_delivery_return_review_v1(p_case_id uuid, p_action text, p_operator_label text)
CREATE OR REPLACE FUNCTION public.ops_resolve_delivery_return_review_v1(p_case_id uuid, p_action text, p_operator_label text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_case public.order_delivery_return_cases%rowtype;
  v_order public.orders%rowtype;
  v_action text:=lower(trim(coalesce(p_action,'')));
  v_payment_count integer;
  v_release jsonb;
  v_attention uuid;
  v_fiscal_attention uuid;
  v_authority text;
  v_physical_state text;
  v_bling_reversed boolean:=false;
begin
  if v_action not in ('redelivery','cancel_intact') then
    raise exception 'invalid_return_review_action';
  end if;

  select * into v_case
  from public.order_delivery_return_cases
  where id=p_case_id
  for update;

  if not found then raise exception 'delivery_return_case_not_found'; end if;
  if v_case.status<>'returned_review' then raise exception 'delivery_return_not_in_review'; end if;

  select * into v_order
  from public.orders
  where id=v_case.order_id
  for update;

  if not found then raise exception 'order_not_found'; end if;
  if v_order.status<>'ready' then raise exception 'order_not_ready_for_return_resolution'; end if;

  select count(*) into v_payment_count
  from public.order_payment_settlements
  where order_id=v_case.order_id
    and status in ('captured','synced','needs_review');

  if v_payment_count>0 then raise exception 'return_has_captured_payment'; end if;

  if v_action='redelivery' then
    update public.order_delivery_return_cases
       set status='closed',final_disposition='redelivery',closed_at=now(),
           returned_by=coalesce(returned_by,left(nullif(trim(coalesce(p_operator_label,'')),''),80)),
           resolution='Retorno revisado e liberado para nova tentativa de entrega.'
     where id=v_case.id;

    select id into v_attention from public.ops_attention
     where idempotency_key='delivery-return-review:'||v_case.id::text
       and status in ('open','acknowledged') limit 1;

    if v_attention is not null then
      perform public.ops_resolve_attention_v1(v_attention,'Mercadoria revisada e liberada para reentrega.','delivery-return:'||v_case.id::text);
    end if;

    perform public.ops_record_event_v1(
      'delivery','delivery.return_review_resolved_redelivery','Retorno revisado e liberado para reentrega.',
      'human','order',v_case.order_id::text,v_case.order_id::text,null,
      left(nullif(trim(coalesce(p_operator_label,'')),''),80),'dona_antonia','info',
      jsonb_build_object('case_id',v_case.id,'stock_restored',false,'order_status','ready','stock_reversal_required',false),
      null,'delivery-return-review-redelivery:'||v_case.id::text,now()
    );

    return jsonb_build_object('case_id',v_case.id,'order_id',v_case.order_id,'action','redelivery','order_status','ready','stock_restored',false);
  end if;

  select coalesce(metadata->>'ops2_stock_authority','legacy_shadow')
    into v_authority
    from public.bling_hub_runtime_v2 where id=1;

  if coalesce(v_authority,'legacy_shadow')='bling' then
    select state into v_physical_state
      from public.bling_order_stock_controls_v2
     where source_order_id=v_case.order_id
     for update;

    if coalesce(v_physical_state,'')<>'reversed' then
      raise exception 'bling_physical_stock_reverse_required_before_cancel';
    end if;
    v_bling_reversed:=true;
  end if;

  v_release:=public.release_vitrine_order_stock_v1(v_case.order_id);
  if coalesce((v_release->>'ok')::boolean,false) is not true then raise exception 'stock_restore_failed'; end if;

  update public.orders
     set status='cancelled',cancelled_at=coalesce(cancelled_at,now()),updated_at=now()
   where id=v_case.order_id;

  update public.order_delivery_return_cases
     set status='closed',final_disposition='cancelled',closed_at=now(),
         resolution=case when v_bling_reversed
           then 'Cliente desistiu/recusou; mercadoria retornou íntegra e baixa física foi estornada no Bling.'
           else 'Cliente desistiu/recusou; mercadoria retornou íntegra e estoque local foi restaurado.' end
   where id=v_case.id;

  select id into v_attention from public.ops_attention
   where idempotency_key='delivery-return-review:'||v_case.id::text
     and status in ('open','acknowledged') limit 1;

  if v_attention is not null then
    perform public.ops_resolve_attention_v1(
      v_attention,
      case when v_bling_reversed then 'Retorno íntegro confirmado; baixa física estornada no Bling e pedido cancelado comercialmente.'
           else 'Retorno íntegro confirmado; pedido cancelado comercialmente e estoque local restaurado.' end,
      'delivery-return:'||v_case.id::text
    );
  end if;

  v_fiscal_attention:=public.ops_open_attention_v1(
    'delivery_return_fiscal_review','Pedido cancelado após sair para entrega: revisar retorno fiscal no Bling.',
    'order',v_case.order_id::text,v_case.order_id::text,'high','owner',
    'Verificar se houve NF-e autorizada. Se houve, tratar retorno/devolução fiscal; não apagar a venda original.',
    jsonb_build_object(
      'case_id',v_case.id,'reason_code',v_case.reason_code,
      'stock_authority',v_authority,'bling_physical_stock_reversed',v_bling_reversed,
      'stock_restored_local',coalesce((v_release->>'restored_physical_stock')::boolean,false),
      'automatic_fiscal_action',false
    ),
    'dona_antonia','delivery-return-fiscal-review:'||v_case.id::text,null
  );

  perform public.ops_record_event_v1(
    'delivery','delivery.return_review_cancelled_intact',
    case when v_bling_reversed then 'Retorno íntegro confirmado; baixa física Bling estornada e pedido cancelado.'
         else 'Retorno íntegro confirmado; pedido cancelado e estoque local restaurado.' end,
    'human','order',v_case.order_id::text,v_case.order_id::text,null,
    left(nullif(trim(coalesce(p_operator_label,'')),''),80),'dona_antonia','warning',
    jsonb_build_object(
      'case_id',v_case.id,'stock_release',v_release,'bling_physical_stock_reversed',v_bling_reversed,
      'fiscal_attention_id',v_fiscal_attention,'automatic_fiscal_action',false
    ),
    null,'delivery-return-cancel-intact:'||v_case.id::text,now()
  );

  return jsonb_build_object(
    'case_id',v_case.id,'order_id',v_case.order_id,'action','cancel_intact','order_status','cancelled',
    'stock_restored',(v_bling_reversed or coalesce((v_release->>'restored_physical_stock')::boolean,false)),
    'bling_physical_stock_reversed',v_bling_reversed,
    'fiscal_review_required',true,'fiscal_attention_id',v_fiscal_attention
  );
end;
$function$
;

-- function: ops_scan_order_check_v1(p_session_id uuid, p_gtin text, p_quantity numeric)
CREATE OR REPLACE FUNCTION public.ops_scan_order_check_v1(p_session_id uuid, p_gtin text, p_quantity numeric DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare s public.ops_order_check_sessions%rowtype; g text; cnt int; it public.ops_order_check_items%rowtype; nq numeric;
begin
 if p_quantity is null or p_quantity<=0 then raise exception 'invalid_quantity'; end if; g:=regexp_replace(coalesce(p_gtin,''),'[^0-9]','','g'); if g='' then raise exception 'invalid_ean'; end if;
 select * into s from public.ops_order_check_sessions where id=p_session_id for update; if not found or s.status<>'open' then raise exception 'check_session_not_open'; end if;
 select count(*) into cnt from public.ops_order_check_items where session_id=s.id and gtin=g; if cnt=0 then raise exception 'ean_not_in_order'; elsif cnt>1 then raise exception 'duplicate_ean_in_order'; end if;
 select * into it from public.ops_order_check_items where session_id=s.id and gtin=g for update; nq:=it.checked_quantity+p_quantity;
 if nq>it.expected_quantity then raise exception 'checked_quantity_exceeds_expected'; end if;
 update public.ops_order_check_items set checked_quantity=nq,updated_at=now() where id=it.id;
 return jsonb_build_object('ok',true,'product_id',it.product_id,'name',it.name_snapshot,'checked_quantity',nq,'expected_quantity',it.expected_quantity,'complete',nq=it.expected_quantity);
end $function$
;

-- function: ops_start_order_check_v1(p_order_id uuid, p_operator_label text)
CREATE OR REPLACE FUNCTION public.ops_start_order_check_v1(p_order_id uuid, p_operator_label text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare o public.orders%rowtype; sid uuid;
begin
 select * into o from public.orders where id=p_order_id for update; if not found then raise exception 'order_not_found'; end if;
 if o.status<>'processing' then raise exception 'order_not_in_separation'; end if;
 select id into sid from public.ops_order_check_sessions where order_id=p_order_id and status='open' limit 1;
 if sid is null then
  insert into public.ops_order_check_sessions(order_id,operator_label) values(p_order_id,left(nullif(trim(coalesce(p_operator_label,'')),''),80)) returning id into sid;
  insert into public.ops_order_check_items(session_id,product_id,gtin,name_snapshot,expected_quantity)
  select sid,oi.product_id,max(nullif(regexp_replace(coalesce(p.gtin,''),'[^0-9]','','g'),'')),max(oi.name_snapshot),sum(oi.quantity)
  from public.order_items oi join public.products p on p.id=oi.product_id where oi.order_id=p_order_id and oi.product_id is not null group by oi.product_id;
 end if;
 return jsonb_build_object('session_id',sid,'order_id',p_order_id,'status','open');
end $function$
;

-- function: ops_sync_delivery_payment_fiscal_trigger_v1()
CREATE OR REPLACE FUNCTION public.ops_sync_delivery_payment_fiscal_trigger_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.source='delivery'
     and new.status in ('captured','synced','needs_review')
     and (
       tg_op='INSERT'
       or old.status is distinct from new.status
       or old.captured_total_cents is distinct from new.captured_total_cents
     ) then
    perform public.ops_sync_delivery_payment_fiscal_v1(new.id);
  end if;
  return new;
end;
$function$
;

-- function: ops_sync_delivery_payment_fiscal_v1(p_settlement_id uuid)
CREATE OR REPLACE FUNCTION public.ops_sync_delivery_payment_fiscal_v1(p_settlement_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  s public.order_payment_settlements%rowtype;
  v_method text;
  v_method_count integer:=0;
  v_readiness jsonb;
begin
  select * into s
  from public.order_payment_settlements
  where id=p_settlement_id;

  if not found then
    return jsonb_build_object('ok',false,'error','settlement_not_found','external_side_effect',false);
  end if;

  if s.source<>'delivery' or s.status not in ('captured','synced','needs_review') then
    return jsonb_build_object('ok',true,'synced',false,'reason','settlement_not_eligible','external_side_effect',false);
  end if;

  if s.expected_total_cents is null
     or s.captured_total_cents is null
     or s.expected_total_cents<>s.captured_total_cents then
    insert into public.order_fiscal_controls(order_id,payment_status,payment_source,updated_at)
    values(s.order_id,'review_required','delivery_settlement',now())
    on conflict(order_id) do update
      set payment_status='review_required',
          payment_source='delivery_settlement',
          updated_at=now();

    v_readiness:=public.refresh_order_fiscal_readiness_v1(s.order_id);
    return jsonb_build_object(
      'ok',true,'synced',true,'payment_status','review_required',
      'reason','settlement_total_mismatch','readiness',v_readiness,
      'external_side_effect',false
    );
  end if;

  select count(distinct method),
         case when count(distinct method)=1 then max(method) else 'split' end
    into v_method_count,v_method
  from public.order_payment_parts
  where settlement_id=s.id;

  if coalesce(v_method_count,0)=0 then
    insert into public.order_fiscal_controls(order_id,payment_status,payment_source,updated_at)
    values(s.order_id,'review_required','delivery_settlement',now())
    on conflict(order_id) do update
      set payment_status='review_required',
          payment_source='delivery_settlement',
          updated_at=now();

    v_readiness:=public.refresh_order_fiscal_readiness_v1(s.order_id);
    return jsonb_build_object(
      'ok',true,'synced',true,'payment_status','review_required',
      'reason','payment_parts_missing','readiness',v_readiness,
      'external_side_effect',false
    );
  end if;

  insert into public.order_fiscal_controls(
    order_id,payment_status,payment_method,payment_source,
    settled_amount,payment_confirmed_at,updated_at
  )
  values(
    s.order_id,'confirmed',v_method,'delivery_settlement',
    s.captured_total_cents::numeric/100,
    coalesce(s.captured_at,now()),now()
  )
  on conflict(order_id) do update
    set payment_status='confirmed',
        payment_method=excluded.payment_method,
        payment_source='delivery_settlement',
        settled_amount=excluded.settled_amount,
        payment_confirmed_at=coalesce(public.order_fiscal_controls.payment_confirmed_at,excluded.payment_confirmed_at),
        updated_at=now();

  v_readiness:=public.refresh_order_fiscal_readiness_v1(s.order_id);

  return jsonb_build_object(
    'ok',true,'synced',true,'payment_status','confirmed',
    'payment_method',v_method,
    'settled_amount_cents',s.captured_total_cents,
    'readiness',v_readiness,
    'external_side_effect',false
  );
end;
$function$
;

-- function: ops_sync_delivery_stop_from_order_trigger_v1()
CREATE OR REPLACE FUNCTION public.ops_sync_delivery_stop_from_order_trigger_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if old.status is distinct from new.status
     and new.status in ('out_for_delivery','delivered','ready','cancelled') then
    perform public.ops_sync_delivery_stop_v1(new.id,new.status);
  end if;
  return new;
end $function$
;

-- function: ops_sync_delivery_stop_v1(p_order_id uuid, p_order_status text)
CREATE OR REPLACE FUNCTION public.ops_sync_delivery_stop_v1(p_order_id uuid, p_order_status text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_status text;
  v_count integer;
begin
  v_status := case p_order_status
    when 'out_for_delivery' then 'out_for_delivery'
    when 'delivered' then 'delivered'
    when 'ready' then 'planned'
    when 'cancelled' then 'cancelled'
    else null
  end;
  if v_status is null then return 0; end if;

  update public.ops_delivery_stops s
     set status = v_status, updated_at = now()
   where s.order_id = p_order_id
     and s.status not in ('failed', 'cancelled', 'delivered')
     and exists (
       select 1 from public.ops_delivery_runs r
        where r.id = s.run_id and r.status in ('planned', 'dispatched')
     );
  get diagnostics v_count = row_count;

  if p_order_status = 'out_for_delivery' then
    update public.ops_delivery_runs r
       set status = 'dispatched',
           dispatched_at = coalesce(dispatched_at, now()),
           updated_at = now()
     where r.id in (
       select run_id from public.ops_delivery_stops
        where order_id = p_order_id and status = 'out_for_delivery'
     )
       and r.status = 'planned';
  end if;

  update public.ops_delivery_runs r
     set status = 'completed',
         completed_at = coalesce(completed_at, now()),
         updated_at = now()
   where r.status = 'dispatched'
     and not exists (
       select 1 from public.ops_delivery_stops s
        where s.run_id = r.id and s.status not in ('delivered', 'failed', 'cancelled')
     );

  return v_count;
end;
$function$
;

-- function: oscb_catalog_worker_authorized_v1(p_secret text)
CREATE OR REPLACE FUNCTION public.oscb_catalog_worker_authorized_v1(p_secret text)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(
    length(coalesce(p_secret,'')) >= 48
    and p_secret = (select decrypted_secret from vault.decrypted_secrets where name='oscb_catalog_worker_secret_v1' limit 1),
    false
  )
$function$
;

-- function: oscb_reserve_gtin_lookup_v1(p_gtin text, p_capture_id uuid, p_actor_id uuid, p_daily_limit integer)
CREATE OR REPLACE FUNCTION public.oscb_reserve_gtin_lookup_v1(p_gtin text, p_capture_id uuid, p_actor_id uuid, p_daily_limit integer DEFAULT 45)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_cache public.oscb_gtin_research_cache_v1%rowtype;
  v_used integer;
  v_limit integer := greatest(1, least(45, coalesce(p_daily_limit, 45)));
  v_attempt uuid;
begin
  if p_gtin !~ '^[0-9]{8,14}$' then
    return jsonb_build_object('allowed', false, 'reason', 'invalid_gtin');
  end if;
  perform pg_advisory_xact_lock(hashtextextended('oscb_gtin_quota', 0));
  select * into v_cache from public.oscb_gtin_research_cache_v1 where gtin = p_gtin for update;
  if found and v_cache.status in ('review', 'not_found') and v_cache.researched_at is not null then
    return jsonb_build_object('allowed', false, 'reason', 'cached', 'cache', to_jsonb(v_cache));
  end if;
  if found and v_cache.status = 'researching' and v_cache.attempted_at > now() - interval '3 minutes' then
    return jsonb_build_object('allowed', false, 'reason', 'in_progress');
  end if;
  if found and v_cache.status = 'error' and v_cache.attempted_at > now() - interval '5 minutes' then
    return jsonb_build_object('allowed', false, 'reason', 'retry_later');
  end if;
  select count(*) into v_used from public.oscb_gtin_research_attempts_v1
   where attempted_at >= (date_trunc('day', now() at time zone 'UTC') at time zone 'UTC');
  if v_used >= v_limit then
    return jsonb_build_object('allowed', false, 'reason', 'daily_limit', 'used', v_used, 'limit', v_limit);
  end if;
  if exists (select 1 from public.oscb_gtin_research_attempts_v1
      where attempted_at > now() - interval '30 seconds') then
    return jsonb_build_object('allowed', false, 'reason', 'rate_limit');
  end if;
  insert into public.oscb_gtin_research_attempts_v1(gtin, capture_id, actor_id)
  values (p_gtin, p_capture_id, p_actor_id) returning id into v_attempt;
  insert into public.oscb_gtin_research_cache_v1(gtin, status, proposal, response_summary, attempted_at, researched_by, updated_at)
  values (p_gtin, 'researching', '{}'::jsonb, jsonb_build_object('source','oscb'), now(), p_actor_id, now())
  on conflict (gtin) do update set status='researching', proposal='{}'::jsonb,
    response_summary=jsonb_build_object('source','oscb'), last_http_status=null, last_error=null,
    attempted_at=now(), researched_at=null, researched_by=p_actor_id, updated_at=now();
  return jsonb_build_object('allowed', true, 'attempt_id', v_attempt, 'used', v_used + 1, 'limit', v_limit);
end;
$function$
;

-- function: papoai_cancel_draft_v2(p_draft_id uuid, p_revision integer)
CREATE OR REPLACE FUNCTION public.papoai_cancel_draft_v2(p_draft_id uuid, p_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_row public.papoai_order_drafts_v2%rowtype;
begin
  select * into v_row from public.papoai_order_drafts_v2 where id=p_draft_id for update;
  if not found then raise exception 'draft_not_found'; end if;
  if v_row.status='cancelled' then
    return jsonb_build_object('ok',true,'duplicate',true,'draft_id',v_row.id,'revision',v_row.revision,'status','cancelled');
  end if;
  if v_row.status='confirmed' then raise exception 'confirmed_draft_cannot_cancel'; end if;
  if v_row.revision<>p_revision then raise exception 'draft_revision_mismatch'; end if;

  update public.papoai_order_drafts_v2
     set status='cancelled',cancelled_at=now(),updated_at=now()
   where id=p_draft_id
   returning * into v_row;

  return jsonb_build_object('ok',true,'duplicate',false,'draft_id',v_row.id,'revision',v_row.revision,'status','cancelled');
end;
$function$
;

-- function: papoai_confirm_draft_v2(p_draft_id uuid, p_revision integer, p_summary_hash text, p_confirmed_message_id text)
CREATE OR REPLACE FUNCTION public.papoai_confirm_draft_v2(p_draft_id uuid, p_revision integer, p_summary_hash text, p_confirmed_message_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row public.papoai_order_drafts_v2%rowtype;
  v_created jsonb;
  v_order_id uuid;
  v_commit_enabled boolean:=false;
begin
  select * into v_row from public.papoai_order_drafts_v2 where id=p_draft_id for update;
  if not found then raise exception 'draft_not_found'; end if;

  if v_row.status='confirmed' and v_row.canonical_order_id is not null then
    return jsonb_build_object(
      'ok',true,'duplicate',true,'draft_id',v_row.id,'revision',v_row.revision,
      'order_id',v_row.canonical_order_id,'status','confirmed'
    );
  end if;

  select structured_order_commit_enabled into v_commit_enabled
  from public.ops2_papoai_bridge_runtime_v1 where id=1;

  if coalesce(v_commit_enabled,false) is not true then
    return jsonb_build_object(
      'ok',false,'blocked',true,'error','papoai_structured_order_commit_not_homologated',
      'draft_id',v_row.id,'revision',v_row.revision,'status',v_row.status,
      'external_write',false
    );
  end if;

  if v_row.status<>'awaiting_confirmation' then raise exception 'draft_not_awaiting_confirmation'; end if;
  if v_row.expires_at<=now() then
    update public.papoai_order_drafts_v2 set status='expired',updated_at=now() where id=p_draft_id;
    raise exception 'draft_expired';
  end if;
  if v_row.revision<>p_revision then raise exception 'draft_revision_mismatch'; end if;
  if lower(coalesce(p_summary_hash,''))<>lower(coalesce(v_row.summary_hash,'')) then
    raise exception 'summary_hash_mismatch';
  end if;
  if v_row.quoted_total_cents is null then raise exception 'draft_quote_missing'; end if;

  v_created:=public.create_canonical_cart_order_v2(
    'papoai',v_row.phone_e164,v_row.payment_method,v_row.cart,v_row.customer_snapshot,v_row.delivery
  );
  v_order_id:=(v_created->>'order_id')::uuid;

  if coalesce((v_created->>'total_cents')::bigint,-1)<>v_row.quoted_total_cents then
    raise exception 'draft_quote_changed';
  end if;

  update public.orders
     set conversation_id=coalesce(conversation_id,(
           select c.id from public.conversations c
           where c.referral->>'papoai_session_uid'=v_row.conversation_ref
              or c.id::text=v_row.conversation_ref
           order by c.updated_at desc limit 1
         )),
         customer_id=coalesce(customer_id,v_row.customer_id),
         updated_at=now()
   where id=v_order_id;

  update public.papoai_order_drafts_v2
     set status='confirmed',canonical_order_id=v_order_id,
         confirmed_message_id=nullif(left(trim(coalesce(p_confirmed_message_id,'')),180),''),
         confirmed_at=now(),updated_at=now()
   where id=p_draft_id
   returning * into v_row;

  return v_created||jsonb_build_object(
    'ok',true,'duplicate',false,'draft_id',v_row.id,'revision',v_row.revision,
    'order_id',v_order_id,'status','confirmed'
  );
end;
$function$
;

-- function: papoai_ensure_conversation_v2(p_capture_id uuid)
CREATE OR REPLACE FUNCTION public.papoai_ensure_conversation_v2(p_capture_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row public.papoai_webhook_inbox_v2%rowtype;
  v_phone_e164 text;
  v_phone_digits text;
  v_business_phone text;
  v_occurred_at timestamptz;
  v_customer_id uuid;
  v_contact_id text;
  v_session_uid text;
  v_account_id uuid;
  v_account_count integer;
  v_conversation_id uuid;
  v_created boolean:=false;
begin
  select * into v_row
  from public.papoai_webhook_inbox_v2
  where id=p_capture_id
  for update;

  if not found then return jsonb_build_object('ok',false,'error','capture_not_found'); end if;
  if v_row.status not in ('normalized','processed') then
    return jsonb_build_object('ok',false,'error','capture_not_normalized','status',v_row.status);
  end if;
  if coalesce(v_row.event_name,'')<>'message.received' then
    return jsonb_build_object('ok',true,'skipped',true,'reason','not_inbound_message');
  end if;

  v_phone_e164:=public.canonical_whatsapp_e164_br_v2(v_row.phone_candidate);
  if v_phone_e164 is null then
    update public.papoai_webhook_inbox_v2
       set status='review_required',last_error='phone_missing_for_conversation'
     where id=p_capture_id;
    return jsonb_build_object('ok',false,'error','phone_missing_for_conversation');
  end if;
  v_phone_digits:=public.normalize_phone_digits(v_phone_e164);
  v_business_phone:=public.canonical_whatsapp_e164_br_v2(v_row.metadata->>'phone_to');

  begin
    v_occurred_at:=coalesce(nullif(v_row.metadata->>'occurred_at','')::timestamptz,v_row.received_at);
  exception when others then v_occurred_at:=v_row.received_at; end;

  begin
    v_customer_id:=nullif(v_row.metadata->>'customer_id','')::uuid;
  exception when others then v_customer_id:=null; end;

  if v_customer_id is null then
    select customer_id into v_customer_id
    from public.lookup_customer_by_phone(v_phone_e164)
    limit 1;
  end if;

  v_contact_id:=nullif(v_row.metadata->>'contact_id','');
  v_session_uid:=nullif(v_row.conversation_ref,'');

  select count(*),(array_agg(id order by updated_at desc))[1]
    into v_account_count,v_account_id
  from public.whatsapp_accounts
  where is_active=true
    and v_business_phone is not null
    and public.normalize_phone_digits(phone_e164)=public.normalize_phone_digits(v_business_phone);

  if v_account_count<>1 or v_account_id is null then
    update public.papoai_webhook_inbox_v2
       set status='review_required',
           last_error=case when v_business_phone is null then 'business_phone_missing'
                           else 'whatsapp_account_unresolved' end
     where id=p_capture_id;
    return jsonb_build_object(
      'ok',false,
      'error',case when v_business_phone is null then 'business_phone_missing' else 'whatsapp_account_unresolved' end,
      'business_phone',v_business_phone,'count',v_account_count
    );
  end if;

  perform pg_advisory_xact_lock(hashtextextended('whatsapp-conversation:'||v_account_id::text||':'||v_phone_e164,0));

  select c.id into v_conversation_id
  from public.conversations c
  where c.whatsapp_account_id=v_account_id
    and coalesce(public.canonical_whatsapp_e164_br_v2(c.wa_contact_e164),c.wa_contact_e164)=v_phone_e164
    and c.status<>'closed'
  order by c.updated_at desc
  limit 1
  for update;

  if v_conversation_id is null then
    insert into public.conversations(
      whatsapp_account_id,channel_account_id,customer_id,wa_contact_e164,source,status,stage,
      response_preference,human_required,referral,opened_at,last_inbound_at,
      service_window_expires_at,created_at,updated_at,mode,channel,external_user_id
    ) values (
      v_account_id,v_account_id,v_customer_id,v_phone_e164,'organic','open','new',
      'auto',false,
      jsonb_strip_nulls(jsonb_build_object(
        'source','papoai','papoai_session_uid',v_session_uid,
        'papoai_contact_id',v_contact_id,'business_phone_e164',v_business_phone
      )),
      v_occurred_at,v_occurred_at,v_occurred_at+interval '24 hours',
      now(),now(),'ai','whatsapp',v_phone_e164
    )
    returning id into v_conversation_id;
    v_created:=true;
  else
    update public.conversations
       set customer_id=coalesce(customer_id,v_customer_id),
           wa_contact_e164=v_phone_e164,
           channel_account_id=coalesce(channel_account_id,v_account_id),
           external_user_id=coalesce(external_user_id,v_phone_e164),
           last_inbound_at=greatest(coalesce(last_inbound_at,v_occurred_at),v_occurred_at),
           service_window_expires_at=greatest(
             coalesce(service_window_expires_at,v_occurred_at+interval '24 hours'),
             v_occurred_at+interval '24 hours'
           ),
           referral=coalesce(referral,'{}'::jsonb)
             || jsonb_strip_nulls(jsonb_build_object(
               'source','papoai','papoai_session_uid',v_session_uid,
               'papoai_contact_id',v_contact_id,'business_phone_e164',v_business_phone
             )),
           updated_at=now()
     where id=v_conversation_id;
  end if;

  update public.papoai_webhook_inbox_v2
     set phone_candidate=public.normalize_phone_digits(v_phone_e164),
         metadata=coalesce(metadata,'{}'::jsonb)
           || jsonb_build_object(
             'conversation_id',v_conversation_id,
             'conversation_created',v_created,
             'customer_id',v_customer_id,
             'conversation_bridge_version',3,
             'business_phone_e164',v_business_phone,
             'whatsapp_account_id',v_account_id,
             'canonical_phone_e164',v_phone_e164
           ),
         last_error=null
   where id=p_capture_id;

  return jsonb_build_object(
    'ok',true,'conversation_id',v_conversation_id,'created',v_created,
    'customer_id',v_customer_id,'phone_e164',v_phone_e164,
    'business_phone_e164',v_business_phone,'whatsapp_account_id',v_account_id
  );
end;
$function$
;

-- function: papoai_mark_draft_summary_v2(p_draft_id uuid, p_revision integer, p_summary_hash text, p_sent_message_id text, p_quoted_total_cents bigint)
CREATE OR REPLACE FUNCTION public.papoai_mark_draft_summary_v2(p_draft_id uuid, p_revision integer, p_summary_hash text, p_sent_message_id text, p_quoted_total_cents bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_row public.papoai_order_drafts_v2%rowtype;
begin
  select * into v_row from public.papoai_order_drafts_v2 where id=p_draft_id for update;
  if not found then raise exception 'draft_not_found'; end if;
  if v_row.status not in ('draft','awaiting_confirmation') then raise exception 'draft_not_editable'; end if;
  if v_row.expires_at<=now() then
    update public.papoai_order_drafts_v2 set status='expired',updated_at=now() where id=p_draft_id;
    raise exception 'draft_expired';
  end if;
  if v_row.revision<>p_revision then raise exception 'draft_revision_mismatch'; end if;
  if coalesce(p_summary_hash,'') !~ '^[0-9a-fA-F]{64}$' then raise exception 'invalid_summary_hash'; end if;
  if p_quoted_total_cents is null or p_quoted_total_cents<0 then raise exception 'invalid_quote_total'; end if;

  update public.papoai_order_drafts_v2
     set status='awaiting_confirmation',
         summary_hash=lower(p_summary_hash),
         sent_message_id=nullif(left(trim(coalesce(p_sent_message_id,'')),180),''),
         quoted_total_cents=p_quoted_total_cents,
         updated_at=now()
   where id=p_draft_id
   returning * into v_row;

  return jsonb_build_object(
    'ok',true,'draft_id',v_row.id,'revision',v_row.revision,'status',v_row.status,
    'quoted_total_cents',v_row.quoted_total_cents,'expires_at',v_row.expires_at
  );
end;
$function$
;

-- function: papoai_normalize_capture_v2(p_capture_id uuid)
CREATE OR REPLACE FUNCTION public.papoai_normalize_capture_v2(p_capture_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row public.papoai_webhook_inbox_v2%rowtype;
  v_payload jsonb;
  v_event_name text;
  v_message_id text;
  v_whatsapp_message_id text;
  v_conversation_ref text;
  v_direction text;
  v_message_type text;
  v_phone_from text;
  v_phone_to text;
  v_phone text;
  v_contact_id text;
  v_contact_name text;
  v_customer_id uuid;
  v_occurred_at text;
  v_metadata jsonb;
begin
  select * into v_row
  from public.papoai_webhook_inbox_v2
  where id=p_capture_id
  for update;

  if not found then
    return jsonb_build_object('ok',false,'error','capture_not_found');
  end if;

  if v_row.status in ('processed','ignored') then
    return jsonb_build_object('ok',true,'id',v_row.id,'status',v_row.status,'already_final',true);
  end if;

  v_payload:=coalesce(v_row.payload,'{}'::jsonb);

  v_event_name:=nullif(trim(coalesce(
    v_payload#>>'{event,type}',
    v_row.event_name,
    v_payload#>>'{event_name}'
  )),'');
  v_message_id:=nullif(trim(coalesce(
    v_payload#>>'{data,message,id}',
    v_row.external_message_id
  )),'');
  v_whatsapp_message_id:=nullif(trim(v_payload#>>'{data,message,external_id}'),'');
  v_conversation_ref:=nullif(trim(coalesce(
    v_payload#>>'{data,session,uid}',
    v_row.conversation_ref
  )),'');
  v_direction:=lower(nullif(trim(v_payload#>>'{data,message,direction}'),''));
  v_message_type:=lower(nullif(trim(v_payload#>>'{data,message,type}'),''));
  v_phone_from:=regexp_replace(coalesce(v_payload#>>'{data,message,phone_number_from}',''),'\D','','g');
  v_phone_to:=regexp_replace(coalesce(v_payload#>>'{data,message,phone_number_to}',''),'\D','','g');
  v_contact_id:=nullif(trim(v_payload#>>'{data,contact,id}'),'');
  v_contact_name:=nullif(trim(v_payload#>>'{data,contact,name}'),'');
  v_occurred_at:=nullif(trim(coalesce(
    v_payload#>>'{event,occurred_at}',
    v_payload#>>'{data,message,created_at}'
  )),'');
  v_phone:=case
    when v_direction='inbound' and length(v_phone_from)>=10 then v_phone_from
    when v_direction='outbound' and length(v_phone_to)>=10 then v_phone_to
    when length(v_phone_from)>=10 then v_phone_from
    when length(v_phone_to)>=10 then v_phone_to
    else null
  end;

  if v_phone is not null then
    select c.id into v_customer_id
    from public.customers c
    where regexp_replace(coalesce(c.primary_whatsapp_e164,''),'\D','','g')=v_phone
    limit 1;

    if v_customer_id is null then
      select cp.customer_id into v_customer_id
      from public.customer_phones cp
      where regexp_replace(coalesce(cp.phone_e164,''),'\D','','g')=v_phone
      order by cp.is_primary desc,cp.created_at asc
      limit 1;
    end if;
  end if;

  v_metadata:=coalesce(v_row.metadata,'{}'::jsonb)
    || jsonb_strip_nulls(jsonb_build_object(
      'source','papoai',
      'capture_only',true,
      'adapter_version',2,
      'direction',v_direction,
      'message_type',v_message_type,
      'whatsapp_message_id',v_whatsapp_message_id,
      'contact_id',v_contact_id,
      'contact_name',v_contact_name,
      'phone_from',nullif(v_phone_from,''),
      'phone_to',nullif(v_phone_to,''),
      'customer_id',v_customer_id,
      'occurred_at',v_occurred_at
    ));

  update public.papoai_webhook_inbox_v2
     set event_name=v_event_name,
         external_message_id=v_message_id,
         conversation_ref=v_conversation_ref,
         phone_candidate=v_phone,
         metadata=v_metadata,
         adapter_version=2,
         status=case
           when v_event_name in ('message.received','message.sent') and v_message_id is not null and v_conversation_ref is not null
             then 'normalized'
           else 'review_required'
         end,
         last_error=case
           when v_event_name in ('message.received','message.sent') and v_message_id is not null and v_conversation_ref is not null
             then null
           else 'unsupported_or_incomplete_payload'
         end
   where id=p_capture_id;

  return jsonb_build_object(
    'ok',true,
    'id',p_capture_id,
    'status',case
      when v_event_name in ('message.received','message.sent') and v_message_id is not null and v_conversation_ref is not null
        then 'normalized'
      else 'review_required'
    end,
    'event_name',v_event_name,
    'conversation_ref',v_conversation_ref,
    'external_message_id',v_message_id,
    'phone_candidate',v_phone,
    'customer_id',v_customer_id,
    'adapter_version',2
  );
end;
$function$
;

-- function: papoai_normalize_pending_v2(p_limit integer)
CREATE OR REPLACE FUNCTION public.papoai_normalize_pending_v2(p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row record;
  v_total integer:=0;
  v_normalized integer:=0;
  v_review integer:=0;
  v_result jsonb;
begin
  for v_row in
    select id
    from public.papoai_webhook_inbox_v2
    where status='captured'
      and expires_at>now()
    order by received_at
    limit greatest(1,least(200,coalesce(p_limit,50)))
  loop
    v_total:=v_total+1;
    v_result:=public.papoai_normalize_capture_v2(v_row.id);
    if v_result->>'status'='normalized' then
      v_normalized:=v_normalized+1;
    else
      v_review:=v_review+1;
    end if;
  end loop;

  return jsonb_build_object(
    'ok',true,
    'processed',v_total,
    'normalized',v_normalized,
    'review_required',v_review
  );
end;
$function$
;

-- function: papoai_prepare_product_draft_v1(p_conversation_ref text, p_phone text, p_message text, p_customer_id uuid, p_source_event_key text)
CREATE OR REPLACE FUNCTION public.papoai_prepare_product_draft_v1(p_conversation_ref text, p_phone text, p_message text, p_customer_id uuid DEFAULT NULL::uuid, p_source_event_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_cfg public.ops2_papoai_bridge_runtime_v1%rowtype;
  v_raw text:=trim(coalesce(p_message,''));
  v_split text;
  v_line text;
  v_query text;
  v_qty integer;
  v_match text[];
  v_resolved jsonb;
  v_candidate jsonb;
  v_cart jsonb:='[]'::jsonb;
  v_issues jsonb:='[]'::jsonb;
  v_customer_snapshot jsonb:='{}'::jsonb;
  v_draft jsonb;
  v_total_cents bigint:=0;
  v_count integer:=0;
  v_stock numeric:=0;
  v_price numeric:=0;
begin
  select * into v_cfg from public.ops2_papoai_bridge_runtime_v1 where id=1;
  if coalesce(v_cfg.structured_draft_enabled,false) is not true then
    return jsonb_build_object('ok',false,'blocked',true,'error','structured_draft_disabled','external_write',false);
  end if;
  if nullif(btrim(coalesce(p_conversation_ref,'')),'') is null then
    return jsonb_build_object('ok',false,'error','conversation_required','external_write',false);
  end if;
  if v_raw='' then
    return jsonb_build_object('ok',false,'error','message_required','external_write',false);
  end if;

  v_split:=regexp_replace(v_raw,'[\r\n;]+',',','g');
  v_split:=regexp_replace(v_split,'\s+e\s+',',','gi');

  for v_line in
    select btrim(x) from regexp_split_to_table(v_split,',') x where btrim(x)<>''
  loop
    v_count:=v_count+1;
    if v_count>20 then
      return jsonb_build_object('ok',false,'error','too_many_product_lines','external_write',false);
    end if;

    v_query:=regexp_replace(v_line,
      '^\s*(quero|queria|preciso\s+de|me\s+manda|me\s+mande|manda|mande|coloca|coloque|adiciona|adicione)\s+',
      '','i');
    v_qty:=1;

    v_match:=regexp_match(v_query,'^\s*([1-9]|[12][0-9]|30)\s*(x|un|unidade|unidades)?\s+','i');
    if v_match is not null and array_length(v_match,1)>=1 then
      begin v_qty:=greatest(1,least(30,v_match[1]::integer)); exception when others then v_qty:=1; end;
      v_query:=regexp_replace(v_query,'^\s*([1-9]|[12][0-9]|30)\s*(x|un|unidade|unidades)?\s+','','i');
    elsif lower(v_query) ~ '^\s*duas\s+' then v_qty:=2; v_query:=regexp_replace(v_query,'^\s*duas\s+','','i');
    elsif translate(lower(v_query),'êéè','eee') ~ '^\s*tres\s+' then v_qty:=3; v_query:=regexp_replace(v_query,'^\s*(três|tres)\s+','','i');
    elsif lower(v_query) ~ '^\s*quatro\s+' then v_qty:=4; v_query:=regexp_replace(v_query,'^\s*quatro\s+','','i');
    elsif lower(v_query) ~ '^\s*cinco\s+' then v_qty:=5; v_query:=regexp_replace(v_query,'^\s*cinco\s+','','i');
    end if;

    v_query:=btrim(v_query);
    if v_query='' then
      v_issues:=v_issues||jsonb_build_array(jsonb_build_object('line',v_line,'reason','product_query_missing'));
      continue;
    end if;

    v_resolved:=public.papoai_resolve_product_intent_v1(v_query,5);
    if coalesce((v_resolved->>'resolved')::boolean,false) is not true then
      v_issues:=v_issues||jsonb_build_array(jsonb_build_object(
        'line',v_line,'query',v_query,'quantity',v_qty,
        'reason',coalesce(v_resolved->>'reason','product_not_resolved'),
        'candidates',coalesce(v_resolved->'candidates','[]'::jsonb)
      ));
      continue;
    end if;

    v_candidate:=v_resolved->'candidates'->0;
    v_stock:=coalesce((v_candidate->>'stock')::numeric,0);
    if v_stock<v_qty then
      v_issues:=v_issues||jsonb_build_array(jsonb_build_object(
        'line',v_line,'query',v_query,'quantity',v_qty,'reason','insufficient_stock',
        'available_quantity',v_stock,'product',v_candidate
      ));
      continue;
    end if;

    v_cart:=v_cart||jsonb_build_array(jsonb_build_object(
      'type','product','id',v_candidate->>'product_id','qty',v_qty
    ));
    v_price:=coalesce((v_candidate->>'price')::numeric,0);
    v_total_cents:=v_total_cents+round(v_price*v_qty*100)::bigint;
  end loop;

  if v_count=0 then
    return jsonb_build_object('ok',true,'draft_created',false,'reason','no_product_lines','external_write',false);
  end if;

  if jsonb_array_length(v_issues)>0 then
    return jsonb_build_object(
      'ok',true,'draft_created',false,'requires_clarification',true,
      'issues',v_issues,'resolved_cart',v_cart,'external_write',false
    );
  end if;

  if jsonb_array_length(v_cart)=0 then
    return jsonb_build_object('ok',true,'draft_created',false,'reason','no_resolved_products','external_write',false);
  end if;

  if p_customer_id is not null then
    select jsonb_strip_nulls(jsonb_build_object('id',c.id,'display_name',nullif(btrim(coalesce(c.name,'')),'')))
      into v_customer_snapshot
      from public.customers c where c.id=p_customer_id;
    v_customer_snapshot:=coalesce(v_customer_snapshot,'{}'::jsonb);
  end if;

  v_draft:=public.papoai_upsert_order_draft_v2(
    p_conversation_ref,p_phone,v_cart,null,v_customer_snapshot,'{}'::jsonb,p_customer_id,p_source_event_key
  );

  return jsonb_build_object(
    'ok',true,'draft_created',true,'draft',v_draft,'cart',v_cart,
    'quoted_subtotal_cents',v_total_cents,'needs_payment',true,'needs_delivery_review',true,
    'requires_clarification',false,'external_order_created',false,
    'structured_order_commit_enabled',coalesce(v_cfg.structured_order_commit_enabled,false)
  );
end;
$function$
;

-- function: papoai_resolve_product_intent_v1(p_query text, p_limit integer)
CREATE OR REPLACE FUNCTION public.papoai_resolve_product_intent_v1(p_query text, p_limit integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
with q0 as (
  select regexp_replace(
    translate(lower(trim(coalesce(p_query,''))),
      'áàãâäéèêëíìîïóòõôöúùûüç',
      'aaaaaeeeeiiiiooooouuuuc'),
    '[^a-z0-9]+',' ','g'
  ) as norm,
  greatest(1,least(coalesce(p_limit,5),10)) as lim
), tokens as (
  select distinct t as token
  from q0, regexp_split_to_table(q0.norm,'\s+') t
  where length(t)>=2
    and t not in ('quero','queria','manda','mande','mandar','me','pra','para','por','favor','favorzinho','um','uma','uns','umas','de','da','do','das','dos','e','com','coloca','coloque','adiciona','adicione','preciso','comprar','produto','produtos','unidade','unidades','un')
), token_count as (
  select count(*)::int n from tokens
), base as (
  select
    p.id,p.sku,p.gtin,p.name,p.brand,p.category,p.packaging,p.image_url,
    case when p.is_offer=true and p.offer_price is not null and p.offer_price>=0 then p.offer_price else p.price end as price,
    greatest(0,coalesce(s.loose_sellable_stock,0))::numeric as stock,
    regexp_replace(translate(lower(concat_ws(' ',p.name,p.brand,p.packaging,p.category,p.sku,p.gtin)),
      'áàãâäéèêëíìîïóòõôöúùûüç','aaaaaeeeeiiiiooooouuuuc'),'[^a-z0-9]+',' ','g') as hay,
    regexp_replace(translate(lower(coalesce(p.name,'')),
      'áàãâäéèêëíìîïóòõôöúùûüç','aaaaaeeeeiiiiooooouuuuc'),'[^a-z0-9]+',' ','g') as n_name
  from public.products p
  join public.ops2_loose_sellable_stock_v1 s on s.product_id=p.id
  where p.is_active=true
    and p.physically_verified=true
    and p.price is not null and p.price>0
    and coalesce(s.loose_sellable_stock,0)>0
), scored as (
  select b.*,
         (select count(*) from tokens t where (' '||b.hay||' ') like '% '||t.token||' %'
           or replace(b.hay,' ','') like '%'||t.token||'%')::int as matched,
         (select n from token_count) as token_total,
         case when b.n_name=(select trim(norm) from q0) then 100
              when b.n_name like (select trim(norm) from q0)||'%' then 95
              else 80 end as score
  from base b
), matches as (
  select * from scored
  where token_total>0 and matched=token_total
), limited as (
  select * from matches
  order by score desc,name,id
  limit (select lim from q0)
), agg as (
  select count(*)::int as visible_count,
         coalesce(jsonb_agg(jsonb_build_object(
           'product_id',id,'sku',sku,'gtin',gtin,'name',name,'brand',brand,
           'category',category,'packaging',packaging,'price',price,'stock',stock,
           'image_url',image_url,'score',score
         ) order by score desc,name,id),'[]'::jsonb) as candidates
  from limited
), total as (
  select count(*)::int as n from matches
)
select jsonb_build_object(
  'ok',true,
  'query',p_query,
  'normalized_query',(select trim(norm) from q0),
  'token_count',(select n from token_count),
  'candidate_count',(select n from total),
  'resolved',(select n from total)=1,
  'ambiguous',(select n from total)>1,
  'reason',case when (select n from token_count)=0 then 'query_too_generic'
                when (select n from total)=1 then 'exact_candidate'
                when (select n from total)>1 then 'multiple_candidates'
                else 'no_candidate' end,
  'candidates',(select candidates from agg)
);
$function$
;

-- function: papoai_upsert_order_draft_v2(p_conversation_ref text, p_phone text, p_cart jsonb, p_payment_method text, p_customer_snapshot jsonb, p_delivery jsonb, p_customer_id uuid, p_source_event_key text)
CREATE OR REPLACE FUNCTION public.papoai_upsert_order_draft_v2(p_conversation_ref text, p_phone text, p_cart jsonb, p_payment_method text, p_customer_snapshot jsonb DEFAULT '{}'::jsonb, p_delivery jsonb DEFAULT '{}'::jsonb, p_customer_id uuid DEFAULT NULL::uuid, p_source_event_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_conversation text:=left(trim(coalesce(p_conversation_ref,'')),180);
  v_phone text;
  v_event text:=nullif(left(trim(coalesce(p_source_event_key,'')),220),'');
  v_existing_event public.papoai_draft_events_v2%rowtype;
  v_row public.papoai_order_drafts_v2%rowtype;
  v_revision integer;
begin
  if v_conversation='' then raise exception 'conversation_required'; end if;
  v_phone:=public.normalize_storefront_phone_v2(p_phone);
  if jsonb_typeof(coalesce(p_cart,'[]'::jsonb))<>'array' then raise exception 'invalid_cart'; end if;
  if jsonb_array_length(coalesce(p_cart,'[]'::jsonb))>80 then raise exception 'too_many_items'; end if;

  if v_event is not null then
    select * into v_existing_event
      from public.papoai_draft_events_v2
     where event_key=v_event;
    if found then
      select * into v_row from public.papoai_order_drafts_v2 where id=v_existing_event.draft_id;
      return jsonb_build_object(
        'ok',true,'duplicate',true,'draft_id',v_row.id,'revision',v_existing_event.revision,
        'status',v_row.status,'canonical_order_id',v_row.canonical_order_id
      );
    end if;
  end if;

  select * into v_row
    from public.papoai_order_drafts_v2
   where conversation_ref=v_conversation
     and status in ('draft','awaiting_confirmation','review_required')
   order by updated_at desc
   limit 1
   for update;

  if found and v_row.expires_at<=now() then
    update public.papoai_order_drafts_v2
       set status='expired',updated_at=now()
     where id=v_row.id;
    v_row:=null;
  end if;

  if v_row.id is null then
    insert into public.papoai_order_drafts_v2(
      conversation_ref,phone_e164,customer_id,revision,status,cart,payment_method,
      customer_snapshot,delivery,last_source_event_key,expires_at
    ) values(
      v_conversation,v_phone,p_customer_id,1,'draft',coalesce(p_cart,'[]'::jsonb),
      nullif(trim(coalesce(p_payment_method,'')),''),
      coalesce(p_customer_snapshot,'{}'::jsonb),coalesce(p_delivery,'{}'::jsonb),
      v_event,now()+interval '2 hours'
    )
    returning * into v_row;
  else
    v_revision:=v_row.revision+1;
    update public.papoai_order_drafts_v2
       set phone_e164=v_phone,
           customer_id=coalesce(p_customer_id,v_row.customer_id),
           revision=v_revision,
           status='draft',
           cart=coalesce(p_cart,'[]'::jsonb),
           payment_method=nullif(trim(coalesce(p_payment_method,'')),''),
           customer_snapshot=coalesce(p_customer_snapshot,'{}'::jsonb),
           delivery=coalesce(p_delivery,'{}'::jsonb),
           quoted_total_cents=null,
           summary_hash=null,
           sent_message_id=null,
           confirmed_message_id=null,
           last_source_event_key=v_event,
           expires_at=now()+interval '2 hours',
           updated_at=now()
     where id=v_row.id
     returning * into v_row;
  end if;

  if v_event is not null then
    insert into public.papoai_draft_events_v2(event_key,draft_id,revision,event_type)
    values(v_event,v_row.id,v_row.revision,'draft_update')
    on conflict(event_key) do nothing;
  end if;

  return jsonb_build_object(
    'ok',true,'duplicate',false,'draft_id',v_row.id,'revision',v_row.revision,
    'status',v_row.status,'expires_at',v_row.expires_at
  );
end;
$function$
;

-- function: phone_variants_br(p_phone text)
CREATE OR REPLACE FUNCTION public.phone_variants_br(p_phone text)
 RETURNS text[]
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  raw text:=regexp_replace(coalesce(p_phone,''),'[^0-9]','','g');
  canonical text:=regexp_replace(coalesce(public.canonical_whatsapp_e164_br_v2(p_phone),''),'[^0-9]','','g');
  base text;
  old_mobile text;
  v text[]:=array[]::text[];
begin
  if raw<>'' then v:=array_append(v,raw); end if;
  if canonical<>'' then
    v:=array_append(v,canonical);
    if left(canonical,2)='55' then
      base:=substr(canonical,3);
      v:=array_append(v,base);
      if length(base)=11 and substr(base,3,1)='9' and substr(base,4,1) ~ '^[6-9]$' then
        old_mobile:=substr(base,1,2)||substr(base,4);
        v:=array_append(v,old_mobile);
        v:=array_append(v,'55'||old_mobile);
      end if;
    end if;
  end if;
  select coalesce(array_agg(x order by length(x),x),array[]::text[]) into v
  from (select distinct x from unnest(v) x where length(x) between 10 and 13) s;
  return v;
end;
$function$
;

-- function: prepare_bling_invoice_issue_job_v1(p_order_id uuid, p_idempotency_key text)
CREATE OR REPLACE FUNCTION public.prepare_bling_invoice_issue_job_v1(p_order_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  cfg public.fiscal_runtime_config%rowtype;
  c public.order_fiscal_controls%rowtype;
  existing public.fiscal_issue_jobs%rowtype;
  new_id uuid;
begin
  select * into cfg from public.fiscal_runtime_config where id=1;
  if not cfg.enabled or not cfg.bling_invoice_prepare_enabled or cfg.execution_mode not in ('homologation','canary','live') then
    return jsonb_build_object('ok',false,'error','fiscal_runtime_disabled','side_effect_performed',false,'external_side_effect',false);
  end if;
  if p_idempotency_key is null or length(trim(p_idempotency_key)) < 12 then
    return jsonb_build_object('ok',false,'error','invalid_idempotency_key','side_effect_performed',false,'external_side_effect',false);
  end if;
  select * into c from public.order_fiscal_controls where order_id=p_order_id for update;
  if not found or c.fiscal_status<>'ready' then
    return jsonb_build_object('ok',false,'error','order_not_fiscal_ready','side_effect_performed',false,'external_side_effect',false);
  end if;
  select * into existing from public.fiscal_issue_jobs where order_id=p_order_id and fiscal_version=c.fiscal_version;
  if found then
    return jsonb_build_object('ok',true,'replay',true,'job_id',existing.id,'status',existing.status,'side_effect_performed',false,'external_side_effect',false);
  end if;
  insert into public.fiscal_issue_jobs(order_id,fiscal_version,idempotency_key,status)
  values(p_order_id,c.fiscal_version,trim(p_idempotency_key),'held') returning id into new_id;
  update public.order_fiscal_controls set fiscal_status='queued',updated_at=now() where order_id=p_order_id;
  return jsonb_build_object('ok',true,'replay',false,'job_id',new_id,'status','held','dispatcher_implemented',false,'side_effect_performed',true,'external_side_effect',false);
end;
$function$
;

-- function: prepare_purchase_stock_receipt_plan_v1(p_document_id uuid)
CREATE OR REPLACE FUNCTION public.prepare_purchase_stock_receipt_plan_v1(p_document_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  p jsonb;
  v_plan public.purchase_stock_receipt_plans_v1%rowtype;
  v_expected jsonb;
  v_baseline jsonb;
  v_lot_summary jsonb;
  v_authority text;
  v_deposit bigint;
begin
  p:=public.get_purchase_xml_receipt_preflight_v1(p_document_id);
  if coalesce((p->>'ready')::boolean,false) is not true then
    return jsonb_build_object('ok',false,'error','purchase_receipt_preflight_failed','preflight',p);
  end if;
  v_authority:='supabase';
  v_deposit:=null;

  select coalesce(jsonb_agg(jsonb_build_object(
    'product_id',q.product_id,'bling_product_id',q.bling_product_id,'quantity',q.quantity,
    'base_unit',q.base_unit,'purchase_item_ids',q.purchase_item_ids
  ) order by q.product_id),'[]'::jsonb)
  into v_expected
  from (
    select i.product_id,max(coalesce(l.bling_id,i.bling_product_id)) as bling_product_id,
      sum(i.converted_quantity)::numeric(18,6) as quantity,min(i.base_unit) as base_unit,
      jsonb_agg(i.id order by i.item_number) as purchase_item_ids
    from public.purchase_xml_items i
    left join lateral (
      select bling_id from public.bling_hub_entity_links_v2 x
      where x.entity_type='product' and x.status='matched' and x.source_id=i.product_id::text
      order by x.last_verified_at desc nulls last limit 1
    ) l on true
    where i.document_id=p_document_id and i.stock_update_requested is true group by i.product_id
  ) q;

  select coalesce(jsonb_agg(jsonb_build_object(
    'product_id',p.id,'catalog_stock',coalesce(p.stock,0),
    'basket_locked_quantity',coalesce(s.basket_locked_quantity,0),
    'sellable_stock',coalesce(s.loose_sellable_stock,0),'observed_at',p.updated_at
  ) order by p.id),'[]'::jsonb)
  into v_baseline from public.products p
  left join public.ops2_loose_sellable_stock_v1 s on s.product_id=p.id
  where p.id in (select product_id from public.purchase_xml_items where document_id=p_document_id and product_id is not null and stock_update_requested is true);

  select jsonb_build_object(
    'rows',count(*),
    'ready',count(*) filter(where e.status in ('observed','ready','materialized')),
    'review_required',count(*) filter(where e.status='review_required'),
    'without_expiration',count(*) filter(where e.expiration_date is null),
    'expiration_required',false
  ) into v_lot_summary
  from public.purchase_xml_item_lot_evidence e
  join public.purchase_xml_items i on i.id=e.purchase_item_id
  where i.document_id=p_document_id and i.stock_update_requested is true;

  insert into public.purchase_stock_receipt_plans_v1(
    document_id,status,stock_authority,deposit_id,expected_items,baseline_snapshot,
    lot_evidence_summary,idempotency_key,updated_at
  ) values(
    p_document_id,'preview',
    v_authority,v_deposit,v_expected,v_baseline,coalesce(v_lot_summary,'{}'::jsonb),
    'purchase-receipt-plan:'||p_document_id::text,now()
  )
  on conflict(document_id) do update set
    expected_items=case when purchase_stock_receipt_plans_v1.status='verified' then purchase_stock_receipt_plans_v1.expected_items else excluded.expected_items end,
    baseline_snapshot=case when purchase_stock_receipt_plans_v1.status='verified' then purchase_stock_receipt_plans_v1.baseline_snapshot else excluded.baseline_snapshot end,
    lot_evidence_summary=excluded.lot_evidence_summary,deposit_id=excluded.deposit_id,
    stock_authority=excluded.stock_authority,
    updated_at=case when purchase_stock_receipt_plans_v1.status='verified' then purchase_stock_receipt_plans_v1.updated_at else now() end
  returning * into v_plan;

  return jsonb_build_object(
    'ok',true,'plan_id',v_plan.id,'document_id',v_plan.document_id,'status',v_plan.status,
    'stock_authority',v_plan.stock_authority,'deposit_id',v_plan.deposit_id,
    'expected_items',v_plan.expected_items,'baseline_snapshot',v_plan.baseline_snapshot,
    'lot_evidence_summary',v_plan.lot_evidence_summary,'expiration_required',false,'external_write',false
  );
end;
$function$
;

-- function: preview_bling_invoice_eligibility_v1(p_order_id uuid)
CREATE OR REPLACE FUNCTION public.preview_bling_invoice_eligibility_v1(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  o public.orders%rowtype;
  c public.order_fiscal_controls%rowtype;
  r jsonb;
  v_reconcile_only boolean:=false;
begin
  select * into o from public.orders where id=p_order_id;
  if not found then
    return jsonb_build_object('ok',false,'eligible',false,'error','order_not_found','external_side_effect',false);
  end if;

  r:=public.refresh_order_fiscal_readiness_v1(o.id);
  select * into c from public.order_fiscal_controls where order_id=o.id;
  v_reconcile_only:=o.status in ('out_for_delivery','delivered') or c.dispatch_fiscal_status in ('authorized','not_required');

  return jsonb_build_object(
    'ok',true,
    'eligible',(o.status='ready' and c.fiscal_status='ready'),
    'reconcile_only',v_reconcile_only,
    'reason',c.fiscal_block_reason,
    'order_status',o.status,
    'payment_status',c.payment_status,
    'fiscal_status',c.fiscal_status,
    'fiscal_version',c.fiscal_version,
    'dispatch_fiscal_status',c.dispatch_fiscal_status,
    'bling_invoice_id',c.bling_invoice_id,
    'bling_invoice_number',c.bling_invoice_number,
    'readiness',r,
    'external_side_effect',false
  );
end;
$function$
;

-- function: product_catalog_enrichment_worker_authorized_v1(p_secret text)
CREATE OR REPLACE FUNCTION public.product_catalog_enrichment_worker_authorized_v1(p_secret text)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(
    length(coalesce(p_secret,'')) >= 48
    and p_secret = (select decrypted_secret from vault.decrypted_secrets where name='product_catalog_enrichment_worker_secret_v1' limit 1),
    false
  )
$function$
;

-- function: project_bling_hub_product_sync_status_v1()
CREATE OR REPLACE FUNCTION public.project_bling_hub_product_sync_status_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_product_id uuid;
  v_bling_id bigint;
  v_id_text text;
begin
  if new.domain <> 'product'
     or new.source_system <> 'vitrine_qx'
     or new.status not in ('synced', 'review_required', 'retry', 'failed')
     or (tg_op = 'UPDATE' and new.status is not distinct from old.status) then
    return new;
  end if;

  begin
    v_product_id := new.source_id::uuid;
  exception when invalid_text_representation then
    return new;
  end;

  v_id_text := coalesce(new.result->>'bling_id', new.provider_id);
  if v_id_text ~ '^[0-9]+$' then
    v_bling_id := v_id_text::bigint;
  end if;

  if v_bling_id is null then
    select bling_id into v_bling_id
      from public.bling_hub_entity_links_v2
     where source_system = 'vitrine_qx'
       and entity_type = 'product'
       and source_id = v_product_id::text
       and status = 'matched'
     limit 1;
  end if;

  if new.status = 'synced' then
    update public.products
       set bling_product_id = coalesce(v_bling_id, bling_product_id),
           sync_status = 'synced',
           last_bling_sync_at = coalesce(new.finished_at, new.updated_at, now()),
           sync_error = null
     where id = v_product_id;
  else
    update public.products
       set sync_status = 'pending_bling',
           sync_error = coalesce(new.error_message, new.error_code, 'Bling product sync requires review')
     where id = v_product_id;
  end if;

  return new;
end
$function$
;

-- function: purchase_xml_activate_inventory_lots_trigger_v1()
CREATE OR REPLACE FUNCTION public.purchase_xml_activate_inventory_lots_trigger_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_table_name='purchase_stock_receipt_plans_v1' then
    if new.status='verified' and (tg_op='INSERT' or old.status is distinct from new.status) then
      perform public.activate_purchase_xml_inventory_lots_v1(new.document_id,new.verified_by);
    end if;
  elsif tg_table_name='purchase_stock_receipts' then
    if new.status='applied' and (tg_op='INSERT' or old.status is distinct from new.status) then
      perform public.activate_purchase_xml_inventory_lots_v1(new.document_id,new.confirmed_by);
    end if;
  end if;
  return new;
end;
$function$
;

-- function: purchase_xml_catalog_identity_immutable_v1()
CREATE OR REPLACE FUNCTION public.purchase_xml_catalog_identity_immutable_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin raise exception 'xml_identity_history_immutable'; end; $function$
;

-- function: purchase_xml_lot_evidence_expiration_v1()
CREATE OR REPLACE FUNCTION public.purchase_xml_lot_evidence_expiration_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.expiration_date is not null then
    update public.purchase_xml_items
       set lot_expiration_date=case when lot_expiration_date is null then new.expiration_date else least(lot_expiration_date,new.expiration_date) end,
           updated_at=now()
     where id=new.purchase_item_id;
  end if;
  return new;
end;
$function$
;

-- function: purchase_xml_resolve_catalog_identity_v1(p_item_id uuid, p_product_id uuid, p_create_new boolean, p_proposed_name text, p_gtin_source text, p_gtin_role text, p_conversion_factor integer, p_actor_id uuid, p_confirmation text)
CREATE OR REPLACE FUNCTION public.purchase_xml_resolve_catalog_identity_v1(p_item_id uuid, p_product_id uuid, p_create_new boolean, p_proposed_name text, p_gtin_source text, p_gtin_role text, p_conversion_factor integer, p_actor_id uuid, p_confirmation text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
 v_item record;
 v_existing uuid;
 v_product record;
 v_product_id uuid;
 v_gtin text;
 v_check integer := 0;
 v_digit integer;
 v_weight integer:=3;
 v_expected integer;
 v_count integer;
 v_action text;
 v_audit_id uuid;
 v_kind text;
begin
 if p_actor_id is null or p_item_id is null or p_create_new is null
 then raise exception 'xml_identity_human_required'; end if;
 -- Re-check human privileges at the database transaction boundary. The Admin
 -- already authenticates the JWT, but this rejects stale/deactivated actors.
 if not exists (select 1 from public.admin_users
     where user_id=p_actor_id and is_active is true and role in ('owner','admin'))
 then raise exception 'xml_identity_actor_not_authorized'; end if;
 if p_confirmation is distinct from (case when p_create_new
   then 'CRIAR_INATIVO_XML' else 'VINCULAR_ITEM_XML' end)
 then raise exception 'xml_identity_confirmation_required'; end if;
 if p_gtin_source not in ('commercial','tax') or p_gtin_source is null
   or p_gtin_role not in ('base_unit','package') or p_gtin_role is null
 then raise exception 'xml_identity_role_required'; end if;
 if p_conversion_factor is null or p_conversion_factor not between 1 and 100000
   or (p_gtin_role='base_unit' and p_conversion_factor<>1)
   or (p_gtin_role='package' and p_conversion_factor<=1)
 then raise exception 'xml_identity_factor_invalid'; end if;
 select i.id,i.document_id,i.item_number,i.product_id,i.commercial_gtin,i.tax_gtin,
   i.purchase_unit,i.converted_quantity,i.inventory_lot_id,i.metadata,
   d.document_key,d.receipt_status
 into v_item from public.purchase_xml_items i
 join public.purchase_xml_documents d on d.id=i.document_id
 where i.id=p_item_id for update of i;
 if not found then raise exception 'xml_identity_item_not_found'; end if;
 if v_item.product_id is not null or exists(
   select 1 from public.purchase_xml_catalog_identity_actions_v1 where item_id=p_item_id)
 then raise exception 'xml_identity_already_resolved'; end if;
 -- Crucial: existing lot trigger fires on product_id UPDATE. Only 0/null
 -- converted quantity with no lot pointer is safe for evidence-only linking.
 if coalesce(v_item.converted_quantity,0)<>0 or v_item.inventory_lot_id is not null
 then raise exception 'xml_identity_operational_lot_review_required'; end if;
 -- The production lot trigger also treats a verified receipt plan or an applied
 -- stock receipt as received, even if document.receipt_status is still review.
 if v_item.receipt_status='received'
    or exists (select 1 from public.purchase_stock_receipt_plans_v1
        where document_id=v_item.document_id and status='verified')
    or exists (select 1 from public.purchase_stock_receipts
        where document_id=v_item.document_id and status='applied')
 then raise exception 'xml_identity_receipt_review_required'; end if;
 -- A stale/detached inventory lot is also operational state. Never relink it.
 if exists (select 1 from public.product_inventory_lots
       where source='purchase_xml' and source_ref='purchase-xml-item:'||p_item_id::text)
 then raise exception 'xml_identity_operational_lot_review_required'; end if;
 if not exists (select 1 from public.purchase_xml_catalog_observation_details_v2 x
   where x.purchase_item_id=v_item.id and x.source_state='xml_verified')
 then raise exception 'xml_identity_verified_source_required'; end if;
 if upper(coalesce(v_item.purchase_unit,'')) ~ '^(KG|G|L|LT|LTS|M|MT|TON)$'
 then raise exception 'xml_identity_weight_unit_review_required'; end if;
 if upper(coalesce(v_item.purchase_unit,'')) ~ '^(CX|FD|FAR|FARDO|CAIXA|FDO)$'
   and p_gtin_role<>'package'
 then raise exception 'xml_identity_outer_pack_requires_package'; end if;
 v_gtin:=case p_gtin_source when 'commercial' then v_item.commercial_gtin
   else v_item.tax_gtin end;
 if v_gtin is null or v_gtin !~ '^[0-9]+$' or
   length(v_gtin) not in (8,12,13,14)
 then raise exception 'xml_identity_gtin_invalid'; end if;
 for v_digit in reverse length(v_gtin)-1..1 loop
   v_check:=v_check + substr(v_gtin,v_digit,1)::integer * v_weight;
   v_weight:=case when v_weight=3 then 1 else 3 end;
 end loop;
 v_expected:=(10-(v_check%10))%10;
 if v_expected<>right(v_gtin,1)::integer
 then raise exception 'xml_identity_gtin_invalid'; end if;
 -- Serialize concurrent claims of the same EAN, across base/package kinds.
 perform pg_advisory_xact_lock(hashtextextended('purchase-xml-gtin:'||v_gtin,0));
 if p_create_new then
   if p_product_id is not null then raise exception 'xml_identity_product_argument_invalid'; end if;
 else
   if p_product_id is null then raise exception 'xml_identity_product_required'; end if;
 end if;
 select id into v_existing from public.products where gtin=v_gtin limit 1;
 if found and (p_create_new or v_existing is distinct from p_product_id)
 then raise exception 'xml_identity_gtin_conflict'; end if;
 if exists(select 1 from public.product_identifiers
     where identifier_value=v_gtin and status='confirmed'
       and identifier_kind in ('base_gtin','package_gtin')
       and (p_create_new or product_id is distinct from p_product_id))
 then raise exception 'xml_identity_identifier_conflict'; end if;
 if p_create_new then
   if length(btrim(coalesce(p_proposed_name,''))) not between 2 and 300
   then raise exception 'xml_identity_name_invalid'; end if;
   insert into public.products(sku,name,gtin,ncm,cost,price,stock,is_active,
     is_whatsapp_active,is_offer,unit,source_system,sync_status,desired_bling_status,metadata)
   values('XML-'||upper(left(replace(p_item_id::text,'-',''),12)),
     btrim(p_proposed_name),
     case when p_gtin_role='base_unit' then v_gtin else null end,
     null,null,null,0,false,false,false,'UN','operational','local','I',
     jsonb_build_object('purchase_xml_created',true,'fiscal_review_required',true,
       'catalog_identity_pending_receipt',true,'purchase_item_id',p_item_id))
   returning id into v_product_id;
   v_action:='create_inactive';
 else
   select id,gtin into v_product from public.products where id=p_product_id for update;
   if not found then raise exception 'xml_identity_product_not_found'; end if;
   if p_gtin_role='base_unit' and v_product.gtin is not null
      and v_product.gtin is distinct from v_gtin
   then raise exception 'xml_identity_existing_gtin_mismatch'; end if;
   v_product_id:=p_product_id;
   v_action:='link_existing';
 end if;
 v_kind:=case when p_gtin_role='package' then 'package_gtin' else 'base_gtin' end;
 -- Prevent a previously confirmed code from silently changing its EAN role.
 if exists (select 1 from public.product_identifiers
   where identifier_value=v_gtin and status='confirmed'
     and identifier_kind in ('base_gtin','package_gtin')
     and product_id=v_product_id and identifier_kind<>v_kind)
 then raise exception 'xml_identity_role_conflict'; end if;
 if not exists(select 1 from public.product_identifiers where identifier_value=v_gtin
   and status='confirmed' and identifier_kind in ('base_gtin','package_gtin'))
 then
   insert into public.product_identifiers(product_id,identifier_value,identifier_kind,
     packaging_unit,conversion_factor,source,confidence,status,metadata)
   values(v_product_id,v_gtin,v_kind,
     case when p_gtin_role='package' then v_item.purchase_unit else null end,
     case when p_gtin_role='package' then p_conversion_factor else null end,
     'purchase_identity_admin',1,'confirmed',
     jsonb_build_object('catalog_evidence_only',true,'purchase_item_id',p_item_id));
 end if;
 -- Do NOT set converted_quantity, receipt_status, NCM/CEST or stock.
 -- Existing lot trigger returns early when converted_quantity<=0 and no lot.
 update public.purchase_xml_items set product_id=v_product_id,
   match_method=case when p_create_new then 'human_created_inactive' else 'human_confirmed_existing' end,
   metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object(
     'catalog_evidence_only',true,'identity_confirmed_at',now(),
     'identity_confirmed_by',p_actor_id,'gtin_role',p_gtin_role,
     'gtin_source',p_gtin_source,'conversion_factor_proposed',p_conversion_factor,
     'receipt_not_authorized',true)
 where id=p_item_id and product_id is null and coalesce(converted_quantity,0)=0
   and inventory_lot_id is null;
 get diagnostics v_count=row_count;
 if v_count<>1 then raise exception 'xml_identity_race_conflict'; end if;
 insert into public.purchase_xml_catalog_identity_actions_v1
 (item_id,document_id,product_id,action,gtin_source,gtin_role,identifier,conversion_factor,actor_id)
 values(p_item_id,v_item.document_id,v_product_id,v_action,p_gtin_source,
   p_gtin_role,v_gtin,p_conversion_factor,p_actor_id) returning id into v_audit_id;
 return jsonb_build_object('ok',true,'item_id',p_item_id,'product_id',v_product_id,
   'created',p_create_new,'is_active',case when p_create_new then false else null end,
   'identity_action_id',v_audit_id,'catalog_evidence_only',true,
   'receipt_authorized',false,'stock_updated',false,'price_updated',false,
   'fiscal_updated',false,'bling_called',false,'finance_updated',false);
end; $function$
;

-- function: purchase_xml_resolve_catalog_identity_v2(p_item_id uuid, p_product_id uuid, p_create_new boolean, p_proposed_name text, p_gtin_source text, p_gtin_role text, p_conversion_factor integer, p_actor_id uuid, p_confirmation text, p_purchase_pack_units_for_review integer)
CREATE OR REPLACE FUNCTION public.purchase_xml_resolve_catalog_identity_v2(p_item_id uuid, p_product_id uuid, p_create_new boolean, p_proposed_name text, p_gtin_source text, p_gtin_role text, p_conversion_factor integer, p_actor_id uuid, p_confirmation text, p_purchase_pack_units_for_review integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
 v_item record;
 v_existing uuid;
 v_product record;
 v_product_id uuid;
 v_gtin text;
 v_check integer := 0;
 v_digit integer;
 v_weight integer:=3;
 v_expected integer;
 v_count integer;
 v_action text;
 v_audit_id uuid;
 v_kind text;
begin
 if p_actor_id is null or p_item_id is null or p_create_new is null
 then raise exception 'xml_identity_human_required'; end if;
 -- Re-check human privileges at the database transaction boundary. The Admin
 -- already authenticates the JWT, but this rejects stale/deactivated actors.
 if not exists (select 1 from public.admin_users
     where user_id=p_actor_id and is_active is true and role in ('owner','admin'))
 then raise exception 'xml_identity_actor_not_authorized'; end if;
 if p_confirmation is distinct from (case when p_create_new
   then 'CRIAR_INATIVO_XML' else 'VINCULAR_ITEM_XML' end)
 then raise exception 'xml_identity_confirmation_required'; end if;
 if p_gtin_source not in ('commercial','tax') or p_gtin_source is null
   or p_gtin_role not in ('base_unit','package') or p_gtin_role is null
 then raise exception 'xml_identity_role_required'; end if;
 if p_conversion_factor is null or p_conversion_factor not between 1 and 100000
   or (p_gtin_role='base_unit' and p_conversion_factor<>1)
   or (p_gtin_role='package' and p_conversion_factor<=1)
 then raise exception 'xml_identity_factor_invalid'; end if;
 -- Independent of the EAN role: a human may record a supplier pack quantity
 -- for later receipt review. Never multiply stock or converted_quantity here.
 if p_purchase_pack_units_for_review is not null and
    (p_gtin_role <> 'base_unit' or p_purchase_pack_units_for_review not between 1 and 100000)
 then raise exception 'xml_identity_purchase_pack_units_invalid'; end if;
 select i.id,i.document_id,i.item_number,i.product_id,i.commercial_gtin,i.tax_gtin,
   i.purchase_unit,i.converted_quantity,i.inventory_lot_id,i.metadata,
   d.document_key,d.receipt_status
 into v_item from public.purchase_xml_items i
 join public.purchase_xml_documents d on d.id=i.document_id
 where i.id=p_item_id for update of i;
 if not found then raise exception 'xml_identity_item_not_found'; end if;
 if v_item.product_id is not null or exists(
   select 1 from public.purchase_xml_catalog_identity_actions_v1 where item_id=p_item_id)
 then raise exception 'xml_identity_already_resolved'; end if;
 -- Crucial: existing lot trigger fires on product_id UPDATE. Only 0/null
 -- converted quantity with no lot pointer is safe for evidence-only linking.
 if coalesce(v_item.converted_quantity,0)<>0 or v_item.inventory_lot_id is not null
 then raise exception 'xml_identity_operational_lot_review_required'; end if;
 -- The production lot trigger also treats a verified receipt plan or an applied
 -- stock receipt as received, even if document.receipt_status is still review.
 if v_item.receipt_status='received'
    or exists (select 1 from public.purchase_stock_receipt_plans_v1
        where document_id=v_item.document_id and status='verified')
    or exists (select 1 from public.purchase_stock_receipts
        where document_id=v_item.document_id and status='applied')
 then raise exception 'xml_identity_receipt_review_required'; end if;
 -- A stale/detached inventory lot is also operational state. Never relink it.
 if exists (select 1 from public.product_inventory_lots
       where source='purchase_xml' and source_ref='purchase-xml-item:'||p_item_id::text)
 then raise exception 'xml_identity_operational_lot_review_required'; end if;
 if not exists (select 1 from public.purchase_xml_catalog_observation_details_v2 x
   where x.purchase_item_id=v_item.id and x.source_state='xml_verified')
 then raise exception 'xml_identity_verified_source_required'; end if;
 if upper(coalesce(v_item.purchase_unit,'')) ~ '^(KG|G|L|LT|LTS|M|MT|TON)$'
 then raise exception 'xml_identity_weight_unit_review_required'; end if;
 -- Purchase UoM and GTIN role are orthogonal. A supplier may invoice CX/FD
 -- while commercial/tax GTIN identifies the single retail unit.
 -- Quantity per supplier pack remains optional, evidence-only, and unposted.
 v_gtin:=case p_gtin_source when 'commercial' then v_item.commercial_gtin
   else v_item.tax_gtin end;
 if v_gtin is null or v_gtin !~ '^[0-9]+$' or
   length(v_gtin) not in (8,12,13,14)
 then raise exception 'xml_identity_gtin_invalid'; end if;
 for v_digit in reverse length(v_gtin)-1..1 loop
   v_check:=v_check + substr(v_gtin,v_digit,1)::integer * v_weight;
   v_weight:=case when v_weight=3 then 1 else 3 end;
 end loop;
 v_expected:=(10-(v_check%10))%10;
 if v_expected<>right(v_gtin,1)::integer
 then raise exception 'xml_identity_gtin_invalid'; end if;
 -- Serialize concurrent claims of the same EAN, across base/package kinds.
 perform pg_advisory_xact_lock(hashtextextended('purchase-xml-gtin:'||v_gtin,0));
 if p_create_new then
   if p_product_id is not null then raise exception 'xml_identity_product_argument_invalid'; end if;
 else
   if p_product_id is null then raise exception 'xml_identity_product_required'; end if;
 end if;
 select id into v_existing from public.products where gtin=v_gtin limit 1;
 if found and (p_create_new or v_existing is distinct from p_product_id)
 then raise exception 'xml_identity_gtin_conflict'; end if;
 if exists(select 1 from public.product_identifiers
     where identifier_value=v_gtin and status='confirmed'
       and identifier_kind in ('base_gtin','package_gtin')
       and (p_create_new or product_id is distinct from p_product_id))
 then raise exception 'xml_identity_identifier_conflict'; end if;
 if p_create_new then
   if length(btrim(coalesce(p_proposed_name,''))) not between 2 and 300
   then raise exception 'xml_identity_name_invalid'; end if;
   insert into public.products(sku,name,gtin,ncm,cost,price,stock,is_active,
     is_whatsapp_active,is_offer,unit,source_system,sync_status,desired_bling_status,metadata)
   values('XML-'||upper(left(replace(p_item_id::text,'-',''),12)),
     btrim(p_proposed_name),
     case when p_gtin_role='base_unit' then v_gtin else null end,
     null,null,null,0,false,false,false,'UN','operational','local','I',
     jsonb_build_object('purchase_xml_created',true,'fiscal_review_required',true,
       'catalog_identity_pending_receipt',true,'purchase_item_id',p_item_id))
   returning id into v_product_id;
   v_action:='create_inactive';
 else
   select id,gtin into v_product from public.products where id=p_product_id for update;
   if not found then raise exception 'xml_identity_product_not_found'; end if;
   if p_gtin_role='base_unit' and v_product.gtin is not null
      and v_product.gtin is distinct from v_gtin
   then raise exception 'xml_identity_existing_gtin_mismatch'; end if;
   v_product_id:=p_product_id;
   v_action:='link_existing';
 end if;
 v_kind:=case when p_gtin_role='package' then 'package_gtin' else 'base_gtin' end;
 -- Prevent a previously confirmed code from silently changing its EAN role.
 if exists (select 1 from public.product_identifiers
   where identifier_value=v_gtin and status='confirmed'
     and identifier_kind in ('base_gtin','package_gtin')
     and product_id=v_product_id and identifier_kind<>v_kind)
 then raise exception 'xml_identity_role_conflict'; end if;
 if not exists(select 1 from public.product_identifiers where identifier_value=v_gtin
   and status='confirmed' and identifier_kind in ('base_gtin','package_gtin'))
 then
   insert into public.product_identifiers(product_id,identifier_value,identifier_kind,
     packaging_unit,conversion_factor,source,confidence,status,metadata)
   values(v_product_id,v_gtin,v_kind,
     case when p_gtin_role='package' then v_item.purchase_unit else null end,
     case when p_gtin_role='package' then p_conversion_factor else null end,
     'purchase_identity_admin',1,'confirmed',
     jsonb_build_object('catalog_evidence_only',true,'purchase_item_id',p_item_id));
 end if;
 -- Do NOT set converted_quantity, receipt_status, NCM/CEST or stock.
 -- Existing lot trigger returns early when converted_quantity<=0 and no lot.
 update public.purchase_xml_items set product_id=v_product_id,
   match_method=case when p_create_new then 'human_created_inactive' else 'human_confirmed_existing' end,
   metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object(
     'catalog_evidence_only',true,'identity_confirmed_at',now(),
     'identity_confirmed_by',p_actor_id,'gtin_role',p_gtin_role,
     'gtin_source',p_gtin_source,'conversion_factor_proposed',p_conversion_factor,
     'receipt_not_authorized',true,
     'purchase_pack_units_for_review',p_purchase_pack_units_for_review,
     'purchase_pack_unit_from_xml',v_item.purchase_unit,
     'purchase_pack_not_authorized',true)
 where id=p_item_id and product_id is null and coalesce(converted_quantity,0)=0
   and inventory_lot_id is null;
 get diagnostics v_count=row_count;
 if v_count<>1 then raise exception 'xml_identity_race_conflict'; end if;
 insert into public.purchase_xml_catalog_identity_actions_v1
 (item_id,document_id,product_id,action,gtin_source,gtin_role,identifier,conversion_factor,
  purchase_pack_units_for_review,actor_id)
 values(p_item_id,v_item.document_id,v_product_id,v_action,p_gtin_source,
   p_gtin_role,v_gtin,p_conversion_factor,p_purchase_pack_units_for_review,
   p_actor_id) returning id into v_audit_id;
 return jsonb_build_object('ok',true,'item_id',p_item_id,'product_id',v_product_id,
   'created',p_create_new,'is_active',case when p_create_new then false else null end,
   'identity_action_id',v_audit_id,'catalog_evidence_only',true,
   'purchase_pack_units_for_review',p_purchase_pack_units_for_review,
   'receipt_authorized',false,'stock_updated',false,'price_updated',false,
   'fiscal_updated',false,'bling_called',false,'finance_updated',false);
end; $function$
;

-- function: purchase_xml_sync_inventory_lot_v1()
CREATE OR REPLACE FUNCTION public.purchase_xml_sync_inventory_lot_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_ref text := 'purchase-xml-item:' || new.id::text;
  v_lot_id uuid;
  v_existing_product uuid;
  v_existing_status text;
  v_doc_receipt text;
  v_doc_issued timestamptz;
  v_verified_at timestamptz;
  v_applied_at timestamptz;
  v_received boolean := false;
  v_received_at timestamptz;
begin
  if pg_trigger_depth() > 1 then return new; end if;

  if new.product_id is null or coalesce(new.converted_quantity,0) <= 0 then
    if new.inventory_lot_id is not null then
      update public.product_inventory_lots set status='cancelled', updated_at=now()
       where id=new.inventory_lot_id and status='quarantine';
      update public.purchase_xml_items set inventory_lot_id=null where id=new.id;
    end if;
    return new;
  end if;

  select d.receipt_status,d.issued_at into v_doc_receipt,v_doc_issued
    from public.purchase_xml_documents d where d.id=new.document_id;
  select p.verified_at into v_verified_at
    from public.purchase_stock_receipt_plans_v1 p
   where p.document_id=new.document_id and p.status='verified' limit 1;
  select r.applied_at into v_applied_at
    from public.purchase_stock_receipts r
   where r.document_id=new.document_id and r.status='applied' limit 1;

  v_received := coalesce(v_doc_receipt='received',false) or v_verified_at is not null or v_applied_at is not null;
  if v_received then v_received_at := coalesce(v_verified_at,v_applied_at,v_doc_issued,now()); end if;

  select l.id,l.product_id,l.status into v_lot_id,v_existing_product,v_existing_status
    from public.product_inventory_lots l
   where l.source='purchase_xml' and l.source_ref=v_ref for update;

  if found and v_existing_status in ('active','depleted','expired')
     and v_existing_product is distinct from new.product_id then
    raise exception 'received_purchase_lot_product_change_forbidden';
  end if;

  insert into public.product_inventory_lots(
    product_id,lot_code,expiration_date,quantity_on_hand,quantity_reserved,
    status,source,source_ref,received_at,metadata,updated_at
  ) values (
    new.product_id,null,new.lot_expiration_date,
    case when v_received then coalesce(new.converted_quantity,0) else 0 end,
    0,case when v_received then 'active' else 'quarantine' end,
    'purchase_xml',v_ref,v_received_at,
    jsonb_strip_nulls(jsonb_build_object(
      'purchase_item_id',new.id,'document_id',new.document_id,'item_number',new.item_number,
      'expected_quantity',new.converted_quantity,'base_unit',new.base_unit,
      'supplier_item_code',new.supplier_item_code,'commercial_gtin',new.commercial_gtin,
      'tax_gtin',new.tax_gtin,'lot_number_required',false,'expiration_optional',true
    )),now()
  )
  on conflict (source,source_ref) where source_ref is not null do update set
    product_id=case when public.product_inventory_lots.status in ('quarantine','cancelled') then excluded.product_id else public.product_inventory_lots.product_id end,
    expiration_date=excluded.expiration_date,
    quantity_on_hand=case
      when public.product_inventory_lots.status in ('quarantine','cancelled') and excluded.status='active' then excluded.quantity_on_hand
      when public.product_inventory_lots.status='cancelled' and excluded.status='quarantine' then 0
      else public.product_inventory_lots.quantity_on_hand end,
    status=case when public.product_inventory_lots.status in ('quarantine','cancelled') then excluded.status else public.product_inventory_lots.status end,
    received_at=coalesce(public.product_inventory_lots.received_at,excluded.received_at),
    metadata=public.product_inventory_lots.metadata || excluded.metadata,
    updated_at=now()
  returning id into v_lot_id;

  if new.inventory_lot_id is distinct from v_lot_id then
    update public.purchase_xml_items set inventory_lot_id=v_lot_id where id=new.id;
  end if;
  return new;
end;
$function$
;

-- function: recalculate_cart(p_cart_id uuid)
CREATE OR REPLACE FUNCTION public.recalculate_cart(p_cart_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_cart public.carts%rowtype;
  v_fiscal numeric := 0;
  v_template_delta numeric := 0;
  v_addons numeric := 0;
  v_total numeric := 0;
  v_adjustment numeric := 0;
  v_other numeric := 0;
  v_discount numeric := 0;
begin
  select * into v_cart from public.carts where id=p_cart_id for update;
  if not found then raise exception 'cart_not_found'; end if;

  select coalesce(sum(ci.quantity * coalesce(p.price,ci.unit_price,0)),0),
         coalesce(sum(case when ci.source in ('basket','substitution') then ci.commercial_delta else 0 end),0),
         coalesce(sum(case when ci.source='addon' then ci.quantity * coalesce(ci.commercial_unit_price,p.price,ci.unit_price,0) else 0 end),0)
    into v_fiscal,v_template_delta,v_addons
  from public.cart_items ci
  join public.products p on p.id=ci.product_id
  where ci.cart_id=p_cart_id;

  update public.cart_items ci
     set unit_price=coalesce(p.price,ci.unit_price,0),
         line_total=ci.quantity*coalesce(p.price,ci.unit_price,0),
         updated_at=now()
    from public.products p
   where ci.cart_id=p_cart_id and p.id=ci.product_id;

  v_total := greatest(0,coalesce(v_cart.base_commercial_price,0)+v_template_delta+v_addons);
  v_adjustment := v_total-v_fiscal;
  v_other := greatest(v_adjustment,0);
  v_discount := greatest(-v_adjustment,0);

  update public.carts
     set subtotal=v_fiscal,
         fiscal_subtotal=v_fiscal,
         adjustments=v_adjustment,
         total=v_total,
         other_expenses=v_other,
         discount=v_discount,
         pricing_status='ready',
         pricing_issues='[]'::jsonb,
         version=version+1,
         updated_at=now()
   where id=p_cart_id;

  return jsonb_build_object('cart_id',p_cart_id,'fiscal_subtotal',v_fiscal,'commercial_total',v_total,'adjustment',v_adjustment,'other_expenses',v_other,'discount',v_discount,'pricing_status','ready');
end;
$function$
;

-- function: reconcile_product_fiscal_strict_validation_v1()
CREATE OR REPLACE FUNCTION public.reconcile_product_fiscal_strict_validation_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_demoted integer:=0;
  v_validated integer:=0;
  v_blocked integer:=0;
begin
  with ineligible as (
    select pf.product_id
    from public.product_fiscal_profiles pf
    where pf.review_status='auto_validated'
      and coalesce(pf.metadata->>'strict_validation_policy','')='r0_10'
      and not exists (
        select 1
        from public.product_fiscal_strict_validation_preview_v1 v
        where v.product_id=pf.product_id
          and v.validation_eligible
      )
  ),
  upd as (
    update public.product_fiscal_profiles pf
       set review_status='pending',
           validated_at=null,
           classification_confidence=least(coalesce(pf.classification_confidence,0.88),0.92),
           metadata=coalesce(pf.metadata,'{}'::jsonb) || jsonb_build_object(
             'strict_validation_revoked_at',now(),
             'strict_validation_revoked_reason','new_or_changed_observed_evidence'
           ),
           updated_at=now()
      from ineligible i
     where pf.product_id=i.product_id
    returning pf.product_id
  )
  select count(*) into v_demoted from upd;

  perform public.refresh_product_fiscal_review_state_v1();

  select count(*) into v_blocked
  from public.product_fiscal_profiles
  where review_status='blocked';

  with applied as (
    select public.apply_product_fiscal_strict_validation_v1() as result
  )
  select coalesce((result->>'profiles_auto_validated')::integer,0)
    into v_validated
  from applied;

  return jsonb_build_object(
    'ok',true,
    'auto_validated_demoted',v_demoted,
    'auto_validated_applied',v_validated,
    'blocked_profiles',v_blocked,
    'external_write',false
  );
end;
$function$
;

-- function: reconcile_vitrine_order_customer_v1(p_customer_id uuid, p_order_suffix text, p_phone text, p_address jsonb)
CREATE OR REPLACE FUNCTION public.reconcile_vitrine_order_customer_v1(p_customer_id uuid, p_order_suffix text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_address jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_customer public.customers%rowtype;
  v_suffix text;
  v_order public.orders%rowtype;
  v_count integer:=0;
  v_source_order_id uuid;
  v_snapshot jsonb;
  v_delivery jsonb;
  v_effective_phone text;
begin
  select * into v_customer from public.customers where id=p_customer_id;
  if not found then
    return jsonb_build_object('ok',false,'error','customer_not_found');
  end if;

  v_suffix:=regexp_replace(coalesce(p_order_suffix,''),'[^0-9]','','g');

  if v_suffix<>'' then
    select count(*) into v_count
    from public.orders
    where source='vitrine'
      and right(regexp_replace(coalesce(order_number,''),'[^0-9]','','g'),length(v_suffix))=v_suffix
      and (customer_id is null or customer_id=p_customer_id);

    if v_count=1 then
      select * into v_order
      from public.orders
      where source='vitrine'
        and right(regexp_replace(coalesce(order_number,''),'[^0-9]','','g'),length(v_suffix))=v_suffix
        and (customer_id is null or customer_id=p_customer_id)
      order by created_at desc
      limit 1;
    elsif v_count>1 then
      return jsonb_build_object('ok',false,'error','order_suffix_ambiguous','matches',v_count);
    end if;
  end if;

  if v_order.id is null and nullif(btrim(coalesce(p_phone,'')),'') is not null then
    select count(*) into v_count
    from public.orders o
    where o.source='vitrine'
      and (o.customer_id is null or o.customer_id=p_customer_id)
      and o.created_at>=now()-interval '24 hours'
      and public.normalize_phone_digits(o.phone_e164)=any(public.phone_variants_br(p_phone));

    if v_count=1 then
      select o.* into v_order
      from public.orders o
      where o.source='vitrine'
        and (o.customer_id is null or o.customer_id=p_customer_id)
        and o.created_at>=now()-interval '24 hours'
        and public.normalize_phone_digits(o.phone_e164)=any(public.phone_variants_br(p_phone))
      order by o.created_at desc
      limit 1;
    elsif v_count>1 then
      return jsonb_build_object('ok',false,'error','phone_order_ambiguous','matches',v_count);
    end if;
  end if;

  if v_order.id is null then
    return jsonb_build_object('ok',true,'linked',false,'reason','order_not_found');
  end if;

  v_effective_phone:=coalesce(nullif(v_order.phone_e164,''),nullif(p_phone,''),v_customer.primary_whatsapp_e164);

  if nullif(v_order.phone_e164,'') is not null
     and nullif(coalesce(p_phone,v_customer.primary_whatsapp_e164),'') is not null
     and public.normalize_phone_digits(v_order.phone_e164)=any(public.phone_variants_br(coalesce(p_phone,v_customer.primary_whatsapp_e164)))
     and not exists(
       select 1 from public.customers c
       where c.id<>p_customer_id
         and public.normalize_phone_digits(c.primary_whatsapp_e164)=public.normalize_phone_digits(v_order.phone_e164)
     )
     and not exists(
       select 1 from public.customer_phones cp
       where cp.customer_id<>p_customer_id
         and public.normalize_phone_digits(cp.phone_e164)=public.normalize_phone_digits(v_order.phone_e164)
     )
  then
    update public.customers
       set primary_whatsapp_e164=v_order.phone_e164,
           updated_at=now()
     where id=p_customer_id;

    update public.customer_phones
       set is_primary=false
     where customer_id=p_customer_id;

    insert into public.customer_phones(customer_id,phone_e164,source,is_primary,verified_at)
    select p_customer_id,v_order.phone_e164,'papoai_flow',true,now()
    where not exists(
      select 1 from public.customer_phones cp where cp.phone_e164=v_order.phone_e164
    );

    update public.customer_phones
       set is_primary=true,
           verified_at=coalesce(verified_at,now())
     where customer_id=p_customer_id
       and phone_e164=v_order.phone_e164;

    v_customer.primary_whatsapp_e164:=v_order.phone_e164;
  end if;

  v_snapshot:=coalesce(v_order.customer_snapshot,'{}'::jsonb)||jsonb_strip_nulls(jsonb_build_object(
    'source_customer_id',p_customer_id,
    'name',v_customer.name,
    'phone',v_effective_phone,
    'cpf',v_customer.cpf_cnpj
  ));

  v_delivery:=coalesce(v_order.delivery_address,'{}'::jsonb)
    || coalesce(p_address,'{}'::jsonb)
    || jsonb_strip_nulls(jsonb_build_object(
      'source_customer_id',p_customer_id,
      'customer_status','registered',
      'customer_name',v_customer.name,
      'phone',v_effective_phone,
      'cpf',v_customer.cpf_cnpj
    ));

  update public.orders
     set customer_id=p_customer_id,
         customer_snapshot=v_snapshot,
         delivery_address=v_delivery,
         updated_at=now()
   where id=v_order.id;

  begin
    v_source_order_id:=nullif(v_order.checkout_snapshot->>'source_order_id','')::uuid;
  exception when others then
    v_source_order_id:=null;
  end;

  perform public.refresh_customer_purchase_profile(p_customer_id);

  return jsonb_build_object(
    'ok',true,
    'linked',true,
    'order_id',v_order.id,
    'order_number',v_order.order_number,
    'source_order_id',v_source_order_id,
    'customer_id',p_customer_id,
    'effective_phone',v_effective_phone
  );
end
$function$
;

-- function: refresh_basket_hidden_adjustment_v1(p_basket_id uuid)
CREATE OR REPLACE FUNCTION public.refresh_basket_hidden_adjustment_v1(p_basket_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_adjustment numeric;
begin
  select public.calculate_basket_hidden_adjustment_v1(p_basket_id)
    into v_adjustment;
  if v_adjustment is null then return null; end if;

  update public.basket_templates
     set hidden_adjustment=v_adjustment,
         updated_at=now()
   where id=p_basket_id
     and hidden_adjustment is distinct from v_adjustment;

  return v_adjustment;
end;
$function$
;

-- function: refresh_customer_purchase_profile(p_customer_id uuid)
CREATE OR REPLACE FUNCTION public.refresh_customer_purchase_profile(p_customer_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_customer_id is null then return; end if;

  delete from public.customer_product_stats
  where customer_id=p_customer_id;

  insert into public.customer_product_stats(
    customer_id,product_id,purchase_count,total_quantity,total_spent,
    first_purchase_at,last_purchase_at,updated_at
  )
  select
    p_customer_id,
    oi.product_id,
    count(distinct o.id)::int,
    coalesce(sum(oi.quantity),0),
    coalesce(sum(oi.line_total),0),
    min(coalesce(o.confirmed_at,o.created_at)),
    max(coalesce(o.confirmed_at,o.created_at)),
    now()
  from public.orders o
  join public.order_items oi on oi.order_id=o.id
  where o.customer_id=p_customer_id
    and public.is_customer_purchase_valid_v1(o.status,o.cancelled_at,o.returned_at)
    and oi.product_id is not null
  group by oi.product_id;

  update public.customers c
  set
    order_count=x.order_count,
    lifetime_value=x.lifetime_value,
    last_order_at=x.last_order_at,
    updated_at=now()
  from (
    select
      count(*)::int as order_count,
      coalesce(sum(total),0)::numeric(14,2) as lifetime_value,
      max(coalesce(confirmed_at,created_at)) as last_order_at
    from public.orders
    where customer_id=p_customer_id
      and public.is_customer_purchase_valid_v1(status,cancelled_at,returned_at)
  ) x
  where c.id=p_customer_id;
end
$function$
;

-- function: refresh_order_fiscal_readiness_v1(p_order_id uuid)
CREATE OR REPLACE FUNCTION public.refresh_order_fiscal_readiness_v1(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  o public.orders%rowtype;
  c public.order_fiscal_controls%rowtype;
  s public.order_separation_completions_v1%rowtype;
  v_items integer:=0;
  v_pending integer:=0;
  v_linked boolean:=false;
  next_status text:='blocked';
  reason text:=null;
  ready_at timestamptz:=null;
begin
  select * into o from public.orders where id=p_order_id;
  if not found then
    return jsonb_build_object('ok',false,'error','order_not_found','external_side_effect',false);
  end if;

  insert into public.order_fiscal_controls(order_id)
  values(o.id)
  on conflict(order_id) do nothing;

  select * into c from public.order_fiscal_controls where order_id=o.id for update;
  select * into s from public.order_separation_completions_v1 where order_id=o.id;
  select count(*),count(*) filter(where state='pending')
    into v_items,v_pending
    from public.order_separation_items_v1
   where order_id=o.id;
  select exists(
    select 1 from public.bling_hub_entity_links_v2 l
     where l.source_system='vitrine_qx'
       and l.entity_type='order'
       and l.source_id=o.id::text
       and l.status='matched'
  ) into v_linked;
  v_linked:=v_linked or o.bling_order_id is not null;

  if o.status='cancelled' then
    next_status:='cancelled'; reason:='order_cancelled';
  elsif o.status='returned' then
    next_status:='blocked'; reason:='order_returned';
  elsif o.status in ('out_for_delivery','delivered') then
    if c.dispatch_fiscal_status in ('authorized','not_required') then
      next_status:='ready'; reason:=null; ready_at:=coalesce(c.fiscal_ready_at,c.dispatch_fiscal_authorized_at,now());
    else
      next_status:='blocked'; reason:='fiscal_authorization_missing_legacy_state';
    end if;
  elsif o.status<>'ready' then
    next_status:='blocked'; reason:='separation_not_completed';
  elsif s.id is null or s.completed_at is null then
    next_status:='blocked'; reason:='separation_not_completed';
  elsif coalesce((s.metadata->>'stock_applied')::boolean,false) is not true then
    next_status:='blocked'; reason:='separation_stock_not_applied';
  elsif v_items=0 then
    next_status:='blocked'; reason:='separation_items_missing';
  elsif v_pending>0 then
    next_status:='blocked'; reason:='separation_has_pending_items';
  elsif coalesce(s.final_total,0)<=0 or coalesce(o.total,0)<=0 then
    next_status:='blocked'; reason:='invalid_final_total';
  elsif abs(coalesce(s.final_total,0)-coalesce(o.total,0))>0.01 then
    next_status:='review_required'; reason:='final_total_mismatch';
  elsif o.customer_id is null then
    next_status:='blocked'; reason:='customer_missing';
  elsif coalesce(nullif(trim(o.delivery_address->>'street'),''),'')=''
     or coalesce(nullif(trim(o.delivery_address->>'city'),''),'')=''
     or coalesce(nullif(trim(o.delivery_address->>'state'),''),'')='' then
    next_status:='blocked'; reason:='delivery_address_incomplete';
  elsif not v_linked then
    next_status:='blocked'; reason:='bling_order_not_linked';
  else
    next_status:='ready'; reason:=null; ready_at:=coalesce(c.fiscal_ready_at,now());
  end if;

  update public.order_fiscal_controls
     set fiscal_status=next_status,
         fiscal_block_reason=reason,
         fiscal_ready_at=case when next_status='ready' then ready_at else null end,
         fiscal_version=4,
         updated_at=now()
   where order_id=o.id;

  return jsonb_build_object(
    'ok',true,
    'order_id',o.id,
    'order_status',o.status,
    'fiscal_status',next_status,
    'block_reason',reason,
    'fiscal_ready_at',case when next_status='ready' then ready_at else null end,
    'separation_completed',s.id is not null and s.completed_at is not null,
    'stock_applied',coalesce((s.metadata->>'stock_applied')::boolean,false),
    'pending_items',v_pending,
    'final_total',coalesce(s.final_total,o.total),
    'bling_order_linked',v_linked,
    'payment_status',c.payment_status,
    'payment_required_for_invoice',false,
    'external_side_effect',false
  );
end;
$function$
;

-- function: refresh_product_fiscal_candidates_r0_3()
CREATE OR REPLACE FUNCTION public.refresh_product_fiscal_candidates_r0_3()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_candidates integer:=0;
  v_ambiguous integer:=0;
begin
  with matched as (
    select *
    from public.product_fiscal_rule_candidates_v1
    where description_matches
  ),
  unique_match as (
    select product_id,min(rule_id::text)::uuid as rule_id
    from matched
    group by product_id
    having count(*)=1
  ),
  chosen as (
    select m.*
    from matched m
    join unique_match u on u.product_id=m.product_id and u.rule_id=m.rule_id
  ),
  upd as (
    update public.product_fiscal_profiles pf
    set
      cest=ch.rule_cest,
      matched_st_rule_id=ch.rule_id,
      tax_segment_code=ch.segment_code,
      tax_segment_name=ch.segment_name,
      st_status='candidate',
      classification_source='supplier_xml+mt_legal_rule',
      classification_confidence=case when ch.document_count>=2 then 0.92 else 0.88 end,
      fiscal_description=coalesce(nullif(pf.fiscal_description,''),ch.evidence_description),
      rule_version=ch.rule_version,
      updated_at=now()
    from chosen ch
    where pf.product_id=ch.product_id
      and pf.review_status='pending'
    returning pf.product_id
  )
  select count(*) into v_candidates from upd;

  select count(*) into v_ambiguous
  from (
    select product_id
    from public.product_fiscal_rule_candidates_v1
    where description_matches
    group by product_id
    having count(*)>1
  ) x;

  return jsonb_build_object(
    'ok',true,
    'candidate_profiles_updated',v_candidates,
    'ambiguous_products',v_ambiguous,
    'preserves_validated_profiles',true,
    'external_write',false
  );
end;
$function$
;

-- function: refresh_product_fiscal_complex_bundle_guard_v1()
CREATE OR REPLACE FUNCTION public.refresh_product_fiscal_complex_bundle_guard_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_opened integer:=0;
  v_downgraded integer:=0;
  v_resolved integer:=0;
begin
  insert into public.product_fiscal_review_items(
    product_id,issue_code,severity,status,title,details,detected_by
  )
  select
    c.product_id,
    'complex_bundle_needs_evidence',
    'warning',
    'open',
    'Kit/combo exige evidência fiscal independente',
    jsonb_build_object(
      'gtin',c.gtin,
      'ncm',c.fiscal_ncm,
      'cest_candidate',c.fiscal_cest,
      'independent_evidence_count',c.independent_evidence_count,
      'policy','complex_bundle_r0_14'
    ),
    'complex_bundle_r0_14'
  from public.product_fiscal_complex_bundle_v1 c
  join public.products p on p.id=c.product_id
  where p.is_active
    and c.is_complex_bundle
    and not c.independently_supported
    and c.review_status='auto_validated'
  on conflict (product_id,issue_code) where status in ('open','in_review')
  do update set
    severity=excluded.severity,
    title=excluded.title,
    details=excluded.details,
    detected_by=excluded.detected_by,
    updated_at=now();
  get diagnostics v_opened=row_count;

  with upd as (
    update public.product_fiscal_profiles pf
       set review_status='pending',
           st_status=case when pf.st_status='applicable' then 'candidate' else pf.st_status end,
           validated_at=null,
           classification_source='strict_validation_revoked_complex_bundle',
           classification_confidence=least(coalesce(pf.classification_confidence,0.8000),0.8000),
           metadata=coalesce(pf.metadata,'{}'::jsonb) || jsonb_build_object(
             'complex_bundle_guard','r0_14',
             'complex_bundle_guard_at',now(),
             'complex_bundle_requires_independent_evidence',true
           ),
           updated_at=now()
      from public.product_fiscal_complex_bundle_v1 c
     where pf.product_id=c.product_id
       and c.is_complex_bundle
       and not c.independently_supported
       and pf.review_status='auto_validated'
    returning pf.product_id
  )
  select count(*) into v_downgraded from upd;

  with resolved as (
    update public.product_fiscal_review_items r
       set status='resolved',
           resolved_at=now(),
           resolution_note='Kit/combo passou a ter evidência fiscal independente compatível.',
           updated_at=now()
     where r.issue_code='complex_bundle_needs_evidence'
       and r.detected_by='complex_bundle_r0_14'
       and r.status in ('open','in_review')
       and exists (
         select 1
         from public.product_fiscal_complex_bundle_v1 c
         where c.product_id=r.product_id
           and c.independently_supported
       )
    returning 1
  )
  select count(*) into v_resolved from resolved;

  return jsonb_build_object(
    'ok',true,
    'review_items_touched',v_opened,
    'profiles_downgraded',v_downgraded,
    'resolved_supported',v_resolved,
    'external_write',false
  );
end;
$function$
;

-- function: refresh_product_fiscal_evidence_quality_v1()
CREATE OR REPLACE FUNCTION public.refresh_product_fiscal_evidence_quality_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_gtin_blockers integer:=0;
  v_ambiguities integer:=0;
  v_unmapped_cest integer:=0;
  v_bling_cest_missing integer:=0;
  v_origin_conflicts integer:=0;
  v_bling_link_missing integer:=0;
  v_origin_enriched integer:=0;
  v_resolved integer:=0;
begin
  insert into public.product_fiscal_review_items(
    product_id,issue_code,severity,status,title,details,detected_by
  )
  select
    s.product_id,'gtin_invalid','blocker','open',
    'GTIN informado é inválido',
    jsonb_build_object(
      'gtin',s.gtin,
      'ncm',s.ncm,
      'risk_score',s.risk_score,
      'note','Bloqueia validação/sincronização fiscal do produto; não bloqueia venda no catálogo.'
    ),
    'catalog_fiscal_r0_6'
  from public.product_fiscal_catalog_scan_v1 s
  where s.is_active and s.risk_code='gtin_invalid'
  on conflict (product_id,issue_code) where status in ('open','in_review')
  do update set severity=excluded.severity,title=excluded.title,details=excluded.details,
                detected_by=excluded.detected_by,updated_at=now();
  get diagnostics v_gtin_blockers = row_count;

  insert into public.product_fiscal_review_items(
    product_id,issue_code,severity,status,title,details,detected_by
  )
  select
    s.product_id,'legal_rule_ambiguous','warning','open',
    'Mais de uma regra fiscal legal é candidata',
    jsonb_build_object(
      'ncm',s.ncm,
      'candidate_cests',s.candidate_cests,
      'legal_rule_match_count',s.legal_rule_match_count
    ),
    'catalog_fiscal_r0_6'
  from public.product_fiscal_catalog_scan_v1 s
  where s.is_active and s.risk_code='legal_rule_ambiguous'
  on conflict (product_id,issue_code) where status in ('open','in_review')
  do update set severity=excluded.severity,title=excluded.title,details=excluded.details,
                detected_by=excluded.detected_by,updated_at=now();
  get diagnostics v_ambiguities = row_count;

  insert into public.product_fiscal_review_items(
    product_id,issue_code,severity,status,title,details,detected_by
  )
  select
    s.product_id,'cest_evidence_unmapped','warning','open',
    'CEST da evidência ainda não foi confirmado pelo classificador legal',
    jsonb_build_object(
      'ncm',s.ncm,
      'ncm_consensus',s.ncm_consensus,
      'cest_consensus',s.cest_consensus,
      'evidence_count',s.evidence_count
    ),
    'catalog_fiscal_r0_6'
  from public.product_fiscal_catalog_scan_v1 s
  where s.is_active and s.risk_code='cest_evidence_unmapped'
  on conflict (product_id,issue_code) where status in ('open','in_review')
  do update set severity=excluded.severity,title=excluded.title,details=excluded.details,
                detected_by=excluded.detected_by,updated_at=now();
  get diagnostics v_unmapped_cest = row_count;

  with bling_latest as (
    select distinct on (product_id)
      product_id,cest,origin_code,ncm,observed_at
    from public.product_fiscal_evidence
    where evidence_type='bling_product_detail'
    order by product_id,observed_at desc,created_at desc
  ),
  xml as (
    select
      product_id,
      case when count(distinct cest) filter (where cest is not null)=1
           then min(cest) filter (where cest is not null) end as xml_cest,
      case when count(distinct origin_code) filter (where origin_code is not null)=1
           then min(origin_code) filter (where origin_code is not null) end as xml_origin,
      count(*) as xml_rows
    from public.product_fiscal_evidence
    where evidence_type='supplier_nfe_xml'
    group by product_id
  )
  insert into public.product_fiscal_review_items(
    product_id,issue_code,severity,status,title,details,detected_by
  )
  select
    b.product_id,'bling_cest_missing_vs_xml','warning','open',
    'CEST existe no XML do fornecedor e está vazio no Bling',
    jsonb_build_object(
      'xml_cest',x.xml_cest,
      'bling_cest',b.cest,
      'bling_ncm',b.ncm,
      'xml_evidence_rows',x.xml_rows,
      'bling_observed_at',b.observed_at
    ),
    'catalog_fiscal_r0_6'
  from bling_latest b
  join xml x on x.product_id=b.product_id
  join public.products p on p.id=b.product_id and p.is_active
  where x.xml_cest is not null and b.cest is null
  on conflict (product_id,issue_code) where status in ('open','in_review')
  do update set severity=excluded.severity,title=excluded.title,details=excluded.details,
                detected_by=excluded.detected_by,updated_at=now();
  get diagnostics v_bling_cest_missing = row_count;

  with bling_latest as (
    select distinct on (product_id)
      product_id,origin_code,observed_at
    from public.product_fiscal_evidence
    where evidence_type='bling_product_detail'
    order by product_id,observed_at desc,created_at desc
  ),
  xml as (
    select
      product_id,
      case when count(distinct origin_code) filter (where origin_code is not null)=1
           then min(origin_code) filter (where origin_code is not null) end as xml_origin,
      count(distinct origin_code) filter (where origin_code is not null) as xml_origin_count
    from public.product_fiscal_evidence
    where evidence_type='supplier_nfe_xml'
    group by product_id
  )
  insert into public.product_fiscal_review_items(
    product_id,issue_code,severity,status,title,details,detected_by
  )
  select
    b.product_id,'origin_evidence_conflict','blocker','open',
    'Origem da mercadoria diverge entre Bling e XML do fornecedor',
    jsonb_build_object(
      'bling_origin',b.origin_code,
      'xml_origin',x.xml_origin,
      'bling_observed_at',b.observed_at
    ),
    'catalog_fiscal_r0_6'
  from bling_latest b
  join xml x on x.product_id=b.product_id
  join public.products p on p.id=b.product_id and p.is_active
  where x.xml_origin_count=1
    and x.xml_origin is not null
    and b.origin_code is not null
    and x.xml_origin<>b.origin_code
  on conflict (product_id,issue_code) where status in ('open','in_review')
  do update set severity=excluded.severity,title=excluded.title,details=excluded.details,
                detected_by=excluded.detected_by,updated_at=now();
  get diagnostics v_origin_conflicts = row_count;

  insert into public.product_fiscal_review_items(
    product_id,issue_code,severity,status,title,details,detected_by
  )
  select
    s.product_id,'bling_product_not_linked','warning','open',
    'Produto de risco fiscal não está vinculado ao Bling',
    jsonb_build_object(
      'gtin',s.gtin,'ncm',s.ncm,'risk_code',s.risk_code,'risk_score',s.risk_score
    ),
    'catalog_fiscal_r0_6'
  from public.product_fiscal_catalog_scan_v1 s
  join public.products p on p.id=s.product_id
  left join public.bling_hub_entity_links_v2 l
    on l.entity_type='product' and l.source_id=p.id::text and l.status='matched'
  where s.is_active
    and (
      s.risk_score>=70
      or (s.legal_rule_match_count=1 and s.cest_consensus is null)
    )
    and p.bling_product_id is null
    and l.bling_id is null
  on conflict (product_id,issue_code) where status in ('open','in_review')
  do update set severity=excluded.severity,title=excluded.title,details=excluded.details,
                detected_by=excluded.detected_by,updated_at=now();
  get diagnostics v_bling_link_missing = row_count;

  with supplier_origin as (
    select
      e.product_id,
      case when count(distinct e.origin_code) filter (where e.origin_code is not null)=1
           then min(e.origin_code) filter (where e.origin_code is not null) end as origin_consensus,
      count(*) filter (where e.origin_code is not null)::bigint as evidence_count
    from public.product_fiscal_evidence e
    join public.products p on p.id=e.product_id and p.is_active
    where e.evidence_type='supplier_nfe_xml'
    group by e.product_id
  ),
  upd as (
    update public.product_fiscal_profiles pf
    set
      origin_code=s.origin_consensus,
      metadata=coalesce(pf.metadata,'{}'::jsonb) || jsonb_build_object(
        'origin_candidate_source','supplier_xml_consensus_r0_9',
        'origin_candidate_evidence_count',s.evidence_count,
        'origin_candidate_at',now()
      ),
      updated_at=now()
    from supplier_origin s
    where pf.product_id=s.product_id
      and s.origin_consensus is not null
      and pf.origin_code is null
      and pf.review_status<>'blocked'
    returning pf.product_id
  )
  select count(*) into v_origin_enriched from upd;

  with current_conditions as (
    select p.id as product_id,'gtin_invalid'::text issue_code
    from public.products p
    where p.is_active
      and nullif(regexp_replace(coalesce(p.gtin,''),'\\D','','g'),'') is not null
      and not public.fiscal_valid_gtin_v1(p.gtin)
    union all
    select s.product_id,'legal_rule_ambiguous'
    from public.product_fiscal_catalog_scan_v1 s
    where s.is_active and s.risk_code='legal_rule_ambiguous'
    union all
    select s.product_id,'cest_evidence_unmapped'
    from public.product_fiscal_catalog_scan_v1 s
    where s.is_active and s.risk_code='cest_evidence_unmapped'
    union all
    select b.product_id,'bling_cest_missing_vs_xml'
    from (
      select distinct on (product_id) product_id,cest
      from public.product_fiscal_evidence
      where evidence_type='bling_product_detail'
      order by product_id,observed_at desc,created_at desc
    ) b
    join (
      select product_id,
        case when count(distinct cest) filter (where cest is not null)=1
             then min(cest) filter (where cest is not null) end xml_cest
      from public.product_fiscal_evidence
      where evidence_type='supplier_nfe_xml'
      group by product_id
    ) x on x.product_id=b.product_id
    where x.xml_cest is not null and b.cest is null
    union all
    select b.product_id,'origin_evidence_conflict'
    from (
      select distinct on (product_id) product_id,origin_code
      from public.product_fiscal_evidence
      where evidence_type='bling_product_detail'
      order by product_id,observed_at desc,created_at desc
    ) b
    join (
      select product_id,
        case when count(distinct origin_code) filter (where origin_code is not null)=1
             then min(origin_code) filter (where origin_code is not null) end xml_origin,
        count(distinct origin_code) filter (where origin_code is not null) origin_count
      from public.product_fiscal_evidence
      where evidence_type='supplier_nfe_xml'
      group by product_id
    ) x on x.product_id=b.product_id
    where x.origin_count=1 and x.xml_origin is not null and b.origin_code is not null and x.xml_origin<>b.origin_code
  ),
  resolved as (
    update public.product_fiscal_review_items r
    set
      status='resolved',
      resolved_at=now(),
      resolution_note='Condição automática deixou de existir.',
      updated_at=now()
    where r.detected_by='catalog_fiscal_r0_6'
      and r.status in ('open','in_review')
      and r.issue_code<>'bling_product_not_linked'
      and not exists (
        select 1 from current_conditions c
        where c.product_id=r.product_id and c.issue_code=r.issue_code
      )
    returning 1
  )
  select count(*) into v_resolved from resolved;

  perform public.refresh_product_fiscal_review_state_v1();

  return jsonb_build_object(
    'ok',true,
    'gtin_blockers_touched',v_gtin_blockers,
    'legal_ambiguities_touched',v_ambiguities,
    'unmapped_cest_touched',v_unmapped_cest,
    'bling_cest_missing_touched',v_bling_cest_missing,
    'origin_conflicts_touched',v_origin_conflicts,
    'bling_link_missing_touched',v_bling_link_missing,
    'origin_profiles_enriched',v_origin_enriched,
    'resolved_stale',v_resolved,
    'external_write',false
  );
end;
$function$
;

-- function: refresh_product_fiscal_observed_conflicts_v1()
CREATE OR REPLACE FUNCTION public.refresh_product_fiscal_observed_conflicts_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_ncm integer:=0;
  v_cest integer:=0;
  v_origin integer:=0;
  v_resolved integer:=0;
begin
  insert into public.product_fiscal_review_items(
    product_id,issue_code,severity,status,title,details,detected_by
  )
  select
    c.product_id,
    'ncm_evidence_conflict',
    'blocker',
    'open',
    'NCM diverge entre perfil fiscal e/ou evidências observadas',
    jsonb_build_object(
      'profile_ncm',c.profile_ncm,
      'evidence_ncm_consensus',c.ncm_consensus,
      'evidence_ncm_distinct_count',c.ncm_distinct_count,
      'evidence_count',c.evidence_count
    ),
    'observed_evidence_guard_r0_15'
  from public.product_fiscal_evidence_consensus_v1 c
  join public.products p on p.id=c.product_id and p.is_active
  where coalesce(c.ncm_conflict,false)
  on conflict (product_id,issue_code) where status in ('open','in_review')
  do update set
    severity='blocker',
    title=excluded.title,
    details=excluded.details,
    detected_by=excluded.detected_by,
    updated_at=now();
  get diagnostics v_ncm=row_count;

  insert into public.product_fiscal_review_items(
    product_id,issue_code,severity,status,title,details,detected_by
  )
  select
    c.product_id,
    'cest_evidence_conflict',
    'blocker',
    'open',
    'CEST diverge entre evidências observadas',
    jsonb_build_object(
      'profile_cest',c.profile_cest,
      'evidence_cest_consensus',c.cest_consensus,
      'evidence_cest_distinct_count',c.cest_distinct_count,
      'evidence_count',c.evidence_count
    ),
    'observed_evidence_guard_r0_15'
  from public.product_fiscal_evidence_consensus_v1 c
  join public.products p on p.id=c.product_id and p.is_active
  where coalesce(c.cest_conflict,false)
  on conflict (product_id,issue_code) where status in ('open','in_review')
  do update set
    severity='blocker',
    title=excluded.title,
    details=excluded.details,
    detected_by=excluded.detected_by,
    updated_at=now();
  get diagnostics v_cest=row_count;

  insert into public.product_fiscal_review_items(
    product_id,issue_code,severity,status,title,details,detected_by
  )
  select
    c.product_id,
    'origin_evidence_conflict',
    'blocker',
    'open',
    'Origem diverge entre perfil fiscal e/ou evidências observadas',
    jsonb_build_object(
      'profile_origin',c.profile_origin_code,
      'evidence_origin_consensus',c.origin_consensus,
      'evidence_origin_distinct_count',c.origin_distinct_count,
      'origin_variation',c.origin_variation,
      'evidence_count',c.evidence_count
    ),
    'observed_evidence_guard_r0_15'
  from public.product_fiscal_evidence_consensus_v1 c
  join public.products p on p.id=c.product_id and p.is_active
  where coalesce(c.origin_variation,false)
     or (
       c.origin_consensus is not null
       and c.profile_origin_code is not null
       and c.origin_consensus<>c.profile_origin_code
     )
  on conflict (product_id,issue_code) where status in ('open','in_review')
  do update set
    severity='blocker',
    title=excluded.title,
    details=excluded.details,
    detected_by=excluded.detected_by,
    updated_at=now();
  get diagnostics v_origin=row_count;

  with current_conditions as (
    select c.product_id,'ncm_evidence_conflict'::text issue_code
    from public.product_fiscal_evidence_consensus_v1 c
    join public.products p on p.id=c.product_id and p.is_active
    where coalesce(c.ncm_conflict,false)

    union all

    select c.product_id,'cest_evidence_conflict'::text
    from public.product_fiscal_evidence_consensus_v1 c
    join public.products p on p.id=c.product_id and p.is_active
    where coalesce(c.cest_conflict,false)

    union all

    select c.product_id,'origin_evidence_conflict'::text
    from public.product_fiscal_evidence_consensus_v1 c
    join public.products p on p.id=c.product_id and p.is_active
    where coalesce(c.origin_variation,false)
       or (
         c.origin_consensus is not null
         and c.profile_origin_code is not null
         and c.origin_consensus<>c.profile_origin_code
       )
  ),
  resolved as (
    update public.product_fiscal_review_items r
       set status='resolved',
           resolved_at=now(),
           resolution_note='Conflito entre evidências observadas deixou de existir.',
           updated_at=now()
     where r.detected_by='observed_evidence_guard_r0_15'
       and r.status in ('open','in_review')
       and r.issue_code in ('ncm_evidence_conflict','cest_evidence_conflict','origin_evidence_conflict')
       and not exists (
         select 1
         from current_conditions c
         where c.product_id=r.product_id
           and c.issue_code=r.issue_code
       )
    returning 1
  )
  select count(*) into v_resolved from resolved;

  perform public.refresh_product_fiscal_review_state_v1();

  return jsonb_build_object(
    'ok',true,
    'ncm_conflicts_touched',v_ncm,
    'cest_conflicts_touched',v_cest,
    'origin_conflicts_touched',v_origin,
    'resolved_stale',v_resolved,
    'external_write',false
  );
end;
$function$
;

-- function: refresh_product_fiscal_origin_consensus_v1()
CREATE OR REPLACE FUNCTION public.refresh_product_fiscal_origin_consensus_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_updated integer:=0;
begin
  with consensus as (
    select
      c.product_id,
      c.origin_consensus,
      c.evidence_count,
      c.origin_variation
    from public.product_fiscal_evidence_consensus_v1 c
    join public.products p on p.id=c.product_id
    where p.is_active
      and c.evidence_count>0
      and c.origin_consensus is not null
      and coalesce(c.origin_variation,false)=false
  ),
  upd as (
    update public.product_fiscal_profiles pf
       set origin_code=c.origin_consensus,
           metadata=coalesce(pf.metadata,'{}'::jsonb) || jsonb_build_object(
             'origin_candidate_source','evidence_consensus_v1',
             'origin_candidate_evidence_count',c.evidence_count,
             'origin_candidate_at',now()
           ),
           updated_at=now()
      from consensus c
     where pf.product_id=c.product_id
       and pf.origin_code is null
       and pf.review_status<>'blocked'
    returning pf.product_id
  )
  select count(*) into v_updated from upd;

  return jsonb_build_object(
    'ok',true,
    'origin_profiles_updated',v_updated,
    'external_write',false
  );
end;
$function$
;

-- function: refresh_product_fiscal_review_state_v1()
CREATE OR REPLACE FUNCTION public.refresh_product_fiscal_review_state_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_blocked integer:=0;
  v_reopened integer:=0;
begin
  with upd as (
    update public.product_fiscal_profiles pf
    set review_status='blocked',updated_at=now()
    where pf.review_status not in ('human_validated','auto_validated')
      and exists (
        select 1 from public.product_fiscal_review_items r
        where r.product_id=pf.product_id
          and r.status in ('open','in_review')
          and r.severity='blocker'
      )
    returning 1
  )
  select count(*) into v_blocked from upd;

  with upd as (
    update public.product_fiscal_profiles pf
    set review_status='pending',updated_at=now()
    where pf.review_status='blocked'
      and not exists (
        select 1 from public.product_fiscal_review_items r
        where r.product_id=pf.product_id
          and r.status in ('open','in_review')
          and r.severity='blocker'
      )
    returning 1
  )
  select count(*) into v_reopened from upd;

  return jsonb_build_object(
    'ok',true,
    'blocked_profiles',v_blocked,
    'reopened_profiles',v_reopened
  );
end;
$function$
;

-- function: refresh_product_fiscal_rule_integrity_v1()
CREATE OR REPLACE FUNCTION public.refresh_product_fiscal_rule_integrity_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_opened integer:=0;
  v_resolved integer:=0;
begin
  insert into public.product_fiscal_review_items(
    product_id,issue_code,severity,status,title,details,detected_by
  )
  select
    i.product_id,
    'cest_rule_mismatch',
    'blocker',
    'open',
    'CEST da evidência diverge da regra legal candidata',
    jsonb_build_object(
      'rule_cest',i.rule_cest,
      'evidence_cest',i.evidence_cest,
      'rule_id',i.rule_id,
      'rule_version',i.version_key,
      'ncm_prefix',i.ncm_prefix,
      'legal_description',i.legal_description
    ),
    'rule_integrity_r0_9'
  from public.product_fiscal_rule_integrity_v1 i
  where i.cest_rule_mismatch
  on conflict (product_id,issue_code) where status in ('open','in_review')
  do update set
    severity='blocker',
    title=excluded.title,
    details=excluded.details,
    detected_by=excluded.detected_by,
    updated_at=now();
  get diagnostics v_opened=row_count;

  with resolved as (
    update public.product_fiscal_review_items r
       set status='resolved',
           resolved_at=now(),
           resolution_note='Divergência CEST x regra legal deixou de existir.',
           updated_at=now()
     where r.detected_by='rule_integrity_r0_9'
       and r.issue_code='cest_rule_mismatch'
       and r.status in ('open','in_review')
       and not exists (
         select 1
         from public.product_fiscal_rule_integrity_v1 i
         where i.product_id=r.product_id
           and i.cest_rule_mismatch
       )
    returning 1
  )
  select count(*) into v_resolved from resolved;

  perform public.refresh_product_fiscal_review_state_v1();

  return jsonb_build_object(
    'ok',true,
    'mismatches_touched',v_opened,
    'resolved_stale',v_resolved,
    'external_write',false
  );
end;
$function$
;

-- function: register_admin_saved_card_transaction_v1(p_card_id uuid, p_transaction_type text, p_amount numeric, p_location text, p_idempotency_key uuid)
CREATE OR REPLACE FUNCTION public.register_admin_saved_card_transaction_v1(p_card_id uuid, p_transaction_type text, p_amount numeric, p_location text, p_idempotency_key uuid)
 RETURNS TABLE(transaction_id uuid, card_id uuid, amount numeric, transaction_type text, location text, transaction_origin text, used_at timestamp with time zone, current_balance numeric)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_card public.admin_saved_cards_v1%rowtype;
  v_existing public.admin_saved_card_uses_v1%rowtype;
  v_transaction public.admin_saved_card_uses_v1%rowtype;
  v_balance numeric(12,2);
begin
  if p_card_id is null then
    raise exception 'card_not_found';
  end if;
  if p_transaction_type is null or p_transaction_type not in ('entry', 'exit') then
    raise exception 'invalid_transaction_type';
  end if;
  if p_amount is null or p_amount <= 0 or p_amount > 9999999999.99 or p_amount <> round(p_amount, 2) then
    raise exception 'invalid_amount';
  end if;
  if p_idempotency_key is null then
    raise exception 'invalid_idempotency_key';
  end if;
  if p_transaction_type = 'entry' and p_location is not null then
    raise exception 'invalid_location';
  end if;
  if p_transaction_type = 'exit'
    and (p_location is null or p_location not in ('Assaí', 'Fort', 'Atacadão'))
  then
    raise exception 'invalid_location';
  end if;

  select c.* into v_card
  from public.admin_saved_cards_v1 as c
  where c.id = p_card_id and c.deleted_at is null
  for update;

  if not found then
    raise exception 'card_not_found';
  end if;

  select u.* into v_existing
  from public.admin_saved_card_uses_v1 as u
  where u.idempotency_key = p_idempotency_key;

  if found then
    if v_existing.card_id <> p_card_id
      or v_existing.amount <> p_amount
      or v_existing.transaction_type <> p_transaction_type
      or v_existing.location is distinct from p_location
    then
      raise exception 'idempotency_key_conflict';
    end if;
    return query
      select v_existing.id, v_existing.card_id, v_existing.amount,
        v_existing.transaction_type, v_existing.location, v_existing.transaction_origin,
        v_existing.used_at, v_card.current_balance;
    return;
  end if;

  if p_transaction_type = 'entry' then
    if v_card.current_balance + p_amount > 9999999999.99 then
      raise exception 'balance_limit_exceeded';
    end if;

    update public.admin_saved_cards_v1 as c
    set current_balance = c.current_balance + p_amount, updated_at = now()
    where c.id = p_card_id
    returning c.current_balance into v_balance;
  else
    update public.admin_saved_cards_v1 as c
    set current_balance = c.current_balance - p_amount, updated_at = now()
    where c.id = p_card_id and c.current_balance >= p_amount
    returning c.current_balance into v_balance;

    if not found then
      raise exception 'insufficient_balance';
    end if;
  end if;

  insert into public.admin_saved_card_uses_v1 (
    card_id, amount, idempotency_key, transaction_type, location, transaction_origin
  )
  values (
    p_card_id, p_amount, p_idempotency_key, p_transaction_type, p_location, 'manual'
  )
  returning * into v_transaction;

  return query
    select v_transaction.id, v_transaction.card_id, v_transaction.amount,
      v_transaction.transaction_type, v_transaction.location, v_transaction.transaction_origin,
      v_transaction.used_at, v_balance;
end;
$function$
;

-- function: register_admin_saved_card_use_v1(p_card_id uuid, p_amount numeric, p_idempotency_key uuid)
CREATE OR REPLACE FUNCTION public.register_admin_saved_card_use_v1(p_card_id uuid, p_amount numeric, p_idempotency_key uuid)
 RETURNS TABLE(id uuid, card_id uuid, amount numeric, used_at timestamp with time zone, current_balance numeric)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_existing public.admin_saved_card_uses_v1%rowtype;
  v_balance numeric(12,2);
  v_used_at timestamptz := now();
  v_use_id uuid;
begin
  if p_card_id is null or p_idempotency_key is null
     or p_amount is null or p_amount <= 0 or p_amount <> round(p_amount, 2) then
    raise exception 'invalid_amount' using errcode = '22023';
  end if;

  select * into v_existing
  from public.admin_saved_card_uses_v1
  where idempotency_key = p_idempotency_key;

  if found then
    if v_existing.card_id <> p_card_id or v_existing.amount <> p_amount then
      raise exception 'idempotency_key_conflict' using errcode = '22023';
    end if;
    select current_balance into v_balance
    from public.admin_saved_cards_v1
    where public.admin_saved_cards_v1.id = p_card_id;
    return query select v_existing.id, v_existing.card_id, v_existing.amount, v_existing.used_at, v_balance;
    return;
  end if;

  update public.admin_saved_cards_v1 as card
  set current_balance = card.current_balance - p_amount,
      updated_at = v_used_at
  where card.id = p_card_id
    and card.current_balance >= p_amount
  returning card.current_balance into v_balance;

  if not found then
    if exists (select 1 from public.admin_saved_cards_v1 as card where card.id = p_card_id) then
      raise exception 'insufficient_balance' using errcode = 'P0001';
    end if;
    raise exception 'card_not_found' using errcode = 'P0002';
  end if;

  insert into public.admin_saved_card_uses_v1 as saved_use (card_id, amount, idempotency_key, used_at)
  values (p_card_id, p_amount, p_idempotency_key, v_used_at)
  returning saved_use.id into v_use_id;

  return query select v_use_id, p_card_id, p_amount, v_used_at, v_balance;
end;
$function$
;

-- function: release_bling_hub_oauth_lock_v2(p_owner uuid)
CREATE OR REPLACE FUNCTION public.release_bling_hub_oauth_lock_v2(p_owner uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  update public.bling_hub_runtime_v2
  set oauth_lock_owner=null,oauth_locked_until=null,updated_at=now()
  where id=1 and oauth_lock_owner=p_owner;
  return found;
end
$function$
;

-- function: release_vitrine_order_stock_v1(p_order_id uuid)
CREATE OR REPLACE FUNCTION public.release_vitrine_order_stock_v1(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  r record;
  v_consumed integer;
  v_cutover timestamptz;
begin
  select nullif(metadata->>'ops2_supabase_stock_authority_at','')::timestamptz into v_cutover
  from public.bling_hub_runtime_v2 where id=1;
  select count(*) filter(where status='consumed' and coalesce(consumed_at,updated_at,created_at)>=v_cutover)
    into v_consumed from public.vitrine_stock_reservations where order_id=p_order_id;
  for r in
    select product_id,quantity from public.vitrine_stock_reservations
    where order_id=p_order_id and status='consumed'
      and coalesce(consumed_at,updated_at,created_at)>=v_cutover
    order by product_id for update
  loop
    update public.products set stock=coalesce(stock,0)+r.quantity,updated_at=now() where id=r.product_id;
  end loop;
  update public.vitrine_stock_reservations
     set status='released',released_at=now(),updated_at=now()
   where order_id=p_order_id and status in ('reserved','allocated','consumed');
  return jsonb_build_object('ok',true,'status','released','stock_source','supabase_products_stock',
    'restored_physical_stock',coalesce(v_consumed,0)>0,'physical_stock_changed',coalesce(v_consumed,0)>0);
end;
$function$
;

-- function: rename_storefront_v3_category(p_old text, p_new text)
CREATE OR REPLACE FUNCTION public.rename_storefront_v3_category(p_old text, p_new text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_old text:=btrim(coalesce(p_old,''));
  v_new text:=btrim(coalesce(p_new,''));
  v_cfg public.storefront_v3_categories%rowtype;
begin
  if v_old='' or v_new='' then raise exception 'category_name_required'; end if;
  if v_old=v_new then return; end if;
  if exists(select 1 from public.storefront_v3_categories where name=v_new) then raise exception 'category_already_exists'; end if;

  select * into v_cfg from public.storefront_v3_categories where name=v_old;
  if not found then raise exception 'category_not_found'; end if;

  insert into public.storefront_v3_categories(name,is_visible,show_home,sort_order,created_at,updated_at)
  values(v_new,v_cfg.is_visible,v_cfg.show_home,v_cfg.sort_order,v_cfg.created_at,now());

  update public.products set category=v_new,updated_at=now() where category=v_old;
  delete from public.storefront_v3_categories where name=v_old;
end;
$function$
;

-- function: reserve_bling_hub_rate_slot_v2(p_min_interval_ms integer)
CREATE OR REPLACE FUNCTION public.reserve_bling_hub_rate_slot_v2(p_min_interval_ms integer DEFAULT NULL::integer)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_interval integer;
  v_now timestamptz:=clock_timestamp();
  v_slot timestamptz;
  v_next timestamptz;
  v_wait integer;
begin
  select coalesce(p_min_interval_ms,min_request_interval_ms) into v_interval
  from public.bling_hub_runtime_v2 where id=1;
  v_interval:=greatest(350,least(coalesce(v_interval,420),5000));

  select next_allowed_at into v_next
  from public.bling_hub_rate_limit_v2
  where id=1
  for update;

  v_slot:=greatest(v_now,coalesce(v_next,v_now));
  v_wait:=greatest(0,ceil(extract(epoch from (v_slot-v_now))*1000)::integer);

  update public.bling_hub_rate_limit_v2
  set next_allowed_at=v_slot+(v_interval::text||' milliseconds')::interval,updated_at=now()
  where id=1;

  return v_wait;
end
$function$
;

-- function: reserve_vitrine_order_stock_v1(p_order_id uuid)
CREATE OR REPLACE FUNCTION public.reserve_vitrine_order_stock_v1(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  r record;
  v_authority text;
  v_effective numeric;
  v_pending_local numeric;
  v_available numeric;
  v_demand_count integer:=0;
  v_manual_replacement_count integer:=0;
  v_manual_shortage_products uuid[]:='{}'::uuid[];
begin
  select coalesce(metadata->>'ops2_stock_authority','legacy_shadow')
    into v_authority
  from public.bling_hub_runtime_v2 where id=1;

  if p_order_id is null or not exists(
    select 1 from public.orders
    where id=p_order_id and source in ('vitrine','manual_whatsapp','papoai','reorder')
  ) then return jsonb_build_object('ok',false,'error','order_not_found'); end if;

  if exists(select 1 from public.vitrine_stock_reservations where order_id=p_order_id and status='consumed') then
    return jsonb_build_object('ok',true,'status','already_consumed','stock_authority',v_authority);
  end if;

  for r in
    select oi.product_id,
      sum(case
        when coalesce(oi.metadata->>'history_kind','')='basket_component'
          then greatest(oi.quantity-coalesce(nullif(oi.metadata->>'preassembled_units','')::numeric,0),0)
        else oi.quantity
      end) as quantity,
      bool_and(coalesce(oi.metadata->>'history_kind','')='basket_mold_component') as basket_components_only
    from public.order_items oi
    where oi.order_id=p_order_id and oi.product_id is not null
    group by oi.product_id
    having sum(case
      when coalesce(oi.metadata->>'history_kind','')='basket_component'
        then greatest(oi.quantity-coalesce(nullif(oi.metadata->>'preassembled_units','')::numeric,0),0)
      else oi.quantity
    end)>0
    order by oi.product_id
  loop
    v_demand_count:=v_demand_count+1;
    perform 1 from public.products p
    where p.id=r.product_id and (
      p.is_active=true or exists(
        select 1 from public.order_items oi
        join public.basket_mold_positions pos on pos.id::text=oi.metadata->>'position_id'
        join public.basket_molds bm on bm.id=pos.mold_id
          and bm.id::text=oi.metadata->>'mold_id'
          and bm.basket_id::text=oi.metadata->>'basket_id'
        join public.basket_mold_position_options opt on opt.position_id=pos.id and opt.product_id=p.id
        where oi.order_id=p_order_id and oi.product_id=p.id
          and oi.metadata->>'history_kind'='basket_mold_component'
      )
    ) for update;
    if not found then return jsonb_build_object('ok',false,'error','product_unavailable','product_id',r.product_id); end if;


    select public.basket_component_fresh_sellable_stock_v1(r.product_id)
      into v_effective;
    select public.supabase_stock_pending_reservations_v1(r.product_id,p_order_id)
      into v_pending_local;
    v_available:=greatest(0,coalesce(v_effective,0)-coalesce(v_pending_local,0));

    if v_available<r.quantity then
      if r.basket_components_only then
        update public.order_items
        set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object(
          'manual_replacement_required',true,
          'manual_replacement_reason','stock_shortage_at_reservation'
        )
        where order_id=p_order_id and product_id=r.product_id
          and metadata->>'history_kind'='basket_mold_component';
        v_manual_replacement_count:=v_manual_replacement_count+1;
        v_manual_shortage_products:=array_append(v_manual_shortage_products,r.product_id);
        continue;
      end if;
      return jsonb_build_object('ok',false,'error','insufficient_stock','product_id',r.product_id,
        'available',v_available,'requested',r.quantity,'stock_authority',v_authority);
    end if;
  end loop;

  if v_demand_count=0 then
    return jsonb_build_object('ok',true,
      'status',case when v_manual_replacement_count>0 then 'manual_replacement_pending' else 'preassembled_only' end,
      'manual_replacement_count',v_manual_replacement_count,'stock_authority',v_authority,
      'local_reservation_tracking',true,'physical_stock_changed',false);
  end if;

  insert into public.vitrine_stock_reservations(order_id,product_id,quantity,status,expires_at,updated_at)
  select p_order_id,oi.product_id,
    sum(case
      when coalesce(oi.metadata->>'history_kind','')='basket_component'
        then greatest(oi.quantity-coalesce(nullif(oi.metadata->>'preassembled_units','')::numeric,0),0)
      else oi.quantity
    end),
    'reserved',now()+interval '48 hours',now()
  from public.order_items oi
  where oi.order_id=p_order_id and oi.product_id is not null
    and not (oi.product_id=any(v_manual_shortage_products))
  group by oi.product_id
  having sum(case
    when coalesce(oi.metadata->>'history_kind','')='basket_component'
      then greatest(oi.quantity-coalesce(nullif(oi.metadata->>'preassembled_units','')::numeric,0),0)
    else oi.quantity
  end)>0
  on conflict(order_id,product_id) do update
    set quantity=excluded.quantity,status='reserved',expires_at=excluded.expires_at,
        updated_at=now(),consumed_at=null,released_at=null;

  return jsonb_build_object('ok',true,
    'status',case
      when v_manual_replacement_count>0 and v_demand_count<=v_manual_replacement_count then 'manual_replacement_pending'
      when v_manual_replacement_count>0 then 'reserved_with_manual_replacements'
      else 'reserved'
    end,
    'manual_replacement_count',v_manual_replacement_count,'stock_authority',v_authority,
    'local_reservation_tracking',true,'physical_stock_changed',false);
end;
$function$
;

-- function: resolve_customer_by_phone_v1(p_phone text)
CREATE OR REPLACE FUNCTION public.resolve_customer_by_phone_v1(p_phone text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_phone text:=public.canonical_whatsapp_e164_br_v2(p_phone);
  v_ids uuid[];
  v_count integer:=0;
begin
  if v_phone is null then
    return jsonb_build_object('ok',false,'match_status','invalid','error','invalid_phone');
  end if;

  select coalesce(array_agg(x.customer_id order by x.customer_id),array[]::uuid[])
    into v_ids
    from public.customer_ids_by_phone_variants_v1(v_phone) x;
  v_count:=coalesce(array_length(v_ids,1),0);

  if v_count=0 then
    return jsonb_build_object('ok',true,'match_status','none','canonical_phone_e164',v_phone,'candidate_count',0);
  elsif v_count=1 then
    return jsonb_build_object('ok',true,'match_status','matched','canonical_phone_e164',v_phone,'candidate_count',1,'customer_id',v_ids[1]);
  end if;

  return jsonb_build_object('ok',true,'match_status','ambiguous','canonical_phone_e164',v_phone,'candidate_count',v_count);
end;
$function$
;

-- function: run_fiscal_ai_worker_tick_v1()
CREATE OR REPLACE FUNCTION public.run_fiscal_ai_worker_tick_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'net'
AS $function$
declare c public.fiscal_ai_worker_control%rowtype; n int; rid bigint;
begin
 select * into c from public.fiscal_ai_worker_control where id=true;
 if not coalesce(c.enabled,false) then return jsonb_build_object('ok',true,'state','disabled'); end if;
 update public.fiscal_ai_family_jobs set status='pending',error='auto_recovered_stale_processing',updated_at=now()
 where status='processing' and updated_at < now()-make_interval(mins=>c.stale_minutes) and attempt_count<c.max_attempts;
 update public.fiscal_ai_family_jobs set status='failed',error=coalesce(error,'')||' | max_attempts_exceeded',updated_at=now()
 where status in('pending','processing') and attempt_count>=c.max_attempts;
 select count(*) into n from public.fiscal_ai_family_jobs where status='pending';
 if n=0 then
   update public.fiscal_ai_worker_control set enabled=false,updated_at=now() where id=true;
   return jsonb_build_object('ok',true,'state','complete');
 end if;
 if exists(select 1 from public.fiscal_ai_family_jobs where status='processing') then
   return jsonb_build_object('ok',true,'state','busy','pending',n);
 end if;
 select net.http_post(
   url:='https://ssbesxgaijknwsjbsbcz.supabase.co/functions/v1/product-image-openai-v1',
   headers:=jsonb_build_object('Content-Type','application/json'),
   body:=jsonb_build_object('limit',least(c.batch_size,n)),
   timeout_milliseconds:=120000
 ) into rid;
 return jsonb_build_object('ok',true,'state','dispatched','request_id',rid,'pending_before',n);
end $function$
;

-- function: run_marketing_campaign_worker_tick_v1()
CREATE OR REPLACE FUNCTION public.run_marketing_campaign_worker_tick_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_locked boolean:=false;
  v_active_accounts integer:=0;
  v_secret text;
  v_tick_id uuid:=gen_random_uuid();
  v_request_id bigint;
begin
  select pg_try_advisory_xact_lock(hashtextextended('marketing-campaign-worker-v1',0)) into v_locked;
  if coalesce(v_locked,false) is not true then
    return jsonb_build_object('ok',true,'no_op',true,'reason','tick_already_running');
  end if;

  select count(*)::integer into v_active_accounts
  from public.marketing_campaign_execution_runtime_v1 e
  join public.whatsapp_channel_runtime_v1 r on r.whatsapp_account_id=e.whatsapp_account_id
  where e.mode in ('canary','live')
    and r.campaigns_enabled is true
    and r.send_enabled is true
    and r.outbound_provider='meta';

  if v_active_accounts=0 then
    return jsonb_build_object('ok',true,'no_op',true,'reason','campaigns_disabled','active_accounts',0);
  end if;

  v_secret:=public.marketing_campaign_worker_internal_key_v1();
  if nullif(btrim(coalesce(v_secret,'')),'') is null then
    return jsonb_build_object('ok',false,'error','worker_auth_unavailable');
  end if;

  select net.http_post(
    url:='https://ssbesxgaijknwsjbsbcz.supabase.co/functions/v1/whatsapp-marketing-worker-v1',
    headers:=jsonb_build_object(
      'Content-Type','application/json',
      'x-dona-antonia-marketing-worker-key',v_secret
    ),
    body:=jsonb_build_object('limit',10,'tick_id',v_tick_id::text),
    timeout_milliseconds:=55000
  ) into v_request_id;

  return jsonb_build_object(
    'ok',true,
    'no_op',false,
    'tick_id',v_tick_id,
    'request_id',v_request_id,
    'active_accounts',v_active_accounts
  );
end;
$function$
;

-- function: sales_quote_bling_claim_v1(p_quote_id uuid)
CREATE OR REPLACE FUNCTION public.sales_quote_bling_claim_v1(p_quote_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_quote public.sales_quotes%rowtype;
        v_link public.sales_quote_bling_orders%rowtype;
        v_key text;
begin
  select * into v_quote from public.sales_quotes
    where id=p_quote_id and archived_at is null for update;
  if not found then return jsonb_build_object('ok',false,'error','quote_not_found'); end if;
  select * into v_link from public.sales_quote_bling_orders where quote_id=p_quote_id for update;
  if found then
    return jsonb_build_object('ok',false,'error',case when v_link.status='synced' then 'already_synced' when v_link.status='processing' then 'conversion_in_progress' else 'manual_review_required' end,
      'status',v_link.status,'bling_order_id',v_link.bling_order_id,'external_key',v_link.external_key);
  end if;
  v_key:='ORC-'||substr(replace(p_quote_id::text,'-',''),1,20);
  insert into public.sales_quote_bling_orders(quote_id,external_key,status,attempt_count)
    values(p_quote_id,v_key,'processing',1);
  return jsonb_build_object('ok',true,'status','processing','external_key',v_key);
end $function$
;

-- function: save_assembly_kit_v1(p_kit_id uuid, p_name text, p_type text, p_notes text, p_source_kit_id uuid, p_items jsonb, p_operator text)
CREATE OR REPLACE FUNCTION public.save_assembly_kit_v1(p_kit_id uuid, p_name text, p_type text, p_notes text, p_source_kit_id uuid, p_items jsonb, p_operator text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_kit_id uuid;
  v_name text:=btrim(coalesce(p_name,''));
  v_type text:=btrim(coalesce(p_type,''));
  v_notes text:=nullif(btrim(coalesce(p_notes,'')),'');
  v_operator text:=coalesce(nullif(btrim(coalesce(p_operator,'')),''),'Operação');
  v_item jsonb;
  v_product_id uuid;
  v_qty numeric;
  v_saved public.assembly_kits%rowtype;
begin
  if length(v_name)<1 or length(v_name)>180 then raise exception 'assembly_kit_name_invalid'; end if;
  if v_type not in ('food','cleaning_hygiene','other') then raise exception 'assembly_kit_type_invalid'; end if;
  if jsonb_typeof(coalesce(p_items,'null'::jsonb))<>'array'
     or jsonb_array_length(p_items)<1
     or jsonb_array_length(p_items)>200 then
    raise exception 'assembly_kit_items_invalid';
  end if;
  if p_source_kit_id is not null and p_source_kit_id=p_kit_id then
    raise exception 'assembly_kit_source_self';
  end if;
  if p_source_kit_id is not null and not exists(
    select 1 from public.assembly_kits k where k.id=p_source_kit_id
  ) then
    raise exception 'assembly_kit_source_not_found';
  end if;

  for v_item in select value from jsonb_array_elements(p_items)
  loop
    begin
      v_product_id:=(v_item->>'product_id')::uuid;
      v_qty:=(v_item->>'quantity')::numeric;
    exception when others then
      raise exception 'assembly_kit_item_invalid';
    end;
    if v_qty<=0 or v_qty>999 then raise exception 'assembly_kit_item_quantity_invalid'; end if;
    if not exists(
      select 1 from public.products p where p.id=v_product_id and p.is_active=true
    ) then
      raise exception 'assembly_kit_product_unavailable:%',v_product_id;
    end if;
  end loop;

  if p_kit_id is null then
    insert into public.assembly_kits(name,type,notes,source_kit_id,is_active,metadata)
    values(v_name,v_type,v_notes,p_source_kit_id,true,
      jsonb_build_object('created_by',v_operator,'created_via','assembly_kit_builder_v1'))
    returning id into v_kit_id;
  else
    select k.id into v_kit_id
    from public.assembly_kits k
    where k.id=p_kit_id
    for update;
    if v_kit_id is null then raise exception 'assembly_kit_not_found'; end if;

    update public.assembly_kits
    set name=v_name,
        type=v_type,
        notes=v_notes,
        source_kit_id=p_source_kit_id,
        is_active=true,
        metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('updated_by',v_operator),
        updated_at=now()
    where id=v_kit_id;
  end if;

  delete from public.assembly_kit_items where kit_id=v_kit_id;

  insert into public.assembly_kit_items(kit_id,product_id,quantity,sort_order)
  select v_kit_id,product_id,sum(quantity)::numeric,min(sort_order)::integer
  from (
    select
      (e.value->>'product_id')::uuid as product_id,
      (e.value->>'quantity')::numeric as quantity,
      coalesce(nullif(e.value->>'sort_order','')::integer,e.ordinality::integer-1) as sort_order
    from jsonb_array_elements(p_items) with ordinality as e(value,ordinality)
  ) raw
  group by product_id;

  select * into v_saved from public.assembly_kits where id=v_kit_id;
  return jsonb_build_object(
    'ok',true,
    'kit',jsonb_build_object(
      'id',v_saved.id,'name',v_saved.name,'type',v_saved.type,'notes',v_saved.notes,
      'source_kit_id',v_saved.source_kit_id,'is_active',v_saved.is_active,
      'created_at',v_saved.created_at,'updated_at',v_saved.updated_at
    ),
    'items',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',i.id,'product_id',i.product_id,'quantity',i.quantity,'sort_order',i.sort_order
      ) order by i.sort_order,i.id)
      from public.assembly_kit_items i where i.kit_id=v_kit_id
    ),'[]'::jsonb),
    'item_count',(select count(*) from public.assembly_kit_items i where i.kit_id=v_kit_id)
  );
end;
$function$
;

-- function: save_basket_mold_v1(p_basket_id uuid, p_hidden_adjustment numeric, p_public_composition_count integer, p_positions jsonb, p_operator text)
CREATE OR REPLACE FUNCTION public.save_basket_mold_v1(p_basket_id uuid, p_hidden_adjustment numeric, p_public_composition_count integer, p_positions jsonb, p_operator text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_mold_id uuid;
  v_position jsonb;
  v_options jsonb;
  v_option jsonb;
  v_position_id uuid;
  v_product_id uuid;
  v_seen_products uuid[];
  v_label text;
  v_quantity numeric;
  v_position_order integer := 0;
  v_option_order integer;
begin
  if p_basket_id is null or not exists (
    select 1 from public.basket_templates b where b.id = p_basket_id
  ) then
    raise exception 'basket_mold_basket_not_found';
  end if;

  if p_public_composition_count is null or p_public_composition_count < 1 or p_public_composition_count > 6 then
    raise exception 'basket_mold_public_composition_count_invalid';
  end if;

  if p_positions is null or jsonb_typeof(p_positions) <> 'array' or jsonb_array_length(p_positions) = 0 then
    raise exception 'basket_mold_positions_required';
  end if;

  for v_position in select value from jsonb_array_elements(p_positions)
  loop
    v_label := btrim(coalesce(v_position->>'label', ''));
    if v_label = '' then
      raise exception 'basket_mold_position_label_required';
    end if;

    begin
      v_quantity := nullif(v_position->>'quantity', '')::numeric;
    exception when others then
      raise exception 'basket_mold_position_quantity_invalid';
    end;
    if v_quantity is null or v_quantity < 0 or v_quantity > 999 then
      raise exception 'basket_mold_position_quantity_invalid';
    end if;

    v_options := v_position->'options';
    if v_options is null or jsonb_typeof(v_options) <> 'array' or jsonb_array_length(v_options) = 0 then
      raise exception 'basket_mold_position_options_required';
    end if;

    v_seen_products := '{}'::uuid[];
    for v_option in select value from jsonb_array_elements(v_options)
    loop
      begin
        if jsonb_typeof(v_option) = 'string' then
          v_product_id := trim(both '"' from v_option::text)::uuid;
        else
          v_product_id := nullif(v_option->>'product_id', '')::uuid;
        end if;
      exception when others then
        raise exception 'basket_mold_product_invalid';
      end;

      if v_product_id is null or not exists (
        select 1 from public.products p where p.id = v_product_id
      ) then
        raise exception 'basket_mold_product_not_found';
      end if;

      if v_product_id = any(v_seen_products) then
        raise exception 'basket_mold_duplicate_option';
      end if;
      v_seen_products := array_append(v_seen_products, v_product_id);
    end loop;
  end loop;

  insert into public.basket_molds(
    basket_id, hidden_adjustment, public_composition_count, metadata
  ) values (
    p_basket_id,
    coalesce(p_hidden_adjustment, 0),
    p_public_composition_count,
    jsonb_build_object('domain_version', 1, 'updated_by', coalesce(nullif(btrim(p_operator), ''), 'Operação'))
  )
  on conflict (basket_id) do update
    set hidden_adjustment = excluded.hidden_adjustment,
        public_composition_count = excluded.public_composition_count,
        metadata = coalesce(public.basket_molds.metadata, '{}'::jsonb)
          || jsonb_build_object('domain_version', 1, 'updated_by', coalesce(nullif(btrim(p_operator), ''), 'Operação')),
        updated_at = now()
  returning id into v_mold_id;

  delete from public.basket_mold_positions where mold_id = v_mold_id;

  v_position_order := 0;
  for v_position in select value from jsonb_array_elements(p_positions)
  loop
    v_label := btrim(v_position->>'label');
    v_quantity := (v_position->>'quantity')::numeric;

    insert into public.basket_mold_positions(
      mold_id, label, quantity, sort_order, metadata
    ) values (
      v_mold_id,
      v_label,
      v_quantity,
      v_position_order,
      coalesce(v_position->'metadata', '{}'::jsonb)
    ) returning id into v_position_id;

    v_option_order := 0;
    for v_option in select value from jsonb_array_elements(v_position->'options')
    loop
      if jsonb_typeof(v_option) = 'string' then
        v_product_id := trim(both '"' from v_option::text)::uuid;
      else
        v_product_id := (v_option->>'product_id')::uuid;
      end if;

      insert into public.basket_mold_position_options(
        position_id, product_id, sort_order, metadata
      ) values (
        v_position_id,
        v_product_id,
        v_option_order,
        case when jsonb_typeof(v_option) = 'object'
          then coalesce(v_option->'metadata', '{}'::jsonb)
          else '{}'::jsonb
        end
      );
      v_option_order := v_option_order + 1;
    end loop;

    v_position_order := v_position_order + 1;
  end loop;

  return public.basket_mold_editor_v1(p_basket_id);
end;
$function$
;

-- function: search_whatsapp_sellable_products_v1(p_query text, p_limit integer)
CREATE OR REPLACE FUNCTION public.search_whatsapp_sellable_products_v1(p_query text, p_limit integer DEFAULT 8)
 RETURNS TABLE(id uuid, sku text, gtin text, name text, brand text, category text, packaging text, price numeric, stock numeric, image_url text, gondola text, shelf text, score integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
with q as (
  select translate(lower(trim(coalesce(p_query,''))),'áàãâäéèêëíìîïóòõôöúùûüç','aaaaaeeeeiiiiooooouuuuc') as term,
         greatest(1,least(coalesce(p_limit,8),20)) as lim
), normalized as (
  select p.*,
    translate(lower(coalesce(p.name,'')),'áàãâäéèêëíìîïóòõôöúùûüç','aaaaaeeeeiiiiooooouuuuc') as n_name,
    translate(lower(coalesce(p.brand,'')),'áàãâäéèêëíìîïóòõôöúùûüç','aaaaaeeeeiiiiooooouuuuc') as n_brand,
    translate(lower(coalesce(p.category,'')),'áàãâäéèêëíìîïóòõôöúùûüç','aaaaaeeeeiiiiooooouuuuc') as n_category
  from public.products p
  where p.physically_verified=true
    and p.is_active=true
   
    and p.price is not null
    and p.price>=0
    and coalesce(p.stock,0)>0
), ranked as (
  select p.id,p.sku,p.gtin,p.name,p.brand,p.category,p.packaging,p.price,p.stock,p.image_url,p.gondola,p.shelf,
    case
      when q.term<>'' and lower(coalesce(p.gtin,''))=q.term then 100
      when q.term<>'' and lower(coalesce(p.sku,''))=q.term then 98
      when q.term<>'' and p.n_name=q.term then 96
      when q.term<>'' and p.n_name like q.term||'%' then 94
      when q.term<>'' and strpos(p.n_name,q.term) between 1 and 14 then 90
      when q.term<>'' and p.n_name like '%'||q.term||'%' then 80
      when q.term<>'' and p.n_brand like '%'||q.term||'%' then 70
      when q.term<>'' and p.n_category like '%'||q.term||'%' then 60
      else 10
    end as score,
    case when q.term='' then 9999 else nullif(strpos(p.n_name,q.term),0) end as term_position,
    p.sort_order
  from normalized p cross join q
  where q.term=''
     or lower(coalesce(p.gtin,''))=q.term
     or lower(coalesce(p.sku,''))=q.term
     or p.n_name like '%'||q.term||'%'
     or p.n_brand like '%'||q.term||'%'
     or p.n_category like '%'||q.term||'%'
)
select r.id,r.sku,r.gtin,r.name,r.brand,r.category,r.packaging,r.price,r.stock,r.image_url,r.gondola,r.shelf,r.score
from ranked r cross join q
order by r.score desc,r.term_position nulls last,r.sort_order nulls last,r.name,r.id
limit (select lim from q)
$function$
;

-- function: set_bling_api_refresh_token_v1(p_refresh_token text)
CREATE OR REPLACE FUNCTION public.set_bling_api_refresh_token_v1(p_refresh_token text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid;
begin
  if nullif(trim(coalesce(p_refresh_token,'')),'') is null then
    raise exception 'refresh_token_required';
  end if;

  select id into v_id
  from vault.secrets
  where name='bling_api_refresh_token_v1'
  order by updated_at desc
  limit 1;

  if v_id is null then
    perform vault.create_secret(
      trim(p_refresh_token),
      'bling_api_refresh_token_v1',
      'Refresh token Bling API V3 rotacionado automaticamente pelo importador historico',
      null
    );
  else
    perform vault.update_secret(
      v_id,
      trim(p_refresh_token),
      'bling_api_refresh_token_v1',
      'Refresh token Bling API V3 rotacionado automaticamente pelo importador historico',
      null
    );
  end if;
  return true;
end
$function$
;

-- function: set_bling_hub_order_rollout_v2(p_state text, p_details jsonb, p_disable_orders boolean)
CREATE OR REPLACE FUNCTION public.set_bling_hub_order_rollout_v2(p_state text, p_details jsonb DEFAULT '{}'::jsonb, p_disable_orders boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_runtime jsonb;
  v_rollout jsonb;
begin
  if nullif(trim(coalesce(p_state,'')),'') is null then
    raise exception 'order_rollout_state_required';
  end if;

  v_rollout=jsonb_build_object('state',trim(p_state))
    ||coalesce(p_details,'{}'::jsonb);

  update public.bling_hub_runtime_v2
  set orders_enabled=case when p_disable_orders then false else orders_enabled end,
      metadata=jsonb_set(coalesce(metadata,'{}'::jsonb),'{order_rollout}',v_rollout,true),
      updated_at=now()
  where id=1
  returning jsonb_build_object(
    'orders_enabled',orders_enabled,
    'order_rollout',metadata->'order_rollout'
  ) into v_runtime;

  if v_runtime is null then
    raise exception 'bling_hub_runtime_missing';
  end if;
  return v_runtime;
end
$function$
;

-- function: set_cart_addon_quantity(p_cart_id uuid, p_product_id uuid, p_quantity numeric)
CREATE OR REPLACE FUNCTION public.set_cart_addon_quantity(p_cart_id uuid, p_product_id uuid, p_quantity numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_price numeric;
  v_stock integer;
  v_limit integer;
begin
  if p_quantity is null or p_quantity<0 or trunc(p_quantity)<>p_quantity then raise exception 'invalid_quantity'; end if;
  if p_quantity>6 then raise exception 'quantity_exceeds_customer_limit'; end if;
  perform 1 from public.carts where id=p_cart_id and status='draft';
  if not found then raise exception 'cart_not_editable'; end if;

  select price,greatest(0,floor(coalesce(stock,0))::integer)
    into v_price,v_stock
    from public.products
   where id=p_product_id
     and is_active=true
     and coalesce(price,0)>0;
  if not found then raise exception 'product_not_available'; end if;

  v_limit:=least(6,v_stock);
  if p_quantity>v_limit then raise exception 'quantity_exceeds_stock'; end if;

  delete from public.cart_items where cart_id=p_cart_id and product_id=p_product_id and source='addon';
  if p_quantity>0 then
    insert into public.cart_items(cart_id,product_id,source,quantity,unit_price,line_total,commercial_unit_price,metadata)
    values(p_cart_id,p_product_id,'addon',p_quantity,coalesce(v_price,0),p_quantity*coalesce(v_price,0),coalesce(v_price,0),
      jsonb_build_object('pricing_source','product_price','source','whatsapp_flow','customer_quantity_cap',6,'stock_at_write',v_stock));
  end if;
  return public.recalculate_cart(p_cart_id);
end;
$function$
;

-- function: set_updated_at()
CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$
;

-- function: si5_research_reserve_next()
CREATE OR REPLACE FUNCTION public.si5_research_reserve_next()
 RETURNS TABLE(request_id bigint, selected_product_id uuid, selected_gtin text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
 cfg record;
 slot_count integer;
 chosen record;
 today_brasilia date := (now() at time zone 'America/Sao_Paulo')::date;
begin
 select enabled,daily_limit,research_mode into cfg
 from public.si5_research_config where id=true for update;
 if not found or not cfg.enabled then return; end if;
 select count(*) into slot_count
 from public.si5_research_requests where quota_date=today_brasilia;
 if slot_count>=cfg.daily_limit then return; end if;

 -- Recolocar em espera reservas abandonadas sem devolver a franquia consumida.
 update public.si5_product_research r
 set status='retry',retry_after=now()+interval '24 hours',
     last_error='abandoned_reservation',updated_at=now()
 where r.status='reserved'
   and r.last_attempt_at<now()-interval '45 minutes';

 select r.product_id,r.gtin into chosen
 from public.si5_product_research r
 join public.products p on p.id=r.product_id
 left join public.cosmos_family_representatives_v2 rep
   on rep.representative_product_id=r.product_id
 where p.is_active and trim(p.gtin)=r.gtin
   and public.cosmos_gtin_valid(r.gtin)
   and (cfg.research_mode='full' or rep.representative_product_id is not null)
   and r.status in ('pending','retry')
   and (r.retry_after is null or r.retry_after<=now())
 order by case when rep.representative_product_id is not null then 0 else 1 end,
          r.created_at,r.product_id
 for update of r skip locked limit 1;
 if not found then return; end if;

 insert into public.si5_research_requests(quota_date,quota_slot,product_id,gtin)
 values(today_brasilia,slot_count+1,chosen.product_id,chosen.gtin)
 returning id into request_id;
 update public.si5_product_research set status='reserved',
    last_attempt_at=now(),updated_at=now()
 where product_id=chosen.product_id;
 selected_product_id:=chosen.product_id;
 selected_gtin:=chosen.gtin;
 return next;
end $function$
;

-- function: site_admin_marketing_campaign_report_summary_v1(p_campaign_id uuid)
CREATE OR REPLACE FUNCTION public.site_admin_marketing_campaign_report_summary_v1(p_campaign_id uuid)
 RETURNS TABLE(total bigint, accepted bigint, sent bigint, delivered bigint, read_count bigint, failed bigint, pending bigint, uncertain bigint, skipped bigint, delivery_rate numeric, read_rate numeric, responses bigint, response_rate numeric, response_window_hours integer, response_measurement_available boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with campaign as (
    select c.id, c.whatsapp_account_id
    from public.marketing_campaigns_v1 c
    where c.id = p_campaign_id
  ),
  dispatches as (
    select
      d.id,
      d.customer_id,
      d.status as dispatch_status,
      o.message_id
    from public.marketing_campaign_dispatches_v1 d
    left join public.whatsapp_outbox_v1 o on o.id = d.outbox_id
    where d.campaign_id = p_campaign_id
  ),
  campaign_message_ids as (
    select distinct d.message_id
    from dispatches d
    where d.message_id is not null
  ),
  latest_meta_status as (
    select distinct on (e.message_id)
      e.message_id,
      e.status
    from public.whatsapp_message_status_events_v1 e
    join campaign_message_ids ids on ids.message_id = e.message_id
    where e.provider = 'meta'
    order by
      e.message_id,
      e.occurred_at desc nulls last,
      case e.status
        when 'read' then 60
        when 'delivered' then 50
        when 'sent' then 40
        when 'failed' then 35
        when 'accepted' then 30
        when 'sending' then 20
        when 'queued' then 10
        else 0
      end desc,
      e.received_at desc nulls last,
      e.id desc
  ),
  delivery_counts as (
    select
      count(distinct d.id) as total,
      count(distinct d.id) filter (where d.dispatch_status = 'accepted') as accepted,
      count(distinct d.message_id) filter (
        where coalesce(latest.status, m.status_current) = 'sent'
      ) as sent_status_count,
      count(distinct d.message_id) filter (
        where coalesce(latest.status, m.status_current) = 'delivered'
      ) as delivered_status_count,
      count(distinct d.message_id) filter (
        where coalesce(latest.status, m.status_current) = 'read'
      ) as read_count,
      count(distinct d.id) filter (
        where d.dispatch_status = 'failed'
           or coalesce(latest.status, m.status_current) = 'failed'
      ) as failed,
      count(distinct d.id) filter (
        where d.dispatch_status = 'skipped'
      ) as skipped,
      count(distinct d.id) filter (
        where d.dispatch_status in ('pending', 'claimed', 'retry')
      ) as pending,
      count(distinct d.id) filter (
        where d.dispatch_status = 'uncertain'
      ) as uncertain
    from dispatches d
    left join public.whatsapp_messages_v1 m on m.id = d.message_id
    left join latest_meta_status latest on latest.message_id = d.message_id
  ),
  send_times as (
    select
      d.customer_id,
      coalesce(m.sent_at, status_times.sent_at) as sent_at
    from dispatches d
    left join public.whatsapp_messages_v1 m on m.id = d.message_id
    left join lateral (
      select min(e.occurred_at) as sent_at
      from public.whatsapp_message_status_events_v1 e
      where e.message_id = d.message_id
        and e.provider = 'meta'
        and e.status in ('sent', 'delivered', 'read')
        and e.occurred_at is not null
    ) status_times on true
    where d.dispatch_status = 'accepted'
  ),
  response_counts as (
    select
      count(*) as accepted_dispatches,
      count(*) filter (
        where s.sent_at is null or s.customer_id is null
      ) as incomplete_dispatches,
      count(distinct s.customer_id) filter (
        where s.sent_at is not null and s.customer_id is not null
      ) as sent_customers,
      count(distinct s.customer_id) filter (
        where s.sent_at is not null
          and s.customer_id is not null
          and exists (
            select 1
            from public.whatsapp_messages_v1 reply
            where reply.customer_id = s.customer_id
              and reply.whatsapp_account_id = c.whatsapp_account_id
              and reply.provider = 'meta'
              and reply.direction = 'inbound'
              and reply.created_at >= s.sent_at
              and reply.created_at <= s.sent_at + interval '48 hours'
              and coalesce(reply.received_at, reply.created_at) >= s.sent_at
              and coalesce(reply.received_at, reply.created_at) <= s.sent_at + interval '48 hours'
          )
      ) as responses
    from send_times s
    cross join campaign c
  ),
  totals as (
    select
      counts.total,
      counts.accepted,
      counts.sent_status_count + counts.delivered_status_count + counts.read_count as sent,
      counts.delivered_status_count + counts.read_count as delivered,
      counts.read_count,
      counts.failed,
      counts.pending,
      counts.uncertain,
      counts.skipped
    from delivery_counts counts
  )
  select
    totals.total,
    totals.accepted,
    totals.sent,
    totals.delivered,
    totals.read_count,
    totals.failed,
    totals.pending,
    totals.uncertain,
    totals.skipped,
    case
      when totals.sent > 0
        then round(totals.delivered::numeric * 100 / totals.sent, 1)
      else 0::numeric
    end as delivery_rate,
    case
      when totals.delivered > 0
        then round(totals.read_count::numeric * 100 / totals.delivered, 1)
      else 0::numeric
    end as read_rate,
    case
      when response_counts.accepted_dispatches > 0
        and response_counts.incomplete_dispatches = 0
        and response_counts.sent_customers > 0
        then response_counts.responses
      else 0::bigint
    end as responses,
    case
      when response_counts.accepted_dispatches > 0
        and response_counts.incomplete_dispatches = 0
        and response_counts.sent_customers > 0
        then round(response_counts.responses::numeric * 100 / response_counts.sent_customers, 1)
      else 0::numeric
    end as response_rate,
    48 as response_window_hours,
    (
      response_counts.accepted_dispatches > 0
      and response_counts.incomplete_dispatches = 0
      and response_counts.sent_customers > 0
    ) as response_measurement_available
  from totals
  cross join response_counts;
$function$
;

-- function: site_admin_marketing_campaign_status_summary_v1(p_campaign_ids uuid[])
CREATE OR REPLACE FUNCTION public.site_admin_marketing_campaign_status_summary_v1(p_campaign_ids uuid[])
 RETURNS TABLE(campaign_id uuid, accepted_count bigint, sent_count bigint, delivered_count bigint, read_count bigint, failed_count bigint, skipped_count bigint, pending_count bigint, uncertain_count bigint, snapshot_available boolean, snapshot_id uuid, snapshot_campaign_revision integer, snapshot_version integer, snapshot_template_name text, snapshot_template_language text, snapshot_template_category text, snapshot_found_count bigint, snapshot_eligible_count bigint, snapshot_excluded_count bigint, currently_verified_consent_count bigint, excluded_opted_out_count bigint, excluded_consent_evidence_unverified_count bigint, excluded_no_consent_count bigint, excluded_inactive_customer_count bigint, excluded_invalid_phone_count bigint, excluded_duplicate_phone_count bigint, snapshot_created_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with requested as (
    select distinct unnest(coalesce(p_campaign_ids, array[]::uuid[])) as campaign_id
  ),
  campaign_messages as (
    select
      d.campaign_id,
      d.id as dispatch_id,
      d.status as dispatch_status,
      o.message_id
    from public.marketing_campaign_dispatches_v1 d
    left join public.whatsapp_outbox_v1 o on o.id = d.outbox_id
    where d.campaign_id = any(coalesce(p_campaign_ids, array[]::uuid[]))
  ),
  latest_meta_status as (
    select distinct on (e.message_id)
      e.message_id,
      e.status
    from public.whatsapp_message_status_events_v1 e
    join (
      select distinct message_id
      from campaign_messages
      where message_id is not null
    ) campaign_message_ids on campaign_message_ids.message_id = e.message_id
    where e.provider = 'meta'
    order by
      e.message_id,
      e.occurred_at desc nulls last,
      case e.status
        when 'read' then 60
        when 'delivered' then 50
        when 'sent' then 40
        when 'failed' then 35
        when 'accepted' then 30
        when 'sending' then 20
        when 'queued' then 10
        else 0
      end desc,
      e.received_at desc nulls last,
      e.id desc
  ),
  delivery_summary as (
    select
      campaign_messages.campaign_id,
      count(distinct campaign_messages.dispatch_id) filter (where campaign_messages.dispatch_status = 'accepted') as accepted_count,
      count(distinct campaign_messages.message_id) filter (where coalesce(latest_meta_status.status, messages.status_current) = 'sent') as sent_count,
      count(distinct campaign_messages.message_id) filter (where coalesce(latest_meta_status.status, messages.status_current) = 'delivered') as delivered_count,
      count(distinct campaign_messages.message_id) filter (where coalesce(latest_meta_status.status, messages.status_current) = 'read') as read_count,
      count(distinct campaign_messages.dispatch_id) filter (
        where campaign_messages.dispatch_status = 'failed'
          or coalesce(latest_meta_status.status, messages.status_current) = 'failed'
      ) as failed_count,
      count(distinct campaign_messages.dispatch_id) filter (where campaign_messages.dispatch_status = 'skipped') as skipped_count,
      count(distinct campaign_messages.dispatch_id) filter (where campaign_messages.dispatch_status in ('pending', 'claimed', 'retry')) as pending_count,
      count(distinct campaign_messages.dispatch_id) filter (where campaign_messages.dispatch_status = 'uncertain') as uncertain_count
    from campaign_messages
    left join public.whatsapp_messages_v1 messages on messages.id = campaign_messages.message_id
    left join latest_meta_status on latest_meta_status.message_id = campaign_messages.message_id
    group by campaign_messages.campaign_id
  ),
  latest_snapshots as (
    select distinct on (s.campaign_id)
      s.campaign_id,
      s.id,
      s.campaign_revision,
      s.snapshot_version,
      s.template_name,
      s.template_language,
      s.template_category,
      s.found_count,
      s.eligible_count,
      s.excluded_count,
      s.created_at
    from public.marketing_campaign_snapshots_v1 s
    where s.campaign_id = any(coalesce(p_campaign_ids, array[]::uuid[]))
    order by s.campaign_id, s.created_at desc, s.snapshot_version desc, s.id desc
  ),
  exclusion_summary as (
    select
      s.campaign_id,
      s.id as snapshot_id,
      count(distinct r.id) filter (where 'opted_out' = any(coalesce(r.exclusion_reasons, array[]::text[]))) as opted_out_count,
      count(distinct r.id) filter (where 'consent_evidence_unverified' = any(coalesce(r.exclusion_reasons, array[]::text[]))) as consent_evidence_unverified_count,
      count(distinct r.id) filter (where r.eligible_at_snapshot is true and public.marketing_has_verified_campaign_consent_v1(r.customer_id)) as currently_verified_consent_count,
      count(distinct r.id) filter (where 'no_consent' = any(coalesce(r.exclusion_reasons, array[]::text[]))) as no_consent_count,
      count(distinct r.id) filter (where 'inactive_customer' = any(coalesce(r.exclusion_reasons, array[]::text[]))) as inactive_customer_count,
      count(distinct r.id) filter (where 'invalid_phone' = any(coalesce(r.exclusion_reasons, array[]::text[]))) as invalid_phone_count,
      count(distinct r.id) filter (where 'duplicate_phone' = any(coalesce(r.exclusion_reasons, array[]::text[]))) as duplicate_phone_count
    from latest_snapshots s
    left join public.marketing_campaign_snapshot_recipients_v1 r on r.snapshot_id = s.id
    group by s.campaign_id, s.id
  )
  select
    requested.campaign_id,
    coalesce(delivery_summary.accepted_count, 0)::bigint,
    coalesce(delivery_summary.sent_count, 0)::bigint,
    coalesce(delivery_summary.delivered_count, 0)::bigint,
    coalesce(delivery_summary.read_count, 0)::bigint,
    coalesce(delivery_summary.failed_count, 0)::bigint,
    coalesce(delivery_summary.skipped_count, 0)::bigint,
    coalesce(delivery_summary.pending_count, 0)::bigint,
    coalesce(delivery_summary.uncertain_count, 0)::bigint,
    latest_snapshots.id is not null,
    latest_snapshots.id,
    latest_snapshots.campaign_revision,
    latest_snapshots.snapshot_version,
    latest_snapshots.template_name,
    latest_snapshots.template_language,
    latest_snapshots.template_category,
    coalesce(latest_snapshots.found_count, 0)::bigint,
    coalesce(latest_snapshots.eligible_count, 0)::bigint,
    coalesce(latest_snapshots.excluded_count, 0)::bigint,
    coalesce(exclusion_summary.currently_verified_consent_count, 0)::bigint,
    coalesce(exclusion_summary.opted_out_count, 0)::bigint,
    coalesce(exclusion_summary.consent_evidence_unverified_count, 0)::bigint,
    coalesce(exclusion_summary.no_consent_count, 0)::bigint,
    coalesce(exclusion_summary.inactive_customer_count, 0)::bigint,
    coalesce(exclusion_summary.invalid_phone_count, 0)::bigint,
    coalesce(exclusion_summary.duplicate_phone_count, 0)::bigint,
    latest_snapshots.created_at
  from requested
  left join delivery_summary on delivery_summary.campaign_id = requested.campaign_id
  left join latest_snapshots on latest_snapshots.campaign_id = requested.campaign_id
  left join exclusion_summary on exclusion_summary.campaign_id = latest_snapshots.campaign_id
    and exclusion_summary.snapshot_id = latest_snapshots.id
  order by requested.campaign_id;
$function$
;

-- function: site_admin_save_basket_default_prices_v1(p_basket_prices jsonb)
CREATE OR REPLACE FUNCTION public.site_admin_save_basket_default_prices_v1(p_basket_prices jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_role text := coalesce(auth.jwt() ->> 'role', '');
  v_entry record;
  v_basket_id uuid;
  v_price_text text;
  v_updated integer := 0;
BEGIN
  IF v_role <> 'service_role' THEN
    RAISE EXCEPTION 'site_admin_service_role_required' USING ERRCODE = '42501';
  END IF;
  IF p_basket_prices IS NULL OR jsonb_typeof(p_basket_prices) <> 'object' THEN
    RAISE EXCEPTION 'site_basket_default_price_invalid';
  END IF;

  FOR v_entry IN
    SELECT key, value
    FROM jsonb_each(p_basket_prices) AS prices(key, value)
  LOOP
    BEGIN
      v_basket_id := v_entry.key::uuid;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'site_basket_default_price_invalid';
    END;

    v_price_text := v_entry.value #>> '{}';
    IF v_price_text IS NULL
       OR v_price_text !~ '^[0-9]{1,9}$'
       OR v_price_text::numeric > 100000000 THEN
      RAISE EXCEPTION 'site_basket_default_price_invalid';
    END IF;

    UPDATE public.basket_molds
    SET metadata = coalesce(metadata, '{}'::jsonb)
          || jsonb_build_object('site_admin_default_price_cents', v_price_text::bigint),
        updated_at = now()
    WHERE basket_id = v_basket_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'site_basket_default_price_invalid';
    END IF;
    v_updated := v_updated + 1;
  END LOOP;

  IF v_updated = 0 THEN
    RAISE EXCEPTION 'site_basket_default_price_invalid';
  END IF;

  RETURN jsonb_build_object('fixed_default_prices_saved', v_updated);
END;
$function$
;

-- function: site_admin_save_basket_grid_v1(p_rows jsonb, p_operator text)
CREATE OR REPLACE FUNCTION public.site_admin_save_basket_grid_v1(p_rows jsonb, p_operator text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_role text := coalesce(auth.jwt() ->> 'role', '');
  v_row jsonb;
  v_option jsonb;
  v_option_map jsonb;
  v_option_count integer;
  v_unique_option_count integer;
  v_existing_product_count integer;
  v_total_product_count integer;
  v_option_quantity_key_count integer;
  v_row_id uuid;
  v_session_id uuid;
  v_title text;
  v_options jsonb;
  v_quantities jsonb;
  v_quantity_text text;
  v_option_quantity_text text;
  v_quantity numeric;
  v_option_quantity numeric;
  v_option_total numeric;
  v_basket record;
  v_row_order integer := 0;
  v_basket_count integer := 0;
  v_type_count integer := 0;
  v_positive_count integer := 0;
  v_positions jsonb;
BEGIN
  IF v_role <> 'service_role' THEN
    RAISE EXCEPTION 'site_admin_service_role_required' USING ERRCODE = '42501';
  END IF;
  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN
    RAISE EXCEPTION 'site_basket_grid_rows_invalid';
  END IF;
  IF jsonb_array_length(p_rows) < 1 THEN
    RAISE EXCEPTION 'site_basket_grid_rows_invalid';
  END IF;

  CREATE TEMP TABLE pg_temp._site_basket_grid_baskets ON COMMIT DROP AS
  SELECT basket.id AS basket_id, mold.id AS mold_id, mold.hidden_adjustment, 1::integer AS public_composition_count,
         basket.sort_order, basket.name
  FROM public.basket_templates basket
  JOIN public.basket_categories category ON category.id = basket.category_id
  JOIN public.basket_molds mold ON mold.basket_id = basket.id
  WHERE basket.is_active IS TRUE AND category.slug = 'cestas-completas'
  ORDER BY basket.sort_order, basket.name;
  SELECT count(*) INTO v_basket_count FROM pg_temp._site_basket_grid_baskets;
  IF v_basket_count < 1 THEN RAISE EXCEPTION 'site_basket_grid_baskets_missing'; END IF;

  CREATE TEMP TABLE pg_temp._site_basket_grid_rows (
    type_id uuid PRIMARY KEY,
    session_id uuid NOT NULL,
    row_order integer NOT NULL,
    title text NOT NULL,
    options jsonb NOT NULL,
    quantities jsonb NOT NULL
  ) ON COMMIT DROP;

  FOR v_row IN SELECT value FROM jsonb_array_elements(p_rows)
  LOOP
    v_row_id := coalesce(nullif(btrim(v_row->>'id'), '')::uuid, gen_random_uuid());
    v_session_id := coalesce(nullif(btrim(v_row->>'session_id'), '')::uuid, v_row_id);
    v_title := btrim(coalesce(v_row->>'title', ''));
    v_options := v_row->'options';
    v_quantities := v_row->'quantities';
    IF v_title = '' OR char_length(v_title) > 180 OR v_options IS NULL OR v_quantities IS NULL THEN
      RAISE EXCEPTION 'site_basket_grid_type_invalid';
    END IF;
    IF jsonb_typeof(v_options) <> 'array' OR jsonb_typeof(v_quantities) <> 'object' THEN
      RAISE EXCEPTION 'site_basket_grid_type_invalid';
    END IF;
    IF jsonb_array_length(v_options) < 1 OR jsonb_array_length(v_options) > 500
       OR (SELECT count(*) FROM jsonb_object_keys(v_quantities)) <> v_basket_count THEN
      RAISE EXCEPTION 'site_basket_grid_type_invalid';
    END IF;

    SELECT count(*), count(DISTINCT (option.value->>'product_id')::uuid)
      INTO v_option_count, v_unique_option_count
    FROM jsonb_array_elements(v_options) AS option(value);
    IF v_option_count <> v_unique_option_count THEN RAISE EXCEPTION 'site_basket_grid_option_invalid'; END IF;

    FOR v_option IN SELECT value FROM jsonb_array_elements(v_options)
    LOOP
      v_option_map := v_option->'quantities';
      IF jsonb_typeof(v_option_map) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'site_basket_grid_option_quantities_invalid';
      END IF;
      SELECT count(*) INTO v_option_quantity_key_count
      FROM jsonb_object_keys(v_option_map) AS keys(key_name);
      IF v_option_quantity_key_count <> v_basket_count OR EXISTS (
        SELECT 1 FROM jsonb_object_keys(v_option_map) AS keys(key_name)
        WHERE NOT EXISTS (
          SELECT 1 FROM pg_temp._site_basket_grid_baskets basket
          WHERE basket.basket_id::text = keys.key_name
        )
      ) THEN RAISE EXCEPTION 'site_basket_grid_option_quantities_invalid'; END IF;
    END LOOP;

    FOR v_basket IN SELECT basket_id FROM pg_temp._site_basket_grid_baskets
    LOOP
      IF NOT (v_quantities ? v_basket.basket_id::text) THEN
        RAISE EXCEPTION 'site_basket_grid_quantity_missing';
      END IF;
      v_quantity_text := v_quantities->>v_basket.basket_id::text;
      IF v_quantity_text IS NULL OR v_quantity_text !~ '^[0-9]+$' THEN
        RAISE EXCEPTION 'site_basket_grid_quantity_invalid';
      END IF;
      v_quantity := v_quantity_text::numeric;
      IF v_quantity < 0 OR v_quantity > 999 THEN RAISE EXCEPTION 'site_basket_grid_quantity_invalid'; END IF;

      v_option_total := 0;
      FOR v_option IN SELECT value FROM jsonb_array_elements(v_options)
      LOOP
        v_option_quantity_text := (v_option->'quantities')->>v_basket.basket_id::text;
        IF v_option_quantity_text IS NULL OR v_option_quantity_text !~ '^[0-9]+$' THEN
          RAISE EXCEPTION 'site_basket_grid_option_quantity_invalid';
        END IF;
        v_option_quantity := v_option_quantity_text::numeric;
        IF v_option_quantity < 0 OR v_option_quantity > 999 THEN
          RAISE EXCEPTION 'site_basket_grid_option_quantity_invalid';
        END IF;
        v_option_total := v_option_total + v_option_quantity;
      END LOOP;
      IF v_option_total <> v_quantity OR v_option_total > 999 THEN
        RAISE EXCEPTION 'site_basket_grid_quantity_mismatch';
      END IF;
    END LOOP;

    INSERT INTO pg_temp._site_basket_grid_rows(type_id,session_id,row_order,title,options,quantities)
    VALUES(v_row_id,v_session_id,v_row_order,v_title,v_options,v_quantities);
    v_row_order := v_row_order + 1;
  END LOOP;
  v_type_count := v_row_order;

  IF EXISTS (
    SELECT 1 FROM pg_temp._site_basket_grid_rows
    GROUP BY session_id
    HAVING count(*) <> 1
  ) THEN RAISE EXCEPTION 'site_basket_grid_session_invalid'; END IF;

  SELECT count(DISTINCT (option.value->>'product_id')::uuid)
    INTO v_total_product_count
  FROM pg_temp._site_basket_grid_rows grid_row
  CROSS JOIN LATERAL jsonb_array_elements(grid_row.options) AS option(value);
  SELECT count(*) INTO v_existing_product_count
  FROM public.products product
  WHERE product.id IN (
    SELECT DISTINCT (option.value->>'product_id')::uuid
    FROM pg_temp._site_basket_grid_rows grid_row
    CROSS JOIN LATERAL jsonb_array_elements(grid_row.options) AS option(value)
  );
  IF v_existing_product_count <> v_total_product_count THEN RAISE EXCEPTION 'site_basket_grid_product_not_found'; END IF;

  SELECT count(*) INTO v_positive_count
  FROM pg_temp._site_basket_grid_baskets basket
  WHERE EXISTS (
    SELECT 1 FROM pg_temp._site_basket_grid_rows grid_row
    WHERE (grid_row.quantities->>basket.basket_id::text)::numeric > 0
  );
  IF v_positive_count <> v_basket_count THEN RAISE EXCEPTION 'site_basket_grid_empty_basket'; END IF;

  DELETE FROM public.site_basket_product_types product_type
  WHERE NOT EXISTS (
    SELECT 1 FROM pg_temp._site_basket_grid_rows grid_row WHERE grid_row.type_id = product_type.id
  );
  INSERT INTO public.site_basket_product_types(id,title,session_id,slot_order,sort_order,updated_at)
  SELECT type_id,title,session_id,1,row_order,now()
  FROM pg_temp._site_basket_grid_rows
  ON CONFLICT (id) DO UPDATE SET
    title=EXCLUDED.title,session_id=EXCLUDED.session_id,slot_order=1,
    sort_order=EXCLUDED.sort_order,updated_at=now();

  DELETE FROM public.site_basket_product_type_options option
  USING pg_temp._site_basket_grid_rows grid_row
  WHERE option.product_type_id=grid_row.type_id;
  INSERT INTO public.site_basket_product_type_options(product_type_id,product_id,sort_order,metadata,updated_at)
  SELECT grid_row.type_id,(option.value->>'product_id')::uuid,(option.ordinality-1)::integer,
    (CASE WHEN jsonb_typeof(option.value->'metadata')='object'
      THEN option.value->'metadata' ELSE '{}'::jsonb END)
      - 'preferred' - 'base_quantity' - 'quantities' - 'basket_quantities',
    now()
  FROM pg_temp._site_basket_grid_rows grid_row
  CROSS JOIN LATERAL jsonb_array_elements(grid_row.options) WITH ORDINALITY AS option(value,ordinality);

  DELETE FROM public.site_basket_product_type_quantities quantity
  USING pg_temp._site_basket_grid_baskets basket
  WHERE quantity.basket_id=basket.basket_id;
  INSERT INTO public.site_basket_product_type_quantities(product_type_id,basket_id,quantity,updated_at)
  SELECT grid_row.type_id,basket.basket_id,(grid_row.quantities->>basket.basket_id::text)::integer,now()
  FROM pg_temp._site_basket_grid_rows grid_row
  CROSS JOIN pg_temp._site_basket_grid_baskets basket;

  DELETE FROM public.site_basket_product_type_option_quantities quantity
  USING pg_temp._site_basket_grid_baskets basket
  WHERE quantity.basket_id=basket.basket_id;
  INSERT INTO public.site_basket_product_type_option_quantities(product_type_id,product_id,basket_id,quantity,updated_at)
  SELECT grid_row.type_id,(option.value->>'product_id')::uuid,basket.basket_id,
    ((option.value->'quantities')->>basket.basket_id::text)::integer,now()
  FROM pg_temp._site_basket_grid_rows grid_row
  CROSS JOIN LATERAL jsonb_array_elements(grid_row.options) AS option(value)
  CROSS JOIN pg_temp._site_basket_grid_baskets basket;

  FOR v_basket IN SELECT * FROM pg_temp._site_basket_grid_baskets ORDER BY sort_order,name
  LOOP
    SELECT coalesce(jsonb_agg(jsonb_build_object(
      'label',grid_row.title,
      'quantity',(grid_row.quantities->>v_basket.basket_id::text)::integer,
      'sort_order',grid_row.row_order,
      'metadata',coalesce(current_position.metadata,'{}'::jsonb)
        || jsonb_build_object(
          'site_basket_product_type_id',grid_row.type_id,
          'site_basket_product_session_id',grid_row.session_id,
          'site_basket_product_slot_order',1
        ),
      'options',coalesce((
        SELECT jsonb_agg(jsonb_build_object(
          'product_id',configured_option.product_id,
          'sort_order',configured_option.sort_order,
          'metadata',(
            coalesce(current_option.metadata,configured_option.metadata,'{}'::jsonb)
              - 'preferred' - 'base_quantity' - 'manual_replacement_required' - 'manual_replacement_reason'
          ) || jsonb_build_object('base_quantity',coalesce(option_quantity.quantity,0))
        ) ORDER BY configured_option.sort_order,configured_option.product_id)
        FROM public.site_basket_product_type_options configured_option
        LEFT JOIN public.basket_mold_position_options current_option
          ON current_option.position_id=current_position.position_id
         AND current_option.product_id=configured_option.product_id
        LEFT JOIN public.site_basket_product_type_option_quantities option_quantity
          ON option_quantity.product_type_id=configured_option.product_type_id
         AND option_quantity.product_id=configured_option.product_id
         AND option_quantity.basket_id=v_basket.basket_id
        WHERE configured_option.product_type_id=grid_row.type_id
      ),'[]'::jsonb)
    ) ORDER BY grid_row.row_order),'[]'::jsonb)
    INTO v_positions
    FROM pg_temp._site_basket_grid_rows grid_row
    LEFT JOIN LATERAL(
      SELECT position.id AS position_id,position.metadata
      FROM public.basket_mold_positions position
      WHERE position.mold_id=v_basket.mold_id
        AND position.metadata->>'site_basket_product_type_id'=grid_row.type_id::text
      ORDER BY position.sort_order,position.id LIMIT 1
    ) current_position ON true;

    PERFORM public.site_admin_save_basket_mold_shared_v1(
      v_basket.basket_id,v_basket.hidden_adjustment,1,v_positions,
      coalesce(nullif(btrim(p_operator),''),'Admin site Dona Antônia'),'[]'::jsonb
    );
  END LOOP;

  RETURN jsonb_build_object('type_count',v_type_count,'basket_count',v_basket_count);
END;
$function$
;

-- function: site_admin_save_basket_grid_with_prices_v1(p_rows jsonb, p_basket_prices jsonb, p_operator text)
CREATE OR REPLACE FUNCTION public.site_admin_save_basket_grid_with_prices_v1(p_rows jsonb, p_basket_prices jsonb, p_operator text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_role text := coalesce(auth.jwt() ->> 'role', '');
  v_basket record;
  v_basket_count integer;
  v_price_key_count integer;
  v_valid_price_key_count integer;
  v_price_text text;
  v_target_price_cents numeric;
  v_product_total_cents numeric;
  v_conditional_cents numeric;
  v_saved jsonb;
BEGIN
  IF v_role <> 'service_role' THEN
    RAISE EXCEPTION 'site_admin_service_role_required' USING ERRCODE = '42501';
  END IF;
  IF p_basket_prices IS NULL OR jsonb_typeof(p_basket_prices) <> 'object' THEN
    RAISE EXCEPTION 'site_basket_grid_price_invalid';
  END IF;

  SELECT count(*) INTO v_basket_count
  FROM public.basket_templates basket
  JOIN public.basket_categories category
    ON category.id = basket.category_id
   AND category.slug = 'cestas-completas'
  JOIN public.basket_molds mold ON mold.basket_id = basket.id
  WHERE basket.is_active IS TRUE;

  SELECT count(*) INTO v_price_key_count
  FROM jsonb_object_keys(p_basket_prices) AS entry(key_name);

  SELECT count(*) INTO v_valid_price_key_count
  FROM jsonb_object_keys(p_basket_prices) AS entry(key_name)
  JOIN public.basket_templates basket ON basket.id::text = entry.key_name
  JOIN public.basket_categories category
    ON category.id = basket.category_id
   AND category.slug = 'cestas-completas'
  JOIN public.basket_molds mold ON mold.basket_id = basket.id
  WHERE basket.is_active IS TRUE;

  IF v_basket_count < 1
     OR v_price_key_count <> v_basket_count
     OR v_valid_price_key_count <> v_basket_count THEN
    RAISE EXCEPTION 'site_basket_grid_price_invalid';
  END IF;

  FOR v_basket IN
    SELECT basket.id AS basket_id
    FROM public.basket_templates basket
    JOIN public.basket_categories category
      ON category.id = basket.category_id
     AND category.slug = 'cestas-completas'
    JOIN public.basket_molds mold ON mold.basket_id = basket.id
    WHERE basket.is_active IS TRUE
  LOOP
    v_price_text := p_basket_prices ->> v_basket.basket_id::text;
    IF v_price_text IS NULL OR v_price_text !~ '^[0-9]{1,9}$'
       OR v_price_text::numeric > 100000000 THEN
      RAISE EXCEPTION 'site_basket_grid_price_invalid';
    END IF;
  END LOOP;

  v_saved := public.site_admin_save_basket_grid_v1(p_rows, p_operator);

  -- Remove only obsolete metadata from the shared option record. Review is
  -- calculated per active basket above, so the shared record is not authoritative.
  UPDATE public.site_basket_product_type_options configured_option
  SET metadata = coalesce(configured_option.metadata, '{}'::jsonb)
      - 'manual_replacement_required' - 'manual_replacement_reason',
      updated_at = now()
  FROM public.products product
  WHERE product.id = configured_option.product_id
    AND product.is_active IS TRUE
    AND coalesce(product.stock, 0) > 0
    AND configured_option.metadata @> '{"manual_replacement_required":true}'::jsonb;

  UPDATE public.basket_mold_position_options position_option
  SET metadata = coalesce(position_option.metadata, '{}'::jsonb)
      - 'manual_replacement_required' - 'manual_replacement_reason',
      updated_at = now()
  FROM public.basket_mold_positions position
  JOIN public.basket_molds mold ON mold.id = position.mold_id
  JOIN public.basket_templates basket ON basket.id = mold.basket_id AND basket.is_active IS TRUE
  WHERE position_option.position_id = position.id
    AND position_option.metadata @> '{"manual_replacement_required":true}'::jsonb
    AND EXISTS (
      SELECT 1
      FROM public.products product
      WHERE product.id = position_option.product_id
        AND product.is_active IS TRUE
        AND greatest(0, coalesce(product.stock, 0)
          - public.supabase_stock_pending_reservations_v1(product.id, NULL::uuid)) >= coalesce(
            nullif(position_option.metadata->>'base_quantity','')::numeric,
            CASE WHEN position_option.sort_order=0 THEN position.quantity ELSE 0 END
          )
    );

  FOR v_basket IN
    SELECT
      basket.id AS basket_id,
      mold.id AS mold_id,
      mold.conditional_hidden_enabled,
      mold.conditional_hidden_product_id,
      mold.conditional_hidden_adjustment
    FROM public.basket_templates basket
    JOIN public.basket_categories category
      ON category.id = basket.category_id
     AND category.slug = 'cestas-completas'
    JOIN public.basket_molds mold ON mold.basket_id = basket.id
    WHERE basket.is_active IS TRUE
  LOOP
    v_target_price_cents := (p_basket_prices ->> v_basket.basket_id::text)::numeric;

    SELECT coalesce(sum(round((CASE
      WHEN product.is_offer IS TRUE
       AND product.offer_price IS NOT NULL
       AND product.offer_price >= 0
        THEN product.offer_price
      ELSE coalesce(product.price, 0)
    END) * 100) * coalesce(
        nullif(option_row.metadata->>'base_quantity','')::numeric,
        CASE WHEN option_row.sort_order=0 THEN position.quantity ELSE 0 END
      )), 0)
    INTO v_product_total_cents
    FROM public.basket_mold_positions position
    JOIN public.basket_mold_position_options option_row
      ON option_row.position_id = position.id
     
    JOIN public.products product ON product.id = option_row.product_id
    WHERE position.mold_id = v_basket.mold_id
      AND coalesce(nullif(option_row.metadata->>'base_quantity','')::numeric,CASE WHEN option_row.sort_order=0 THEN position.quantity ELSE 0 END) > 0;

    v_conditional_cents := 0;
    IF v_basket.conditional_hidden_enabled IS TRUE
       AND v_basket.conditional_hidden_product_id IS NOT NULL
       AND coalesce(v_basket.conditional_hidden_adjustment, 0) > 0
       AND EXISTS (
         SELECT 1
         FROM public.basket_mold_positions position
         JOIN public.basket_mold_position_options option_row
           ON option_row.position_id = position.id
          
         WHERE position.mold_id = v_basket.mold_id
           AND coalesce(nullif(option_row.metadata->>'base_quantity','')::numeric,CASE WHEN option_row.sort_order=0 THEN position.quantity ELSE 0 END) > 0
           AND option_row.product_id = v_basket.conditional_hidden_product_id
       ) THEN
      v_conditional_cents := round(v_basket.conditional_hidden_adjustment * 100);
    END IF;

    UPDATE public.basket_molds
    SET hidden_adjustment = (v_target_price_cents - v_product_total_cents - v_conditional_cents) / 100
    WHERE id = v_basket.mold_id;
  END LOOP;

  RETURN coalesce(v_saved, '{}'::jsonb)
    || jsonb_build_object('default_prices_saved', v_basket_count);
END;
$function$
;

-- function: site_admin_save_basket_grid_with_prices_v2(p_rows jsonb, p_basket_prices jsonb, p_operator text)
CREATE OR REPLACE FUNCTION public.site_admin_save_basket_grid_with_prices_v2(p_rows jsonb, p_basket_prices jsonb, p_operator text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_saved jsonb;
  v_fixed_prices jsonb;
  v_projection jsonb;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('site_admin_basket_grid_public_projection_v1', 0));
  v_saved := public.site_admin_save_basket_grid_with_prices_v1(p_rows, p_basket_prices, p_operator);
  v_fixed_prices := public.site_admin_save_basket_default_prices_v1(p_basket_prices);
  v_projection := public.site_admin_sync_basket_grid_public_projection_v1();
  RETURN coalesce(v_saved, '{}'::jsonb)
    || coalesce(v_fixed_prices, '{}'::jsonb)
    || jsonb_build_object('public_projection_sync', v_projection);
END;
$function$
;

-- function: site_admin_save_basket_mold_shared_v1(p_basket_id uuid, p_hidden_adjustment numeric, p_public_composition_count integer, p_positions jsonb, p_operator text, p_share_changes jsonb)
CREATE OR REPLACE FUNCTION public.site_admin_save_basket_mold_shared_v1(p_basket_id uuid, p_hidden_adjustment numeric, p_public_composition_count integer, p_positions jsonb, p_operator text, p_share_changes jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_role text := COALESCE(auth.jwt() ->> 'role', '');
  v_category_slug text;
  v_editor jsonb;
  v_change jsonb;
  v_action text;
  v_item_id uuid;
  v_old_label text;
  v_label text;
  v_options jsonb;
  v_option jsonb;
  v_product_id uuid;
  v_seen uuid[] := '{}'::uuid[];
  v_order integer := 0;
  v_defaults jsonb;
  v_old_totals jsonb;
  v_basket record;
  v_old_total_cents bigint;
  v_new_base_cents bigint;
  v_new_conditional_cents bigint;
  v_option_rows integer := 0;
  v_results jsonb := '[]'::jsonb;
  v_hidden_adjustment_cents bigint;
BEGIN
  IF v_role <> 'service_role' THEN
    RAISE EXCEPTION 'site_admin_service_role_required' USING ERRCODE = '42501';
  END IF;

  IF p_share_changes IS NULL
    OR jsonb_typeof(p_share_changes) <> 'array'
    OR jsonb_array_length(p_share_changes) > 80 THEN
    RAISE EXCEPTION 'basket_mold_shared_changes_invalid';
  END IF;

  SELECT cat.slug INTO v_category_slug
  FROM public.basket_templates b
  JOIN public.basket_categories cat ON cat.id = b.category_id
  WHERE b.id = p_basket_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'basket_mold_basket_not_found';
  END IF;
  IF jsonb_array_length(p_share_changes) > 0 AND v_category_slug <> 'cestas-completas' THEN
    RAISE EXCEPTION 'basket_mold_shared_scope_invalid';
  END IF;

  v_editor := public.save_basket_mold_v1(
    p_basket_id,
    p_hidden_adjustment,
    p_public_composition_count,
    p_positions,
    p_operator
  );

  FOR v_change IN SELECT value FROM jsonb_array_elements(p_share_changes)
  LOOP
    v_action := COALESCE(v_change ->> 'action', '');
    PERFORM pg_advisory_xact_lock(hashtextextended('basket_mold_shared_items:cestas-completas', 0));

    IF v_action = 'disable' THEN
      v_item_id := NULLIF(v_change ->> 'shared_item_id', '')::uuid;
      IF v_item_id IS NULL THEN
        RAISE EXCEPTION 'basket_mold_shared_item_invalid';
      END IF;

      DELETE FROM public.basket_mold_shared_items
      WHERE id = v_item_id AND scope = 'cestas-completas';
      IF NOT FOUND THEN
        RAISE EXCEPTION 'basket_mold_shared_item_not_found';
      END IF;
      v_results := v_results || jsonb_build_array(jsonb_build_object(
        'action', 'disable', 'item_id', v_item_id
      ));
      CONTINUE;
    END IF;

    IF v_action <> 'upsert' THEN
      RAISE EXCEPTION 'basket_mold_shared_action_invalid';
    END IF;

    v_label := btrim(COALESCE(v_change ->> 'label', ''));
    v_options := v_change -> 'options';
    IF v_label = '' OR char_length(v_label) > 180
      OR COALESCE(jsonb_typeof(v_options), '') <> 'array'
      OR jsonb_array_length(v_options) < 1
      OR jsonb_array_length(v_options) > 40 THEN
      RAISE EXCEPTION 'basket_mold_shared_item_invalid';
    END IF;

    v_item_id := NULLIF(v_change ->> 'shared_item_id', '')::uuid;
    v_old_label := NULL;
    IF v_item_id IS NULL THEN
      SELECT id, label INTO v_item_id, v_old_label
      FROM public.basket_mold_shared_items
      WHERE scope = 'cestas-completas' AND label = v_label
      FOR UPDATE;
      IF NOT FOUND THEN
        INSERT INTO public.basket_mold_shared_items(scope, label, sort_order, metadata)
        VALUES (
          'cestas-completas',
          v_label,
          (SELECT COALESCE(MAX(sort_order) + 1, 0)
           FROM public.basket_mold_shared_items WHERE scope = 'cestas-completas'),
          jsonb_build_object('updated_by', COALESCE(NULLIF(btrim(p_operator), ''), 'Admin site Dona Antônia'))
        )
        RETURNING id INTO v_item_id;
      ELSE
        UPDATE public.basket_mold_shared_items
        SET updated_at = now(),
            metadata = COALESCE(metadata, '{}'::jsonb)
              || jsonb_build_object('updated_by', COALESCE(NULLIF(btrim(p_operator), ''), 'Admin site Dona Antônia'))
        WHERE id = v_item_id;
      END IF;
    ELSE
      SELECT label INTO v_old_label
      FROM public.basket_mold_shared_items
      WHERE id = v_item_id AND scope = 'cestas-completas'
      FOR UPDATE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'basket_mold_shared_item_not_found';
      END IF;
      IF v_old_label <> v_label THEN
        UPDATE public.basket_mold_positions pos SET label = v_label
        FROM public.basket_molds m,
             public.basket_templates b,
             public.basket_categories cat
        WHERE pos.mold_id = m.id
          AND m.basket_id = b.id
          AND b.category_id = cat.id
          AND cat.slug = 'cestas-completas'
          AND pos.label = v_old_label;
      END IF;
      UPDATE public.basket_mold_shared_items
      SET label = v_label,
          updated_at = now(),
          metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('updated_by', COALESCE(NULLIF(btrim(p_operator), ''), 'Admin site Dona Antônia'))
      WHERE id = v_item_id;
    END IF;

    v_seen := '{}'::uuid[];
    FOR v_option IN SELECT value FROM jsonb_array_elements(v_options)
    LOOP
      BEGIN
        v_product_id := NULLIF(v_option ->> 'product_id', '')::uuid;
      EXCEPTION WHEN others THEN
        RAISE EXCEPTION 'basket_mold_shared_product_invalid';
      END;
      IF v_product_id IS NULL
        OR v_product_id = ANY(v_seen)
        OR NOT EXISTS (SELECT 1 FROM public.products p WHERE p.id = v_product_id) THEN
        RAISE EXCEPTION 'basket_mold_shared_product_invalid';
      END IF;
      v_seen := array_append(v_seen, v_product_id);
    END LOOP;

    SELECT COALESCE(jsonb_object_agg(pos.id::text, default_option.product_id::text), '{}'::jsonb)
    INTO v_defaults
    FROM public.basket_mold_positions pos
    JOIN public.basket_molds m ON m.id = pos.mold_id
    JOIN public.basket_templates b ON b.id = m.basket_id
    JOIN public.basket_categories cat ON cat.id = b.category_id
    CROSS JOIN LATERAL (
      SELECT opt.product_id
      FROM public.basket_mold_position_options opt
      WHERE opt.position_id = pos.id
      ORDER BY opt.sort_order, opt.id
      LIMIT 1
    ) default_option
    WHERE cat.slug = 'cestas-completas' AND pos.label = v_label;

    SELECT COALESCE(jsonb_object_agg(m.id::text, jsonb_build_object(
      'total_cents',
      COALESCE((
        SELECT SUM(ROUND(ROUND((CASE
          WHEN p.is_offer IS TRUE AND p.offer_price IS NOT NULL AND p.offer_price >= 0 THEN p.offer_price
          ELSE COALESCE(p.price, 0)
        END)::numeric * 100) * pos.quantity))::bigint
        FROM public.basket_mold_positions pos
        JOIN LATERAL (
          SELECT opt.product_id
          FROM public.basket_mold_position_options opt
          WHERE opt.position_id = pos.id
          ORDER BY opt.sort_order, opt.id
          LIMIT 1
        ) default_option ON TRUE
        JOIN public.products p ON p.id = default_option.product_id
        WHERE pos.mold_id = m.id
      ), 0)
      + ROUND(COALESCE(m.hidden_adjustment, 0) * 100)::bigint
      + CASE WHEN m.conditional_hidden_enabled IS TRUE
          AND m.conditional_hidden_product_id IS NOT NULL
          AND EXISTS (
            SELECT 1
            FROM public.basket_mold_positions pos
            JOIN LATERAL (
              SELECT opt.product_id
              FROM public.basket_mold_position_options opt
              WHERE opt.position_id = pos.id
              ORDER BY opt.sort_order, opt.id
              LIMIT 1
            ) default_option ON TRUE
            WHERE pos.mold_id = m.id
              AND pos.quantity > 0
              AND default_option.product_id = m.conditional_hidden_product_id
          )
        THEN ROUND(COALESCE(m.conditional_hidden_adjustment, 0) * 100)::bigint
        ELSE 0 END
    )), '{}'::jsonb)
    INTO v_old_totals
    FROM public.basket_molds m
    JOIN public.basket_templates b ON b.id = m.basket_id
    JOIN public.basket_categories cat ON cat.id = b.category_id
    WHERE cat.slug = 'cestas-completas'
      AND EXISTS (
        SELECT 1 FROM public.basket_mold_positions pos
        WHERE pos.mold_id = m.id AND pos.label = v_label
      );

    DELETE FROM public.basket_mold_shared_item_options
    WHERE shared_item_id = v_item_id;
    v_order := 0;
    FOR v_option IN SELECT value FROM jsonb_array_elements(v_options)
    LOOP
      v_product_id := (v_option ->> 'product_id')::uuid;
      INSERT INTO public.basket_mold_shared_item_options(shared_item_id, product_id, sort_order)
      VALUES (v_item_id, v_product_id, v_order);
      v_order := v_order + 1;
    END LOOP;

    DELETE FROM public.basket_mold_position_options opt
    USING public.basket_mold_positions pos,
          public.basket_molds m,
          public.basket_templates b,
          public.basket_categories cat
    WHERE opt.position_id = pos.id
      AND pos.mold_id = m.id
      AND m.basket_id = b.id
      AND b.category_id = cat.id
      AND cat.slug = 'cestas-completas'
      AND pos.label = v_label;

    WITH ranked_options AS (
      SELECT pos.id AS position_id,
             shared_option.product_id,
             ROW_NUMBER() OVER (
               PARTITION BY pos.id
               ORDER BY CASE
                 WHEN shared_option.product_id::text = (v_defaults ->> (pos.id::text)) THEN 0
                 ELSE 1
               END,
               shared_option.sort_order,
               shared_option.id
             ) - 1 AS sort_order
      FROM public.basket_mold_positions pos
      JOIN public.basket_molds m ON m.id = pos.mold_id
      JOIN public.basket_templates b ON b.id = m.basket_id
      JOIN public.basket_categories cat ON cat.id = b.category_id
      JOIN public.basket_mold_shared_item_options shared_option ON shared_option.shared_item_id = v_item_id
      WHERE cat.slug = 'cestas-completas' AND pos.label = v_label
    )
    INSERT INTO public.basket_mold_position_options(position_id, product_id, sort_order)
    SELECT position_id, product_id, sort_order FROM ranked_options;
    GET DIAGNOSTICS v_option_rows = ROW_COUNT;

    FOR v_basket IN
      SELECT m.id, (v_old_totals -> (m.id::text) ->> 'total_cents')::bigint AS total_cents
      FROM public.basket_molds m
      WHERE v_old_totals ? (m.id::text)
    LOOP
      v_old_total_cents := v_basket.total_cents;

      SELECT COALESCE(SUM(ROUND(ROUND((CASE
        WHEN p.is_offer IS TRUE AND p.offer_price IS NOT NULL AND p.offer_price >= 0 THEN p.offer_price
        ELSE COALESCE(p.price, 0)
      END)::numeric * 100) * pos.quantity)), 0)::bigint
      INTO v_new_base_cents
      FROM public.basket_mold_positions pos
      JOIN LATERAL (
        SELECT opt.product_id
        FROM public.basket_mold_position_options opt
        WHERE opt.position_id = pos.id
        ORDER BY opt.sort_order, opt.id
        LIMIT 1
      ) default_option ON TRUE
      JOIN public.products p ON p.id = default_option.product_id
      WHERE pos.mold_id = v_basket.id;

      SELECT CASE WHEN m.conditional_hidden_enabled IS TRUE
          AND m.conditional_hidden_product_id IS NOT NULL
          AND EXISTS (
            SELECT 1
            FROM public.basket_mold_positions pos
            JOIN LATERAL (
              SELECT opt.product_id
              FROM public.basket_mold_position_options opt
              WHERE opt.position_id = pos.id
              ORDER BY opt.sort_order, opt.id
              LIMIT 1
            ) default_option ON TRUE
            WHERE pos.mold_id = m.id
              AND pos.quantity > 0
              AND default_option.product_id = m.conditional_hidden_product_id
          )
        THEN ROUND(COALESCE(m.conditional_hidden_adjustment, 0) * 100)::bigint
        ELSE 0 END
      INTO v_new_conditional_cents
      FROM public.basket_molds m
      WHERE m.id = v_basket.id;

      UPDATE public.basket_molds
      SET hidden_adjustment = (v_old_total_cents - v_new_base_cents - COALESCE(v_new_conditional_cents, 0))::numeric / 100,
          updated_at = now()
      WHERE id = v_basket.id;
    END LOOP;

    v_results := v_results || jsonb_build_array(jsonb_build_object(
      'action', 'upsert',
      'item_id', v_item_id,
      'label', v_label,
      'option_rows', v_option_rows
    ));
  END LOOP;

  v_editor := public.basket_mold_editor_v1(p_basket_id);
  SELECT ROUND(COALESCE(m.hidden_adjustment, 0) * 100)::bigint
  INTO v_hidden_adjustment_cents
  FROM public.basket_molds m
  WHERE m.basket_id = p_basket_id;

  RETURN jsonb_build_object(
    'editor', v_editor,
    'hidden_adjustment_cents', COALESCE(v_hidden_adjustment_cents, 0),
    'share_changes', v_results
  );
END;
$function$
;

-- function: site_admin_save_basket_mold_shared_with_fixed_price_v1(p_basket_id uuid, p_hidden_adjustment numeric, p_public_composition_count integer, p_positions jsonb, p_operator text, p_share_changes jsonb, p_default_price_cents integer)
CREATE OR REPLACE FUNCTION public.site_admin_save_basket_mold_shared_with_fixed_price_v1(p_basket_id uuid, p_hidden_adjustment numeric, p_public_composition_count integer, p_positions jsonb, p_operator text, p_share_changes jsonb, p_default_price_cents integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_role text := coalesce(auth.jwt() ->> 'role', '');
  v_saved jsonb;
  v_fixed_prices jsonb;
BEGIN
  IF v_role <> 'service_role' THEN
    RAISE EXCEPTION 'site_admin_service_role_required' USING ERRCODE = '42501';
  END IF;
  IF p_default_price_cents IS NULL
     OR p_default_price_cents < 0
     OR p_default_price_cents > 100000000 THEN
    RAISE EXCEPTION 'site_basket_default_price_invalid';
  END IF;

  v_saved := public.site_admin_save_basket_mold_shared_v1(
    p_basket_id,
    p_hidden_adjustment,
    p_public_composition_count,
    p_positions,
    p_operator,
    p_share_changes
  );
  v_fixed_prices := public.site_admin_save_basket_default_prices_v1(
    jsonb_build_object(p_basket_id::text, p_default_price_cents)
  );
  RETURN coalesce(v_saved, '{}'::jsonb) || coalesce(v_fixed_prices, '{}'::jsonb);
END;
$function$
;

-- function: site_admin_sync_basket_grid_public_projection_v1()
CREATE OR REPLACE FUNCTION public.site_admin_sync_basket_grid_public_projection_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_role text := coalesce(auth.jwt() ->> 'role', '');
  v_basket record;
  v_positions jsonb;
  v_baskets_synced integer := 0;
  v_mismatch_count integer := 0;
BEGIN
  IF v_role <> 'service_role' THEN
    RAISE EXCEPTION 'site_admin_service_role_required' USING ERRCODE = '42501';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('site_admin_basket_grid_public_projection_v1', 0));

  FOR v_basket IN
    SELECT basket.id AS basket_id,
           mold.id AS mold_id,
           mold.hidden_adjustment,
           mold.public_composition_count
    FROM public.basket_templates basket
    JOIN public.basket_categories category ON category.id = basket.category_id
    JOIN public.basket_molds mold ON mold.basket_id = basket.id
    WHERE category.slug = 'cestas-completas'
      AND basket.is_active IS TRUE
    ORDER BY basket.sort_order, basket.name, basket.id
  LOOP
    IF EXISTS (
      SELECT 1
      FROM public.site_basket_product_types product_type
      JOIN public.site_basket_product_type_quantities type_quantity
        ON type_quantity.product_type_id = product_type.id
       AND type_quantity.basket_id = v_basket.basket_id
       AND type_quantity.quantity > 0
      WHERE NOT EXISTS (
        SELECT 1
        FROM public.site_basket_product_type_options option_row
        WHERE option_row.product_type_id = product_type.id
      )
    ) THEN
      RAISE EXCEPTION 'basket_projection_session_has_no_products';
    END IF;

    SELECT coalesce(jsonb_agg(
      jsonb_build_object(
        'label', source.title,
        'quantity', source.total_quantity,
        'sort_order', source.position_order,
        'metadata', source.position_metadata,
        'options', source.options
      ) ORDER BY source.position_order, source.slot_order, source.type_id
    ), '[]'::jsonb)
    INTO v_positions
    FROM (
      SELECT product_type.id AS type_id,
             product_type.title,
             coalesce(product_type.sort_order, 0) AS position_order,
             coalesce(product_type.slot_order, 1) AS slot_order,
             (
               SELECT coalesce(sum(greatest(0, coalesce(quantity.quantity, 0))), 0)::integer
               FROM public.site_basket_product_type_options option_row
               LEFT JOIN public.site_basket_product_type_option_quantities quantity
                 ON quantity.product_type_id = option_row.product_type_id
                AND quantity.product_id = option_row.product_id
                AND quantity.basket_id = v_basket.basket_id
               WHERE option_row.product_type_id = product_type.id
             ) AS total_quantity,
             coalesce((
               SELECT position.metadata
               FROM public.basket_mold_positions position
               WHERE position.mold_id = v_basket.mold_id
                 AND position.metadata ->> 'site_basket_product_type_id' = product_type.id::text
               ORDER BY position.sort_order, position.id
               LIMIT 1
             ), '{}'::jsonb) || jsonb_build_object(
               'site_basket_product_type_id', product_type.id,
               'site_basket_product_session_id', coalesce(product_type.session_id, product_type.id),
               'site_basket_product_slot_order', coalesce(product_type.slot_order, 1)
             ) AS position_metadata,
             (
               SELECT coalesce(jsonb_agg(jsonb_build_object(
                 'product_id', option_row.product_id,
                 'sort_order', option_row.sort_order,
                 'metadata', (
                   coalesce(option_row.metadata, '{}'::jsonb)
                     - 'preferred' - 'base_quantity' - 'quantities' - 'basket_quantities'
                     - 'manual_replacement_required' - 'manual_replacement_reason'
                 ) || jsonb_build_object(
                   'base_quantity', greatest(0, coalesce(quantity.quantity, 0))
                 )
               ) ORDER BY option_row.sort_order, option_row.product_id), '[]'::jsonb)
               FROM public.site_basket_product_type_options option_row
               LEFT JOIN public.site_basket_product_type_option_quantities quantity
                 ON quantity.product_type_id = option_row.product_type_id
                AND quantity.product_id = option_row.product_id
                AND quantity.basket_id = v_basket.basket_id
               WHERE option_row.product_type_id = product_type.id
             ) AS options
      FROM public.site_basket_product_types product_type
      WHERE EXISTS (
        SELECT 1
        FROM public.site_basket_product_type_options option_row
        WHERE option_row.product_type_id = product_type.id
      )
    ) AS source;

    IF jsonb_typeof(v_positions) IS DISTINCT FROM 'array'
      OR jsonb_array_length(v_positions) = 0 THEN
      RAISE EXCEPTION 'basket_projection_positions_missing';
    END IF;

    PERFORM public.save_basket_mold_v1(
      v_basket.basket_id,
      v_basket.hidden_adjustment,
      greatest(1, least(6, coalesce(v_basket.public_composition_count, 1))),
      v_positions,
      'Admin site Dona Antônia'
    );
    v_baskets_synced := v_baskets_synced + 1;
  END LOOP;

  IF v_baskets_synced = 0 THEN
    RAISE EXCEPTION 'basket_projection_active_baskets_missing';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.basket_templates basket
    JOIN public.basket_categories category ON category.id = basket.category_id
    JOIN public.basket_molds mold ON mold.basket_id = basket.id
    JOIN public.site_basket_product_types product_type ON true
    WHERE category.slug = 'cestas-completas'
      AND basket.is_active IS TRUE
      AND EXISTS (
        SELECT 1
        FROM public.site_basket_product_type_options option_row
        WHERE option_row.product_type_id = product_type.id
      )
      AND (
        SELECT count(*)
        FROM public.basket_mold_positions position
        WHERE position.mold_id = mold.id
          AND position.metadata ->> 'site_basket_product_type_id' = product_type.id::text
      ) <> 1
  ) THEN
    RAISE EXCEPTION 'basket_projection_position_count_mismatch';
  END IF;

  WITH expected AS (
    SELECT basket.id AS basket_id,
           product_type.id::text AS type_id,
           option_row.product_id,
           greatest(0, coalesce(quantity.quantity, 0))::numeric AS quantity
    FROM public.basket_templates basket
    JOIN public.basket_categories category ON category.id = basket.category_id
    JOIN public.site_basket_product_types product_type ON true
    JOIN public.site_basket_product_type_options option_row
      ON option_row.product_type_id = product_type.id
    LEFT JOIN public.site_basket_product_type_option_quantities quantity
      ON quantity.product_type_id = option_row.product_type_id
     AND quantity.product_id = option_row.product_id
     AND quantity.basket_id = basket.id
    WHERE category.slug = 'cestas-completas'
      AND basket.is_active IS TRUE
  ), actual AS (
    SELECT basket.id AS basket_id,
           position.metadata ->> 'site_basket_product_type_id' AS type_id,
           option_row.product_id,
           greatest(0, coalesce(
             nullif(option_row.metadata ->> 'base_quantity', '')::numeric,
             CASE WHEN option_row.sort_order = 0 THEN position.quantity ELSE 0 END
           )) AS quantity
    FROM public.basket_templates basket
    JOIN public.basket_categories category ON category.id = basket.category_id
    JOIN public.basket_molds mold ON mold.basket_id = basket.id
    JOIN public.basket_mold_positions position ON position.mold_id = mold.id
    JOIN public.basket_mold_position_options option_row ON option_row.position_id = position.id
    WHERE category.slug = 'cestas-completas'
      AND basket.is_active IS TRUE
  )
  SELECT count(*)
  INTO v_mismatch_count
  FROM expected
  FULL OUTER JOIN actual USING (basket_id, type_id, product_id)
  WHERE expected.product_id IS NULL
     OR actual.product_id IS NULL
     OR expected.quantity IS DISTINCT FROM actual.quantity;

  IF v_mismatch_count <> 0 THEN
    RAISE EXCEPTION 'basket_projection_quantity_mismatch:%', v_mismatch_count;
  END IF;

  RETURN jsonb_build_object(
    'baskets_synced', v_baskets_synced,
    'quantity_mismatches', v_mismatch_count
  );
END;
$function$
;

-- function: site_order_number_short_v1()
CREATE OR REPLACE FUNCTION public.site_order_number_short_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_code_value bigint;
begin
  v_code_value := nextval('public.order_public_code_seq_v1'::regclass);
  if v_code_value > 675999 then
    raise exception using message = 'order_public_code_exhausted';
  end if;
  new.order_number := public.ops2_format_order_public_code_v1(v_code_value);
  return new;
end;
$function$
;

-- function: site_order_whatsapp_notice_status_v1(p_order_ids uuid[])
CREATE OR REPLACE FUNCTION public.site_order_whatsapp_notice_status_v1(p_order_ids uuid[])
 RETURNS TABLE(order_id uuid, stage text, status text, error_code text, channel_origin text)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  WITH requested_orders AS (
    SELECT DISTINCT request.order_id
    FROM unnest(coalesce(p_order_ids, '{}'::uuid[])) AS request(order_id)
    JOIN public.orders AS storefront_order ON storefront_order.id = request.order_id
    WHERE storefront_order.source IN ('vitrine', 'storefront_v2')
    LIMIT 200
  ),
  notice_rows AS (
    SELECT
      outbox.order_id,
      'received'::text AS stage,
      outbox.status AS local_status,
      outbox.last_error AS local_error,
      outbox.whatsapp_account_id,
      outbox.external_message_id,
      outbox.channel_origin,
      outbox.created_at
    FROM public.ops2_whatsapp_outbox_v1 AS outbox
    JOIN requested_orders AS requested ON requested.order_id = outbox.order_id
    WHERE outbox.recipient_kind = 'customer'
      AND outbox.message_kind = 'order_received'

    UNION ALL

    SELECT
      notification.order_id,
      'separation'::text AS stage,
      notification.status AS local_status,
      notification.last_error AS local_error,
      notification.whatsapp_account_id,
      notification.provider_message_id AS external_message_id,
      notification.channel_origin,
      notification.created_at
    FROM public.order_separation_customer_notifications_v1 AS notification
    JOIN requested_orders AS requested ON requested.order_id = notification.order_id

    UNION ALL

    SELECT
      completion.order_id,
      'separation'::text AS stage,
      coalesce(nullif(completion.metadata #>> '{customer_notification,status}', ''), 'unrecorded') AS local_status,
      completion.metadata #>> '{customer_notification,error}' AS local_error,
      storefront_order.whatsapp_account_id,
      NULL::text AS external_message_id,
      right(regexp_replace(coalesce(account.phone_e164, ''), '[^0-9]', '', 'g'), 4) AS channel_origin,
      completion.completed_at AS created_at
    FROM public.order_separation_completions_v1 AS completion
    JOIN requested_orders AS requested ON requested.order_id = completion.order_id
    JOIN public.orders AS storefront_order ON storefront_order.id = completion.order_id
    LEFT JOIN public.whatsapp_accounts AS account ON account.id = storefront_order.whatsapp_account_id
    WHERE completion.completed_at IS NOT NULL
      AND NOT EXISTS (
        SELECT 1
        FROM public.order_separation_customer_notifications_v1 AS notification
        WHERE notification.order_id = completion.order_id
      )

    UNION ALL

    SELECT
      storefront_order.id AS order_id,
      'received'::text AS stage,
      'unrecorded'::text AS local_status,
      NULL::text AS local_error,
      storefront_order.whatsapp_account_id,
      NULL::text AS external_message_id,
      right(regexp_replace(coalesce(account.phone_e164, ''), '[^0-9]', '', 'g'), 4) AS channel_origin,
      storefront_order.created_at
    FROM public.orders AS storefront_order
    JOIN requested_orders AS requested ON requested.order_id = storefront_order.id
    LEFT JOIN public.whatsapp_accounts AS account ON account.id = storefront_order.whatsapp_account_id
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.ops2_whatsapp_outbox_v1 AS outbox
      WHERE outbox.order_id = storefront_order.id
        AND outbox.recipient_kind = 'customer'
        AND outbox.message_kind = 'order_received'
    )
  )
  SELECT
    notice.order_id,
    notice.stage,
    CASE
      WHEN message.status_current = 'read' OR provider_status.status = 'read' THEN 'read'
      WHEN message.status_current = 'delivered' OR provider_status.status = 'delivered' THEN 'delivered'
      WHEN message.status_current = 'failed' OR provider_status.status = 'failed' THEN 'failed'
      WHEN message.status_current = 'cancelled' OR provider_status.status = 'cancelled' THEN 'failed'
      WHEN message.status_current = 'accepted' OR provider_status.status = 'accepted' THEN 'awaiting_delivery'
      WHEN message.status_current = 'sent' OR provider_status.status = 'sent' THEN 'awaiting_delivery'
      WHEN notice.local_status IN ('sending', 'failed', 'retry', 'pending', 'suppressed', 'uncertain', 'unrecorded') THEN notice.local_status
      ELSE coalesce(notice.local_status, 'unrecorded')
    END::text AS status,
    CASE
      WHEN (message.status_current = 'failed' OR provider_status.status = 'failed')
        AND provider_status.error_code ~ '^[0-9]{1,10}$' THEN provider_status.error_code
      WHEN notice.local_error ~ '^meta_[a-z_]{1,60}$' THEN notice.local_error
      WHEN message.status_current = 'failed' OR provider_status.status = 'failed' THEN 'send_failed'
      ELSE NULL
    END::text AS error_code,
    notice.channel_origin::text
  FROM notice_rows AS notice
  LEFT JOIN public.whatsapp_messages_v1 AS message
    ON message.whatsapp_account_id = notice.whatsapp_account_id
    AND message.provider = 'meta'
    AND message.provider_message_id = notice.external_message_id
  LEFT JOIN LATERAL (
    SELECT event.status, event.error_code
    FROM public.whatsapp_message_status_events_v1 AS event
    WHERE event.message_id = message.id
      AND event.provider = 'meta'
    ORDER BY
      CASE event.status
        WHEN 'read' THEN 6
        WHEN 'delivered' THEN 5
        WHEN 'failed' THEN 4
        WHEN 'cancelled' THEN 4
        WHEN 'sent' THEN 3
        WHEN 'accepted' THEN 2
        ELSE 1
      END DESC,
      event.occurred_at DESC,
      event.received_at DESC
    LIMIT 1
  ) AS provider_status ON true;
$function$
;

-- function: site_product_taxonomy_manage_v1(p_action text, p_id uuid, p_kind text, p_name text, p_parent_id uuid)
CREATE OR REPLACE FUNCTION public.site_product_taxonomy_manage_v1(p_action text, p_id uuid DEFAULT NULL::uuid, p_kind text DEFAULT NULL::text, p_name text DEFAULT NULL::text, p_parent_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_term public.product_taxonomy_terms%rowtype;
  v_parent public.product_taxonomy_terms%rowtype;
  v_name text := btrim(coalesce(p_name,''));
  v_count bigint := 0;
  v_children bigint := 0;
  v_parent_name text := '';
  v_new public.product_taxonomy_terms%rowtype;
begin
  if current_user not in ('service_role','postgres') then raise exception 'Acesso negado'; end if;
  if p_action = 'create' then
    if p_kind not in ('category','subcategory','brand','gondola') then raise exception 'Tipo inválido'; end if;
    if length(v_name) not between 1 and 100 then raise exception 'Informe um nome entre 1 e 100 caracteres'; end if;
    if p_kind = 'subcategory' and p_parent_id is not null then
      select * into v_parent from public.product_taxonomy_terms where id=p_parent_id and kind='category';
      if not found then raise exception 'Categoria não encontrada'; end if;
    elsif p_kind <> 'subcategory' and p_parent_id is not null then
      raise exception 'Este tipo não aceita categoria vinculada';
    end if;
    insert into public.product_taxonomy_terms(kind,name,parent_id)
    values(p_kind,v_name,case when p_kind='subcategory' then p_parent_id else null end)
    returning * into v_new;
    insert into public.admin_audit_logs(action,entity_type,entity_id,details)
      values('taxonomy_create','product_taxonomy',v_new.id::text,jsonb_build_object('kind',v_new.kind,'name',v_new.name));
    return jsonb_build_object('id',v_new.id,'affected',0,'action','create');
  end if;

  select * into v_term from public.product_taxonomy_terms where id=p_id for update;
  if not found then raise exception 'Classificação não encontrada'; end if;
  if v_term.parent_id is not null then
    select name into v_parent_name from public.product_taxonomy_terms where id=v_term.parent_id;
  end if;
  select usage_count, child_count into v_count,v_children
    from public.site_product_taxonomy_usage_v1 where id=p_id;

  if p_action = 'delete' then
    if v_count > 0 then raise exception 'Esta classificação está em uso por % produto(s). Renomeie antes de excluir',v_count; end if;
    if v_children > 0 then raise exception 'Remova primeiro as subcategorias desta categoria'; end if;
    delete from public.product_taxonomy_terms where id=p_id;
    insert into public.admin_audit_logs(action,entity_type,entity_id,details)
      values('taxonomy_delete','product_taxonomy',p_id::text,jsonb_build_object('kind',v_term.kind,'name',v_term.name));
    return jsonb_build_object('id',p_id,'affected',0,'action','delete');
  elsif p_action <> 'rename' then
    raise exception 'Operação inválida';
  end if;

  if length(v_name) not between 1 and 100 then raise exception 'Informe um nome entre 1 e 100 caracteres'; end if;
  if lower(v_name)=lower(v_term.name) and v_name=v_term.name then
    return jsonb_build_object('id',p_id,'affected',0,'action','rename');
  end if;
  update public.product_taxonomy_terms set name=v_name, updated_at=now() where id=p_id;
  if v_term.kind='category' then
    update public.products set category=v_name,updated_at=now()
      where lower(btrim(category))=lower(v_term.name);
  elsif v_term.kind='brand' then
    update public.products set brand=v_name,updated_at=now()
      where lower(btrim(brand))=lower(v_term.name);
  elsif v_term.kind='gondola' then
    update public.products set gondola=v_name,updated_at=now()
      where lower(btrim(gondola))=lower(v_term.name);
  elsif v_term.kind='subcategory' then
    update public.products set subcategory=v_name,updated_at=now()
      where lower(btrim(subcategory))=lower(v_term.name)
        and coalesce(lower(btrim(category)),'')=coalesce(lower(v_parent_name),'');
  end if;
  get diagnostics v_count = row_count;
  insert into public.admin_audit_logs(action,entity_type,entity_id,details)
    values('taxonomy_rename','product_taxonomy',p_id::text,
      jsonb_build_object('kind',v_term.kind,'from',v_term.name,'to',v_name,'affected_products',v_count));
  return jsonb_build_object('id',p_id,'affected',v_count,'action','rename');
exception
  when unique_violation then
    raise exception 'Já existe uma classificação com esse nome neste grupo';
end $function$
;

-- function: site_product_taxonomy_sync_v1()
CREATE OR REPLACE FUNCTION public.site_product_taxonomy_sync_v1()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_count integer;
begin
  insert into public.product_taxonomy_terms (kind,name)
  select distinct on (lower(btrim(category))) 'category', btrim(category)
  from public.products where nullif(btrim(category),'') is not null
  order by lower(btrim(category)), btrim(category)
  on conflict do nothing;

  insert into public.product_taxonomy_terms (kind,name)
  select distinct on (lower(btrim(brand))) 'brand', btrim(brand)
  from public.products where nullif(btrim(brand),'') is not null
  order by lower(btrim(brand)), btrim(brand)
  on conflict do nothing;

  insert into public.product_taxonomy_terms (kind,name)
  select distinct on (lower(btrim(gondola))) 'gondola', btrim(gondola)
  from public.products where nullif(btrim(gondola),'') is not null
  order by lower(btrim(gondola)), btrim(gondola)
  on conflict do nothing;

  insert into public.product_taxonomy_terms (kind,name,parent_id)
  select distinct on (lower(btrim(p.subcategory)),coalesce(c.id::text,''))
    'subcategory',btrim(p.subcategory),c.id
  from public.products p
  left join public.product_taxonomy_terms c
    on c.kind='category' and lower(c.name)=lower(btrim(p.category))
  where nullif(btrim(p.subcategory),'') is not null
  order by lower(btrim(p.subcategory)),coalesce(c.id::text,''), btrim(p.subcategory)
  on conflict do nothing;
  select count(*)::integer into v_count from public.product_taxonomy_terms;
  return v_count;
end $function$
;

-- function: smart_delivery_admin_assign_order_v1(p_order_id uuid, p_driver_id uuid, p_operator_label text)
CREATE OR REPLACE FUNCTION public.smart_delivery_admin_assign_order_v1(p_order_id uuid, p_driver_id uuid, p_operator_label text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_order public.orders%rowtype;
  v_driver public.delivery_drivers_v1%rowtype;
  v_run public.ops_delivery_runs%rowtype;
  v_existing_run public.ops_delivery_runs%rowtype;
  v_stop public.ops_delivery_stops%rowtype;
  v_today date := (now() at time zone 'America/Cuiaba')::date;
  v_service_date date;
  v_raw_date text;
  v_operator text := coalesce(nullif(left(trim(coalesce(p_operator_label, '')), 80), ''), 'Admin');
  v_sequence integer;
  v_count integer;
  v_status text := 'planned';
  v_name text;
begin
  if p_order_id is null or p_driver_id is null then raise exception 'invalid_order_or_driver'; end if;

  select * into v_order from public.orders where id = p_order_id for update;
  if not found or v_order.source not in ('vitrine', 'storefront_v2', 'manual_whatsapp', 'papoai', 'reorder') then
    raise exception 'order_not_found';
  end if;
  if v_order.status not in ('ready', 'out_for_delivery') then raise exception 'order_not_ready'; end if;

  v_raw_date := nullif(trim(v_order.checkout_snapshot #>> '{delivery,date}'), '');
  if v_raw_date is null then
    v_service_date := (v_order.created_at at time zone 'America/Cuiaba')::date;
  else
    if v_raw_date !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'invalid_delivery_date'; end if;
    begin
      v_service_date := v_raw_date::date;
    exception when others then
      raise exception 'invalid_delivery_date';
    end;
  end if;
  if v_service_date < v_today then raise exception 'delivery_date_in_past'; end if;
  if extract(dow from v_service_date) = 0 then raise exception 'delivery_not_available_sunday'; end if;

  select * into v_driver from public.delivery_drivers_v1 where id = p_driver_id for update;
  if not found or not v_driver.is_active then raise exception 'driver_not_active'; end if;

  perform pg_advisory_xact_lock(
    hashtextextended('ops_delivery_run:' || v_service_date::text || ':driver_' || lower(p_driver_id::text), 0)
  );

  select s.* into v_stop
    from public.ops_delivery_stops s
   where s.order_id = p_order_id and s.status in ('planned', 'out_for_delivery')
   order by s.created_at desc
   limit 1
   for update;

  if found then
    select * into v_existing_run from public.ops_delivery_runs where id = v_stop.run_id for update;
    if not found then raise exception 'run_not_found'; end if;
    if v_existing_run.driver_id <> p_driver_id then raise exception 'order_already_assigned'; end if;
    if v_existing_run.service_date <> v_service_date then raise exception 'order_delivery_date_mismatch'; end if;
    if v_stop.status = 'out_for_delivery' then
      return jsonb_build_object(
        'ok', true, 'order_id', p_order_id, 'stop_id', v_stop.id, 'run_id', v_existing_run.id,
        'driver_id', p_driver_id, 'service_date', v_service_date, 'status', 'out_for_delivery', 'already_assigned', true
      );
    end if;
    if v_existing_run.status not in ('planned', 'dispatched') then raise exception 'order_already_assigned'; end if;
    if v_existing_run.status = 'dispatched' then
      perform public.ops4_start_dispatch_v1(
        p_order_id, v_operator, 'dispatch-v4:' || p_order_id::text
      );
      perform public.ops_sync_delivery_stop_v1(p_order_id, 'out_for_delivery');
      v_status := 'out_for_delivery';
    end if;
    return jsonb_build_object(
      'ok', true, 'order_id', p_order_id, 'stop_id', v_stop.id, 'run_id', v_existing_run.id,
      'driver_id', p_driver_id, 'service_date', v_service_date, 'status', v_status, 'already_assigned', true
    );
  end if;

  if v_order.status = 'out_for_delivery' then raise exception 'order_already_dispatched'; end if;

  select * into v_run
    from public.ops_delivery_runs r
   where r.service_date = v_service_date
     and r.driver_id = p_driver_id
     and r.status in ('planned', 'dispatched')
   order by case when r.status = 'dispatched' then 0 else 1 end, r.created_at desc
   limit 1
   for update;

  if not found then
    insert into public.ops_delivery_runs(
      service_date, vehicle_key, status, operator_label, region_id, driver_id
    ) values (
      v_service_date, 'driver_' || lower(p_driver_id::text), 'planned', v_operator,
      coalesce(v_order.delivery_region_id, v_driver.home_region_id), p_driver_id
    ) returning * into v_run;
  end if;

  select count(*) into v_count
    from public.ops_delivery_stops
   where run_id = v_run.id and status <> 'cancelled';
  if v_count >= 30 then raise exception 'route_too_many_orders'; end if;

  select coalesce(max(sequence), 0) + 1 into v_sequence
    from public.ops_delivery_stops where run_id = v_run.id;

  v_name := coalesce(
    nullif(trim(v_order.customer_snapshot->>'display_name'), ''),
    nullif(trim(v_order.customer_snapshot->>'name'), ''),
    nullif(trim(v_order.delivery_address->>'customer_name'), ''),
    nullif(trim(v_order.delivery_address->>'recipient_name'), ''),
    'Cliente'
  );

  insert into public.ops_delivery_stops(
    run_id, order_id, sequence, status, address_snapshot, phone_snapshot,
    customer_name_snapshot, order_number_snapshot, total_cents, payment_method_snapshot,
    maps_url_snapshot, customer_address_id, location_evidence_id, region_id
  ) values (
    v_run.id, p_order_id, v_sequence, 'planned', coalesce(v_order.delivery_address, '{}'::jsonb),
    v_order.phone_e164, v_name, v_order.order_number, round(coalesce(v_order.total, 0) * 100)::bigint,
    coalesce(v_order.delivery_paid_ahead_method, v_order.payment_method),
    nullif(trim(coalesce(v_order.delivery_address->>'google_maps_url', '')), ''),
    v_order.delivery_customer_address_id, v_order.delivery_location_evidence_id,
    coalesce(v_order.delivery_region_id, v_run.region_id, v_driver.home_region_id)
  ) returning * into v_stop;

  if v_run.status = 'dispatched' then
    perform public.ops4_start_dispatch_v1(
      p_order_id, v_operator, 'dispatch-v4:' || p_order_id::text
    );
    perform public.ops_sync_delivery_stop_v1(p_order_id, 'out_for_delivery');
    v_status := 'out_for_delivery';
  end if;

  insert into public.admin_audit_logs(admin_user_id, action, entity_type, entity_id, details)
  values (
    null, 'delivery.order_assigned', 'order', p_order_id::text,
    jsonb_build_object(
      'stop_id', v_stop.id, 'run_id', v_run.id, 'driver_id', p_driver_id,
      'service_date', v_service_date, 'operator', v_operator
    )
  );

  return jsonb_build_object(
    'ok', true, 'order_id', p_order_id, 'stop_id', v_stop.id, 'run_id', v_run.id,
    'driver_id', p_driver_id, 'service_date', v_service_date, 'status', v_status,
    'already_assigned', false
  );
end;
$function$
;

-- function: smart_delivery_admin_dispatch_run_v1(p_run_id uuid, p_operator_label text)
CREATE OR REPLACE FUNCTION public.smart_delivery_admin_dispatch_run_v1(p_run_id uuid, p_operator_label text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_run public.ops_delivery_runs%rowtype;
  v_stop public.ops_delivery_stops%rowtype;
  v_started integer := 0;
  v_operator text := coalesce(nullif(left(trim(coalesce(p_operator_label, '')), 80), ''), 'Admin');
begin
  if p_run_id is null then raise exception 'invalid_run'; end if;
  select * into v_run from public.ops_delivery_runs where id = p_run_id for update;
  if not found then raise exception 'run_not_found'; end if;
  if v_run.status = 'dispatched' then
    return jsonb_build_object('ok', true, 'run_id', p_run_id, 'status', 'dispatched', 'already_dispatched', true);
  end if;
  if v_run.status <> 'planned' or v_run.driver_id is null then
    raise exception 'run_not_ready_for_dispatch';
  end if;
  if v_run.service_date <> (now() at time zone 'America/Cuiaba')::date then
    raise exception 'delivery_not_due';
  end if;

  for v_stop in
    select * from public.ops_delivery_stops
    where run_id = p_run_id and status = 'planned'
    order by sequence
    for update
  loop
    perform public.ops4_start_dispatch_v1(
      v_stop.order_id,
      v_operator,
      'dispatch-v4:' || v_stop.order_id::text
    );
    perform public.ops_sync_delivery_stop_v1(v_stop.order_id, 'out_for_delivery');
    v_started := v_started + 1;
  end loop;

  if v_started = 0 then raise exception 'run_has_no_pending_stops'; end if;
  update public.ops_delivery_runs
     set status = 'dispatched',
         dispatched_at = coalesce(dispatched_at, now()),
         updated_at = now()
   where id = p_run_id;

  return jsonb_build_object(
    'ok', true, 'run_id', p_run_id, 'status', 'dispatched', 'order_count', v_started
  );
end;
$function$
;

-- function: smart_delivery_admin_fail_stop_v1(p_stop_id uuid, p_operator_label text)
CREATE OR REPLACE FUNCTION public.smart_delivery_admin_fail_stop_v1(p_stop_id uuid, p_operator_label text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_stop public.ops_delivery_stops%rowtype;
  v_run public.ops_delivery_runs%rowtype;
  v_order public.orders%rowtype;
  v_case public.order_delivery_return_cases%rowtype;
  v_attempt integer;
  v_operator text := coalesce(nullif(left(trim(coalesce(p_operator_label, '')), 80), ''), 'Admin');
begin
  if p_stop_id is null then raise exception 'invalid_stop'; end if;
  select * into v_stop from public.ops_delivery_stops where id = p_stop_id for update;
  if not found then raise exception 'stop_not_found'; end if;
  select * into v_run from public.ops_delivery_runs where id = v_stop.run_id for update;
  if not found or v_run.status <> 'dispatched' then raise exception 'run_not_dispatched'; end if;
  select * into v_order from public.orders where id = v_stop.order_id for update;
  if not found then raise exception 'order_not_found'; end if;
  if v_order.status <> 'out_for_delivery' then raise exception 'order_not_in_delivery'; end if;

  select * into v_case
    from public.order_delivery_return_cases
   where order_id = v_order.id and status in ('returning', 'returned_review')
   order by failed_at desc limit 1 for update;

  if v_stop.status = 'failed' and v_case.id is not null then
    return jsonb_build_object(
      'ok', true, 'stop_id', v_stop.id, 'order_id', v_order.id,
      'case_id', v_case.id, 'status', 'failed', 'already_failed', true
    );
  end if;
  if v_stop.status <> 'out_for_delivery' then raise exception 'stop_not_out_for_delivery'; end if;

  select coalesce(max(attempt_number), 0) + 1 into v_attempt
    from public.order_delivery_return_cases where order_id = v_order.id;
  insert into public.order_delivery_return_cases(
    order_id, attempt_number, reason_code, reason_label, note, status,
    recommended_disposition, failed_by, idempotency_key, metadata
  ) values (
    v_order.id, v_attempt, 'other', 'Não entregue', null, 'returning',
    'review', v_operator, 'delivery-return:' || v_order.id::text || ':' || v_attempt::text,
    jsonb_build_object('stock_already_consumed', true, 'return_stock_to_general_automatically', false)
  ) returning * into v_case;

  update public.ops_delivery_stops
     set status = 'failed', failed_at = coalesce(failed_at, now()),
         failure_reason = 'Não entregue', updated_at = now()
   where id = v_stop.id;

  perform public.ops_sync_delivery_stop_v1(v_order.id, 'out_for_delivery');
  perform public.ops_record_event_v1(
    'delivery', 'delivery.failed', 'Entrega não concluída.', 'human', 'order',
    v_order.id::text, v_order.id::text, null, v_operator, 'dona_antonia', 'warning',
    jsonb_build_object('case_id', v_case.id, 'attempt_number', v_attempt, 'reason_code', 'other'),
    null, 'delivery-failed:' || v_case.id::text, now()
  );

  insert into public.admin_audit_logs(admin_user_id, action, entity_type, entity_id, details)
  values(null, 'delivery.stop_not_delivered', 'order', v_order.id::text,
    jsonb_build_object('stop_id', v_stop.id, 'case_id', v_case.id, 'operator', v_operator));

  return jsonb_build_object(
    'ok', true, 'stop_id', v_stop.id, 'order_id', v_order.id,
    'case_id', v_case.id, 'attempt_number', v_attempt, 'status', 'failed'
  );
end;
$function$
;

-- function: smart_delivery_admin_reassign_stop_v1(p_stop_id uuid, p_new_driver_id uuid, p_operator_label text)
CREATE OR REPLACE FUNCTION public.smart_delivery_admin_reassign_stop_v1(p_stop_id uuid, p_new_driver_id uuid, p_operator_label text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_run_id uuid;
  v_source public.ops_delivery_runs%rowtype;
  v_target public.ops_delivery_runs%rowtype;
  v_stop public.ops_delivery_stops%rowtype;
  v_order public.orders%rowtype;
  v_driver public.delivery_drivers_v1%rowtype;
  v_source_key text;
  v_target_key text;
  v_lock_key text;
  v_next_sequence integer;
  v_target_count integer;
  v_operator text := nullif(left(trim(coalesce(p_operator_label, '')), 80), '');
begin
  if p_stop_id is null or p_new_driver_id is null then raise exception 'invalid_stop_or_driver'; end if;
  select s.run_id into v_run_id from public.ops_delivery_stops s where s.id = p_stop_id;
  if not found then raise exception 'stop_not_found'; end if;
  select * into v_source from public.ops_delivery_runs where id = v_run_id;
  if not found then raise exception 'run_not_found'; end if;
  if v_source.driver_id is null then raise exception 'route_driver_missing'; end if;
  if v_source.driver_id = p_new_driver_id then raise exception 'driver_same_as_current'; end if;

  v_source_key := 'driver_' || lower(v_source.driver_id::text);
  v_target_key := 'driver_' || lower(p_new_driver_id::text);
  for v_lock_key in
    select key_value from unnest(array[v_source_key, v_target_key]) as keys(key_value) order by key_value
  loop
    perform pg_advisory_xact_lock(hashtextextended('ops_delivery_run:' || v_source.service_date::text || ':' || v_lock_key, 0));
  end loop;

  select * into v_source from public.ops_delivery_runs where id = v_run_id for update;
  if v_source.status <> 'planned' then raise exception 'route_locked'; end if;
  select * into v_stop from public.ops_delivery_stops where id = p_stop_id and run_id = v_source.id for update;
  if not found then raise exception 'stop_not_found'; end if;
  if v_stop.status <> 'planned' then raise exception 'stop_not_planned'; end if;
  select * into v_order from public.orders where id = v_stop.order_id for update;
  if not found then raise exception 'order_not_found'; end if;
  if v_order.status <> 'ready' then raise exception 'order_not_ready'; end if;

  select * into v_driver from public.delivery_drivers_v1 where id = p_new_driver_id for update;
  if not found or not v_driver.is_active then raise exception 'driver_not_active'; end if;
  if exists (
    select 1 from public.ops_delivery_runs r
     where r.service_date = v_source.service_date and r.driver_id = p_new_driver_id and r.status = 'dispatched'
  ) then raise exception 'driver_already_dispatched'; end if;

  select * into v_target
    from public.ops_delivery_runs r
   where r.service_date = v_source.service_date and r.driver_id = p_new_driver_id and r.status = 'planned'
   order by r.created_at desc limit 1 for update;

  select count(*) into v_target_count
    from public.ops_delivery_stops s where s.run_id = v_target.id and s.status <> 'cancelled';
  if v_target_count >= 30 then raise exception 'route_too_many_orders'; end if;

  if v_target.id is null then
    insert into public.ops_delivery_runs(service_date, vehicle_key, status, operator_label, region_id, driver_id)
    values(v_source.service_date, v_target_key, 'planned', coalesce(v_operator, 'Admin'),
      coalesce(v_stop.region_id, v_driver.home_region_id), p_new_driver_id)
    returning * into v_target;
  elsif v_target.region_id is null then
    update public.ops_delivery_runs
       set region_id = coalesce(v_stop.region_id, v_driver.home_region_id), updated_at = now()
     where id = v_target.id returning * into v_target;
  end if;

  select coalesce(max(s.sequence), 0) + 1 into v_next_sequence
    from public.ops_delivery_stops s where s.run_id = v_target.id;
  update public.ops_delivery_stops
     set run_id = v_target.id, sequence = v_next_sequence,
         region_id = coalesce(v_target.region_id, v_stop.region_id, v_driver.home_region_id),
         updated_at = now()
   where id = v_stop.id;

  update public.ops_delivery_runs r
     set status = 'cancelled', updated_at = now()
   where r.id = v_source.id
     and not exists (
       select 1 from public.ops_delivery_stops s
        where s.run_id = r.id and s.status in ('planned', 'out_for_delivery')
     );

  insert into public.admin_audit_logs(admin_user_id, action, entity_type, entity_id, details)
  values(null, 'delivery.stop_reassigned', 'order', v_order.id::text,
    jsonb_build_object('stop_id', v_stop.id, 'source_run_id', v_source.id, 'target_run_id', v_target.id,
      'source_driver_id', v_source.driver_id, 'target_driver_id', p_new_driver_id,
      'service_date', v_source.service_date, 'operator', coalesce(v_operator, 'Admin')));

  return jsonb_build_object('ok', true, 'stop_id', v_stop.id, 'order_id', v_order.id,
    'source_run_id', v_source.id, 'run_id', v_target.id, 'driver_id', p_new_driver_id,
    'service_date', v_source.service_date);
end;
$function$
;

-- function: smart_delivery_admin_release_stop_v1(p_stop_id uuid, p_service_date date, p_operator_label text)
CREATE OR REPLACE FUNCTION public.smart_delivery_admin_release_stop_v1(p_stop_id uuid, p_service_date date DEFAULT NULL::date, p_operator_label text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_run_id uuid;
  v_run public.ops_delivery_runs%rowtype;
  v_stop public.ops_delivery_stops%rowtype;
  v_order public.orders%rowtype;
  v_today date := (now() at time zone 'America/Cuiaba')::date;
  v_operator text := nullif(left(trim(coalesce(p_operator_label, '')), 80), '');
begin
  if p_stop_id is null then raise exception 'invalid_stop'; end if;
  if p_service_date is not null then
    if p_service_date < v_today then raise exception 'delivery_date_in_past'; end if;
    if extract(dow from p_service_date) = 0 then raise exception 'delivery_not_available_sunday'; end if;
  end if;

  select s.run_id into v_run_id from public.ops_delivery_stops s where s.id = p_stop_id;
  if not found then raise exception 'stop_not_found'; end if;
  select * into v_run from public.ops_delivery_runs where id = v_run_id for update;
  if not found then raise exception 'run_not_found'; end if;
  if v_run.status <> 'planned' then raise exception 'route_locked'; end if;
  select * into v_stop from public.ops_delivery_stops where id = p_stop_id and run_id = v_run.id for update;
  if not found then raise exception 'stop_not_found'; end if;
  if v_stop.status <> 'planned' then raise exception 'stop_not_planned'; end if;
  select * into v_order from public.orders where id = v_stop.order_id for update;
  if not found then raise exception 'order_not_found'; end if;
  if v_order.status <> 'ready' then raise exception 'order_not_ready'; end if;
  if p_service_date is not null and p_service_date = v_run.service_date then
    return jsonb_build_object('ok', true, 'stop_id', v_stop.id, 'order_id', v_order.id,
      'service_date', p_service_date, 'released_from_route', false, 'unchanged', true);
  end if;

  if p_service_date is not null then
    update public.orders
       set checkout_snapshot = jsonb_set(
         coalesce(checkout_snapshot, '{}'::jsonb), '{delivery}',
         case when jsonb_typeof(checkout_snapshot->'delivery') = 'object'
           then (checkout_snapshot->'delivery') || jsonb_build_object('date', p_service_date::text)
           else jsonb_build_object('date', p_service_date::text)
         end, true
       ),
       updated_at = now()
     where id = v_order.id;
    perform public.ops2_refresh_order_public_snapshot_v1(v_order.id);
  end if;

  update public.ops_delivery_stops set status = 'cancelled', updated_at = now() where id = v_stop.id;
  update public.ops_delivery_runs r
     set status = 'cancelled', updated_at = now()
   where r.id = v_run.id
     and not exists (
       select 1 from public.ops_delivery_stops s
        where s.run_id = r.id and s.status in ('planned', 'out_for_delivery')
     );

  insert into public.admin_audit_logs(admin_user_id, action, entity_type, entity_id, details)
  values(null,
    case when p_service_date is null then 'delivery.stop_cancelled' else 'delivery.stop_rescheduled' end,
    'order', v_order.id::text,
    jsonb_build_object('stop_id', v_stop.id, 'run_id', v_run.id,
      'previous_service_date', v_run.service_date, 'service_date', coalesce(p_service_date, v_run.service_date),
      'operator', coalesce(v_operator, 'Admin')));

  return jsonb_build_object('ok', true, 'stop_id', v_stop.id, 'order_id', v_order.id,
    'service_date', coalesce(p_service_date, v_run.service_date), 'released_from_route', true);
end;
$function$
;

-- function: smart_delivery_apply_optimization_v1(p_run_id uuid, p_result jsonb)
CREATE OR REPLACE FUNCTION public.smart_delivery_apply_optimization_v1(p_run_id uuid, p_result jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_run public.ops_delivery_runs%rowtype;
  v_current jsonb;
  v_fingerprint text;
  v_expected text := nullif(p_result->>'fingerprint','');
  v_provider text := coalesce(nullif(p_result->>'provider',''),'google_route_optimization');
  v_job_ref text := nullif(p_result->>'job_ref','');
  v_order jsonb := p_result->'stop_ids';
  v_count integer;
  v_distinct integer;
begin
  select * into v_run from public.ops_delivery_runs where id=p_run_id for update;
  if not found then raise exception 'Rota não encontrada' using errcode='P0002'; end if;
  if v_run.status <> 'planned' then raise exception 'Rota mudou de estado durante a otimização' using errcode='40001'; end if;
  if v_expected is null or not jsonb_typeof(v_order)='array' then raise exception 'Resultado do otimizador inválido' using errcode='22023'; end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',s.id::text,'order_id',s.order_id::text,'sequence',s.sequence,
    'lat',s.destination_latitude,'lng',s.destination_longitude
  ) order by s.sequence),'[]'::jsonb)
  into v_current
  from public.ops_delivery_stops s where s.run_id=p_run_id;

  v_fingerprint := md5(v_current::text || '|' || v_run.updated_at::text);
  if v_fingerprint <> v_expected then raise exception 'Rota mudou durante a otimização; refaça o cálculo' using errcode='40001'; end if;

  v_count := jsonb_array_length(v_order);
  if v_count <> jsonb_array_length(v_current) then raise exception 'Resultado incompleto do otimizador' using errcode='22023'; end if;

  select count(distinct x.value) into v_distinct from jsonb_array_elements_text(v_order) x;
  if v_distinct <> v_count then raise exception 'Resultado contém entrega duplicada' using errcode='22023'; end if;

  if exists (
    select 1 from jsonb_array_elements_text(v_order) x
    where not exists (
      select 1 from public.ops_delivery_stops s where s.run_id=p_run_id and s.id::text=x.value
    )
  ) then raise exception 'Resultado contém entrega de outra rota' using errcode='22023'; end if;

  with desired as (
    select value::uuid stop_id, ordinality::integer seq
    from jsonb_array_elements_text(v_order) with ordinality
  )
  update public.ops_delivery_stops s
  set sequence=d.seq, updated_at=now()
  from desired d where s.id=d.stop_id and s.run_id=p_run_id;

  update public.ops_delivery_runs
  set optimizer_provider=v_provider,
      optimizer_job_ref=v_job_ref,
      optimizer_payload=p_result,
      updated_at=now()
  where id=p_run_id;

  return jsonb_build_object('ok',true,'run_id',p_run_id,'provider',v_provider,'stop_count',v_count);
end;
$function$
;

-- function: smart_delivery_assign_run_v1(p_run_id uuid, p_region_id uuid, p_driver_id uuid, p_vehicle_id uuid, p_operator_label text, p_actor_user_id uuid)
CREATE OR REPLACE FUNCTION public.smart_delivery_assign_run_v1(p_run_id uuid, p_region_id uuid DEFAULT NULL::uuid, p_driver_id uuid DEFAULT NULL::uuid, p_vehicle_id uuid DEFAULT NULL::uuid, p_operator_label text DEFAULT NULL::text, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_run public.ops_delivery_runs%rowtype;
  v_region public.delivery_regions_v1%rowtype;
  v_driver public.delivery_drivers_v1%rowtype;
  v_vehicle public.delivery_vehicles_v1%rowtype;
  v_new_region uuid;
  v_new_driver uuid;
  v_new_vehicle uuid;
begin
  select * into v_run
  from public.ops_delivery_runs
  where id = p_run_id
  for update;

  if not found then
    raise exception 'Rota não encontrada' using errcode = 'P0002';
  end if;
  if v_run.status in ('completed', 'cancelled') then
    raise exception 'Rota encerrada não pode ser reatribuída' using errcode = '22023';
  end if;

  v_new_region := coalesce(p_region_id, v_run.region_id);
  v_new_driver := coalesce(p_driver_id, v_run.driver_id);
  v_new_vehicle := coalesce(p_vehicle_id, v_run.vehicle_id);

  if v_new_region is not null then
    select * into v_region from public.delivery_regions_v1 where id = v_new_region for share;
    if not found or not v_region.is_active then
      raise exception 'Região inexistente ou inativa' using errcode = '22023';
    end if;
  end if;

  if v_new_driver is not null then
    select * into v_driver from public.delivery_drivers_v1 where id = v_new_driver for share;
    if not found or not v_driver.is_active then
      raise exception 'Entregador inexistente ou inativo' using errcode = '22023';
    end if;
  end if;

  if v_new_vehicle is not null then
    select * into v_vehicle from public.delivery_vehicles_v1 where id = v_new_vehicle for share;
    if not found or not v_vehicle.is_active then
      raise exception 'Veículo inexistente ou inativo' using errcode = '22023';
    end if;
  end if;

  update public.ops_delivery_runs
  set region_id = v_new_region,
      driver_id = v_new_driver,
      vehicle_id = v_new_vehicle,
      operator_label = coalesce(nullif(btrim(p_operator_label), ''), operator_label),
      updated_at = now()
  where id = p_run_id;

  insert into public.admin_audit_logs(admin_user_id, action, entity_type, entity_id, details)
  values (
    p_actor_user_id,
    'smart_delivery.run_assignment_changed',
    'delivery_run',
    p_run_id::text,
    jsonb_build_object(
      'before', jsonb_build_object(
        'region_id', v_run.region_id,
        'driver_id', v_run.driver_id,
        'vehicle_id', v_run.vehicle_id
      ),
      'after', jsonb_build_object(
        'region_id', v_new_region,
        'driver_id', v_new_driver,
        'vehicle_id', v_new_vehicle
      )
    )
  );

  return jsonb_build_object(
    'ok', true,
    'run_id', p_run_id,
    'status', v_run.status,
    'region_id', v_new_region,
    'driver_id', v_new_driver,
    'vehicle_id', v_new_vehicle
  );
end;
$function$
;

-- function: smart_delivery_catalog_v1()
CREATE OR REPLACE FUNCTION public.smart_delivery_catalog_v1()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  select jsonb_build_object(
    'regions', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',r.id,'code',r.code,'name',r.name,'city',r.city,'state',r.state,
        'is_active',r.is_active,'priority',r.priority,'notes',r.notes,'polygon_geojson',r.polygon_geojson
      ) order by r.is_active desc,r.priority,r.name)
      from public.delivery_regions_v1 r
    ), '[]'::jsonb),
    'drivers', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',d.id,'name',d.name,'phone_e164',d.phone_e164,'is_active',d.is_active,
        'home_region_id',d.home_region_id,'metadata',d.metadata
      ) order by d.is_active desc,d.name)
      from public.delivery_drivers_v1 d
    ), '[]'::jsonb),
    'vehicles', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',v.id,'label',v.label,'plate',v.plate,'vehicle_type',v.vehicle_type,
        'capacity_units',v.capacity_units,'is_active',v.is_active,'metadata',v.metadata
      ) order by v.is_active desc,v.label)
      from public.delivery_vehicles_v1 v
    ), '[]'::jsonb)
  );
$function$
;

-- function: smart_delivery_complete_stop_v1(p_stop_id uuid, p_method text, p_amount_cents bigint, p_operator_label text, p_idempotency_key text)
CREATE OR REPLACE FUNCTION public.smart_delivery_complete_stop_v1(p_stop_id uuid, p_method text, p_amount_cents bigint, p_operator_label text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_stop public.ops_delivery_stops%rowtype;
  v_run public.ops_delivery_runs%rowtype;
  v_result jsonb;
begin
  select * into v_stop from public.ops_delivery_stops where id = p_stop_id for update;
  if not found then raise exception 'stop_not_found'; end if;
  select * into v_run from public.ops_delivery_runs where id = v_stop.run_id for update;
  if not found or v_run.status <> 'dispatched' then raise exception 'run_not_dispatched'; end if;
  if v_stop.status = 'delivered' then
    return jsonb_build_object('ok', true, 'stop_id', p_stop_id, 'order_id', v_stop.order_id, 'status', 'delivered', 'already_delivered', true);
  end if;
  if v_stop.status <> 'out_for_delivery' then raise exception 'stop_not_out_for_delivery'; end if;

  v_result := public.ops3_complete_delivery_v1(
    v_stop.order_id, p_method, p_amount_cents, p_operator_label,
    coalesce(nullif(trim(coalesce(p_idempotency_key, '')), ''), 'driver-delivery-v1:' || v_stop.order_id::text)
  );
  perform public.ops_sync_delivery_stop_v1(v_stop.order_id, 'delivered');
  return coalesce(v_result, '{}'::jsonb) || jsonb_build_object('stop_id', p_stop_id, 'status', 'delivered');
end;
$function$
;

-- function: smart_delivery_confirm_loading_v1(p_run_id uuid, p_stop_id uuid, p_actor_user_id uuid)
CREATE OR REPLACE FUNCTION public.smart_delivery_confirm_loading_v1(p_run_id uuid, p_stop_id uuid DEFAULT NULL::uuid, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_run public.ops_delivery_runs%rowtype;
  v_stop public.ops_delivery_stops%rowtype;
  v_touched integer := 0;
  v_remaining integer := 0;
  v_loaded_at timestamptz;
begin
  select * into v_run
  from public.ops_delivery_runs
  where id = p_run_id
  for update;

  if not found then
    raise exception 'Rota não encontrada' using errcode = 'P0002';
  end if;
  if v_run.status in ('completed', 'cancelled') then
    raise exception 'Rota encerrada não pode receber confirmação de carregamento' using errcode = '22023';
  end if;

  update public.ops_delivery_runs
  set loading_started_at = coalesce(loading_started_at, now()),
      updated_at = now()
  where id = p_run_id;

  if p_stop_id is not null then
    select * into v_stop
    from public.ops_delivery_stops
    where id = p_stop_id and run_id = p_run_id
    for update;

    if not found then
      raise exception 'Entrega não pertence à rota informada' using errcode = '22023';
    end if;
    if v_stop.status not in ('planned', 'out_for_delivery') then
      raise exception 'Entrega não está em estado carregável' using errcode = '22023';
    end if;

    update public.ops_delivery_stops
    set loaded_at = coalesce(loaded_at, now()),
        custody_confirmed_at = coalesce(custody_confirmed_at, now()),
        updated_at = now()
    where id = p_stop_id;

    v_touched := 1;
  else
    update public.ops_delivery_stops
    set loaded_at = coalesce(loaded_at, now()),
        custody_confirmed_at = coalesce(custody_confirmed_at, now()),
        updated_at = now()
    where run_id = p_run_id
      and status in ('planned', 'out_for_delivery');

    get diagnostics v_touched = row_count;
  end if;

  select count(*) into v_remaining
  from public.ops_delivery_stops
  where run_id = p_run_id
    and status in ('planned', 'out_for_delivery')
    and loaded_at is null;

  if v_remaining = 0 and exists (
    select 1 from public.ops_delivery_stops
    where run_id = p_run_id
      and status in ('planned', 'out_for_delivery')
  ) then
    update public.ops_delivery_runs
    set loaded_at = coalesce(loaded_at, now()),
        updated_at = now()
    where id = p_run_id
    returning loaded_at into v_loaded_at;
  else
    select loaded_at into v_loaded_at
    from public.ops_delivery_runs
    where id = p_run_id;
  end if;

  insert into public.admin_audit_logs(admin_user_id, action, entity_type, entity_id, details)
  values (
    p_actor_user_id,
    'smart_delivery.loading_confirmed',
    'delivery_run',
    p_run_id::text,
    jsonb_build_object(
      'stop_id', p_stop_id,
      'touched_stops', v_touched,
      'remaining_unloaded_stops', v_remaining,
      'run_loaded_at', v_loaded_at
    )
  );

  return jsonb_build_object(
    'ok', true,
    'run_id', p_run_id,
    'stop_id', p_stop_id,
    'touched_stops', v_touched,
    'remaining_unloaded_stops', v_remaining,
    'run_loaded_at', v_loaded_at
  );
end;
$function$
;

-- function: smart_delivery_confirm_location_v1(p_order_id uuid, p_customer_address_id uuid, p_location_evidence_id uuid, p_region_id uuid, p_confirmation_source text, p_actor_user_id uuid)
CREATE OR REPLACE FUNCTION public.smart_delivery_confirm_location_v1(p_order_id uuid, p_customer_address_id uuid, p_location_evidence_id uuid, p_region_id uuid DEFAULT NULL::uuid, p_confirmation_source text DEFAULT 'admin'::text, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_order public.orders%rowtype;
  v_address public.customer_addresses%rowtype;
  v_evidence public.customer_location_evidence_v1%rowtype;
  v_region public.delivery_regions_v1%rowtype;
  v_source text;
begin
  select * into v_order
  from public.orders
  where id = p_order_id
  for update;

  if not found then
    raise exception 'Pedido não encontrado' using errcode = 'P0002';
  end if;
  if v_order.customer_id is null then
    raise exception 'Pedido sem cliente vinculado' using errcode = '22023';
  end if;

  select * into v_address
  from public.customer_addresses
  where id = p_customer_address_id
  for update;

  if not found then
    raise exception 'Endereço não encontrado' using errcode = 'P0002';
  end if;
  if v_address.customer_id <> v_order.customer_id then
    raise exception 'Endereço não pertence ao cliente do pedido' using errcode = '22023';
  end if;
  if not v_address.is_active then
    raise exception 'Endereço está inativo' using errcode = '22023';
  end if;

  select * into v_evidence
  from public.customer_location_evidence_v1
  where id = p_location_evidence_id
  for update;

  if not found then
    raise exception 'Evidência de localização não encontrada' using errcode = 'P0002';
  end if;

  if v_evidence.customer_id is null then
    if v_order.conversation_id is null
       or v_evidence.conversation_id is distinct from v_order.conversation_id then
      raise exception 'Evidência sem vínculo seguro com o cliente do pedido' using errcode = '22023';
    end if;
  elsif v_evidence.customer_id <> v_order.customer_id then
    raise exception 'Evidência pertence a outro cliente' using errcode = '22023';
  end if;

  if v_evidence.customer_address_id is not null
     and v_evidence.customer_address_id <> p_customer_address_id then
    raise exception 'Evidência já vinculada a outro endereço' using errcode = '22023';
  end if;

  if v_evidence.order_id is not null
     and v_evidence.order_id <> p_order_id then
    raise exception 'Evidência já vinculada a outro pedido' using errcode = '22023';
  end if;

  if p_region_id is not null then
    select * into v_region
    from public.delivery_regions_v1
    where id = p_region_id
    for share;

    if not found or not v_region.is_active then
      raise exception 'Região de entrega inexistente ou inativa' using errcode = '22023';
    end if;
  end if;

  v_source := coalesce(nullif(btrim(p_confirmation_source), ''), 'admin');

  update public.customer_location_evidence_v1
  set customer_id = v_order.customer_id,
      customer_address_id = p_customer_address_id,
      order_id = p_order_id,
      confidence = 'confirmed',
      confirmation_source = v_source,
      confirmed_at = coalesce(confirmed_at, now()),
      updated_at = now()
  where id = p_location_evidence_id;

  update public.customer_addresses
  set latitude = v_evidence.latitude,
      longitude = v_evidence.longitude,
      last_confirmed_at = now(),
      updated_at = now()
  where id = p_customer_address_id;

  update public.orders
  set delivery_customer_address_id = p_customer_address_id,
      delivery_location_evidence_id = p_location_evidence_id,
      delivery_region_id = coalesce(p_region_id, delivery_region_id),
      updated_at = now()
  where id = p_order_id;

  update public.ops_delivery_stops
  set customer_address_id = p_customer_address_id,
      location_evidence_id = p_location_evidence_id,
      region_id = coalesce(p_region_id, region_id),
      destination_latitude = v_evidence.latitude,
      destination_longitude = v_evidence.longitude,
      destination_confidence = 'confirmed',
      updated_at = now()
  where order_id = p_order_id
    and status not in ('delivered', 'cancelled');

  insert into public.admin_audit_logs(admin_user_id, action, entity_type, entity_id, details)
  values (
    p_actor_user_id,
    'smart_delivery.location_confirmed',
    'order',
    p_order_id::text,
    jsonb_build_object(
      'customer_address_id', p_customer_address_id,
      'location_evidence_id', p_location_evidence_id,
      'region_id', p_region_id,
      'confirmation_source', v_source
    )
  );

  return jsonb_build_object(
    'ok', true,
    'order_id', p_order_id,
    'customer_address_id', p_customer_address_id,
    'location_evidence_id', p_location_evidence_id,
    'region_id', coalesce(p_region_id, v_order.delivery_region_id),
    'latitude', v_evidence.latitude,
    'longitude', v_evidence.longitude,
    'confidence', 'confirmed'
  );
end;
$function$
;

-- function: smart_delivery_confirm_order_location_v1(p_order_id uuid, p_location_evidence_id uuid, p_region_id uuid, p_confirmation_source text, p_actor_user_id uuid)
CREATE OR REPLACE FUNCTION public.smart_delivery_confirm_order_location_v1(p_order_id uuid, p_location_evidence_id uuid, p_region_id uuid DEFAULT NULL::uuid, p_confirmation_source text DEFAULT 'delivery_admin'::text, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_order public.orders%rowtype;
  v_evidence public.customer_location_evidence_v1%rowtype;
  v_address_doc jsonb;
  v_address_id uuid;
  v_street text;
  v_number text;
  v_neighborhood text;
  v_city text;
  v_state text;
  v_postal_code text;
  v_label text;
  v_created boolean := false;
  v_result jsonb;
begin
  select * into v_order from public.orders where id = p_order_id for update;
  if not found then raise exception 'order_not_found' using errcode = 'P0002'; end if;
  if v_order.customer_id is null then raise exception 'order_customer_required' using errcode = '22023'; end if;

  select * into v_evidence from public.customer_location_evidence_v1
   where id = p_location_evidence_id for update;
  if not found then raise exception 'location_evidence_not_found' using errcode = 'P0002'; end if;
  if v_evidence.latitude is null or v_evidence.longitude is null
     or v_evidence.latitude < -90 or v_evidence.latitude > 90
     or v_evidence.longitude < -180 or v_evidence.longitude > 180
     or (v_evidence.latitude = 0 and v_evidence.longitude = 0) then
    raise exception 'location_coordinates_invalid' using errcode = '22023';
  end if;
  if v_evidence.customer_id is not null and v_evidence.customer_id <> v_order.customer_id then
    raise exception 'location_customer_mismatch' using errcode = '22023';
  end if;
  if v_evidence.customer_id is null and (v_order.conversation_id is null or v_evidence.conversation_id is distinct from v_order.conversation_id) then
    raise exception 'location_conversation_mismatch' using errcode = '22023';
  end if;
  if v_evidence.order_id is not null and v_evidence.order_id <> p_order_id then
    raise exception 'location_order_mismatch' using errcode = '22023';
  end if;

  v_address_doc := coalesce(v_order.delivery_address, '{}'::jsonb);
  v_street := coalesce(
    nullif(trim(v_address_doc->>'street'), ''),
    nullif(trim(v_address_doc->>'address_line'), '')
  );
  v_number := nullif(trim(v_address_doc->>'number'), '');
  v_neighborhood := nullif(trim(coalesce(v_address_doc->>'neighborhood', v_address_doc->>'district')), '');
  v_city := nullif(trim(v_address_doc->>'city'), '');
  v_state := nullif(upper(trim(v_address_doc->>'state')), '');
  v_postal_code := nullif(trim(coalesce(v_address_doc->>'postal_code', v_address_doc->>'zip_code')), '');
  v_address_id := coalesce(v_order.delivery_customer_address_id, v_evidence.customer_address_id);

  if v_address_id is null and v_street is not null then
    select a.id into v_address_id
      from public.customer_addresses a
     where a.customer_id = v_order.customer_id and a.is_active
       and lower(trim(coalesce(a.street, ''))) = lower(v_street)
       and lower(trim(coalesce(a.number, ''))) = lower(coalesce(v_number, ''))
       and lower(trim(coalesce(a.neighborhood, ''))) = lower(coalesce(v_neighborhood, ''))
       and lower(trim(coalesce(a.city, ''))) = lower(coalesce(v_city, ''))
       and lower(trim(coalesce(a.state, ''))) = lower(coalesce(v_state, ''))
       and lower(trim(coalesce(a.postal_code, ''))) = lower(coalesce(v_postal_code, ''))
     order by a.is_default desc, a.updated_at desc
     limit 1 for update;
  end if;

  if v_address_id is null then
    v_label := coalesce(
      nullif(trim(v_address_doc->>'label'), ''),
      nullif(concat_ws(', ', v_street, v_number, v_neighborhood), ''),
      'Endereço confirmado do pedido ' || coalesce(v_order.order_number::text, left(p_order_id::text, 8))
    );
    insert into public.customer_addresses(
      customer_id, label, street, number, complement, neighborhood, city, state,
      postal_code, reference, is_default, is_active, google_maps_url, latitude, longitude
    ) values (
      v_order.customer_id, v_label, v_street, v_number,
      nullif(trim(v_address_doc->>'complement'), ''), v_neighborhood, v_city, v_state,
      v_postal_code, nullif(trim(v_address_doc->>'reference'), ''), false, true,
      'https://www.google.com/maps/search/?api=1&query=' || v_evidence.latitude::text || '%2C' || v_evidence.longitude::text,
      v_evidence.latitude, v_evidence.longitude
    ) returning id into v_address_id;
    v_created := true;
  end if;

  v_result := public.smart_delivery_confirm_location_v1(
    p_order_id, v_address_id, p_location_evidence_id, p_region_id,
    coalesce(nullif(trim(coalesce(p_confirmation_source, '')), ''), 'delivery_admin'), p_actor_user_id
  );
  return coalesce(v_result, '{}'::jsonb) || jsonb_build_object(
    'customer_address_id', v_address_id,
    'customer_address_created', v_created
  );
end;
$function$
;

-- function: smart_delivery_dispatch_run_v1(p_run_id uuid, p_operator_label text)
CREATE OR REPLACE FUNCTION public.smart_delivery_dispatch_run_v1(p_run_id uuid, p_operator_label text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_run public.ops_delivery_runs%rowtype;
  v_stop public.ops_delivery_stops%rowtype;
  v_count integer := 0;
  v_result jsonb;
begin
  select * into v_run from public.ops_delivery_runs where id = p_run_id for update;
  if not found then raise exception 'run_not_found'; end if;
  if v_run.status = 'dispatched' then
    return jsonb_build_object('ok', true, 'run_id', p_run_id, 'status', v_run.status, 'already_dispatched', true);
  end if;
  if v_run.status <> 'planned' or v_run.driver_id is null then raise exception 'run_not_ready_for_dispatch'; end if;

  select count(*) into v_count from public.ops_delivery_stops
   where run_id = p_run_id and status = 'planned' and loaded_at is not null and custody_confirmed_at is not null;
  if v_count = 0 or exists (
    select 1 from public.ops_delivery_stops
     where run_id = p_run_id and status = 'planned'
       and (loaded_at is null or custody_confirmed_at is null)
  ) then raise exception 'delivery_loading_confirmation_required'; end if;

  for v_stop in
    select * from public.ops_delivery_stops where run_id = p_run_id and status = 'planned' order by sequence for update
  loop
    v_result := public.ops4_start_dispatch_v1(v_stop.order_id,
      coalesce(nullif(trim(coalesce(p_operator_label, '')), ''), 'Operação'),
      'dispatch-v4:' || v_stop.order_id::text);
    perform public.ops_sync_delivery_stop_v1(v_stop.order_id, 'out_for_delivery');
  end loop;

  update public.ops_delivery_runs
     set status = 'dispatched', dispatched_at = coalesce(dispatched_at, now()), updated_at = now()
   where id = p_run_id;

  return jsonb_build_object('ok', true, 'run_id', p_run_id, 'status', 'dispatched', 'order_count', v_count);
end;
$function$
;

-- function: smart_delivery_driver_save_location_v1(p_stop_id uuid, p_driver_id uuid, p_latitude numeric, p_longitude numeric, p_accuracy_m numeric, p_mode text, p_label text)
CREATE OR REPLACE FUNCTION public.smart_delivery_driver_save_location_v1(p_stop_id uuid, p_driver_id uuid, p_latitude numeric, p_longitude numeric, p_accuracy_m numeric, p_mode text, p_label text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_stop public.ops_delivery_stops%rowtype;
  v_run public.ops_delivery_runs%rowtype;
  v_order public.orders%rowtype;
  v_address public.customer_addresses%rowtype;
  v_address_doc jsonb;
  v_address_id uuid;
  v_evidence_id uuid;
  v_next_stop_id uuid;
  v_street text;
  v_number text;
  v_neighborhood text;
  v_city text;
  v_state text;
  v_postal_code text;
  v_label text;
  v_mode text := lower(trim(coalesce(p_mode, '')));
  v_point_label text := nullif(trim(coalesce(p_label, '')), '');
  v_created boolean := false;
begin
  if p_latitude is null or p_longitude is null
     or p_latitude < -90 or p_latitude > 90
     or p_longitude < -180 or p_longitude > 180
     or (p_latitude = 0 and p_longitude = 0) then
    raise exception 'invalid_location_coordinates' using errcode = '22023';
  end if;
  if p_accuracy_m is null or p_accuracy_m < 0 or p_accuracy_m > 100000 then
    raise exception 'invalid_location_accuracy' using errcode = '22023';
  end if;
  if v_mode not in ('primary', 'alternate') then
    raise exception 'invalid_location_mode' using errcode = '22023';
  end if;
  if v_mode = 'alternate' and (v_point_label is null or char_length(v_point_label) > 80) then
    raise exception 'alternate_location_label_required' using errcode = '22023';
  end if;

  select s.* into v_stop
    from public.ops_delivery_stops s
    join public.ops_delivery_runs r on r.id = s.run_id
   where s.id = p_stop_id and r.driver_id = p_driver_id and r.status = 'dispatched'
   for update of s;
  if not found then raise exception 'driver_stop_not_found' using errcode = 'P0002'; end if;
  if v_stop.status <> 'out_for_delivery' then
    raise exception 'stop_not_out_for_delivery' using errcode = '22023';
  end if;

  select * into v_run from public.ops_delivery_runs where id = v_stop.run_id for update;
  if not found or v_run.driver_id <> p_driver_id or v_run.status <> 'dispatched' then
    raise exception 'driver_run_not_dispatched' using errcode = '22023';
  end if;
  select s.id into v_next_stop_id
    from public.ops_delivery_stops s
   where s.run_id = v_run.id and s.status = 'out_for_delivery'
   order by s.sequence, s.created_at, s.id
   limit 1;
  if v_next_stop_id is distinct from p_stop_id then
    raise exception 'stop_is_not_next' using errcode = '22023';
  end if;

  select * into v_order from public.orders where id = v_stop.order_id for update;
  if not found then raise exception 'order_not_found' using errcode = 'P0002'; end if;
  if v_order.customer_id is null then raise exception 'order_customer_required' using errcode = '22023'; end if;

  v_address_id := coalesce(v_stop.customer_address_id, v_order.delivery_customer_address_id);
  if v_address_id is null and v_stop.location_evidence_id is not null then
    select e.customer_address_id into v_address_id
      from public.customer_location_evidence_v1 e
     where e.id = v_stop.location_evidence_id;
  end if;
  if v_address_id is not null then
    select * into v_address from public.customer_addresses a
     where a.id = v_address_id and a.customer_id = v_order.customer_id and a.is_active
     for update;
    if not found then raise exception 'customer_address_mismatch' using errcode = '22023'; end if;
  else
    v_address_doc := coalesce(v_order.delivery_address, '{}'::jsonb);
    v_street := coalesce(nullif(trim(v_address_doc->>'street'), ''), nullif(trim(v_address_doc->>'address_line'), ''));
    v_number := nullif(trim(v_address_doc->>'number'), '');
    v_neighborhood := nullif(trim(coalesce(v_address_doc->>'neighborhood', v_address_doc->>'district')), '');
    v_city := nullif(trim(v_address_doc->>'city'), '');
    v_state := nullif(upper(trim(v_address_doc->>'state')), '');
    v_postal_code := nullif(trim(coalesce(v_address_doc->>'postal_code', v_address_doc->>'zip_code')), '');

    if v_street is not null then
      select a.id into v_address_id
        from public.customer_addresses a
       where a.customer_id = v_order.customer_id and a.is_active
         and lower(trim(coalesce(a.street, ''))) = lower(v_street)
         and lower(trim(coalesce(a.number, ''))) = lower(coalesce(v_number, ''))
         and lower(trim(coalesce(a.neighborhood, ''))) = lower(coalesce(v_neighborhood, ''))
         and lower(trim(coalesce(a.city, ''))) = lower(coalesce(v_city, ''))
         and lower(trim(coalesce(a.state, ''))) = lower(coalesce(v_state, ''))
         and lower(trim(coalesce(a.postal_code, ''))) = lower(coalesce(v_postal_code, ''))
       order by a.is_default desc, a.updated_at desc
       limit 1 for update;
    end if;

    if v_address_id is null and v_mode = 'alternate' then
      raise exception 'primary_location_required' using errcode = '22023';
    end if;
    if v_address_id is null then
      v_label := coalesce(
        nullif(trim(v_address_doc->>'label'), ''),
        nullif(concat_ws(', ', v_street, v_number, v_neighborhood), ''),
        'Endereço do pedido ' || coalesce(v_order.order_number::text, left(v_order.id::text, 8))
      );
      insert into public.customer_addresses(
        customer_id, label, street, number, complement, neighborhood, city, state,
        postal_code, reference, is_default, is_active, google_maps_url, latitude, longitude
      ) values (
        v_order.customer_id, v_label, v_street, v_number,
        nullif(trim(v_address_doc->>'complement'), ''), v_neighborhood, v_city, v_state,
        v_postal_code, nullif(trim(v_address_doc->>'reference'), ''), false, true,
        'https://www.google.com/maps/search/?api=1&query=' || p_latitude::text || '%2C' || p_longitude::text,
        p_latitude, p_longitude
      ) returning id into v_address_id;
      v_created := true;
      select * into v_address from public.customer_addresses where id = v_address_id for update;
    end if;
  end if;

  if v_address_id is not null and v_address.id is null then
    select * into v_address from public.customer_addresses a
     where a.id = v_address_id and a.customer_id = v_order.customer_id and a.is_active
     for update;
    if not found then raise exception 'customer_address_mismatch' using errcode = '22023'; end if;
  end if;

  if v_mode = 'alternate' and (v_address.latitude is null or v_address.longitude is null) then
    raise exception 'primary_location_required' using errcode = '22023';
  end if;

  insert into public.customer_location_evidence_v1(
    customer_id, customer_address_id, order_id, conversation_id,
    source, direction, latitude, longitude, label, address_text,
    confidence, confirmation_source, confirmed_at, captured_at, metadata
  ) values (
    v_order.customer_id, v_address_id, v_order.id, v_order.conversation_id,
    'driver', 'internal', p_latitude, p_longitude,
    coalesce(v_point_label, 'Localização principal confirmada pelo entregador'),
    nullif(concat_ws(', ', v_address.street, v_address.number, v_address.neighborhood, v_address.city), ''),
    'confirmed', 'delivery_driver', now(), now(),
    jsonb_build_object(
      'capture_mode', v_mode,
      'accuracy_m', p_accuracy_m,
      'driver_id', p_driver_id,
      'stop_id', p_stop_id,
      'previous_primary_location', case
        when v_mode = 'primary' and not v_created and v_address.latitude is not null and v_address.longitude is not null
          then jsonb_build_object('latitude', v_address.latitude, 'longitude', v_address.longitude)
        else null
      end
    )
  ) returning id into v_evidence_id;

  if v_mode = 'primary' then
    perform public.smart_delivery_confirm_location_v1(
      v_order.id, v_address_id, v_evidence_id, v_stop.region_id, 'delivery_driver', null
    );
    update public.customer_addresses
       set google_maps_url = 'https://www.google.com/maps/search/?api=1&query=' || p_latitude::text || '%2C' || p_longitude::text,
           updated_at = now()
     where id = v_address_id;
  else
    update public.orders
       set delivery_customer_address_id = v_address_id,
           delivery_location_evidence_id = v_evidence_id,
           updated_at = now()
     where id = v_order.id;
    update public.ops_delivery_stops
       set customer_address_id = v_address_id,
           location_evidence_id = v_evidence_id,
           destination_latitude = p_latitude,
           destination_longitude = p_longitude,
           destination_confidence = 'confirmed',
           updated_at = now()
     where id = p_stop_id;
    insert into public.admin_audit_logs(admin_user_id, action, entity_type, entity_id, details)
    values(null, 'smart_delivery.alternate_location_saved', 'order', v_order.id::text,
      jsonb_build_object('customer_address_id', v_address_id, 'location_evidence_id', v_evidence_id,
        'stop_id', p_stop_id, 'driver_id', p_driver_id, 'label', v_point_label, 'accuracy_m', p_accuracy_m));
  end if;

  return jsonb_build_object(
    'ok', true,
    'stop_id', p_stop_id,
    'order_id', v_order.id,
    'customer_address_id', v_address_id,
    'location_evidence_id', v_evidence_id,
    'mode', v_mode,
    'latitude', p_latitude,
    'longitude', p_longitude,
    'customer_address_created', v_created
  );
end;
$function$
;

-- function: smart_delivery_driver_save_v1(p_id uuid, p_name text, p_phone_e164 text, p_home_region_id uuid, p_is_active boolean, p_metadata jsonb, p_actor_user_id uuid)
CREATE OR REPLACE FUNCTION public.smart_delivery_driver_save_v1(p_id uuid, p_name text, p_phone_e164 text DEFAULT NULL::text, p_home_region_id uuid DEFAULT NULL::uuid, p_is_active boolean DEFAULT true, p_metadata jsonb DEFAULT '{}'::jsonb, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_id uuid := coalesce(p_id, gen_random_uuid());
  v_name text := btrim(coalesce(p_name,''));
  v_phone text := nullif(regexp_replace(coalesce(p_phone_e164,''), '[^0-9+]', '', 'g'),'');
begin
  if v_name = '' or length(v_name) > 120 then raise exception 'Nome do entregador inválido' using errcode='22023'; end if;
  if v_phone is not null and v_phone !~ '^\+[1-9][0-9]{7,14}$' then raise exception 'Telefone deve estar em E.164' using errcode='22023'; end if;
  if p_home_region_id is not null and not exists(select 1 from public.delivery_regions_v1 where id=p_home_region_id) then
    raise exception 'Região base inexistente' using errcode='22023';
  end if;

  insert into public.delivery_drivers_v1(id,name,phone_e164,is_active,home_region_id,metadata,created_at,updated_at)
  values(v_id,v_name,v_phone,coalesce(p_is_active,true),p_home_region_id,coalesce(p_metadata,'{}'::jsonb),now(),now())
  on conflict(id) do update set
    name=excluded.name,phone_e164=excluded.phone_e164,is_active=excluded.is_active,
    home_region_id=excluded.home_region_id,metadata=excluded.metadata,updated_at=now();

  insert into public.admin_audit_logs(admin_user_id,action,entity_type,entity_id,details)
  values(p_actor_user_id,'smart_delivery.driver_saved','delivery_driver',v_id::text,
    jsonb_build_object('name',v_name,'active',coalesce(p_is_active,true),'home_region_id',p_home_region_id));
  return v_id;
end;
$function$
;

-- function: smart_delivery_driver_select_location_v1(p_stop_id uuid, p_driver_id uuid, p_location_evidence_id uuid)
CREATE OR REPLACE FUNCTION public.smart_delivery_driver_select_location_v1(p_stop_id uuid, p_driver_id uuid, p_location_evidence_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_stop public.ops_delivery_stops%rowtype;
  v_run public.ops_delivery_runs%rowtype;
  v_order public.orders%rowtype;
  v_evidence public.customer_location_evidence_v1%rowtype;
  v_address_id uuid;
  v_next_stop_id uuid;
begin
  select s.* into v_stop
    from public.ops_delivery_stops s
    join public.ops_delivery_runs r on r.id = s.run_id
   where s.id = p_stop_id and r.driver_id = p_driver_id and r.status = 'dispatched'
   for update of s;
  if not found then raise exception 'driver_stop_not_found' using errcode = 'P0002'; end if;
  if v_stop.status <> 'out_for_delivery' then
    raise exception 'stop_not_out_for_delivery' using errcode = '22023';
  end if;

  select * into v_run from public.ops_delivery_runs where id = v_stop.run_id for update;
  if not found or v_run.driver_id <> p_driver_id or v_run.status <> 'dispatched' then
    raise exception 'driver_run_not_dispatched' using errcode = '22023';
  end if;
  select s.id into v_next_stop_id
    from public.ops_delivery_stops s
   where s.run_id = v_run.id and s.status = 'out_for_delivery'
   order by s.sequence, s.created_at, s.id
   limit 1;
  if v_next_stop_id is distinct from p_stop_id then
    raise exception 'stop_is_not_next' using errcode = '22023';
  end if;

  select * into v_order from public.orders where id = v_stop.order_id for update;
  if not found or v_order.customer_id is null then raise exception 'order_customer_required' using errcode = '22023'; end if;
  v_address_id := coalesce(v_stop.customer_address_id, v_order.delivery_customer_address_id);
  if v_address_id is null then raise exception 'customer_address_required' using errcode = '22023'; end if;
  select * into v_evidence from public.customer_location_evidence_v1
   where id = p_location_evidence_id
     and source = 'driver'
     and confidence = 'confirmed'
     and metadata->>'capture_mode' = 'alternate'
     and customer_id = v_order.customer_id
     and customer_address_id = v_address_id
   for share;
  if not found then raise exception 'saved_location_not_available' using errcode = '22023'; end if;

  update public.ops_delivery_stops
     set location_evidence_id = v_evidence.id,
         destination_latitude = v_evidence.latitude,
         destination_longitude = v_evidence.longitude,
         destination_confidence = 'confirmed',
         updated_at = now()
   where id = p_stop_id;
  update public.orders set delivery_location_evidence_id = v_evidence.id, updated_at = now()
   where id = v_order.id;
  insert into public.admin_audit_logs(admin_user_id, action, entity_type, entity_id, details)
  values(null, 'smart_delivery.alternate_location_selected', 'order', v_order.id::text,
    jsonb_build_object('location_evidence_id', v_evidence.id, 'stop_id', p_stop_id, 'driver_id', p_driver_id));

  return jsonb_build_object('ok', true, 'stop_id', p_stop_id, 'location_evidence_id', v_evidence.id,
    'latitude', v_evidence.latitude, 'longitude', v_evidence.longitude, 'label', v_evidence.label);
end;
$function$
;

-- function: smart_delivery_guard_route_resequence_v1()
CREATE OR REPLACE FUNCTION public.smart_delivery_guard_route_resequence_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_source public.ops_delivery_runs%rowtype;
  v_target public.ops_delivery_runs%rowtype;
begin
  if new.run_id is not distinct from old.run_id and new.sequence is not distinct from old.sequence then
    return new;
  end if;
  select * into v_source from public.ops_delivery_runs where id = old.run_id;

  if new.run_id is not distinct from old.run_id then
    if new.status is distinct from old.status then raise exception 'smart_delivery_route_locked_after_loading'; end if;
    if v_source.status = 'planned' and old.status in ('planned', 'delivered', 'failed', 'cancelled') then
      return new;
    end if;
    if v_source.status = 'dispatched' and old.status in ('out_for_delivery', 'delivered', 'failed', 'cancelled') then
      return new;
    end if;
    raise exception 'smart_delivery_route_locked_after_loading';
  end if;

  if v_source.status <> 'planned' or old.status <> 'planned' then
    raise exception 'smart_delivery_route_locked_after_loading';
  end if;
  select * into v_target from public.ops_delivery_runs where id = new.run_id;
  if not found or v_target.status <> 'planned' then raise exception 'smart_delivery_target_route_locked'; end if;
  return new;
end;
$function$
;

-- function: smart_delivery_move_stop_v1(p_stop_id uuid, p_target_run_id uuid, p_actor_user_id uuid)
CREATE OR REPLACE FUNCTION public.smart_delivery_move_stop_v1(p_stop_id uuid, p_target_run_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_stop public.ops_delivery_stops%rowtype;
  v_source_run public.ops_delivery_runs%rowtype;
  v_target_run public.ops_delivery_runs%rowtype;
  v_next_sequence integer;
begin
  select * into v_stop
  from public.ops_delivery_stops
  where id = p_stop_id
  for update;

  if not found then
    raise exception 'Entrega não encontrada' using errcode = 'P0002';
  end if;

  if v_stop.run_id = p_target_run_id then
    return jsonb_build_object(
      'ok', true,
      'stop_id', p_stop_id,
      'source_run_id', v_stop.run_id,
      'target_run_id', p_target_run_id,
      'sequence', v_stop.sequence,
      'unchanged', true
    );
  end if;

  if v_stop.status <> 'planned' then
    raise exception 'Somente entregas ainda planejadas podem mudar de rota diretamente' using errcode = '22023';
  end if;

  select * into v_source_run
  from public.ops_delivery_runs
  where id = v_stop.run_id
  for update;

  if not found or v_source_run.status in ('completed', 'cancelled') then
    raise exception 'Rota de origem inválida para movimentação' using errcode = '22023';
  end if;

  select * into v_target_run
  from public.ops_delivery_runs
  where id = p_target_run_id
  for update;

  if not found then
    raise exception 'Rota de destino não encontrada' using errcode = 'P0002';
  end if;
  if v_target_run.status in ('completed', 'cancelled') then
    raise exception 'Rota de destino está encerrada' using errcode = '22023';
  end if;
  if v_target_run.service_date <> v_source_run.service_date then
    raise exception 'Mudança entre datas diferentes exige reagendamento explícito' using errcode = '22023';
  end if;

  select coalesce(max(sequence), 0) + 1 into v_next_sequence
  from public.ops_delivery_stops
  where run_id = p_target_run_id;

  if v_next_sequence > 100 then
    raise exception 'Rota de destino atingiu o limite de 100 paradas' using errcode = '22023';
  end if;

  update public.ops_delivery_stops
  set run_id = p_target_run_id,
      sequence = v_next_sequence,
      loaded_at = null,
      custody_confirmed_at = null,
      updated_at = now()
  where id = p_stop_id;

  update public.ops_delivery_runs
  set loaded_at = null,
      updated_at = now()
  where id = p_target_run_id;

  insert into public.admin_audit_logs(admin_user_id, action, entity_type, entity_id, details)
  values (
    p_actor_user_id,
    'smart_delivery.stop_moved',
    'delivery_stop',
    p_stop_id::text,
    jsonb_build_object(
      'source_run_id', v_source_run.id,
      'target_run_id', v_target_run.id,
      'old_sequence', v_stop.sequence,
      'new_sequence', v_next_sequence,
      'order_id', v_stop.order_id
    )
  );

  return jsonb_build_object(
    'ok', true,
    'stop_id', p_stop_id,
    'order_id', v_stop.order_id,
    'source_run_id', v_source_run.id,
    'target_run_id', v_target_run.id,
    'sequence', v_next_sequence,
    'unchanged', false
  );
end;
$function$
;

-- function: smart_delivery_plan_run_v1(p_vehicle_key text, p_order_ids uuid[], p_operator_label text, p_region_id uuid, p_driver_id uuid, p_vehicle_id uuid, p_actor_user_id uuid)
CREATE OR REPLACE FUNCTION public.smart_delivery_plan_run_v1(p_vehicle_key text, p_order_ids uuid[], p_operator_label text DEFAULT NULL::text, p_region_id uuid DEFAULT NULL::uuid, p_driver_id uuid DEFAULT NULL::uuid, p_vehicle_id uuid DEFAULT NULL::uuid, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_run_id uuid;
  v_assignment jsonb;
  v_order_ids uuid[] := '{}'::uuid[];
  v_region_id uuid := p_region_id;
  v_regions integer;
  v_route_key text := lower(trim(coalesce(p_vehicle_key, '')));
begin
  if v_route_key in ('car_1', 'car_2') then
    if p_driver_id is not null then
      raise exception 'legacy_route_key_cannot_be_bound_to_driver' using errcode = '22023';
    end if;
  else
    if p_driver_id is null or v_route_key <> 'driver_' || lower(p_driver_id::text) then
      raise exception 'invalid_driver_route_key' using errcode = '22023';
    end if;
  end if;

  v_run_id := public.ops_plan_delivery_run_v1(v_route_key, p_order_ids, p_operator_label);

  if v_region_id is null then
    select count(distinct o.delivery_region_id), min(o.delivery_region_id::text)::uuid
      into v_regions, v_region_id
    from public.ops_delivery_stops s
    join public.orders o on o.id = s.order_id
    where s.run_id = v_run_id and o.delivery_region_id is not null;
    if v_regions <> 1 then v_region_id := null; end if;
  end if;

  select coalesce(array_agg(s.order_id order by s.sequence), '{}'::uuid[])
    into v_order_ids
  from public.ops_delivery_stops s
  where s.run_id = v_run_id;

  v_assignment := public.smart_delivery_assign_run_v1(
    v_run_id, v_region_id, p_driver_id, p_vehicle_id, p_operator_label, p_actor_user_id
  );

  update public.ops_delivery_stops s
  set customer_address_id = o.delivery_customer_address_id,
      location_evidence_id = o.delivery_location_evidence_id,
      region_id = coalesce(o.delivery_region_id, v_region_id),
      destination_latitude = coalesce(e.latitude, a.latitude),
      destination_longitude = coalesce(e.longitude, a.longitude),
      destination_confidence = case
        when e.confidence = 'confirmed' then 'confirmed'
        when a.latitude is not null and a.longitude is not null then 'saved'
        else null
      end,
      updated_at = now()
  from public.orders o
  left join public.customer_addresses a on a.id = o.delivery_customer_address_id
  left join public.customer_location_evidence_v1 e on e.id = o.delivery_location_evidence_id
  where s.run_id = v_run_id and s.order_id = o.id;

  insert into public.admin_audit_logs(admin_user_id, action, entity_type, entity_id, details)
  values(p_actor_user_id, 'smart_delivery.run_planned', 'delivery_run', v_run_id::text,
    jsonb_build_object('vehicle_key', v_route_key, 'region_id', v_region_id, 'driver_id', p_driver_id,
      'vehicle_id', p_vehicle_id, 'order_ids', to_jsonb(v_order_ids),
      'order_count', coalesce(array_length(v_order_ids, 1), 0)));

  return jsonb_build_object('ok', true, 'run_id', v_run_id, 'vehicle_key', v_route_key,
    'region_id', v_region_id, 'driver_id', p_driver_id, 'vehicle_id', p_vehicle_id,
    'order_count', coalesce(array_length(v_order_ids, 1), 0), 'assignment', v_assignment);
end;
$function$
;

-- function: smart_delivery_prepare_optimization_v1(p_run_id uuid)
CREATE OR REPLACE FUNCTION public.smart_delivery_prepare_optimization_v1(p_run_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_run public.ops_delivery_runs%rowtype;
  v_stops jsonb;
  v_fingerprint text;
begin
  select * into v_run from public.ops_delivery_runs where id=p_run_id for update;
  if not found then raise exception 'Rota não encontrada' using errcode='P0002'; end if;
  if v_run.status <> 'planned' then raise exception 'Somente rota planejada pode ser otimizada' using errcode='22023'; end if;

  if exists (
    select 1 from public.ops_delivery_stops
    where run_id=p_run_id and status <> 'planned'
  ) then raise exception 'Rota já possui parada em execução' using errcode='22023'; end if;

  if exists (
    select 1 from public.ops_delivery_stops
    where run_id=p_run_id and (destination_latitude is null or destination_longitude is null)
  ) then raise exception 'Todas as entregas precisam de localização antes da otimização' using errcode='22023'; end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',s.id::text,'order_id',s.order_id::text,'sequence',s.sequence,
    'lat',s.destination_latitude,'lng',s.destination_longitude
  ) order by s.sequence),'[]'::jsonb)
  into v_stops
  from public.ops_delivery_stops s where s.run_id=p_run_id;

  if jsonb_array_length(v_stops)=0 then raise exception 'Rota sem entregas' using errcode='22023'; end if;
  if jsonb_array_length(v_stops)>100 then raise exception 'Rota excede 100 entregas' using errcode='22023'; end if;

  v_fingerprint := md5(v_stops::text || '|' || v_run.updated_at::text);

  return jsonb_build_object(
    'ok',true,'run_id',v_run.id,'service_date',v_run.service_date,
    'vehicle_key',v_run.vehicle_key,'fingerprint',v_fingerprint,'stops',v_stops
  );
end;
$function$
;

-- function: smart_delivery_region_save_v1(p_id uuid, p_code text, p_name text, p_city text, p_state text, p_priority integer, p_is_active boolean, p_notes text, p_polygon_geojson jsonb, p_actor_user_id uuid)
CREATE OR REPLACE FUNCTION public.smart_delivery_region_save_v1(p_id uuid, p_code text, p_name text, p_city text DEFAULT NULL::text, p_state text DEFAULT 'MT'::text, p_priority integer DEFAULT 100, p_is_active boolean DEFAULT true, p_notes text DEFAULT NULL::text, p_polygon_geojson jsonb DEFAULT NULL::jsonb, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_id uuid := coalesce(p_id, gen_random_uuid());
  v_code text := lower(regexp_replace(btrim(coalesce(p_code,'')), '[^a-zA-Z0-9_-]+', '-', 'g'));
  v_name text := btrim(coalesce(p_name,''));
begin
  if v_code = '' or length(v_code) > 60 then raise exception 'Código da região inválido' using errcode='22023'; end if;
  if v_name = '' or length(v_name) > 120 then raise exception 'Nome da região inválido' using errcode='22023'; end if;
  if coalesce(p_priority,100) < 0 or coalesce(p_priority,100) > 10000 then raise exception 'Prioridade inválida' using errcode='22023'; end if;

  insert into public.delivery_regions_v1(id,code,name,city,state,is_active,priority,polygon_geojson,notes,created_at,updated_at)
  values(v_id,v_code,v_name,nullif(btrim(coalesce(p_city,'')),''),coalesce(nullif(upper(btrim(coalesce(p_state,''))),''),'MT'),
         coalesce(p_is_active,true),coalesce(p_priority,100),p_polygon_geojson,nullif(btrim(coalesce(p_notes,'')),''),now(),now())
  on conflict(id) do update set
    code=excluded.code,name=excluded.name,city=excluded.city,state=excluded.state,is_active=excluded.is_active,
    priority=excluded.priority,polygon_geojson=excluded.polygon_geojson,notes=excluded.notes,updated_at=now();

  insert into public.admin_audit_logs(admin_user_id,action,entity_type,entity_id,details)
  values(p_actor_user_id,'smart_delivery.region_saved','delivery_region',v_id::text,
    jsonb_build_object('code',v_code,'name',v_name,'active',coalesce(p_is_active,true)));
  return v_id;
end;
$function$
;

-- function: smart_delivery_reorder_stops_v1(p_run_id uuid, p_stop_ids uuid[], p_actor_label text)
CREATE OR REPLACE FUNCTION public.smart_delivery_reorder_stops_v1(p_run_id uuid, p_stop_ids uuid[], p_actor_label text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_run public.ops_delivery_runs%rowtype;
  v_active_status text;
  v_count integer;
  v_unique integer;
  v_changed integer;
  v_terminal_count integer;
begin
  select * into v_run from public.ops_delivery_runs where id = p_run_id for update;
  if not found then raise exception 'run_not_found'; end if;
  if v_run.status not in ('planned', 'dispatched') then raise exception 'route_locked'; end if;
  v_active_status := case when v_run.status = 'dispatched' then 'out_for_delivery' else 'planned' end;

  select count(*) into v_count
    from public.ops_delivery_stops
   where run_id = p_run_id and status = v_active_status;
  select count(distinct x) into v_unique from unnest(coalesce(p_stop_ids, '{}'::uuid[])) x;
  if v_count < 1 or coalesce(array_length(p_stop_ids, 1), 0) <> v_count or v_unique <> v_count then
    raise exception 'invalid_route_order';
  end if;
  if exists (
    select 1 from unnest(p_stop_ids) x
    left join public.ops_delivery_stops s on s.id = x and s.run_id = p_run_id and s.status = v_active_status
    where s.id is null
  ) then raise exception 'invalid_route_order'; end if;

  set constraints all deferred;
  with ordered as (
    select stop_id, ordinality::integer as sequence
      from unnest(p_stop_ids) with ordinality as x(stop_id, ordinality)
  )
  update public.ops_delivery_stops s
     set sequence = ordered.sequence, updated_at = now()
    from ordered
   where s.id = ordered.stop_id and s.run_id = p_run_id;
  get diagnostics v_changed = row_count;
  if v_changed <> v_count then raise exception 'invalid_route_order'; end if;

  select count(*) into v_terminal_count
    from public.ops_delivery_stops
   where run_id = p_run_id and status in ('delivered', 'failed', 'cancelled');
  with terminal as (
    select id, v_count + row_number() over (order by sequence, id)::integer as sequence
      from public.ops_delivery_stops
     where run_id = p_run_id and status in ('delivered', 'failed', 'cancelled')
  )
  update public.ops_delivery_stops s
     set sequence = terminal.sequence, updated_at = now()
    from terminal
   where s.id = terminal.id;

  update public.ops_delivery_runs
     set optimizer_provider = null, optimizer_job_ref = null, optimizer_payload = null, updated_at = now()
   where id = p_run_id;

  insert into public.admin_audit_logs(admin_user_id, action, entity_type, entity_id, details)
  values(null, 'smart_delivery.route_reordered', 'delivery_run', p_run_id::text,
    jsonb_build_object('actor', left(nullif(trim(coalesce(p_actor_label, '')), ''), 80), 'stop_ids', to_jsonb(p_stop_ids)));

  return jsonb_build_object('ok', true, 'run_id', p_run_id, 'stop_ids', to_jsonb(p_stop_ids),
    'terminal_stops', v_terminal_count);
end;
$function$
;

-- function: smart_delivery_vehicle_save_v1(p_id uuid, p_label text, p_plate text, p_vehicle_type text, p_capacity_units integer, p_is_active boolean, p_metadata jsonb, p_actor_user_id uuid)
CREATE OR REPLACE FUNCTION public.smart_delivery_vehicle_save_v1(p_id uuid, p_label text, p_plate text DEFAULT NULL::text, p_vehicle_type text DEFAULT NULL::text, p_capacity_units integer DEFAULT NULL::integer, p_is_active boolean DEFAULT true, p_metadata jsonb DEFAULT '{}'::jsonb, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_id uuid := coalesce(p_id, gen_random_uuid());
  v_label text := btrim(coalesce(p_label,''));
  v_plate text := nullif(upper(regexp_replace(coalesce(p_plate,''), '[^A-Za-z0-9]', '', 'g')),'');
begin
  if v_label = '' or length(v_label) > 120 then raise exception 'Nome do veículo inválido' using errcode='22023'; end if;
  if p_capacity_units is not null and (p_capacity_units < 1 or p_capacity_units > 10000) then raise exception 'Capacidade inválida' using errcode='22023'; end if;

  insert into public.delivery_vehicles_v1(id,label,plate,vehicle_type,capacity_units,is_active,metadata,created_at,updated_at)
  values(v_id,v_label,v_plate,nullif(btrim(coalesce(p_vehicle_type,'')),''),p_capacity_units,coalesce(p_is_active,true),coalesce(p_metadata,'{}'::jsonb),now(),now())
  on conflict(id) do update set
    label=excluded.label,plate=excluded.plate,vehicle_type=excluded.vehicle_type,
    capacity_units=excluded.capacity_units,is_active=excluded.is_active,metadata=excluded.metadata,updated_at=now();

  insert into public.admin_audit_logs(admin_user_id,action,entity_type,entity_id,details)
  values(p_actor_user_id,'smart_delivery.vehicle_saved','delivery_vehicle',v_id::text,
    jsonb_build_object('label',v_label,'plate',v_plate,'active',coalesce(p_is_active,true)));
  return v_id;
end;
$function$
;

-- function: start_basket_cart(p_conversation_id uuid, p_basket_id uuid)
CREATE OR REPLACE FUNCTION public.start_basket_cart(p_conversation_id uuid, p_basket_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_customer_id uuid; v_price numeric; v_cart_id uuid; v_result jsonb;
begin
  select customer_id into v_customer_id from public.conversations where id=p_conversation_id and status<>'closed'; if not found then raise exception 'conversation_not_found'; end if;
  select base_price into v_price from public.basket_templates where id=p_basket_id and is_active=true and is_whatsapp_active=true; if not found then raise exception 'basket_not_available'; end if;
  if coalesce(v_price,0)<=0 then raise exception 'basket_price_not_configured'; end if;
  if not exists(select 1 from public.basket_template_items where basket_id=p_basket_id) then raise exception 'basket_composition_empty'; end if;
  if exists(select 1 from public.basket_template_items bi left join public.products p on p.id=bi.product_id where bi.basket_id=p_basket_id and p.id is null) then raise exception 'basket_component_missing'; end if;
  update public.carts set status='cancelled',updated_at=now() where conversation_id=p_conversation_id and status='draft';
  insert into public.carts(conversation_id,customer_id,basket_id,status,base_commercial_price,total,expires_at) values(p_conversation_id,v_customer_id,p_basket_id,'draft',v_price,v_price,now()+interval '24 hours') returning id into v_cart_id;
  insert into public.cart_items(cart_id,product_id,source,quantity,base_quantity,unit_price,line_total,commercial_delta,metadata)
  select v_cart_id,bi.product_id,'basket',bi.quantity,bi.quantity,coalesce(p.price,0),bi.quantity*coalesce(p.price,0),0,jsonb_build_object('basket_template_item_id',bi.id,'remove_unit_delta',bi.remove_unit_delta,'add_unit_delta',bi.add_unit_delta,'removable',bi.removable,'quantity_editable',bi.quantity_editable,'min_quantity',bi.min_quantity,'max_quantity',bi.max_quantity,'substitution_group',bi.substitution_group,'basket_component_official',true) from public.basket_template_items bi join public.products p on p.id=bi.product_id where bi.basket_id=p_basket_id order by bi.sort_order,bi.created_at;
  v_result:=public.recalculate_cart(v_cart_id); update public.conversations set stage='customizing',updated_at=now() where id=p_conversation_id; return v_result||jsonb_build_object('basket_id',p_basket_id,'composition_source','supabase');
end;$function$
;

-- function: storefront_order_unit_price_v1(p_price numeric, p_offer_price numeric, p_is_offer boolean, p_metadata jsonb, p_at timestamp with time zone)
CREATE OR REPLACE FUNCTION public.storefront_order_unit_price_v1(p_price numeric, p_offer_price numeric, p_is_offer boolean, p_metadata jsonb, p_at timestamp with time zone)
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select case
    when p_is_offer is true and p_offer_price>=0 and p_offer_price<p_price
      and case when p_metadata->>'offer_source'='auto_rotation' then
        case when pg_input_is_valid(p_metadata->>'offer_starts_at','timestamp with time zone')
                  and pg_input_is_valid(p_metadata->>'offer_ends_at','timestamp with time zone')
             then isfinite((p_metadata->>'offer_starts_at')::timestamptz)
               and isfinite((p_metadata->>'offer_ends_at')::timestamptz)
               and (p_metadata->>'offer_starts_at')::timestamptz<=p_at
               and (p_metadata->>'offer_ends_at')::timestamptz>p_at
             else false end
        else true end
    then p_offer_price
    else p_price
  end;
$function$
;

-- function: supabase_stock_pending_reservations_v1(p_product_id uuid, p_exclude_order_id uuid)
CREATE OR REPLACE FUNCTION public.supabase_stock_pending_reservations_v1(p_product_id uuid, p_exclude_order_id uuid DEFAULT NULL::uuid)
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(sum(r.quantity),0)::numeric
  from public.vitrine_stock_reservations r
  join public.orders o on o.id=r.order_id
  cross join public.bling_hub_runtime_v2 rt
  left join public.order_separation_completions_v1 c on c.order_id=r.order_id
  where r.product_id=p_product_id
    and (p_exclude_order_id is null or r.order_id<>p_exclude_order_id)
    and o.status not in ('cancelled','delivered','returned')
    and (
      (r.status in ('reserved','allocated') and (r.expires_at is null or r.expires_at>now()))
      or (
        r.status='consumed'
        and coalesce(r.consumed_at,r.updated_at,r.created_at)
          < nullif(rt.metadata->>'ops2_supabase_stock_authority_at','')::timestamptz
        and coalesce((c.metadata->>'stock_applied')::boolean,false)=false
      )
    );
$function$
;

-- function: sync_site_basket_type_after_product_unavailable_v1()
CREATE OR REPLACE FUNCTION public.sync_site_basket_type_after_product_unavailable_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_type_id uuid;
  v_removed_order integer;
  v_remaining_count integer;
BEGIN
  IF OLD.stock IS NOT DISTINCT FROM NEW.stock
    AND OLD.is_active IS NOT DISTINCT FROM NEW.is_active THEN
    RETURN NEW;
  END IF;
  IF NEW.is_active IS TRUE AND coalesce(NEW.stock, 0) > 0 THEN
    RETURN NEW;
  END IF;

  FOR v_type_id IN
    SELECT DISTINCT option.product_type_id
    FROM public.site_basket_product_type_options option
    JOIN public.site_basket_product_type_quantities quantity
      ON quantity.product_type_id = option.product_type_id
    JOIN public.basket_templates basket
      ON basket.id = quantity.basket_id
     AND basket.is_active = true
    WHERE option.product_id = NEW.id
      AND quantity.quantity > 0
  LOOP
    SELECT option.sort_order INTO v_removed_order
    FROM public.site_basket_product_type_options option
    WHERE option.product_type_id = v_type_id
      AND option.product_id = NEW.id;

    SELECT count(*) INTO v_remaining_count
    FROM public.site_basket_product_type_options option
    WHERE option.product_type_id = v_type_id
      AND option.product_id <> NEW.id;

    IF v_remaining_count > 0 THEN
      DELETE FROM public.site_basket_product_type_options
      WHERE product_type_id = v_type_id
        AND product_id = NEW.id;

      WITH ordered AS (
        SELECT
          option.product_id,
          row_number() OVER (
            ORDER BY CASE WHEN option.sort_order > v_removed_order THEN 0 ELSE 1 END,
                     option.sort_order,
                     option.product_id
          ) - 1 AS next_order
        FROM public.site_basket_product_type_options option
        WHERE option.product_type_id = v_type_id
      )
      UPDATE public.site_basket_product_type_options option
      SET sort_order = ordered.next_order,
          metadata = (coalesce(option.metadata, '{}'::jsonb) - 'preferred')
            || jsonb_build_object('preferred', ordered.next_order = 0),
          updated_at = now()
      FROM ordered
      WHERE option.product_type_id = v_type_id
        AND option.product_id = ordered.product_id;
    END IF;
  END LOOP;
  RETURN NEW;
END;
$function$
;

-- function: sync_vitrine_order_fiscal_delivery_v1(p_order_id uuid)
CREATE OR REPLACE FUNCTION public.sync_vitrine_order_fiscal_delivery_v1(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  o public.orders%rowtype;
begin
  select * into o
  from public.orders
  where id=p_order_id
  for update;

  if not found then
    return jsonb_build_object('ok',false,'error','order_not_found','external_side_effect',false);
  end if;

  insert into public.order_fiscal_controls(order_id,delivery_status,delivery_confirmed_at)
  values(
    o.id,
    case
      when o.status='delivered' then 'delivered'
      when o.status='cancelled' then 'cancelled'
      when o.status='returned' then 'returned'
      else 'pending'
    end,
    case when o.status='delivered' then coalesce(o.delivered_at,now()) else null end
  )
  on conflict(order_id) do nothing;

  update public.order_fiscal_controls
  set delivery_status=case
        when o.status='delivered' then 'delivered'
        when o.status='cancelled' then 'cancelled'
        when o.status='returned' then 'returned'
        else delivery_status
      end,
      delivery_confirmed_at=case
        when o.status='delivered' then coalesce(delivery_confirmed_at,o.delivered_at,now())
        else delivery_confirmed_at
      end,
      updated_at=now()
  where order_id=o.id;

  return public.refresh_order_fiscal_readiness_v1(o.id);
end
$function$
;

-- function: sync_vitrine_order_stock_reservation_v1()
CREATE OR REPLACE FUNCTION public.sync_vitrine_order_stock_reservation_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_result jsonb;
  v_error text;
begin
  if new.source='vitrine' and (tg_op='INSERT' or old.status is distinct from new.status) then
    if new.status='ready' and exists (
      select 1 from public.order_separation_completions_v1 c
      where c.order_id=new.id and coalesce((c.metadata->>'stock_applied')::boolean,false)=true
    ) then
      return new;
    end if;
    if new.status in ('processing','ready','out_for_delivery','delivered') then
      v_result:=public.consume_vitrine_order_stock_v1(new.id);
      if coalesce((v_result->>'ok')::boolean,false) is not true then
        v_error:=coalesce(nullif(v_result->>'error',''),'unknown');
        raise exception 'order_stock_consume_failed:%',v_error using errcode='P0001';
      end if;
    elsif new.status in ('cancelled','returned') then
      perform public.release_vitrine_order_stock_v1(new.id);
    end if;
  end if;
  return new;
end;
$function$
;

-- function: trg_refresh_basket_hidden_adjustment_on_price_v1()
CREATE OR REPLACE FUNCTION public.trg_refresh_basket_hidden_adjustment_on_price_v1()
